private struct QuipslyClearingCard: ViewModifier {
    let radius: CGFloat
    let stroke: Color
    let shadow: CGFloat

    func body(content: Content) -> some View {
        content
            .background(
                RoundedRectangle(cornerRadius: radius, style: .continuous)
                    .fill(QuipslyStudioTheme.meadowGlassGradient)
                    .overlay(
                        RoundedRectangle(cornerRadius: radius, style: .continuous)
                            .stroke(stroke, lineWidth: 1)
                    )
                    .overlay(alignment: .topLeading) {
                        RoundedRectangle(cornerRadius: radius, style: .continuous)
                            .stroke(QuipslyStudioTheme.moonMilk.opacity(0.065), lineWidth: 1)
                            .blur(radius: 0.5)
                    }
            )
            .shadow(color: QuipslyStudioTheme.softShadow, radius: shadow, y: shadow * 0.35)
    }
}

private extension View {
    func quipslyClearingCard(
        radius: CGFloat = 24,
        stroke: Color = QuipslyStudioTheme.warmGlassStroke,
        shadow: CGFloat = 14
    ) -> some View {
        modifier(QuipslyClearingCard(radius: radius, stroke: stroke, shadow: shadow))
    }
}

struct QuipslySectionHeader: View {
    let eyebrow: String
    let title: String
    let detail: String
    var systemImage: String = "leaf.fill"
    var tint: Color = QuipslyStudioTheme.moss
    var compact: Bool = false

    var body: some View {
        HStack(alignment: .top, spacing: 10) {
            Image(systemName: systemImage)
                .font(compact ? .caption : .subheadline)
                .fontWeight(.black)
                .foregroundStyle(tint)
                .frame(width: compact ? 24 : 30, height: compact ? 24 : 30)
                .background(tint.opacity(0.12))
                .clipShape(RoundedRectangle(cornerRadius: compact ? 8 : 10, style: .continuous))

            VStack(alignment: .leading, spacing: compact ? 2 : 4) {
                Text(eyebrow.uppercased())
                    .font(.caption2)
                    .fontWeight(.black)
                    .tracking(1.7)
                    .foregroundStyle(QuipslyStudioTheme.sunbeam.opacity(0.88))
                Text(title)
                    .font(compact ? .subheadline : .title3)
                    .fontWeight(.black)
                    .foregroundStyle(.primary)
                    .lineLimit(2)
                    .fixedSize(horizontal: false, vertical: true)
                if !detail.isEmpty {
                    Text(detail)
                        .font(.caption)
                        .foregroundStyle(.secondary)
                        .fixedSize(horizontal: false, vertical: true)
                }
            }
        }
    }
}

