private struct ProxyJobSnapshot: Equatable {
    var status: String = "idle"
    var phase: String = "no active proxy job"
    var sessionName: String = ""
    var sequenceTitle: String = ""
    var currentLane: String = ""
    var currentKind: String = ""
    var currentSource: String = ""
    var currentProxy: String = ""
    var currentProxyBytes: Int = 0
    var currentPartialBytes: Int = 0
    var processedCount: Int = 0
    var skippedCount: Int = 0
    var failedCount: Int = 0
    var elapsedSeconds: Double = 0
    var startedAt: String = ""
    var updatedAt: String = ""
    var lastFailure: String = ""
    var sourcePolicy: String = ""
    var statePath: String = ""

    var hasJobFile: Bool { !statePath.isEmpty }
    var isRunning: Bool { status == "running" }
    var hasAttention: Bool { failedCount > 0 || status == "failed" }

    var currentBytesLabel: String {
        let bytes = currentPartialBytes > 0 ? currentPartialBytes : currentProxyBytes
        guard bytes > 0 else { return "waiting for bytes" }
        return ByteCountFormatter.string(fromByteCount: Int64(bytes), countStyle: .file)
    }

    var statusTitle: String {
        if !hasJobFile { return "No proxy job heartbeat yet" }
        if isRunning { return "Proxy job running" }
        if hasAttention { return "Proxy job needs review" }
        if status == "completed" { return "Proxy job completed" }
        return "Proxy job idle"
    }

    static let idle = ProxyJobSnapshot()
}

private struct AgentProofReceipt: Identifiable {
    let id: String
    let path: String
    let folderPath: String
    let createdLabel: String
    let status: String
    let sessionName: String
    let activeSessionName: String
    let playbackFormat: String
    let selectedLaneName: String
    let selectedTagType: String
    let sharedPlayheadStatus: String
    let lastMediaAction: String
    let beforePlayhead: Double
    let afterPlayhead: Double
    let timelinePixelsPerSecond: Double
    let beforePath: String
    let afterPath: String
    let commandsPath: String

    var passed: Bool { status.lowercased() == "passed" }
    var shortSessionName: String { sessionName.isEmpty ? activeSessionName : sessionName }

    static var defaultFolderURL: URL {
        if let configured = ProcessInfo.processInfo.environment["QUIPSLY_AGENT_OBSERVATIONS_DIR"],
           configured.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty == false {
            return URL(fileURLWithPath: configured)
        }
        return FileManager.default.homeDirectoryForCurrentUser
            .appendingPathComponent("Dev/high-ground-studio/apps/QuipslyStudio/.quipsly/agent-observations")
    }

    static func recent(limit: Int = 8) -> [AgentProofReceipt] {
        let folder = defaultFolderURL
        guard let urls = try? FileManager.default.contentsOfDirectory(
            at: folder,
            includingPropertiesForKeys: [.contentModificationDateKey],
            options: [.skipsHiddenFiles]
        ) else {
            return []
        }

        return urls
            .filter { url in
                let name = url.lastPathComponent
                return name.hasPrefix("agent-driver-proof-") && name.hasSuffix("-summary.json")
            }
            .sorted { lhs, rhs in
                let leftDate = ((try? lhs.resourceValues(forKeys: [.contentModificationDateKey]))?.contentModificationDate) ?? .distantPast
                let rightDate = ((try? rhs.resourceValues(forKeys: [.contentModificationDateKey]))?.contentModificationDate) ?? .distantPast
                return leftDate > rightDate
            }
            .prefix(limit)
            .compactMap { receipt(from: $0, folder: folder) }
    }

    private static func receipt(from url: URL, folder: URL) -> AgentProofReceipt? {
        guard
            let data = try? Data(contentsOf: url),
            let object = try? JSONSerialization.jsonObject(with: data),
            let json = object as? [String: Any]
        else {
            return nil
        }

        let paths = json["receiptPaths"] as? [String: Any] ?? [:]
        return AgentProofReceipt(
            id: url.path,
            path: url.path,
            folderPath: folder.path,
            createdLabel: createdLabel(from: url.lastPathComponent),
            status: string(json["status"]),
            sessionName: string(json["sessionName"]),
            activeSessionName: string(json["activeSessionName"]),
            playbackFormat: string(json["playbackFormat"]),
            selectedLaneName: string(json["selectedLaneName"]),
            selectedTagType: string(json["selectedTagType"]),
            sharedPlayheadStatus: string(json["sharedPlayheadStatus"]),
            lastMediaAction: string(json["lastMediaAction"]),
            beforePlayhead: double(json["beforePlayhead"]),
            afterPlayhead: double(json["afterPlayhead"]),
            timelinePixelsPerSecond: double(json["timelinePixelsPerSecond"]),
            beforePath: string(paths["before"]),
            afterPath: string(paths["after"]),
            commandsPath: string(paths["commands"])
        )
    }

    private static func string(_ value: Any?) -> String {
        if let value = value as? String { return value }
        if let value { return "\(value)" }
        return ""
    }

    private static func double(_ value: Any?) -> Double {
        if let value = value as? Double { return value }
        if let value = value as? Int { return Double(value) }
        if let value = value as? String { return Double(value) ?? 0 }
        return 0
    }

    private static func createdLabel(from filename: String) -> String {
        filename
            .replacingOccurrences(of: "agent-driver-proof-", with: "")
            .replacingOccurrences(of: "-summary.json", with: "")
    }
}

