                        selectedLane: selectedProgramCropLane(),
                        programCropEditMode: $programCropEditMode,
                        programCrop: selectedProgramCropAdjustment(),
                        programCropAtPlayhead: selectedProgramCropAtPlayheadAdjustment(),
                        programCropKeyframeCount: selectedProgramCropKeyframeCount(),
                        updateKeyframe: updateKeyframe,
                        updateProgramCrop: { crop in
                            applyProgramCropAdjustment(
                                laneId: selectedLaneId?.uuidString,
                                format: playbackEngine.playbackFormat.rawValue,
                                panX: crop.panX,
                                panY: crop.panY,
                                zoom: crop.zoom,
                                panXDelta: nil,
                                panYDelta: nil,
                                zoomDelta: nil
                            )
                        },
                        updateProgramCropKeyframe: { crop in
                            applyProgramCropKeyframe(
                                laneId: selectedLaneId?.uuidString,
                                format: playbackEngine.playbackFormat.rawValue,
                                time: playbackEngine.playhead,
                                panX: crop.panX,
                                panY: crop.panY,
                                zoom: crop.zoom,
                                panXDelta: nil,
                                panYDelta: nil,
                                zoomDelta: nil
                            )
                        },
                        addProgramCropKeyframe: {
                            applyProgramCropKeyframe(
                                laneId: selectedLaneId?.uuidString,
                                format: playbackEngine.playbackFormat.rawValue,
                                time: playbackEngine.playhead,
                                panX: selectedProgramCropAtPlayheadAdjustment().panX,
                                panY: selectedProgramCropAtPlayheadAdjustment().panY,
                                zoom: selectedProgramCropAtPlayheadAdjustment().zoom,
                                panXDelta: nil,
                                panYDelta: nil,
                                zoomDelta: nil
                            )
                        },
                        clearProgramCropKeyframes: {
                            clearProgramCropKeyframes(
                                laneId: selectedLaneId?.uuidString,
                                format: playbackEngine.playbackFormat.rawValue
                            )
                        },
                        rebuildPlayer: { rebuildPlayer() }
                    )
                    .tabItem { Label("Frame", systemImage: "slider.horizontal.3") }

                    shortsWorkbenchSidebar
                        .tabItem { Label("Shorts", systemImage: "rectangle.portrait.on.rectangle.portrait.angled") }

                    transcriptWorkbenchSidebar
                        .tabItem { Label("Script", systemImage: "text.quote") }

                    agentReceiptWorkbenchSidebar
                        .tabItem { Label("Agent", systemImage: "sparkles.rectangle.stack.fill") }

                    RightSidebarView(
                        playbackEngine: playbackEngine,
                        projectStore: projectStore,
                        selectedLaneId: selectedLaneId,
                        onDropVideo: { url in
                        _ = url.startAccessingSecurityScopedResource()
                        loadVideoIntoProject(url: url, allowProtectedOriginalProbe: true)
                        },
                        onSelectLane: selectSourceLane,
                        onRelinkLane: beginRelinkLane,
                        onAttachProxy: beginAttachProxy,
                        onShowLaneWindow: showSourceLaneWindow,
                        onCutLaneWindow: cutSourceLaneWindow,
                        sourceStopCount: sourceReviewBoundaryCount,
                        onSourceStopNavigate: { laneId, direction in
                            jumpToAdjacentSourceDecision(direction: direction, laneId: laneId)
                        }
                    )
                        .tabItem { Label("Media", systemImage: "photo.on.rectangle.angled") }
                }
            } else {
                HStack(spacing: 0) {
                    #if os(macOS)
                    let showWorkbench = true
                    #else
                    let showWorkbench = isInspectorVisible
                    #endif

                    if showWorkbench {
                        VStack(spacing: 0) {
                            workbenchHeader
                            workbenchModeDeck

                            switch leftWorkbenchMode {
                            case .nest:
                                nestWorkbenchSidebar
                            case .inspector:
                                InspectorSidebarView(
                                    playbackEngine: playbackEngine,
                                    projectStore: projectStore,
                                    yaw: $yaw,
                                    pitch: $pitch,
                                    roll: $roll,
                                    fov: $fov,
                                    interpolation: $interpolation,
                                    selectedLane: selectedProgramCropLane(),
                                    programCropEditMode: $programCropEditMode,
                                    programCrop: selectedProgramCropAdjustment(),
                                    programCropAtPlayhead: selectedProgramCropAtPlayheadAdjustment(),
                                    programCropKeyframeCount: selectedProgramCropKeyframeCount(),
                                    updateKeyframe: updateKeyframe,
                                    updateProgramCrop: { crop in
                                        applyProgramCropAdjustment(
                                            laneId: selectedLaneId?.uuidString,
                                            format: playbackEngine.playbackFormat.rawValue,
                                            panX: crop.panX,
                                            panY: crop.panY,
                                            zoom: crop.zoom,
                                            panXDelta: nil,
                                            panYDelta: nil,
                                            zoomDelta: nil
                                        )
                                    },
                                    updateProgramCropKeyframe: { crop in
                                        applyProgramCropKeyframe(
                                            laneId: selectedLaneId?.uuidString,
                                            format: playbackEngine.playbackFormat.rawValue,
                                            time: playbackEngine.playhead,
                                            panX: crop.panX,
                                            panY: crop.panY,
                                            zoom: crop.zoom,
                                            panXDelta: nil,
                                            panYDelta: nil,
                                            zoomDelta: nil
                                        )
                                    },
                                    addProgramCropKeyframe: {
                                        applyProgramCropKeyframe(
                                            laneId: selectedLaneId?.uuidString,
                                            format: playbackEngine.playbackFormat.rawValue,
                                            time: playbackEngine.playhead,
                                            panX: selectedProgramCropAtPlayheadAdjustment().panX,
                                            panY: selectedProgramCropAtPlayheadAdjustment().panY,
                                            zoom: selectedProgramCropAtPlayheadAdjustment().zoom,
                                            panXDelta: nil,
                                            panYDelta: nil,
                                            zoomDelta: nil
                                        )
                                    },
                                    clearProgramCropKeyframes: {
                                        clearProgramCropKeyframes(
                                            laneId: selectedLaneId?.uuidString,
                                            format: playbackEngine.playbackFormat.rawValue
                                        )
                                    },
                                    rebuildPlayer: { rebuildPlayer() }
                                )
                            case .shorts:
                                shortsWorkbenchSidebar
                            case .transcript:
                                transcriptWorkbenchSidebar
                            case .publish:
                                publishWorkbenchSidebar
                            case .agent:
                                agentReceiptWorkbenchSidebar
                            }
                        }
                        .background(QuipslyStudioTheme.toolBayGradient)
                        .frame(minWidth: 318, idealWidth: 348, maxWidth: 372)
                    } else {
                        inspectorRail
                    }

                    Divider()

                    mainWorkspace

                    Divider()

                    RightSidebarView(
                        playbackEngine: playbackEngine,
                        projectStore: projectStore,
                        selectedLaneId: selectedLaneId,
                        onDropVideo: { url in
                        _ = url.startAccessingSecurityScopedResource()
                        loadVideoIntoProject(url: url, allowProtectedOriginalProbe: true)
                        },
                        onSelectLane: selectSourceLane,
                        onRelinkLane: beginRelinkLane,
                        onAttachProxy: beginAttachProxy,
                        onShowLaneWindow: showSourceLaneWindow,
                        onCutLaneWindow: cutSourceLaneWindow,
                        sourceStopCount: sourceReviewBoundaryCount,
                        onSourceStopNavigate: { laneId, direction in
                            jumpToAdjacentSourceDecision(direction: direction, laneId: laneId)
                        }
                    )
                    .frame(minWidth: 330, idealWidth: 360, maxWidth: 388)
                }
            }
        }
        .fileImporter(
            isPresented: $isShowingFileImporter,
            allowedContentTypes: [UTType.movie, UTType.video, UTType.audio],
            allowsMultipleSelection: true
        ) { result in
            switch result {
            case .success(let urls):
                for url in urls {
                    // Start accessing security-scoped resource on macOS/iOS
                    _ = url.startAccessingSecurityScopedResource()
                    loadVideoIntoProject(url: url, allowProtectedOriginalProbe: true)
                    // We technically shouldn't stop accessing immediately for AVPlayer, but this is an MVP
                }
            case .failure(let error):
                errorMessage = error.localizedDescription
                showErrorAlert = true
            }
        }
        .fileImporter(
            isPresented: $isShowingRelinkImporter,
            allowedContentTypes: [UTType.movie, UTType.video, UTType.audio],
            allowsMultipleSelection: false
        ) { result in
            defer { relinkingLaneId = nil }
            switch result {
            case .success(let urls):
                guard let url = urls.first, let laneId = relinkingLaneId else { return }
                _ = url.startAccessingSecurityScopedResource()
                relinkLaneMedia(laneId: laneId.uuidString, sourceURL: url)
            case .failure(let error):
                errorMessage = error.localizedDescription
                showErrorAlert = true
            }
        }
        .fileImporter(
            isPresented: $isShowingAttachProxyImporter,
            allowedContentTypes: [UTType.audio, UTType.movie, UTType.video],
            allowsMultipleSelection: false
        ) { result in
            defer { proxyAttachingLaneId = nil }
            switch result {
            case .success(let urls):
                guard let url = urls.first, let laneId = proxyAttachingLaneId else { return }
                _ = url.startAccessingSecurityScopedResource()
                attachProxyToLane(laneId: laneId.uuidString, proxyURL: url)
            case .failure(let error):
                errorMessage = error.localizedDescription
                showErrorAlert = true
            }
        }
        #if os(macOS)
        .fileImporter(
            isPresented: $isShowingExternalMediaAccessImporter,
            allowedContentTypes: [UTType.folder],
            allowsMultipleSelection: false
        ) { result in
            switch result {
            case .success(let urls):
                guard let url = urls.first else { return }
                externalMediaAccess.grantAccess(to: url)
                lastMediaAction = "External media access granted for \(url.lastPathComponent)"
                updateAgentState()
            case .failure(let error):
                errorMessage = error.localizedDescription
                showErrorAlert = true
            }
        }
        #endif
        .alert(isPresented: $showErrorAlert) {
            Alert(title: Text("Error"), message: Text(errorMessage ?? "Unknown error"), dismissButton: .default(Text("OK")))
        }
    }

    private var inspectorRail: some View {
        VStack(spacing: 12) {
            ForEach(LeftWorkbenchMode.allCases) { mode in
                Button {
                    withAnimation(.easeInOut(duration: 0.16)) {
                        leftWorkbenchMode = mode
                        isInspectorVisible = true
                    }
                } label: {
                    Image(systemName: mode.icon)
                        .font(.headline)
                        .frame(width: 32, height: 32)
                        .foregroundStyle(mode.tint)
                        .background(mode.tint.opacity(0.13))
                        .overlay(
                            RoundedRectangle(cornerRadius: 10, style: .continuous)
                                .stroke(mode.tint.opacity(0.18), lineWidth: 1)
                        )
                        .clipShape(RoundedRectangle(cornerRadius: 10, style: .continuous))
                }
                .buttonStyle(.plain)
                .help("Open \(mode.title): \(mode.helperText)")
                .accessibilityIdentifier("quipsly.workbench.rail.\(mode.rawValue)")
            }

            Text("Workbench")
                .font(.caption2)
                .fontWeight(.black)
                .foregroundStyle(QuipslyStudioTheme.sage)
                .rotationEffect(.degrees(-90))
                .fixedSize()

            Spacer()

            VStack(spacing: 8) {
                Button("16:9") {
                    playbackEngine.playbackFormat = .horizontal16x9
                    rebuildPlayer()
                }
                .font(.caption2)
                .buttonStyle(.borderedProminent)
                .controlSize(.mini)

                Button("9:16") {
                    playbackEngine.playbackFormat = .vertical9x16
                    rebuildPlayer()
                }
                .font(.caption2)
                .buttonStyle(.bordered)
                .controlSize(.mini)
            }
            .rotationEffect(.degrees(-90))
            .fixedSize()
            .padding(.bottom, 26)
        }
        .padding(.vertical, 12)
        .frame(width: 58)
        .background(QuipslyStudioTheme.toolBayGradient)
        .overlay(alignment: .trailing) {
            Rectangle()
                .fill(QuipslyStudioTheme.honey.opacity(0.10))
                .frame(width: 1)
        }
    }

