    private var workbenchModeDeck: some View {
        LazyVGrid(
            columns: [
                GridItem(.flexible(), spacing: 8),
                GridItem(.flexible(), spacing: 8)
            ],
            spacing: 8
        ) {
            ForEach(LeftWorkbenchMode.allCases) { mode in
                leftWorkbenchModeButton(mode)
