    private func leftWorkbenchModeButton(_ mode: LeftWorkbenchMode) -> some View {
        let isSelected = leftWorkbenchMode == mode
        let tint = mode.tint
        return Button {
            withAnimation(.easeInOut(duration: 0.16)) {
                leftWorkbenchMode = mode
            }
        } label: {
            VStack(alignment: .leading, spacing: 5) {
                HStack(spacing: 6) {
                    Image(systemName: mode.icon)
                        .font(.caption)
                        .foregroundStyle(isSelected ? QuipslyStudioTheme.night.opacity(0.90) : tint)
                        .frame(width: 21, height: 21)
                        .background((isSelected ? QuipslyStudioTheme.night.opacity(0.10) : tint.opacity(0.12)))
                        .clipShape(RoundedRectangle(cornerRadius: 7, style: .continuous))
                    Text(mode.title)
                        .font(.caption)
                        .fontWeight(.black)
                        .lineLimit(1)
                        .minimumScaleFactor(0.72)
                    Spacer(minLength: 0)
                }
                Text(mode.microLabel)
                    .font(.caption2)
                    .fontWeight(.black)
                    .tracking(0.3)
                    .foregroundStyle(isSelected ? QuipslyStudioTheme.night.opacity(0.62) : tint.opacity(0.86))
                    .lineLimit(1)
                    .minimumScaleFactor(0.70)
            }
            .frame(maxWidth: .infinity, alignment: .leading)
            .frame(minHeight: 50)
            .padding(.horizontal, 9)
            .padding(.vertical, 8)
            .foregroundStyle(isSelected ? QuipslyStudioTheme.night : QuipslyStudioTheme.lichen)
            .background(
                RoundedRectangle(cornerRadius: 16, style: .continuous)
                    .fill(isSelected ? AnyShapeStyle(QuipslyStudioTheme.selectedToolGradient) : AnyShapeStyle(QuipslyStudioTheme.quietToolGradient))
                    .overlay(
                        RoundedRectangle(cornerRadius: 16, style: .continuous)
                            .stroke(isSelected ? tint.opacity(0.95) : QuipslyStudioTheme.quietStroke, lineWidth: 1)
                    )
                    .shadow(color: isSelected ? tint.opacity(0.18) : .clear, radius: 12, y: 5)
            )
        }
        .buttonStyle(.plain)
        .help("Open \(mode.title): \(mode.helperText)")
        .accessibilityIdentifier("quipsly.workbench.tab.\(mode.rawValue)")
        .accessibilityLabel("Open \(mode.title) workbench. \(mode.helperText)")
    }

    private var mainWorkspace: some View {
        ZStack {
            studioBackdrop
                .ignoresSafeArea()
            QuipslyStudioTheme.clearingGlowGradient
                .ignoresSafeArea()

            VStack(spacing: 10) {
                studioMasthead
                    .accessibilityIdentifier("quipsly.editor.masthead")

                studioCompassStrip
                    .padding(.horizontal, 14)
                    .accessibilityIdentifier("quipsly.editor.studioCompass")

                editorNextActionRail
                    .padding(.horizontal, 14)
                    .accessibilityIdentifier("quipsly.editor.nextActionRail")

                monitorWall
                    .id(WorkspaceScrollTarget.monitors)
                    .frame(minHeight: 450, maxHeight: 690)
                    .padding(.horizontal, 14)
                    .accessibilityIdentifier("quipsly.editor.monitorWall")

                ScrollViewReader { scrollProxy in
                    ScrollView(.vertical) {
                        VStack(spacing: 12) {
                            NativeTransportControls(
                                playbackEngine: playbackEngine,
                                onPlaybackModeRequest: handlePlaybackModeRequest
                            )
                                .padding(.horizontal, 14)
                                .padding(.vertical, 8)
                                .background(
                                    RoundedRectangle(cornerRadius: 22, style: .continuous)
                                        .fill(QuipslyStudioTheme.quietInsetGradient)
                                        .overlay(
                                            RoundedRectangle(cornerRadius: 22, style: .continuous)
                                                .stroke(QuipslyStudioTheme.quietStroke, lineWidth: 1)
                                        )
                                )
                                .padding(.horizontal, 14)
                                .accessibilityIdentifier("quipsly.editor.transport")

                            selectedShortTimelineFocusStrip
                                .padding(.horizontal, 14)
                                .accessibilityIdentifier("quipsly.editor.selectedShortFocus")

                            TimelineEditorView(
                                playbackEngine: playbackEngine,
                                projectStore: projectStore,
                                selectedLaneId: selectedLaneId,
                                selectedTagId: selectedTagId,
                                visualReviewBoundaries: visualDecisionBoundariesForTimeline(),
                                focusedSourceReviewBoundaries: sourceDecisionBoundariesForTimeline(laneId: selectedLaneId),
                                selectedShortTitle: selectedShortClipValue()?.title,
                                selectedShortSegments: selectedShortTimelineSegments(),
                                onSelectTag: { laneId, tagId in
                                    selectedLaneId = laneId
                                    selectedTagId = tagId
                                },
                                onAddTag: { laneId, tag in
                                    guard var seq = projectStore.activeSequence,
                                          let laneIndex = seq.lanes.firstIndex(where: { $0.id == laneId }) else { return }
                                    seq.lanes[laneIndex].tags.append(tag)
                                    selectedLaneId = laneId
                                    selectedTagId = tag.id
                                    projectStore.updateSequence(seq, undoManager: nil, actionName: "Add Tag")
                                    rebuildPlayer()
                                    scheduleAutosave(reason: "added decision")
                                },
                                onRemoveTag: { laneId, tagId in
                                    guard var seq = projectStore.activeSequence,
                                          let laneIndex = seq.lanes.firstIndex(where: { $0.id == laneId }) else { return }
                                    seq.lanes[laneIndex].tags.removeAll(where: { $0.id == tagId })
                                    if selectedLaneId == laneId && selectedTagId == tagId {
                                        selectedLaneId = nil
                                        selectedTagId = nil
                                    }
                                    projectStore.updateSequence(seq, undoManager: nil, actionName: "Remove Tag")
                                    rebuildPlayer()
                                    scheduleAutosave(reason: "removed decision")
                                },
                                onUpdateTag: { laneId, updatedTag in
                                    guard var seq = projectStore.activeSequence,
                                          let laneIndex = seq.lanes.firstIndex(where: { $0.id == laneId }),
                                          let tagIndex = seq.lanes[laneIndex].tags.firstIndex(where: { $0.id == updatedTag.id }) else { return }
                                    seq.lanes[laneIndex].tags[tagIndex] = updatedTag
                                    selectedLaneId = laneId
                                    selectedTagId = updatedTag.id
                                    projectStore.updateSequence(seq, undoManager: nil, actionName: "Update Tag")
                                    rebuildPlayer()
                                    scheduleAutosave(reason: "updated decision")
                                },
                                onSelectAdjacentDecision: { direction in
                                    jumpToAdjacentDecision(direction: direction, scope: "video")
                                },
                                onSelectReviewBoundary: { boundary in
                                    selectReviewBoundary(boundary)
                                },
                                onZoomChanged: { scale, fitToWindow, label in
                                    lastMediaAction = fitToWindow
                                        ? label
                                        : String(format: "%@ (%.1f px/sec)", label, scale)
                                    updateAgentState()
                                },
                                onTimelineHitboxChange: { frame in
                                    if timelineWindowFrame.isMeaningfullyDifferent(from: frame) {
                                        timelineWindowFrame = frame
                                        updateAgentState()
                                    }
                                },
                                allowExternalOriginalMedia: false,
                                pixelsPerSecond: $timelinePixelsPerSecond,
                                fitToWindow: $isTimelineFitToWindow
                            )
                            .frame(maxHeight: .infinity)
                            .padding(.vertical, 10)
                            .background(
                                RoundedRectangle(cornerRadius: 28, style: .continuous)
                                    .fill(QuipslyStudioTheme.timelineMapGradient)
                                    .overlay(
                                        RoundedRectangle(cornerRadius: 28, style: .continuous)
                                            .stroke(QuipslyStudioTheme.warmGlassStroke, lineWidth: 1)
                                    )
                            )
                            .shadow(color: QuipslyStudioTheme.softShadow.opacity(0.82), radius: 18, y: 9)
                            .padding(.horizontal, 14)
                            .id(WorkspaceScrollTarget.timeline)
                            .accessibilityIdentifier("quipsly.editor.timeline")

                            productionActionBar
                                .padding(.horizontal, 14)
                                .padding(.vertical, 8)
                                .background(
                                    RoundedRectangle(cornerRadius: 22, style: .continuous)
                                        .fill(QuipslyStudioTheme.quietInsetGradient)
                                        .overlay(
                                            RoundedRectangle(cornerRadius: 22, style: .continuous)
                                                .stroke(QuipslyStudioTheme.quietStroke, lineWidth: 1)
                                        )
                                )
                                .padding(.horizontal, 14)
                                .accessibilityIdentifier("quipsly.editor.productionDock")

                            externalStorageOnboardingBanner
                                .padding(.horizontal, 14)
                                .accessibilityIdentifier("quipsly.editor.externalStorageBanner")

                            productionDetailsDrawer
                                .padding(.horizontal, 14)
                                .accessibilityIdentifier("quipsly.editor.productionDetails")

                            Spacer()
                        }
                        .padding(.bottom, 14)
                    }
                    .onChange(of: timelineFocusRequest) { _ in
                        withAnimation(.easeInOut(duration: 0.22)) {
                            scrollProxy.scrollTo(WorkspaceScrollTarget.timeline, anchor: .top)
                        }
                    }
                }
            }
        }
        .onChange(of: monitorFocusRequest) { _ in
            // Monitor Wall is pinned above the scrolling workbench, so focusing it
            // no longer requires a scroll operation. The state update still gives
            // agents a visible acknowledgement via lastMediaAction.
        }
        .onChange(of: projectStore.project) { _ in
            updateAgentState()
        }
        .onChange(of: projectStore.activeSequenceId) { _ in
            requestMonitorFocus(reason: "Focused monitor wall for loaded sequence")
        }
        .onChange(of: playbackEngine.playhead) { newValue in
            enforceSelectedShortPreviewStop(at: newValue)
            guard abs(newValue - lastAgentPlayheadUpdate) >= 0.25 else { return }
            lastAgentPlayheadUpdate = newValue
            updateAgentState()
        }
        .onChange(of: playbackEngine.isPlaying) { _ in
            updateAgentState()
        }
        .onChange(of: agentServer.trigger) { _ in
            handleAgentCommandDispatch(fallbackToLegacy: true)
        }
        .onChange(of: agentServer.commandSerial) { _ in
            handleAgentCommandDispatch(fallbackToLegacy: false)
        }
        .onReceive(Timer.publish(every: 0.5, on: .main, in: .common).autoconnect()) { _ in
            handleAgentCommandDispatch(fallbackToLegacy: false)
            refreshProxyJobSnapshotIfNeeded()
        }
        #if os(macOS)
        .onAppear {
            installKeyboardMonitorIfNeeded()
            installProgramScrollMonitorIfNeeded()
            refreshProxyJobSnapshotIfNeeded(force: true)
            restoreActiveSessionIfPossible()
            if projectStore.activeSequence != nil {
                requestMonitorFocus(reason: "Focused monitor wall on launch")
            } else {
                updateAgentState()
            }
        }
        .onDisappear {
            removeKeyboardMonitor()
            removeProgramScrollMonitor()
        }
        #endif
    }

    private var studioBackdrop: some View {
        ZStack {
            QuipslyStudioTheme.night
            QuipslyStudioTheme.studioGradient
            RadialGradient(
                colors: [QuipslyStudioTheme.moonMilk.opacity(0.10), QuipslyStudioTheme.honey.opacity(0.10), Color.clear],
                center: .topTrailing,
                startRadius: 20,
                endRadius: 640
            )
            RadialGradient(
                colors: [QuipslyStudioTheme.creek.opacity(0.12), QuipslyStudioTheme.fern.opacity(0.08), Color.clear],
                center: .bottomLeading,
                startRadius: 20,
                endRadius: 720
            )
            RadialGradient(
                colors: [QuipslyStudioTheme.moss.opacity(0.10), Color.clear],
                center: .center,
                startRadius: 80,
                endRadius: 840
            )
            Canvas { context, size in
                let lineColor = QuipslyStudioTheme.moonMilk.opacity(0.030)
                let accentColor = QuipslyStudioTheme.moss.opacity(0.022)
                let spacing: CGFloat = 58
                var x: CGFloat = -size.height
                var index: Int = 0
                while x < size.width + size.height {
                    var path = Path()
                    path.move(to: CGPoint(x: x, y: 0))
                    path.addCurve(
                        to: CGPoint(x: x + size.height * 0.45, y: size.height),
                        control1: CGPoint(x: x + 120, y: size.height * 0.28),
                        control2: CGPoint(x: x - 90, y: size.height * 0.74)
                    )
                    context.stroke(path, with: .color(index.isMultiple(of: 3) ? accentColor : lineColor), lineWidth: index.isMultiple(of: 4) ? 1.4 : 0.8)
                    x += spacing
                    index += 1
                }
            }
            .blendMode(.screen)
        }
    }

