    private struct EditorNextAction {
        var title: String
        var detail: String
        var buttonTitle: String
        var help: String
        var icon: String
        var tint: Color
        var target: EditorNextActionTarget
    }

    private enum EditorNextActionTarget {
        case timeline
        case ship
        case state
    }

    private func editorNextAction(
        summary: MediaReadinessSummary,
        sequence: MediaSequence?,
        records: [PublishReceiptRecord],
        releasePrepared: Bool,
        shortsPrepared: Bool,
        podcastPrepared: Bool,
        receiptCount: Int
    ) -> EditorNextAction {
        if sequence == nil {
            return EditorNextAction(
                title: "Load or import a sequence",
                detail: "The editor needs a living spine before cuts, audio, or publishing can be prepared.",
                buttonTitle: "Copy State",
                help: "Copy current editor state so a human or Codex can diagnose the missing sequence.",
                icon: "tray.and.arrow.down.fill",
                tint: QuipslyStudioTheme.clay,
                target: .state
            )
        }

        if summary.showDecisionCount == 0 {
            return EditorNextAction(
                title: "Mark the first SHOW decision",
                detail: "Choose what Program should show; sources remain whole underneath.",
                buttonTitle: "Timeline",
                help: "Jump to the Episode Spine and start shaping SHOW/SKIP metadata.",
                icon: "timeline.selection",
                tint: QuipslyStudioTheme.honey,
                target: .timeline
            )
        }

        if (sequence?.shortClipQueue.count ?? 0) == 0 && !shortsPrepared {
            return EditorNextAction(
                title: "Pull one vertical cut",
                detail: "Create at least one 9:16 recipe so social output is part of the proof loop.",
                buttonTitle: "Timeline",
                help: "Jump to the Episode Spine and select a moment for a short cut recipe.",
                icon: "rectangle.portrait.on.rectangle.portrait.angled",
                tint: QuipslyStudioTheme.creek,
                target: .timeline
            )
        }

        if !releasePrepared || !podcastPrepared || !shortsPrepared {
            return EditorNextAction(
                title: "Prepare output packets",
                detail: "Ship needs the 16:9 master, 9:16 cuts, and podcast handoff before proof.",
                buttonTitle: "Open Ship",
                help: "Open Ship to prepare release artifacts and handoff packets.",
                icon: "shippingbox.fill",
                tint: QuipslyStudioTheme.moss,
                target: .ship
            )
        }

        if records.isEmpty || receiptCount < records.count {
            return EditorNextAction(
                title: "Capture publication receipts",
                detail: "Prepared files are not proof; save URLs or provider IDs after publishing.",
                buttonTitle: "Open Ship",
                help: "Open Ship to capture publication receipt proof.",
                icon: "checklist.checked",
                tint: QuipslyStudioTheme.sage,
                target: .ship
            )
        }

        return EditorNextAction(
            title: "Everything visible is proof-ready",
            detail: "Keep editing, export state, or publish the next episode from the same spine.",
            buttonTitle: "Copy State",
            help: "Copy the current shared editor state for handoff or review.",
            icon: "checkmark.seal.fill",
            tint: QuipslyStudioTheme.moss,
            target: .state
        )
    }

    private func workflowStepPill(_ title: String, _ isReady: Bool, _ tint: Color) -> some View {
        HStack(spacing: 4) {
            Image(systemName: isReady ? "checkmark.circle.fill" : "circle")
                .font(.caption2)
            Text(title.uppercased())
                .font(.caption2)
                .fontWeight(.black)
        }
        .foregroundStyle(isReady ? tint : .secondary)
        .padding(.horizontal, 6)
        .padding(.vertical, 4)
        .background((isReady ? tint : Color.secondary).opacity(isReady ? 0.10 : 0.055))
        .clipShape(Capsule())
    }

    private func performEditorNextAction(_ action: EditorNextAction) {
        switch action.target {
        case .timeline:
            requestTimelineFocus(reason: action.title)
            lastMediaAction = action.title
        case .ship:
            isInspectorVisible = true
            leftWorkbenchMode = .publish
            lastMediaAction = action.title
        case .state:
            let summary = mediaReadinessSummary()
            let sequence = projectStore.activeSequence
            let records = sequence?.publishReceipts ?? []
            copyTextToClipboard(studioCompassStateJSON(
                summary: summary,
                sequence: sequence,
                records: records,
                releasePrepared: !fullReleaseOutputPath.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty,
                shortsPrepared: !socialShortsPacketOutputPath.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty,
                podcastPrepared: !podcastReadyPacketOutputPath.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty,
                capturedReceipts: records.filter { publishRecordReceiptCaptured($0) }.count
            ))
            lastMediaAction = "Copied editor state from next-action rail"
        }
        updateAgentState()
    }

    private func studioCompassStateJSON(
        summary: MediaReadinessSummary,
        sequence: MediaSequence?,
        records: [PublishReceiptRecord],
        releasePrepared: Bool,
        shortsPrepared: Bool,
        podcastPrepared: Bool,
        capturedReceipts: Int
    ) -> String {
        jsonString(from: [
            "payloadVersion": 1,
            "generatedAt": ISO8601DateFormatter().string(from: Date()),
            "truth": "Program publishes; sources stay whole; spine decisions change; Ship separates prepared, approved, posted, and proved states for humans and Codex.",
            "safeCodexActions": [
                "inspect-state",
                "prepare-show-skip-tags",
                "prepare-frame-recipes",
                "prepare-short-recipes",
                "prepare-packets",
                "review-delivery-path",
                "copy-missing-receipts",
                "prepare-social-posting-packet"
            ],
            "requiresHumanApproval": [
                "upload",
                "publish",
                "claim-publication-proof",
                "capture-receipt-without-real-url",
                "connect-platform-account",
                "destructive-source-change"
            ],
            "sequence": [
                "id": sequence?.id.uuidString ?? "",
