    private func missionStep(title: String, state: String, icon: String, tint: Color) -> some View {
        HStack(spacing: 6) {
            Image(systemName: icon)
                .font(.caption2)
                .foregroundStyle(tint)
            VStack(alignment: .leading, spacing: 0) {
                Text(title)
                    .font(.caption2)
                    .fontWeight(.black)
                    .lineLimit(1)
                Text(state)
                    .font(.caption2)
                    .foregroundStyle(.secondary)
                    .lineLimit(1)
            }
        }
        .frame(maxWidth: .infinity, alignment: .leading)
        .padding(.horizontal, 7)
        .padding(.vertical, 5)
        .background(tint.opacity(0.08))
        .overlay(
            RoundedRectangle(cornerRadius: 12, style: .continuous)
                .stroke(tint.opacity(0.13), lineWidth: 1)
        )
        .clipShape(RoundedRectangle(cornerRadius: 12, style: .continuous))
        .accessibilityIdentifier("quipsly.sessionMission.\(missionStepIdentifierToken(title))")
        .accessibilityLabel("Session mission step \(title): \(state)")
    }

    private func missionStepIdentifierToken(_ title: String) -> String {
        let normalized = title
            .lowercased()
            .replacingOccurrences(of: "+", with: "plus")
            .replacingOccurrences(of: "&", with: "and")
            .replacingOccurrences(of: " ", with: "")
        let safeString = normalized.unicodeScalars.map { scalar -> String in
            CharacterSet.alphanumerics.contains(scalar) ? String(scalar) : "_"
        }.joined()
        let token = safeString
            .split(separator: "_", omittingEmptySubsequences: true)
            .joined(separator: "_")
        return token.isEmpty ? "step" : token
    }

    private func studioStatusToken(_ title: String, _ value: String, _ color: Color, _ icon: String) -> some View {
        HStack(spacing: 8) {
            Image(systemName: icon)
                .font(.caption)
                .foregroundStyle(color)
                .frame(width: 18)
            VStack(alignment: .leading, spacing: 1) {
                Text(title.uppercased())
                    .font(.caption2)
                    .fontWeight(.black)
                    .tracking(0.8)
                    .foregroundStyle(.secondary)
            Text(value)
                    .font(.caption)
                    .fontWeight(.semibold)
                    .lineLimit(1)
                    .truncationMode(.middle)
            }
        }
        .padding(.horizontal, 10)
        .padding(.vertical, 7)
        .background(color.opacity(0.12))
        .overlay(
            RoundedRectangle(cornerRadius: 14, style: .continuous)
                .stroke(color.opacity(0.28), lineWidth: 1)
        )
        .clipShape(RoundedRectangle(cornerRadius: 14, style: .continuous))
    }

    private func compactProgramTitle(_ title: String) -> String {
        let cleaned = title
            .replacingOccurrences(of: "Showing ", with: "")
            .replacingOccurrences(of: " + ", with: " + ")
            .trimmingCharacters(in: .whitespacesAndNewlines)
        if cleaned.count <= 34 { return cleaned }
        return "\(cleaned.prefix(31))..."
    }

