        .accessibilityLabel("\(title) readiness state: \(detail).")
        .accessibilityIdentifier("quipsly.releaseMap.readiness.\(readinessLegendToken(title))")
    }

    private func readinessLegendToken(_ value: String) -> String {
        let safe = value.lowercased().unicodeScalars.map { scalar -> String in
            CharacterSet.alphanumerics.contains(scalar) ? String(scalar) : "-"
        }.joined()
        let collapsed = safe
            .replacingOccurrences(of: "-+", with: "-", options: .regularExpression)
            .trimmingCharacters(in: CharacterSet(charactersIn: "-"))
        return collapsed.isEmpty ? "state" : collapsed
    }

