        return VStack(alignment: .leading, spacing: 10) {
            HStack(spacing: 10) {
                Image(systemName: "shippingbox.and.arrow.backward.fill")
                    .font(.title3)
                    .foregroundStyle(QuipslyStudioTheme.creek)
                    .frame(width: 30, height: 30)
                    .background(QuipslyStudioTheme.creek.opacity(0.14))
                    .clipShape(Circle())
                VStack(alignment: .leading, spacing: 2) {
                    Text("Delivery readiness")
                        .font(.subheadline)
                        .fontWeight(.semibold)
                    Text("Rendering, shorts, podcast audio, and platform publishing are tracked separately so an export is not mistaken for a release.")
                        .font(.caption)
                        .foregroundStyle(.secondary)
                }
                Spacer()
                Text("\(lanes.filter { $0.isReady }.count)/\(lanes.count) ready")
                    .font(.caption2)
                    .fontWeight(.black)
                    .foregroundStyle(QuipslyStudioTheme.creek)
                    .padding(.horizontal, 8)
                    .padding(.vertical, 4)
                    .background(QuipslyStudioTheme.creek.opacity(0.12))
                    .clipShape(Capsule())
            }

            LazyVGrid(columns: [GridItem(.adaptive(minimum: 220), spacing: 8)], spacing: 8) {
                ForEach(lanes) { lane in
                    deliveryLaneCard(lane)
                }
            }

            deliveryPacketPanel
            publishLedgerPanel

            shortClipQueuePanel

            HStack(alignment: .top, spacing: 8) {
                Image(systemName: "info.circle")
                    .foregroundStyle(.secondary)
                Text("Publishing truth: this app can prove proxy render readiness before it proves account upload automation. YouTube, Patreon, social, Spotify, and Apple Podcasts still need explicit channel integrations before direct publishing is called ready.")
                    .font(.caption2)
                    .foregroundStyle(.secondary)
            }
        }
        .padding(10)
        .background(QuipslyStudioTheme.cardGradient)
        .overlay(
            RoundedRectangle(cornerRadius: 14, style: .continuous)
                .stroke(QuipslyStudioTheme.creek.opacity(0.18), lineWidth: 1)
        )
        .clipShape(RoundedRectangle(cornerRadius: 14, style: .continuous))
        .accessibilityIdentifier("quipsly.delivery.readiness")
    }

    private var publishLedgerPanel: some View {
        let sequence = projectStore.activeSequence
        let records = sequence?.publishReceipts ?? []
        let readyCount = records.filter { $0.publishStatus == "ready-to-upload" }.count
        let scheduledCount = records.filter { $0.publishStatus == "scheduled" }.count
        let uploadedCount = records.filter { $0.publishStatus == "uploaded" }.count
        let publishedCount = records.filter { $0.publishStatus == "published" }.count
        let integrationNeededCount = records.filter { $0.uploadJobStatus == "integration-needed" }.count

        return VStack(alignment: .leading, spacing: 10) {
            HStack(alignment: .top, spacing: 10) {
                Image(systemName: "checklist.checked")
                    .font(.headline)
                    .foregroundStyle(QuipslyStudioTheme.moss)
                    .frame(width: 30, height: 30)
                    .background(QuipslyStudioTheme.moss.opacity(0.14))
                    .clipShape(Circle())

                VStack(alignment: .leading, spacing: 2) {
                    Text("Ship ledger")
                        .font(.caption)
                        .fontWeight(.bold)
                    Text(records.isEmpty
                         ? "Generate platform records from exported artifacts before upload, scheduling, and receipt work."
                         : publishLedgerSummaryText(recordCount: records.count, readyCount: readyCount, scheduledCount: scheduledCount, uploadedCount: uploadedCount, publishedCount: publishedCount, integrationNeededCount: integrationNeededCount))
                        .font(.caption2)
                        .foregroundStyle(.secondary)
                        .fixedSize(horizontal: false, vertical: true)
                }

                Spacer(minLength: 8)

                Button {
                    generatePublishLedgerFromCurrentDelivery()
                } label: {
                    Label(records.isEmpty ? "Generate ledger" : "Refresh ledger", systemImage: "wand.and.stars")
                }
                .buttonStyle(.borderedProminent)
                .controlSize(.small)
                .disabled(sequence == nil)
                .help("Create or update platform-specific publish records from exported artifacts and the delivery packet.")

                Button {
                    copyPublishLedgerJSON()
                } label: {
                    Label("Copy JSON", systemImage: "doc.on.doc")
                }
                .controlSize(.small)
                .disabled(records.isEmpty)

                Button {
                    generatePublishPacketForAgent(directoryPath: nil, basename: nil)
                } label: {
                    Label("Packet", systemImage: "tray.and.arrow.down")
                }
                .controlSize(.small)
                .disabled(records.isEmpty)
                .help("Write a publish handoff packet with ledger JSON plus per-platform metadata, upload job, and checklist files.")

                Button {
                    generatePublishUploadPacketBundleForAgent(directoryPath: nil, basename: nil)
                } label: {
                    Label(publishUploadBundleStatus == "generating" ? "Writing Uploads..." : "Upload Bundle", systemImage: "shippingbox")
                }
                .controlSize(.small)
                .disabled(records.isEmpty || publishUploadBundleStatus == "generating")
                .help("Write one upload packet JSON per platform record plus a manifest and README for manual or Codex publishing.")

                Button {
                    generatePublicationCockpitForAgent(directoryPath: nil, basename: nil)
                } label: {
                    Label(publicationCockpitStatus == "generating" ? "Writing Cockpit..." : "Cockpit", systemImage: "rectangle.3.group")
                }
                .controlSize(.small)
                .disabled(records.isEmpty || publicationCockpitStatus == "generating")
                .help("Write the human/Codex publication cockpit: core artifacts, top shorts, upload checklist, and receipt commands in one place.")

                Button {
                    runAllBundledPublishConnectorWorkersDryRunFromAgent(values: [:])
                } label: {
                    Label("Dry-run all", systemImage: "play.rectangle.on.rectangle")
                }
                .controlSize(.small)
                .disabled(records.isEmpty || publishConnectorWorkerStatus == "running" || publishConnectorWorkerStatus == "running-all")
                .help("Run every bundled dry-run worker against the current publish ledger. This proves packet safety; it does not upload or publish.")

                Button {
                    prepareFullReleaseForHuman()
                } label: {
                    Label("Full prep", systemImage: "shippingbox.and.arrow.backward")
                }
                .controlSize(.small)
                .disabled(sequence == nil || exportEngine.isExporting)
                .help("Run release prep, then generate the delivery packet, publish ledger, release checklist, and publish packet in one operator flow.")

                Button {
                    generatePodcastPacketForAgent(directoryPath: nil, basename: nil)
                } label: {
                    Label(podcastPacketStatus == "generating" ? "Writing Podcast..." : "Podcast Packet", systemImage: "dot.radiowaves.left.and.right")
                }
                .controlSize(.small)
                .disabled(sequence == nil || podcastPacketStatus == "generating")
                .help("Write a Spotify and Apple Podcasts handoff packet for the exported audio master. This does not upload directly; it prepares the RSS/podcast-host handoff.")

                Button {
                    generatePodcastReadyPacketForCurrentManifest()
                } label: {
                    Label("Podcast Ready", systemImage: "checklist.checked")
                }
                .controlSize(.small)
                .disabled(podcastPacketOutputPath.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty || podcastPacketStatus == "generating" || podcastReadyPacketStatus == "generating")
                .help("Turn the generated podcast manifest into the operator-ready Spotify/Apple handoff folder with copied audio, probe data, CSV, README, and optional zip.")

                Button {
                    generateSocialPublicationQueueForAgent(directoryPath: nil, basename: nil)
                } label: {
                    Label(socialPublicationQueueStatus == "generating" ? "Writing Queue..." : "Social Queue", systemImage: "square.grid.3x3.square")
                }
                .controlSize(.small)
                .disabled(sequence == nil || socialPublicationQueueStatus == "generating")
                .help("Prepare a manual-upload queue with copied 9:16 shorts, per-platform copy, captions, CSV, JSON, and a README.")
            }

            publicationMissionControlPanel(records: records)

            if fullReleaseStatus != "idle" || !fullReleaseOutputPath.isEmpty || !fullReleaseErrorMessage.isEmpty {
                fullReleaseStatusRow
            }

            if records.isEmpty {
                HStack(alignment: .top, spacing: 8) {
                    Image(systemName: "arrow.down.doc")
                        .foregroundStyle(.secondary)
                    Text("After release prep exports the episode master, vertical master, shorts, and podcast audio, this ledger becomes the platform work queue for YouTube, Patreon, social, Spotify, and Apple Podcasts.")
                    .font(.caption2)
                    .foregroundStyle(.secondary)
                    .fixedSize(horizontal: false, vertical: true)
                }
                .padding(8)
                .background(QuipslyStudioTheme.panelLift.opacity(0.18))
                .clipShape(RoundedRectangle(cornerRadius: 12, style: .continuous))
            } else {
                HStack(spacing: 6) {
                    publishStatPill("records", records.count, QuipslyStudioTheme.moss)
                    publishStatPill("ready", readyCount, QuipslyStudioTheme.moss)
                    publishStatPill("scheduled", scheduledCount, QuipslyStudioTheme.creek)
                    publishStatPill("uploaded", uploadedCount, QuipslyStudioTheme.creek)
                    publishStatPill("published", publishedCount, QuipslyStudioTheme.honey)
                    publishStatPill("needs API", integrationNeededCount, QuipslyStudioTheme.clay)
                }

                publicationReadyHandoffPanel(records: records)
                publishReleaseChecklistPanel(records: records)
                socialPublicationQueuePanel(records: records)
                publishReceiptCapturePanel(records: records)

                if publishConnectorWorkerStatus != "idle" || !publishConnectorWorkerResultJson.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty || !publishConnectorWorkerErrorMessage.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty {
                    publishConnectorWorkerStatusRow
                }

                if let selectedReceipt = selectedPublishReceipt(from: records) {
                    publishReceiptEditorPanel(selectedReceipt)
                }

                LazyVGrid(columns: [GridItem(.adaptive(minimum: 255), spacing: 8)], spacing: 8) {
                    ForEach(records.prefix(8), id: \.id) { record in
                        publishReceiptCard(record)
                    }
                }

                Text(publishLedgerNextActionText(records: records))
                    .font(.caption2)
                    .foregroundStyle(.secondary)
                    .fixedSize(horizontal: false, vertical: true)

                if publishPacketStatus != "idle" || !publishPacketOutputPath.isEmpty || !publishPacketErrorMessage.isEmpty {
                    publishPacketStatusRow
                }

                if publishUploadBundleStatus != "idle" || !publishUploadBundleOutputPath.isEmpty || !publishUploadBundleErrorMessage.isEmpty {
                    publishUploadBundleStatusRow
                }

                if publicationCockpitStatus != "idle" || !publicationCockpitOutputPath.isEmpty || !publicationCockpitErrorMessage.isEmpty {
                    publicationCockpitStatusRow
                }
            }

            if podcastPacketStatus != "idle" || !podcastPacketOutputPath.isEmpty || !podcastPacketErrorMessage.isEmpty {
                podcastPacketStatusRow
            }

            if podcastReadyPacketStatus != "idle" || !podcastReadyPacketOutputPath.isEmpty || !podcastReadyPacketErrorMessage.isEmpty {
                podcastReadyPacketStatusRow
            }

            if socialPublicationQueueStatus != "idle" || !socialPublicationQueueOutputPath.isEmpty || !socialPublicationQueueErrorMessage.isEmpty {
                socialPublicationQueueStatusRow
            }
        }
        .padding(9)
        .background(QuipslyStudioTheme.cardGradient)
        .overlay(
            RoundedRectangle(cornerRadius: 14, style: .continuous)
                .stroke(QuipslyStudioTheme.moss.opacity(0.18), lineWidth: 1)
        )
        .clipShape(RoundedRectangle(cornerRadius: 14, style: .continuous))
        .accessibilityIdentifier("quipsly.publish.ledger")
    }

    private var nestWorkbenchSidebar: some View {
        let documents = projectStore.project.nestDocuments.sorted { $0.updatedAt > $1.updatedAt }
        let selectedDocument = selectedNestDocumentValue() ?? documents.first

        return ScrollView {
            VStack(alignment: .leading, spacing: 14) {
                HStack(spacing: 10) {
                    Image(systemName: "leaf.fill")
                        .font(.title3)
                        .foregroundStyle(QuipslyStudioTheme.moss)
                    VStack(alignment: .leading, spacing: 2) {
                        Text("Quipsly Nest")
                            .font(.headline)
                            .foregroundStyle(QuipslyStudioTheme.moonMilk)
                        Text("Writing, source context, and episode memory.")
                            .font(.caption)
                            .foregroundStyle(QuipslyStudioTheme.sage)
                    }
                    Spacer()
                }

                VStack(alignment: .leading, spacing: 8) {
                    Text("Seeded episode context")
                        .font(.caption)
                        .fontWeight(.black)
                        .foregroundStyle(QuipslyStudioTheme.honey)
                    Text("Seeded text is working context, not final manuscript truth. Charlie’s new writing becomes the authored layer.")
                        .font(.caption)
                        .foregroundStyle(QuipslyStudioTheme.sage)

                    Button {
                        seedHighGroundOdysseyNestContext()
                    } label: {
                        Label(documents.isEmpty ? "Seed Episodes 1-3" : "Refresh seed context", systemImage: "tray.and.arrow.down.fill")
                            .frame(maxWidth: .infinity)
                    }
                    .buttonStyle(.borderedProminent)
                    .controlSize(.small)
                    .help("Create reviewable Nest context blocks for Episodes 1-3 from local transcript/import artifacts. Does not overwrite authored writing.")
