                nestWritingReadinessPanel
                nestWritingNextActionPanel
                nestWritingPacketPanel

                nestOutlinePanel

                VStack(alignment: .leading, spacing: 8) {
                    Text("Write / paste")
                        .font(.caption)
                        .fontWeight(.black)
                        .foregroundStyle(QuipslyStudioTheme.lichen)
                    Text("Drafts can be human-authored, agent-authored, or mixed. Quipsly tracks that so AI can create real work without turning the manuscript into a black box.")
                        .font(.caption2)
                        .foregroundStyle(QuipslyStudioTheme.sage)
                        .fixedSize(horizontal: false, vertical: true)
                    TextField("Title or moment", text: $nestDraftTitle)
