                    .pickerStyle(.segmented)
                    .controlSize(.small)
                    TextEditor(text: $nestDraftBody)
                        .font(.body)
                        .frame(minHeight: 150)
                        .padding(8)
                        .background(Color.black.opacity(0.16))
                        .clipShape(RoundedRectangle(cornerRadius: 14, style: .continuous))
                    Button {
                        appendNestDraftBlock()
                    } label: {
                        Label("Add writing block", systemImage: "plus.circle.fill")
                            .frame(maxWidth: .infinity)
                    }
                    .buttonStyle(.borderedProminent)
                    .disabled(nestDraftBody.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty)
                    .help("Append a durable Nest block to the active writing document.")

                    HStack(spacing: 8) {
                        Button {
                            appendNestStructureMarker(kind: "chapter")
                        } label: {
                            Label("Chapter", systemImage: "book.closed.fill")
                                .frame(maxWidth: .infinity)
                        }
                        .buttonStyle(.bordered)
                        .disabled(nestDraftTitle.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty && nestDraftBody.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty)
