                            appendNestStructureMarker(kind: "episode")
                        } label: {
                            Label("Episode", systemImage: "play.rectangle.fill")
                                .frame(maxWidth: .infinity)
                        }
                        .buttonStyle(.bordered)
                        .disabled(nestDraftTitle.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty && nestDraftBody.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty)
