                            .background(Color.black.opacity(0.12))
                            .clipShape(RoundedRectangle(cornerRadius: 14, style: .continuous))
                    } else {
                        ForEach(documents) { document in
                            Button {
                                selectedNestDocumentId = document.id
                                selectedNestBlockId = document.blocks.first?.id
                                lastMediaAction = "Selected Nest document: \(document.title)"
                                updateAgentState()
                            } label: {
                                VStack(alignment: .leading, spacing: 6) {
                                    HStack {
                                        Text(document.title)
                                            .font(.subheadline)
                                            .fontWeight(.bold)
                                            .lineLimit(2)
                                        Spacer()
                                        Text("\(document.blocks.count)")
                                            .font(.caption2)
                                            .fontWeight(.black)
                                    }
                                    Text("\(document.kind) • \(document.status) • \(document.source)")
                                        .font(.caption2)
                                        .foregroundStyle(QuipslyStudioTheme.sage)
                                        .lineLimit(2)
                                    if !document.tags.isEmpty {
                                        Text(document.tags.joined(separator: " • "))
                                            .font(.caption2)
                                            .foregroundStyle(QuipslyStudioTheme.lichen)
                                            .lineLimit(2)
                                    }
                                }
                                .padding(10)
                                .frame(maxWidth: .infinity, alignment: .leading)
                                .background(selectedNestDocumentId == document.id ? QuipslyStudioTheme.moss.opacity(0.22) : Color.black.opacity(0.12))
                                .overlay(
                                    RoundedRectangle(cornerRadius: 14, style: .continuous)
                                        .stroke(selectedNestDocumentId == document.id ? QuipslyStudioTheme.moss.opacity(0.65) : Color.white.opacity(0.08), lineWidth: 1)
                                )
                                .clipShape(RoundedRectangle(cornerRadius: 14, style: .continuous))
                            }
                            .buttonStyle(.plain)
                        }
                    }
                }

                if let selectedDocument {
                    VStack(alignment: .leading, spacing: 10) {
                        Text("Selected context")
                            .font(.caption)
                            .fontWeight(.black)
                            .foregroundStyle(QuipslyStudioTheme.honey)
                        Text(selectedDocument.title)
                            .font(.headline)
                            .foregroundStyle(QuipslyStudioTheme.moonMilk)
                        ForEach(selectedDocument.blocks.sorted { $0.sortIndex < $1.sortIndex }) { block in
                            Button {
                                selectedNestDocumentId = selectedDocument.id
                                selectedNestBlockId = block.id
                                lastMediaAction = "Selected Nest block: \(block.role)"
                                updateAgentState()
                            } label: {
                                VStack(alignment: .leading, spacing: 6) {
                                    HStack {
                                        Text(block.role.uppercased())
                                            .font(.caption2)
                                            .fontWeight(.black)
                                            .foregroundStyle(QuipslyStudioTheme.honey)
                                        Spacer()
                                        Text(nestAuthorshipLabel(block.authorship))
                                            .font(.caption2)
                                            .fontWeight(.black)
                                            .foregroundStyle(nestAuthorshipColor(block.authorship))
                                            .padding(.horizontal, 6)
                                            .padding(.vertical, 2)
                                            .background(nestAuthorshipColor(block.authorship).opacity(0.12))
                                            .clipShape(Capsule())
                                        Text(block.reviewStatus)
                                            .font(.caption2)
                                            .foregroundStyle(QuipslyStudioTheme.sage)
                                    }
                                    Text(block.text)
                                        .font(.caption)
                                        .foregroundStyle(QuipslyStudioTheme.moonMilk)
                                        .lineLimit(selectedNestBlockId == block.id ? 12 : 4)
                                    if !block.sourcePath.isEmpty {
                                        Text(block.sourcePath)
                                            .font(.caption2)
                                            .foregroundStyle(QuipslyStudioTheme.sage)
                                            .lineLimit(1)
                                    }
                                    if !block.provenanceNote.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty {
                                        Text(block.provenanceNote)
                                            .font(.caption2)
                                            .foregroundStyle(nestAuthorshipColor(block.authorship))
                                            .lineLimit(2)
                                    }
                                    if selectedNestBlockId == block.id {
                                        VStack(alignment: .leading, spacing: 8) {
                                            HStack(spacing: 8) {
                                                Button("Chapter") {
                                                    updateSelectedNestBlockStructure(
                                                        role: "chapter-marker",
                                                        tags: "chapter,structure,book",
                                                        chapterSlug: block.chapterSlug.isEmpty ? nestSlug(from: block.text, fallback: "chapter") : block.chapterSlug,
                                                        note: "Marked as a Chapter structure block from the native Nest workbench.",
                                                        blockId: block.id.uuidString
                                                    )
                                                }
                                                .buttonStyle(.bordered)

                                                Button("Episode") {
                                                    updateSelectedNestBlockStructure(
                                                        role: "episode-marker",
                                                        tags: "episode,structure,show",
                                                        episodeSlug: block.episodeSlug.isEmpty ? nestSlug(from: block.text, fallback: "episode") : block.episodeSlug,
                                                        note: "Marked as an Episode structure block from the native Nest workbench.",
                                                        blockId: block.id.uuidString
                                                    )
                                                }
                                                .buttonStyle(.bordered)

                                                Button("Writing") {
                                                    updateSelectedNestBlockStructure(
                                                        role: "writing",
                                                        tags: "book,draft,writing",
                                                        note: "Marked as a writing block from the native Nest workbench.",
                                                        blockId: block.id.uuidString
                                                    )
                                                }
                                                .buttonStyle(.bordered)
                                            }
                                            HStack(spacing: 8) {
                                                Button("Reviewed") {
                                                    updateSelectedNestBlockReviewStatus(
                                                        "human-reviewed",
                                                        note: "Marked human-reviewed from the native Nest workbench.",
                                                        blockId: block.id.uuidString
                                                    )
                                                }
                                                .buttonStyle(.bordered)

                                                Button("Canon") {
                                                    updateSelectedNestBlockReviewStatus(
                                                        "canon-approved",
                                                        note: "Marked canon-approved from the native Nest workbench.",
                                                        blockId: block.id.uuidString
                                                    )
                                                }
                                                .buttonStyle(.borderedProminent)

                                                Button("Needs work") {
                                                    updateSelectedNestBlockReviewStatus(
                                                        "needs-human-review",
                                                        note: "Sent back to needs-human-review from the native Nest workbench.",
                                                        blockId: block.id.uuidString
                                                    )
                                                }
                                                .buttonStyle(.bordered)
                                            }
                                        }
                                        .controlSize(.small)
                                    }
                                }
                                .padding(10)
                                .frame(maxWidth: .infinity, alignment: .leading)
                                .background(selectedNestBlockId == block.id ? QuipslyStudioTheme.honey.opacity(0.18) : Color.black.opacity(0.10))
                                .clipShape(RoundedRectangle(cornerRadius: 14, style: .continuous))
                            }
                            .buttonStyle(.plain)
                            if selectedNestBlockId == block.id {
                                selectedNestBlockEditor(block)
                            }
                        }
                    }
                }
            }
            .padding(12)
        }
        .accessibilityIdentifier("quipsly.nest.workbench")
    }

    private var nestWritingReadinessPanel: some View {
        let readiness = nestWritingReadinessPayload()
        let status = readiness["status"] as? String ?? "unknown"
        let authoredBlockCount = readiness["authoredBlockCount"] as? Int ?? 0
        let writingDocumentCount = readiness["writingDocumentCount"] as? Int ?? 0
        let needsReviewCount = readiness["authoredNeedsReviewCount"] as? Int ?? 0
        let humanAuthoredCount = readiness["humanAuthoredBlockCount"] as? Int ?? 0
        let agentAuthoredCount = readiness["agentAuthoredBlockCount"] as? Int ?? 0
        let mixedAuthorshipCount = readiness["mixedAuthorshipBlockCount"] as? Int ?? 0
        let nextAction = readiness["nextAction"] as? String ?? ""
        let statusColor: Color = {
            switch status {
            case "writing-loop-active":
                return QuipslyStudioTheme.moss
            case "drafting-needs-review", "ready-for-first-draft":
                return QuipslyStudioTheme.honey
            default:
                return QuipslyStudioTheme.creek
            }
        }()

        return VStack(alignment: .leading, spacing: 9) {
            HStack(spacing: 8) {
                Image(systemName: "pencil.and.scribble")
                    .foregroundStyle(statusColor)
                VStack(alignment: .leading, spacing: 2) {
                    Text("Living manuscript layer")
                        .font(.caption)
                        .fontWeight(.black)
                        .foregroundStyle(QuipslyStudioTheme.moonMilk)
                    Text(status.replacingOccurrences(of: "-", with: " "))
                        .font(.caption2)
                        .fontWeight(.black)
                        .foregroundStyle(statusColor)
                }
                Spacer()
                Text("\(authoredBlockCount) authored")
                    .font(.caption2)
                    .fontWeight(.black)
                    .foregroundStyle(statusColor)
                    .padding(.horizontal, 7)
                    .padding(.vertical, 4)
                    .background(statusColor.opacity(0.12))
                    .clipShape(Capsule())
            }

            HStack(spacing: 6) {
                miniTruthPill("\(writingDocumentCount)", "draft docs", QuipslyStudioTheme.creek)
                miniTruthPill("\(needsReviewCount)", "review", QuipslyStudioTheme.honey)
                miniTruthPill("\(readiness["sourceContextBlockCount"] as? Int ?? 0)", "source ctx", QuipslyStudioTheme.sage)
            }

            HStack(spacing: 6) {
                miniTruthPill("\(humanAuthoredCount)", "human", QuipslyStudioTheme.moss)
                miniTruthPill("\(agentAuthoredCount)", "agent", QuipslyStudioTheme.creek)
                miniTruthPill("\(mixedAuthorshipCount)", "mixed", QuipslyStudioTheme.lichen)
            }

            VStack(alignment: .leading, spacing: 4) {
                Label("Creative partner rule", systemImage: "person.2.wave.2.fill")
                    .font(.caption2)
                    .fontWeight(.black)
                    .foregroundStyle(QuipslyStudioTheme.creek)
                Text("Codex and Quipslys can create serious first-pass manuscript material. Agent-authored does not mean placeholder; review state and provenance tell us what it is.")
                    .font(.caption2)
