                        .foregroundStyle(nestWritingNextActionColor(row["tone"] ?? ""))
                        .frame(width: 18)
                    VStack(alignment: .leading, spacing: 2) {
                        Text(row["label"] ?? "Next action")
                            .font(.caption)
                            .fontWeight(.bold)
                            .foregroundStyle(QuipslyStudioTheme.moonMilk)
                        Text(row["detail"] ?? "")
                            .font(.caption2)
                            .foregroundStyle(QuipslyStudioTheme.sage)
                            .fixedSize(horizontal: false, vertical: true)
                    }
                    Spacer()
                    Button(row["button"] ?? "Do") {
                        performNestWritingNextAction(row)
                    }
                    .buttonStyle(.bordered)
                    .controlSize(.mini)
                    .help(row["command"] ?? "Use the native Nest workbench action.")
                }
                .padding(8)
                .background(nestWritingNextActionColor(row["tone"] ?? "").opacity(0.08))
                .clipShape(RoundedRectangle(cornerRadius: 12, style: .continuous))
            }
        }
        .padding(12)
        .background(QuipslyStudioTheme.lichen.opacity(0.09))
        .overlay(
            RoundedRectangle(cornerRadius: 16, style: .continuous)
                .stroke(QuipslyStudioTheme.lichen.opacity(0.18), lineWidth: 1)
        )
        .clipShape(RoundedRectangle(cornerRadius: 16, style: .continuous))
        .accessibilityIdentifier("quipsly.nest.writingNextActions")
    }

    private var nestWritingPacketPanel: some View {
        let color = nestWritingPacketStatusColor
        let hasPath = !nestWritingPacketOutputPath.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty
        let readiness = nestWritingReadinessPayload()
        let authoredCount = readiness["authoredBlockCount"] as? Int ?? 0
        let sourceCount = readiness["sourceContextBlockCount"] as? Int ?? 0
        let reviewCount = readiness["authoredNeedsReviewCount"] as? Int ?? 0

        return VStack(alignment: .leading, spacing: 9) {
            HStack(alignment: .top, spacing: 8) {
                Image(systemName: nestWritingPacketStatusIcon)
                    .foregroundStyle(color)
                    .frame(width: 22)
                VStack(alignment: .leading, spacing: 2) {
                    Text(nestWritingPacketStatusLabel)
                        .font(.caption)
                        .fontWeight(.black)
                        .foregroundStyle(color)
                    Text(nestWritingPacketStatusDetail)
                        .font(.caption2)
                        .foregroundStyle(QuipslyStudioTheme.sage)
                        .fixedSize(horizontal: false, vertical: true)
                }
                Spacer()
            }

            HStack(spacing: 6) {
                miniTruthPill("\(authoredCount)", "authored", QuipslyStudioTheme.creek)
                miniTruthPill("\(sourceCount)", "source ctx", QuipslyStudioTheme.moss)
                miniTruthPill("\(reviewCount)", "review", QuipslyStudioTheme.honey)
            }

            Text("Portable manuscript field note: authored blocks, source-context summaries, review queue, provenance, and safe next actions. It does not canonize drafts.")
                .font(.caption2)
                .foregroundStyle(QuipslyStudioTheme.moonMilk.opacity(0.86))
                .fixedSize(horizontal: false, vertical: true)

            HStack(spacing: 7) {
                Button {
                    generateNestWritingPacketForAgent(directoryPath: nil, basename: nil)
                } label: {
                    Label(nestWritingPacketStatus == "generating" ? "Writing" : "Generate writing packet", systemImage: "doc.text.magnifyingglass")
                }
                .buttonStyle(.borderedProminent)
                .controlSize(.small)
                .disabled(nestWritingPacketStatus == "generating")
                .help("Write a JSON handoff packet for the current Nest writing layer.")

                #if os(macOS)
                Button {
                    revealNestWritingPacketFile()
                } label: {
                    Label("Reveal", systemImage: "finder")
                }
                .buttonStyle(.bordered)
                .controlSize(.small)
                .disabled(!hasPath)
                .help("Reveal the generated Nest writing packet in Finder.")
                #endif

                Button {
                    copyPublishReceiptText(
                        nestWritingPacketOutputPath,
                        successMessage: "Copied Nest writing packet path"
                    )
                } label: {
                    Label("Copy path", systemImage: "doc.on.doc")
                }
                .buttonStyle(.bordered)
                .controlSize(.small)
                .disabled(!hasPath)
                .help("Copy the generated Nest writing packet path for another agent or collaborator.")
            }
        }
        .padding(12)
        .background(color.opacity(0.09))
        .overlay(
            RoundedRectangle(cornerRadius: 16, style: .continuous)
                .stroke(color.opacity(0.20), lineWidth: 1)
        )
        .clipShape(RoundedRectangle(cornerRadius: 16, style: .continuous))
        .accessibilityIdentifier("quipsly.nest.writingPacket")
    }

    private var nestWritingPacketStatusColor: Color {
        switch nestWritingPacketStatus {
        case "generated":
            return QuipslyStudioTheme.moss
        case "generating":
            return QuipslyStudioTheme.creek
        case "failed":
            return QuipslyStudioTheme.clay
        default:
            return QuipslyStudioTheme.sage
        }
    }

    private var nestWritingPacketStatusIcon: String {
        switch nestWritingPacketStatus {
        case "generated":
            return "checkmark.seal.fill"
        case "generating":
            return "arrow.triangle.2.circlepath"
        case "failed":
            return "exclamationmark.triangle.fill"
        default:
            return "doc.text.magnifyingglass"
        }
    }

    private var nestWritingPacketStatusLabel: String {
        switch nestWritingPacketStatus {
        case "generated":
            return "NEST WRITING PACKET READY"
        case "generating":
            return "WRITING NEST PACKET"
        case "failed":
            return "NEST WRITING PACKET FAILED"
        default:
            return "NEST WRITING HANDOFF"
        }
    }

    private var nestWritingPacketStatusDetail: String {
        if !nestWritingPacketErrorMessage.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty {
            return nestWritingPacketErrorMessage
        }
        if !nestWritingPacketOutputPath.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty {
            return "Packet file: \(nestWritingPacketOutputPath)"
        }
        return "Generate a portable packet for authored drafts, source scaffolding, review queue, and agent-safe writing actions."
    }

    private func nestWritingNextActionColor(_ tone: String) -> Color {
        switch tone {
        case "review":
            return QuipslyStudioTheme.honey
        case "write":
            return QuipslyStudioTheme.creek
        case "source":
            return QuipslyStudioTheme.moss
        case "structure":
            return QuipslyStudioTheme.lichen
        default:
            return QuipslyStudioTheme.sage
        }
    }

    private func nestWritingNextActionIcon(_ kind: String) -> String {
        switch kind {
        case "start-writing":
            return "doc.badge.plus"
        case "seed-context":
            return "tray.and.arrow.down.fill"
        case "select-review-block":
            return "checklist"
        case "draft-next":
            return "pencil.and.scribble"
        case "create-structure":
            return "point.3.connected.trianglepath.dotted"
        default:
            return "arrow.right.circle"
        }
    }

    private func miniTruthPill(_ value: String, _ label: String, _ color: Color) -> some View {
