    private func selectedNestBlockEditor(_ block: NestBlock) -> some View {
        VStack(alignment: .leading, spacing: 8) {
            HStack {
                Label("Revise selected block", systemImage: "square.and.pencil")
                    .font(.caption)
                    .fontWeight(.black)
                    .foregroundStyle(QuipslyStudioTheme.moonMilk)
                Spacer()
                Text(block.reviewStatus == "canon-approved" ? "canon will become draft" : "safe draft edit")
                    .font(.caption2)
                    .fontWeight(.black)
                    .foregroundStyle(block.reviewStatus == "canon-approved" ? QuipslyStudioTheme.clay : QuipslyStudioTheme.sage)
            }

            HStack(spacing: 6) {
                Text(nestAuthorshipLabel(block.authorship))
                    .font(.caption2)
                    .fontWeight(.black)
                    .foregroundStyle(nestAuthorshipColor(block.authorship))
                    .padding(.horizontal, 7)
                    .padding(.vertical, 4)
                    .background(nestAuthorshipColor(block.authorship).opacity(0.12))
                    .clipShape(Capsule())
                Text(block.reviewStatus.replacingOccurrences(of: "-", with: " "))
                    .font(.caption2)
                    .fontWeight(.black)
                    .foregroundStyle(QuipslyStudioTheme.honey)
                    .padding(.horizontal, 7)
                    .padding(.vertical, 4)
                    .background(QuipslyStudioTheme.honey.opacity(0.10))
                    .clipShape(Capsule())
                Spacer()
            }

            if !block.provenanceNote.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty {
                Text(block.provenanceNote)
                    .font(.caption2)
                    .foregroundStyle(QuipslyStudioTheme.sage)
                    .lineLimit(3)
                    .fixedSize(horizontal: false, vertical: true)
            }

            if nestEditingBlockId == block.id {
                TextEditor(text: $nestEditingBody)
                    .font(.body)
                    .frame(minHeight: 150)
                    .padding(8)
                    .background(Color.black.opacity(0.16))
                    .clipShape(RoundedRectangle(cornerRadius: 14, style: .continuous))
                    .accessibilityIdentifier("quipsly.nest.selectedBlockEditor.body")

                TextField("Revision note", text: $nestEditingNote)
                    .textFieldStyle(.roundedBorder)
                    .accessibilityIdentifier("quipsly.nest.selectedBlockEditor.note")

                HStack(spacing: 8) {
                    Button {
                        saveNestBlockEdit(blockId: block.id.uuidString)
                    } label: {
                        Label("Save revision", systemImage: "checkmark.circle.fill")
                    }
                    .buttonStyle(.borderedProminent)
                    .disabled(nestEditingBody.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty)

                    Button {
                        cancelNestBlockEdit()
                    } label: {
                        Label("Cancel", systemImage: "xmark.circle")
                    }
                    .buttonStyle(.bordered)
                }
                .controlSize(.small)
            } else {
                Button {
                    beginNestBlockEdit(block)
                } label: {
                    Label("Edit this block", systemImage: "pencil")
                        .frame(maxWidth: .infinity)
                }
                .buttonStyle(.bordered)
                .controlSize(.small)
                .help("Load this block into a real editable field. Saving preserves provenance and autosaves the session.")
            }
        }
        .padding(10)
        .background(QuipslyStudioTheme.creek.opacity(0.10))
        .overlay(
            RoundedRectangle(cornerRadius: 14, style: .continuous)
                .stroke(QuipslyStudioTheme.creek.opacity(0.18), lineWidth: 1)
        )
        .clipShape(RoundedRectangle(cornerRadius: 14, style: .continuous))
        .accessibilityIdentifier("quipsly.nest.selectedBlockEditor")
    }

    private var nestOutlinePanel: some View {
        let outlineEntries = nestOutlineEntries()

        return VStack(alignment: .leading, spacing: 9) {
            HStack {
                Label("Document outline", systemImage: "list.bullet.indent")
                    .font(.caption)
                    .fontWeight(.black)
                    .foregroundStyle(QuipslyStudioTheme.moonMilk)
                Spacer()
                Text("\(outlineEntries.count)")
                    .font(.caption2)
                    .fontWeight(.black)
                    .foregroundStyle(QuipslyStudioTheme.sage)
            }

            Text("Derived from Chapter/Episode blocks. No separate outline truth.")
                .font(.caption2)
                .foregroundStyle(QuipslyStudioTheme.sage)
                .fixedSize(horizontal: false, vertical: true)

            if outlineEntries.isEmpty {
                Text("Mark any block as Chapter or Episode and it will appear here.")
                    .font(.caption)
                    .foregroundStyle(QuipslyStudioTheme.sage)
                    .padding(10)
                    .frame(maxWidth: .infinity, alignment: .leading)
                    .background(Color.black.opacity(0.12))
                    .clipShape(RoundedRectangle(cornerRadius: 13, style: .continuous))
            } else {
                ForEach(outlineEntries) { entry in
                    Button {
                        selectedNestDocumentId = entry.documentId
                        selectedNestBlockId = entry.id
                        lastMediaAction = "Selected outline \(entry.kind): \(entry.title)"
                        updateAgentState()
                    } label: {
                        HStack(alignment: .top, spacing: 8) {
                            Image(systemName: entry.kind == "chapter" ? "book.closed.fill" : "play.rectangle.fill")
                                .font(.caption)
                                .foregroundStyle(entry.kind == "chapter" ? QuipslyStudioTheme.moss : QuipslyStudioTheme.honey)
                                .frame(width: 18)
                                .padding(.top, 2)
                            VStack(alignment: .leading, spacing: 4) {
                                Text(entry.title)
                                    .font(.caption)
                                    .fontWeight(.bold)
                                    .foregroundStyle(QuipslyStudioTheme.moonMilk)
                                    .lineLimit(2)
                                HStack(spacing: 6) {
                                    Text(entry.kind.uppercased())
                                        .font(.caption2)
                                        .fontWeight(.black)
                                        .foregroundStyle(entry.kind == "chapter" ? QuipslyStudioTheme.moss : QuipslyStudioTheme.honey)
                                    Text(nestAuthorshipLabel(entry.authorship))
                                        .font(.caption2)
                                        .fontWeight(.black)
                                        .foregroundStyle(nestAuthorshipColor(entry.authorship))
                                    Text(entry.reviewStatus)
                                        .font(.caption2)
                                        .foregroundStyle(QuipslyStudioTheme.sage)
                                        .lineLimit(1)
                                }
                                if entry.kind == "episode", !entry.chapterTitle.isEmpty {
                                    Text("under \(entry.chapterTitle)")
                                        .font(.caption2)
                                        .foregroundStyle(QuipslyStudioTheme.lichen)
                                        .lineLimit(1)
                                }
                            }
                            Spacer()
                        }
                        .padding(9)
                        .frame(maxWidth: .infinity, alignment: .leading)
                        .background(selectedNestBlockId == entry.id ? QuipslyStudioTheme.honey.opacity(0.18) : Color.black.opacity(0.10))
                        .overlay(
                            RoundedRectangle(cornerRadius: 13, style: .continuous)
                                .stroke(selectedNestBlockId == entry.id ? QuipslyStudioTheme.honey.opacity(0.55) : Color.white.opacity(0.07), lineWidth: 1)
                        )
                        .clipShape(RoundedRectangle(cornerRadius: 13, style: .continuous))
                    }
                    .buttonStyle(.plain)
                    .accessibilityLabel("\(entry.kind) outline entry \(entry.title), \(entry.reviewStatus), \(nestAuthorshipLabel(entry.authorship))")
                }
            }
        }
        .padding(12)
        .background(QuipslyStudioTheme.fern.opacity(0.10))
        .overlay(
            RoundedRectangle(cornerRadius: 16, style: .continuous)
                .stroke(QuipslyStudioTheme.fern.opacity(0.18), lineWidth: 1)
        )
        .clipShape(RoundedRectangle(cornerRadius: 16, style: .continuous))
        .accessibilityIdentifier("quipsly.nest.outline")
    }

    private var publishWorkbenchSidebar: some View {
        let sequence = projectStore.activeSequence
        let records = sequence?.publishReceipts ?? []
        let readyCount = records.filter { publishRecordArtifactReady($0) && publishRecordCopyReady($0) }.count
        let receiptSummary = publicationReceiptCompletionSummary(for: sequence)
        let captured = receiptSummary["receiptCapturedCount"] as? Int ?? 0
        let remaining = receiptSummary["receiptRemainingCount"] as? Int ?? records.count
        let publicationComplete = receiptSummary["publicationComplete"] as? Bool ?? false
        let releaseFolderPath = currentPublicationReleaseFolderPath()
        let nextAction = records.isEmpty
            ? "Run Full prep when the edit is ready. Quipsly creates artifacts, platform ledgers, handoff packets, and a receipt checklist without claiming anything is published."
            : publishLedgerNextActionText(records: records)

        return ScrollView {
            VStack(alignment: .leading, spacing: 10) {
                HStack(alignment: .top, spacing: 9) {
                    Image(systemName: publicationComplete ? "checkmark.seal.fill" : "paperplane.fill")
                        .font(.headline)
                        .foregroundStyle(publicationComplete ? QuipslyStudioTheme.moss : QuipslyStudioTheme.creek)
                        .frame(width: 30, height: 30)
                        .background((publicationComplete ? QuipslyStudioTheme.moss : QuipslyStudioTheme.creek).opacity(0.14))
                        .clipShape(Circle())

                    VStack(alignment: .leading, spacing: 2) {
                        Text("Production Cockpit")
                            .font(.caption)
                            .fontWeight(.black)
                        Text("Prepare, approve, post, and prove: 16:9 episode, 9:16 shorts, podcast audio, and receipt truth all stay tied to this Episode Spine.")
                            .font(.caption2)
                            .foregroundStyle(.secondary)
                            .fixedSize(horizontal: false, vertical: true)
                    }
                }

                HStack(spacing: 6) {
                    publishStatPill("records", records.count, records.isEmpty ? QuipslyStudioTheme.honey : QuipslyStudioTheme.moss)
                    publishStatPill("ready", readyCount, readyCount > 0 ? QuipslyStudioTheme.moss : QuipslyStudioTheme.honey)
                    publishStatPill("receipts", captured, publicationComplete ? QuipslyStudioTheme.moss : QuipslyStudioTheme.honey)
                    publishStatPill("missing", remaining, remaining == 0 ? QuipslyStudioTheme.moss : QuipslyStudioTheme.clay)
                }

                publishShortsPlatformCopyPanel(sequence: sequence)
                episodeSpineBridgePanel(sequence: sequence)
                towerNestWritingContextPanel(sequence: sequence)
                verticalSlicePacketPanel(sequence: sequence)
                publishProductionStateLadder(
                    sequenceLoaded: sequence != nil,
                    ledgerRecordCount: records.count,
                    preparedRecordCount: readyCount,
                    receiptCapturedCount: captured,
                    receiptRemainingCount: remaining,
                    publicationComplete: publicationComplete
                )
                publishReceiptCockpitPanel(sequence: sequence, records: records)
                publishSafeNextActionQueue(sequence: sequence, records: records)
                publishPlatformDestinationMatrix(sequence: sequence, records: records)
                publishDeliveryPathPrimer(sequence: sequence, records: records)
                publishOutputReadinessDeck(records: records, sequenceLoaded: sequence != nil)
                publishArtifactTruthPanel(sequenceLoaded: sequence != nil)
                publishTestFlightReadinessPanel(sequence: sequence, records: records)
                publishCodexEditorHandoffPanel(sequence: sequence, records: records)

                Text(nextAction)
                    .font(.caption2)
                    .foregroundStyle(.secondary)
                    .fixedSize(horizontal: false, vertical: true)
                    .padding(8)
                    .background(QuipslyStudioTheme.panelLift.opacity(0.18))
                    .clipShape(RoundedRectangle(cornerRadius: 12, style: .continuous))

                releaseCockpitPanel(sequence: sequence, records: records)
                platformProofChecklistPanel(records: records)

                productionCommandCenterPanel

                LazyVGrid(columns: [GridItem(.adaptive(minimum: 126), spacing: 7)], spacing: 7) {
                    Button {
                        prepareFullReleaseForHuman()
                    } label: {
                        Label("Full prep", systemImage: "shippingbox.and.arrow.backward")
                            .frame(maxWidth: .infinity)
                    }
                    .buttonStyle(.borderedProminent)
                    .controlSize(.small)
                    .disabled(sequence == nil || exportEngine.isExporting)
                    .help("Generate release artifacts, delivery packet, publish ledger, upload bundle, social queue, podcast handoff, and cockpit.")

                    Button {
                        generatePublishLedgerFromCurrentDelivery()
                    } label: {
                        Label(records.isEmpty ? "Ledger" : "Refresh", systemImage: "wand.and.stars")
                            .frame(maxWidth: .infinity)
                    }
                    .controlSize(.small)
                    .disabled(sequence == nil)
                    .help("Create or refresh platform publish records from exported artifacts.")

                    Button {
                        generatePublicationCockpitForAgent(directoryPath: nil, basename: nil)
                    } label: {
                        Label(publicationCockpitStatus == "generating" ? "Writing" : "Cockpit", systemImage: "rectangle.3.group")
                            .frame(maxWidth: .infinity)
                    }
                    .controlSize(.small)
                    .disabled(records.isEmpty || publicationCockpitStatus == "generating")
                    .help("Write the human/Codex publication cockpit handoff.")

                    Button {
                        copyPublicationMissionControlJSON()
                    } label: {
                        Label("Copy mission", systemImage: "doc.on.doc")
                            .frame(maxWidth: .infinity)
                    }
                    .controlSize(.small)
                    .disabled(sequence == nil)
                    .help("Copy read-only publication mission control JSON for Codex, Mako, or another agent.")

                    Button {
                        generateSocialPublicationQueueForAgent(directoryPath: nil, basename: nil)
                    } label: {
                        Label("Social queue", systemImage: "square.grid.3x3.square")
                            .frame(maxWidth: .infinity)
                    }
                    .controlSize(.small)
                    .disabled(sequence == nil || socialPublicationQueueStatus == "generating")
                    .help("Prepare the manual-upload queue for YouTube Shorts, Instagram, Facebook, and LinkedIn.")

                    Button {
                        generatePodcastReadyPacketForCurrentManifest()
                    } label: {
                        Label("Podcast", systemImage: "dot.radiowaves.left.and.right")
                            .frame(maxWidth: .infinity)
                    }
                    .controlSize(.small)
                    .disabled(podcastPacketOutputPath.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty || podcastReadyPacketStatus == "generating")
                    .help("Create the Spotify/Apple handoff packet from the podcast manifest.")

                    #if os(macOS)
                    Button {
                        revealPublicationArtifactPath(releaseFolderPath, label: "current release folder")
                    } label: {
                        Label("Reveal", systemImage: "folder")
                            .frame(maxWidth: .infinity)
                    }
                    .controlSize(.small)
                    .disabled(releaseFolderPath.isEmpty || !FileManager.default.fileExists(atPath: releaseFolderPath))
                    .help("Reveal the best available local release handoff folder.")
                    #endif

                    Button {
                        copyMissingPublicationReceipts(records)
                    } label: {
                        Label("Receipts", systemImage: "exclamationmark.bubble")
                            .frame(maxWidth: .infinity)
                    }
                    .controlSize(.small)
                    .disabled(records.isEmpty)
                    .help("Copy missing publication receipts and exact capture commands. This does not mark anything published.")
                }

                publishWorkbenchLaneCard(
                    title: "16:9 episode",
                    destination: "YouTube + Patreon",
                    record: records.first { $0.deliveryLaneId == "episode-16x9-master" },
                    missingText: "Needs 16:9 master / publish ledger"
                )

                publishWorkbenchLaneCard(
                    title: "9:16 shorts",
                    destination: "YouTube Shorts, Instagram, Facebook, LinkedIn",
                    record: records.first { $0.deliveryLaneId == "social-short-clips" || $0.deliveryLaneId.hasPrefix("social-short-clips/") },
                    missingText: "Needs reviewed social queue"
                )

                publishWorkbenchLaneCard(
                    title: "Podcast audio",
                    destination: "Spotify + Apple Podcasts",
                    record: records.first { $0.deliveryLaneId == "podcast-audio-master" },
                    missingText: "Needs podcast audio packet"
                )

                if publicationCockpitStatus != "idle" || !publicationCockpitOutputPath.isEmpty || !publicationCockpitErrorMessage.isEmpty {
                    publicationCockpitStatusRow
                }
                if publishUploadBundleStatus != "idle" || !publishUploadBundleOutputPath.isEmpty || !publishUploadBundleErrorMessage.isEmpty {
                    publishUploadBundleStatusRow
                }
                if socialPublicationQueueStatus != "idle" || !socialPublicationQueueOutputPath.isEmpty || !socialPublicationQueueErrorMessage.isEmpty {
                    socialPublicationQueueStatusRow
                }
                if podcastReadyPacketStatus != "idle" || !podcastReadyPacketOutputPath.isEmpty || !podcastReadyPacketErrorMessage.isEmpty {
                    podcastReadyPacketStatusRow
                }

                Text("Rule: prepared is not posted, posted is not proved. Publication becomes true only when receipt URLs or provider IDs are captured.")
                    .font(.caption2)
                    .foregroundStyle(.secondary)
                    .fixedSize(horizontal: false, vertical: true)
            }
            .padding(10)
        }
        .accessibilityIdentifier("quipsly.workbench.ship")
    }

    private enum ShortPublicationReadinessBucket: String, CaseIterable {
        case ready
        case refine
        case test
        case other

        var shortLabel: String {
            switch self {
            case .ready: return "ready"
            case .refine: return "refine"
            case .test: return "test"
            case .other: return "other"
            }
        }

        var groupTitle: String {
            switch self {
            case .ready: return "Ready / human-review candidates"
            case .refine: return "Needs refinement before posting"
            case .test: return "Test or proof-only candidates"
            case .other: return "Other draft candidates"
            }
        }

        var emptyText: String {
            switch self {
            case .ready: return "No shorts are marked Keep or ready yet."
            case .refine: return "No refinement candidates are waiting."
            case .test: return "No test-only shorts are queued."
            case .other: return ""
            }
        }

        var tint: Color {
            switch self {
            case .ready: return QuipslyStudioTheme.moss
            case .refine: return QuipslyStudioTheme.honey
            case .test: return QuipslyStudioTheme.creek
            case .other: return QuipslyStudioTheme.clay
            }
        }
    }

    @ViewBuilder
    private func publishShortsPlatformCopyPanel(sequence: MediaSequence?) -> some View {
        if let sequence {
            let queue = sequence.shortClipQueue.sorted {
                sequenceStartTime(for: $0, in: sequence) < sequenceStartTime(for: $1, in: sequence)
            }
            let ready = queue.filter { publishShortPlatformBucket(for: $0) == .ready }
            let refine = queue.filter { publishShortPlatformBucket(for: $0) == .refine }
            let test = queue.filter { publishShortPlatformBucket(for: $0) == .test }
            let other = queue.filter {
                let bucket = publishShortPlatformBucket(for: $0)
                return bucket == .other
            }

            VStack(alignment: .leading, spacing: 10) {
                QuipslySectionHeader(
                    eyebrow: "Shorts Platform Copy",
                    title: "Turn chosen moments into posts",
                    detail: "Short recipes stay tied to the Episode Spine. Copy drafts are first-pass human-review material, not proof that anything has been uploaded.",
                    systemImage: "rectangle.portrait.on.rectangle.portrait.angled",
                    tint: QuipslyStudioTheme.moss,
                    compact: true
                )

                LazyVGrid(columns: [GridItem(.adaptive(minimum: 70), spacing: 6)], spacing: 6) {
                    publishStatPill(ShortPublicationReadinessBucket.ready.shortLabel, ready.count, ready.isEmpty ? QuipslyStudioTheme.sage : ShortPublicationReadinessBucket.ready.tint)
                    publishStatPill(ShortPublicationReadinessBucket.refine.shortLabel, refine.count, refine.isEmpty ? QuipslyStudioTheme.sage : ShortPublicationReadinessBucket.refine.tint)
                    publishStatPill(ShortPublicationReadinessBucket.test.shortLabel, test.count, test.isEmpty ? QuipslyStudioTheme.sage : ShortPublicationReadinessBucket.test.tint)
                    publishStatPill(ShortPublicationReadinessBucket.other.shortLabel, other.count, other.isEmpty ? QuipslyStudioTheme.sage : ShortPublicationReadinessBucket.other.tint)
                }

                if queue.isEmpty {
                    Text("No short recipes yet. Create or import 9:16 pull-outs in Studio, then Ship will show platform copy, receipt boundaries, and upload readiness here.")
                        .font(.caption2)
                        .foregroundStyle(.secondary)
                        .fixedSize(horizontal: false, vertical: true)
                        .padding(8)
                        .background(QuipslyStudioTheme.panelLift.opacity(0.16))
                        .clipShape(RoundedRectangle(cornerRadius: 12, style: .continuous))
                } else {
                    publishShortsPlatformCopyGroup(
                        title: ShortPublicationReadinessBucket.ready.groupTitle,
                        clips: ready,
                        sequence: sequence,
                        bucket: .ready
                    )
                    publishShortsPlatformCopyGroup(
                        title: ShortPublicationReadinessBucket.refine.groupTitle,
                        clips: refine,
                        sequence: sequence,
                        bucket: .refine
                    )
                    publishShortsPlatformCopyGroup(
                        title: ShortPublicationReadinessBucket.test.groupTitle,
                        clips: test,
                        sequence: sequence,
                        bucket: .test
                    )
                    if !other.isEmpty {
                        publishShortsPlatformCopyGroup(
                            title: ShortPublicationReadinessBucket.other.groupTitle,
                            clips: other,
                            sequence: sequence,
                            bucket: .other
                        )
                    }
                }

                Text("Receipt boundary: this panel prepares captions and post copy. Publication is true only after a platform URL, scheduled URL, or provider receipt is captured back into Quipsly.")
                    .font(.caption2)
                    .foregroundStyle(.secondary)
                    .fixedSize(horizontal: false, vertical: true)
                    .padding(8)
                    .background(QuipslyStudioTheme.honey.opacity(0.08))
                    .clipShape(RoundedRectangle(cornerRadius: 12, style: .continuous))
            }
            .padding(9)
            .background(QuipslyStudioTheme.cardGradient)
            .overlay(
                RoundedRectangle(cornerRadius: 16, style: .continuous)
                    .stroke(QuipslyStudioTheme.moss.opacity(0.20), lineWidth: 1)
            )
            .clipShape(RoundedRectangle(cornerRadius: 16, style: .continuous))
            .accessibilityIdentifier("quipsly.publish.shortsPlatformCopy")
        } else {
            VStack(alignment: .leading, spacing: 8) {
                QuipslySectionHeader(
                    eyebrow: "Shorts Platform Copy",
                    title: "Load an episode to prepare posts",
                    detail: "Ship can show short captions, platform copy, and receipt boundaries once an Episode Spine is active.",
                    systemImage: "rectangle.portrait.slash",
                    tint: QuipslyStudioTheme.sage,
                    compact: true
                )
            }
            .padding(9)
            .background(QuipslyStudioTheme.cardGradient)
            .clipShape(RoundedRectangle(cornerRadius: 16, style: .continuous))
            .accessibilityIdentifier("quipsly.publish.shortsPlatformCopy.empty")
        }
    }

