        let readiness = publishShortTowerReadiness(for: clip)

        return VStack(alignment: .leading, spacing: 7) {
            HStack(alignment: .top, spacing: 7) {
                Image(systemName: readiness.icon)
                    .foregroundStyle(readiness.color)
                    .frame(width: 18)
                VStack(alignment: .leading, spacing: 2) {
                    Text(clip.title.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty ? "Untitled short" : clip.title)
                        .font(.caption)
                        .fontWeight(.black)
                        .lineLimit(2)
                    Text(String(format: "sequence %.2fs -> %.2fs · %.1fs", sequenceStart, sequenceEnd, max(0, clip.duration)))
                        .font(.caption2.monospacedDigit())
                        .foregroundStyle(.secondary)
                }
                Spacer()
                Text(clip.reviewStatus.isEmpty ? "DRAFT" : clip.reviewStatus.uppercased())
                    .font(.caption2)
                    .fontWeight(.black)
                    .foregroundStyle(shortStatusColor(clip.reviewStatus))
                    .padding(.horizontal, 6)
                    .padding(.vertical, 3)
                    .background(shortStatusColor(clip.reviewStatus).opacity(0.14))
                    .clipShape(Capsule())
            }

            Text(readiness.text)
                .font(.caption2)
                .foregroundStyle(readiness.color)
                .fixedSize(horizontal: false, vertical: true)

            VStack(alignment: .leading, spacing: 3) {
                Text("Hook")
                    .font(.caption2)
                    .fontWeight(.black)
                    .foregroundStyle(tint)
                Text(hook)
                    .font(.caption2)
                    .foregroundStyle(QuipslyStudioTheme.moonMilk.opacity(0.82))
                    .lineLimit(3)
            }

            ForEach(visiblePresets) { preset in
                let title = socialShortPublishTitle(clip: clip, preset: preset)
                let description = socialShortPublishDescription(clip: clip, preset: preset, sequence: sequence)
                VStack(alignment: .leading, spacing: 2) {
                    Text(preset.platform.uppercased())
                        .font(.caption2)
                        .fontWeight(.black)
                        .foregroundStyle(QuipslyStudioTheme.honey)
                    Text(title)
                        .font(.caption2)
                        .fontWeight(.semibold)
                        .lineLimit(1)
                    Text(description)
                        .font(.caption2)
                        .foregroundStyle(.secondary)
                        .lineLimit(3)
                }
                .padding(7)
                .background(Color.black.opacity(0.14))
                .clipShape(RoundedRectangle(cornerRadius: 10, style: .continuous))
            }

            HStack(spacing: 6) {
                Button {
                    selectShortClipCandidate(clip)
                    leftWorkbenchMode = .shorts
                    updateAgentState()
                } label: {
                    Label("Review in Shorts", systemImage: "rectangle.stack.fill")
                        .frame(maxWidth: .infinity)
                }
                .buttonStyle(.borderedProminent)
                .controlSize(.small)
                .tint(tint)
                .help("Select this short recipe in the Shorts workbench. This does not publish or mutate source media.")
                .accessibilityIdentifier("quipsly.publish.shortsPlatformCopy.reviewInShorts.\(clip.id.uuidString)")

                Button {
                    selectShortClipCandidate(clip)
                    previewSelectedShortClip(play: false)
                } label: {
                    Label("Cue", systemImage: "scope")
                }
                .buttonStyle(.bordered)
                .controlSize(.small)
