                .stroke(tint.opacity(0.18), lineWidth: 1)
        )
        .clipShape(RoundedRectangle(cornerRadius: 13, style: .continuous))
    }

    private func publishShortPlatformBucket(for clip: ShortClipCandidate) -> ShortPublicationReadinessBucket {
        let status = clip.reviewStatus.trimmingCharacters(in: .whitespacesAndNewlines).lowercased()
        let combined = [
            clip.title,
            clip.status,
            clip.reviewStatus,
            clip.exportStatus,
            clip.notes
        ].joined(separator: " ").lowercased()

        if combined.contains("test-only") || combined.contains("smoke") || combined.contains("debug") || combined.contains("proof-only") {
            return .test
        }
        if status == "keep" || status == "kept" || status.contains("ready") || status.contains("approved") {
            return .ready
        }
        if status == "refine" || status == "revise" || status.contains("review") || status == "draft" || status == "queued" || status.isEmpty {
            return .refine
        }
        return .other
    }

    private func publishShortTowerReadiness(for clip: ShortClipCandidate) -> (text: String, color: Color, icon: String) {
        let bucket = publishShortPlatformBucket(for: clip)
        let exportPath = lastExportedShortPath(for: clip)
        let exportExists = exportPath.map { FileManager.default.fileExists(atPath: $0) } ?? false

        if bucket == .ready && exportExists {
            return ("Tower readiness: exported derivative exists. Review once, then queue for manual upload and receipt capture.", QuipslyStudioTheme.moss, "checkmark.seal.fill")
        }
        if bucket == .ready {
            return ("Tower readiness: copy is promising, but this short still needs a 9:16 export before upload.", QuipslyStudioTheme.honey, "square.and.arrow.up")
        }
        if bucket == .test {
            return ("Tower readiness: proof/test material. Useful for learning the workflow, not publication.", QuipslyStudioTheme.creek, "testtube.2")
        }
        if bucket == .refine {
            return ("Tower readiness: refine the edit, caption, or hook before this becomes upload work.", QuipslyStudioTheme.honey, "slider.horizontal.3")
        }
        return ("Tower readiness: preserved as context. Do not post until a human explicitly promotes it.", QuipslyStudioTheme.clay, "exclamationmark.triangle.fill")
    }

    private func publishShortHook(for clip: ShortClipCandidate) -> String {
        let hook = clip.hookText.trimmingCharacters(in: .whitespacesAndNewlines)
        if !hook.isEmpty {
            return hook
        }
        let overlay = clip.primaryOverlayText.trimmingCharacters(in: .whitespacesAndNewlines)
        if !overlay.isEmpty {
            return overlay
        }
        let caption = clip.captionDraft
            .replacingOccurrences(of: "Rough transcript:", with: "")
            .trimmingCharacters(in: .whitespacesAndNewlines)
        if !caption.isEmpty {
            return caption
        }
        let title = clip.title.trimmingCharacters(in: .whitespacesAndNewlines)
        return title.isEmpty ? "Needs hook review." : title
    }

