    private func publishDeliveryPathJSONString(sequence: MediaSequence?, records: [PublishReceiptRecord]) -> String {
        let payload: [String: Any] = [
            "payloadVersion": 1,
            "generatedAt": ISO8601DateFormatter().string(from: Date()),
            "truth": "Delivery path reports artifact readiness, approval intent, posting state, and publication proof separately. Preparing artifacts does not claim publication.",
            "activeSequenceLoaded": sequence != nil,
            "sequence": [
                "title": sequence?.title ?? "",
                "durationSeconds": sequence?.duration ?? 0,
                "laneCount": sequence?.lanes.count ?? 0,
                "shortRecipeCount": sequence?.shortClipQueue.count ?? 0
            ],
            "outputs": publishDeliveryPathPayload(sequence: sequence, records: records),
            "safeAgentActions": [
                "prepare_release_artifacts",
                "generate_social_shorts_packet",
                "generate_podcast_ready_packet",
                "copy_missing_receipts",
                "capture_receipt_after_human_upload"
            ],
            "unsafeWithoutHumanProof": [
                "claim_published",
                "delete_source_media",
                "overwrite_timeline",
                "mark_receipt_captured_without_url_or_provider_id"
            ]
        ]

        guard JSONSerialization.isValidJSONObject(payload),
              let data = try? JSONSerialization.data(withJSONObject: payload, options: [.prettyPrinted, .sortedKeys]),
              let string = String(data: data, encoding: .utf8) else {
            return "{\n  \"error\": \"Unable to serialize delivery path payload\"\n}"
        }

        return string
    }

    private func publishDeliveryPathPayload(sequence: MediaSequence?, records: [PublishReceiptRecord]) -> [[String: Any]] {
        let sequenceLoaded = sequence != nil
        let releasePrepared = !fullReleaseOutputPath.isEmpty
        let shortsPrepared = !socialShortsPacketOutputPath.isEmpty
        let podcastPrepared = !podcastReadyPacketOutputPath.isEmpty
        let capturedReceipts = records.filter { publishRecordReceiptCaptured($0) }.count
        let episodeRecords = records.filter { record in
            let platform = record.platform.lowercased()
            return platform.contains("youtube") || platform.contains("patreon")
        }
        let socialRecords = records.filter { record in
            let platform = record.platform.lowercased()
            return platform.contains("short") || platform.contains("instagram") || platform.contains("facebook") || platform.contains("linkedin")
        }
        let podcastRecords = records.filter { record in
            let platform = record.platform.lowercased()
            return platform.contains("spotify") || platform.contains("apple")
        }

        return [
            [
                "id": "wide-episode-master",
                "label": "16:9 episode master",
                "destinations": ["YouTube", "Patreon", "Episode page"],
                "state": releasePrepared ? "artifact_ready" : (sequenceLoaded ? "ready_to_prepare" : "needs_episode"),
                "artifactPath": fullReleaseOutputPath,
                "receiptTotal": episodeRecords.count,
                "receiptCaptured": episodeRecords.filter { publishRecordReceiptCaptured($0) }.count,
                "nextAction": releasePrepared ? "Upload/schedule the wide master, then capture public or scheduled receipts." : (sequenceLoaded ? "Prepare release artifacts." : "Load an episode session.")
            ],
            [
                "id": "vertical-social-shorts",
                "label": "9:16 shorts",
                "destinations": ["YouTube Shorts", "Instagram", "Facebook", "LinkedIn"],
                "state": shortsPrepared ? "packet_ready" : "needs_reviewed_shorts",
                "artifactPath": socialShortsPacketOutputPath,
                "receiptTotal": socialRecords.count,
                "receiptCaptured": socialRecords.filter { publishRecordReceiptCaptured($0) }.count,
                "nextAction": shortsPrepared ? "Review/export selected shorts, upload/schedule, then capture receipts." : "Create or review short recipes and generate the social shorts packet."
            ],
            [
                "id": "podcast-audio",
                "label": "Podcast audio",
                "destinations": ["Spotify", "Apple Podcasts"],
                "state": podcastPrepared ? "handoff_ready" : "needs_audio_packet",
                "artifactPath": podcastReadyPacketOutputPath,
                "receiptTotal": podcastRecords.count,
                "receiptCaptured": podcastRecords.filter { publishRecordReceiptCaptured($0) }.count,
                "nextAction": podcastPrepared ? "Upload/schedule podcast audio and capture receipts." : "Generate podcast-ready packet from the episode spine."
            ],
            [
                "id": "publication-proof",
                "label": "Publication receipts",
                "destinations": ["All release targets"],
                "state": records.isEmpty ? "no_ledger" : (capturedReceipts == records.count ? "proof_complete" : "proof_incomplete"),
                "artifactPath": "",
                "receiptTotal": records.count,
                "receiptCaptured": capturedReceipts,
                "nextAction": records.isEmpty ? "Generate publish ledger from the current delivery." : "Capture missing public/scheduled URLs, provider IDs, and notes."
            ]
        ]
    }

