            )

            publishSafeNextActionRow(
                title: "Human review",
                status: hasLedger ? "review needed" : "waiting for ledger",
                detail: "A person checks files, titles, captions, thumbnails, and platform choices before anything is posted.",
                color: hasLedger ? QuipslyStudioTheme.creek : QuipslyStudioTheme.sage,
                systemImage: "person.crop.circle.badge.checkmark",
