            )

            publishSafeNextActionRow(
                title: "Post or schedule",
                status: hasLedger ? "manual/provider step" : "not ready",
                detail: "Upload or schedule on YouTube, Patreon, social platforms, Spotify, and Apple. Do not mark published here.",
                color: hasLedger ? QuipslyStudioTheme.honey : QuipslyStudioTheme.sage,
                systemImage: "paperplane.fill",
