                    generateSocialPublicationQueueForAgent(directoryPath: nil, basename: nil)
                }
            )

            publishSafeNextActionRow(
                title: "Capture proof",
                status: proofComplete ? "proved" : (hasLedger ? "\(capturedReceipts)/\(records.count) receipts" : "waiting for ledger"),
                detail: "Paste real public URLs, scheduled URLs, provider IDs, and notes. This is when publication becomes true.",
                color: proofComplete ? QuipslyStudioTheme.moss : (hasLedger ? QuipslyStudioTheme.clay : QuipslyStudioTheme.sage),
                systemImage: "checkmark.seal.fill",
