    private func publishPlatformDestinationCard(
        platform: String,
        output: String,
        record: PublishReceiptRecord?,
        artifactPrepared: Bool,
        sequenceLoaded: Bool,
        systemImage: String
    ) -> some View {
        let receiptCaptured = record.map { publishRecordReceiptCaptured($0) } ?? false
        let copyReady = record.map { publishRecordCopyReady($0) } ?? false
        let artifactReady = record.map { publishRecordArtifactReady($0) } ?? artifactPrepared
        let status = receiptCaptured
            ? "proved"
            : (record != nil ? (artifactReady && copyReady ? "ready to post" : "ledger") : (artifactPrepared ? "needs ledger" : (sequenceLoaded ? "needs prep" : "load episode")))
        let color: Color = receiptCaptured
            ? QuipslyStudioTheme.moss
            : (record != nil ? (artifactReady && copyReady ? QuipslyStudioTheme.creek : QuipslyStudioTheme.honey) : (artifactPrepared ? QuipslyStudioTheme.honey : QuipslyStudioTheme.sage))
        let nextAction = publishPlatformDestinationNextAction(platform: platform, output: output, status: status)

        return VStack(alignment: .leading, spacing: 5) {
            HStack(alignment: .firstTextBaseline, spacing: 6) {
                Image(systemName: systemImage)
                    .font(.caption)
                    .foregroundStyle(color)
                    .frame(width: 18, height: 18)
                    .background(color.opacity(0.12))
                    .clipShape(Circle())
                VStack(alignment: .leading, spacing: 1) {
                    Text(platform)
                        .font(.caption)
                        .fontWeight(.black)
                        .foregroundStyle(.primary)
                        .lineLimit(1)
                    Text(output)
                        .font(.caption2)
                        .foregroundStyle(.secondary)
                        .lineLimit(1)
                }
                Spacer(minLength: 4)
            }

            Text(status.uppercased())
                .font(.caption2.monospacedDigit())
                .fontWeight(.black)
                .foregroundStyle(color)
                .padding(.horizontal, 6)
                .padding(.vertical, 3)
                .background(color.opacity(0.12))
                .clipShape(Capsule())

            Text(nextAction)
                .font(.caption2)
                .foregroundStyle(.secondary)
                .fixedSize(horizontal: false, vertical: true)
        }
        .padding(8)
        .background(QuipslyStudioTheme.panelLift.opacity(0.22))
        .overlay(
            RoundedRectangle(cornerRadius: 12, style: .continuous)
                .stroke(color.opacity(0.14), lineWidth: 1)
        )
        .clipShape(RoundedRectangle(cornerRadius: 12, style: .continuous))
    }

    private func publishBestPlatformRecord(
        _ records: [PublishReceiptRecord],
        platformKeywords: [String],
        deliveryKeywords: [String]
    ) -> PublishReceiptRecord? {
        records.first { record in
            let platform = record.platform.lowercased()
            let deliveryLane = record.deliveryLaneId.lowercased()
            let platformMatches = platformKeywords.contains { keyword in
                platform.contains(keyword.lowercased())
            }
            let deliveryMatches = deliveryKeywords.isEmpty || deliveryKeywords.contains { keyword in
                deliveryLane.contains(keyword.lowercased())
            }
            return platformMatches && deliveryMatches
        } ?? records.first { record in
            let platform = record.platform.lowercased()
            return platformKeywords.contains { keyword in
                platform.contains(keyword.lowercased())
            }
        }
    }

    private func publishPlatformDestinationMatrixJSONString(sequence: MediaSequence?, records: [PublishReceiptRecord]) -> String {
        let sequenceLoaded = sequence != nil
        let destinations = publishPlatformDestinationPayloads(sequenceLoaded: sequenceLoaded, records: records)

        let payload: [String: Any] = [
            "payloadVersion": 1,
            "generatedAt": ISO8601DateFormatter().string(from: Date()),
            "truth": "Destination matrix reports artifact, ledger, and proof status per platform. It does not perform provider uploads.",
            "sequence": [
                "loaded": sequenceLoaded,
                "title": sequence?.title ?? "",
                "durationSeconds": sequence?.duration ?? 0
            ],
            "destinations": destinations
        ]

        guard JSONSerialization.isValidJSONObject(payload),
              let data = try? JSONSerialization.data(withJSONObject: payload, options: [.prettyPrinted, .sortedKeys]),
              let string = String(data: data, encoding: .utf8) else {
            return "{\n  \"error\": \"Unable to serialize destination matrix\"\n}"
        }

        return string
    }

    private func publishHumanApprovalPacketJSONString(sequence: MediaSequence?, records: [PublishReceiptRecord]) -> String {
        let sequenceLoaded = sequence != nil
        let destinations = publishPlatformDestinationPayloads(sequenceLoaded: sequenceLoaded, records: records)
        let readyDestinations = destinations.filter { destination in
            let status = destination["status"] as? String ?? ""
            return status == "ready_to_post" || status == "proved"
        }.count
        let unprovedDestinations = destinations.filter { destination in
            let proved = destination["receiptCaptured"] as? Bool ?? false
            return !proved
        }.count

        let payload: [String: Any] = [
            "payloadVersion": 1,
            "generatedAt": ISO8601DateFormatter().string(from: Date()),
            "truth": "This packet is a human approval aid. It does not approve, post, schedule, or prove publication by itself.",
