    private func publishPlatformDestinationPayloads(sequenceLoaded: Bool, records: [PublishReceiptRecord]) -> [[String: Any]] {
        let episodePrepared = !fullReleaseOutputPath.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty
        let shortsPrepared = !socialShortsPacketOutputPath.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty
        let podcastPrepared = !podcastReadyPacketOutputPath.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty

        return [
            publishPlatformDestinationPayload(platform: "YouTube", output: "16:9 episode", record: publishBestPlatformRecord(records, platformKeywords: ["youtube"], deliveryKeywords: ["episode", "16x9", "master"]), artifactPrepared: episodePrepared, sequenceLoaded: sequenceLoaded),
            publishPlatformDestinationPayload(platform: "Patreon", output: "supporter episode", record: publishBestPlatformRecord(records, platformKeywords: ["patreon"], deliveryKeywords: ["episode", "16x9", "master"]), artifactPrepared: episodePrepared, sequenceLoaded: sequenceLoaded),
            publishPlatformDestinationPayload(platform: "YouTube Shorts", output: "9:16 short", record: publishBestPlatformRecord(records, platformKeywords: ["youtube shorts", "shorts"], deliveryKeywords: ["social", "short"]), artifactPrepared: shortsPrepared, sequenceLoaded: sequenceLoaded),
            publishPlatformDestinationPayload(platform: "Instagram", output: "reel/social short", record: publishBestPlatformRecord(records, platformKeywords: ["instagram"], deliveryKeywords: ["social", "short"]), artifactPrepared: shortsPrepared, sequenceLoaded: sequenceLoaded),
            publishPlatformDestinationPayload(platform: "Facebook", output: "social short", record: publishBestPlatformRecord(records, platformKeywords: ["facebook"], deliveryKeywords: ["social", "short"]), artifactPrepared: shortsPrepared, sequenceLoaded: sequenceLoaded),
            publishPlatformDestinationPayload(platform: "LinkedIn", output: "professional short", record: publishBestPlatformRecord(records, platformKeywords: ["linkedin"], deliveryKeywords: ["social", "short"]), artifactPrepared: shortsPrepared, sequenceLoaded: sequenceLoaded),
            publishPlatformDestinationPayload(platform: "Spotify", output: "podcast audio", record: publishBestPlatformRecord(records, platformKeywords: ["spotify"], deliveryKeywords: ["podcast", "audio"]), artifactPrepared: podcastPrepared, sequenceLoaded: sequenceLoaded),
            publishPlatformDestinationPayload(platform: "Apple Podcasts", output: "podcast audio", record: publishBestPlatformRecord(records, platformKeywords: ["apple"], deliveryKeywords: ["podcast", "audio"]), artifactPrepared: podcastPrepared, sequenceLoaded: sequenceLoaded)
        ]
    }

    private func publishPlatformDestinationPayload(
        platform: String,
        output: String,
        record: PublishReceiptRecord?,
        artifactPrepared: Bool,
        sequenceLoaded: Bool
    ) -> [String: Any] {
        let receiptCaptured = record.map { publishRecordReceiptCaptured($0) } ?? false
        let artifactReady = record.map { publishRecordArtifactReady($0) } ?? artifactPrepared
        let copyReady = record.map { publishRecordCopyReady($0) } ?? false
        let status = receiptCaptured
            ? "proved"
            : (record != nil ? (artifactReady && copyReady ? "ready_to_post" : "ledger_created") : (artifactPrepared ? "needs_ledger" : (sequenceLoaded ? "needs_prep" : "needs_episode")))

        return [
            "platform": platform,
            "output": output,
            "status": status,
            "artifactPrepared": artifactPrepared,
            "ledgerRecordExists": record != nil,
            "artifactReady": artifactReady,
            "copyReady": copyReady,
            "receiptCaptured": receiptCaptured,
            "deliveryLaneId": record?.deliveryLaneId ?? "",
            "nextAction": publishPlatformDestinationNextAction(platform: platform, output: output, status: status),
            "safeCodexActions": ["inspect", "copy_status", "prepare_missing_artifacts", "list_receipt_gap"],
            "requiresHumanOrProviderAction": !receiptCaptured
        ]
    }

    private func publishPlatformDestinationNextAction(platform: String, output: String, status: String) -> String {
        switch status {
        case "proved":
            return "Proof captured. Keep the receipt with this release lane."
        case "ready to post", "ready_to_post":
            return "Open the \(platform) workflow, post or schedule the \(output), then capture the receipt."
        case "ledger", "ledger_created":
            return "Ledger exists. Check copy/artifact fields before posting to \(platform)."
        case "needs ledger", "needs_ledger":
            return "Artifact exists. Refresh the publish ledger so \(platform) gets a receipt slot."
        case "needs prep", "needs_prep":
            return "Prepare release artifacts before working on the \(platform) destination."
        case "load episode", "needs_episode":
            return "Load an episode session before preparing this \(platform) lane."
        default:
            return "Inspect this destination, then follow the safe Ship queue before posting."
        }
    }

    private func publishSafeNextActionJSONString(sequence: MediaSequence?, records: [PublishReceiptRecord]) -> String {
        let sequenceLoaded = sequence != nil
        let releasePrepared = !fullReleaseOutputPath.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty
        let socialPrepared = !socialShortsPacketOutputPath.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty
        let podcastPrepared = !podcastReadyPacketOutputPath.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty
        let preparedRecords = records.filter { publishRecordArtifactReady($0) && publishRecordCopyReady($0) }.count
        let capturedReceipts = records.filter { publishRecordReceiptCaptured($0) }.count
        let receiptRemaining = max(0, records.count - capturedReceipts)

        let payload: [String: Any] = [
            "payloadVersion": 1,
            "generatedAt": ISO8601DateFormatter().string(from: Date()),
            "truth": "Safe Ship actions can prepare, inspect, queue, copy, and list proof gaps. They do not claim publication without real receipts.",
            "sequence": [
                "loaded": sequenceLoaded,
                "title": sequence?.title ?? "",
                "durationSeconds": sequence?.duration ?? 0,
                "laneCount": sequence?.lanes.count ?? 0,
                "shortRecipeCount": sequence?.shortClipQueue.count ?? 0
            ],
            "artifactFamilies": [
                "wideEpisodeMasterPrepared": releasePrepared,
                "socialShortsPacketPrepared": socialPrepared,
                "podcastReadyPacketPrepared": podcastPrepared
            ],
            "ledger": [
                "recordCount": records.count,
                "preparedRecordCount": preparedRecords,
                "receiptCapturedCount": capturedReceipts,
                "receiptRemainingCount": receiptRemaining
            ],
            "safeNextActions": [
                [
                    "id": "prepare_artifacts",
                    "label": "Prepare artifacts",
                    "status": releasePrepared && socialPrepared && podcastPrepared ? "prepared" : (sequenceLoaded ? "next_safe_step" : "needs_episode"),
                    "codexSafe": sequenceLoaded,
                    "humanRequiredBeforeAction": false,
                    "notes": "Build local episode, shorts, podcast, ledger, cockpit, and receipt checklist artifacts."
                ],
                [
                    "id": "human_review",
                    "label": "Human review",
                    "status": records.isEmpty ? "waiting_for_ledger" : "review_needed",
                    "codexSafe": sequenceLoaded,
                    "humanRequiredBeforeAction": true,
                    "notes": "Inspect titles, captions, thumbnails, files, and platform choices before posting."
                ],
                [
                    "id": "post_or_schedule",
                    "label": "Post or schedule",
                    "status": records.isEmpty ? "not_ready" : "manual_or_provider_step",
                    "codexSafe": false,
                    "humanRequiredBeforeAction": true,
                    "notes": "Upload, schedule, or send through a provider. This is a real publishing event."
                ],
                [
                    "id": "capture_proof",
                    "label": "Capture proof",
                    "status": records.isEmpty ? "waiting_for_ledger" : (receiptRemaining == 0 ? "proved" : "proof_incomplete"),
                    "codexSafe": !records.isEmpty,
                    "humanRequiredBeforeAction": receiptRemaining > 0,
                    "notes": "Paste public URLs, scheduled URLs, provider IDs, and notes. Publication truth advances here."
                ]
            ],
            "destinationMatrix": publishPlatformDestinationPayloads(sequenceLoaded: sequenceLoaded, records: records),
            "records": records.map { record in
                [
                    "deliveryLaneId": record.deliveryLaneId,
                    "platform": record.platform,
                    "artifactReady": publishRecordArtifactReady(record),
                    "copyReady": publishRecordCopyReady(record),
                    "receiptCaptured": publishRecordReceiptCaptured(record)
                ] as [String: Any]
            }
        ]

        guard JSONSerialization.isValidJSONObject(payload),
              let data = try? JSONSerialization.data(withJSONObject: payload, options: [.prettyPrinted, .sortedKeys]),
              let string = String(data: data, encoding: .utf8) else {
            return "{\n  \"error\": \"Unable to serialize safe Ship checklist\"\n}"
        }

        return string
    }

    private func publishSafeNextActionRow(
        title: String,
        status: String,
        detail: String,
        color: Color,
        systemImage: String,
        actionTitle: String,
        actionSystemImage: String,
        isDisabled: Bool,
        action: @escaping () -> Void
    ) -> some View {
        HStack(alignment: .top, spacing: 9) {
            Image(systemName: systemImage)
                .font(.caption)
                .foregroundStyle(color)
                .frame(width: 24, height: 24)
                .background(color.opacity(0.12))
                .clipShape(Circle())

            VStack(alignment: .leading, spacing: 3) {
                HStack(alignment: .firstTextBaseline, spacing: 6) {
                    Text(title)
                        .font(.caption)
                        .fontWeight(.black)
                        .foregroundStyle(.primary)
                    Text(status.uppercased())
                        .font(.caption2.monospacedDigit())
                        .fontWeight(.black)
                        .foregroundStyle(color)
                        .padding(.horizontal, 6)
                        .padding(.vertical, 2)
                        .background(color.opacity(0.10))
                        .clipShape(Capsule())
                }
                Text(detail)
                    .font(.caption2)
                    .foregroundStyle(.secondary)
                    .fixedSize(horizontal: false, vertical: true)
            }

            Spacer(minLength: 4)

            Button(action: action) {
                Label(actionTitle, systemImage: actionSystemImage)
                    .labelStyle(.titleAndIcon)
            }
            .controlSize(.small)
            .disabled(isDisabled)
        }
        .padding(8)
        .background(QuipslyStudioTheme.panelLift.opacity(0.22))
        .overlay(
            RoundedRectangle(cornerRadius: 12, style: .continuous)
                .stroke(color.opacity(0.12), lineWidth: 1)
        )
        .clipShape(RoundedRectangle(cornerRadius: 12, style: .continuous))
    }

    private func publishProductionStateLadder(
        sequenceLoaded: Bool,
        ledgerRecordCount: Int,
        preparedRecordCount: Int,
        receiptCapturedCount: Int,
        receiptRemainingCount: Int,
        publicationComplete: Bool
    ) -> some View {
        let hasLedger = ledgerRecordCount > 0
        let preparedStatus = preparedRecordCount > 0 ? "\(preparedRecordCount) ready" : (sequenceLoaded ? "needs prep" : "load episode")
        let approvedStatus = hasLedger ? "human gate" : "not started"
        let postedStatus = receiptCapturedCount > 0 ? "some posted" : (hasLedger ? "waiting" : "not started")
        let provedStatus = publicationComplete ? "complete" : (hasLedger ? "\(receiptCapturedCount)/\(ledgerRecordCount) proof" : "no ledger")

        return VStack(alignment: .leading, spacing: 8) {
            HStack(alignment: .firstTextBaseline, spacing: 8) {
                Label("Production states", systemImage: "signpost.right.and.left.fill")
                    .font(.caption)
                    .fontWeight(.black)
                    .foregroundStyle(QuipslyStudioTheme.moss)
                Spacer()
                Text("PREPARED IS NOT POSTED")
                    .font(.caption2.monospacedDigit())
                    .fontWeight(.black)
                    .foregroundStyle(QuipslyStudioTheme.honey)
            }

            LazyVGrid(columns: [GridItem(.flexible()), GridItem(.flexible())], spacing: 7) {
                publishProductionStateStep(
                    title: "Prepared",
                    status: preparedStatus,
                    detail: "Files, packets, captions, and ledgers exist locally. Safe for Codex to help here.",
                    color: preparedRecordCount > 0 ? QuipslyStudioTheme.moss : (sequenceLoaded ? QuipslyStudioTheme.honey : QuipslyStudioTheme.sage),
                    systemImage: "shippingbox.fill"
                )
                publishProductionStateStep(
                    title: "Approved",
                    status: approvedStatus,
                    detail: "A human chooses what actually goes out. This stays explicit, even when agents prepare the work.",
                    color: hasLedger ? QuipslyStudioTheme.creek : QuipslyStudioTheme.sage,
                    systemImage: "person.crop.circle.badge.checkmark"
                )
                publishProductionStateStep(
                    title: "Posted",
                    status: postedStatus,
                    detail: "Upload, schedule, or send happens here. Future connectors may help, but they still need receipts.",
                    color: receiptCapturedCount > 0 ? QuipslyStudioTheme.creek : QuipslyStudioTheme.honey,
                    systemImage: "paperplane.fill"
                )
                publishProductionStateStep(
                    title: "Proved",
                    status: provedStatus,
                    detail: receiptRemainingCount == 0 && hasLedger ? "Every lane has durable proof." : "Public URLs, scheduled URLs, or provider IDs close the loop.",
                    color: publicationComplete ? QuipslyStudioTheme.moss : QuipslyStudioTheme.clay,
                    systemImage: "checkmark.seal.fill"
                )
            }

            Text("This ladder is intentionally conservative: Quipsly can prepare aggressively, but publication truth only advances when the ledger has evidence.")
                .font(.caption2)
                .foregroundStyle(QuipslyStudioTheme.sage)
                .fixedSize(horizontal: false, vertical: true)
        }
        .padding(10)
        .background(QuipslyStudioTheme.cardGradient)
        .overlay(
            RoundedRectangle(cornerRadius: 14, style: .continuous)
                .stroke(QuipslyStudioTheme.moss.opacity(0.18), lineWidth: 1)
        )
        .clipShape(RoundedRectangle(cornerRadius: 14, style: .continuous))
        .accessibilityIdentifier("quipsly.ship.productionStateLadder")
        .accessibilityLabel("Production states. Prepared, approved, posted, and proved are tracked separately.")
    }

    private func publishReceiptCockpitPanel(sequence: MediaSequence?, records: [PublishReceiptRecord]) -> some View {
        let captured = records.filter { publishRecordReceiptCaptured($0) }
        let missing = records.filter { !publishRecordReceiptCaptured($0) }
        let readyMissing = publishReceiptCaptureReadyMissingRecords(records: records)
        let blockedOrNotReady = missing.filter { !readyMissing.contains($0) }
        let nextRecord = readyMissing.sorted {
            publishRecordActionPriority($0) == publishRecordActionPriority($1)
                ? publishReceiptDisplayLabel($0) < publishReceiptDisplayLabel($1)
                : publishRecordActionPriority($0) < publishRecordActionPriority($1)
        }.first
        let statusColor: Color = records.isEmpty
            ? QuipslyStudioTheme.honey
            : (missing.isEmpty ? QuipslyStudioTheme.moss : (readyMissing.isEmpty ? QuipslyStudioTheme.clay : QuipslyStudioTheme.creek))
        let statusText = records.isEmpty
            ? "no ledger"
            : (missing.isEmpty ? "publication proved" : "\(readyMissing.count) ready to capture")
        let familyRows = publicationReceiptFamilySummaries(records: records)
        let platformRows = publicationReceiptPlatformSummaries(records: records)

        return VStack(alignment: .leading, spacing: 10) {
            HStack(alignment: .firstTextBaseline, spacing: 8) {
                Label("Tower receipt cockpit", systemImage: "checkmark.seal.text.page.fill")
                    .font(.caption)
                    .fontWeight(.black)
                    .foregroundStyle(statusColor)
                Spacer(minLength: 0)
                Text(statusText.uppercased())
                    .font(.caption2.monospaced())
                    .fontWeight(.black)
                    .foregroundStyle(statusColor)
                    .padding(.horizontal, 7)
                    .padding(.vertical, 3)
                    .background(statusColor.opacity(0.12))
                    .clipShape(Capsule())
            }

            Text("Exports are prepared work. Receipts are publishing proof. Capture a public URL, scheduled URL, provider ID, or receipt JSON after each real platform post.")
                .font(.caption2)
                .foregroundStyle(.secondary)
                .fixedSize(horizontal: false, vertical: true)

            HStack(spacing: 6) {
                publishStatPill("records", records.count, records.isEmpty ? QuipslyStudioTheme.honey : QuipslyStudioTheme.moss)
                publishStatPill("captured", captured.count, captured.isEmpty ? QuipslyStudioTheme.honey : QuipslyStudioTheme.moss)
                publishStatPill("ready", readyMissing.count, readyMissing.isEmpty ? QuipslyStudioTheme.honey : QuipslyStudioTheme.creek)
                publishStatPill("waiting", blockedOrNotReady.count, blockedOrNotReady.isEmpty ? QuipslyStudioTheme.moss : QuipslyStudioTheme.clay)
            }

            if let nextRecord {
                VStack(alignment: .leading, spacing: 7) {
                    HStack(alignment: .top, spacing: 8) {
                        Image(systemName: "arrowshape.turn.up.right.circle.fill")
                            .font(.body)
                            .foregroundStyle(QuipslyStudioTheme.creek)
                            .frame(width: 24, height: 24)
                            .background(QuipslyStudioTheme.creek.opacity(0.13))
                            .clipShape(Circle())

                        VStack(alignment: .leading, spacing: 3) {
                            Text("Next receipt")
                                .font(.caption2)
                                .fontWeight(.black)
                                .foregroundStyle(.secondary)
                            Text(publishReceiptDisplayLabel(nextRecord))
                                .font(.caption)
                                .fontWeight(.black)
                                .lineLimit(2)
                            Text("Post or schedule this artifact, then save the receipt. Quipsly will not call the episode published until proof is attached.")
                                .font(.caption2)
                                .foregroundStyle(.secondary)
                                .fixedSize(horizontal: false, vertical: true)
                        }
                        Spacer(minLength: 0)
                    }

                    HStack(spacing: 8) {
                        Button {
                            beginEditingPublishReceipt(nextRecord)
                        } label: {
                            Label("Capture receipt", systemImage: "link.badge.plus")
                                .font(.caption2)
                                .fontWeight(.black)
                        }
                        .buttonStyle(.borderedProminent)
                        .controlSize(.mini)
                        .tint(QuipslyStudioTheme.creek)
                        .help("Open the manual receipt editor for the next platform target.")

                        Button {
                            copyPublishReceiptText(
                                publicationReceiptCaptureCommand(for: nextRecord),
                                successMessage: "Copied next receipt command"
                            )
                        } label: {
                            Label("Copy command", systemImage: "terminal.fill")
                                .font(.caption2)
                                .fontWeight(.black)
                        }
                        .buttonStyle(.bordered)
                        .controlSize(.mini)
                        .help("Copy the exact agent command shape for saving this receipt later.")

                        Button {
                            copyPublishReceiptText(
                                publicationReceiptNextActionCardMarkdown(nextRecord),
                                successMessage: "Copied next receipt card"
                            )
                        } label: {
                            Label("Copy card", systemImage: "doc.text.fill")
                                .font(.caption2)
                                .fontWeight(.black)
                        }
                        .buttonStyle(.bordered)
                        .controlSize(.mini)
                        .help("Copy the full next-receipt action card with platform, artifact, proof rule, and commands.")
                    }
                }
                .padding(9)
                .background(QuipslyStudioTheme.creek.opacity(0.08))
                .overlay(
                    RoundedRectangle(cornerRadius: 14, style: .continuous)
                        .stroke(QuipslyStudioTheme.creek.opacity(0.16), lineWidth: 1)
                )
                .clipShape(RoundedRectangle(cornerRadius: 14, style: .continuous))
            } else {
                HStack(alignment: .top, spacing: 8) {
                    Image(systemName: records.isEmpty ? "shippingbox.fill" : "checkmark.seal.fill")
                        .foregroundStyle(statusColor)
                    Text(records.isEmpty
                         ? "Generate a publish ledger or full release packet before receipt capture has anything real to track."
                         : "All tracked platform receipts are captured. Next Tower step is analytics and follow-up review.")
                        .font(.caption2)
                        .foregroundStyle(.secondary)
                        .fixedSize(horizontal: false, vertical: true)
                }
                .padding(8)
                .background(statusColor.opacity(0.06))
                .clipShape(RoundedRectangle(cornerRadius: 12, style: .continuous))
            }

            VStack(alignment: .leading, spacing: 7) {
                Text("Receipt map")
                    .font(.caption2)
                    .fontWeight(.black)
                    .foregroundStyle(.secondary)
                LazyVGrid(columns: [GridItem(.flexible()), GridItem(.flexible())], spacing: 7) {
                    ForEach(Array(familyRows.prefix(4).enumerated()), id: \.offset) { _, row in
                        publishReceiptCockpitSummaryTile(row: row, fallbackLabel: "Family")
                    }
                    ForEach(Array(platformRows.prefix(8).enumerated()), id: \.offset) { _, row in
                        publishReceiptCockpitSummaryTile(row: row, fallbackLabel: "Platform")
                    }
                }
            }

            HStack(spacing: 8) {
                Button {
                    copyPublishReceiptText(
                        jsonString(from: publicationReceiptCockpitPayload(for: sequence)),
                        successMessage: "Copied receipt cockpit JSON"
                    )
                } label: {
                    Label("Copy cockpit JSON", systemImage: "curlybraces.square")
                        .font(.caption2)
                        .fontWeight(.black)
                }
                .buttonStyle(.bordered)
                .controlSize(.mini)
                .help("Copy the same receipt truth exposed at /publication_receipt_cockpit.")

                Button {
                    copyMissingPublicationReceipts(records)
                } label: {
                    Label("Copy missing receipts", systemImage: "doc.on.doc.fill")
                        .font(.caption2)
                        .fontWeight(.black)
                }
                .buttonStyle(.bordered)
                .controlSize(.mini)
                .disabled(missing.isEmpty)
                .help("Copy every missing publication receipt and capture command.")
            }
        }
        .padding(10)
        .background(QuipslyStudioTheme.cardGradient)
        .overlay(
            RoundedRectangle(cornerRadius: 18, style: .continuous)
                .stroke(statusColor.opacity(0.18), lineWidth: 1)
        )
        .clipShape(RoundedRectangle(cornerRadius: 18, style: .continuous))
        .accessibilityIdentifier("quipsly.publish.receiptCockpit")
        .accessibilityLabel("Tower receipt cockpit. Shows platform publication proof gaps and the next receipt to capture.")
    }

    private func publishReceiptCockpitSummaryTile(row: [String: Any], fallbackLabel: String) -> some View {
        let label = (row["label"] as? String) ?? fallbackLabel
        let total = (row["totalCount"] as? Int) ?? 0
        let captured = (row["capturedCount"] as? Int) ?? 0
        let ready = (row["readyForReceiptCaptureCount"] as? Int) ?? 0
        let waiting = (row["blockedOrNotReadyCount"] as? Int) ?? 0
        let complete = (row["complete"] as? Bool) ?? false
        let tint: Color = complete ? QuipslyStudioTheme.moss : (ready > 0 ? QuipslyStudioTheme.creek : (waiting > 0 ? QuipslyStudioTheme.clay : QuipslyStudioTheme.honey))

        return VStack(alignment: .leading, spacing: 3) {
            HStack(spacing: 5) {
                Circle()
                    .fill(tint)
                    .frame(width: 7, height: 7)
                Text(label)
                    .font(.caption2)
                    .fontWeight(.black)
                    .lineLimit(1)
                    .truncationMode(.tail)
                Spacer(minLength: 0)
            }
            Text("\(captured)/\(total) proved · \(ready) ready · \(waiting) waiting")
                .font(.caption2.monospacedDigit())
                .foregroundStyle(.secondary)
                .lineLimit(1)
                .minimumScaleFactor(0.78)
        }
        .padding(7)
        .background(tint.opacity(0.055))
        .overlay(
            RoundedRectangle(cornerRadius: 11, style: .continuous)
                .stroke(tint.opacity(0.13), lineWidth: 1)
        )
        .clipShape(RoundedRectangle(cornerRadius: 11, style: .continuous))
        .accessibilityLabel("\(label): \(captured) of \(total) receipts proved, \(ready) ready to capture, \(waiting) waiting.")
    }

