    private func publishOutputReadinessDeck(records: [PublishReceiptRecord], sequenceLoaded: Bool) -> some View {
        let episodeRecord = records.first { $0.deliveryLaneId == "episode-16x9-master" }
        let shortRecord = records.first { $0.deliveryLaneId == "social-short-clips" || $0.deliveryLaneId.hasPrefix("social-short-clips/") }
        let podcastRecord = records.first { $0.deliveryLaneId == "podcast-audio-master" }
        let proofCount = records.filter { publishRecordReceiptCaptured($0) }.count

        return VStack(alignment: .leading, spacing: 9) {
            HStack(alignment: .firstTextBaseline, spacing: 8) {
                Label("Ship map", systemImage: "point.3.connected.trianglepath.dotted")
                    .font(.caption)
                    .fontWeight(.black)
                    .foregroundStyle(QuipslyStudioTheme.honey)
                Spacer()
                Text(records.isEmpty ? "NO LEDGER YET" : "\(proofCount)/\(records.count) RECEIPTS")
                    .font(.caption2.monospacedDigit())
                    .fontWeight(.black)
                    .foregroundStyle(records.isEmpty ? QuipslyStudioTheme.honey : (proofCount == records.count ? QuipslyStudioTheme.moss : QuipslyStudioTheme.creek))
            }

            LazyVGrid(columns: [GridItem(.flexible()), GridItem(.flexible())], spacing: 7) {
                publishOutputTile(
                    title: "16:9 episode",
                    destination: "YouTube + Patreon",
                    systemImage: "rectangle.16x9",
                    record: episodeRecord,
                    sequenceLoaded: sequenceLoaded,
                    emptyAction: "Full prep builds the episode master and platform packet.",
                    primaryActionTitle: records.isEmpty ? "Full prep" : "Copy proof gaps",
                    primarySystemImage: records.isEmpty ? "shippingbox.and.arrow.backward" : "doc.on.doc",
                    primaryAction: {
                        records.isEmpty ? prepareFullReleaseForHuman() : copyMissingPublicationReceipts(records)
                    }
                )
                publishOutputTile(
                    title: "9:16 shorts",
                    destination: "Shorts, Reels, LinkedIn",
                    systemImage: "rectangle.portrait",
                    record: shortRecord,
                    sequenceLoaded: sequenceLoaded,
                    emptyAction: "Queue strong moments, then Full prep exports social derivatives.",
                    primaryActionTitle: "Social queue",
                    primarySystemImage: "square.grid.3x3.square",
                    primaryAction: {
                        generateSocialPublicationQueueForAgent(directoryPath: nil, basename: nil)
                    }
                )
                publishOutputTile(
                    title: "Podcast audio",
                    destination: "Spotify + Apple",
                    systemImage: "waveform",
                    record: podcastRecord,
                    sequenceLoaded: sequenceLoaded,
                    emptyAction: "Audio proxy readiness gates podcast handoff.",
                    primaryActionTitle: podcastPacketOutputPath.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty ? "Podcast packet" : "Ready packet",
                    primarySystemImage: "dot.radiowaves.left.and.right",
                    primaryAction: {
                        if podcastPacketOutputPath.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty {
                            generatePodcastPacketForAgent(directoryPath: nil, basename: nil)
                        } else {
                            generatePodcastReadyPacketForCurrentManifest()
                        }
                    }
                )
                publishOutputTile(
                    title: "Receipt proof",
                    destination: "URLs + provider IDs",
                    systemImage: "checklist.checked",
                    record: records.first(where: { publishRecordReceiptCaptured($0) }),
                    sequenceLoaded: sequenceLoaded,
                    emptyAction: records.isEmpty ? "Create the ledger first; proof comes after posting." : "Paste real receipts before calling the release published.",
                    treatsAnyRecordAsStarted: true,
                    primaryActionTitle: records.isEmpty ? "Copy mission" : "Proof gaps",
                    primarySystemImage: records.isEmpty ? "doc.on.doc" : "exclamationmark.bubble",
                    primaryAction: {
                        records.isEmpty ? copyPublicationMissionControlJSON() : copyMissingPublicationReceipts(records)
                    }
                )
            }

            Text("Design rule: edit truth, artifact truth, upload intent, and publication proof stay separate. That is what lets humans and Codex ship without lying to ourselves.")
                .font(.caption2)
                .foregroundStyle(QuipslyStudioTheme.sage)
                .fixedSize(horizontal: false, vertical: true)
        }
        .padding(10)
        .background(QuipslyStudioTheme.livingPanelGradient)
        .overlay(
            RoundedRectangle(cornerRadius: 14, style: .continuous)
                .stroke(QuipslyStudioTheme.warmGlassStroke, lineWidth: 1)
        )
        .clipShape(RoundedRectangle(cornerRadius: 14, style: .continuous))
        .accessibilityIdentifier("quipsly.ship.outputReadinessDeck")
        .accessibilityLabel("Ship map. Shows episode, shorts, podcast, and publication proof readiness.")
    }

    private func publishArtifactTruthPanel(sequenceLoaded: Bool) -> some View {
        let releaseFolder = fullReleaseOutputPath.trimmingCharacters(in: .whitespacesAndNewlines)
        let releaseFolderExists = !releaseFolder.isEmpty && FileManager.default.fileExists(atPath: releaseFolder)
        let fullPrepStatus = fullReleaseStatus == "idle"
            ? (sequenceLoaded ? "ready to prep" : "load episode")
            : fullReleaseStatus
        let fullPrepColor: Color = {
            switch fullReleaseStatus {
            case "completed":
                return QuipslyStudioTheme.moss
            case "running":
                return QuipslyStudioTheme.creek
            case "failed", "blocked":
                return QuipslyStudioTheme.clay
            default:
                return sequenceLoaded ? QuipslyStudioTheme.honey : QuipslyStudioTheme.sage
            }
        }()

        return VStack(alignment: .leading, spacing: 8) {
            HStack(alignment: .firstTextBaseline, spacing: 8) {
                Label("Artifact truth", systemImage: "shippingbox.fill")
                    .font(.caption)
                    .fontWeight(.black)
                    .foregroundStyle(QuipslyStudioTheme.creek)
                Spacer()
                Text(releaseFolderExists ? "RELEASE FOLDER FOUND" : "NO RELEASE FOLDER")
                    .font(.caption2.monospacedDigit())
                    .fontWeight(.black)
                    .foregroundStyle(releaseFolderExists ? QuipslyStudioTheme.moss : QuipslyStudioTheme.honey)
            }

            publishArtifactRow(
                title: "Full release prep",
                status: fullPrepStatus,
                detail: fullReleaseStep.isEmpty ? "Exports episode, shorts, podcast audio, ledgers, packets, and cockpit." : fullReleaseStep,
                color: fullPrepColor
            )

            publishArtifactRow(
                title: "Release folder",
                status: releaseFolderExists ? "ready" : (sequenceLoaded ? "not built" : "no episode"),
                detail: releaseFolder.isEmpty ? "Full prep will choose the output folder." : releaseFolder,
                color: releaseFolderExists ? QuipslyStudioTheme.moss : QuipslyStudioTheme.honey
            )

            publishArtifactRow(
                title: "Ship packet",
