    private func publishArtifactRow(title: String, status: String, detail: String, color: Color) -> some View {
        HStack(alignment: .top, spacing: 8) {
            Circle()
                .fill(color.opacity(0.78))
                .frame(width: 8, height: 8)
                .padding(.top, 4)

            VStack(alignment: .leading, spacing: 2) {
                HStack(spacing: 6) {
                    Text(title)
                        .font(.caption2)
                        .fontWeight(.black)
                    Text(status.uppercased())
                        .font(.caption2.monospacedDigit())
                        .fontWeight(.black)
                        .foregroundStyle(color)
                }
                Text(detail)
                    .font(.caption2)
                    .foregroundStyle(.secondary)
                    .lineLimit(2)
                    .truncationMode(.middle)
                    .fixedSize(horizontal: false, vertical: true)
            }
            Spacer(minLength: 0)
        }
        .accessibilityLabel("\(title): \(status). \(detail)")
    }

    private func publishOutputTile(
        title: String,
        destination: String,
        systemImage: String,
        record: PublishReceiptRecord?,
        sequenceLoaded: Bool,
        emptyAction: String,
        treatsAnyRecordAsStarted: Bool = false,
        primaryActionTitle: String? = nil,
        primarySystemImage: String = "arrow.right.circle",
        primaryAction: (() -> Void)? = nil
    ) -> some View {
        let receiptCaptured = record.map { publishRecordReceiptCaptured($0) } ?? false
        let artifactReady = record.map { publishRecordArtifactReady($0) } ?? false
        let copyReady = record.map { publishRecordCopyReady($0) } ?? false
        let hasRecord = record != nil
        let started = treatsAnyRecordAsStarted ? hasRecord : (artifactReady || copyReady || receiptCaptured)
        let status: String = {
            if receiptCaptured { return "proved" }
            if artifactReady && copyReady { return "ready" }
            if started { return "needs receipt" }
            if sequenceLoaded { return "needs prep" }
            return "load episode"
        }()
        let color: Color = {
            switch status {
            case "proved":
                return QuipslyStudioTheme.moss
            case "ready":
                return QuipslyStudioTheme.honey
            case "needs receipt":
                return QuipslyStudioTheme.creek
            case "needs prep":
                return QuipslyStudioTheme.honey
            default:
                return QuipslyStudioTheme.sage
            }
        }()
        let nextAction: String = {
            if receiptCaptured { return "Keep proof with the release folder." }
            if artifactReady && copyReady { return "Post or schedule, then paste the receipt." }
            if started { return "Resolve missing copy, artifact, or receipt details." }
            return emptyAction
        }()

        return VStack(alignment: .leading, spacing: 5) {
            HStack(spacing: 7) {
                Image(systemName: systemImage)
                    .foregroundStyle(color)
                    .frame(width: 22, height: 22)
                    .background(color.opacity(0.12))
                    .clipShape(RoundedRectangle(cornerRadius: 7, style: .continuous))
                VStack(alignment: .leading, spacing: 1) {
                    Text(title)
                        .font(.caption2)
                        .fontWeight(.black)
                        .lineLimit(1)
                    Text(destination)
                        .font(.caption2)
                        .foregroundStyle(.secondary)
                        .lineLimit(1)
                        .minimumScaleFactor(0.75)
                }
                Spacer(minLength: 0)
            }

            Text(status.uppercased())
                .font(.caption2.monospacedDigit())
                .fontWeight(.black)
                .foregroundStyle(color)

            publishOutputTileRungs(
                sequenceLoaded: sequenceLoaded,
                hasRecord: hasRecord,
                artifactReady: artifactReady,
                copyReady: copyReady,
                receiptCaptured: receiptCaptured,
                treatsAnyRecordAsStarted: treatsAnyRecordAsStarted
            )

            Text(nextAction)
                .font(.caption2)
                .foregroundStyle(.secondary)
                .lineLimit(3)
                .fixedSize(horizontal: false, vertical: true)

            if let primaryActionTitle, let primaryAction {
                Button {
                    primaryAction()
                } label: {
                    Label(primaryActionTitle, systemImage: primarySystemImage)
                        .font(.caption2)
                        .fontWeight(.black)
                        .frame(maxWidth: .infinity)
                }
                .buttonStyle(.bordered)
                .controlSize(.mini)
                .help("Safe next action for \(title). This prepares, reveals, or copies handoff truth; it does not mark publication complete.")
                .accessibilityIdentifier("quipsly.ship.outputTile.\(releaseCockpitIdentifier(title)).primaryAction")
            }
        }
        .padding(8)
        .frame(maxWidth: .infinity, alignment: .leading)
        .background(color.opacity(0.065))
        .overlay(
            RoundedRectangle(cornerRadius: 12, style: .continuous)
                .stroke(color.opacity(0.14), lineWidth: 1)
        )
        .clipShape(RoundedRectangle(cornerRadius: 12, style: .continuous))
        .accessibilityLabel("\(title). \(destination). Status \(status). \(nextAction)")
    }

    private func publishOutputTileRungs(
        sequenceLoaded: Bool,
        hasRecord: Bool,
        artifactReady: Bool,
        copyReady: Bool,
        receiptCaptured: Bool,
        treatsAnyRecordAsStarted: Bool
    ) -> some View {
        let prepared = artifactReady || copyReady || (treatsAnyRecordAsStarted && hasRecord)
        let posted = receiptCaptured
        return HStack(spacing: 4) {
            publishOutputTileRungChip("edit", isActive: sequenceLoaded, color: QuipslyStudioTheme.creek)
            publishOutputTileRungChip("prep", isActive: prepared, color: QuipslyStudioTheme.honey)
            publishOutputTileRungChip("post", isActive: posted, color: QuipslyStudioTheme.pollen)
            publishOutputTileRungChip("proof", isActive: receiptCaptured, color: QuipslyStudioTheme.moss)
        }
        .accessibilityLabel("Output ladder. Edit \(sequenceLoaded ? "ready" : "not ready"), prep \(prepared ? "ready" : "not ready"), post \(posted ? "done" : "not done"), proof \(receiptCaptured ? "captured" : "missing").")
    }

    private func publishOutputTileRungChip(_ title: String, isActive: Bool, color: Color) -> some View {
        Text(title.uppercased())
            .font(.system(size: 8, weight: .black, design: .monospaced))
            .foregroundStyle(isActive ? color : QuipslyStudioTheme.sage.opacity(0.72))
            .padding(.horizontal, 4)
            .padding(.vertical, 2)
            .background((isActive ? color : QuipslyStudioTheme.sage).opacity(isActive ? 0.14 : 0.07))
            .clipShape(Capsule())
    }

    private func releaseCockpitPanel(sequence: MediaSequence?, records: [PublishReceiptRecord]) -> some View {
        let readinessRows = sequence?.publishDeliverableReadiness(artifactExists: { path in
            FileManager.default.fileExists(atPath: path)
        }) ?? []
        let proofCaptured = records.filter { publishRecordReceiptCaptured($0) }.count
        let proofTotal = records.count
        let proofRemaining = max(0, proofTotal - proofCaptured)

        return VStack(alignment: .leading, spacing: 8) {
            HStack(spacing: 7) {
                Label("Release cockpit", systemImage: "leaf.circle.fill")
                    .font(.caption)
                    .fontWeight(.black)
                    .foregroundStyle(QuipslyStudioTheme.honey)
                Spacer()
                Text(proofTotal == 0 ? "NO LEDGER" : "\(proofCaptured)/\(proofTotal) PROVED")
                    .font(.caption2.monospacedDigit())
                    .fontWeight(.black)
                    .foregroundStyle(proofRemaining == 0 && proofTotal > 0 ? QuipslyStudioTheme.moss : QuipslyStudioTheme.honey)
                    .padding(.horizontal, 7)
                    .padding(.vertical, 4)
                    .background((proofRemaining == 0 && proofTotal > 0 ? QuipslyStudioTheme.moss : QuipslyStudioTheme.honey).opacity(0.12))
                    .clipShape(Capsule())
            }

            Text("Follow the output families from local artifact to platform proof. Nothing is called published until a URL, provider id, or receipt is attached.")
                .font(.caption2)
                .foregroundStyle(.secondary)
                .fixedSize(horizontal: false, vertical: true)

            VStack(spacing: 7) {
                releaseCockpitFamilyCard(
                    title: "16:9 episode master",
                    destinations: "YouTube + Patreon",
                    icon: "play.rectangle.fill",
                    color: QuipslyStudioTheme.creek,
                    rows: readinessRows.filter { $0.family == .episode16x9 },
                    emptyAction: "Run Full prep to create the episode master handoff."
                )
                releaseCockpitFamilyCard(
                    title: "9:16 short recipes",
                    destinations: "Cuts, Instagram, Facebook, LinkedIn",
                    icon: "rectangle.portrait.on.rectangle.portrait.angled",
                    color: QuipslyStudioTheme.moss,
                    rows: readinessRows.filter { $0.family == .short9x16 },
                    emptyAction: "Review short recipes, export social derivatives, then create receipt rows."
                )
                releaseCockpitFamilyCard(
                    title: "Podcast audio",
                    destinations: "Spotify + Apple Podcasts",
                    icon: "waveform",
                    color: QuipslyStudioTheme.lichen,
                    rows: readinessRows.filter { $0.family == .podcastAudio },
                    emptyAction: "Export podcast audio and generate the podcast ready packet."
                )
                releaseProofFamilyCard(records: records, captured: proofCaptured, remaining: proofRemaining)
            }
        }
        .padding(10)
        .background(
            LinearGradient(
                colors: [
                    QuipslyStudioTheme.forest.opacity(0.18),
                    QuipslyStudioTheme.panelLift.opacity(0.16),
                    QuipslyStudioTheme.panel.opacity(0.34)
                ],
                startPoint: .topLeading,
                endPoint: .bottomTrailing
            )
        )
        .overlay(
            RoundedRectangle(cornerRadius: 16, style: .continuous)
                .stroke(QuipslyStudioTheme.honey.opacity(0.13), lineWidth: 1)
        )
        .clipShape(RoundedRectangle(cornerRadius: 16, style: .continuous))
        .accessibilityIdentifier("quipsly.ship.cockpit")
    }

