    private func platformProofChecklistRows(records: [PublishReceiptRecord]) -> [(platform: String, family: String, status: String, proof: String, nextAction: String, color: Color)] {
        records
            .sorted { lhs, rhs in
                if lhs.outputFamily.rawValue != rhs.outputFamily.rawValue {
                    return lhs.outputFamily.rawValue < rhs.outputFamily.rawValue
                }
                return lhs.platform.localizedCaseInsensitiveCompare(rhs.platform) == .orderedAscending
            }
            .map { record in
                let receiptCaptured = publishRecordReceiptCaptured(record)
                let artifactReady = publishRecordArtifactReady(record)
                let copyReady = publishRecordCopyReady(record)
                let status: String
                let color: Color
                let proof: String
                let nextAction: String

                if receiptCaptured {
                    status = "Proved"
                    color = QuipslyStudioTheme.moss
                    proof = !record.publicURL.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty
                        ? record.publicURL
                        : (!record.providerReceiptId.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty ? record.providerReceiptId : "Receipt captured")
                    nextAction = "Keep this receipt with the release folder and analytics trail."
                } else if artifactReady && copyReady {
                    status = "Ready to post"
                    color = QuipslyStudioTheme.honey
                    proof = "Needs real public/scheduled URL or provider receipt."
                    nextAction = "Upload or schedule on \(record.platform), then paste the real proof back into Quipsly."
                } else if artifactReady {
                    status = "Needs copy"
                    color = QuipslyStudioTheme.lichen
                    proof = "Artifact exists; title, description, captions, or metadata still need review."
                    nextAction = "Review copy and metadata before posting."
                } else {
                    status = "Needs artifact"
                    color = QuipslyStudioTheme.clay
                    proof = record.artifactPath.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty
                        ? "No artifact path attached."
                        : "Artifact not found locally."
                    nextAction = "Export or regenerate this deliverable before platform handoff."
                }

                return (
                    platform: record.platform.isEmpty ? "Unknown platform" : record.platform,
                    family: record.outputFamily.title,
                    status: status,
                    proof: proof,
                    nextAction: nextAction,
                    color: color
                )
            }
    }

    private func platformProofChecklistPayload(records: [PublishReceiptRecord]) -> [[String: Any]] {
        records
            .sorted { lhs, rhs in
                if lhs.outputFamily.rawValue != rhs.outputFamily.rawValue {
                    return lhs.outputFamily.rawValue < rhs.outputFamily.rawValue
                }
                return lhs.platform.localizedCaseInsensitiveCompare(rhs.platform) == .orderedAscending
            }
            .map { record in
                let receiptCaptured = publishRecordReceiptCaptured(record)
                let artifactReady = publishRecordArtifactReady(record)
                let copyReady = publishRecordCopyReady(record)
                let status: String
                let proofNeeded: String
                let nextAction: String

                if receiptCaptured {
                    status = "proved"
                    proofNeeded = "Receipt already captured."
                    nextAction = "Keep this receipt with the release folder and analytics trail."
                } else if artifactReady && copyReady {
                    status = "ready-to-post"
                    proofNeeded = "Real public/scheduled URL or provider receipt."
                    nextAction = "Upload or schedule on \(record.platform), then paste the real proof back into Quipsly."
                } else if artifactReady {
                    status = "needs-copy"
                    proofNeeded = "Reviewed title, description, captions, or metadata."
                    nextAction = "Review copy and metadata before posting."
                } else {
                    status = "needs-artifact"
                    proofNeeded = record.artifactPath.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty
                        ? "Artifact path."
                        : "Local artifact file."
                    nextAction = "Export or regenerate this deliverable before platform handoff."
                }

                return [
                    "id": record.id.uuidString,
                    "platform": record.platform,
                    "family": record.outputFamily.rawValue,
                    "familyLabel": record.outputFamily.title,
                    "deliveryLaneId": record.deliveryLaneId,
                    "artifactType": record.artifactType,
                    "format": record.format,
                    "artifactPath": record.artifactPath,
                    "artifactReady": artifactReady,
                    "copyReady": copyReady,
                    "receiptCaptured": receiptCaptured,
                    "publicURL": record.publicURL,
                    "providerReceiptId": record.providerReceiptId,
                    "status": status,
                    "proofNeeded": proofNeeded,
                    "nextAction": nextAction
                ] as [String: Any]
            }
    }

    private func copyPlatformProofChecklist(_ records: [PublishReceiptRecord]) {
        let rows = platformProofChecklistPayload(records: records)
        let lines = [
            "# Quipsly platform proof checklist",
            "",
            "Proof rule: local artifacts, upload handoffs, and scheduled posts are not publication proof until a real public/scheduled URL, provider id, or receipt is captured.",
            "",
            rows.isEmpty ? "No platform targets exist yet. Run Full prep or refresh the publish ledger after exports exist." : rows.enumerated().map { index, row in
                let platform = row["platform"] as? String ?? "Unknown platform"
                let family = row["familyLabel"] as? String ?? "Unknown family"
                let status = row["status"] as? String ?? "unknown"
                let proofNeeded = row["proofNeeded"] as? String ?? "Proof needed"
                let nextAction = row["nextAction"] as? String ?? "Review this platform target."
                let publicURL = row["publicURL"] as? String ?? ""
                let providerReceiptId = row["providerReceiptId"] as? String ?? ""
                let existingProof = [publicURL, providerReceiptId]
                    .map { $0.trimmingCharacters(in: .whitespacesAndNewlines) }
                    .filter { !$0.isEmpty }
                    .joined(separator: " | ")

                return [
                    "\(index + 1). \(platform) - \(family)",
                    "   Status: \(status)",
                    "   Proof needed: \(proofNeeded)",
                    existingProof.isEmpty ? "   Existing proof: none" : "   Existing proof: \(existingProof)",
                    "   Next action: \(nextAction)"
                ].joined(separator: "\n")
            }.joined(separator: "\n\n")
        ].joined(separator: "\n")

        #if os(macOS)
        NSPasteboard.general.clearContents()
        NSPasteboard.general.setString(lines, forType: .string)
        #endif

        lastMediaAction = "Copied platform proof checklist"
        updateAgentState()
    }

