    private func releaseCockpitFamilyStatus(_ rows: [PublishDeliverableReadiness]) -> String {
        if rows.isEmpty { return "Not queued" }
        if rows.contains(where: { $0.status == .needsAttention }) { return "Needs care" }
        if rows.allSatisfy({ $0.status == .published }) { return "Proved" }
        if rows.contains(where: { $0.status == .exported || $0.status == .readyToExport || $0.status == .readyToReview }) { return "Ready to work" }
        return "Drafting"
    }

    private func releaseCockpitStatusColor(_ status: String) -> Color {
        switch status {
        case "Proved":
            return QuipslyStudioTheme.moss
        case "Ready to work":
            return QuipslyStudioTheme.honey
        case "Needs care":
            return QuipslyStudioTheme.clay
        case "Not queued":
            return QuipslyStudioTheme.sage
        default:
            return QuipslyStudioTheme.creek
        }
    }

    private func releaseCockpitFamilyNextAction(_ rows: [PublishDeliverableReadiness], fallback: String) -> String {
        guard !rows.isEmpty else { return fallback }
        if let needsCare = rows.first(where: { $0.status == .needsAttention }) {
            return needsCare.blocker.isEmpty ? needsCare.nextAction : needsCare.blocker
        }
        if let unproved = rows.first(where: { $0.status != .published }) {
            return "\(unproved.destination): \(unproved.nextAction)"
        }
        return "Receipt proof exists. Keep the receipt with this release and analytics trail."
    }

    private func releaseCockpitIdentifier(_ title: String) -> String {
        title.lowercased()
            .replacingOccurrences(of: ":", with: "")
            .replacingOccurrences(of: "+", with: "plus")
            .replacingOccurrences(of: " ", with: "-")
            .replacingOccurrences(of: "/", with: "-")
    }

