    private var productionCommandCenterPanel: some View {
        let indexPath = currentProductionCommandCenterIndexPath()
        let hasIndex = FileManager.default.fileExists(atPath: indexPath)
        let isRunning = productionCommandCenterStatus == "generating"
        let color: Color = productionCommandCenterStatus == "failed" ? QuipslyStudioTheme.clay : (hasIndex ? QuipslyStudioTheme.creek : QuipslyStudioTheme.honey)
        let statusText: String = {
            if isRunning {
                return productionCommandCenterMode == "live" ? "Live refresh is running..." : "Fast redraw is running..."
            }
            if productionCommandCenterStatus == "failed" {
                return productionCommandCenterErrorMessage.isEmpty ? "Command center failed." : productionCommandCenterErrorMessage
            }
            if hasIndex {
                return productionCommandCenterOutputPath.isEmpty
                    ? "Episodes 1-3 cockpit is ready."
                    : "Cockpit ready: \(productionCommandCenterOutputPath)"
            }
            return "Generate the Episodes 1-3 cockpit when you want a multi-episode publishing map."
        }()

        return VStack(alignment: .leading, spacing: 8) {
            HStack(alignment: .top, spacing: 8) {
                Image(systemName: hasIndex ? "rectangle.3.group.fill" : "rectangle.3.group")
                    .foregroundStyle(color)
                    .frame(width: 22, height: 22)
                    .background(color.opacity(0.13))
                    .clipShape(Circle())
                VStack(alignment: .leading, spacing: 2) {
                    Text("Episodes 1-3 Command Center")
                        .font(.caption)
                        .fontWeight(.black)
                    Text(statusText)
                        .font(.caption2)
                        .foregroundStyle(.secondary)
                        .lineLimit(3)
                }
                Spacer()
            }

            HStack(spacing: 6) {
                #if os(macOS)
                Button {
                    revealPublicationArtifactPath(indexPath, label: "Episodes 1-3 command center")
                } label: {
                    Label("Open", systemImage: "safari")
                        .frame(maxWidth: .infinity)
                }
                .controlSize(.mini)
                .disabled(!hasIndex)
                .help("Open the latest generated Episodes 1-3 command center HTML.")
                #endif

                Button {
                    generateProductionCommandCenter(reuseExisting: true, openAfter: false)
                } label: {
                    Label("Fast redraw", systemImage: "arrow.triangle.2.circlepath")
                        .frame(maxWidth: .infinity)
                }
                .controlSize(.mini)
                .disabled(isRunning)
                .help("Redraw the command center from existing reports. Fast, but not fresh app truth.")

                Button {
                    generateProductionCommandCenter(reuseExisting: false, openAfter: false)
                } label: {
                    Label("Live refresh", systemImage: "dot.radiowaves.left.and.right")
                        .frame(maxWidth: .infinity)
                }
                .controlSize(.mini)
                .disabled(isRunning)
                .help("Reload the native sessions and regenerate current release/social/review truth. Slower, but authoritative.")
            }
        }
        .padding(8)
        .background(color.opacity(0.055))
        .overlay(
            RoundedRectangle(cornerRadius: 12, style: .continuous)
                .stroke(color.opacity(0.16), lineWidth: 1)
        )
        .clipShape(RoundedRectangle(cornerRadius: 12, style: .continuous))
    }

    private func currentProductionCommandCenterDirectory() -> String {
        (FileManager.default.homeDirectoryForCurrentUser as NSURL)
            .appendingPathComponent("Movies/QuipslyExports/CommandCenters/episodes-1-3-20260618")?
            .path ?? ""
    }

    private func currentProductionCommandCenterIndexPath() -> String {
        URL(fileURLWithPath: currentProductionCommandCenterDirectory(), isDirectory: true)
            .appendingPathComponent("index.html")
            .path
    }

    private func quipslyStudioSourceRootURL() -> URL {
        URL(fileURLWithPath: #filePath)
            .deletingLastPathComponent()
            .deletingLastPathComponent()
            .deletingLastPathComponent()
    }

    private func generateProductionCommandCenter(reuseExisting: Bool, openAfter: Bool) {
        let appRoot = quipslyStudioSourceRootURL()
        let scriptURL = appRoot.appendingPathComponent("script/generate_episode_command_center.py")
        guard FileManager.default.fileExists(atPath: scriptURL.path) else {
            productionCommandCenterStatus = "failed"
            productionCommandCenterErrorMessage = "Command center blocked: script/generate_episode_command_center.py was not found."
            productionCommandCenterOutputPath = ""
            lastMediaAction = productionCommandCenterErrorMessage
            updateAgentState()
            return
        }

        let outputPath = currentProductionCommandCenterDirectory()
        productionCommandCenterStatus = "generating"
        productionCommandCenterErrorMessage = ""
        productionCommandCenterOutputPath = ""
        productionCommandCenterMode = reuseExisting ? "fast" : "live"
        lastMediaAction = reuseExisting
            ? "Fast redraw of Episodes 1-3 command center started"
            : "Live refresh of Episodes 1-3 command center started"
        updateAgentState()

        Task.detached(priority: .userInitiated) {
            let result: Result<[String: Any], Error> = Result {
                let process = Process()
                let outputPipe = Pipe()
                let errorPipe = Pipe()
                var arguments = [
                    scriptURL.path,
                    "--output",
                    outputPath
                ]
                if reuseExisting {
                    arguments.append("--reuse-existing")
                } else {
                    arguments.append("--generate-reviewed")
                }
                if openAfter {
                    arguments.append("--open")
                }

                process.executableURL = URL(fileURLWithPath: "/usr/bin/python3")
                process.arguments = arguments
                process.currentDirectoryURL = appRoot
                process.standardOutput = outputPipe
                process.standardError = errorPipe
                try process.run()
                process.waitUntilExit()

                let outputData = outputPipe.fileHandleForReading.readDataToEndOfFile()
                let errorData = errorPipe.fileHandleForReading.readDataToEndOfFile()
                let outputText = String(data: outputData, encoding: .utf8) ?? ""
                let errorText = String(data: errorData, encoding: .utf8) ?? ""
                guard process.terminationStatus == 0 else {
                    throw NSError(
                        domain: "QuipslyCommandCenter",
                        code: Int(process.terminationStatus),
                        userInfo: [NSLocalizedDescriptionKey: errorText.isEmpty ? outputText : errorText]
                    )
                }
                guard let data = outputText.data(using: .utf8),
                      let payload = try JSONSerialization.jsonObject(with: data) as? [String: Any] else {
                    throw NSError(
                        domain: "QuipslyCommandCenter",
                        code: 2,
                        userInfo: [NSLocalizedDescriptionKey: "Command center did not return JSON."]
                    )
                }
                return payload
            }

            await MainActor.run {
                switch result {
                case .success(let payload):
                    let indexPath = payload["indexPath"] as? String ?? currentProductionCommandCenterIndexPath()
                    productionCommandCenterStatus = "generated"
                    productionCommandCenterOutputPath = indexPath
                    productionCommandCenterErrorMessage = ""
                    productionCommandCenterGeneratedAt = Date()
                    lastMediaAction = reuseExisting
                        ? "Fast command center redraw complete"
                        : "Live command center refresh complete"
                case .failure(let error):
                    productionCommandCenterStatus = "failed"
                    productionCommandCenterErrorMessage = error.localizedDescription
                    productionCommandCenterOutputPath = ""
                    lastMediaAction = "Command center failed: \(error.localizedDescription)"
                }
                updateAgentState()
            }
        }
    }

