    private func agentReceiptCard(_ receipt: AgentProofReceipt) -> some View {
        VStack(alignment: .leading, spacing: 8) {
            HStack(alignment: .top, spacing: 8) {
                Image(systemName: receipt.passed ? "checkmark.seal.fill" : "exclamationmark.triangle.fill")
                    .font(.headline)
                    .foregroundStyle(receipt.passed ? QuipslyStudioTheme.moss : QuipslyStudioTheme.clay)
                    .frame(width: 30, height: 30)
                    .background((receipt.passed ? QuipslyStudioTheme.moss : QuipslyStudioTheme.clay).opacity(0.14))
                    .clipShape(RoundedRectangle(cornerRadius: 10, style: .continuous))

                VStack(alignment: .leading, spacing: 3) {
                    Text(receipt.passed ? "Proof passed" : "Proof needs review")
                        .font(.subheadline)
                        .fontWeight(.black)
                        .foregroundStyle(.primary)
                    Text(receipt.createdLabel)
                        .font(.caption2.monospaced())
                        .foregroundStyle(.secondary)
                        .lineLimit(1)
                }

                Spacer()

                Text(receipt.playbackFormat.isEmpty ? "format ?" : receipt.playbackFormat)
                    .font(.caption2)
                    .fontWeight(.black)
                    .padding(.horizontal, 7)
                    .padding(.vertical, 4)
                    .background(QuipslyStudioTheme.creek.opacity(0.18))
                    .clipShape(Capsule())
            }

            VStack(alignment: .leading, spacing: 4) {
                agentReceiptFact("Session", receipt.shortSessionName)
                agentReceiptFact("Selected", [receipt.selectedLaneName, receipt.selectedTagType].filter { !$0.isEmpty }.joined(separator: " | "))
                agentReceiptFact("Playhead", "\(String(format: "%.2f", receipt.beforePlayhead))s -> \(String(format: "%.2f", receipt.afterPlayhead))s")
                agentReceiptFact("Timeline", "\(String(format: "%.1f", receipt.timelinePixelsPerSecond)) px/sec")
                agentReceiptFact("Sync", receipt.sharedPlayheadStatus.isEmpty ? "unknown" : receipt.sharedPlayheadStatus)
            }

            if !receipt.lastMediaAction.isEmpty {
                Text(receipt.lastMediaAction)
                    .font(.caption2)
                    .foregroundStyle(QuipslyStudioTheme.lichen)
                    .fixedSize(horizontal: false, vertical: true)
            }

            HStack(spacing: 6) {
                Button("Copy summary") {
                    copyAgentWorkbenchText(receipt.path, note: "Copied Agent receipt summary path")
                }
                .buttonStyle(.bordered)
                .controlSize(.mini)

                Button("Copy commands") {
                    copyAgentWorkbenchText(receipt.commandsPath, note: "Copied Agent receipt commands path")
                }
                .buttonStyle(.bordered)
                .controlSize(.mini)
                .disabled(receipt.commandsPath.isEmpty)

                Button("Reveal") {
                    revealAgentWorkbenchPath(receipt.path, note: "Revealed Agent receipt")
                }
                .buttonStyle(.bordered)
                .controlSize(.mini)
            }
        }
        .padding(10)
        .background(receipt.passed ? QuipslyStudioTheme.selectedSourceCardGradient : QuipslyStudioTheme.recipeCardGradient)
        .overlay(
            RoundedRectangle(cornerRadius: 16, style: .continuous)
                .stroke((receipt.passed ? QuipslyStudioTheme.moss : QuipslyStudioTheme.clay).opacity(0.28), lineWidth: 1)
        )
        .clipShape(RoundedRectangle(cornerRadius: 16, style: .continuous))
        .accessibilityIdentifier("quipsly.agent.receipt.\(receipt.id)")
    }

    private func agentReceiptFact(_ label: String, _ value: String) -> some View {
        HStack(alignment: .firstTextBaseline, spacing: 6) {
            Text(label)
                .font(.caption2)
                .fontWeight(.black)
                .foregroundStyle(QuipslyStudioTheme.sage)
                .frame(width: 56, alignment: .leading)
            Text(value.isEmpty ? "not captured" : value)
                .font(.caption2)
                .foregroundStyle(.secondary)
                .lineLimit(2)
        }
    }

    private func copyAgentWorkbenchText(_ text: String, note: String) {
        #if os(macOS)
        NSPasteboard.general.clearContents()
        NSPasteboard.general.setString(text, forType: .string)
        #endif
        lastMediaAction = note
        updateAgentState()
    }

    private func revealAgentWorkbenchPath(_ path: String, note: String) {
        #if os(macOS)
        guard !path.isEmpty else { return }
        NSWorkspace.shared.activateFileViewerSelecting([URL(fileURLWithPath: path)])
        #endif
        lastMediaAction = note
        updateAgentState()
    }

    private var transcriptWorkbenchSidebar: some View {
        let sequence = projectStore.activeSequence
        let segments = (sequence?.transcriptSegments ?? []).sorted { $0.startTime < $1.startTime }
        let selectedSegment = selectedTranscriptSegmentValue(in: sequence)
        let currentSegment = sequence.flatMap { currentTranscriptSegment(in: $0) }
        let currentSegmentId = currentSegment?.id
        let canApplyToShort = selectedSegment != nil && selectedShortClipValue() != nil

        return ScrollView {
            VStack(alignment: .leading, spacing: 12) {
                transcriptHeaderView
                transcriptTimingReadinessPanel(segments: segments)
                transcriptNowPanel(segment: currentSegment)
                transcriptControlRow(sequenceLoaded: sequence != nil, hasSegments: !segments.isEmpty)
                transcriptSearchPanel(hasSegments: !segments.isEmpty)
                transcriptGenerationPanel(sequenceLoaded: sequence != nil)

                if let selectedSegment {
                    selectedTranscriptPanel(segment: selectedSegment, canApplyToShort: canApplyToShort)
                }

                transcriptSegmentCountHeader(count: segments.count)

                if segments.isEmpty {
                    transcriptEmptyState
                } else {
                    ForEach(segments) { segment in
                        transcriptSegmentCard(segment, currentSegmentId: currentSegmentId)
                    }
                }

                Button(role: .destructive) {
                    clearTranscriptForActiveSequence()
                } label: {
                    Label("Clear demo transcript", systemImage: "trash")
                        .frame(maxWidth: .infinity)
                }
                .buttonStyle(.bordered)
                .controlSize(.small)
                .disabled(segments.isEmpty)
                .help("Remove transcript segments from the current sequence.")
            }
            .padding(12)
        }
    }

    private func transcriptTimingReadinessPanel(segments: [TranscriptSegment]) -> some View {
        let words = segments.flatMap { transcriptWordTimings(for: $0) }
        let demoCount = words.filter { $0.source.localizedCaseInsensitiveContains("demo") }.count
        let estimatedCount = words.filter { $0.source.localizedCaseInsensitiveContains("estimated") }.count
        let wordLevelCount = max(0, words.count - demoCount - estimatedCount)
        let label: String
        let detail: String
        let color: Color

        if segments.isEmpty {
            label = "No transcript"
            detail = "Import, generate, or seed a transcript before using script-aware editing."
            color = QuipslyStudioTheme.sage
        } else if words.isEmpty {
            label = "Line timing only"
            detail = "Segments exist, but there are no word timings yet. Useful for navigation; not ready for word-highlight captions."
            color = QuipslyStudioTheme.honey
        } else if demoCount == words.count {
            label = "Demo timing"
            detail = "This proves the workflow. Replace with real word-level timing before publication captions or edit-by-word claims."
            color = QuipslyStudioTheme.honey
        } else if estimatedCount > 0 || demoCount > 0 {
            label = "Mixed timing"
            detail = "\(wordLevelCount) word-level, \(estimatedCount) estimated, \(demoCount) demo. Good for review; verify before publishing captions."
            color = QuipslyStudioTheme.honey
        } else {
            label = "Word-level timing"
            detail = "\(wordLevelCount) timed words are available for script-aware editing, captions, quotes, and shorts."
            color = QuipslyStudioTheme.moss
        }

        return HStack(alignment: .top, spacing: 8) {
            Image(systemName: words.isEmpty ? "clock.badge.questionmark" : "text.badge.checkmark")
                .foregroundStyle(color)
                .font(.caption)
                .frame(width: 18)

            VStack(alignment: .leading, spacing: 3) {
                HStack(spacing: 6) {
                    Text(label)
                        .font(.caption2)
                        .fontWeight(.black)
                        .tracking(0.8)
                        .foregroundStyle(color)
                        .textCase(.uppercase)
                    Spacer()
                    if !segments.isEmpty {
                        Text("\(segments.count) lines")
                            .font(.caption2.monospacedDigit())
                            .fontWeight(.bold)
                            .foregroundStyle(.secondary)
                    }
                }

                Text(detail)
                    .font(.caption2)
                    .foregroundStyle(.secondary)
                    .fixedSize(horizontal: false, vertical: true)
            }
        }
        .padding(9)
        .frame(maxWidth: .infinity, alignment: .leading)
        .background(color.opacity(0.08))
        .overlay(
            RoundedRectangle(cornerRadius: 13, style: .continuous)
                .stroke(color.opacity(0.16), lineWidth: 1)
        )
        .clipShape(RoundedRectangle(cornerRadius: 13, style: .continuous))
        .help("Transcript timing readiness is informational. It never blocks editing; it keeps publication promises honest.")
    }

    private func transcriptGenerationPanel(sequenceLoaded: Bool) -> some View {
        let selected = selectedProgramCropLane()
        let jobs = projectStore.activeSequence?.transcriptJobs ?? []
        let latest = jobs.sorted { $0.startedAt > $1.startedAt }.first

        return VStack(alignment: .leading, spacing: 8) {
            HStack {
                Label("Transcribe media", systemImage: "waveform.and.magnifyingglass")
                    .font(.caption)
                    .fontWeight(.bold)
                    .foregroundStyle(.secondary)
                Spacer()
                if let latest {
                    Text(latest.status.uppercased())
                        .font(.caption2.monospacedDigit())
                        .fontWeight(.black)
                        .foregroundStyle(transcriptJobColor(latest.status))
                }
            }

            Text(selected?.name ?? "Select a source lane first.")
                .font(.caption)
                .fontWeight(.semibold)
                .lineLimit(2)

            Text("Generates reviewable transcript segments from a readable local proxy, sidecar, or configured transcriber command. Captions and shorts should derive from this spine.")
                .font(.caption2)
                .foregroundStyle(.secondary)
                .fixedSize(horizontal: false, vertical: true)

            VStack(alignment: .leading, spacing: 5) {
                HStack(spacing: 6) {
                    TextField("Optional local transcriber command path", text: $transcriptCommandPath)
                        .textFieldStyle(.roundedBorder)
                        .font(.caption2.monospaced())

                    Button("Use repo provider") {
                        if let providerPath = defaultLocalTranscriptProviderPath() {
                            transcriptCommandPath = providerPath
                        }
                    }
                    .buttonStyle(.bordered)
                    .controlSize(.small)
                    .disabled(defaultLocalTranscriptProviderPath() == nil)
                    .help("Use script/local_transcript_provider.py from this source checkout when available.")
                }

                Text(transcriptCommandPath.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty
                     ? "No command set: Quipsly will look only for a sidecar beside the selected media."
                     : "Command set: Quipsly will run this executable and import its stdout as transcript metadata.")
                    .font(.caption2)
                    .foregroundStyle(.secondary)
                    .fixedSize(horizontal: false, vertical: true)
            }

            Button {
                generateTranscriptForActiveSequence(
                    laneId: selectedLaneId?.uuidString,
                    commandPath: transcriptCommandPath
                )
            } label: {
                Label("Generate from selected lane", systemImage: "text.bubble")
                    .frame(maxWidth: .infinity)
            }
            .buttonStyle(.borderedProminent)
            .controlSize(.small)
            .disabled(!sequenceLoaded || selected == nil)
            .help("Use a sidecar transcript next to the selected lane media, or a configured local transcriber command. This writes transcript metadata only.")

            if let latest {
                VStack(alignment: .leading, spacing: 3) {
                    Text(latest.sourceLaneName.isEmpty ? "Latest job" : latest.sourceLaneName)
                        .font(.caption2)
                        .fontWeight(.bold)
                        .lineLimit(1)
                    Text(latest.status == "failed" ? latest.error : "\(latest.provider) | \(latest.segmentCount) segment(s)")
                        .font(.caption2)
                        .foregroundStyle(latest.status == "failed" ? QuipslyStudioTheme.clay : .secondary)
