        }
        .padding(10)
        .background(QuipslyStudioTheme.creek.opacity(0.07))
        .overlay(
            RoundedRectangle(cornerRadius: 14, style: .continuous)
                .stroke(QuipslyStudioTheme.creek.opacity(0.14), lineWidth: 1)
        )
        .clipShape(RoundedRectangle(cornerRadius: 14, style: .continuous))
    }

    private func transcriptJobColor(_ status: String) -> Color {
        switch status.lowercased() {
        case "completed":
            return QuipslyStudioTheme.moss
        case "failed", "blocked":
            return QuipslyStudioTheme.clay
        case "running", "queued":
            return QuipslyStudioTheme.honey
        default:
            return QuipslyStudioTheme.sage
        }
    }

