    private func transcriptSearchPanel(hasSegments: Bool) -> some View {
        let query = transcriptSearchQuery.trimmingCharacters(in: .whitespacesAndNewlines)
        let canSearch = hasSegments && !query.isEmpty
        let status = latestTranscriptSearchReceipt["status"] as? String ?? ""
        let resultText = latestTranscriptSearchReceipt["text"] as? String ?? ""
        let speaker = latestTranscriptSearchReceipt["speaker"] as? String ?? ""
        let matchCount = latestTranscriptSearchReceipt["matchCount"] as? Int ?? 0

        return VStack(alignment: .leading, spacing: 8) {
            Label("Find spoken moment", systemImage: "text.magnifyingglass")
                .font(.caption)
                .fontWeight(.black)
                .foregroundStyle(QuipslyStudioTheme.creek)

            TextField("Search transcript words...", text: $transcriptSearchQuery)
                .textFieldStyle(.roundedBorder)
                .font(.caption)
                .disabled(!hasSegments)
                .help("Search the timed transcript spine. This moves the shared playhead; it does not edit media.")

            HStack(spacing: 6) {
                Button {
                    searchTranscriptForAgent(query: transcriptSearchQuery, mode: "previous")
                } label: {
                    Label("Prev", systemImage: "chevron.left")
                        .frame(maxWidth: .infinity)
                }
                .buttonStyle(.bordered)
                .controlSize(.small)
                .disabled(!canSearch)

                Button {
                    searchTranscriptForAgent(query: transcriptSearchQuery, mode: "next")
                } label: {
                    Label("Next", systemImage: "chevron.right")
                        .frame(maxWidth: .infinity)
                }
                .buttonStyle(.borderedProminent)
                .controlSize(.small)
                .disabled(!canSearch)
            }

            if !status.isEmpty {
                VStack(alignment: .leading, spacing: 4) {
                    HStack(spacing: 6) {
                        Text(status == "found" ? "FOUND" : status.uppercased())
                            .font(.caption2.monospaced())
                            .fontWeight(.black)
                            .foregroundStyle(status == "found" ? QuipslyStudioTheme.moss : QuipslyStudioTheme.clay)
                        if matchCount > 0 {
                            Text("\(matchCount) match\(matchCount == 1 ? "" : "es")")
                                .font(.caption2)
                                .foregroundStyle(.secondary)
                        }
                    }
                    if !speaker.isEmpty {
                        Text(speaker)
                            .font(.caption2)
                            .fontWeight(.bold)
                            .foregroundStyle(QuipslyStudioTheme.creek)
                    }
                    if !resultText.isEmpty {
                        Text(resultText)
                            .font(.caption2)
                            .foregroundStyle(.secondary)
                            .lineLimit(3)
                    }

                    if status == "found" {
                        Button {
                            createShortFromTranscriptForAgent(
                                mode: "selected",
                                title: query.isEmpty ? nil : "Clip: \(query)",
                                paddingBefore: 1.0,
                                paddingAfter: 2.0,
                                actor: "Human",
                                actorType: "human"
                            )
                        } label: {
                            Label("Clip found moment", systemImage: "scissors")
                                .frame(maxWidth: .infinity)
                        }
                        .buttonStyle(.borderedProminent)
                        .controlSize(.small)
                        .help("Create a short recipe from the transcript segment selected by this search. Source media stays untouched.")
                    }
                }
                .padding(8)
                .frame(maxWidth: .infinity, alignment: .leading)
                .background(QuipslyStudioTheme.panelLift.opacity(0.22))
                .clipShape(RoundedRectangle(cornerRadius: 12, style: .continuous))
            }
        }
        .padding(10)
        .background(QuipslyStudioTheme.creek.opacity(0.08))
        .overlay(
            RoundedRectangle(cornerRadius: 14, style: .continuous)
                .stroke(QuipslyStudioTheme.creek.opacity(0.16), lineWidth: 1)
        )
        .clipShape(RoundedRectangle(cornerRadius: 14, style: .continuous))
    }

