    private func transcriptNowPanel(segment: TranscriptSegment?) -> some View {
        guard let segment else {
            return AnyView(
                VStack(alignment: .leading, spacing: 6) {
                    Label("Script Now", systemImage: "waveform.path.ecg")
                        .font(.caption)
                        .fontWeight(.black)
                        .foregroundStyle(QuipslyStudioTheme.sage)
                    Text("Scrub or play through a transcript segment to see the current speaker and word here.")
                        .font(.caption2)
                        .foregroundStyle(.secondary)
                        .fixedSize(horizontal: false, vertical: true)
                }
                .padding(10)
                .frame(maxWidth: .infinity, alignment: .leading)
                .background(QuipslyStudioTheme.moss.opacity(0.08))
                .clipShape(RoundedRectangle(cornerRadius: 14, style: .continuous))
            )
        }

        let words = transcriptWordTimings(for: segment)
        let activeIndex = activeTranscriptWordIndex(words: words, segment: segment, at: playbackEngine.playhead)
        let activeWord = activeIndex.flatMap { words.indices.contains($0) ? words[$0] : nil }
        let currentWord = activeWord?.word ?? ""
        let activeWordSource = activeWord?.source ?? "estimated"
        let timingLabel: String
        if activeWordSource.localizedCaseInsensitiveContains("demo") {
            timingLabel = "DEMO WORD"
        } else if activeWordSource.localizedCaseInsensitiveContains("estimated") {
            timingLabel = "EST WORD"
        } else {
            timingLabel = "WORD"
        }
        let speakerContext = transcriptSpeakerContext(for: segment, at: playbackEngine.playhead)
        let columns = [GridItem(.adaptive(minimum: 42), spacing: 4)]

        return AnyView(
            VStack(alignment: .leading, spacing: 8) {
                HStack(alignment: .firstTextBaseline, spacing: 8) {
                    Label("Script Now", systemImage: "waveform.path.ecg")
                        .font(.caption)
                        .fontWeight(.black)
                        .foregroundStyle(QuipslyStudioTheme.moss)
                    Spacer()
                    Text(timingLabel)
                        .font(.caption2.monospaced())
                        .fontWeight(.black)
                        .foregroundStyle(QuipslyStudioTheme.honey)
                }

                HStack(alignment: .firstTextBaseline, spacing: 6) {
                    Text(speakerContext.displayName)
                        .font(.caption)
                        .fontWeight(.black)
                        .foregroundStyle(QuipslyStudioTheme.creek)
                        .help(speakerContext.detail)
                    Text(String(format: "%.2fs", playbackEngine.playhead))
                        .font(.caption2.monospacedDigit())
                        .foregroundStyle(.secondary)
                    if !currentWord.isEmpty {
                        Text(currentWord)
                            .font(.caption)
                            .fontWeight(.black)
                            .foregroundStyle(Color.black)
                            .padding(.horizontal, 7)
                            .padding(.vertical, 3)
                            .background(QuipslyStudioTheme.honey.opacity(0.92))
                            .clipShape(Capsule())
                    }
                }

                transcriptLiveTextLens(
                    segment: segment,
                    words: words,
                    activeIndex: activeIndex,
                    timingLabel: timingLabel
                )

                HStack(spacing: 6) {
                    Button {
                        selectTranscriptWordForAgent(mode: "previous", segmentId: segment.id.uuidString, index: nil)
                    } label: {
                        Label("Prev word", systemImage: "chevron.left")
                            .labelStyle(.titleAndIcon)
                    }
                    .buttonStyle(.bordered)
                    .controlSize(.mini)
                    .disabled(words.isEmpty)
                    .help("Jump to the previous word in this transcript segment. Shortcut: Option+Comma.")

                    Button {
                        selectTranscriptWordForAgent(mode: "next", segmentId: segment.id.uuidString, index: nil)
                    } label: {
                        Label("Next word", systemImage: "chevron.right")
                            .labelStyle(.titleAndIcon)
                    }
                    .buttonStyle(.borderedProminent)
                    .controlSize(.mini)
                    .disabled(words.isEmpty)
                    .help("Jump to the next word in this transcript segment. Shortcut: Option+Period.")

                    Spacer()

                    Button {
                        selectTranscriptWordForAgent(mode: "current", segmentId: segment.id.uuidString, index: nil)
                    } label: {
                        Label("At playhead", systemImage: "scope")
                            .labelStyle(.titleAndIcon)
                    }
                    .buttonStyle(.bordered)
                    .controlSize(.mini)
                    .disabled(words.isEmpty)
                    .help("Select the word currently under the shared playhead. Shortcut: Option+S.")
                }

                Button {
                    createShortFromTranscriptForAgent(
                        mode: "current",
                        title: nil,
                        paddingBefore: 1.0,
                        paddingAfter: 2.0,
                        actor: "Human",
                        actorType: "human"
                    )
                } label: {
                    Label("Clip this moment", systemImage: "scissors")
                        .frame(maxWidth: .infinity)
                }
                .buttonStyle(.borderedProminent)
                .controlSize(.small)
                .help("Create a vertical short recipe from the transcript segment under the shared playhead.")

                transcriptReadAlongPanel(
                    segment: segment,
                    words: words,
                    activeIndex: activeIndex,
                    columns: columns
                )

                Text(transcriptWordTimingHelpText(label: timingLabel))
                    .font(.caption2)
                    .foregroundStyle(.secondary)
                    .fixedSize(horizontal: false, vertical: true)
            }
            .padding(10)
            .frame(maxWidth: .infinity, alignment: .leading)
            .background(QuipslyStudioTheme.moss.opacity(0.10))
            .overlay(
                RoundedRectangle(cornerRadius: 14, style: .continuous)
                    .stroke(QuipslyStudioTheme.moss.opacity(0.22), lineWidth: 1)
            )
            .clipShape(RoundedRectangle(cornerRadius: 14, style: .continuous))
        )
    }

    private func transcriptLiveTextLens(
        segment: TranscriptSegment,
        words: [TranscriptWordTiming],
        activeIndex: Int?,
        timingLabel: String
    ) -> some View {
        let speakerContext = transcriptSpeakerContext(for: segment, at: playbackEngine.playhead)
        let index = activeIndex ?? 0
        let safeIndex = words.indices.contains(index) ? index : nil
        let activeWord = safeIndex.map { words[$0].word } ?? ""
        let beforeWords = safeIndex.map { words.prefix($0).suffix(7).map(\.word).joined(separator: " ") } ?? ""
        let afterWords = safeIndex.map { words.dropFirst($0 + 1).prefix(9).map(\.word).joined(separator: " ") } ?? ""
        let segmentDuration = max(0.01, segment.endTime - segment.startTime)
        let progress = min(1.0, max(0.0, (playbackEngine.playhead - segment.startTime) / segmentDuration))
        let speakerNeedsReview = transcriptSpeakerNeedsReview(source: speakerContext.source)

        return VStack(alignment: .leading, spacing: 8) {
            HStack(alignment: .firstTextBaseline, spacing: 8) {
                Label("Text awareness", systemImage: "text.viewfinder")
                    .font(.caption2)
                    .fontWeight(.black)
                    .foregroundStyle(QuipslyStudioTheme.honey)
                Spacer()
                Text(timingLabel)
                    .font(.caption2.monospaced())
                    .fontWeight(.black)
                    .foregroundStyle(QuipslyStudioTheme.creekMist)
            }

            Text(speakerContext.displayName)
                .font(.caption2)
                .fontWeight(.black)
                .tracking(0.8)
                .foregroundStyle(speakerNeedsReview ? QuipslyStudioTheme.honey : QuipslyStudioTheme.creekMist)
                .textCase(.uppercase)
                .help(speakerContext.detail)

            if speakerNeedsReview {
                HStack(alignment: .top, spacing: 6) {
                    Image(systemName: "questionmark.bubble")
                        .font(.caption2)
                        .foregroundStyle(QuipslyStudioTheme.honey)
                    VStack(alignment: .leading, spacing: 3) {
                        Text("Speaker needs review")
                            .font(.caption2)
                            .fontWeight(.black)
                            .foregroundStyle(QuipslyStudioTheme.honey)
                        Text(speakerContext.detail)
                            .font(.caption2)
                            .foregroundStyle(QuipslyStudioTheme.moonMilk.opacity(0.76))
                            .fixedSize(horizontal: false, vertical: true)
                        if !speakerContext.laneNames.isEmpty {
                            Text("Candidate lane: \(speakerContext.laneNames.joined(separator: " + "))")
                                .font(.caption2.monospaced())
                                .foregroundStyle(QuipslyStudioTheme.creekMist.opacity(0.82))
                                .lineLimit(2)
                        }
                    }
                }
                .padding(8)
                .background(QuipslyStudioTheme.honey.opacity(0.10))
                .overlay(
                    RoundedRectangle(cornerRadius: 10, style: .continuous)
                        .stroke(QuipslyStudioTheme.honey.opacity(0.22), lineWidth: 1)
                )
                .clipShape(RoundedRectangle(cornerRadius: 10, style: .continuous))
            }

            if words.isEmpty || activeWord.isEmpty {
                Text(segment.text)
                    .font(.callout)
                    .fontWeight(.semibold)
                    .foregroundStyle(QuipslyStudioTheme.moonMilk.opacity(0.92))
                    .fixedSize(horizontal: false, vertical: true)
            } else {
                VStack(alignment: .leading, spacing: 5) {
                    if !beforeWords.isEmpty {
                        Text(beforeWords)
                            .font(.caption)
                            .foregroundStyle(QuipslyStudioTheme.moonMilk.opacity(0.60))
                            .lineLimit(2)
                    }

                    Text(activeWord)
                        .font(.system(size: 24, weight: .black, design: .rounded))
