    private func transcriptHighlightedLine(
        segment: TranscriptSegment,
        words: [TranscriptWordTiming],
        activeIndex: Int?
    ) -> some View {
        let speakerContext = transcriptSpeakerContext(for: segment, at: playbackEngine.playhead)
        let tokens = words.isEmpty
            ? segment.text.split(separator: " ").map(String.init)
            : words.map(\.word)
        let columns = [GridItem(.adaptive(minimum: 42), spacing: 4)]

        return VStack(alignment: .leading, spacing: 6) {
            HStack(spacing: 6) {
                Text("Speaking")
                    .font(.caption2)
                    .fontWeight(.bold)
                    .foregroundStyle(.secondary)
                Text(speakerContext.displayName)
                    .font(.caption2)
                    .fontWeight(.black)
                    .foregroundStyle(QuipslyStudioTheme.creekMist)
                    .padding(.horizontal, 7)
                    .padding(.vertical, 3)
                    .background(QuipslyStudioTheme.creek.opacity(0.16))
                    .clipShape(Capsule())
                Spacer()
                if let activeIndex, words.indices.contains(activeIndex) {
                    Text(String(format: "%.2fs", words[activeIndex].startTime))
                        .font(.caption2.monospacedDigit())
                        .fontWeight(.black)
                        .foregroundStyle(QuipslyStudioTheme.honey)
                }
            }

            LazyVGrid(columns: columns, alignment: .leading, spacing: 4) {
                ForEach(Array(tokens.enumerated()), id: \.offset) { index, token in
                    let isActive = activeIndex == index && !words.isEmpty
                    Text(token)
                        .font(.callout)
                        .fontWeight(isActive ? .black : .regular)
                        .foregroundStyle(isActive ? QuipslyStudioTheme.night : QuipslyStudioTheme.moonMilk.opacity(0.92))
                        .lineLimit(1)
                        .padding(.horizontal, isActive ? 7 : 3)
                        .padding(.vertical, isActive ? 4 : 2)
                        .background(isActive ? QuipslyStudioTheme.honey.opacity(0.92) : Color.clear)
                        .clipShape(Capsule())
                }
            }
                .padding(9)
                .frame(maxWidth: .infinity, alignment: .leading)
                .background(QuipslyStudioTheme.panelLift.opacity(0.52))
                .overlay(
                    RoundedRectangle(cornerRadius: 12, style: .continuous)
                        .stroke(QuipslyStudioTheme.honey.opacity(0.22), lineWidth: 1)
                )
                .clipShape(RoundedRectangle(cornerRadius: 12, style: .continuous))
        }
    }

