    private func shortPublicationReadiness(for clip: ShortClipCandidate) -> (text: String, color: Color, icon: String) {
        let review = clip.reviewStatus.lowercased()
        let exportPath = lastExportedShortPath(for: clip)
        let exportExists = exportPath.map { FileManager.default.fileExists(atPath: $0) } ?? false
        if review == "keep" && exportExists {
            return ("Approved and exported. This can enter the reviewed social queue.", QuipslyStudioTheme.moss, "checkmark.seal.fill")
        }
        if review == "keep" {
            return ("Approved, but needs a 9:16 export before it can be queued for posting.", QuipslyStudioTheme.honey, "square.and.arrow.up")
        }
        if review == "refine" {
            return ("Promising, but intentionally blocked from publishing until refined.", QuipslyStudioTheme.honey, "slider.horizontal.3")
        }
        if review == "reject" {
            return ("Rejected for publication. Preserved as learning/context, not deleted.", QuipslyStudioTheme.clay, "xmark.octagon.fill")
        }
        if exportExists {
            return ("Export exists, but this still needs a Keep/Refine/Reject decision.", QuipslyStudioTheme.creek, "eye")
        }
        return ("Needs review and export before it can become a social queue item.", QuipslyStudioTheme.sage, "circle.dashed")
    }

