    private func shortRangeSummary(
        for clip: ShortClipCandidate,
        sequenceRange: (start: Double, end: Double, duration: Double)?
    ) -> String {
        if let sequenceRange {
            return String(
                format: "sequence %.2fs - %.2fs | %.2fs",
                sequenceRange.start,
                sequenceRange.end,
                sequenceRange.duration
            )
        }
        return String(format: "sequence %.2fs - %.2fs", clip.startTime, clip.startTime + clip.duration)
    }

    private func shortPacketOriginSummary(
        for clip: ShortClipCandidate,
        sequenceRange: (start: Double, end: Double, duration: Double)?
    ) -> String {
        let origin = clip.sourceLaneId == nil
            ? "episode-spine range"
            : "selected SHOW decision"
        let review = clip.reviewStatus.isEmpty ? "draft" : clip.reviewStatus
        let export = clip.exportStatus.isEmpty ? "not-exported" : clip.exportStatus
        if let sequenceRange {
            return String(
                format: "%@ | %@ | %@ | %.1fs",
                origin,
                review,
                export,
                sequenceRange.duration
            )
        }
        return "\(origin) | \(review) | \(export)"
    }

    private func shortSegmentCountLabel(for clip: ShortClipCandidate) -> String {
        let count = max(1, clip.segments.count)
        return count == 1 ? "1 segment" : "\(count) segments"
    }

    private func shortRecipeSummary(for clip: ShortClipCandidate) -> String {
        let count = max(1, clip.segments.count)
        let total = projectStore.activeSequence.map { shortClipExportRanges(for: clip, in: $0).reduce(0) { $0 + $1.duration } } ?? clip.duration
        if total <= 0 {
            return "Needs a SHOW segment. This recipe currently sits inside skipped Play Edit gaps, so it has no renderable social output yet."
        }
        if count == 1 {
            return "One continuous recipe segment. Add more SHOW segments when a short needs multiple moments collapsed together."
        }
        return String(format: "%d ordered recipe segments collapse into one 9:16 derivative short. Export duration after skipped-gap collapse: %.2fs.", count, total)
    }

    private func shortTranscriptContext(
        for clip: ShortClipCandidate,
        in sequence: MediaSequence?
    ) -> (segmentCount: Int, speakers: String, excerpt: String) {
        guard let sequence, !sequence.transcriptSegments.isEmpty else {
            return (0, "", "")
        }

        let recipeSegments = shortClipSegments(for: clip, in: sequence)
        guard !recipeSegments.isEmpty else {
            return (0, "", "")
        }

        var seenSegmentIds = Set<UUID>()
        var overlappingSegments: [TranscriptSegment] = []
        for recipeSegment in recipeSegments {
            let start = recipeSegment.start
            let end = recipeSegment.end
            let matches = sequence.transcriptSegments
                .filter { transcript in
                    transcript.endTime >= start && transcript.startTime <= end
                }
                .sorted { $0.startTime < $1.startTime }

            for match in matches where !seenSegmentIds.contains(match.id) {
                seenSegmentIds.insert(match.id)
                overlappingSegments.append(match)
            }
        }

        guard !overlappingSegments.isEmpty else {
            return (0, "", "")
        }

        let speakerNames = orderedUnique(overlappingSegments.map { segment in
            let midpoint = (segment.startTime + segment.endTime) / 2.0
            return transcriptSpeakerContext(for: segment, at: midpoint).displayName
        })
        .filter { !$0.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty }

        let joinedText = overlappingSegments
            .map(\.text)
            .joined(separator: " ")
            .replacingOccurrences(of: "\\s+", with: " ", options: .regularExpression)
            .trimmingCharacters(in: .whitespacesAndNewlines)
        let excerpt = transcriptExcerpt(joinedText, maxWords: 34)

        return (
            overlappingSegments.count,
            speakerNames.prefix(3).joined(separator: " + "),
            excerpt
        )
    }

    private func shortTranscriptContextPayload(
        for clip: ShortClipCandidate,
        in sequence: MediaSequence
    ) -> [String: Any] {
        let context = shortTranscriptContext(for: clip, in: sequence)
        return [
            "model": "short-transcript-context",
            "version": "2026-06-19.short-transcript-context.v1",
            "segmentCount": context.segmentCount,
            "speakers": context.speakers,
            "excerpt": context.excerpt,
            "status": context.segmentCount > 0 ? "available" : "no_overlapping_transcript",
            "truth": "Read-only projection from timed transcript segments overlapping this short recipe. It does not overwrite hook, caption, overlay, review, or publishing copy."
        ]
    }

    private func transcriptExcerpt(_ text: String, maxWords: Int) -> String {
        let words = text
            .split(whereSeparator: { $0.isWhitespace })
            .map(String.init)
        guard words.count > maxWords else {
            return text
        }
        return words.prefix(maxWords).joined(separator: " ") + "..."
    }

