    private func selectedShortTextBurnPolicyCard(_ clip: ShortClipCandidate) -> some View {
        let overlay = clip.primaryOverlayText.trimmingCharacters(in: .whitespacesAndNewlines)
        let caption = clip.captionDraft.trimmingCharacters(in: .whitespacesAndNewlines)
        let burnedOverlay = burnedInPrimaryOverlayText(for: clip)?.trimmingCharacters(in: .whitespacesAndNewlines) ?? ""
        let burnedCaption = burnedInCaptionText(for: clip)?.trimmingCharacters(in: .whitespacesAndNewlines) ?? ""
        let hasVisibleText = !overlay.isEmpty || !caption.isEmpty
        let statusColor: Color = (!burnedOverlay.isEmpty || !burnedCaption.isEmpty) ? QuipslyStudioTheme.honey : QuipslyStudioTheme.moss

        return VStack(alignment: .leading, spacing: 7) {
            HStack(spacing: 6) {
                Image(systemName: hasVisibleText ? "text.bubble.fill" : "text.bubble")
                    .foregroundStyle(statusColor)
                VStack(alignment: .leading, spacing: 2) {
                    Text("Text burn-in safety")
                        .font(.caption)
                        .fontWeight(.black)
                    Text(hasVisibleText
                         ? "Text is recipe metadata unless a positioned safe rail is explicitly approved."
                         : "No text is queued for burned-in export.")
                        .font(.caption2)
                        .foregroundStyle(.secondary)
                        .fixedSize(horizontal: false, vertical: true)
                }
                Spacer()
            }

            shortTextBurnPolicyRow(
                label: "Overlay",
                text: overlay,
                burned: !burnedOverlay.isEmpty,
                safeDetail: overlay.isEmpty
                    ? "No overlay copy."
                    : "Held as metadata. Hook/platform copy can ship without covering faces."
            )

            shortTextBurnPolicyRow(
                label: "Caption",
                text: caption,
                burned: !burnedCaption.isEmpty,
                safeDetail: caption.isEmpty
                    ? "No caption draft."
                    : "Draft caption stays in metadata/sidecars until approved copy exists."
            )

            if !overlay.isEmpty {
                HStack(spacing: 6) {
                    Button {
                        approveSelectedShortOverlayBurnIn()
                    } label: {
                        Label("Request burn-in review", systemImage: "checkmark.seal")
                    }
                    .buttonStyle(.bordered)
                    .controlSize(.small)
                    .disabled(!burnedOverlay.isEmpty)
                    .help("Adds a review-needed note. It does not burn text into pixels until a positioned safe rail is explicitly approved.")

                    Button {
                        holdSelectedShortOverlayAsMetadata()
                    } label: {
                        Label("Keep as metadata", systemImage: "eye.slash")
                    }
                    .buttonStyle(.bordered)
                    .controlSize(.small)
                    .disabled(burnedOverlay.isEmpty && primaryOverlayBurnInDirective(for: clip) == "held")
                    .help("Add an audit note keeping this overlay out of exported pixels while preserving it for captions, hooks, and platform copy.")
                }
            }

            Text("Rule: recipe text helps us edit; burned-in text needs a positioned safe rail, not just a good intention.")
                .font(.caption2)
                .foregroundStyle(.secondary)
                .fixedSize(horizontal: false, vertical: true)
        }
        .padding(8)
        .background(statusColor.opacity(0.08))
        .overlay(
            RoundedRectangle(cornerRadius: 11, style: .continuous)
                .stroke(statusColor.opacity(0.18), lineWidth: 1)
        )
        .clipShape(RoundedRectangle(cornerRadius: 11, style: .continuous))
        .accessibilityIdentifier("quipsly.workbench.shorts.textBurnPolicy")
    }

