    private func shortReviewPipelineCard(queue: [ShortClipCandidate]) -> some View {
        let keepCount = queue.filter { $0.reviewStatus.lowercased() == "keep" }.count
        let refineCount = queue.filter { $0.reviewStatus.lowercased() == "refine" }.count
        let rejectCount = queue.filter { $0.reviewStatus.lowercased() == "reject" }.count
        let draftCount = queue.count - keepCount - refineCount - rejectCount
        let missingKeptExportCount = queue.filter { clip in
            guard clip.reviewStatus.lowercased() == "keep" else { return false }
            guard let path = lastExportedShortPath(for: clip) else { return true }
            return !FileManager.default.fileExists(atPath: path)
        }.count
        let command = reviewedSocialQueueCommand()
        let canGenerate = keepCount > 0 && missingKeptExportCount == 0 && socialPublicationQueueStatus != "generating"

        return VStack(alignment: .leading, spacing: 8) {
            HStack(spacing: 7) {
                Image(systemName: keepCount > 0 ? "checkmark.seal.fill" : "checkmark.seal")
                    .foregroundStyle(keepCount > 0 ? QuipslyStudioTheme.moss : Color.secondary)
                VStack(alignment: .leading, spacing: 2) {
                    Text("Review to publish")
                        .font(.caption)
                        .fontWeight(.black)
                    Text(keepCount > 0
                         ? "\(keepCount) kept short(s) can become a social upload queue. Draft/refine/reject decisions stay visible but do not publish."
                         : "Mark promising shorts Keep before generating a social upload queue.")
                        .font(.caption2)
                        .foregroundStyle(.secondary)
                        .fixedSize(horizontal: false, vertical: true)
                }
                Spacer()
            }

            LazyVGrid(columns: [GridItem(.adaptive(minimum: 70), spacing: 6)], spacing: 6) {
                shortReviewMetric("keep", keepCount, QuipslyStudioTheme.moss)
                shortReviewMetric("refine", refineCount, QuipslyStudioTheme.honey)
                shortReviewMetric("reject", rejectCount, QuipslyStudioTheme.clay)
                shortReviewMetric("draft", max(0, draftCount), QuipslyStudioTheme.creek)
                if missingKeptExportCount > 0 {
                    shortReviewMetric("needs export", missingKeptExportCount, QuipslyStudioTheme.honey)
                }
            }

            HStack(spacing: 6) {
                Button {
                    selectNextShortReviewCandidate(status: nil)
                } label: {
                    Label("Next candidate", systemImage: "arrow.right.circle")
                        .frame(maxWidth: .infinity)
                }
                .buttonStyle(.borderedProminent)
                .controlSize(.small)
                .tint(QuipslyStudioTheme.creek)
                .disabled(queue.isEmpty)
                .help(queue.isEmpty
                      ? "No shorts are queued yet."
                      : "Select the next draft/refine short, switch to 9:16, and scrub the shared playhead to its recipe.")

                Button {
                    generateReviewedSocialQueueForAgent(directoryPath: nil, basename: nil)
                } label: {
                    Label(
                        socialPublicationQueueStatus == "generating" ? "Generating" : "Generate queue",
                        systemImage: "shippingbox.and.arrow.backward"
                    )
                    .frame(maxWidth: .infinity)
                }
                .buttonStyle(.borderedProminent)
                .controlSize(.small)
                .disabled(!canGenerate)
                .help(reviewedSocialQueueGenerateHelp(keepCount: keepCount, missingExports: missingKeptExportCount))

                Button {
                    copyReviewedSocialQueueCommand(command)
                } label: {
                    Label("Copy command", systemImage: "terminal")
                }
                .buttonStyle(.bordered)
                .controlSize(.small)
                .disabled(keepCount == 0)
                .help(keepCount == 0 ? "Mark at least one short Keep first." : "Copy the fallback CLI command for kept shorts.")

                Button {
                    leftWorkbenchMode = .shorts
                    requestTimelineFocus(reason: "Review kept/refine/reject short recipes")
                    updateAgentState()
                } label: {
                    Label("Review", systemImage: "rectangle.stack")
                }
                .buttonStyle(.bordered)
                .controlSize(.small)
            }

            let latestQueuePath = currentSocialPublicationQueueOutputPath()
            if !latestQueuePath.isEmpty {
                Text("Latest queue: \(latestQueuePath)")
                    .font(.caption2.monospaced())
                    .foregroundStyle(QuipslyStudioTheme.moss)
                    .lineLimit(2)
                    .truncationMode(.middle)
                HStack(spacing: 6) {
                    Button {
                        revealShortExport(path: latestQueuePath)
                    } label: {
                        Label("Reveal queue", systemImage: "folder")
                    }
                    Button {
                        copyShortExportPath(latestQueuePath)
                    } label: {
                        Label("Copy path", systemImage: "doc.on.doc")
                    }
                }
                .buttonStyle(.bordered)
                .controlSize(.small)
                .help("Open or copy the latest reviewed social queue folder.")
            } else if !socialPublicationQueueErrorMessage.isEmpty {
                Text(socialPublicationQueueErrorMessage)
                    .font(.caption2)
                    .foregroundStyle(QuipslyStudioTheme.honey)
                    .fixedSize(horizontal: false, vertical: true)
            } else if missingKeptExportCount > 0 {
                Text("\(missingKeptExportCount) kept short(s) need a 9:16 export before the reviewed social queue can be generated.")
                    .font(.caption2)
                    .foregroundStyle(QuipslyStudioTheme.honey)
                    .fixedSize(horizontal: false, vertical: true)
            }

            Text(keepCount > 0
                 ? "Next: generate the queue here. Only kept shorts are copied; source videos and drafts stay untouched."
                 : "The queue builder intentionally ignores drafts. That protects us from accidentally publishing machine-picked clips.")
                .font(.caption2)
                .foregroundStyle(.secondary)
                .fixedSize(horizontal: false, vertical: true)
        }
        .padding(9)
        .background(QuipslyStudioTheme.recipeCardGradient)
        .overlay(
            RoundedRectangle(cornerRadius: 14, style: .continuous)
                .stroke(QuipslyStudioTheme.moss.opacity(0.18), lineWidth: 1)
        )
        .clipShape(RoundedRectangle(cornerRadius: 14, style: .continuous))
        .accessibilityIdentifier("quipsly.workbench.shorts.reviewPipeline")
    }

    private func shortReviewMetric(_ label: String, _ count: Int, _ color: Color) -> some View {
        VStack(spacing: 2) {
            Text("\(count)")
                .font(.caption.monospacedDigit())
                .fontWeight(.black)
                .foregroundStyle(color)
            Text(label.uppercased())
                .font(.caption2)
                .fontWeight(.black)
                .tracking(0.6)
                .foregroundStyle(.secondary)
        }
        .frame(maxWidth: .infinity)
        .padding(.vertical, 5)
        .background(color.opacity(0.10))
        .clipShape(RoundedRectangle(cornerRadius: 10, style: .continuous))
    }

    private func reviewedSocialQueueGenerateHelp(keepCount: Int, missingExports: Int) -> String {
        if keepCount == 0 {
            return "Mark at least one short Keep first."
        }
        if missingExports > 0 {
            return "Export kept short(s) before generating the reviewed social queue."
        }
        return "Generate a derivative-only social upload queue from kept shorts."
    }

    private func reviewedSocialQueueCommand() -> String {
        let session = normalizedActiveSessionName()
        let safeSession = sanitizedExportBasename(session.isEmpty ? "quipsly-session" : session)
        let episodeTitle = projectStore.activeSequence?.title ?? "High Ground Odyssey Episode"
        let output = "\(NSHomeDirectory())/Movies/QuipslyExports/SocialQueues/\(safeSession)-reviewed-keeps"
        return "script/agentctl.sh reviewed-social-queue --session \(shellQuote(session)) --output \(shellQuote(output)) --basename \(shellQuote("\(safeSession)-reviewed-keeps")) --episode-title \(shellQuote(episodeTitle)) --include-status keep"
    }

    private func copyReviewedSocialQueueCommand(_ command: String) {
        #if os(macOS)
        NSPasteboard.general.clearContents()
        NSPasteboard.general.setString(command, forType: .string)
        #endif
        lastMediaAction = "Copied reviewed social queue command"
        updateAgentState()
    }

    private func shellQuote(_ value: String) -> String {
        "'\(value.replacingOccurrences(of: "'", with: "'\\''"))'"
    }

    private func shortStatusColor(_ status: String) -> Color {
        switch status.lowercased() {
        case "ready", "approved", "keep", "kept":
            return QuipslyStudioTheme.moss
        case "needs-captions", "needs-review", "refine", "revise":
            return QuipslyStudioTheme.honey
        case "blocked", "reject", "rejected":
            return QuipslyStudioTheme.clay
        default:
            return QuipslyStudioTheme.creek
        }
    }

