            RoundedRectangle(cornerRadius: 14, style: .continuous)
                .stroke(color.opacity(0.18), lineWidth: 1)
        )
        .clipShape(RoundedRectangle(cornerRadius: 14, style: .continuous))
    }

    private func deliveryStatusColor(_ status: String) -> Color {
        switch status {
        case "ready":
            return .green
        case "blocked":
            return .orange
        case "planned":
            return .blue
        default:
            return .secondary
        }
    }

    private func deliveryStatusIcon(_ status: String) -> String {
        switch status {
        case "ready":
            return "checkmark.seal.fill"
        case "blocked":
            return "exclamationmark.triangle.fill"
        case "planned":
            return "hammer.fill"
        default:
            return "circle.dashed"
        }
    }

    private func deliveryStatusLabel(_ status: String) -> String {
        switch status {
        case "ready":
            return "READY"
        case "blocked":
            return "BLOCKED"
        case "planned":
            return "PLANNED"
        default:
            return status.uppercased()
        }
    }

