    private func episodeSpineBridgePanel(sequence: MediaSequence?) -> some View {
        let spine = episodeSpinePayload(for: sequence)
        let nest = spine["nest"] as? [String: Any] ?? [:]
        let studio = spine["studio"] as? [String: Any] ?? [:]
        let tower = spine["tower"] as? [String: Any] ?? [:]
        let status = spine["status"] as? String ?? "unknown"
        let nextAction = spine["nextAction"] as? String ?? ""

        return VStack(alignment: .leading, spacing: 8) {
            HStack(spacing: 8) {
                Image(systemName: "point.3.connected.trianglepath.dotted")
                    .foregroundStyle(QuipslyStudioTheme.honey)
                VStack(alignment: .leading, spacing: 2) {
                    Text("Episode Spine")
                        .font(.caption)
                        .fontWeight(.black)
                    Text("Vertical slice: Nest context → Studio edit → Tower handoff.")
                        .font(.caption2)
                        .foregroundStyle(QuipslyStudioTheme.sage)
                }
                Spacer()
                Text(status.replacingOccurrences(of: "-", with: " "))
                    .font(.caption2)
                    .fontWeight(.black)
                    .padding(.horizontal, 8)
                    .padding(.vertical, 5)
                    .background(QuipslyStudioTheme.panelLift.opacity(0.32))
                    .clipShape(Capsule())
            }

            HStack(spacing: 6) {
                spineStageCard(
                    title: "Nest",
                    value: "\(nest["blockCount"] as? Int ?? 0) blocks",
                    detail: (nest["status"] as? String ?? "unknown").replacingOccurrences(of: "-", with: " "),
                    color: QuipslyStudioTheme.moss
                )
                spineStageCard(
                    title: "Studio",
                    value: "\(studio["shortRecipeCount"] as? Int ?? 0) shorts",
                    detail: (studio["status"] as? String ?? "unknown").replacingOccurrences(of: "-", with: " "),
                    color: QuipslyStudioTheme.creek
                )
                spineStageCard(
                    title: "Tower",
                    value: "\(tower["readyLaneCount"] as? Int ?? 0)/\(tower["laneCount"] as? Int ?? 0) lanes",
                    detail: (tower["status"] as? String ?? "unknown").replacingOccurrences(of: "-", with: " "),
                    color: QuipslyStudioTheme.honey
                )
            }

            verticalSliceReviewStackPanel(sequence: sequence, nest: nest, studio: studio, tower: tower)

            Text(nextAction)
                .font(.caption2)
                .foregroundStyle(QuipslyStudioTheme.moonMilk)
                .fixedSize(horizontal: false, vertical: true)
        }
        .padding(10)
        .background(
            RoundedRectangle(cornerRadius: 16, style: .continuous)
                .fill(QuipslyStudioTheme.canopy.opacity(0.30))
                .overlay(
                    RoundedRectangle(cornerRadius: 16, style: .continuous)
                        .stroke(QuipslyStudioTheme.honey.opacity(0.22), lineWidth: 1)
                )
        )
        .accessibilityIdentifier("quipsly.episode-spine.bridge")
    }

    private func verticalSliceReviewStackPanel(
        sequence: MediaSequence?,
        nest: [String: Any],
        studio: [String: Any],
        tower: [String: Any]
    ) -> some View {
        let nestWriting = nestWritingHandoffSummaryPayload()
        let receiptCockpit = publicationReceiptCockpitPayload(for: sequence)
        let receiptSummary = receiptCockpit["summary"] as? [String: Any] ?? [:]
        let missingReceiptCount = receiptSummary["missingCount"] as? Int
            ?? (tower["missingReceiptCount"] as? Int)
            ?? 0
        let capturedReceiptCount = receiptSummary["capturedCount"] as? Int ?? 0
        let nextReceipt = receiptCockpit["nextReceipt"] as? [String: Any] ?? [:]
        let nextReceiptLabel = nextReceipt["displayLabel"] as? String ?? ""
        let nestAuthoredCount = nestWriting["authoredBlockCount"] as? Int
            ?? nest["authoredBlockCount"] as? Int
            ?? 0
        let nestAgentAuthoredCount = nestWriting["agentAuthoredBlockCount"] as? Int
            ?? nest["agentAuthoredBlockCount"] as? Int
            ?? 0
        let nestReviewCount = nestWriting["reviewQueueCount"] as? Int ?? 0
        let studioShortCount = studio["shortRecipeCount"] as? Int ?? 0
        let studioStatus = studio["status"] as? String ?? "unknown"
        let towerStatus = tower["status"] as? String ?? "unknown"
        let receiptDetail = missingReceiptCount > 0
            ? "\(missingReceiptCount) receipt(s) still prove publication"
            : "all tracked receipts captured"

        return VStack(alignment: .leading, spacing: 8) {
            HStack(spacing: 7) {
                Image(systemName: "list.clipboard.fill")
                    .foregroundStyle(QuipslyStudioTheme.creek)
                VStack(alignment: .leading, spacing: 1) {
                    Text("Vertical slice review stack")
                        .font(.caption2)
                        .fontWeight(.black)
                        .foregroundStyle(QuipslyStudioTheme.moonMilk)
                    Text("Review each lens without inventing a second source of truth.")
                        .font(.caption2)
                        .foregroundStyle(QuipslyStudioTheme.sage)
                }
                Spacer()
            }

            HStack(spacing: 6) {
                reviewStackLensCard(
                    title: "Nest review",
                    value: "\(nestAuthoredCount) authored",
                    detail: nestReviewCount > 0 ? "\(nestReviewCount) writing item(s) to review" : "authorship/context visible",
                    color: nestReviewCount > 0 ? QuipslyStudioTheme.honey : QuipslyStudioTheme.moss
                )
                reviewStackLensCard(
                    title: "Studio review",
                    value: "\(studioShortCount) shorts",
                    detail: studioStatus.replacingOccurrences(of: "-", with: " "),
                    color: studioStatus == "render-ready" ? QuipslyStudioTheme.moss : QuipslyStudioTheme.creek
                )
                reviewStackLensCard(
                    title: "Tower review",
                    value: "\(capturedReceiptCount) captured",
                    detail: receiptDetail,
                    color: missingReceiptCount == 0 && towerStatus == "publication-proof-complete"
                        ? QuipslyStudioTheme.moss
                        : QuipslyStudioTheme.honey
                )
            }

            HStack(alignment: .top, spacing: 8) {
                Image(systemName: "sparkles.rectangle.stack.fill")
                    .font(.caption)
                    .foregroundStyle(QuipslyStudioTheme.lichen)
                    .padding(.top, 1)
                VStack(alignment: .leading, spacing: 2) {
                    Text("Creative operator rule")
                        .font(.caption2)
                        .fontWeight(.black)
                        .foregroundStyle(QuipslyStudioTheme.moonMilk)
                    Text(nestAgentAuthoredCount > 0
                         ? "\(nestAgentAuthoredCount) agent-first-pass block(s) are real reviewable work, not placeholder by default. The boundary is visible provenance, canon state, and publication receipts."
                         : "Codex and Quipslys may create serious first-pass writing, edits, shorts, captions, and release copy. The boundary is hidden mutation, not authorship.")
                        .font(.caption2)
                        .foregroundStyle(QuipslyStudioTheme.sage)
                        .fixedSize(horizontal: false, vertical: true)
                }
            }
            .padding(8)
            .background(QuipslyStudioTheme.lichen.opacity(0.08))
            .clipShape(RoundedRectangle(cornerRadius: 10, style: .continuous))
            .accessibilityIdentifier("quipsly.vertical-slice.creative-operator-rule")

            if !nextReceiptLabel.isEmpty {
                Text("Next receipt target: \(nextReceiptLabel)")
                    .font(.caption2)
                    .fontWeight(.semibold)
                    .foregroundStyle(QuipslyStudioTheme.moonMilk.opacity(0.86))
                    .lineLimit(2)
            }

            Text("Generated START-HERE, Nest, Studio, and Tower review pages are projections over this same state. They help humans and agents inspect the loop; they do not approve, export, publish, or mutate anything.")
                .font(.caption2)
                .foregroundStyle(QuipslyStudioTheme.sage)
                .fixedSize(horizontal: false, vertical: true)
        }
        .padding(9)
        .background(Color.black.opacity(0.14))
        .overlay(
            RoundedRectangle(cornerRadius: 13, style: .continuous)
                .stroke(QuipslyStudioTheme.creek.opacity(0.16), lineWidth: 1)
        )
        .clipShape(RoundedRectangle(cornerRadius: 13, style: .continuous))
        .accessibilityIdentifier("quipsly.vertical-slice.review-stack")
    }

    private func reviewStackLensCard(title: String, value: String, detail: String, color: Color) -> some View {
        VStack(alignment: .leading, spacing: 3) {
            Text(title.uppercased())
                .font(.caption2)
                .fontWeight(.black)
                .foregroundStyle(color)
            Text(value)
                .font(.caption2.monospacedDigit())
                .fontWeight(.black)
                .foregroundStyle(QuipslyStudioTheme.moonMilk)
            Text(detail)
                .font(.caption2)
                .foregroundStyle(QuipslyStudioTheme.sage)
                .lineLimit(2)
        }
        .padding(7)
        .frame(maxWidth: .infinity, alignment: .leading)
        .background(color.opacity(0.08))
        .clipShape(RoundedRectangle(cornerRadius: 10, style: .continuous))
    }

    private func spineStageCard(title: String, value: String, detail: String, color: Color) -> some View {
        VStack(alignment: .leading, spacing: 3) {
            Text(title.uppercased())
                .font(.caption2)
                .fontWeight(.black)
                .foregroundStyle(color)
            Text(value)
                .font(.caption)
                .fontWeight(.semibold)
                .foregroundStyle(QuipslyStudioTheme.moonMilk)
            Text(detail)
                .font(.caption2)
                .foregroundStyle(QuipslyStudioTheme.sage)
                .lineLimit(2)
        }
        .padding(8)
        .frame(maxWidth: .infinity, alignment: .leading)
        .background(Color.black.opacity(0.16))
        .clipShape(RoundedRectangle(cornerRadius: 12, style: .continuous))
    }

