    private func towerNestWritingContextPanel(sequence: MediaSequence?) -> some View {
        let handoff = nestWritingHandoffSummaryPayload()
        let status = handoff["status"] as? String ?? "unknown"
        let packetStatus = handoff["packetStatus"] as? String ?? "idle"
        let packetPath = handoff["packetOutputPath"] as? String ?? ""
        let authoredCount = handoff["authoredBlockCount"] as? Int ?? 0
        let reviewCount = handoff["reviewQueueCount"] as? Int ?? 0
        let sourceCount = handoff["sourceContextSummaryCount"] as? Int ?? 0
        let sourceStatus = handoff["sourceContextStatus"] as? String ?? "unknown"
        let nextAction = handoff["nextAction"] as? String ?? ""
        let selectedAuthorship = handoff["selectedAuthorship"] as? String ?? ""
        let selectedReviewStatus = handoff["selectedReviewStatus"] as? String ?? ""
        let color = towerNestWritingStatusColor(status)
        let hasPath = !packetPath.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty

        return VStack(alignment: .leading, spacing: 9) {
            HStack(alignment: .top, spacing: 8) {
                Image(systemName: towerNestWritingStatusIcon(status))
                    .font(.headline)
                    .foregroundStyle(color)
                    .frame(width: 28, height: 28)
                    .background(color.opacity(0.13))
                    .clipShape(Circle())

                VStack(alignment: .leading, spacing: 2) {
                    Text("Nest writing context")
                        .font(.caption)
                        .fontWeight(.black)
                    Text("Tower release prep now sees manuscript work, source context, authorship, and review state as part of the same handoff.")
                        .font(.caption2)
                        .foregroundStyle(QuipslyStudioTheme.sage)
                        .fixedSize(horizontal: false, vertical: true)
                }

                Spacer()

                Text(status.replacingOccurrences(of: "-", with: " "))
                    .font(.caption2)
                    .fontWeight(.black)
                    .foregroundStyle(color)
                    .padding(.horizontal, 8)
                    .padding(.vertical, 5)
                    .background(color.opacity(0.12))
                    .clipShape(Capsule())
            }

            HStack(spacing: 6) {
                miniTruthPill("\(authoredCount)", "authored", QuipslyStudioTheme.creek)
                miniTruthPill("\(sourceCount)", "source ctx", sourceStatus == "available" ? QuipslyStudioTheme.moss : QuipslyStudioTheme.honey)
                miniTruthPill("\(reviewCount)", "review", reviewCount > 0 ? QuipslyStudioTheme.honey : QuipslyStudioTheme.moss)
            }

            if !selectedAuthorship.isEmpty || !selectedReviewStatus.isEmpty {
                Text("Selected work: \(selectedAuthorship.replacingOccurrences(of: "-", with: " ")) / \(selectedReviewStatus.replacingOccurrences(of: "-", with: " "))")
                    .font(.caption2)
                    .fontWeight(.semibold)
                    .foregroundStyle(QuipslyStudioTheme.moonMilk.opacity(0.88))
                    .fixedSize(horizontal: false, vertical: true)
            }

            Text(nextAction)
                .font(.caption2)
                .foregroundStyle(QuipslyStudioTheme.moonMilk.opacity(0.84))
                .fixedSize(horizontal: false, vertical: true)

            HStack(spacing: 7) {
                Button {
                    generateNestWritingPacketForAgent(directoryPath: nil, basename: nil)
                } label: {
                    Label(packetStatus == "generating" ? "Writing" : "Generate writing packet", systemImage: "doc.text.magnifyingglass")
                }
                .buttonStyle(.borderedProminent)
                .controlSize(.small)
                .disabled(packetStatus == "generating")
                .help("Generate the Nest manuscript/authorship handoff used by Tower release prep.")

                Button {
                    generateVerticalSlicePacketForAgent(directoryPath: nil, basename: nil)
                } label: {
                    Label("Refresh full handoff", systemImage: "point.3.connected.trianglepath.dotted")
                }
                .buttonStyle(.bordered)
                .controlSize(.small)
                .disabled(sequence == nil || verticalSlicePacketStatus == "generating")
                .help("Regenerate the combined Nest -> Studio -> Tower packet with the writing context embedded.")

                Button {
                    copyPublishReceiptText(
                        packetPath,
                        successMessage: "Copied Nest writing packet path"
                    )
                } label: {
                    Label("Copy path", systemImage: "doc.on.doc")
                }
                .buttonStyle(.bordered)
                .controlSize(.small)
                .disabled(!hasPath)
            }
        }
        .padding(10)
        .background(
            RoundedRectangle(cornerRadius: 16, style: .continuous)
                .fill(color.opacity(0.08))
                .overlay(
                    RoundedRectangle(cornerRadius: 16, style: .continuous)
                        .stroke(color.opacity(0.22), lineWidth: 1)
                )
        )
        .accessibilityIdentifier("quipsly.tower.nest-writing-context")
    }

    private func towerNestWritingStatusColor(_ status: String) -> Color {
        switch status {
        case "ready-with-writing-packet":
            return QuipslyStudioTheme.moss
        case "ready-needs-writing-packet", "generating":
            return QuipslyStudioTheme.honey
        case "needs-source-context":
            return QuipslyStudioTheme.clay
        case "needs-authored-work":
            return QuipslyStudioTheme.creek
        default:
            return QuipslyStudioTheme.sage
        }
    }

    private func towerNestWritingStatusIcon(_ status: String) -> String {
        switch status {
        case "ready-with-writing-packet":
            return "checkmark.seal.fill"
        case "ready-needs-writing-packet":
            return "doc.badge.clock"
        case "generating":
            return "arrow.triangle.2.circlepath"
        case "needs-source-context":
            return "leaf.arrow.triangle.circlepath"
        case "needs-authored-work":
            return "square.and.pencil"
        default:
            return "doc.text.magnifyingglass"
        }
    }

    private func publicationMissionControlPanel(records: [PublishReceiptRecord]) -> some View {
        let episodeRecord = records.first { $0.deliveryLaneId == "episode-16x9-master" }
        let episodeReady = episodeRecord.map { publishRecordArtifactReady($0) && publishRecordCopyReady($0) } ?? false
        let episodeReceiptCaptured = episodeRecord.map { publishRecordReceiptCaptured($0) } ?? false
        let socialReady = effectiveSocialPublicationQueueClipCount() > 0 && !effectiveSocialPublicationQueueManifestPath().isEmpty
        let podcastReady = podcastReadyPacketIsOperatorReady()
        let receiptSummary = publicationReceiptCompletionSummary(for: projectStore.activeSequence)
        let publicationComplete = receiptSummary["publicationComplete"] as? Bool ?? false
        let captured = receiptSummary["receiptCapturedCount"] as? Int ?? 0
        let remaining = receiptSummary["receiptRemainingCount"] as? Int ?? records.count
        let total = receiptSummary["receiptTotalCount"] as? Int ?? records.count
        let readyLaneCount = [episodeReady, socialReady, podcastReady].filter { $0 }.count
        let releaseFolderPath = currentPublicationReleaseFolderPath()
        let headline = projectStore.activeSequence == nil
            ? "Load an episode session before publishing."
            : (records.isEmpty
                ? "Run Full prep to create the release queue."
                : (publicationComplete
                    ? "Publication proof is complete."
                    : (readyLaneCount == 3
                        ? "Ready to post or schedule. Capture receipts as you go."
                        : "Finish the missing handoff artifacts before platform posting.")))

        return VStack(alignment: .leading, spacing: 9) {
            HStack(alignment: .top, spacing: 10) {
                Image(systemName: "dot.scope")
                    .font(.headline)
                    .foregroundStyle(QuipslyStudioTheme.honey)
                    .frame(width: 30, height: 30)
                    .background(QuipslyStudioTheme.honey.opacity(0.14))
                    .clipShape(Circle())

                VStack(alignment: .leading, spacing: 2) {
                    Text("Publication mission control")
                        .font(.caption)
                        .fontWeight(.black)
                    Text(headline)
                        .font(.caption2)
                        .foregroundStyle(.secondary)
                        .fixedSize(horizontal: false, vertical: true)
                }

                Spacer(minLength: 8)

                HStack(spacing: 6) {
                    publishStatPill("lanes ready", readyLaneCount, readyLaneCount == 3 ? QuipslyStudioTheme.moss : QuipslyStudioTheme.honey)
                    publishStatPill("receipts", captured, publicationComplete ? QuipslyStudioTheme.moss : QuipslyStudioTheme.honey)
                    publishStatPill("missing", remaining, remaining == 0 ? QuipslyStudioTheme.moss : QuipslyStudioTheme.clay)
                }

                Button {
                    copyPublicationMissionControlJSON()
                } label: {
                    Label("Copy mission", systemImage: "doc.on.doc")
                }
                .controlSize(.small)
                .help("Copy the full read-only mission control JSON for Codex, another agent, or a manual publishing handoff.")
            }

            HStack(spacing: 7) {
                Button {
                    revealPublicationArtifactPath(releaseFolderPath, label: "current release folder")
                } label: {
                    Label("Reveal release", systemImage: "folder")
                }
                .controlSize(.small)
                .disabled(releaseFolderPath.isEmpty || !FileManager.default.fileExists(atPath: releaseFolderPath))
                .help("Reveal the best available release handoff folder: full release folder first, then cockpit/upload/publish packet folders.")

                Button {
                    copyMissingPublicationReceipts(records)
                } label: {
                    Label("Copy missing receipts", systemImage: "exclamationmark.bubble")
                }
                .controlSize(.small)
                .disabled(records.isEmpty)
                .help("Copy a plain-English checklist of missing publication proof and exact receipt-capture commands.")

                Button {
                    importSocialMasterQueueFromAgent(path: episode1FinalSocialPostingPacketManifestPath)
                } label: {
                    Label(socialReady ? "Reload E1 socials" : "Load E1 socials", systemImage: "square.grid.3x3.square")
                }
                .controlSize(.small)
                .disabled(!FileManager.default.fileExists(atPath: episode1FinalSocialPostingPacketManifestPath))
                .help("Load the current Episode 1 final 31-clip social posting packet into Mission Control. This is read-only review state; it does not upload or alter source media.")

                Button {
                    openSocialMasterQueueCandidateClip()
                } label: {
                    Label("Open selected short", systemImage: "play.rectangle")
                }
                .controlSize(.small)
                .disabled(!socialReady || selectedSocialMasterQueueCandidate() == nil)
                .help("Open the selected derivative social short for watch-once review before posting.")

                Button {
                    copySelectedSocialPostingPacketJSON()
                } label: {
                    Label("Copy social packet", systemImage: "paperplane")
                }
                .controlSize(.small)
                .disabled(!socialReady || selectedSocialMasterQueueCandidate() == nil)
                .help("Copy the selected social posting packet JSON: clip path, platform copy, captions, receipt checklist, and proof rule.")
            }

            LazyVGrid(columns: [GridItem(.adaptive(minimum: 210), spacing: 8)], spacing: 8) {
                publicationMissionDeliverableCard(
                    title: "16:9 episode",
                    destination: "YouTube + Patreon",
                    status: episodeReady ? (episodeReceiptCaptured ? "Receipt captured" : "Ready to post") : "Needs Full prep",
                    detail: episodeRecord?.artifactPath ?? "Export the 16:9 master and generate the publish ledger.",
                    color: episodeReady ? QuipslyStudioTheme.moss : QuipslyStudioTheme.honey,
                    icon: "play.rectangle.fill",
                    nextAction: episodeReady ? "Upload/schedule, then capture receipt." : "Run Full prep."
                )

                publicationMissionDeliverableCard(
                    title: "9:16 shorts",
                    destination: "Cuts + Reels + LinkedIn",
                    status: socialReady ? "\(socialMasterQueueClipCount) clips loaded" : "Needs social packet",
                    detail: !effectiveSocialPostingRunPacketPath().trimmingCharacters(in: .whitespacesAndNewlines).isEmpty
                        ? effectiveSocialPostingRunPacketPath()
                        : (socialMasterQueueOutputPath.isEmpty ? "Generate or load the social master queue." : socialMasterQueueOutputPath),
                    color: socialReady ? QuipslyStudioTheme.creek : QuipslyStudioTheme.honey,
                    icon: "rectangle.portrait.on.rectangle.portrait.fill",
                    nextAction: socialReady
                        ? (effectiveSocialPostingRunPacketPath().trimmingCharacters(in: .whitespacesAndNewlines).isEmpty
                           ? "Select a candidate and generate a posting run packet."
                           : "Work platform packets, then capture receipts.")
                        : "Load the Episode 1 final social packet."
                )

                publicationMissionDeliverableCard(
                    title: "Podcast audio",
                    destination: "Spotify + Apple",
                    status: podcastReady ? "Ready packet generated" : "Needs podcast ready",
                    detail: podcastReadyPacketOutputPath.isEmpty ? "Generate Podcast Packet, then Podcast Ready." : podcastReadyPacketOutputPath,
                    color: podcastReady ? QuipslyStudioTheme.moss : QuipslyStudioTheme.honey,
                    icon: "dot.radiowaves.left.and.right",
                    nextAction: podcastReady ? "Listen-check, upload via host/RSS, capture URLs." : "Generate Podcast Ready."
                )
            }

            HStack(alignment: .top, spacing: 8) {
                Image(systemName: total > 0 && remaining == 0 ? "checkmark.seal.fill" : "exclamationmark.triangle.fill")
                    .foregroundStyle(total > 0 && remaining == 0 ? QuipslyStudioTheme.moss : QuipslyStudioTheme.honey)
                Text(total == 0
                     ? "Receipt proof starts after the publish ledger exists. Until then, nothing should be called published."
                     : "\(captured) of \(total) platform receipt(s) captured. \(remaining) still need public/scheduled URLs or provider IDs.")
                    .font(.caption2)
                    .foregroundStyle(.secondary)
                    .fixedSize(horizontal: false, vertical: true)
            }
        }
        .padding(9)
        .background(QuipslyStudioTheme.selectedRecipeGradient)
        .overlay(
            RoundedRectangle(cornerRadius: 14, style: .continuous)
                .stroke(QuipslyStudioTheme.honey.opacity(0.16), lineWidth: 1)
        )
        .clipShape(RoundedRectangle(cornerRadius: 14, style: .continuous))
    }

    private func publicationMissionDeliverableCard(
        title: String,
        destination: String,
        status: String,
        detail: String,
        color: Color,
        icon: String,
        nextAction: String
    ) -> some View {
        VStack(alignment: .leading, spacing: 6) {
