    private func publicationReceiptProofQuickActions(records: [PublishReceiptRecord]) -> some View {
        let total = records.count
        let captured = records.filter { publishRecordReceiptCaptured($0) }.count
        let remaining = max(0, total - captured)
        let complete = total > 0 && remaining == 0
        let color: Color = complete ? .green : (total == 0 ? .orange : .yellow)
        let receiptLogPath = publicationReceiptLogOutputPath.trimmingCharacters(in: .whitespacesAndNewlines)
        let cockpitPath = publicationCockpitOutputPath.trimmingCharacters(in: .whitespacesAndNewlines)
        let publishPacketPath = publishPacketOutputPath.trimmingCharacters(in: .whitespacesAndNewlines)

        return HStack(alignment: .center, spacing: 7) {
            Image(systemName: complete ? "checkmark.shield.fill" : "checklist")
                .foregroundStyle(color)
            VStack(alignment: .leading, spacing: 2) {
                Text("Publication proof")
                    .font(.caption2)
                    .fontWeight(.black)
                Text(total == 0
                     ? "No publish ledger yet. Run Full prep before receipt capture."
                     : "\(captured)/\(total) receipt(s) captured. \(remaining) still need public/scheduled URLs or provider ids.")
                    .font(.caption2)
                    .foregroundStyle(.secondary)
                    .lineLimit(2)
            }
            Spacer(minLength: 8)
            if total > 0 {
                Text(complete ? "complete" : "\(remaining) open")
                    .font(.caption2)
                    .fontWeight(.black)
                    .foregroundStyle(color)
                    .padding(.horizontal, 7)
                    .padding(.vertical, 4)
                    .background(color.opacity(0.12))
                    .clipShape(Capsule())
            }
            #if os(macOS)
            Button("Receipt log") {
                revealPublicationArtifactPath(receiptLogPath, label: "publication receipt log")
            }
            .controlSize(.mini)
            .disabled(receiptLogPath.isEmpty || !FileManager.default.fileExists(atPath: receiptLogPath))
            .help("Reveal the receipt log that proves what was uploaded, scheduled, or published.")

            Button("Checklist") {
                revealPublicationArtifactPath(publishPacketPath, label: "publish packet checklist")
            }
            .controlSize(.mini)
            .disabled(publishPacketPath.isEmpty || !FileManager.default.fileExists(atPath: publishPacketPath))
            .help("Reveal the publish packet/checklist folder for manual posting work.")

            Button("Cockpit") {
                revealPublicationArtifactPath(cockpitPath, label: "publication cockpit")
            }
            .controlSize(.mini)
            .disabled(cockpitPath.isEmpty || !FileManager.default.fileExists(atPath: cockpitPath))
            .help("Reveal the cockpit summary that survives outside the running app.")

            Button("Copy missing") {
                copyMissingPublicationReceipts(records)
            }
            .controlSize(.mini)
            .disabled(total == 0)
            .help("Copy a plain-English checklist of publish receipts that still need platform URLs or provider ids.")
            #endif
        }
        .padding(7)
        .background(color.opacity(0.08))
        .overlay(
            RoundedRectangle(cornerRadius: 9)
                .stroke(color.opacity(0.16), lineWidth: 1)
        )
        .clipShape(RoundedRectangle(cornerRadius: 9))
    }

    private func copyMissingPublicationReceipts(_ records: [PublishReceiptRecord]) {
        let checklist = missingPublicationReceiptsChecklist(records: records)
        let missing = records.filter { !publishRecordReceiptCaptured($0) }
        #if os(macOS)
        NSPasteboard.general.clearContents()
        NSPasteboard.general.setString(checklist, forType: .string)
        #endif
        lastMediaAction = missing.isEmpty
            ? "Copied publication receipt proof summary"
            : "Copied \(missing.count) missing publication receipt(s)"
        updateAgentState()
    }

    private func missingPublicationReceiptsChecklist(records: [PublishReceiptRecord]) -> String {
        let missing = records.filter { !publishRecordReceiptCaptured($0) }
        if records.isEmpty {
            return [
                "# Missing publication receipts",
                "",
                "No publish ledger records exist yet.",
                "Run Full prep to generate the publish ledger, upload packet bundle, ready packets, and publication cockpit before receipt capture."
            ].joined(separator: "\n")
        }
        if missing.isEmpty {
            return [
                "# Missing publication receipts",
                "",
                "All \(records.count) publish receipt record(s) have captured proof.",
                "Keep the receipt log with the release folder before archiving the release."
            ].joined(separator: "\n")
        }

        let lines = [
            "# Missing publication receipts",
            "",
            "\(missing.count) of \(records.count) publish receipt record(s) still need public/scheduled URLs or provider ids.",
            ""
        ] + missing.enumerated().flatMap { index, record -> [String] in
            [
                "\(index + 1). \(record.platform) / \(record.deliveryLaneId)",
                "   - Current status: \(record.publishStatus.isEmpty ? "not set" : record.publishStatus)",
                "   - Artifact: \(record.artifactPath.isEmpty ? "not generated yet" : record.artifactPath)",
                "   - Capture command:",
                "     \(publicationReceiptCaptureCommand(for: record))",
                ""
            ]
        }
        return lines.joined(separator: "\n")
    }

    private func publicationReceiptCaptureCommand(for record: PublishReceiptRecord) -> String {
        "script/agentctl.sh publish-receipt-update \(record.id.uuidString) published <public-url> <provider-id> \"manual receipt\""
    }

    private func missingPublicationReceiptRows(records: [PublishReceiptRecord]) -> [[String: Any]] {
        records.filter { !publishRecordReceiptCaptured($0) }.map { record in
            [
                "id": record.id.uuidString,
                "platform": record.platform,
                "deliveryLaneId": record.deliveryLaneId,
                "format": record.format,
                "artifactType": record.artifactType,
                "artifactPath": record.artifactPath,
                "artifactExists": publishRecordArtifactExists(record),
                "publishStatus": record.publishStatus,
                "publicURL": record.publicURL,
                "providerReceiptId": record.providerReceiptId,
                "receiptCaptured": publishRecordReceiptCaptured(record),
                "captureCommand": publicationReceiptCaptureCommand(for: record)
            ] as [String: Any]
        }
    }

    private func missingPublicationReceiptsPayload(for sequence: MediaSequence?) -> [String: Any] {
        let records = sequence?.publishReceipts ?? []
        let missingRows = missingPublicationReceiptRows(records: records)
        let completion = publicationReceiptCompletionSummary(for: sequence)
        let status: String
        if records.isEmpty {
            status = "no-publish-ledger"
        } else if missingRows.isEmpty {
            status = "complete"
        } else {
            status = "missing-receipts"
        }

        return [
            "model": "quipsly-missing-publication-receipts",
            "version": "2026-06-17.missing-publication-receipts.v1",
            "status": status,
            "publicationPhase": completion["publicationPhase"] ?? "ready-for-human-review",
            "publicationComplete": completion["publicationComplete"] ?? false,
            "totalCount": records.count,
            "capturedCount": completion["receiptCapturedCount"] ?? 0,
            "missingCount": missingRows.count,
            "missingReceipts": missingRows,
            "checklistMarkdown": missingPublicationReceiptsChecklist(records: records),
            "sourceState": "publicationReadyHandoff.receiptProof",
            "receiptProofCommand": "script/agentctl.sh missing-publication-receipts",
            "nextAction": records.isEmpty
                ? "Run Full prep to generate the publish ledger and upload packet bundle."
                : (missingRows.isEmpty
                    ? "Publication proof is complete. Keep the receipt log with the release folder."
                    : "Capture each public/scheduled URL or provider id with the listed publish-receipt-update command.")
        ]
    }

