                }

                if let selectedCandidate = selectedSocialMasterQueueCandidate() {
                    VStack(alignment: .leading, spacing: 6) {
                        Text("Selected for review")
                            .font(.caption2)
                            .fontWeight(.bold)
                            .foregroundStyle(.secondary)
                        Text("#\(selectedCandidate["rank"] ?? "?") \(selectedCandidate["title"] ?? "Untitled short")")
                            .font(.caption2)
                            .fontWeight(.black)
                            .lineLimit(1)
                        HStack(spacing: 5) {
                            socialCandidateArtifactStatusPill("clip", key: "clipPath")
                            socialCandidateArtifactStatusPill("thumb", key: "thumbnailPath")
                            socialCandidateArtifactStatusPill("captions", key: "captionSrtPath")
                            socialCandidateArtifactStatusPill("copy", key: "platformCopyPath")
                        }
                        socialMasterQueuePostingPacketCard(selectedCandidate)
                        socialMasterQueueManualPostingChecklistCard(selectedCandidate)
                        socialMasterQueuePlatformCompletionCard(selectedCandidate)
                        socialMasterQueuePostingSessionCard(selectedCandidate)
                        HStack(spacing: 6) {
                            Button("Open clip") {
                                openSocialMasterQueueCandidateClip()
                            }
                            .controlSize(.mini)
                            Button("Reveal clip") {
                                revealSocialMasterQueueCandidateClip()
                            }
                            .controlSize(.mini)
                            Button("Copy handoff") {
                                copySocialMasterQueueCandidateSummary()
                            }
                            .controlSize(.mini)
                            Button("Copy packet JSON") {
                                copySelectedSocialPostingPacketJSON()
                            }
                            .controlSize(.mini)
                        }
                        HStack(spacing: 6) {
                            Button("Open copy") {
                                openSocialMasterQueueCandidateArtifact(key: "platformCopyPath", label: "platform copy")
                            }
                            .controlSize(.mini)
                            Button("Reveal captions") {
                                revealSocialMasterQueueCandidateArtifact(key: "captionSrtPath", label: "captions")
                            }
                            .controlSize(.mini)
                            Button("Reveal thumb") {
                                revealSocialMasterQueueCandidateArtifact(key: "thumbnailPath", label: "thumbnail")
                            }
                            .controlSize(.mini)
                            Button("Copy copy text") {
                                copySocialMasterQueueCandidatePlatformCopy()
                            }
                            .controlSize(.mini)
                        }
                        Divider().opacity(0.25)
                        VStack(alignment: .leading, spacing: 5) {
                            let receiptId = socialMasterQueueSelectedReceiptId()
                            let receiptURLReady = !socialMasterReceiptCaptureURL.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty
                            let receiptCommand = socialMasterQueueReceiptCommandForSelectedCandidate(includeFilledValues: receiptURLReady)
                            Text(receiptId.isEmpty ? "Receipt tracking: promote this scout clip before posting" : "Receipt tracking: existing platform receipt ready")
                                .font(.caption2)
                                .fontWeight(.bold)
                                .foregroundStyle(receiptId.isEmpty ? .orange : .green)
                            Button {
                                promoteSelectedSocialMasterQueueCandidateToReceipts()
                            } label: {
                                Label("Create receipt rows", systemImage: "list.bullet.clipboard")
                            }
                            .buttonStyle(.bordered)
                            .controlSize(.mini)
                            .disabled(selectedSocialMasterQueueCandidate() == nil)
                            .help("Creates receipt tracking rows for the selected derivative short. It does not upload, schedule, publish, or claim platform proof.")
                            HStack(spacing: 6) {
                                Picker("Platform", selection: $socialMasterReceiptCapturePlatform) {
                                    ForEach(socialMasterQueueSelectedPlatforms(), id: \.self) { platform in
                                        Text(platform).tag(platform)
                                    }
                                }
                                .labelsHidden()
                                .frame(width: 142)

                                Picker("Status", selection: $socialMasterReceiptCaptureStatus) {
                                    Text("Uploaded").tag("uploaded")
                                    Text("Scheduled").tag("scheduled")
                                    Text("Published").tag("published")
                                }
                                .labelsHidden()
                                .frame(width: 112)
                            }
                            HStack(spacing: 6) {
                                TextField("Public or scheduled URL", text: $socialMasterReceiptCaptureURL)
                                    .textFieldStyle(.roundedBorder)
                                TextField("Provider ID", text: $socialMasterReceiptCaptureProviderId)
                                    .textFieldStyle(.roundedBorder)
                                    .frame(width: 130)
                            }
                            VStack(alignment: .leading, spacing: 3) {
                                Text(receiptURLReady ? "Filled receipt command is ready to copy after you verify the platform proof." : "Paste real platform proof to turn this template into a filled receipt command.")
                                    .font(.caption2)
                                    .fontWeight(.semibold)
                                    .foregroundStyle(receiptURLReady ? QuipslyStudioTheme.moss : .secondary)
                                Text(receiptCommand)
                                    .font(.caption2.monospaced())
                                    .foregroundStyle(.secondary)
                                    .lineLimit(2)
                                    .textSelection(.enabled)
                            }
                            .padding(6)
                            .background((receiptURLReady ? QuipslyStudioTheme.moss : QuipslyStudioTheme.honey).opacity(0.07))
                            .clipShape(RoundedRectangle(cornerRadius: 7))
                            HStack(spacing: 6) {
                                Button {
                                    captureSocialMasterQueueReceiptForSelectedCandidate()
                                } label: {
                                    Label("Save selected receipt", systemImage: "checkmark.seal")
                                }
                                .buttonStyle(.borderedProminent)
                                .controlSize(.mini)
                                .disabled(receiptId.isEmpty || socialMasterReceiptCaptureURL.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty)

                                if !receiptId.isEmpty {
                                    Button(receiptURLReady ? "Copy filled command" : "Copy template command") {
                                        copySocialMasterQueueReceiptCommand()
                                    }
                                    .controlSize(.mini)
                                }
                                Button("Copy all commands") {
                                    copySocialMasterQueueAllReceiptCommands()
                                }
                                .controlSize(.mini)
                                .disabled(selectedSocialMasterQueueCandidate() == nil)
                            }
                            VStack(alignment: .leading, spacing: 4) {
                                Text("Batch receipt paste")
                                    .font(.caption2)
                                    .fontWeight(.bold)
                                    .foregroundStyle(.secondary)
                                TextEditor(text: $socialMasterReceiptBatchText)
                                    .font(.caption2.monospaced())
                                    .frame(height: 54)
                                    .overlay(
                                        RoundedRectangle(cornerRadius: 6)
                                            .stroke(Color.secondary.opacity(0.16), lineWidth: 1)
                                    )
                                    .help("Paste rows as platform, status, public_url, provider_id, notes. URLs are required; rows without URLs are skipped.")
                                HStack(spacing: 6) {
                                    Button("Apply batch receipts") {
                                        captureSocialMasterQueueReceiptsFromBatchText()
                                    }
                                    .controlSize(.mini)
                                    .disabled(
                                        selectedSocialMasterQueueCandidate() == nil
                                            || socialMasterReceiptBatchText.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty
                                    )
                                    Button("Clear batch") {
                                        socialMasterReceiptBatchText = ""
                                        lastMediaAction = "Cleared social receipt batch text"
                                        updateAgentState()
                                    }
                                    .controlSize(.mini)
                                    .disabled(socialMasterReceiptBatchText.isEmpty)
                                }
                                Text("Rows without real URLs are ignored. This only updates Quipsly receipt tracking after manual posting/scheduling.")
                                    .font(.caption2)
                                    .foregroundStyle(.secondary)
                                    .fixedSize(horizontal: false, vertical: true)
                            }
                            if receiptId.isEmpty {
                                Text("Expansion candidates do not have durable receipt IDs yet. Watch, promote, or post manually with an explicit note; do not claim Quipsly captured the platform receipt.")
                                    .font(.caption2)
                                    .foregroundStyle(.secondary)
                                    .fixedSize(horizontal: false, vertical: true)
                            }
                        }
                    }
                    .padding(7)
                    .background(QuipslyStudioTheme.creek.opacity(0.08))
                    .clipShape(RoundedRectangle(cornerRadius: 10, style: .continuous))
                }
            }

            if !socialMasterQueueErrorMessage.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty {
                Text(socialMasterQueueErrorMessage)
                    .font(.caption2)
                    .foregroundStyle(QuipslyStudioTheme.clay)
                    .fixedSize(horizontal: false, vertical: true)
            }
        }
        .padding(7)
        .background(color.opacity(0.055))
        .overlay(
            RoundedRectangle(cornerRadius: 9)
                .stroke(color.opacity(0.16), lineWidth: 1)
        )
        .clipShape(RoundedRectangle(cornerRadius: 9))
    }

    private func socialCandidateArtifactStatusPill(_ label: String, key: String) -> some View {
        let path = socialMasterQueueSelectedPath(key)
        let ready = !path.isEmpty && FileManager.default.fileExists(atPath: path)
        return Text("\(ready ? "ok" : "!" ) \(label)")
            .font(.caption2)
            .fontWeight(.bold)
            .padding(.horizontal, 6)
            .padding(.vertical, 3)
            .background((ready ? QuipslyStudioTheme.moss : QuipslyStudioTheme.honey).opacity(0.14))
            .foregroundStyle(ready ? QuipslyStudioTheme.moss : QuipslyStudioTheme.honey)
            .clipShape(Capsule())
            .help(ready ? "\(label) file found" : "\(label) file missing or not generated")
    }

