                Text(receiptId.isEmpty ? "receipt needed" : "receipt ready")
                    .font(.caption2.monospaced())
                    .fontWeight(.bold)
                    .foregroundStyle(receiptId.isEmpty ? QuipslyStudioTheme.honey : QuipslyStudioTheme.moss)
