    private func socialMasterQueueManualPostingChecklistCard(_ candidate: [String: String]) -> some View {
        let clipPath = (candidate["clipPath"] ?? "").trimmingCharacters(in: .whitespacesAndNewlines)
        let captionPath = (candidate["captionSrtPath"] ?? "").trimmingCharacters(in: .whitespacesAndNewlines)
        let copyPath = (candidate["platformCopyPath"] ?? "").trimmingCharacters(in: .whitespacesAndNewlines)
        let clipReady = !clipPath.isEmpty && FileManager.default.fileExists(atPath: clipPath)
        let copyReady = !copyPath.isEmpty && FileManager.default.fileExists(atPath: copyPath)
        let captionsReady = !captionPath.isEmpty && FileManager.default.fileExists(atPath: captionPath)
        let receiptChecklist = selectedSocialMasterQueueReceiptChecklistPayload()
        let readyPlatformCount = receiptChecklist["readyPlatformCount"] as? Int ?? 0
        let blockedPlatformCount = receiptChecklist["blockedPlatformCount"] as? Int ?? 0
        let receiptsReady = readyPlatformCount > 0 && blockedPlatformCount == 0
        let platformCompletionRows = socialMasterQueuePlatformCompletionRows()
        let proofComplete = !platformCompletionRows.isEmpty && platformCompletionRows.allSatisfy { ($0["proofCaptured"] as? Bool) == true }
        let overallReady = clipReady && copyReady && receiptsReady

        return VStack(alignment: .leading, spacing: 7) {
            HStack(spacing: 6) {
                Label("Manual posting checklist", systemImage: "checklist")
                    .font(.caption2)
                    .fontWeight(.black)
                    .foregroundStyle(QuipslyStudioTheme.moss)
                Spacer()
                Text(overallReady ? "ready to post" : "prep needed")
                    .font(.caption2.monospaced())
                    .fontWeight(.bold)
                    .foregroundStyle(overallReady ? QuipslyStudioTheme.moss : QuipslyStudioTheme.honey)
                    .padding(.horizontal, 6)
                    .padding(.vertical, 2)
                    .background((overallReady ? QuipslyStudioTheme.moss : QuipslyStudioTheme.honey).opacity(0.12))
                    .clipShape(Capsule())
            }

            socialManualChecklistRow(
                title: "1. Watch the clip once",
                detail: clipReady ? "Derivative 9:16 clip exists. Open it and judge it like a human." : "Clip artifact is missing; export/regenerate before posting.",
                ready: clipReady,
                systemName: "play.rectangle"
            )
            socialManualChecklistRow(
                title: "2. Review copy and captions",
                detail: "\(copyReady ? "Platform copy ready" : "Platform copy missing"). \(captionsReady ? "Captions ready." : "Captions optional/missing.")",
                ready: copyReady,
                systemName: "text.quote"
            )
            socialManualChecklistRow(
                title: "3. Create receipt rows",
                detail: receiptsReady ? "\(readyPlatformCount) platform receipt rows ready for URL capture." : "Create receipt rows before claiming Quipsly can capture platform proof.",
                ready: receiptsReady,
                systemName: "list.bullet.clipboard"
            )
            socialManualChecklistRow(
                title: "4. Post or schedule manually",
                detail: "Use the exported derivative short, copy, captions, and optional thumbnail on each platform.",
                ready: overallReady,
                systemName: "paperplane"
            )
            socialManualChecklistRow(
                title: "5. Paste proof back",
                detail: "Capture each public/scheduled URL or provider receipt. No URL means not complete.",
                ready: proofComplete,
                systemName: "checkmark.seal"
            )
        }
        .padding(7)
        .background(QuipslyStudioTheme.moss.opacity(0.07))
        .overlay(
            RoundedRectangle(cornerRadius: 10, style: .continuous)
                .stroke(QuipslyStudioTheme.moss.opacity(0.16), lineWidth: 1)
        )
        .clipShape(RoundedRectangle(cornerRadius: 10, style: .continuous))
    }

    private func socialManualChecklistRow(title: String, detail: String, ready: Bool, systemName: String) -> some View {
        HStack(alignment: .top, spacing: 7) {
            Image(systemName: ready ? "checkmark.circle.fill" : systemName)
                .font(.caption2)
                .foregroundStyle(ready ? QuipslyStudioTheme.moss : QuipslyStudioTheme.honey)
                .frame(width: 16)
            VStack(alignment: .leading, spacing: 1) {
                Text(title)
                    .font(.caption2)
                    .fontWeight(.bold)
                    .foregroundStyle(.primary.opacity(0.88))
                Text(detail)
                    .font(.caption2)
                    .foregroundStyle(.secondary)
                    .fixedSize(horizontal: false, vertical: true)
            }
            Spacer(minLength: 0)
        }
    }

    private func socialMasterQueuePlatformCompletionCard(_ candidate: [String: String]) -> some View {
        let rows = socialMasterQueuePlatformCompletionRows()
        let completedCount = rows.filter { ($0["proofCaptured"] as? Bool) == true }.count
        let totalCount = max(1, rows.count)

        return VStack(alignment: .leading, spacing: 7) {
            HStack(spacing: 6) {
                Label("Platform completion", systemImage: "dot.radiowaves.left.and.right")
                    .font(.caption2)
                    .fontWeight(.black)
                    .foregroundStyle(QuipslyStudioTheme.creek)
                Spacer()
                Text("\(completedCount)/\(totalCount) proof captured")
                    .font(.caption2.monospaced())
                    .fontWeight(.bold)
                    .foregroundStyle(completedCount == totalCount ? .green : .orange)
                    .padding(.horizontal, 6)
                    .padding(.vertical, 2)
                    .background((completedCount == totalCount ? Color.green : Color.orange).opacity(0.12))
                    .clipShape(Capsule())
            }

            ForEach(rows.indices, id: \.self) { index in
                let row = rows[index]
                let platform = row["platform"] as? String ?? "Platform"
                let status = row["status"] as? String ?? "unknown"
                let proofCaptured = row["proofCaptured"] as? Bool ?? false
                let publishStatus = row["publishStatus"] as? String ?? ""
                HStack(alignment: .top, spacing: 7) {
                    Image(systemName: proofCaptured ? "checkmark.seal.fill" : "circle.dashed")
                        .font(.caption2)
                        .foregroundStyle(proofCaptured ? .green : .orange)
                        .frame(width: 16)
                    VStack(alignment: .leading, spacing: 1) {
                        Text(platform)
                            .font(.caption2)
                            .fontWeight(.bold)
                        Text(status)
                            .font(.caption2.monospaced())
                            .foregroundStyle(proofCaptured ? .green : .orange)
                        if !publishStatus.isEmpty {
                            Text("ledger: \(publishStatus)")
                                .font(.caption2)
                                .foregroundStyle(.secondary)
                        }
                    }
                    Spacer(minLength: 0)
                    Button(proofCaptured ? "View" : "Capture") {
                        selectSocialMasterReceiptPlatform(platform: platform, status: proofCaptured ? publishStatus : "published")
                    }
                    .controlSize(.mini)
                    .help("Targets the receipt capture form at \(platform). This does not post or mark proof captured.")
                }
            }

            Text("Only rows with a real public/scheduled URL or provider receipt count as complete.")
                .font(.caption2)
                .fontWeight(.semibold)
                .foregroundStyle(.secondary)
                .fixedSize(horizontal: false, vertical: true)
        }
        .padding(7)
        .background(Color.blue.opacity(0.06))
        .overlay(
            RoundedRectangle(cornerRadius: 10, style: .continuous)
                .stroke(Color.blue.opacity(0.15), lineWidth: 1)
        )
        .clipShape(RoundedRectangle(cornerRadius: 10, style: .continuous))
    }

    private func socialMasterQueuePostingSessionCard(_ candidate: [String: String]) -> some View {
        let rows = socialMasterQueuePlatformCompletionRows()
        let incompletePlatforms = rows.compactMap { row -> String? in
            let proofCaptured = row["proofCaptured"] as? Bool ?? false
            return proofCaptured ? nil : (row["platform"] as? String)
        }
        let selectedPlatform = socialMasterReceiptCapturePlatform.trimmingCharacters(in: .whitespacesAndNewlines)
        let nextPlatform = nextIncompleteSocialPostingPlatform()
        let currentPlatform = incompletePlatforms.contains(selectedPlatform)
            ? selectedPlatform
            : (nextPlatform ?? selectedPlatform)
        let allComplete = nextPlatform == nil && !rows.isEmpty
        let title = (candidate["title"] ?? "selected social candidate").trimmingCharacters(in: .whitespacesAndNewlines)

        return VStack(alignment: .leading, spacing: 7) {
            HStack(spacing: 6) {
                Label("Posting session", systemImage: "paperplane.circle")
                    .font(.caption2)
                    .fontWeight(.black)
                    .foregroundStyle(.mint)
                Spacer()
                Text(allComplete ? "proof complete" : "next: \(currentPlatform.isEmpty ? "choose platform" : currentPlatform)")
                    .font(.caption2.monospaced())
                    .fontWeight(.bold)
                    .foregroundStyle(allComplete ? .green : .mint)
                    .padding(.horizontal, 6)
                    .padding(.vertical, 2)
                    .background((allComplete ? Color.green : Color.mint).opacity(0.12))
                    .clipShape(Capsule())
            }

            if allComplete {
                Text("All target platforms have receipt proof captured for this selected short.")
                    .font(.caption2)
                    .foregroundStyle(.secondary)
            } else {
                VStack(alignment: .leading, spacing: 3) {
                    Text(title.isEmpty ? "Selected short" : title)
                        .font(.caption2)
                        .fontWeight(.bold)
                        .lineLimit(1)
                    Text("1. Watch the clip. 2. Open platform copy/captions. 3. Post or schedule on \(currentPlatform.isEmpty ? "the selected platform" : currentPlatform). 4. Paste the real URL/receipt back here.")
                        .font(.caption2)
                        .foregroundStyle(.secondary)
                        .fixedSize(horizontal: false, vertical: true)
                }

                HStack(spacing: 6) {
                    Button("Select next platform") {
                        selectNextIncompleteSocialPostingPlatform()
                    }
                    .controlSize(.mini)
                    .disabled(nextPlatform == nil)

                    Button("Open clip") {
                        openSocialMasterQueueCandidateClip()
                    }
                    .controlSize(.mini)

                    Button("Open copy") {
                        openSocialMasterQueueCandidateArtifact(key: "platformCopyPath", label: "platform copy")
                    }
                    .controlSize(.mini)

                    Button("Reveal captions") {
                        revealSocialMasterQueueCandidateArtifact(key: "captionSrtPath", label: "captions")
                    }
                    .controlSize(.mini)
                }

                HStack(spacing: 6) {
                    Button("Copy receipt command") {
                        copySocialMasterQueueReceiptCommand()
                    }
                    .controlSize(.mini)
                    .disabled(socialMasterQueueSelectedReceiptId().isEmpty)

                    Button("Copy session") {
                        copySocialMasterQueuePostingSessionHandoff()
                    }
                    .controlSize(.mini)

                    Button("Generate packet") {
                        generateSocialMasterQueuePostingRunPacket()
                    }
                    .controlSize(.mini)

                    Button("Open packet") {
                        openSocialMasterQueuePostingRunPacket()
                    }
                    .controlSize(.mini)
                    .disabled(socialMasterPostingRunPacketPath.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty)

                    Button("Reveal packet") {
                        revealSocialMasterQueuePostingRunPacket()
                    }
                    .controlSize(.mini)
                    .disabled(socialMasterPostingRunPacketPath.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty)

                    Button("Copy handoff") {
                        copySocialMasterQueueCandidateSummary()
                    }
                    .controlSize(.mini)
                }
            }

            VStack(alignment: .leading, spacing: 4) {
                Text("Platform queue")
                    .font(.caption2)
                    .fontWeight(.bold)
                    .foregroundStyle(.secondary)
                ForEach(rows.indices, id: \.self) { index in
                    let row = rows[index]
                    let platform = row["platform"] as? String ?? "Platform"
                    let proofCaptured = row["proofCaptured"] as? Bool ?? false
                    let receiptRowFound = row["receiptRowFound"] as? Bool ?? false
                    let isCurrent = platform == currentPlatform
                    HStack(spacing: 6) {
                        Image(systemName: proofCaptured ? "checkmark.seal.fill" : (isCurrent ? "arrow.right.circle.fill" : "circle"))
                            .font(.caption2)
                            .foregroundStyle(proofCaptured ? .green : (isCurrent ? .mint : .secondary))
                            .frame(width: 16)
                        VStack(alignment: .leading, spacing: 1) {
                            Text(platform)
                                .font(.caption2)
                                .fontWeight(.bold)
                            Text(proofCaptured ? "proof captured" : (receiptRowFound ? "needs real URL/receipt" : "create receipt rows first"))
                                .font(.caption2.monospaced())
                                .foregroundStyle(proofCaptured ? .green : .orange)
                        }
                        Spacer(minLength: 0)
                        Button(isCurrent ? "Current" : "Target") {
                            selectSocialMasterReceiptPlatform(platform: platform, status: proofCaptured ? (row["publishStatus"] as? String ?? "published") : "published")
                        }
                        .controlSize(.mini)
                        .disabled(proofCaptured && isCurrent)
                    }
                    .padding(.horizontal, 6)
                    .padding(.vertical, 4)
                    .background(isCurrent ? Color.mint.opacity(0.12) : Color.white.opacity(0.03))
                    .clipShape(RoundedRectangle(cornerRadius: 7))
                }
            }

            Text("Posting session is an operator guide only. Platform completion still requires a real public/scheduled URL or provider receipt.")
                .font(.caption2)
                .fontWeight(.semibold)
                .foregroundStyle(.secondary)
                .fixedSize(horizontal: false, vertical: true)
        }
        .padding(7)
        .background(Color.mint.opacity(0.06))
        .overlay(
            RoundedRectangle(cornerRadius: 10, style: .continuous)
                .stroke(Color.mint.opacity(0.16), lineWidth: 1)
        )
        .clipShape(RoundedRectangle(cornerRadius: 10, style: .continuous))
    }

    private func socialMasterQueueCandidateCard(_ candidate: [String: String], index: Int) -> some View {
        let rank = candidate["rank"] ?? "\(index + 1)"
        let selected = rank == selectedSocialMasterQueueRank
        let title = candidate["title"]?.trimmingCharacters(in: .whitespacesAndNewlines) ?? ""
        let hook = candidate["hook"]?.trimmingCharacters(in: .whitespacesAndNewlines) ?? ""
        let sourcePack = candidate["sourcePack"]?.trimmingCharacters(in: .whitespacesAndNewlines) ?? "unknown"
        let duration = candidate["duration"]?.trimmingCharacters(in: .whitespacesAndNewlines) ?? "?"
        let platforms = socialMasterQueueCandidatePlatforms(candidate)
        let receiptCount = Int(candidate["platformReceiptCount"] ?? "0") ?? 0

        return Button {
            selectSocialMasterQueueCandidate(rank: rank)
        } label: {
            VStack(alignment: .leading, spacing: 5) {
                HStack(alignment: .firstTextBaseline, spacing: 7) {
                    Text("#\(rank)")
                        .font(.caption2.monospaced())
                        .fontWeight(.black)
                        .foregroundStyle(selected ? .white : .cyan)
                        .padding(.horizontal, 6)
                        .padding(.vertical, 3)
                        .background((selected ? Color.cyan : Color.cyan.opacity(0.14)))
                        .clipShape(Capsule())
                    Text(title.isEmpty ? "Untitled short" : title)
                        .font(.caption2)
                        .fontWeight(.black)
                        .lineLimit(1)
                    Spacer(minLength: 6)
                    Text("\(duration)s")
                        .font(.caption2.monospaced())
                        .fontWeight(.bold)
                        .foregroundStyle(.secondary)
                    if selected {
                        Text("SELECTED")
                            .font(.caption2)
                            .fontWeight(.black)
                            .foregroundStyle(.cyan)
                    }
                }

                if !hook.isEmpty {
                    Text(hook)
                        .font(.caption2)
                        .foregroundStyle(.secondary)
                        .lineLimit(2)
                }

                HStack(spacing: 5) {
                    Text(sourcePack.isEmpty ? "unknown pack" : sourcePack)
                        .font(.caption2)
                        .fontWeight(.bold)
                        .foregroundStyle(.cyan)
                        .lineLimit(1)
                    socialMasterQueueCandidateArtifactPill("clip", key: "clipPath", candidate: candidate)
                    socialMasterQueueCandidateArtifactPill("copy", key: "platformCopyPath", candidate: candidate)
                    socialMasterQueueCandidateArtifactPill("captions", key: "captionSrtPath", candidate: candidate)
                    socialMasterQueueCandidateArtifactPill("thumb", key: "thumbnailPath", candidate: candidate)
                    Spacer(minLength: 6)
                    Text(receiptCount > 0 ? "\(receiptCount) receipt ids" : "no receipt id")
                        .font(.caption2)
                        .fontWeight(.bold)
                        .foregroundStyle(receiptCount > 0 ? .green : .orange)
                }

                if !platforms.isEmpty {
                    HStack(spacing: 4) {
                        ForEach(platforms.prefix(4), id: \.self) { platform in
                            Text(platform)
                                .font(.caption2)
                                .fontWeight(.bold)
                                .lineLimit(1)
                                .padding(.horizontal, 5)
                                .padding(.vertical, 2)
                                .background(Color.primary.opacity(0.055))
                                .clipShape(Capsule())
                        }
                    }
                }
            }
            .frame(maxWidth: .infinity, alignment: .leading)
        }
        .buttonStyle(.plain)
        .padding(7)
        .background(selected ? Color.cyan.opacity(0.18) : Color.black.opacity(0.12))
        .overlay(
            RoundedRectangle(cornerRadius: 10, style: .continuous)
                .stroke(selected ? Color.cyan.opacity(0.48) : Color.primary.opacity(0.06), lineWidth: 1)
        )
        .clipShape(RoundedRectangle(cornerRadius: 10, style: .continuous))
        .help("Select candidate #\(rank). Selection drives Open clip, Copy copy text, and receipt capture below.")
    }

    private func socialMasterQueueCandidateArtifactPill(_ label: String, key: String, candidate: [String: String]) -> some View {
        let path = (candidate[key] ?? "").trimmingCharacters(in: .whitespacesAndNewlines)
        let ready = !path.isEmpty && FileManager.default.fileExists(atPath: path)
        return Text("\(ready ? "ok" : "!") \(label)")
            .font(.caption2)
            .fontWeight(.bold)
            .padding(.horizontal, 5)
            .padding(.vertical, 2)
            .background((ready ? Color.green : Color.orange).opacity(0.13))
            .foregroundStyle(ready ? .green : .orange)
            .clipShape(Capsule())
            .help(ready ? "\(label) is ready: \(path)" : "\(label) is missing or not generated")
    }

    private func socialMasterQueueCandidatePlatforms(_ candidate: [String: String]) -> [String] {
        let raw = (candidate["platforms"] ?? "").trimmingCharacters(in: .whitespacesAndNewlines)
        return raw
            .split(separator: ",")
            .map { String($0).trimmingCharacters(in: .whitespacesAndNewlines) }
            .filter { !$0.isEmpty }
    }

    private func publishReceiptCapturePanel(records: [PublishReceiptRecord]) -> some View {
        let summary = publishReceiptCaptureSummary(records: records)
        let capturedCount = summary["capturedCount"] as? Int ?? 0
        let missingCount = summary["missingCount"] as? Int ?? 0
        let readyMissing = publishReceiptCaptureReadyMissingRecords(records: records)
        let color: Color = missingCount == 0 ? .green : (readyMissing.isEmpty ? .orange : .cyan)

        return VStack(alignment: .leading, spacing: 8) {
            HStack(alignment: .top, spacing: 8) {
                Image(systemName: missingCount == 0 ? "checkmark.seal.fill" : "link.badge.plus")
                    .foregroundStyle(color)
                    .frame(width: 22, height: 22)
                    .background(color.opacity(0.13))
                    .clipShape(Circle())
                VStack(alignment: .leading, spacing: 2) {
                    Text("Receipt capture")
                        .font(.caption)
                        .fontWeight(.black)
                    Text(receiptCaptureSummaryText(summary))
                        .font(.caption2)
                        .foregroundStyle(.secondary)
                        .fixedSize(horizontal: false, vertical: true)
                }
                Spacer()
                Button {
                    copyPublishReceiptCaptureChecklist(records: records)
                } label: {
                    Label("Copy missing", systemImage: "doc.on.doc")
                }
                .controlSize(.mini)
                .disabled(missingCount == 0)
            }

            HStack(spacing: 6) {
                publishStatPill("captured", capturedCount, .green)
                publishStatPill("missing", missingCount, .orange)
                publishStatPill("ready", readyMissing.count, .cyan)
            }

            if let selectedReceipt = selectedPublishReceipt(from: records) {
                VStack(alignment: .leading, spacing: 6) {
                    Text("Quick capture for \(publishReceiptDisplayLabel(selectedReceipt))")
                        .font(.caption2)
                        .fontWeight(.bold)
                        .lineLimit(1)
                    HStack(spacing: 6) {
                        Picker("Status", selection: $publishReceiptQuickStatus) {
                            Text("Uploaded").tag("uploaded")
                            Text("Scheduled").tag("scheduled")
                            Text("Published").tag("published")
                        }
                        .labelsHidden()
                        .frame(width: 112)

                        TextField("Public or scheduled URL", text: $publishReceiptQuickURL)
                            .textFieldStyle(.roundedBorder)
                        TextField("Provider ID", text: $publishReceiptQuickProviderId)
                            .textFieldStyle(.roundedBorder)
                            .frame(width: 135)
                        Button {
                            capturePublishReceiptForSelectedRecord(selectedReceipt)
                        } label: {
                            Label("Save receipt", systemImage: "checkmark.seal")
                        }
                        .buttonStyle(.borderedProminent)
                        .controlSize(.mini)
                        .disabled(publishReceiptQuickURL.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty)
                    }
                }
                .padding(7)
                .background(Color.white.opacity(0.045))
                .clipShape(RoundedRectangle(cornerRadius: 9))
            } else if !readyMissing.isEmpty {
                Text("Select any publish record below to capture its public or scheduled URL here.")
                    .font(.caption2)
                    .foregroundStyle(.secondary)
                    .fixedSize(horizontal: false, vertical: true)
            }

            if !readyMissing.isEmpty {
                VStack(alignment: .leading, spacing: 5) {
                    ForEach(readyMissing.prefix(4), id: \.id) { record in
                        HStack(spacing: 6) {
                            VStack(alignment: .leading, spacing: 1) {
                                Text(publishReceiptDisplayLabel(record))
                                    .font(.caption2)
                                    .fontWeight(.semibold)
                                    .lineLimit(1)
                                Text("Paste the public or scheduled URL after uploading.")
                                    .font(.caption2)
                                    .foregroundStyle(.secondary)
                            }
                            Spacer()
                            Button("Capture") {
                                beginEditingPublishReceipt(record)
                            }
                            .controlSize(.mini)
                        }
                        .padding(6)
                        .background(Color.white.opacity(0.04))
                        .clipShape(RoundedRectangle(cornerRadius: 10, style: .continuous))
                    }
                }
            }
        }
        .padding(8)
        .background(color.opacity(0.055))
        .overlay(
            RoundedRectangle(cornerRadius: 12, style: .continuous)
                .stroke(color.opacity(0.16), lineWidth: 1)
        )
        .clipShape(RoundedRectangle(cornerRadius: 12, style: .continuous))
    }

    private func publishReleaseChecklistColor(_ readiness: String) -> Color {
        switch readiness {
        case "released":
            return .yellow
        case "partially-released":
            return .blue
        case "ready-for-manual-upload":
            return .green
        case "needs-copy-review":
            return .cyan
        case "needs-artifacts":
            return .orange
        default:
            return .mint
        }
    }

    private func publishReleaseChecklistIcon(_ readiness: String) -> String {
        switch readiness {
        case "released":
            return "checkmark.seal.fill"
        case "partially-released":
            return "clock.badge.checkmark"
        case "ready-for-manual-upload":
            return "arrow.up.doc.fill"
        case "needs-copy-review":
            return "text.badge.checkmark"
        case "needs-artifacts":
            return "shippingbox.fill"
        default:
            return "checklist"
        }
    }

    private func publishReleaseChecklistSummaryText(_ summary: [String: Any]) -> String {
        let recordCount = summary["recordCount"] as? Int ?? 0
        if recordCount == 0 {
            return "No platform records yet. Generate the publish ledger after release prep exports artifacts."
        }
        let artifactReady = summary["artifactReadyCount"] as? Int ?? 0
        let copyReady = summary["copyReadyCount"] as? Int ?? 0
        let receipts = summary["receiptCapturedCount"] as? Int ?? 0
        let apiNeeded = summary["apiNeededCount"] as? Int ?? 0
        return "\(artifactReady)/\(recordCount) artifacts ready, \(copyReady)/\(recordCount) copy ready, \(receipts)/\(recordCount) receipts captured, \(apiNeeded) waiting for direct platform APIs."
    }

