    private var fullReleaseStatusLabel: String {
        switch fullReleaseStatus {
        case "running":
            return "FULL RELEASE PREP RUNNING"
        case "completed":
            return "FULL RELEASE PREP READY"
        case "failed":
            return "FULL RELEASE PREP FAILED"
        case "blocked":
            return "FULL RELEASE PREP BLOCKED"
        default:
            return "FULL RELEASE PREP"
        }
    }

    private var fullReleaseStatusDetail: String {
        if fullReleaseStatus == "running" {
            let base = fullReleaseStep.isEmpty
                ? "Preparing exports, delivery packet, publish ledger, release checklist, publish packet, upload bundle, social queue, social ready packet, podcast packet, podcast ready packet, and publication cockpit."
                : "Current step: \(fullReleaseStep)."
            return "\(base) Large episode exports may keep writing or finalizing even when a single progress value appears unchanged."
        }
        if fullReleaseStatus == "completed" {
            return fullReleaseOutputPath.isEmpty
                ? "Exports and publishing handoff artifacts were generated."
                : "Operator-ready release folder: \(fullReleaseOutputPath)"
        }
        if fullReleaseStatus == "failed" || fullReleaseStatus == "blocked" {
            return fullReleaseErrorMessage.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty
                ? "Check export, delivery packet, publish packet, upload bundle, social queue, social ready packet, podcast packet, podcast ready packet, and publication cockpit state for details."
                : fullReleaseErrorMessage
        }
        return "Runs release prep plus delivery packet, publish ledger, checklist, upload bundle, social queue, social ready packet, podcast handoff, podcast ready packet, and publication cockpit."
    }

