            let firstWaveCount = socialMasterQueueFirstWaveCandidates().count
            let quoteCheckCount = socialMasterQueueQuoteCheckCandidates().count
            return "\(socialMasterQueueClipCount) short recipes loaded. \(firstWaveCount) are first-wave post candidates; \(quoteCheckCount) need quote-check or promotion. Nothing has been uploaded automatically."
        }
        return "Load a generated social-master-queue.json to review release shorts and expansion candidates from one place."
    }

    private func socialMasterQueueCandidateHasFullReceiptIds(_ candidate: [String: String]) -> Bool {
        let requiredKeys = [
            "youtubeShortsReceiptId",
            "instagramReceiptId",
            "facebookReceiptId",
            "linkedinReceiptId"
        ]
        return requiredKeys.allSatisfy { key in
            !(candidate[key] ?? "").trimmingCharacters(in: .whitespacesAndNewlines).isEmpty
        }
    }

    private func socialMasterQueueFirstWaveCandidates() -> [[String: String]] {
        socialMasterQueueCandidatePreview.filter { candidate in
            let reviewStatus = (candidate["reviewStatus"] ?? "").lowercased()
            guard socialMasterQueueCandidateHasFullReceiptIds(candidate) else { return false }
            return !reviewStatus.contains("test-only") && !reviewStatus.contains("quote-check")
        }
    }

    private func socialMasterQueueReviewLastCandidates() -> [[String: String]] {
        socialMasterQueueCandidatePreview.filter { candidate in
            let reviewStatus = (candidate["reviewStatus"] ?? "").lowercased()
            return socialMasterQueueCandidateHasFullReceiptIds(candidate)
                && (reviewStatus.contains("test-only") || reviewStatus.contains("review-last"))
        }
    }

    private func socialMasterQueueQuoteCheckCandidates() -> [[String: String]] {
        socialMasterQueueCandidatePreview.filter { candidate in
            let reviewStatus = (candidate["reviewStatus"] ?? "").lowercased()
            return !socialMasterQueueCandidateHasFullReceiptIds(candidate)
                || reviewStatus.contains("quote-check")
                || reviewStatus.contains("scout")
                || reviewStatus.contains("expansion")
        }
    }

    private func socialMasterQueuePlatformReceiptPayloads(for candidate: [String: String]) -> [[String: String]] {
        let rank = candidate["rank"] ?? ""
        let platforms = [
            ("YouTube Shorts", "youtubeShortsReceiptId"),
            ("Instagram Reels", "instagramReceiptId"),
            ("Facebook Reels", "facebookReceiptId"),
            ("LinkedIn", "linkedinReceiptId")
        ]
        return platforms.map { platform, receiptKey in
            let receiptId = candidate[receiptKey] ?? ""
            return [
                "platform": platform,
                "receiptId": receiptId,
                "captureCommand": "script/agentctl.sh social-master-queue-receipt \(rank) \"\(platform)\" published <public-or-scheduled-url> <provider-id-or-scheduled-id> \"manual receipt\""
            ]
        }
    }

    private func socialMasterQueueFirstWaveCandidatePayload(_ candidate: [String: String]) -> [String: Any] {
        let rank = candidate["rank"] ?? ""
        return [
            "rank": rank,
            "title": candidate["title"] ?? "",
            "duration": candidate["duration"] ?? "",
            "hook": candidate["hook"] ?? "",
            "clipPath": candidate["clipPath"] ?? "",
            "thumbnailPath": candidate["thumbnailPath"] ?? "",
            "captionSrtPath": candidate["captionSrtPath"] ?? "",
            "platformCopyPath": candidate["platformCopyPath"] ?? "",
            "receiptReady": true,
            "watchOnceCommand": "script/agentctl.sh social-master-queue-select \(rank) && script/agentctl.sh social-master-open-selected-clip",
            "copyPlatformCopyCommand": "script/agentctl.sh social-master-queue-select \(rank) && script/agentctl.sh social-master-copy-selected-platform-copy",
            "copyHandoffCommand": "script/agentctl.sh social-master-queue-select \(rank) && script/agentctl.sh social-master-queue-artifact copy_handoff",
            "receiptCaptureCommands": socialMasterQueuePlatformReceiptPayloads(for: candidate)
        ]
    }

    private func socialMasterQueuePostingReadinessPayload() -> [String: Any] {
        let firstWave = socialMasterQueueFirstWaveCandidates()
        let reviewLast = socialMasterQueueReviewLastCandidates()
        let quoteCheck = socialMasterQueueQuoteCheckCandidates()
        let firstWavePreview = firstWave.prefix(12).map { candidate in
            socialMasterQueueFirstWaveCandidatePayload(candidate)
        }
        let reviewFirstPreview = quoteCheck.prefix(12).map { candidate -> [String: Any] in
            [
                "rank": candidate["rank"] ?? "",
                "title": candidate["title"] ?? "",
                "duration": candidate["duration"] ?? "",
                "hook": candidate["hook"] ?? "",
                "reviewStatus": candidate["reviewStatus"] ?? "",
                "clipPath": candidate["clipPath"] ?? "",
                "platformCopyPath": candidate["platformCopyPath"] ?? "",
                "receiptReady": socialMasterQueueCandidateHasFullReceiptIds(candidate)
            ]
        }

        return [
            "model": "quipsly-social-posting-readiness",
            "version": "2026-06-17.social-posting-readiness.v1",
            "status": socialMasterQueueClipCount > 0 ? "loaded" : "no-social-queue-loaded",
            "totalClipCount": socialMasterQueueClipCount,
            "firstWavePostCandidateCount": firstWave.count,
            "reviewLastCandidateCount": reviewLast.count,
            "quoteCheckOrPromotionNeededCount": quoteCheck.count,
            "firstWaveRanks": firstWave.map { $0["rank"] ?? "" }.filter { !$0.isEmpty },
            "reviewLastRanks": reviewLast.map { $0["rank"] ?? "" }.filter { !$0.isEmpty },
            "quoteCheckRanks": quoteCheck.map { $0["rank"] ?? "" }.filter { !$0.isEmpty },
            "firstWavePreview": firstWavePreview,
            "reviewFirstPreview": reviewFirstPreview,
            "operatorRule": "Post first-wave clips only after a watch-once review. Quote-check or promote expansion/scout clips before calling them publication-ready.",
            "safeCommand": "script/agentctl.sh episode1-socials-load",
            "firstWaveCommand": "script/agentctl.sh episode1-socials-first-wave",
            "receiptProofRule": "A platform is not complete until a real public/scheduled URL or provider receipt is captured."
        ]
    }

