    private var publishConnectorWorkerStatusDetail: String {
        let error = publishConnectorWorkerErrorMessage.trimmingCharacters(in: .whitespacesAndNewlines)
        if !error.isEmpty {
            return error
        }
        if let parsed = parseJSONObject(publishConnectorWorkerResultJson),
           let recordCount = parsed["recordCount"] as? Int {
            let passedCount = parsed["passedCount"] as? Int ?? 0
            let failedCount = parsed["failedCount"] as? Int ?? 0
            return "\(passedCount)/\(recordCount) bundled dry-run worker(s) passed; \(failedCount) issue(s). No upload, schedule, publish, provider receipt, or public URL was created."
        }
        if publishConnectorWorkerStatus == "running-all" {
            return "Running bundled dry-run workers against the current publish ledger."
        }
        if publishConnectorWorkerStatus == "running" {
            return "Running \(publishConnectorWorkerPlatform) dry-run worker for \(publishConnectorWorkerLaneId)."
        }
        if publishConnectorWorkerStatus == "dry-run-passed" {
            return "\(publishConnectorWorkerPlatform) worker validated artifact, copy, metadata, and receipt contract without publishing."
        }
        return "Use Dry-run all after full prep or ledger generation to prove bundled worker contracts before manual or API publishing."
    }

    private func selectedPublishReceipt(from records: [PublishReceiptRecord]) -> PublishReceiptRecord? {
        guard let publishReceiptEditId else { return nil }
        return records.first { $0.id == publishReceiptEditId }
    }

    private func isSocialShortReceipt(_ record: PublishReceiptRecord) -> Bool {
        record.deliveryLaneId == "social-short-clips"
            || record.deliveryLaneId.hasPrefix("social-short-clips/")
    }

    private func socialShortPublishRecords(from records: [PublishReceiptRecord]) -> [PublishReceiptRecord] {
        records.filter { record in
            isSocialShortReceipt(record)
                || (record.format == "9:16" && record.artifactType.lowercased().contains("short"))
        }
    }

    private func uniqueSocialShortArtifactPaths(from records: [PublishReceiptRecord]) -> [String] {
        var seen: Set<String> = []
        var paths: [String] = []
        for record in records {
            let path = record.artifactPath.trimmingCharacters(in: .whitespacesAndNewlines)
            guard !path.isEmpty,
                  !seen.contains(path),
                  FileManager.default.fileExists(atPath: path) else {
                continue
            }
            seen.insert(path)
            paths.append(path)
        }
        return paths
    }

    private func socialPublicationTopTitles(from records: [PublishReceiptRecord], limit: Int) -> [String] {
        var seen: Set<String> = []
        return records
            .sorted { lhs, rhs in
                let left = socialPublicationRank(for: lhs.title, fallback: 999)
                let right = socialPublicationRank(for: rhs.title, fallback: 999)
                if left == right {
                    return lhs.title < rhs.title
                }
                return left < right
            }
            .compactMap { record in
                let title = record.title.trimmingCharacters(in: .whitespacesAndNewlines)
                guard !title.isEmpty, seen.insert(title).inserted else { return nil }
                return title
            }
            .prefix(limit)
            .map { $0 }
    }

    private func publishReceiptDisplayLabel(_ record: PublishReceiptRecord) -> String {
        guard isSocialShortReceipt(record) else {
            return "\(record.platform) / \(record.deliveryLaneId)"
        }
        let title = record.title.trimmingCharacters(in: .whitespacesAndNewlines)
        return "\(record.platform) / \(title.isEmpty ? publishReceiptLaneDisplayLabel(record) : title)"
    }

    private func publishReceiptLaneDisplayLabel(_ record: PublishReceiptRecord) -> String {
        guard isSocialShortReceipt(record) else {
            return record.deliveryLaneId
        }
        let shortId = record.deliveryLaneId
            .replacingOccurrences(of: "social-short-clips/", with: "")
            .prefix(8)
        return "Social short \(shortId)"
    }

