    private func publishStatusColor(_ publishStatus: String, uploadJobStatus: String) -> Color {
        switch publishStatus {
        case "published":
            return .yellow
        case "scheduled":
            return .blue
        case "uploaded":
            return .cyan
        case "ready-to-upload":
            return uploadJobStatus == "integration-needed" ? .orange : .green
        case "failed", "blocked":
            return .red
        case "needs-export":
            return .purple
        default:
            return .secondary
        }
    }

    private func publishStatusIcon(_ publishStatus: String, uploadJobStatus: String) -> String {
        switch publishStatus {
        case "published":
            return "checkmark.seal.fill"
        case "scheduled":
            return "calendar.badge.clock"
        case "uploaded":
            return "icloud.and.arrow.up.fill"
        case "ready-to-upload":
            return uploadJobStatus == "integration-needed" ? "point.3.connected.trianglepath.dotted" : "arrow.up.circle.fill"
        case "failed", "blocked":
            return "exclamationmark.triangle.fill"
        case "needs-export":
            return "shippingbox.fill"
        default:
            return "circle.dashed"
        }
    }

    private func publishStatusLabel(_ publishStatus: String, uploadJobStatus: String) -> String {
        if publishStatus == "ready-to-upload" && uploadJobStatus == "integration-needed" {
            return "API NEEDED"
        }
        return publishStatus
            .replacingOccurrences(of: "-", with: " ")
            .uppercased()
    }

    private func publishLedgerNextActionText(records: [PublishReceiptRecord]) -> String {
        if records.contains(where: { $0.publishStatus == "needs-export" }) {
            return "Next: run release prep again so every platform record points at a real artifact."
        }
        if records.contains(where: { $0.uploadJobStatus == "integration-needed" }) {
            return "Next: connect platform OAuth/API workers. Until then, copy metadata/job JSON and use manual upload while preserving receipt records."
        }
        if records.contains(where: { $0.publishStatus == "uploaded" || $0.publishStatus == "scheduled" }) {
            return "Next: confirm live URLs and mark receipts published when the platform confirms them."
        }
        if records.allSatisfy({ $0.publishStatus == "published" }) {
            return "All platform receipts are marked published. Future analytics can attach to these receipt records."
        }
        return "Next: review metadata, upload/schedule, and save platform receipts without touching the rendered artifacts."
    }

    private var deliveryPacketStatusColor: Color {
        switch deliveryPacketStatus {
        case "generated":
            return .green
        case "generating":
            return .blue
        case "blocked":
            return .orange
        case "failed":
            return .red
        default:
            return .cyan
        }
    }

    private var deliveryPacketStatusIcon: String {
        switch deliveryPacketStatus {
        case "generated":
            return "checkmark.seal.fill"
        case "generating":
            return "arrow.triangle.2.circlepath"
        case "blocked":
            return "exclamationmark.triangle.fill"
        case "failed":
            return "xmark.octagon.fill"
        default:
            return "doc.badge.gearshape"
        }
    }

    private var deliveryPacketStatusDetail: String {
        switch deliveryPacketStatus {
        case "generated":
            return deliveryPacketOutputPath.isEmpty
                ? "Packet generated. No output path was recorded."
                : "Packet ready: \(URL(fileURLWithPath: deliveryPacketOutputPath).lastPathComponent)"
        case "generating":
            return "Building the JSON handoff from current export, shorts, audio, and publishing readiness."
        case "blocked", "failed":
            return deliveryPacketErrorMessage.isEmpty ? "Packet needs attention." : deliveryPacketErrorMessage
        default:
            return "Generate an inspectable publishing handoff before upload/scheduling work."
        }
    }

    private var editorProofPanel: some View {
        let sequence = projectStore.activeSequence
        let summary = mediaReadinessSummary()
        let videoMonitorCount = sequence?.lanes.filter { !isSupportOnlyLane($0) }.count ?? 0
        let playableVideoMonitorCount = sequence.map { playableProgramLanes(in: $0).count } ?? 0
        let sourcePlayerCount = playbackEngine.sourcePlayers.count
        let canScrubSyncedSources = videoMonitorCount > 0 && sourcePlayerCount >= videoMonitorCount
        let canScrubAvailableSources = playableVideoMonitorCount > 0 && sourcePlayerCount >= playableVideoMonitorCount
        let canPlayEdit = !playbackEngine.validRanges.isEmpty && (summary.showDecisionCount > 0 || summary.skipDecisionCount > 0)
        let canEditAvailableSourcesNow = playableVideoMonitorCount > 0 && canScrubAvailableSources && canPlayEdit
        let canEditNow = summary.isVideoRoughCutReady && canScrubSyncedSources && canPlayEdit
        let color: Color = canEditNow ? QuipslyStudioTheme.moss : (canEditAvailableSourcesNow ? QuipslyStudioTheme.creek : (sequence == nil ? QuipslyStudioTheme.sage : QuipslyStudioTheme.clay))
        let title = canEditNow
            ? "Editing path is open"
            : (canEditAvailableSourcesNow ? "You can cut while recovery continues" : (sequence == nil ? "Load an episode to begin" : "A few roots need attention"))
        let detail = canEditNow
            ? "Program, source grove, proxies, and decision ranges are all present enough for real editing."
            : (canEditAvailableSourcesNow
               ? "\(playableVideoMonitorCount) playable source monitor(s) are ready now. \(max(0, videoMonitorCount - playableVideoMonitorCount)) source(s) stay visible as recovery work before final export."
            : (sequence == nil
               ? "Load a native session or import whole sources before editing."
               : "Use the calm status chips below to see what still needs work before trusting this as a production edit."))

        return VStack(alignment: .leading, spacing: 9) {
            HStack(spacing: 10) {
                Image(systemName: canEditNow ? "leaf.circle.fill" : "stethoscope")
                    .font(.title3)
                    .foregroundStyle(color)
                    .frame(width: 28, height: 28)
                    .background(color.opacity(0.14))
                    .clipShape(Circle())

                VStack(alignment: .leading, spacing: 2) {
                    Text(title)
                        .font(.subheadline)
                        .fontWeight(.semibold)
                    Text(detail)
                        .font(.caption)
                        .foregroundStyle(.secondary)
                        .lineLimit(2)
                }

                Spacer()

                    Text(canEditNow ? "READY" : (canEditAvailableSourcesNow ? "WORKABLE" : "CHECK"))
                    .font(.caption2)
                    .fontWeight(.black)
                    .foregroundStyle(color)
                    .padding(.horizontal, 8)
                    .padding(.vertical, 4)
                    .background(color.opacity(0.12))
                    .clipShape(Capsule())
            }

            HStack(spacing: 8) {
                proofChip("Sources", "\(sourcePlayerCount)/\(videoMonitorCount)", canScrubSyncedSources ? QuipslyStudioTheme.moss : (canScrubAvailableSources ? QuipslyStudioTheme.creek : QuipslyStudioTheme.clay))
                proofChip("Playable", "\(playableVideoMonitorCount)", canEditAvailableSourcesNow ? QuipslyStudioTheme.creek : QuipslyStudioTheme.clay)
                proofChip("Proxies", "\(summary.videoProxyReadyCount)/\(videoMonitorCount)", summary.videoBlockedCount == 0 ? QuipslyStudioTheme.moss : QuipslyStudioTheme.clay)
                proofChip("Play Edit [Space]", "\(playbackEngine.validRanges.count) ranges", canPlayEdit ? QuipslyStudioTheme.moss : QuipslyStudioTheme.clay)
                proofChip("SHOW", "\(summary.showDecisionCount)", summary.showDecisionCount > 0 ? QuipslyStudioTheme.moss : QuipslyStudioTheme.clay)
                proofChip("SKIP", "\(summary.skipDecisionCount)", summary.skipDecisionCount > 0 ? QuipslyStudioTheme.moss : QuipslyStudioTheme.sage)
                Spacer()
            }
        }
        .padding(10)
        .background(
            LinearGradient(
                colors: [
                    color.opacity(0.08),
                    QuipslyStudioTheme.panelWarm.opacity(0.48)
                ],
                startPoint: .topLeading,
                endPoint: .bottomTrailing
            )
        )
        .overlay(
            RoundedRectangle(cornerRadius: 14, style: .continuous)
                .stroke(color.opacity(0.20), lineWidth: 1)
        )
        .clipShape(RoundedRectangle(cornerRadius: 14, style: .continuous))
    }

