    private var workingSetStatusPanel: some View {
        let summary = mediaReadinessSummary()
        let truth = workingSetTruthPayload(for: projectStore.activeSequence, summary: summary)
        let status = truth["status"] as? String ?? "unknown"
        let sufficient = truth["sufficientForEditingNow"] as? Bool ?? false
        let primaryReady = truth["primaryCameraProxyReadyCount"] as? Int ?? 0
        let placeholderCount = truth["shortOrPlaceholderCameraLaneCount"] as? Int ?? 0
        let missingPrimary = truth["missingPrimaryCameraLaneCount"] as? Int ?? 0
        let summaryText = truth["summary"] as? String ?? "Working set truth is not available yet."
        let nextAction = truth["nextAction"] as? String ?? "Load or import media before editing."
        let color: Color = sufficient ? QuipslyStudioTheme.moss : (primaryReady > 0 ? QuipslyStudioTheme.honey : QuipslyStudioTheme.clay)
        let icon = sufficient ? "person.2.wave.2.fill" : (primaryReady > 0 ? "person.crop.rectangle.stack" : "questionmark.video")

        return HStack(alignment: .top, spacing: 10) {
            Image(systemName: icon)
                .font(.title3)
                .foregroundStyle(color)
                .frame(width: 28, height: 28)
                .background(color.opacity(0.14))
