                        .clipShape(Capsule())
                }

                Text(summaryText)
                    .font(.caption)
                    .foregroundStyle(.secondary)
                    .lineLimit(2)

                Text(nextAction)
                    .font(.caption2)
                    .foregroundStyle(color)
                    .lineLimit(2)

