    private struct SourceReadiness {
        var label: String
        var detail: String
        var systemImage: String
        var color: Color
        var isReady: Bool
        var playbackPath: String
        var needsStorageAccess: Bool = false
    }

    private func sourceReadiness(for lane: VideoLane) -> SourceReadiness {
        if lane.metadata?.ignoreForProduction == true {
            return SourceReadiness(
                label: "Held for recovery",
                detail: "This lane is preserved in the session but intentionally excluded from Play Edit [Space], production readiness, and exports until unheld or relinked.",
                systemImage: "archivebox",
                color: .secondary,
                isReady: false,
                playbackPath: "",
                needsStorageAccess: false
            )
        }

        guard let source = lane.sourceVideo else {
            return SourceReadiness(
                label: "No source",
                detail: "No source linked",
                systemImage: "video.slash",
                color: .secondary,
                isReady: false,
                playbackPath: ""
            )
        }

        let kind = lane.metadata?.mediaKind.lowercased() ?? source.mediaURL.pathExtension.lowercased()
        let proxyPath = source.proxyURL?.path
        let proxyURL = proxyPath.map { URL(fileURLWithPath: $0) }
        let rawPath = source.mediaURL.path
        let hasProxyFile = proxyURL.map { externalMediaAccess.fileExistsWithoutPrompt(at: $0) == true } ?? false
        let proxyNeedsStorageAccess = proxyURL.map { !externalMediaAccess.canProbeWithoutPrompt($0) } ?? false
        let declaredExists = lane.metadata?.declaredExists == true
        let originalURL = URL(fileURLWithPath: rawPath)
        let originalNeedsStorageAccess = isExternalOriginalPath(rawPath) && !externalMediaAccess.canProbeWithoutPrompt(originalURL)
        let needsStorageAccess = originalNeedsStorageAccess || proxyNeedsStorageAccess
        let proxyFailure = proxyFailureByLaneId[lane.id]
        let protectedOriginalWithoutGrant = originalNeedsStorageAccess && !externalMediaAccess.hasExplicitFolderGrant
        let protectedProxyWithoutGrant = proxyNeedsStorageAccess && !externalMediaAccess.hasExplicitFolderGrant

        if kind == "audio" || isAudioPath(rawPath) {
            if let proxyPath, hasProxyFile {
                switch audioProxyValidationStatus(proxyPath: proxyPath, expectedDuration: source.duration) {
                case .ready:
                    break
                case .pending(let detail):
                    return SourceReadiness(
                        label: "Audio proxy validating",
                        detail: detail,
                        systemImage: "waveform.badge.magnifyingglass",
                        color: .orange,
                        isReady: false,
                        playbackPath: proxyPath,
                        needsStorageAccess: needsStorageAccess
                    )
                case .blocked(let detail):
                    return SourceReadiness(
                        label: "Audio proxy blocked",
                        detail: detail,
                        systemImage: "waveform.badge.exclamationmark",
                        color: .red,
                        isReady: false,
                        playbackPath: proxyPath,
                        needsStorageAccess: needsStorageAccess
                    )
                }

                return SourceReadiness(
                    label: "Audio proxy-safe",
                    detail: needsStorageAccess
                        ? "Local audio proxy available. Grant storage access only for relink, regeneration, or raw-source work."
                        : "Local audio proxy available",
                    systemImage: needsStorageAccess ? "externaldrive.badge.questionmark" : "waveform",
                    color: .green,
                    isReady: true,
                    playbackPath: proxyPath,
                    needsStorageAccess: needsStorageAccess
                )
            }

            if protectedProxyWithoutGrant {
                return SourceReadiness(
                    label: "Proxy protected",
                    detail: "This proxy path is in a protected folder. Attach or rebuild the proxy into the Quipsly MediaVault before previewing.",
                    systemImage: "externaldrive.badge.exclamationmark",
                    color: .orange,
                    isReady: false,
                    playbackPath: "",
                    needsStorageAccess: true
                )
            }

            if let proxyFailure {
                return SourceReadiness(
                    label: "Audio proxy blocked",
                    detail: proxyFailure,
                    systemImage: "waveform.badge.exclamationmark",
                    color: .red,
                    isReady: false,
                    playbackPath: proxyPath ?? "",
                    needsStorageAccess: needsStorageAccess
                )
            }

            if source.proxyURL != nil {
                return SourceReadiness(
                    label: "Audio proxy missing",
                    detail: "The expected local audio proxy is not in the vault yet. Generate or attach a full-length .m4a proxy; do not preview from the giant original WAV.",
                    systemImage: "waveform.badge.exclamationmark",
                    color: .orange,
                    isReady: false,
                    playbackPath: proxyPath ?? "",
                    needsStorageAccess: needsStorageAccess
                )
            }

            if protectedOriginalWithoutGrant {
                return SourceReadiness(
                    label: "Original protected",
                    detail: "Original audio is remembered outside the vault. Quipsly will not probe it until you grant access; attach or generate a proxy for production work.",
                    systemImage: "externaldrive.badge.exclamationmark",
                    color: .orange,
                    isReady: false,
                    playbackPath: "",
                    needsStorageAccess: true
                )
            }

            let hasRawFile = originalExistsForReadiness(path: rawPath, declaredExists: declaredExists)
            return SourceReadiness(
                label: hasRawFile ? "Audio proxy needed" : "Audio held",
                detail: hasRawFile
                    ? "Create a local audio proxy before production preview; keep the original WAV untouched."
                    : "Audio file not local yet",
                systemImage: hasRawFile ? "waveform.badge.exclamationmark" : "clock",
                color: .orange,
                isReady: false,
                playbackPath: "",
                needsStorageAccess: needsStorageAccess
                )
        }

        if let proxyFailure {
            return SourceReadiness(
                label: "Proxy blocked",
                detail: proxyFailure,
                systemImage: "video.badge.exclamationmark",
                color: .red,
                isReady: false,
                playbackPath: proxyPath ?? "",
                needsStorageAccess: needsStorageAccess
                )
        }

        if protectedProxyWithoutGrant {
            return SourceReadiness(
                label: "Proxy protected",
                detail: "This proxy path is in a protected folder. Attach or rebuild a full-length proxy into the Quipsly MediaVault before previewing.",
                systemImage: "externaldrive.badge.exclamationmark",
                color: .orange,
                isReady: false,
                playbackPath: "",
                needsStorageAccess: true
            )
        }

        if let proxyPath, hasProxyFile {
            if videoProxyValidationInFlight.contains(proxyPath) {
                return SourceReadiness(
                    label: "Proxy validating",
                    detail: "Verifying this video proxy covers the whole source lane before production editing.",
                    systemImage: "video.badge.magnifyingglass",
                    color: .orange,
                    isReady: false,
                    playbackPath: proxyPath,
                    needsStorageAccess: needsStorageAccess
                )
            }

                return SourceReadiness(
                    label: "Proxy ready",
                    detail: needsStorageAccess
                        ? "Proxy video available. Grant storage access only for relink, regeneration, or raw-source work."
                        : "Proxy video available",
                    systemImage: needsStorageAccess ? "externaldrive.badge.questionmark" : "bolt.fill",
                    color: .green,
                    isReady: true,
                    playbackPath: proxyPath,
                    needsStorageAccess: needsStorageAccess
                )
        }

        if source.proxyURL != nil {
            return SourceReadiness(
                label: "Proxy pending",
                detail: "Proxy path is declared; preview will not touch the original video",
                systemImage: "hourglass",
                color: .orange,
                isReady: false,
                playbackPath: proxyPath ?? "",
                needsStorageAccess: needsStorageAccess
            )
        }

        if protectedOriginalWithoutGrant {
            return SourceReadiness(
                label: "Original protected",
                detail: "Original video is remembered outside the vault. Quipsly will not probe it until you grant access; attach or generate a full-length proxy for playback.",
                systemImage: "externaldrive.badge.exclamationmark",
                color: .orange,
                isReady: false,
                playbackPath: "",
                needsStorageAccess: true
            )
        }

        if lane.metadata?.declaredExists == false || rawPath.contains("__quipsly_missing_media__") {
            return SourceReadiness(
                label: "Missing source",
                detail: "Premiere packet references media that is not linked yet",
                systemImage: "exclamationmark.triangle",
                color: .red,
                isReady: false,
                playbackPath: ""
            )
        }

        if lane.metadata?.isPremiereRescue == true {
            return SourceReadiness(
                label: "Source held",
                detail: "Premiere packet path is preserved; relink or generate a proxy before preview",
                systemImage: "clock",
                color: .orange,
                isReady: false,
                playbackPath: ""
            )
        }

        let hasRawFile = originalExistsForReadiness(path: rawPath, declaredExists: declaredExists)
        if hasRawFile {
            return SourceReadiness(
                label: "Proxy required",
                detail: needsStorageAccess
                    ? "Original is linked, but storage access should be granted intentionally before proxy generation or relink work"
                    : "Original video is linked; generate a proxy before editor playback",
                systemImage: "bolt.slash",
                color: .orange,
                isReady: false,
                playbackPath: "",
                needsStorageAccess: needsStorageAccess
            )
        }

        return SourceReadiness(
            label: "Source held",
            detail: "File is known, but not local/playable yet",
            systemImage: "clock",
            color: .orange,
            isReady: false,
            playbackPath: ""
        )
    }

    private enum ProxyValidationStatus {
        case ready
        case pending(String)
        case blocked(String)
    }

    private func audioProxyValidationStatus(proxyPath: String, expectedDuration: Double) -> ProxyValidationStatus {
        guard expectedDuration.isFinite, expectedDuration > 10 else {
            return .ready
        }

        if let cached = audioProxyValidationByPath[proxyPath] {
            return cached.isEmpty ? .ready : .blocked(cached)
        }

        scheduleAudioProxyValidation(proxyPath: proxyPath, expectedDuration: expectedDuration)
        return .pending("Verifying audio proxy duration before production editing.")
    }

    private func scheduleAudioProxyValidation(proxyPath: String, expectedDuration: Double) {
        guard !audioProxyValidationInFlight.contains(proxyPath) else { return }

        audioProxyValidationInFlight.insert(proxyPath)
        Task.detached(priority: .utility) {
            let issue: String
            do {
                let asset = AVURLAsset(url: URL(fileURLWithPath: proxyPath))
                let duration = try await asset.load(.duration)
                let proxyDuration = CMTimeGetSeconds(duration)
                if !proxyDuration.isFinite || proxyDuration <= 0 {
                    issue = "Proxy exists, but its duration could not be verified. Rebuild or attach a readable whole-lane proxy."
                } else {
                    let tolerance = max(2.0, expectedDuration * 0.01)
                    if proxyDuration + tolerance < expectedDuration {
                        issue = String(
                            format: "Proxy is too short for this whole lane: proxy %.1fs vs source %.1fs. Attach or generate a full-length proxy before production editing.",
                            proxyDuration,
                            expectedDuration
                        )
                    } else {
                        issue = ""
                    }
                }
            } catch {
                issue = "Proxy exists, but its duration could not be verified: \(error.localizedDescription). Rebuild or attach a readable whole-lane proxy."
            }

            await MainActor.run {
                audioProxyValidationByPath[proxyPath] = issue
                audioProxyValidationInFlight.remove(proxyPath)
                updateAgentState()
            }
        }
    }

    private func isExternalOriginalPath(_ path: String) -> Bool {
        ExternalMediaAccess.isProtectedUserMediaPath(path)
    }

    private func shouldProbeOriginalPath(_ path: String) -> Bool {
        guard !path.isEmpty else { return false }
        if isExternalOriginalPath(path) {
            let url = URL(fileURLWithPath: path)
            return externalMediaAccess.canProbeWithoutPrompt(url)
        }
        return true
    }

    private func originalExistsForReadiness(path: String, declaredExists: Bool) -> Bool {
        guard !path.isEmpty else { return false }
        let url = URL(fileURLWithPath: path)
        if isExternalOriginalPath(path) {
            return externalMediaAccess.fileExistsWithoutPrompt(at: url) ?? declaredExists
        }
        return externalMediaAccess.fileExistsWithoutPrompt(at: url) ?? declaredExists
    }

    private func canProbeOriginalForUserInitiatedImport(_ url: URL, allowProtectedOriginalProbe: Bool) -> Bool {
        let path = url.standardizedFileURL.path
        guard isExternalOriginalPath(path) else { return true }
        if externalMediaAccess.canProbeWithoutPrompt(url) {
            return true
        }
        return allowProtectedOriginalProbe
    }

    private struct DecisionMarker {
        var laneId: UUID
        var tagId: UUID
        var type: TagType
        var sequenceTime: Double
        var laneName: String
    }

    private func decisionMarkers(scope: String = "all", laneId: String? = nil) -> [DecisionMarker] {
        guard let sequence = projectStore.activeSequence else { return [] }
        let normalizedScope = normalizedDecisionScope(scope)

        return sequence.lanes
            .filter { lane in
                if let laneId, !laneId.isEmpty, !laneMatches(lane, laneId: laneId) {
                    return false
                }
                switch normalizedScope {
                case "video":
                    return !isSupportOnlyLane(lane)
                case "support":
                    return isSupportOnlyLane(lane)
                default:
                    return true
                }
            }
            .flatMap { lane -> [DecisionMarker] in
            let offset = lane.sourceVideo?.offset ?? 0
            return lane.tags.compactMap { tag in
                guard tag.type == .active || tag.type == .cut else { return nil }
                return DecisionMarker(
                    laneId: lane.id,
                    tagId: tag.id,
                    type: tag.type,
                    sequenceTime: max(0, tag.startTime + offset),
                    laneName: lane.name
                )
            }
        }
        .sorted {
            if abs($0.sequenceTime - $1.sequenceTime) > 0.001 {
                return $0.sequenceTime < $1.sequenceTime
            }
            return $0.laneName < $1.laneName
        }
    }

    private func decisionBoundaryMarkers(scope: String = "video", laneId: String? = nil) -> [DecisionMarker] {
        let markers = decisionMarkers(scope: scope, laneId: laneId)
        guard !markers.isEmpty else { return [] }

        let boundaryTolerance = 0.05
        var groups: [[DecisionMarker]] = []
        for marker in markers {
            if let lastGroup = groups.indices.last,
               let groupTime = groups[lastGroup].first?.sequenceTime,
               abs(marker.sequenceTime - groupTime) <= boundaryTolerance {
                groups[lastGroup].append(marker)
            } else {
                groups.append([marker])
            }
        }

        return groups.compactMap { group in
            group.first(where: { $0.type == .active }) ?? group.first
        }
    }

    private func visualDecisionBoundariesForTimeline() -> [TimelineReviewBoundary] {
        decisionBoundaryMarkers(scope: "video").map { marker in
            TimelineReviewBoundary(
                laneId: marker.laneId,
                tagId: marker.tagId,
                type: marker.type,
                sequenceTime: marker.sequenceTime,
                laneName: marker.laneName
            )
        }
    }

    private func sourceDecisionBoundariesForTimeline(laneId: UUID?) -> [TimelineReviewBoundary] {
        guard let laneId else { return [] }
        return decisionBoundaryMarkers(scope: "video", laneId: laneId.uuidString).map { marker in
            TimelineReviewBoundary(
                laneId: marker.laneId,
                tagId: marker.tagId,
                type: marker.type,
                sequenceTime: marker.sequenceTime,
                laneName: marker.laneName
            )
        }
    }

    private func sourceReviewBoundaryCount(for lane: VideoLane) -> Int {
        decisionBoundaryMarkers(scope: "video", laneId: lane.id.uuidString).count
    }

    private func selectReviewBoundary(_ boundary: TimelineReviewBoundary) {
        selectedLaneId = boundary.laneId
        selectedTagId = boundary.tagId
        playbackEngine.seek(to: max(0, boundary.sequenceTime))
        lastMediaAction = String(
            format: "Selected visual review stop at %.2fs on %@",
            boundary.sequenceTime,
            boundary.laneName
        )
        updateAgentState()
    }

    private func normalizedDecisionScope(_ scope: String?) -> String {
        let normalized = (scope ?? "all").lowercased().replacingOccurrences(of: "-", with: "_")
        if ["video", "visual", "source", "camera"].contains(normalized) {
            return "video"
        }
        if ["support", "audio", "context"].contains(normalized) {
            return "support"
        }
        return "all"
    }

    private func visualDecisionReviewState(for sequence: MediaSequence) -> (count: Int, selectedIndex: Int, selectedSequenceTime: Double) {
        let markers = decisionBoundaryMarkers(scope: "video")
        guard let selectedLaneId,
              let selectedTagId,
              let selectedLane = sequence.lanes.first(where: { $0.id == selectedLaneId }),
              let selectedTag = selectedLane.tags.first(where: { $0.id == selectedTagId }) else {
            return (markers.count, -1, 0)
        }

        let selectedSequenceTime = (selectedLane.sourceVideo?.offset ?? 0) + selectedTag.startTime
        let index = markers.firstIndex(where: { $0.laneId == selectedLaneId && $0.tagId == selectedTagId })
            ?? markers.firstIndex(where: { abs($0.sequenceTime - selectedSequenceTime) <= 0.05 })
        guard let index else {
            return (markers.count, -1, selectedSequenceTime)
        }
        return (markers.count, index + 1, markers[index].sequenceTime)
    }

    private func jumpToAdjacentDecision(direction: Int, scope: String = "video") {
        let normalizedScope = normalizedDecisionScope(scope)
        let markers = normalizedScope == "video"
            ? decisionBoundaryMarkers(scope: normalizedScope)
            : decisionMarkers(scope: normalizedScope)
        guard !markers.isEmpty else {
            let scopeLabel = normalizedScope == "all" ? "" : " \(normalizedScope)"
            lastMediaAction = "No\(scopeLabel) edit decisions to navigate yet"
            updateAgentState()
            return
        }

        let playhead = playbackEngine.playhead
        let marker: DecisionMarker
        if direction >= 0 {
            marker = markers.first(where: { $0.sequenceTime > playhead + 0.05 }) ?? markers.first!
        } else {
            marker = markers.last(where: { $0.sequenceTime < playhead - 0.05 }) ?? markers.last!
        }

        selectedLaneId = marker.laneId
        selectedTagId = marker.tagId
        playbackEngine.seek(to: marker.sequenceTime)
        lastMediaAction = "\(direction >= 0 ? "Next" : "Previous") \(normalizedScope) decision: \(marker.type.rawValue.uppercased()) on \(marker.laneName)"
        updateAgentState()
    }

    private func jumpToAdjacentSourceDecision(direction: Int, laneId: UUID) {
        let markers = decisionBoundaryMarkers(scope: "video", laneId: laneId.uuidString)
        guard !markers.isEmpty else {
            selectedLaneId = laneId
            selectedTagId = nil
            lastMediaAction = "No source-specific SHOW/SKIP decisions to navigate yet"
            updateAgentState()
            return
        }

        let playhead = playbackEngine.playhead
        let marker: DecisionMarker
        if direction >= 0 {
            marker = markers.first(where: { $0.sequenceTime > playhead + 0.05 }) ?? markers.first!
        } else {
            marker = markers.last(where: { $0.sequenceTime < playhead - 0.05 }) ?? markers.last!
        }

        selectedLaneId = marker.laneId
        selectedTagId = marker.tagId
        playbackEngine.seek(to: marker.sequenceTime)
        lastMediaAction = "\(direction >= 0 ? "Next" : "Previous") source stop: \(marker.type.rawValue.uppercased()) on \(marker.laneName)"
        updateAgentState()
    }

    private func selectFirstMediaIssue() {
        guard let sequence = projectStore.activeSequence else {
            lastMediaAction = "No sequence loaded"
            updateAgentState()
            return
        }

        guard let lane = sequence.lanes.first(where: { !sourceReadiness(for: $0).isReady }) else {
            lastMediaAction = "No media issues found"
            updateAgentState()
            return
        }

        selectedLaneId = lane.id
        selectedTagId = nil
        let offset = max(0, lane.sourceVideo?.offset ?? 0)
        playbackEngine.seek(to: offset)
        lastMediaAction = "Selected first media issue: \(lane.name) (\(sourceReadiness(for: lane).label))"
        updateAgentState()
    }

    private func isAudioPath(_ path: String) -> Bool {
        let ext = URL(fileURLWithPath: path).pathExtension.lowercased()
        return ["wav", "aif", "aiff", "mp3", "m4a", "aac", "flac"].contains(ext)
    }

    private func plannedProxyURLExists(for url: URL) -> Bool {
        guard let plannedProxyURL = try? LocalMediaVault.shared.proxyURL(for: url) else {
            return false
        }
        return externalMediaAccess.fileExistsWithoutPrompt(at: plannedProxyURL) == true
    }

