    private func programMonitorHelpText(shouldBlankProgram: Bool) -> String {
        if let lane = programCropGestureLane() {
            return "Selected \(lane.name): drag/pinch the Program Output to adjust \(programCropGestureTargetDescription()). Switch Position + zoom mode between Base frame and Keyframe in the inspector. Two-finger scroll still scrubs the shared timeline."
        }

        if let lane = selectedProgramCropLane(), lane.sourceVideo?.is360 == true {
            return "Selected 360 lane \(lane.name): drag adjusts yaw/pitch keyframes and pinch adjusts FOV. Two-finger scroll still scrubs the shared timeline."
        }

        if shouldBlankProgram {
            return "Play Edit has no SHOW decision at this sequence time, so the program output is intentionally blank. Select a source lane to drag/pinch \(programCropGestureTargetDescription()). Two-finger scroll still scrubs the whole sequence."
        }

        return "Program output: the edit result, driven by SHOW/SKIP metadata over whole source lanes. Select a source lane to drag/pinch \(programCropGestureTargetDescription()). Two-finger scroll scrubs the timeline."
    }

    private func programCropGestureTargetDescription() -> String {
        switch programCropEditMode {
        case .baseline:
            return "the whole-lane base frame"
        case .keyframe:
            return "a timed crop keyframe at the shared playhead"
        }
    }

    private func programCropGestureLane() -> VideoLane? {
        guard let lane = selectedProgramCropLane(),
              lane.sourceVideo != nil,
              lane.sourceVideo?.is360 != true,
              !isSupportOnlyLane(lane) else {
            return nil
        }
        return lane
    }

    private func beginProgramCropGestureIfNeeded() {
        guard !isProgramCropGestureActive else { return }
        startProgramCrop = programCropEditMode == .baseline
            ? selectedProgramCropAdjustment()
            : selectedProgramCropAtPlayheadAdjustment()
        lastProgramCropGestureCommit = .distantPast
        isProgramCropGestureActive = true
    }

    private func applyProgramCropDragGesture(_ value: DragGesture.Value, final: Bool) {
        guard let lane = programCropGestureLane() else { return }
        beginProgramCropGestureIfNeeded()
        let panSensitivity = 0.0025
        let next = ProgramCropAdjustment(
            panX: startProgramCrop.panX + (Double(value.translation.width) * panSensitivity),
            panY: startProgramCrop.panY + (Double(value.translation.height) * panSensitivity),
            zoom: startProgramCrop.zoom
        )
        commitProgramCropGesture(next, lane: lane, final: final)
    }

    private func applyProgramCropMagnificationGesture(_ value: MagnificationGesture.Value, final: Bool) {
        guard let lane = programCropGestureLane() else { return }
        beginProgramCropGestureIfNeeded()
        let next = ProgramCropAdjustment(
            panX: startProgramCrop.panX,
            panY: startProgramCrop.panY,
            zoom: startProgramCrop.zoom * Double(value)
        )
        commitProgramCropGesture(next, lane: lane, final: final)
    }

    private func commitProgramCropGesture(_ crop: ProgramCropAdjustment, lane: VideoLane, final: Bool) {
        let now = Date()
        guard final || now.timeIntervalSince(lastProgramCropGestureCommit) >= 0.12 else {
            return
        }
        lastProgramCropGestureCommit = now

        switch programCropEditMode {
        case .baseline:
            applyProgramCropAdjustment(
                laneId: lane.id.uuidString,
                format: playbackEngine.playbackFormat.rawValue,
                panX: crop.panX,
                panY: crop.panY,
                zoom: crop.zoom,
                panXDelta: nil,
                panYDelta: nil,
                zoomDelta: nil
            )
        case .keyframe:
            applyProgramCropKeyframe(
                laneId: lane.id.uuidString,
                format: playbackEngine.playbackFormat.rawValue,
                time: playbackEngine.playhead,
                panX: crop.panX,
                panY: crop.panY,
                zoom: crop.zoom,
                panXDelta: nil,
                panYDelta: nil,
                zoomDelta: nil
            )
        }
    }

    private func finishProgramCropGesture() {
        isProgramCropGestureActive = false
        startProgramCrop = selectedProgramCropAtPlayheadAdjustment()
    }

    private func decisionAtPlayhead(for lane: VideoLane) -> VideoTag? {
        let offset = lane.sourceVideo?.offset ?? 0
        let localTime = playbackEngine.playhead - offset
        return lane.tags
            .filter { tag in
                guard tag.type == .active || tag.type == .cut else { return false }
                return localTime >= tag.startTime && localTime < tag.startTime + tag.duration
            }
            .sorted {
                if $0.startTime == $1.startTime {
                    return $0.duration < $1.duration
                }
                return $0.startTime > $1.startTime
            }
            .first
    }

    private func decisionColor(_ type: TagType?) -> Color {
        switch type {
        case .active:
            return .yellow
        case .cut:
            return .red
        default:
            return .blue
        }
    }

    private func decisionLabel(_ type: TagType?) -> String {
        switch type {
        case .active:
            return "SHOW"
        case .cut:
