    private func selectedTagContext(in sequence: MediaSequence) -> (type: String, startTime: Double, duration: Double, laneName: String) {
        guard let selectedLaneId,
              let selectedTagId,
              let lane = sequence.lanes.first(where: { $0.id == selectedLaneId }),
              let tag = lane.tags.first(where: { $0.id == selectedTagId }) else {
            return ("", 0, 0, "")
        }

        return (
            tag.type.rawValue,
            tag.startTime,
            tag.duration,
            lane.name
        )
    }

    private func currentProgramState() -> (title: String, detail: String, color: Color, systemImage: String) {
        guard let sequence = projectStore.activeSequence, !sequence.lanes.isEmpty else {
            return (
                title: "No sequence loaded",
                detail: "Import media or load the demo edit to start building decisions.",
                color: .secondary,
                systemImage: "rectangle.stack.badge.plus"
            )
        }

        let programLanes = primaryProgramLanes(in: sequence)
        let playableProgramLanes = playableProgramLanes(in: sequence)
        let activeLanes = playableProgramLanes.filter { decisionAtPlayhead(for: $0)?.type == .active }
        let blockedActiveLanes = programLanes.filter { lane in
            decisionAtPlayhead(for: lane)?.type == .active && !sourceReadiness(for: lane).isReady
        }
        let cutLanes = playableProgramLanes.filter { decisionAtPlayhead(for: $0)?.type == .cut }

        if !activeLanes.isEmpty {
            let names = activeLanes.map(\.name).joined(separator: " + ")
            let blockedDetail = blockedActiveLanes.isEmpty
                ? ""
                : " \(blockedActiveLanes.count) unresolved active source(s) stay visible in the source grove for recovery."
            return (
                title: "Showing \(names)",
                detail: "Program output is driven by playable SHOW decisions at this sequence time.\(blockedDetail)",
                color: .yellow,
                systemImage: "eye.fill"
            )
        }

        if !blockedActiveLanes.isEmpty {
            let names = blockedActiveLanes.map(\.name).joined(separator: " + ")
            return (
                title: "Active source needs recovery",
                detail: "\(names) has a SHOW decision here, but no playable proxy/source. Relink the whole source or attach a full-length proxy.",
                color: .orange,
                systemImage: "externaldrive.badge.exclamationmark"
            )
        }

        if !playableProgramLanes.isEmpty, cutLanes.count == playableProgramLanes.count {
            return (
                title: "Skipping this section",
                detail: "Play Edit jumps over this gap. Play Through still shows the synced source lanes.",
                color: .red,
                systemImage: "forward.end.fill"
            )
        }

        if !cutLanes.isEmpty {
            let names = cutLanes.map(\.name).joined(separator: " + ")
            return (
                title: "Play Edit gap",
                detail: "\(names) are marked SKIP and no playable SHOW source is active here. Play Edit should jump this section; source monitors still reveal the whole synced lanes.",
                color: .red,
                systemImage: "forward.end.fill"
            )
        }

        if playableProgramLanes.isEmpty, !programLanes.isEmpty {
            return (
                title: "Sources need recovery",
                detail: "The edit decisions are preserved, but no visual source lane is playable yet. Relink whole originals or generate full-length proxies.",
                color: .orange,
                systemImage: "externaldrive.badge.exclamationmark"
            )
        }

        return (
            title: "Source-only section",
            detail: "No edit decision is active at this playhead. The original lanes are still intact.",
            color: .blue,
            systemImage: "rectangle.on.rectangle"
        )
    }

    private func primaryProgramLanes(in sequence: MediaSequence) -> [VideoLane] {
        let visualLanes = sequence.lanes.filter { !isSupportOnlyLane($0) }
        let productionEligibleLanes = visualLanes.filter { !laneIsParkedRecoveryForProgram($0) }
        if !productionEligibleLanes.isEmpty { return productionEligibleLanes }
        return visualLanes.isEmpty ? sequence.lanes : visualLanes
    }

    private func laneIsParkedRecoveryForProgram(_ lane: VideoLane) -> Bool {
        if lane.metadata?.ignoreForProduction == true { return true }
        let readiness = sourceReadiness(for: lane)
        if readiness.isReady { return false }
        if lane.sourceVideo?.mediaURL.path.contains("__quipsly_missing_media__") == true { return true }
        if workingSetLaneLooksMystery(lane) { return true }

        let duration = lane.sourceVideo?.duration ?? lane.duration
        let text = [
            lane.name,
            lane.metadata?.role ?? "",
            lane.metadata?.sourceLabel ?? "",
            lane.metadata?.originalPath ?? "",
            lane.sourceVideo?.mediaURL.path ?? ""
        ]
        .joined(separator: " ")
        .lowercased()

        let looksLikePlaceholder = text.contains("unresolved")
            || text.contains("missing")
            || text.contains("temp_video")
            || text.contains("video clip")
            || text.contains("placeholder")

        return looksLikePlaceholder || (duration > 0 && duration < 45 && looksLikePlaceholder)
    }

    private func playableProgramLanes(in sequence: MediaSequence) -> [VideoLane] {
        primaryProgramLanes(in: sequence).filter { lane in
            sourceReadiness(for: lane).isReady
        }
    }

