    private func requestMonitorFocus(reason: String) {
        isShowingProductionDetails = false
        lastMediaAction = reason
        monitorFocusRequest += 1
        updateAgentState()
    }

    private func requestTimelineFocus(reason: String) {
        isShowingProductionDetails = false
        lastMediaAction = reason
        timelineFocusRequest += 1
        updateAgentState()
        Task { @MainActor in
            try? await Task.sleep(nanoseconds: 350_000_000)
            updateAgentState()
        }
    }

    private func applyTimelineZoom(mode: String?, scale: Double?) {
        let normalizedMode = (mode ?? "").trimmingCharacters(in: .whitespacesAndNewlines).lowercased()
        let minimumScale = 0.08
        let maximumScale = 320.0

        switch normalizedMode {
        case "fit":
            isTimelineFitToWindow = true
        case "cut", "edit":
            isTimelineFitToWindow = false
            timelinePixelsPerSecond = min(maximumScale, max(minimumScale, 80))
        case "precision":
            isTimelineFitToWindow = false
            timelinePixelsPerSecond = min(maximumScale, max(120, timelinePixelsPerSecond))
        case "frame", "fine":
            isTimelineFitToWindow = false
            timelinePixelsPerSecond = min(maximumScale, max(minimumScale, 240))
        case "in", "zoom_in":
            isTimelineFitToWindow = false
            timelinePixelsPerSecond = min(maximumScale, timelinePixelsPerSecond * 1.5)
        case "out", "zoom_out":
            isTimelineFitToWindow = false
            timelinePixelsPerSecond = max(minimumScale, timelinePixelsPerSecond / 1.5)
        case "set":
            isTimelineFitToWindow = false
            timelinePixelsPerSecond = min(maximumScale, max(minimumScale, scale ?? timelinePixelsPerSecond))
        default:
            if let scale {
                isTimelineFitToWindow = false
                timelinePixelsPerSecond = min(maximumScale, max(minimumScale, scale))
            } else {
                isTimelineFitToWindow = false
                timelinePixelsPerSecond = min(maximumScale, max(120, timelinePixelsPerSecond))
            }
        }

        requestTimelineFocus(
            reason: isTimelineFitToWindow
                ? "Timeline zoom set to fit overview"
                : String(format: "Timeline zoom set to %.1f px/sec", timelinePixelsPerSecond)
        )
    }

    private func selectedDecisionQuickStrip(_ selected: (lane: VideoLane, tag: VideoTag)) -> some View {
        HStack(spacing: 10) {
            Label(selected.tag.type == .active ? "SHOW" : "SKIP", systemImage: selected.tag.type == .active ? "eye.fill" : "scissors")
                .font(.caption)
                .fontWeight(.bold)
                .foregroundStyle(selected.tag.type == .active ? Color.yellow : Color.red)
                .lineLimit(1)
                .fixedSize(horizontal: true, vertical: false)

            Text(selected.lane.name)
                .font(.caption)
                .lineLimit(1)
                .truncationMode(.middle)

            Text(String(format: "start %.2fs · end %.2fs · %.2fs", selected.tag.startTime, selected.tag.startTime + selected.tag.duration, selected.tag.duration))
                .font(.caption)
                .monospacedDigit()
                .foregroundStyle(.secondary)
                .lineLimit(1)
                .fixedSize(horizontal: true, vertical: false)

            Spacer()

            Button("Prev") { jumpToAdjacentDecision(direction: -1, scope: "video") }
                .help("Select the previous visual decision.")
            Button("Next") { jumpToAdjacentDecision(direction: 1, scope: "video") }
                .help("Select the next visual decision.")
            Button("-0.1") { nudgeSelectedTag(by: -0.1) }
            Button("+0.1") { nudgeSelectedTag(by: 0.1) }
            Button("Trim in") { trimSelectedTag(startDelta: 0.1, durationDelta: -0.1) }
            Button("Trim out") { trimSelectedTag(startDelta: 0, durationDelta: -0.1) }
            Button("1 Charlie") { switchSelectedDecision(to: .charlie) }
                .help("Switch this selected span so Charlie is the Program Output. Shortcut: 1 when a decision is selected.")
            Button("2 Homer") { switchSelectedDecision(to: .homer) }
                .help("Switch this selected span so Homer is the Program Output. Shortcut: 2 when a decision is selected.")
            Button("3 Both") { switchSelectedDecision(to: .both) }
                .help("Switch this selected span to a two-shot/multi-source SHOW. Shortcut: 3 when a decision is selected.")
            Button("4 Skip") { switchSelectedDecision(to: .skip) }
                .help("Switch this selected span to SKIP across visual sources. Shortcut: 4 when a decision is selected.")
            Button {
                seekToSelectedDecision(selected)
            } label: {
                Image(systemName: "arrow.turn.down.right")
            }
            Button {
                clearSelection()
            } label: {
                Image(systemName: "xmark")
            }
        }
        .buttonStyle(.bordered)
        .padding(8)
        .background((selected.tag.type == .active ? Color.yellow : Color.red).opacity(0.10))
        .overlay(
            RoundedRectangle(cornerRadius: 12, style: .continuous)
                .stroke((selected.tag.type == .active ? Color.yellow : Color.red).opacity(0.35), lineWidth: 1)
        )
        .clipShape(RoundedRectangle(cornerRadius: 12, style: .continuous))
        .help("Selected decision overlay. These controls move or trim metadata only; source media remains whole.")
    }

    private func selectedDecisionStats(_ selected: (lane: VideoLane, tag: VideoTag)) -> some View {
        let sourceOffset = selected.lane.sourceVideo?.offset ?? 0
        let sequenceStart = max(0, sourceOffset + selected.tag.startTime)
        return HStack(spacing: 8) {
            selectedDecisionStat("lane start", selected.tag.startTime, .blue)
            selectedDecisionStat("lane end", selected.tag.startTime + selected.tag.duration, .orange)
            selectedDecisionStat("duration", selected.tag.duration, selected.tag.type == .active ? .yellow : .red)
            selectedDecisionStat("sequence", sequenceStart, .green)
            Spacer()
        }
    }

