    private func externalStorageBannerTitle(for summary: MediaReadinessSummary) -> String {
        if summary.isProductionReady {
            return "Proxy production edit is ready. Originals are still protected."
        }
        if summary.hasAvailableProxyEditing {
            return "Available proxies are safe to edit. Recovery stays visible."
        }
        return "Originals are protected until proxies are ready."
    }

    private func externalStorageBannerDetail(for summary: MediaReadinessSummary) -> String {
        if summary.isProductionReady {
            return "\(summary.storageAccessNeededCount) original source lane(s) are remembered outside the vault. Preview uses proxies; grant folder access only for relink, waveform-from-originals, or raw-source operations."
        }
        if summary.hasAvailableProxyEditing {
            return "\(summary.videoProxyReadyCount) video proxy lane(s) and \(summary.audioReadyCount) audio/context proxy lane(s) are usable now. \(summary.sourceRecoveryCount) lane(s) still need recovery before final export. \(summary.storageAccessNeededCount) original path(s) remain protected outside the vault."
        }
        return "\(summary.storageAccessNeededCount) original source lane(s) are protected. Quipsly will not touch raw originals until you explicitly grant access or build a proxy."
    }

    private func mediaReadinessTitle(for summary: MediaReadinessSummary) -> String {
        if summary.isProductionReady {
            return "Production edit state is proxy-safe"
        }
        if summary.hasAvailableProxyEditing {
            return "Available proxy edit is usable; final export needs recovery"
        }
        return "Production edit state needs attention"
    }

