    private func proxyJobDetailText(_ snapshot: ProxyJobSnapshot) -> String {
        if !snapshot.hasJobFile {
            return "Run a proxy recovery pass to see live media-job progress here. This prevents long encodes from looking frozen."
        }
        let lane = snapshot.currentLane.isEmpty ? "no current lane" : snapshot.currentLane
        let session = snapshot.sessionName.isEmpty ? "this session" : snapshot.sessionName
        if snapshot.isRunning {
            return "\(session): \(snapshot.phase) on \(lane). \(snapshot.currentBytesLabel) written; originals stay untouched."
        }
        if snapshot.hasAttention {
            return "\(session): \(snapshot.failedCount) item(s) need review. \(snapshot.lastFailure.isEmpty ? snapshot.phase : snapshot.lastFailure)"
        }
        return "\(session): \(snapshot.phase). Processed \(snapshot.processedCount), skipped \(snapshot.skippedCount)."
    }

    private func quipslyStudioRootURL() -> URL {
        URL(fileURLWithPath: #filePath)
            .deletingLastPathComponent()
            .deletingLastPathComponent()
            .deletingLastPathComponent()
    }

    private func proxyJobCurrentURL() -> URL {
        quipslyStudioRootURL()
            .appendingPathComponent("reports", isDirectory: true)
            .appendingPathComponent("proxy-job-current.json")
    }

    private func refreshProxyJobSnapshotIfNeeded(force: Bool = false) {
        let now = Date()
        guard force || now.timeIntervalSince(lastProxyJobRefresh) >= 2.0 else { return }
        lastProxyJobRefresh = now

        let url = proxyJobCurrentURL()
        guard let data = try? Data(contentsOf: url),
              let raw = try? JSONSerialization.jsonObject(with: data) as? [String: Any] else {
            if proxyJobSnapshot.hasJobFile {
                proxyJobSnapshot = .idle
                updateAgentState()
            }
            return
        }

        let next = proxyJobSnapshot(from: raw, path: url.path)
        if next != proxyJobSnapshot {
            proxyJobSnapshot = next
            updateAgentState()
        }
    }

    private func proxyJobSnapshot(from payload: [String: Any], path: String) -> ProxyJobSnapshot {
        let current = payload["current"] as? [String: Any] ?? [:]
        let lastFailure = payload["lastFailure"] as? [String: Any] ?? [:]
        return ProxyJobSnapshot(
            status: payload["status"] as? String ?? "unknown",
            phase: payload["phase"] as? String ?? "",
            sessionName: payload["sessionName"] as? String ?? "",
            sequenceTitle: payload["sequenceTitle"] as? String ?? "",
            currentLane: current["lane"] as? String ?? "",
            currentKind: current["kind"] as? String ?? "",
            currentSource: current["source"] as? String ?? "",
            currentProxy: current["proxy"] as? String ?? "",
            currentProxyBytes: intValue(current["proxyBytes"]),
            currentPartialBytes: intValue(current["partialBytes"]),
            processedCount: intValue(payload["processedCount"]),
            skippedCount: intValue(payload["skippedCount"]),
            failedCount: intValue(payload["failedCount"]),
            elapsedSeconds: doubleValue(current["elapsedSeconds"]),
            startedAt: payload["startedAt"] as? String ?? "",
            updatedAt: payload["updatedAt"] as? String ?? "",
            lastFailure: lastFailure["error"] as? String ?? "",
            sourcePolicy: payload["sourcePolicy"] as? String ?? "",
            statePath: path
        )
    }

    private func intValue(_ value: Any?) -> Int {
        if let int = value as? Int { return int }
        if let number = value as? NSNumber { return number.intValue }
        if let string = value as? String { return Int(string) ?? 0 }
        return 0
    }

    private func doubleValue(_ value: Any?) -> Double {
        if let double = value as? Double { return double }
        if let number = value as? NSNumber { return number.doubleValue }
        if let string = value as? String { return Double(string) ?? 0 }
        return 0
    }

    private func proxyJobPayload() -> [String: Any] {
        let snapshot = proxyJobSnapshot
        return [
            "status": snapshot.status,
            "phase": snapshot.phase,
            "sessionName": snapshot.sessionName,
            "sequenceTitle": snapshot.sequenceTitle,
            "currentLane": snapshot.currentLane,
            "currentKind": snapshot.currentKind,
            "currentSource": snapshot.currentSource,
            "currentProxy": snapshot.currentProxy,
            "currentProxyBytes": snapshot.currentProxyBytes,
            "currentPartialBytes": snapshot.currentPartialBytes,
            "processedCount": snapshot.processedCount,
            "skippedCount": snapshot.skippedCount,
            "failedCount": snapshot.failedCount,
            "elapsedSeconds": snapshot.elapsedSeconds,
            "startedAt": snapshot.startedAt,
            "updatedAt": snapshot.updatedAt,
            "lastFailure": snapshot.lastFailure,
            "statePath": snapshot.statePath,
            "sourcePolicy": snapshot.sourcePolicy.isEmpty ? "Whole source lanes stay whole. Proxy jobs create full-length editor media, not chopped clips." : snapshot.sourcePolicy
        ]
    }

