    private func mediaRecoveryBadge(for lane: VideoLane, readiness: SourceReadiness) -> some View {
        let label = mediaRecoveryCategory(for: lane, readiness: readiness)
        let color = mediaRecoveryColor(for: lane, readiness: readiness)
        return Text(label.uppercased())
            .font(.caption2)
            .fontWeight(.bold)
            .foregroundStyle(color)
            .padding(.horizontal, 6)
            .padding(.vertical, 2)
            .background(color.opacity(0.12))
            .clipShape(Capsule())
    }

    private func mediaRecoveryCategory(for lane: VideoLane, readiness: SourceReadiness) -> String {
        let sourcePath = lane.sourceVideo?.mediaURL.path ?? lane.metadata?.sourcePath ?? ""
        if sourcePath.contains("__quipsly_missing_media__") || readiness.label == "Missing source" {
            return "relink"
        }
        if readiness.label.lowercased().contains("proxy blocked") {
            return "blocked"
        }
        if readiness.label == "Original protected" || readiness.needsStorageAccess {
            return "protected"
        }
        if readiness.label.lowercased().contains("proxy") || lane.sourceVideo?.proxyURL == nil {
            return "proxy"
        }
        return "held"
    }

    private func mediaRecoveryColor(for lane: VideoLane, readiness: SourceReadiness) -> Color {
        switch mediaRecoveryCategory(for: lane, readiness: readiness) {
        case "relink":
            return .red
        case "blocked":
            return .orange
        case "protected":
            return .orange
        case "proxy":
            return .yellow
        default:
            return readiness.color
        }
    }

    private func mediaRecoveryNextStep(for lane: VideoLane, readiness: SourceReadiness) -> String {
        let sourcePath = lane.sourceVideo?.mediaURL.path ?? lane.metadata?.sourcePath ?? ""
        if sourcePath.contains("__quipsly_missing_media__") || readiness.label == "Missing source" {
            return "Next: relink this lane to the whole original source file, or attach a full-length proxy that represents that source."
        }
        if readiness.label.lowercased().contains("proxy blocked") {
            return "Next: grant the exact folder or move/download the original, then retry pending proxies. Do not preview from the raw original."
        }
        if readiness.label == "Original protected" || readiness.needsStorageAccess {
            return "Next: attach an existing full-length proxy, or explicitly grant the source folder only when you are ready to generate/rebuild proxies from originals."
        }
        if sourcePath.hasPrefix(FileManager.default.homeDirectoryForCurrentUser.path + "/Desktop/")
            || sourcePath.hasPrefix(FileManager.default.homeDirectoryForCurrentUser.path + "/Downloads/")
            || sourcePath.hasPrefix(FileManager.default.homeDirectoryForCurrentUser.path + "/Documents/") {
            return "Next: create/attach a MediaVault proxy. If the file behaves like 0B on disk, recover it in Finder or move a readable copy to stable storage first."
        }
        if lane.sourceVideo?.proxyURL == nil || readiness.label.lowercased().contains("proxy") {
            return "Next: generate the deterministic proxy or attach an existing proxy; Quipsly will keep the original lane untouched."
        }
        return "Next: select the lane, inspect its source path, then relink or attach a proxy."
    }

