                .textFieldStyle(.roundedBorder)
                .frame(width: 220)

            Button("Save now") {
                saveNativeSession(named: normalizedActiveSessionName())
            }
            .buttonStyle(.borderedProminent)

            Button("Load") {
                loadNativeSession(named: normalizedActiveSessionName())
            }
            .buttonStyle(.bordered)

            Menu("Recent") {
                if recentSessions.isEmpty {
                    Text("No saved sessions yet")
                } else {
                    ForEach(recentSessions.indices, id: \.self) { index in
                        let session = recentSessions[index]
                        let name = session["name"] ?? "session"
                        Button(name) {
                            activeSessionName = name
                            loadNativeSession(named: name)
                        }
                    }
                }
            }

            Button {
                refreshRecentSessions()
            } label: {
                Image(systemName: "arrow.clockwise")
            }
            .buttonStyle(.bordered)
        }
        .padding(10)
        .background(.thinMaterial)
        .clipShape(RoundedRectangle(cornerRadius: 14, style: .continuous))
    }

