        var nextAction: String
        var humanAction: String
        var agentAction: String
        var proof: [String]
    }

    private struct ReleaseNextAction {
        var stage: String
        var laneId: String
        var laneLabel: String
        var title: String
        var detail: String
        var status: String
        var humanAction: String
        var agentAction: String
        var icon: String
        var proof: [String]
    }

    private func deliveryLaneReadiness(summary providedSummary: MediaReadinessSummary? = nil) -> [DeliveryLaneReadiness] {
        let summary = providedSummary ?? mediaReadinessSummary()
        let noSessionBlocker = "Load an episode session before delivery readiness can be evaluated."
        let renderBlocker = summary.hasSequence ? summary.detail : noSessionBlocker
        let renderReady = summary.isProductionReady
        let audioReadyForPlanning = summary.hasSequence && summary.audioReadyCount > 0 && summary.audioBlockedCount == 0
        let shortRecipeCount = projectStore.activeSequence?.shortClipQueue.count ?? 0

        func renderLane(
            id: String,
            label: String,
            destinations: [String],
            format: String,
            artifactType: String
        ) -> DeliveryLaneReadiness {
            DeliveryLaneReadiness(
                id: id,
                label: label,
                destinations: destinations,
                artifactType: artifactType,
                format: format,
                status: renderReady ? "ready" : "blocked",
                isReady: renderReady,
                summary: renderReady
                    ? "Proxy-backed render is ready. This proves file creation, not account publishing."
                    : "Render is blocked until the loaded session is proxy-safe.",
                blocker: renderReady ? "" : renderBlocker,
                nextAction: renderReady
                    ? "Run Export Proxy Package, inspect the output, then hand it to the publishing lane."
                    : "Resolve proxy/media readiness before rendering.",
                humanAction: "Export dual-format proxy package",
                agentAction: "GET /export_proxy_package?directory=<absolute-output-folder>&basename=<name>&proof_seconds=<seconds>",
                proof: ["GET /state", "GET /editor_snapshot", "GET /delivery_readiness"]
            )
        }

        return [
            renderLane(
                id: "episode-16x9-master",
                label: "16:9 episode master",
                destinations: ["YouTube", "Patreon"],
                format: "16:9",
                artifactType: "MP4 episode master"
            ),
            renderLane(
                id: "episode-9x16-master",
                label: "9:16 vertical episode render",
                destinations: ["Review", "Cuts source"],
                format: "9:16",
                artifactType: "MP4 vertical master"
            ),
            DeliveryLaneReadiness(
                id: "social-short-clips",
                label: "9:16 short recipes",
                destinations: ["YouTube Shorts", "Instagram", "Facebook", "LinkedIn"],
                artifactType: "Short recipe exports + platform packets",
                format: "9:16",
                status: renderReady && shortRecipeCount > 0 ? "ready" : renderReady ? "planned" : "blocked",
                isReady: renderReady && shortRecipeCount > 0,
                summary: renderReady && shortRecipeCount > 0
                    ? "\(shortRecipeCount) short recipes are queued over the episode spine and can export as 9:16 proof files. Captions, platform copy, and upload receipts stay separate."
                    : renderReady
                    ? "The vertical render foundation is ready, but social recipes still need explicit SHOW ranges, captions, and per-platform presets."
                    : "Social recipes depend on the episode render foundation first.",
                blocker: renderReady && shortRecipeCount > 0
                    ? ""
                    : renderReady ? "Needs short recipes and per-platform export presets." : renderBlocker,
                nextAction: renderReady && shortRecipeCount > 0
                    ? "Batch export queued recipes, review the files, then add captions/templates before platform publishing."
                    : "Add short recipes: mark SHOW ranges, choose caption/template, render each derivative, then publish/schedule.",
                humanAction: "Mark short recipe ranges from the edited episode",
                agentAction: "GET /shorts_export_all?directory=<absolute-output-folder>&basename=<name>",
                proof: ["GET /shorts_queue", "GET /shorts_export_all", "GET /state"]
            ),
            DeliveryLaneReadiness(
                id: "podcast-audio-master",
                label: "Podcast audio master",
                destinations: ["Spotify", "Apple Podcasts"],
                artifactType: "Audio master + episode feed metadata",
                format: "audio",
                status: audioReadyForPlanning ? "ready" : "blocked",
                isReady: audioReadyForPlanning,
                summary: audioReadyForPlanning
                    ? "Audio proxies are available and Quipsly can export a proxy-backed M4A audio proof. Loudness normalization, metadata, and podcast host publishing are still next."
                    : "Podcast audio needs ready audio lanes before a master can be generated.",
                blocker: audioReadyForPlanning
                    ? ""
                    : (summary.hasSequence ? summary.detail : noSessionBlocker),
                nextAction: audioReadyForPlanning
                    ? "Export podcast audio proof, inspect it, then add loudness/metadata/feed publishing."
                    : "Recover or generate audio proxies before exporting podcast audio.",
                humanAction: "Prepare podcast audio master",
                agentAction: "GET /audio_master_export?directory=<absolute-output-folder>&basename=<name>&proof_seconds=<seconds>",
                proof: ["GET /audio_master_export", "GET /state", "GET /delivery_readiness"]
            ),
            DeliveryLaneReadiness(
                id: "channel-publishing",
                label: "Direct platform publishing",
                destinations: ["YouTube", "Patreon", "Instagram", "Facebook", "LinkedIn", "Spotify", "Apple Podcasts"],
                artifactType: "Authenticated upload/schedule workflow",
                format: "platform",
                status: "planned",
                isReady: false,
                summary: "Direct channel publishing is intentionally separate from render readiness.",
                blocker: "Needs OAuth/account connections, upload APIs, scheduling, entitlement checks, and publish receipts before this can be called ready.",
                nextAction: "Connect publishing-channel ledger/OAuth flows to exported artifacts and store publish receipts.",
                humanAction: "Connect and schedule channels",
                agentAction: "planned: publishing integration endpoints",
                proof: ["GET /delivery_readiness"]
            )
        ]
    }

    private func releaseNextAction(summary providedSummary: MediaReadinessSummary? = nil) -> ReleaseNextAction {
        let summary = providedSummary ?? mediaReadinessSummary()
        let lanes = deliveryLaneReadiness(summary: summary)

        guard summary.hasSequence else {
            return ReleaseNextAction(
                stage: "Load",
                laneId: "sequence",
                laneLabel: "Episode session",
                title: "Load or import an episode session",
                detail: "The editor needs a sequence before it can build episode masters, short recipes, podcast audio, or receipts.",
                status: "blocked",
                humanAction: "Load episode session",
                agentAction: "GET /state",
                icon: "tray.and.arrow.down.fill",
                proof: ["GET /state", "GET /editor_snapshot"]
            )
        }

        let orderedIds = ["episode-16x9-master", "social-short-clips", "podcast-audio-master", "channel-publishing"]
        for id in orderedIds {
            guard let lane = lanes.first(where: { $0.id == id }) else { continue }
            if !lane.isReady {
                let stage = releaseLaneStage(lane)
                let detail = lane.blocker.isEmpty ? lane.nextAction : "\(lane.blocker) \(lane.nextAction)"
                return ReleaseNextAction(
                    stage: stage,
                    laneId: lane.id,
                    laneLabel: lane.label,
                    title: "\(stage): \(releaseLaneShortTitle(lane))",
                    detail: detail,
                    status: lane.status,
                    humanAction: lane.humanAction,
                    agentAction: lane.agentAction,
                    icon: releaseNextActionIcon(stage: stage),
                    proof: lane.proof
                )
            }
        }

        return ReleaseNextAction(
            stage: "Prove",
            laneId: "release-complete",
            laneLabel: "Release proof",
            title: "Review receipts before calling this published",
            detail: "Local artifacts are ready. Confirm YouTube, Patreon, social, Spotify, and Apple Podcast receipts before calling the release complete.",
            status: "ready",
            humanAction: "Review publication receipts",
            agentAction: "GET /missing_publication_receipts",
            icon: "checkmark.seal.fill",
            proof: ["GET /missing_publication_receipts", "GET /publication_mission_control"]
        )
    }

    private func releaseNextActionIcon(stage: String) -> String {
        switch stage {
        case "Load":
            return "tray.and.arrow.down.fill"
        case "Build":
            return "hammer.fill"
        case "Pull":
            return "rectangle.portrait.on.rectangle.portrait.fill"
        case "Listen":
            return "waveform"
        case "Prove":
            return "checkmark.seal.fill"
        default:
            return "arrow.forward.circle.fill"
        }
    }

    private func releaseNextActionPayload(summary providedSummary: MediaReadinessSummary? = nil) -> [String: Any] {
        let action = releaseNextAction(summary: providedSummary)
        return [
            "stage": action.stage,
            "laneId": action.laneId,
            "laneLabel": action.laneLabel,
            "title": action.title,
            "detail": action.detail,
            "status": action.status,
            "humanAction": action.humanAction,
            "agentAction": action.agentAction,
            "proof": action.proof
        ]
    }

    private func releaseTruthLadderPayload() -> [[String: String]] {
        [
            [
                "stage": "edit",
                "label": "Edit",
                "meaning": "SHOW/SKIP source decisions create output truth.",
                "proof": "Trail Map decisions and shared playhead state"
            ],
            [
                "stage": "build",
                "label": "Build",
                "meaning": "Quipsly renders a local artifact or packet.",
                "proof": "local artifact path, packet path, duration, and format"
            ],
            [
                "stage": "upload",
                "label": "Upload",
                "meaning": "The artifact is handed to a destination platform or host.",
                "proof": "upload handoff, platform draft, provider response, or connector result"
            ],
            [
                "stage": "schedule",
                "label": "Schedule",
                "meaning": "Platform-side release timing is set where applicable.",
                "proof": "scheduled timestamp, platform state, or schedule receipt"
            ],
            [
                "stage": "prove",
                "label": "Prove",
                "meaning": "Receipt, URL, provider ID, or schedule proof is captured.",
