    }

    private func releaseCockpitSummaryPayload(sequence: MediaSequence?) -> [String: Any] {
        let records = sequence?.publishReceipts ?? []
        let rows = sequence?.publishDeliverableReadiness(artifactExists: { path in
            FileManager.default.fileExists(atPath: path)
        }) ?? []
        let captured = records.filter { publishRecordReceiptCaptured($0) }.count
        let remaining = max(0, records.count - captured)

        return [
            "model": "quipsly-release-cockpit-summary",
            "version": "2026-06-18.release-cockpit.v1",
            "proofRule": "Local artifacts, upload handoffs, and scheduled posts are not publication proof until a real URL, provider id, or receipt is captured.",
            "families": [
                releaseCockpitFamilyPayload(
                    id: "episode16x9",
                    label: "16:9 episode master",
                    destinations: ["YouTube", "Patreon"],
                    rows: rows.filter { $0.family == .episode16x9 },
                    fallback: "Run Full prep to create the episode master handoff."
                ),
                releaseCockpitFamilyPayload(
                    id: "short9x16",
                    label: "9:16 short recipes",
                    destinations: ["YouTube Shorts", "Instagram", "Facebook", "LinkedIn"],
                    rows: rows.filter { $0.family == .short9x16 },
                    fallback: "Review short recipes, export social derivatives, then create receipt rows."
                ),
                releaseCockpitFamilyPayload(
                    id: "podcastAudio",
                    label: "Podcast audio",
                    destinations: ["Spotify", "Apple Podcasts"],
                    rows: rows.filter { $0.family == .podcastAudio },
                    fallback: "Export podcast audio and generate the podcast ready packet."
                )
            ],
            "proof": [
                "recordCount": records.count,
                "capturedCount": captured,
                "remainingCount": remaining,
                "status": records.isEmpty ? "no-ledger" : (remaining == 0 ? "proved" : "needs-receipts"),
                "nextAction": records.isEmpty
                    ? "Run Full prep or refresh the publish ledger before claiming platform progress."
                    : (remaining == 0 ? "Keep receipt proof with the release folder." : "Copy missing receipts, publish or schedule manually/API, then paste real URLs or provider IDs.")
            ],
            "platformProofChecklist": platformProofChecklistPayload(records: records)
        ]
    }

    private func releaseCockpitFamilyPayload(
        id: String,
        label: String,
        destinations: [String],
        rows: [PublishDeliverableReadiness],
        fallback: String
    ) -> [String: Any] {
        let status = releaseCockpitFamilyStatus(rows)
        let receiptCount = rows.filter { !$0.publicURL.isEmpty || !$0.providerReceiptId.isEmpty || $0.status == .published }.count
        return [
            "id": id,
            "label": label,
            "destinations": destinations,
            "targetCount": rows.count,
            "receiptCount": receiptCount,
            "status": status,
            "nextAction": releaseCockpitFamilyNextAction(rows, fallback: fallback),
            "targets": rows.map { row in
                [
                    "destination": row.destination,
                    "deliveryLaneId": row.deliveryLaneId,
                    "artifactType": row.artifactType,
                    "format": row.format,
                    "status": row.status.rawValue,
                    "artifactPath": row.artifactPath,
                    "publicURL": row.publicURL,
                    "providerReceiptId": row.providerReceiptId,
                    "blocker": row.blocker,
                    "nextAction": row.nextAction
                ] as [String: Any]
            }
        ]
    }

