    private func deliveryPacketPayload(summary providedSummary: MediaReadinessSummary? = nil) -> [String: Any] {
        let summary = providedSummary ?? mediaReadinessSummary()
        let lanes = deliveryLaneReadiness(summary: summary)
        let artifacts = deliveryPacketArtifacts(lanes: lanes)
        let destinations = deliveryPacketDestinations(artifacts: artifacts, lanes: lanes)
        let formatter = ISO8601DateFormatter()

        return [
            "model": "quipsly-episode-delivery-packet",
            "version": "2026-06-16.delivery-packet.v1",
            "status": deliveryPacketStatus,
            "sessionName": normalizedActiveSessionName(),
            "projectTitle": projectStore.project.title,
            "sequenceTitle": projectStore.activeSequence?.title ?? "",
            "sequenceDuration": projectStore.activeSequence?.duration ?? 0,
            "sourcePolicy": "proxy-first; originals stay untouched unless explicitly granted",
            "editingModel": "whole synced source lanes plus metadata output recipes",
            "publishingTruth": "This packet can make exports inspectable and platform-targeted, but direct upload/scheduling is not ready until channel integrations and receipts exist.",
            "readyForDirectPublishing": false,
            "renderFoundationReady": summary.isProductionReady,
            "visualRoughCutReady": summary.isVideoRoughCutReady,
            "generatedAt": deliveryPacketGeneratedAt.map { formatter.string(from: $0) } ?? "",
            "outputPath": deliveryPacketOutputPath,
            "error": deliveryPacketErrorMessage,
            "lastExportState": exportStatePayload(),
            "readiness": deliveryReadinessPayload(summary: summary),
            "artifacts": artifacts,
            "destinations": destinations,
            "nextHumanActions": deliveryPacketNextActions(lanes: lanes),
            "nextAgentActions": deliveryPacketAgentActions(lanes: lanes)
        ]
    }

    private func deliveryPacketArtifacts(lanes: [DeliveryLaneReadiness]) -> [[String: Any]] {
        lanes
            .filter { $0.id != "channel-publishing" }
            .map { lane in
                let outputPath = deliveryOutputPath(for: lane)
                let hasOutput = outputPath.map { FileManager.default.fileExists(atPath: $0) } ?? false
                let outputBytes = outputPath.flatMap { path -> Int64? in
                    guard let attrs = try? FileManager.default.attributesOfItem(atPath: path),
                          let size = attrs[.size] as? NSNumber else {
                        return nil
                    }
                    return size.int64Value
                }
                let status: String
                if hasOutput {
                    status = "exported"
                } else if lane.isReady {
                    status = "export-needed"
                } else {
                    status = lane.status
                }

                return [
                    "id": "\(lane.id)-artifact",
                    "laneId": lane.id,
                    "label": lane.label,
                    "artifactType": lane.artifactType,
                    "format": lane.format,
                    "status": status,
                    "outputPath": outputPath ?? "",
                    "fileExists": hasOutput,
                    "bytes": outputBytes ?? 0,
                    "destinations": lane.destinations,
                    "sourceExportKind": exportKind,
                    "sourceExportStatus": exportStatus,
                    "sourcePolicy": "proxy-first; output artifact only",
                    "nextAction": hasOutput ? "Review artifact, then attach platform metadata before publishing." : lane.nextAction
                ] as [String: Any]
            }
    }

    private func deliveryPacketDestinations(artifacts: [[String: Any]], lanes: [DeliveryLaneReadiness]) -> [[String: Any]] {
        var rows: [[String: Any]] = []
        for lane in lanes where lane.id != "channel-publishing" {
            let artifact = artifacts.first { ($0["laneId"] as? String) == lane.id }
            let artifactStatus = artifact?["status"] as? String ?? lane.status
            let outputPath = artifact?["outputPath"] as? String ?? ""
            let publishStatus: String
            if artifactStatus == "exported" {
                publishStatus = "artifact-ready-integration-needed"
            } else if lane.isReady {
                publishStatus = "needs-export"
            } else {
                publishStatus = "blocked"
            }

            for destination in lane.destinations {
                rows.append([
                    "platform": destination,
                    "laneId": lane.id,
                    "artifactType": lane.artifactType,
                    "format": lane.format,
                    "artifactStatus": artifactStatus,
                    "publishStatus": publishStatus,
                    "outputPath": outputPath,
                    "receiptStatus": "not-started",
                    "nextAction": artifactStatus == "exported"
                        ? "Add channel metadata/OAuth upload integration and save publish receipt."
                        : lane.nextAction
                ])
            }
        }

        rows.append([
            "platform": "Direct channel publishing",
            "laneId": "channel-publishing",
            "artifactType": "Authenticated upload/schedule workflow",
            "format": "platform",
            "artifactStatus": "planned",
            "publishStatus": "integration-needed",
            "outputPath": "",
            "receiptStatus": "not-started",
            "nextAction": "Build platform OAuth, upload/schedule APIs, entitlement checks, and publish receipts."
        ])
        return rows
    }

    private func deliveryOutputPath(for lane: DeliveryLaneReadiness) -> String? {
        let lowerKind = exportKind.lowercased()
        let existingPaths = exportOutputPaths.filter { FileManager.default.fileExists(atPath: $0) }
        switch lane.id {
        case "podcast-audio-master":
            return existingPaths.first { path in
                let lower = path.lowercased()
                return lower.hasSuffix(".m4a") || lower.hasSuffix(".mp3") || lowerKind.contains("audio")
            }
        case "episode-16x9-master":
            return existingPaths.first { path in
                let lower = path.lowercased()
                return lower.hasSuffix(".mp4") && (lower.contains("16x9") || lower.contains("16-9") || lower.contains("wide"))
            }
        case "episode-9x16-master":
            return existingPaths.first { path in
                let lower = path.lowercased()
                return lower.hasSuffix(".mp4") && !lowerKind.contains("short") && (lower.contains("9x16") || lower.contains("9-16") || lower.contains("vertical"))
            }
        case "social-short-clips":
            return existingPaths.first { path in
                let lower = path.lowercased()
                return lower.hasSuffix(".mp4") && (lowerKind.contains("short") || lower.contains("short"))
            }
        default:
            return nil
        }
    }

    private func deliveryPacketNextActions(lanes: [DeliveryLaneReadiness]) -> [[String: Any]] {
        lanes.map { lane in
            [
                "laneId": lane.id,
                "label": lane.label,
                "status": lane.status,
                "humanAction": lane.humanAction,
                "nextAction": lane.nextAction
            ]
        }
    }

    private func deliveryPacketAgentActions(lanes: [DeliveryLaneReadiness]) -> [[String: Any]] {
        lanes.map { lane in
            [
                "laneId": lane.id,
                "label": lane.label,
                "status": lane.status,
                "agentAction": lane.agentAction,
                "proof": lane.proof
            ]
        }
    }

    private func publishReleaseChecklistPayload(for sequence: MediaSequence?) -> [String: Any] {
        let records = sequence?.publishReceipts ?? []
        var payload = publishReleaseChecklistSummary(records: records)
        payload["model"] = "quipsly-publish-release-checklist"
        payload["version"] = "2026-06-16.publish-release-checklist.v1"
        payload["sessionName"] = normalizedActiveSessionName()
        payload["sequenceTitle"] = sequence?.title ?? ""
        payload["sourcePolicy"] = "checklist reports artifact/copy/receipt truth; it never mutates source media or platform state"
        payload["directPublishingReady"] = false
        payload["nextActions"] = publishReleaseChecklistNextActions(records: records, limit: 8)
        payload["records"] = records.map { publishReleaseChecklistRecordPayload($0) }
        return payload
    }

    private func publishReleaseChecklistSummary(records: [PublishReceiptRecord]) -> [String: Any] {
        let recordCount = records.count
        let artifactReadyCount = records.filter { publishRecordArtifactReady($0) }.count
        let copyReadyCount = records.filter { publishRecordCopyReady($0) }.count
        let receiptCapturedCount = records.filter { publishRecordReceiptCaptured($0) }.count
        let uploadJobReadyCount = records.filter { publishRecordUploadJobReady($0) }.count
        let apiNeededCount = records.filter { $0.uploadJobStatus == "integration-needed" }.count
        let blockedCount = records.filter { publishRecordBlocked($0) }.count
        let readyForManualUploadCount = records.filter {
            publishRecordArtifactReady($0) && publishRecordCopyReady($0) && !publishRecordReceiptCaptured($0)
        }.count

        let readinessLevel: String
        if recordCount == 0 {
            readinessLevel = "no-ledger"
        } else if blockedCount > 0 {
            readinessLevel = "needs-artifacts"
        } else if receiptCapturedCount == recordCount && records.allSatisfy({ $0.publishStatus == "published" }) {
            readinessLevel = "released"
        } else if receiptCapturedCount > 0 {
            readinessLevel = "partially-released"
        } else if artifactReadyCount == recordCount && copyReadyCount == recordCount {
            readinessLevel = "ready-for-manual-upload"
        } else if artifactReadyCount > 0 {
            readinessLevel = "needs-copy-review"
        } else {
            readinessLevel = "drafting"
        }

        return [
            "recordCount": recordCount,
            "artifactReadyCount": artifactReadyCount,
            "copyReadyCount": copyReadyCount,
            "receiptCapturedCount": receiptCapturedCount,
            "uploadJobReadyCount": uploadJobReadyCount,
            "apiNeededCount": apiNeededCount,
            "blockedCount": blockedCount,
            "readyForManualUploadCount": readyForManualUploadCount,
            "readinessLevel": readinessLevel
        ]
    }

    private func publishReleaseChecklistNextActions(records: [PublishReceiptRecord], limit: Int) -> [[String: Any]] {
        if records.isEmpty {
            return [[
                "label": "Generate publish ledger",
                "platform": "",
                "deliveryLaneId": "",
                "action": "Run release prep, then generate the publish ledger so Quipsly has platform-specific records.",
                "agentCommand": "script/agentctl.sh publish-ledger-generate"
            ]]
        }

        let ordered = records.sorted { lhs, rhs in
            let lhsPriority = publishRecordActionPriority(lhs)
            let rhsPriority = publishRecordActionPriority(rhs)
            if lhsPriority == rhsPriority {
                if lhs.deliveryLaneId == rhs.deliveryLaneId {
                    return lhs.platform < rhs.platform
                }
                return lhs.deliveryLaneId < rhs.deliveryLaneId
            }
            return lhsPriority < rhsPriority
        }
        return ordered.prefix(max(1, limit)).map { publishRecordNextAction($0) }
    }

    private func publishReceiptCaptureSummary(records: [PublishReceiptRecord]) -> [String: Any] {
        let captured = records.filter { publishRecordReceiptCaptured($0) }
        let missing = records.filter { !publishRecordReceiptCaptured($0) }
        let readyMissing = publishReceiptCaptureReadyMissingRecords(records: records)
        return [
            "model": "quipsly-publish-receipt-capture-summary",
            "version": "2026-06-17.publish-receipt-capture.v1",
            "recordCount": records.count,
            "capturedCount": captured.count,
            "missingCount": missing.count,
            "readyForReceiptCaptureCount": readyMissing.count,
            "capturedRecords": captured.map { publishReceiptCaptureRecordPayload($0) },
            "readyForReceiptCaptureRecords": readyMissing.map { publishReceiptCaptureRecordPayload($0) },
            "missingReceiptRecords": missing.map { publishReceiptCaptureRecordPayload($0) },
            "operatorRule": "After every manual upload or schedule, capture the public or scheduled URL on the exact publish receipt before moving to the next artifact."
        ]
    }

    private func publicationReceiptCockpitPayload(for sequence: MediaSequence?) -> [String: Any] {
        let records = sequence?.publishReceipts ?? []
        let summary = publishReceiptCaptureSummary(records: records)
        let completion = publicationReceiptCompletionSummary(for: sequence)
        let readyMissing = publishReceiptCaptureReadyMissingRecords(records: records)
        let missing = records.filter { !publishRecordReceiptCaptured($0) }
        let nextRecord = readyMissing.first ?? missing.first

        let status: String
        if records.isEmpty {
            status = "needs-publish-ledger"
        } else if missing.isEmpty {
            status = "receipt-proof-complete"
        } else if !readyMissing.isEmpty {
            status = "ready-for-receipt-capture"
        } else {
            status = "needs-artifact-or-copy-readiness"
        }

        let nextAction: String
        if records.isEmpty {
            nextAction = "Run Full prep so Tower has platform-specific receipt rows."
        } else if missing.isEmpty {
            nextAction = "All receipts are captured. Keep the receipt log with the release folder."
        } else if let nextRecord {
            nextAction = "Post or schedule \(publishReceiptDisplayLabel(nextRecord)), then capture the public/scheduled URL with the provided command."
        } else {
            nextAction = "Review missing rows and generate any missing artifact/copy packets before posting."
        }

        let families = publicationReceiptFamilySummaries(records: records)
        let platforms = publicationReceiptPlatformSummaries(records: records)

        return [
            "model": "quipsly-publication-receipt-cockpit",
            "version": "2026-06-19.publication-receipt-cockpit.v1",
            "status": status,
            "sessionName": normalizedActiveSessionName(),
            "sequenceTitle": sequence?.title ?? "",
            "publicationPhase": completion["publicationPhase"] ?? "",
            "publicationComplete": completion["publicationComplete"] ?? false,
            "summary": summary,
            "familySummary": families,
            "platformSummary": platforms,
            "creativePartnerPolicy": publicationReceiptCreativePartnerPolicyPayload(),
            "nextReceipt": nextRecord.map { publicationReceiptCockpitRecordPayload($0) } ?? [:],
            "nextReceiptActionCard": nextRecord.map { publicationReceiptNextActionCardPayload($0) } ?? [:],
            "readyForReceiptCapture": readyMissing.prefix(12).map { publicationReceiptCockpitRecordPayload($0) },
            "blockedOrNotReady": missing
                .filter { record in !readyMissing.contains(record) }
                .prefix(12)
                .map { publicationReceiptCockpitRecordPayload($0) },
            "commands": [
                "inspect": "script/agentctl.sh publication-receipt-cockpit",
