        [
            "model": "quipsly-tower-next-receipt-action-card",
            "version": "2026-06-20.tower-next-receipt-action-card.v1",
            "receiptId": record.id.uuidString,
            "displayLabel": publishReceiptDisplayLabel(record),
            "platform": record.platform,
            "deliveryLaneId": record.deliveryLaneId,
            "artifactPath": record.artifactPath,
            "artifactReady": publishRecordArtifactReady(record),
            "copyReady": publishRecordCopyReady(record),
            "publishStatus": record.publishStatus,
            "publicURL": record.publicURL,
            "providerReceiptId": record.providerReceiptId,
            "captureCommand": publicationReceiptCaptureCommand(for: record),
            "genericCommand": "script/agentctl.sh publish-receipt-update \(record.id.uuidString) published <public-or-scheduled-url> <provider-id> \"manual receipt\"",
            "operatorSteps": [
                "Watch or listen-check the artifact.",
                "Post or schedule it on the destination platform.",
                "Copy the public URL, scheduled URL, provider ID, screenshot path, or equivalent proof.",
                "Run the capture command for this exact receipt ID.",
                "Re-open publication receipt cockpit and handle the next receipt."
            ],
            "creativePartnerPolicy": publicationReceiptCreativePartnerPolicyPayload(),
            "markdown": publicationReceiptNextActionCardMarkdown(record),
            "proofRule": "Prepared artifacts are not publication proof. This row is not complete until external destination evidence is captured on the exact receipt.",
            "authorshipRule": "Agent-authored or mixed-authorship copy is allowed when upstream provenance and review state are visible. This receipt card proves destination state, not human-only authorship.",
            "truth": "This is the live Tower next receipt action card. It does not upload, schedule, publish, or mutate anything until a receipt capture command is run."
        ] as [String: Any]
    }

    private func publicationReceiptNextActionCardMarkdown(_ record: PublishReceiptRecord) -> String {
        """
        # Next Tower receipt

        - Receipt ID: `\(record.id.uuidString)`
        - Target: `\(publishReceiptDisplayLabel(record))`
        - Platform: `\(record.platform)`
        - Lane: `\(record.deliveryLaneId)`
        - Artifact: `\(record.artifactPath)`
        - Artifact ready: `\(publishRecordArtifactReady(record))`
        - Copy ready: `\(publishRecordCopyReady(record))`
        - Publish status: `\(record.publishStatus)`

        ## What to do

        1. Watch or listen-check the artifact.
        2. Post or schedule it on the destination platform.
        3. Copy the public URL, scheduled URL, provider ID, screenshot path, or equivalent proof.
        4. Run the receipt capture command for this exact row.
        5. Re-open the Tower receipt cockpit and handle the next receipt.

        ## Capture command

        ```bash
        \(publicationReceiptCaptureCommand(for: record))
        ```

        ## Generic command

        ```bash
        script/agentctl.sh publish-receipt-update \(record.id.uuidString) published <public-or-scheduled-url> <provider-id> "manual receipt"
        ```

        ## Boundary

        Prepared artifacts are not publication proof. This row is not complete until external destination evidence is captured on the exact receipt.

        Agent-authored or mixed-authorship copy is allowed when upstream provenance and review state are visible. This receipt card proves destination state, not human-only authorship.
        """
    }

    private func publicationReceiptFamilySummaries(records: [PublishReceiptRecord]) -> [[String: Any]] {
        let familyOrder = [
            "episode-16x9-master",
            "podcast-audio-master",
            "social-short-clips"
        ]
        return familyOrder.map { family in
            let familyRecords = records.filter { record in
                family == "social-short-clips"
                    ? record.deliveryLaneId.hasPrefix("social-short-clips")
                    : record.deliveryLaneId == family
            }
            return publicationReceiptGroupSummaryPayload(id: family, label: publicationReceiptFamilyLabel(family), records: familyRecords)
        }
    }

    private func publicationReceiptPlatformSummaries(records: [PublishReceiptRecord]) -> [[String: Any]] {
        let platforms = Array(Set(records.map(\.platform))).sorted()
        return platforms.map { platform in
            let platformRecords = records.filter { $0.platform == platform }
            return publicationReceiptGroupSummaryPayload(id: platform, label: platform, records: platformRecords)
        }
    }

    private func publicationReceiptGroupSummaryPayload(id: String, label: String, records: [PublishReceiptRecord]) -> [String: Any] {
        let captured = records.filter { publishRecordReceiptCaptured($0) }.count
        let ready = records.filter {
            publishRecordArtifactReady($0)
                && publishRecordCopyReady($0)
                && !publishRecordReceiptCaptured($0)
        }.count
        let blocked = records.count - captured - ready
        return [
            "id": id,
            "label": label,
            "totalCount": records.count,
            "capturedCount": captured,
            "readyForReceiptCaptureCount": ready,
            "blockedOrNotReadyCount": max(0, blocked),
            "complete": !records.isEmpty && captured == records.count
        ] as [String: Any]
    }

    private func publicationReceiptFamilyLabel(_ id: String) -> String {
        switch id {
        case "episode-16x9-master":
            return "16:9 episode master"
        case "podcast-audio-master":
            return "Podcast audio"
        case "social-short-clips":
            return "9:16 social shorts"
        default:
            return id
        }
    }

