    private func publishReceiptCaptureReadyMissingRecords(records: [PublishReceiptRecord]) -> [PublishReceiptRecord] {
        records
            .filter {
                publishRecordArtifactReady($0)
                    && publishRecordCopyReady($0)
                    && !publishRecordReceiptCaptured($0)
            }
            .sorted { lhs, rhs in
                let leftPriority = publishRecordActionPriority(lhs)
                let rightPriority = publishRecordActionPriority(rhs)
                if leftPriority == rightPriority {
                    return publishReceiptDisplayLabel(lhs) < publishReceiptDisplayLabel(rhs)
                }
                return leftPriority < rightPriority
            }
    }

