    private func nestWritingHandoffSummaryPayload() -> [String: Any] {
        let packetState = nestWritingPacketStatePayload()
        let packet = nestWritingPacketPayload()
        let readiness = packet["writingReadiness"] as? [String: Any] ?? [:]
        let selectedBlock = packet["selectedBlock"] as? [String: Any] ?? [:]
        let authoredCount = packet["authoredBlockCount"] as? Int
            ?? readiness["authoredBlockCount"] as? Int
            ?? 0
        let reviewCount = packet["reviewQueueCount"] as? Int
            ?? readiness["authoredNeedsReviewCount"] as? Int
            ?? 0
        let sourceCount = packet["sourceContextSummaryCount"] as? Int
            ?? readiness["sourceContextBlockCount"] as? Int
            ?? 0
        let sourceStatus = packet["sourceContextStatus"] as? String
            ?? (sourceCount > 0 ? "available" : "not-loaded-in-current-session")
        let packetStatus = packetState["status"] as? String ?? nestWritingPacketStatus
        let packetPath = packetState["outputPath"] as? String ?? nestWritingPacketOutputPath
        let selectedAuthorship = selectedBlock["authorship"] as? String ?? ""
        let selectedReviewStatus = selectedBlock["reviewStatus"] as? String ?? ""

        let status: String
        let nextAction: String
        if packetStatus == "generating" {
            status = "generating"
            nextAction = "Nest writing packet is being written. Keep Tower release prep visible, but do not hand it off until the packet path is present."
        } else if authoredCount == 0 {
            status = "needs-authored-work"
            nextAction = "Create or select real authored manuscript/content work before treating this release as content-complete."
        } else if sourceStatus != "available" {
            status = "needs-source-context"
            nextAction = "Authored work exists, but source context is not loaded in this session. Run the safe Nest context seed, then regenerate the writing packet."
        } else if packetStatus == "generated" && !packetPath.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty {
            status = "ready-with-writing-packet"
            nextAction = "Manuscript context is traveling with Tower release prep. Review authorship and source receipts before canon/publication approval."
        } else {
            status = "ready-needs-writing-packet"
            nextAction = "Authored work and source context are available. Generate the Nest writing packet so another agent or collaborator can pick up the release without chat memory."
        }

        return [
            "model": "quipsly-nest-writing-handoff-summary",
            "version": "2026-06-20.nest-writing-handoff-summary.v1",
            "status": status,
            "packetStatus": packetStatus,
            "packetOutputPath": packetPath,
            "packetError": packetState["error"] ?? "",
            "authoredBlockCount": authoredCount,
            "reviewQueueCount": reviewCount,
            "sourceContextSummaryCount": sourceCount,
            "sourceContextStatus": sourceStatus,
            "selectedBlockId": selectedBlock["id"] ?? "",
            "selectedRole": selectedBlock["role"] ?? "",
            "selectedAuthorship": selectedAuthorship,
            "selectedReviewStatus": selectedReviewStatus,
            "agentCanCreateContent": true,
            "creativePartnerTruth": "Codex and Quipslys are allowed to create serious publishable first-pass work. Tower should carry that work as inspectable authored context, not hide it or downgrade it to placeholder by default.",
            "canonBoundary": "This handoff can prepare publishing context, but it does not canonize manuscript text or publish anything by itself.",
            "commands": [
                "inspect": "script/agentctl.sh nest-writing-packet",
                "generate": "script/agentctl.sh nest-writing-packet-generate /absolute/output/folder optional-basename",
                "nextAction": "script/agentctl.sh nest-writing-next-action 1",
                "seedSourceContext": sourceStatus == "available" ? "" : "script/agentctl.sh nest-seed-context"
            ] as [String: Any],
            "nextAction": nextAction
        ]
    }

    private func episodeReceiptTargetsPayload(records: [PublishReceiptRecord]) -> [[String: Any]] {
        let publishPacketReady = !effectivePublishPacketPath().isEmpty
        let uploadBundleReady = !effectivePublishUploadBundlePath().isEmpty
        let cockpitReady = !effectivePublicationCockpitPath().isEmpty
        return ["YouTube", "Patreon"].map { platform in
            let record = records.first { receipt in
                receipt.platform == platform && receipt.deliveryLaneId == "episode-16x9-master"
            }
            let receiptCaptured = record.map { publishRecordReceiptCaptured($0) } ?? false
            let artifactReady = record.map { publishRecordArtifactReady($0) } ?? false
            let status: String
            let humanStatus: String
            let nextAction: String
            if receiptCaptured {
                status = "receipt-captured"
                humanStatus = "Proof captured"
                nextAction = "Keep the captured URL/provider id with the release folder."
            } else if !artifactReady {
                status = "needs-episode-master"
                humanStatus = "Needs rendered master"
                nextAction = "Run Full prep to render the 16:9 episode master."
            } else if !publishPacketReady || !uploadBundleReady || !cockpitReady {
                status = "needs-operator-packets"
                humanStatus = "Needs publish handoff"
                nextAction = "Generate or rediscover the publish packet, upload bundle, and cockpit before platform upload."
            } else if record == nil {
                status = "missing-publish-ledger-record"
                humanStatus = "Needs receipt row"
                nextAction = "Run Full prep or regenerate the publish ledger so this platform can be tracked."
            } else {
                status = "ready-for-upload-and-receipt"
                humanStatus = "Ready for \(platform)"
                nextAction = "Upload or schedule the 16:9 episode master on \(platform), then capture the real platform URL/provider id."
            }
            let command = record == nil
                ? "Generate the publish ledger before episode receipt capture."
                : "script/agentctl.sh episode-receipt-capture \"\(platform)\" published <public-url> <provider-id> \"manual episode receipt\""
            return [
                "platform": platform,
                "deliveryLaneId": "episode-16x9-master",
                "receiptId": record?.id.uuidString ?? "",
                "status": status,
                "humanStatus": humanStatus,
                "publishStatus": record?.publishStatus ?? "",
                "publicURL": record?.publicURL ?? "",
                "providerReceiptId": record?.providerReceiptId ?? "",
                "receiptCaptured": receiptCaptured,
                "artifactPath": record?.artifactPath ?? "",
                "artifactReady": artifactReady,
                "publishPacketReady": publishPacketReady,
                "uploadBundleReady": uploadBundleReady,
                "cockpitReady": cockpitReady,
                "nextAction": nextAction,
                "receiptURLRequired": true,
                "proofPolicy": "Do not mark \(platform) published until the public or scheduled episode URL/provider id is captured.",
                "agentCommand": command,
                "receiptCaptureCommand": command
            ] as [String: Any]
        }
    }

    private func episodeMasterArtifactPath() -> String {
        let recordPath = (projectStore.activeSequence?.publishReceipts.first { receipt in
            receipt.deliveryLaneId == "episode-16x9-master"
        }?.artifactPath ?? "").trimmingCharacters(in: .whitespacesAndNewlines)
        if fileSize(atPath: recordPath) > 0 {
            return recordPath
        }
        let completedExportArtifacts = exportArtifactStatePayloads()
        return completedExportArtifacts.first { artifact in
            (artifact["kind"] as? String) == "episode-master"
                && (artifact["status"] as? String) == "ready"
                && fileSize(atPath: artifact["path"] as? String ?? "") > 0
        }?["path"] as? String ?? ""
    }

    private func episodeReleaseBaseURL() -> URL? {
        let masterPath = episodeMasterArtifactPath().trimmingCharacters(in: .whitespacesAndNewlines)
        guard !masterPath.isEmpty else { return nil }
        let masterURL = URL(fileURLWithPath: masterPath)
        let extensionless = masterURL.deletingPathExtension().lastPathComponent
        let baseName = extensionless.hasSuffix("-16x9")
            ? String(extensionless.dropLast("-16x9".count))
            : extensionless
        return masterURL.deletingLastPathComponent().appendingPathComponent(baseName)
    }

    private func effectivePublishPacketPath() -> String {
        let explicit = publishPacketOutputPath.trimmingCharacters(in: .whitespacesAndNewlines)
        if !explicit.isEmpty, FileManager.default.fileExists(atPath: explicit) {
            return explicit
        }
        guard let baseURL = episodeReleaseBaseURL() else { return explicit }
        let candidate = URL(fileURLWithPath: "\(baseURL.path)-publish-packet", isDirectory: true)
        let manifest = candidate.appendingPathComponent("\(baseURL.lastPathComponent)-publish-manifest.json")
        return FileManager.default.fileExists(atPath: manifest.path) ? candidate.path : explicit
    }

    private func effectivePublishUploadBundlePath() -> String {
        let explicit = publishUploadBundleOutputPath.trimmingCharacters(in: .whitespacesAndNewlines)
        if !explicit.isEmpty, FileManager.default.fileExists(atPath: explicit) {
            return explicit
        }
        guard let baseURL = episodeReleaseBaseURL() else { return explicit }
        let candidate = URL(fileURLWithPath: "\(baseURL.path)-upload-packet-bundle", isDirectory: true)
        let manifest = candidate.appendingPathComponent("\(baseURL.lastPathComponent)-upload-packet-bundle.json")
        return FileManager.default.fileExists(atPath: manifest.path) ? candidate.path : explicit
    }

    private func effectivePublicationCockpitPath() -> String {
        let explicit = publicationCockpitOutputPath.trimmingCharacters(in: .whitespacesAndNewlines)
        if !explicit.isEmpty, FileManager.default.fileExists(atPath: explicit) {
            return explicit
        }
        guard let baseURL = episodeReleaseBaseURL() else { return explicit }
