    private func publicationReceiptCompletionSummary(for sequence: MediaSequence?) -> [String: Any] {
        let records = sequence?.publishReceipts ?? []
        let captured = records.filter { publishRecordReceiptCaptured($0) }.count
        let remaining = max(0, records.count - captured)
        let complete = !records.isEmpty && remaining == 0
        return [
            "receiptTotalCount": records.count,
            "receiptCapturedCount": captured,
            "receiptRemainingCount": remaining,
            "publicationComplete": complete,
            "publicationPhase": complete ? "publication-complete" : "ready-for-human-review"
        ]
    }

    private func publicationReadyHandoffPayload(for sequence: MediaSequence?) -> [String: Any] {
        let records = sequence?.publishReceipts ?? []
        let episodeRecords = records.filter { $0.deliveryLaneId == "episode-16x9-master" }
        let ledgerEpisodeReady = episodeRecords.contains { publishRecordArtifactReady($0) && publishRecordCopyReady($0) }
        let episodeMasterPath = episodeMasterArtifactPath()
        let episodeMasterReady = fileSize(atPath: episodeMasterPath) > 0
        let episodeReady = ledgerEpisodeReady || episodeMasterReady
        let episodeReceiptCaptured = episodeRecords.contains { publishRecordReceiptCaptured($0) }
        let episodeTargets = episodeReceiptTargetsPayload(records: records)
        let socialRecords = records.filter { $0.outputFamily == .short9x16 }
        let ledgerSocialReady = socialRecords.contains { publishRecordArtifactReady($0) && publishRecordCopyReady($0) }
        let podcastRecords = records.filter { $0.outputFamily == .podcastAudio }
        let ledgerPodcastReady = podcastRecords.contains { publishRecordArtifactReady($0) && publishRecordCopyReady($0) }
        let effectivePublishPacket = effectivePublishPacketPath()
        let effectiveUploadBundle = effectivePublishUploadBundlePath()
        let effectiveCockpit = effectivePublicationCockpitPath()
        let effectiveReceiptLog = effectivePublicationReceiptLogPath()
        let socialReadyPath = effectiveSocialPublicationQueueManifestPath()
        let socialClipCount = effectiveSocialPublicationQueueClipCount()
        let socialLoaded = socialClipCount > 0 && !socialReadyPath.isEmpty
        let socialReady = ledgerSocialReady || socialLoaded
        let socialActiveFolderPath = socialReadyPath.isEmpty ? "" : URL(fileURLWithPath: socialReadyPath).deletingLastPathComponent().path
        let socialPostingRunPath = effectiveSocialPostingRunPacketPath()
        let socialPostingRunExists = !socialPostingRunPath.isEmpty && FileManager.default.fileExists(atPath: socialPostingRunPath)
        let socialStartHerePath = socialPostingRunExists ? "\(socialPostingRunPath)/START-HERE.md" : ""
        let socialZipPath = socialActiveFolderPath.isEmpty ? "" : "\(socialActiveFolderPath).zip"
        let podcastReadyPath = effectivePodcastReadyPacketManifestPath()
        let podcastReadyFolderPath = podcastReadyPath.isEmpty ? "" : URL(fileURLWithPath: podcastReadyPath).deletingLastPathComponent().path
        let podcastPacketReady = podcastReadyPacketIsOperatorReady(path: podcastReadyPath)
        let podcastReady = ledgerPodcastReady || podcastPacketReady
        let podcastTargets = podcastReceiptTargetsPayload(records: records)
        let podcastReceiptCaptured = podcastTargets.contains { ($0["receiptCaptured"] as? Bool) == true }
        let readyLaneCount = [episodeReady, socialReady, podcastReady].filter { $0 }.count
        let receiptSummary = publicationReceiptCompletionSummary(for: sequence)
        let nestWritingHandoff = nestWritingHandoffSummaryPayload()

        return [
            "model": "quipsly-publication-ready-handoff",
            "version": "2026-06-17.publication-ready-handoff.v1",
            "readyLaneCount": readyLaneCount,
            "laneCount": 3,
            "publishingTruth": "Local handoff artifacts can be ready before anything is uploaded. Platform publication is only true after receipt capture.",
            "nestWriting": nestWritingHandoff,
            "receiptProof": [
                "summary": receiptSummary,
                "missingReceipts": missingPublicationReceiptsPayload(for: sequence),
                "operatorArtifacts": [
                    "receiptLogPath": effectiveReceiptLog,
                    "publishPacketPath": effectivePublishPacket,
                    "uploadPacketBundlePath": effectiveUploadBundle,
                    "publicationCockpitPath": effectiveCockpit
                ],
                "missingReceiptsCommand": "script/agentctl.sh missing-publication-receipts",
                "nextAction": (receiptSummary["publicationComplete"] as? Bool) == true
                    ? "Publication proof is complete. Keep the receipt log with the release folder."
                    : "After each manual/API upload or schedule, capture the platform URL/provider id back into Quipsly."
            ],
            "episode16x9": [
                "status": episodeReady
                    ? (episodeReceiptCaptured
                       ? "receipt-captured"
                       : (ledgerEpisodeReady ? "ready-for-youtube-patreon" : "master-rendered-needs-publish-packet"))
                    : "needs-release-prep",
                "artifactPath": episodeMasterPath,
                "operatorArtifacts": [
                    "masterPath": episodeMasterPath,
                    "publishPacketPath": effectivePublishPacket,
                    "uploadPacketBundlePath": effectiveUploadBundle,
                    "publicationCockpitPath": effectiveCockpit,
                    "receiptLogPath": effectiveReceiptLog
                ],
                "targets": episodeTargets,
                "targetCount": episodeTargets.count,
                "receiptCapturedCount": episodeTargets.filter { ($0["receiptCaptured"] as? Bool) == true }.count,
                "receiptRemainingCount": episodeTargets.filter { ($0["receiptCaptured"] as? Bool) != true }.count,
                "receiptCommands": episodeReceiptCommandsText(records: records),
                "receiptCaptured": episodeReceiptCaptured,
                "nextAction": episodeReady
                    ? (ledgerEpisodeReady
                       ? "Upload or schedule to YouTube/Patreon, then capture receipt."
                       : "Generate the publish packet/upload handoff for this rendered master, or manually upload then capture receipt.")
                    : "Run Full prep."
            ],
            "social9x16": [
                "status": socialReady
                    ? (ledgerSocialReady ? "ready-for-social-posting" : "ready-for-social-review")
                    : "needs-social-ready-packet",
                "clipCount": socialClipCount,
                "ledgerRecordCount": socialRecords.count,
                "ledgerArtifactReady": ledgerSocialReady,
                "manifestPath": socialReadyPath,
                "operatorArtifacts": [
                    "loadedManifestPath": socialReadyPath,
                    "activeQueueManifestPath": socialReadyPath,
                    "activeQueueFolderPath": socialActiveFolderPath,
                    "activeQueueZipPath": socialZipPath,
                    "selectedPostingRunPacketPath": socialPostingRunPath,
                    "selectedPostingRunPacketExists": socialPostingRunExists,
                    "selectedPostingRunStartHerePath": socialStartHerePath,
                    "legacyEpisode1FinalManifestPath": episode1FinalSocialPostingPacketManifestPath,
                    "legacyEpisode1FinalFolderPath": episode1FinalSocialPostingPacketFolderPath
                ],
                "receiptCaptureAvailable": !socialMasterQueueCandidatePreview.isEmpty,
                "selectedPostingSession": selectedSocialMasterQueuePostingSessionPayload(),
                "nextAction": socialReady
                    ? (ledgerSocialReady
                       ? "Post or schedule social short artifacts from the ledger, then capture receipts."
                       : (socialPostingRunPath.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty
                          ? "Review top clips, select a candidate, and generate its posting run packet."
                          : "Work the selected posting run packet, post/schedule manually, then capture receipts."))
                    : "Generate or load the social ready packet."
            ],
            "podcastAudio": [
                "status": podcastReady ? (podcastReceiptCaptured ? "receipt-captured" : "ready-for-spotify-apple-handoff") : "needs-podcast-ready-packet",
                "manifestPath": podcastReadyPath,
                "ledgerRecordCount": podcastRecords.count,
                "ledgerArtifactReady": ledgerPodcastReady,
                "operatorArtifacts": [
                    "readyManifestPath": podcastReadyPath,
                    "readyFolderPath": podcastReadyFolderPath,
                    "sourcePodcastManifestPath": podcastPacketOutputPath
                ],
                "targets": podcastTargets,
                "targetCount": podcastTargets.count,
                "receiptCapturedCount": podcastTargets.filter { ($0["receiptCaptured"] as? Bool) == true }.count,
                "receiptRemainingCount": podcastTargets.filter { ($0["receiptCaptured"] as? Bool) != true }.count,
                "receiptCommands": podcastReceiptCommandsText(records: records),
                "receiptCaptured": podcastReceiptCaptured,
                "nextAction": podcastReady ? "Listen-check, upload via podcast host/RSS, then capture Spotify/Apple URLs." : "Generate Podcast Packet, then Podcast Ready."
            ]
        ]
    }

    private func publicationMissionControlPayload(for sequence: MediaSequence?) -> [String: Any] {
        let records = sequence?.publishReceipts ?? []
        let handoff = publicationReadyHandoffPayload(for: sequence)
        let nestWritingHandoff = handoff["nestWriting"] as? [String: Any] ?? nestWritingHandoffSummaryPayload()
        let missingReceipts = missingPublicationReceiptsPayload(for: sequence)
        let receiptSummary = publicationReceiptCompletionSummary(for: sequence)
        let readyLaneCount = handoff["readyLaneCount"] as? Int ?? 0
        let laneCount = handoff["laneCount"] as? Int ?? 3
        let missingCount = missingReceipts["missingCount"] as? Int ?? records.count
        let publicationComplete = receiptSummary["publicationComplete"] as? Bool ?? false
        let socialLoaded = effectiveSocialPublicationQueueClipCount() > 0 && !effectiveSocialPublicationQueueManifestPath().isEmpty
        let podcastReady = podcastReadyPacketIsOperatorReady()
        let status: String
        if sequence == nil {
            status = "no-sequence-loaded"
        } else if records.isEmpty {
            status = "needs-full-release-prep"
        } else if publicationComplete {
            status = "publication-proof-complete"
        } else if readyLaneCount == laneCount {
            status = "ready-for-platform-posting"
        } else {
            status = "needs-handoff-artifacts"
        }

        return [
            "model": "quipsly-publication-mission-control",
            "version": "2026-06-17.publication-mission-control.v1",
            "status": status,
            "sessionName": normalizedActiveSessionName(),
            "sequenceTitle": sequence?.title ?? "",
            "summary": [
                "readyLaneCount": readyLaneCount,
                "laneCount": laneCount,
                "publishLedgerRecordCount": records.count,
                "missingReceiptCount": missingCount,
                "publicationComplete": publicationComplete,
                "socialQueueLoaded": socialLoaded,
                "podcastReadyPacketGenerated": podcastReady,
                "nestWritingStatus": nestWritingHandoff["status"] ?? "unknown",
                "nestWritingAuthoredBlockCount": nestWritingHandoff["authoredBlockCount"] ?? 0,
                "nestWritingReviewQueueCount": nestWritingHandoff["reviewQueueCount"] ?? 0,
                "nestWritingSourceContextStatus": nestWritingHandoff["sourceContextStatus"] ?? "unknown"
            ] as [String: Any],
            "objectiveCoverage": [
                "nestWritingContext": [
                    "requiredDestinations": ["Tower release handoff", "agent handoff", "human review"],
                    "coveredBy": "publicationReadyHandoff.nestWriting + nestWritingPacket",
                    "ready": (nestWritingHandoff["status"] as? String) == "ready-with-writing-packet",
                    "proofRequired": false,
                    "truth": "Agent-authored content may be real work. Release prep should carry authorship, source context, and review state rather than hiding or demoting it."
                ] as [String: Any],
                "episode16x9": [
                    "requiredDestinations": ["YouTube", "Patreon"],
                    "coveredBy": "publicationReadyHandoff.episode16x9",
                    "ready": (handoff["episode16x9"] as? [String: Any]).map { (($0["status"] as? String) ?? "").contains("ready") || (($0["status"] as? String) ?? "") == "receipt-captured" } ?? false,
                    "proofRequired": true
