                        ? "Publication proof is complete. Keep the receipt log with the release folder."
                        : (readyLaneCount == laneCount
                            ? "Post or schedule the ready artifacts, then capture every platform URL/provider receipt."
                            : "Generate the missing handoff artifacts before platform posting."))),
            "sourcePolicy": "Mission control is read-only. It aggregates rendered derivative artifacts, packet paths, selected social posting state, and receipt proof without touching source media or edit decisions."
        ]
    }

    private func episodeSpinePayload(
        for sequence: MediaSequence?,
        readinessSummary providedSummary: MediaReadinessSummary? = nil
    ) -> [String: Any] {
        let nest = nestPayload()
        let summary = providedSummary ?? mediaReadinessSummary()
        let delivery = deliveryReadinessPayload(summary: summary)
        let mission = publicationMissionControlPayload(for: sequence)
        let handoff = publicationReadyHandoffPayload(for: sequence)
        let checklist = publishReleaseChecklistPayload(for: sequence)
        let missionSummary = mission["summary"] as? [String: Any] ?? [:]
        let nestSeeded = nest["seededContextAvailable"] as? Bool ?? false
        let writingAvailable = nest["writingDocumentAvailable"] as? Bool ?? false
        let readyLaneCount = missionSummary["readyLaneCount"] as? Int ?? 0
        let laneCount = missionSummary["laneCount"] as? Int ?? 3
        let missionStatus = mission["status"] as? String ?? "unknown"

        let nestStatus: String
        if nestSeeded && writingAvailable {
            nestStatus = "seeded-and-writing"
        } else if nestSeeded {
            nestStatus = "seeded-needs-writing"
        } else {
            nestStatus = "needs-seed-context"
        }

        let studioStatus: String
        if sequence == nil {
            studioStatus = "needs-sequence"
        } else if summary.isProductionReady {
            studioStatus = "render-ready"
        } else if summary.isVideoRoughCutReady {
            studioStatus = "visual-ready-needs-production"
        } else {
            studioStatus = "needs-media-or-proxy"
        }

        let status: String
        let nextAction: String
        if sequence == nil {
            status = "needs-sequence"
            nextAction = "Load Episode 1 before proving the full Nest to Studio to Tower loop."
        } else if !nestSeeded {
            status = "needs-nest-context"
            nextAction = "Seed or write Nest context, then re-open this Episode Spine."
        } else if !summary.isProductionReady {
            status = "needs-studio-readiness"
            nextAction = "Fix media/proxy readiness before treating Tower handoff as real."
        } else if missionStatus == "needs-handoff-artifacts" {
            status = "needs-tower-handoff"
            nextAction = "Run Full prep or targeted packet generation so Tower has actual handoff artifacts."
        } else if readyLaneCount < laneCount {
            status = "needs-lane-packets"
            nextAction = "Generate missing episode/social/podcast packets before platform posting."
        } else {
            status = missionStatus
            nextAction = mission["nextAction"] as? String
                ?? "Review Tower handoff and capture platform receipts after posting."
        }

        return [
            "model": "quipsly-episode-spine-loop",
            "version": "2026-06-19.episode-spine-loop.v1",
            "aliases": ["vertical-slice", "nest-studio-tower", "one-loop"],
            "status": status,
            "sessionName": normalizedActiveSessionName(),
            "projectTitle": projectStore.project.title,
            "sequenceTitle": sequence?.title ?? "",
            "sourcePolicy": "Nest, Studio, and Tower are lenses over the same episode truth. Seeded context is review-labeled, source lanes stay whole, and publication is only true after receipts.",
            "creativePartnerPolicy": "Codex and Quipslys may create real publishable drafts and packets. The safeguard is visible authorship, provenance, review state, and receipts; not a ban on agent-authored work.",
            "nest": [
                "status": nestStatus,
                "documentCount": nest["documentCount"] ?? 0,
                "blockCount": nest["blockCount"] ?? 0,
                "seededContextAvailable": nestSeeded,
                "writingDocumentAvailable": writingAvailable,
                "selectedDocumentTitle": (nest["selectedDocument"] as? [String: Any])?["title"] ?? "",
                "fallbackSourcePolicy": nest["fallbackSourcePolicy"] ?? ""
            ] as [String: Any],
            "studio": [
                "status": studioStatus,
                "renderFoundationReady": summary.isProductionReady,
                "visualRoughCutReady": summary.isVideoRoughCutReady,
                "videoProxyReadyCount": summary.videoProxyReadyCount,
                "videoBlockedCount": summary.videoBlockedCount,
                "audioReadyCount": summary.audioReadyCount,
                "audioBlockedCount": summary.audioBlockedCount,
                "showDecisionCount": summary.showDecisionCount,
                "skipDecisionCount": summary.skipDecisionCount,
                "shortRecipeCount": sequence?.shortClipQueue.count ?? 0,
                "deliveryReadinessStatus": delivery["status"] ?? "",
                "deliveryCounts": delivery["counts"] ?? [:]
            ] as [String: Any],
            "tower": [
                "status": missionStatus,
                "readyLaneCount": readyLaneCount,
                "laneCount": laneCount,
                "publishLedgerRecordCount": missionSummary["publishLedgerRecordCount"] ?? 0,
                "missingReceiptCount": missionSummary["missingReceiptCount"] ?? 0,
                "publicationComplete": missionSummary["publicationComplete"] ?? false,
                "episode16x9": handoff["episode16x9"] ?? [:],
                "social9x16": handoff["social9x16"] ?? [:],
                "podcastAudio": handoff["podcastAudio"] ?? [:],
                "checklist": checklist
            ] as [String: Any],
            "commands": [
                "inspect": "script/agentctl.sh vertical-slice",
                "legacyInspect": "script/agentctl.sh episode-spine",
                "nest": "script/agentctl.sh left-workbench nest",
                "tower": "script/agentctl.sh left-workbench publish",
                "seedNest": "script/agentctl.sh nest-seed-context",
                "missionControl": "script/agentctl.sh publication-mission-control",
                "fullReleasePrep": "script/agentctl.sh full-release-prepare /absolute/output/folder basename 8"
            ] as [String: Any],
            "nextAction": nextAction
        ]
    }

