    private func podcastReceiptTargetsPayload(records: [PublishReceiptRecord]) -> [[String: Any]] {
        let readyPath = effectivePodcastReadyPacketManifestPath()
        let readyExists = podcastReadyPacketIsOperatorReady(path: readyPath)
        return ["Spotify", "Apple Podcasts"].map { platform in
            let record = records.first { receipt in
                receipt.platform == platform && receipt.deliveryLaneId == "podcast-audio-master"
            }
            let receiptCaptured = record.map { publishRecordReceiptCaptured($0) } ?? false
            let artifactReady = record.map { publishRecordArtifactReady($0) } ?? false
            let status: String
            let humanStatus: String
            let nextAction: String
            if receiptCaptured {
                status = "receipt-captured"
                humanStatus = "Proof captured"
                nextAction = "Keep the captured URL/provider id with the release folder."
            } else if !readyExists {
                status = "needs-podcast-ready-packet"
                humanStatus = "Needs ready packet"
                nextAction = "Generate Podcast Packet, then Podcast Ready before uploading."
            } else if record == nil {
                status = "missing-publish-ledger-record"
                humanStatus = "Needs receipt row"
                nextAction = "Run Full prep or regenerate the publish ledger so this platform can be tracked."
            } else {
                status = "ready-for-host-upload-and-receipt"
                humanStatus = "Ready for host/RSS upload"
                nextAction = "Upload/listen-check through the podcast host/RSS workflow, then capture the real platform URL."
            }
            let command = record == nil
                ? "Generate the publish ledger before podcast receipt capture."
                : "script/agentctl.sh podcast-receipt-capture \"\(platform)\" published <public-url> <provider-id> \"manual podcast receipt\""
            return [
                "platform": platform,
                "deliveryLaneId": "podcast-audio-master",
                "receiptId": record?.id.uuidString ?? "",
                "status": status,
                "humanStatus": humanStatus,
                "publishStatus": record?.publishStatus ?? "",
                "publicURL": record?.publicURL ?? "",
                "providerReceiptId": record?.providerReceiptId ?? "",
                "receiptCaptured": receiptCaptured,
                "readyPacketGenerated": readyExists,
                "readyPacketPath": readyPath,
                "artifactPath": record?.artifactPath ?? podcastAudioArtifactPath(),
                "artifactReady": artifactReady,
                "nextAction": nextAction,
                "receiptURLRequired": true,
                "proofPolicy": "Do not mark \(platform) published until the public or scheduled episode URL/provider id is captured.",
                "agentCommand": command,
                "receiptCaptureCommand": command
            ] as [String: Any]
        }
    }

    private func podcastReceiptCommandsText(records: [PublishReceiptRecord]) -> String {
        podcastReceiptTargetsPayload(records: records)
            .compactMap { target in
                let command = (target["receiptCaptureCommand"] as? String ?? "")
                    .trimmingCharacters(in: .whitespacesAndNewlines)
                return command.hasPrefix("script/") ? command : nil
            }
            .joined(separator: "\n")
    }

