        let diskTitles = diskSummary["topCandidateTitles"] as? [String]
        let diskManifestPath = diskSummary["manifestPath"] as? String ?? ""
        let readyShortArtifactCount = diskClipCount ?? exportedShorts.count
        let socialReceiptCount = diskReceiptCount ?? socialRecords.count
        let effectiveStatus = socialPublicationQueueStatus == "idle" && !effectiveOutputPath.isEmpty
