            "readyShortArtifactCount": readyShortArtifactCount,
            "socialReceiptCount": socialReceiptCount,
            "topCandidateTitles": diskTitles ?? socialPublicationTopTitles(from: socialRecords, limit: 6),
            "manualQueueReady": readyShortArtifactCount > 0,
