    private func currentSocialPublicationQueueOutputPath() -> String {
        let explicit = socialPublicationQueueOutputPath.trimmingCharacters(in: .whitespacesAndNewlines)
        if !explicit.isEmpty, FileManager.default.fileExists(atPath: explicit) {
            return explicit
        }
        return latestSocialPublicationQueueDirectoryPath() ?? explicit
    }

    private func currentSocialPublicationQueueManifestPath() -> String {
        let queuePath = currentSocialPublicationQueueOutputPath().trimmingCharacters(in: .whitespacesAndNewlines)
        guard !queuePath.isEmpty else { return "" }
        return socialPublicationQueueManifestURL(in: URL(fileURLWithPath: queuePath, isDirectory: true))?.path ?? ""
    }

    private func effectiveSocialPublicationQueueManifestPath() -> String {
        let loadedPath = socialMasterQueueOutputPath.trimmingCharacters(in: .whitespacesAndNewlines)
        if socialMasterQueueClipCount > 0,
           socialMasterQueueStatus == "loaded",
           !loadedPath.isEmpty,
           FileManager.default.fileExists(atPath: loadedPath) {
            return loadedPath
        }
        return currentSocialPublicationQueueManifestPath().trimmingCharacters(in: .whitespacesAndNewlines)
    }

    private func effectiveSocialPublicationQueueFolderPath() -> String {
        let manifestPath = effectiveSocialPublicationQueueManifestPath()
        guard !manifestPath.isEmpty else { return "" }
        return URL(fileURLWithPath: manifestPath).deletingLastPathComponent().path
    }

    private func effectiveSocialPublicationQueueClipCount() -> Int {
        if socialMasterQueueClipCount > 0, socialMasterQueueStatus == "loaded" {
            return socialMasterQueueClipCount
        }
        let folderPath = effectiveSocialPublicationQueueFolderPath()
        guard !folderPath.isEmpty else { return 0 }
        return socialPublicationQueueDiskSummary(outputPath: folderPath)["clipCount"] as? Int ?? 0
    }

    private func effectiveSocialPostingRunPacketPath() -> String {
        let statePath = socialMasterPostingRunPacketPath.trimmingCharacters(in: .whitespacesAndNewlines)
        if !statePath.isEmpty, FileManager.default.fileExists(atPath: statePath) {
            return statePath
        }
        return durableSocialPostingRunPacketPath()
    }

    private func durableSocialPostingRunPacketPath() -> String {
        #if os(macOS)
        let movies = FileManager.default.urls(for: .moviesDirectory, in: .userDomainMask).first
            ?? URL(fileURLWithPath: NSHomeDirectory()).appendingPathComponent("Movies", isDirectory: true)
        #else
        let movies = FileManager.default.temporaryDirectory
        #endif
        let root = movies
            .appendingPathComponent("QuipslyStudio", isDirectory: true)
            .appendingPathComponent("PublishPackets", isDirectory: true)
            .appendingPathComponent("SocialPostingRuns", isDirectory: true)
        let sessionName = normalizedActiveSessionName().lowercased()
        let parts = sessionName.split(separator: "-").map(String.init)
        let episodeToken = parts.count >= 2 ? "\(parts[0])-\(parts[1])" : sessionName
        guard let children = try? FileManager.default.contentsOfDirectory(
            at: root,
            includingPropertiesForKeys: [.isDirectoryKey, .contentModificationDateKey],
            options: [.skipsHiddenFiles]
        ) else {
            return ""
        }
        let candidates: [(url: URL, modifiedAt: Date)] = children.compactMap { child in
            let values = try? child.resourceValues(forKeys: [.isDirectoryKey, .contentModificationDateKey])
            guard values?.isDirectory == true else { return nil }
            let name = child.lastPathComponent.lowercased()
            guard name.contains(episodeToken), name.contains("posting-run") else { return nil }
            let manifest = child.appendingPathComponent("posting-run-manifest.json")
            guard FileManager.default.fileExists(atPath: manifest.path) else { return nil }
            return (child, values?.contentModificationDate ?? Date.distantPast)
        }
        return candidates
            .sorted { lhs, rhs in
                if lhs.modifiedAt == rhs.modifiedAt {
                    return lhs.url.path > rhs.url.path
                }
                return lhs.modifiedAt > rhs.modifiedAt
            }
            .first?
            .url
            .path ?? ""
    }

    private func latestSocialPublicationQueueDirectoryPath() -> String? {
        let sessionName = normalizedActiveSessionName()
        var candidates: [(url: URL, modifiedAt: Date)] = []

        for root in socialPublicationQueueSearchRoots() {
            guard let children = try? FileManager.default.contentsOfDirectory(
                at: root,
                includingPropertiesForKeys: [.isDirectoryKey, .contentModificationDateKey],
                options: [.skipsHiddenFiles]
            ) else {
                continue
            }

            for child in children {
                let values = try? child.resourceValues(forKeys: [.isDirectoryKey, .contentModificationDateKey])
                guard values?.isDirectory == true else { continue }
                let lowercasedName = child.lastPathComponent.lowercased()
                guard lowercasedName.contains("social") && lowercasedName.contains("queue") else { continue }
                guard let manifestURL = socialPublicationQueueManifestURL(in: child) else { continue }
                guard socialPublicationQueueManifestMatchesSession(manifestURL, sessionName: sessionName)
                    || lowercasedName.contains(sessionName.lowercased()) else {
                    continue
                }
                let modifiedAt = (try? manifestURL.resourceValues(forKeys: [.contentModificationDateKey]).contentModificationDate)
                    ?? values?.contentModificationDate
                    ?? Date.distantPast
                candidates.append((url: child, modifiedAt: modifiedAt))
            }
        }

        return candidates
            .sorted { lhs, rhs in
                if lhs.modifiedAt == rhs.modifiedAt {
                    return lhs.url.path > rhs.url.path
                }
                return lhs.modifiedAt > rhs.modifiedAt
            }
            .first?
            .url
            .path
    }

    private func socialPublicationQueueSearchRoots() -> [URL] {
        #if os(macOS)
        let movies = FileManager.default.urls(for: .moviesDirectory, in: .userDomainMask).first
            ?? URL(fileURLWithPath: NSHomeDirectory()).appendingPathComponent("Movies", isDirectory: true)
        #else
        let movies = FileManager.default.temporaryDirectory
        #endif
        return [
            movies
                .appendingPathComponent("QuipslyExports", isDirectory: true)
                .appendingPathComponent("SocialQueues", isDirectory: true),
            defaultPublishPacketDirectory()
                .appendingPathComponent("ReviewedSocialQueues", isDirectory: true),
            defaultPublishPacketDirectory()
                .appendingPathComponent("SocialPublicationQueues", isDirectory: true)
        ]
    }

    private func socialPublicationQueueManifestMatchesSession(_ manifestURL: URL, sessionName: String) -> Bool {
        guard let data = try? Data(contentsOf: manifestURL),
              let object = try? JSONSerialization.jsonObject(with: data) as? [String: Any] else {
            return false
        }
        if let manifestSessionName = object["sessionName"] as? String {
            return manifestSessionName == sessionName
        }
        if let episode = object["episode"] as? [String: Any],
           let manifestSessionName = episode["sessionName"] as? String {
            return manifestSessionName == sessionName
        }
        return false
    }

    private func socialPublicationQueueDiskSummary(outputPath: String) -> [String: Any] {
        let trimmed = outputPath.trimmingCharacters(in: .whitespacesAndNewlines)
        guard !trimmed.isEmpty else { return [:] }

        let directoryURL = URL(fileURLWithPath: trimmed, isDirectory: true)
        guard let manifestURL = socialPublicationQueueManifestURL(in: directoryURL),
              let data = try? Data(contentsOf: manifestURL),
              let object = try? JSONSerialization.jsonObject(with: data) as? [String: Any] else {
            return [:]
        }

        let clips = (object["clips"] as? [[String: Any]])
            ?? (object["items"] as? [[String: Any]])
            ?? (object["queueItems"] as? [[String: Any]])
            ?? []
        let titles = clips
            .compactMap { clip in
                (clip["title"] as? String)
                    ?? (clip["clipTitle"] as? String)
                    ?? (clip["displayTitle"] as? String)
            }
            .prefix(6)
            .map { $0 }
        let platformList = object["platforms"] as? [String] ?? []
        let receiptCount = clips.reduce(0) { partial, clip in
            if let platformCopy = clip["platformCopy"] as? [String: Any] {
                return partial + max(1, platformCopy.keys.count)
            }
            if let destinations = clip["destinations"] as? [String] {
                return partial + max(1, destinations.count)
            }
            return partial + max(1, platformList.count)
        }

        return [
            "manifestPath": manifestURL.path,
            "clipCount": clips.count,
            "receiptCount": receiptCount,
            "topCandidateTitles": Array(titles),
            "reviewGate": object["reviewGate"] as? String ?? "",
            "publishingTruth": object["publishingTruth"] as? String ?? ""
        ]
    }

    private func socialPublicationQueueManifestURL(in directoryURL: URL) -> URL? {
        guard let contents = try? FileManager.default.contentsOfDirectory(
            at: directoryURL,
            includingPropertiesForKeys: nil,
            options: [.skipsHiddenFiles]
        ) else {
            return nil
        }

        return contents
            .filter { $0.pathExtension.lowercased() == "json" }
            .sorted { lhs, rhs in
                let left = lhs.lastPathComponent
                let right = rhs.lastPathComponent
                if left.contains("reviewed-social-queue") != right.contains("reviewed-social-queue") {
                    return left.contains("reviewed-social-queue")
                }
                if left.contains("social-publication-queue") != right.contains("social-publication-queue") {
                    return left.contains("social-publication-queue")
                }
                return left < right
            }
            .first
    }

    private func shortReviewCountsPayload(for sequence: MediaSequence?) -> [String: Any] {
        let queue = sequence?.shortClipQueue ?? []
        let keep = queue.filter { $0.reviewStatus.lowercased() == "keep" }.count
        let refine = queue.filter { $0.reviewStatus.lowercased() == "refine" }.count
        let reject = queue.filter { $0.reviewStatus.lowercased() == "reject" }.count
        let draft = max(0, queue.count - keep - refine - reject)
        return [
            "model": "quipsly-short-review-counts",
            "version": "2026-06-18.short-review-counts.v1",
            "total": queue.count,
            "keep": keep,
            "refine": refine,
            "reject": reject,
            "draft": draft,
            "approvedForSocialQueue": keep,
            "reviewDecisionCommand": "script/agentctl.sh shorts-review-selected keep|refine|reject \"optional notes\"",
            "nextReviewCommand": "script/agentctl.sh shorts-review-next",
            "nextReviewEndpoint": "GET /shorts_review_next?status=<optional-status>",
            "nextReviewCandidate": shortReviewNextCandidatePayload(for: sequence),
            "reviewNavigator": shortReviewNavigatorPayload(for: sequence),
            "reviewedQueueCommand": "script/agentctl.sh reviewed-social-queue --session \(normalizedActiveSessionName()) --output /absolute/output/folder --basename reviewed-social --include-status keep",
            "nativeReviewedQueueCommand": "script/agentctl.sh reviewed-social-queue-generate /absolute/output/folder optional-basename",
            "reviewScopeGuidance": queue.isEmpty
                ? "No derivative shorts are queued yet."
                : "Short review can proceed from transcript context and current exports even when the full two-camera episode edit is not ready. Keep/refine/reject decisions stay metadata-only until export or queue generation.",
            "truth": "Only keep-status shorts should flow into reviewed social queues. Draft, refine, and reject remain useful editorial metadata but are not publish approvals."
        ]
    }

    private func sequencePlatformPackIndexStatePayload(for sequence: MediaSequence?) -> [String: Any] {
        guard let sequence else {
            return [
                "model": "quipsly-sequence-platform-pack-index-state",
                "version": "2026-06-21.sequence-platform-pack-index-state.v1",
                "status": "no_sequence",
                "shortCount": 0,
                "readyForPackagingCount": 0,
                "needsReviewCount": 0,
                "suggestedOutputPath": "",
                "seriesManifestSuggestedOutputPath": seriesPlatformPackManifestOutputURL().path,
                "saveCommand": "script/agentctl.sh shorts-platform-pack-index save",
                "copyCommand": "script/agentctl.sh shorts-platform-pack-index copy",
                "saveEndpoint": "GET /shorts_platform_pack_index?action=save",
                "copyEndpoint": "GET /shorts_platform_pack_index?action=copy",
                "nextAction": "Load a native edit session before creating a platform-pack index.",
                "truth": "This state summarizes the batch shorts handoff. It is not a publishing receipt."
            ]
        }

        let briefPairs = sequence.shortClipQueue.map { clip in
            (clip: clip, brief: shortCreatorQualityBrief(for: clip))
        }
        let readyCount = briefPairs.filter { $0.brief.isReadyForPackaging }.count
        let needsReviewCount = briefPairs.filter { $0.brief.recommendedReviewStatus != "ready-for-human-review" }.count
        let primaryPlatforms = Dictionary(grouping: briefPairs, by: { $0.brief.primaryPlatform })
            .mapValues { $0.count }
            .sorted { lhs, rhs in
                if lhs.value == rhs.value { return lhs.key < rhs.key }
                return lhs.value > rhs.value
            }
            .map { ["platform": $0.key, "count": $0.value] as [String: Any] }

        let status: String
        let nextAction: String
        if sequence.shortClipQueue.isEmpty {
            status = "empty_queue"
            nextAction = "Create or import short recipes before generating a platform-pack index."
        } else if needsReviewCount > 0 {
            status = "needs_review"
            nextAction = "Review weak packets, then save the sequence platform-pack index for Tower handoff."
        } else {
            status = "ready_to_package"
            nextAction = "Save the sequence platform-pack index, then review the generated JSON beside exported proofs."
        }

        return [
            "model": "quipsly-sequence-platform-pack-index-state",
            "version": "2026-06-21.sequence-platform-pack-index-state.v1",
            "status": status,
            "sequenceTitle": sequence.title,
            "shortCount": sequence.shortClipQueue.count,
            "readyForPackagingCount": readyCount,
            "needsReviewCount": needsReviewCount,
            "primaryPlatformDistribution": primaryPlatforms,
            "suggestedOutputPath": activeSequencePlatformPackIndexOutputURL().path,
            "seriesManifestSuggestedOutputPath": seriesPlatformPackManifestOutputURL().path,
            "saveCommand": "script/agentctl.sh shorts-platform-pack-index save",
            "copyCommand": "script/agentctl.sh shorts-platform-pack-index copy",
            "saveEndpoint": "GET /shorts_platform_pack_index?action=save",
            "copyEndpoint": "GET /shorts_platform_pack_index?action=copy",
            "nextAction": nextAction,
            "contract": "Metadata-only batch handoff for active-sequence shorts. Does not publish, approve, mutate source media, create exports, move timeline decisions, or claim receipts.",
            "seriesManifestTruth": "Saving an episode index also refreshes a local series manifest that can list Episode 1-3 indexes as they are produced.",
            "truth": "Use this as a Tower/publication checklist input after human review, not as proof that platforms were posted."
        ]
    }

    private func shortReviewNavigatorPayload(for sequence: MediaSequence?) -> [String: Any] {
        guard let sequence else {
            return [
                "model": "quipsly-short-review-navigator",
                "version": "2026-06-19.short-review-navigator.v1",
                "status": "no_sequence",
                "queueCount": 0,
                "nextAction": "Load a native edit session before reviewing shorts.",
                "nextCommand": "script/agentctl.sh load-session episode-1-premiere-rescue",
                "truth": "Navigator state is transparent routing, not a quality score."
            ]
        }

        let queue = sequence.shortClipQueue
        guard !queue.isEmpty else {
            return [
                "model": "quipsly-short-review-navigator",
                "version": "2026-06-19.short-review-navigator.v1",
                "status": "empty_queue",
                "queueCount": 0,
                "nextAction": "Create short recipes from promising timeline moments.",
                "nextCommand": "script/agentctl.sh shorts-append-selected-segment",
                "truth": "Navigator state is transparent routing, not a quality score."
            ]
        }

        struct ShortNavigatorCandidate {
            let priority: Int
            let clip: ShortClipCandidate
            let evidence: [String: Any]
            let readiness: [String: Any]
            let status: String
            let reason: String
            let nextAction: String
            let nextCommand: String
            let selected: Bool
        }

        func requiredIncompleteStepIds(from readiness: [String: Any]) -> [String] {
            readiness["requiredIncompleteStepIds"] as? [String] ?? []
        }

        func readinessPayload(from evidence: [String: Any]) -> [String: Any] {
            evidence["publicationReadiness"] as? [String: Any] ?? [:]
        }

        func evidenceBool(_ evidence: [String: Any], _ key: String) -> Bool {
            evidence[key] as? Bool ?? false
        }

        func evidenceString(_ evidence: [String: Any], _ key: String) -> String {
            evidence[key] as? String ?? ""
        }

        func readinessBool(_ readiness: [String: Any], _ key: String) -> Bool {
            readiness[key] as? Bool ?? false
        }

        func reviewStatus(for clip: ShortClipCandidate) -> String {
            normalizedShortReviewStatus(clip.reviewStatus)
        }

        func commandWithSelection(_ clip: ShortClipCandidate, _ command: String) -> String {
            let select = "script/agentctl.sh shorts-select id \(clip.id.uuidString)"
            guard !command.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty else {
                return select
            }
            if command.hasPrefix("script/agentctl.sh shorts-select") {
                return command
            }
            return "\(select) >/dev/null && \(command)"
        }

        func candidate(for clip: ShortClipCandidate) -> ShortNavigatorCandidate {
            let evidence = shortReviewEvidencePayload(for: clip, in: sequence)
            let readiness = readinessPayload(from: evidence)
            let missing = requiredIncompleteStepIds(from: readiness)
            let exportExists = evidenceBool(evidence, "exportExists")
            let review = reviewStatus(for: clip)
            let selected = selectedShortClipId == clip.id
            let selectCommand = "script/agentctl.sh shorts-select id \(clip.id.uuidString)"

            let priority: Int
            let status: String
            let reason: String
            let nextAction: String
            let nextCommand: String

            if !exportExists || missing.contains("export-derivative") {
                priority = 10
                status = "needs_export"
                reason = "No exported 9:16 derivative exists at the expected path, so review would be imaginary."
                nextAction = "Export this short, then review the actual derivative."
                nextCommand = evidenceString(evidence, "exportCommand")
            } else if review == "refine" {
                priority = 20
                status = "needs_refinement"
                reason = "This short is already marked refine, so the honest next step is to adjust recipe, crop, hook, text, or audio before re-export."
                nextAction = "Refine the short recipe and re-export."
                nextCommand = selectCommand
            } else if missing.contains("visual-review") {
                priority = 30
                status = "needs_visual_review"
                reason = "The derivative exists, but there is no visual/contact-sheet proof yet."
                nextAction = "Create a contact sheet or preview the derivative."
                let contactSheet = evidenceString(evidence, "contactSheetCommand")
                nextCommand = commandWithSelection(clip, contactSheet.isEmpty ? evidenceString(evidence, "previewCommand") : contactSheet)
            } else if missing.contains("listen-through") {
                priority = 40
                status = "needs_listen_through"
                reason = "Visual review is not enough; listen for awkward cuts, audio glitches, and timing."
                nextAction = "Listen through the short and record audio/timing proof."
                nextCommand = commandWithSelection(clip, "script/agentctl.sh shorts-listen-through \"audio and timing reviewed\"")
            } else if missing.contains("caption-copy") {
                priority = 50
                status = "needs_text_review"
                reason = "Hook, overlay, caption, or platform copy exists but needs explicit review before publishing."
                nextAction = "Approve or rewrite the short text as metadata/platform copy."
                nextCommand = commandWithSelection(clip, "script/agentctl.sh shorts-text-review approve \"text reviewed; keep burn-in metadata-only unless separately approved\"")
            } else if review == "ready-for-human-review" || review == "draft" || review.isEmpty {
                priority = 60
                status = "needs_review_decision"
                reason = "Evidence is far enough along to make a keep/refine/reject decision."
                nextAction = "Mark the short keep, refine, or reject with notes."
                nextCommand = "script/agentctl.sh shorts-review \(clip.id.uuidString) keep|refine|reject \"why\""
            } else if review == "keep" && readinessBool(readiness, "readyForSocialQueue") {
                priority = 80
                status = "ready_for_social_queue"
                reason = "This short has a keep decision and required publication-prep evidence."
                nextAction = "Include it in a reviewed social queue and track platform receipts."
                nextCommand = "script/agentctl.sh reviewed-social-queue --session \(normalizedActiveSessionName()) --output /absolute/output/folder --basename reviewed-social --include-status keep"
            } else if review == "reject" {
                priority = 95
                status = "rejected_learning_data"
                reason = "Rejected shorts are useful training/review data, not publishing candidates."
                nextAction = "Leave it preserved as learning data and move to the next candidate."
                nextCommand = "script/agentctl.sh shorts-review-next"
            } else {
                priority = 70
                status = "needs_human_attention"
                reason = "The short is in an uncommon state; inspect it before automating the next step."
                nextAction = "Select and inspect this short."
                nextCommand = selectCommand
            }

            return ShortNavigatorCandidate(
                priority: selected ? max(1, priority - 5) : priority,
                clip: clip,
                evidence: evidence,
                readiness: readiness,
                status: status,
                reason: selected ? "Selected short: \(reason)" : reason,
                nextAction: nextAction,
                nextCommand: nextCommand,
                selected: selected
            )
        }

        let candidates = queue.map(candidate(for:))
        let sortedCandidates = candidates.sorted {
            if $0.priority != $1.priority {
                return $0.priority < $1.priority
            }
            return $0.clip.updatedAt < $1.clip.updatedAt
        }
        let next = sortedCandidates.first
        let nextMechanical = sortedCandidates.first {
            $0.status == "needs_export" || $0.status == "needs_visual_review"
        }
        let nextAudition = sortedCandidates.first {
            $0.status == "needs_listen_through"
        }
        let nextAuditionCommand = nextAudition.map {
            commandWithSelection($0.clip, evidenceString($0.evidence, "previewCommand"))
        } ?? ""
        let reviewPacketSessionName = normalizedActiveSessionName()
        let reviewPacketDirectory = FileManager.default.homeDirectoryForCurrentUser
            .appendingPathComponent("Movies/QuipslyExports/ReviewShorts/\(reviewPacketSessionName)-listen-review")
            .path
        let reviewPacketBasename = "\(reviewPacketSessionName)-shorts-listen-review"
        let reviewPacketHtmlPath = "\(reviewPacketDirectory)/\(reviewPacketBasename).html"
        let reviewPacketManifestPath = "\(reviewPacketDirectory)/\(reviewPacketBasename).json"

        func count(_ predicate: (ShortNavigatorCandidate) -> Bool) -> Int {
            candidates.filter(predicate).count
        }

        func candidatePayload(_ item: ShortNavigatorCandidate?) -> [String: Any] {
            guard let item else {
                return [
                    "available": false,
                    "status": "none"
                ]
            }

            let missing = requiredIncompleteStepIds(from: item.readiness)
            return [
                "available": true,
                "id": item.clip.id.uuidString,
                "title": item.clip.title,
                "selected": item.selected,
                "reviewStatus": reviewStatus(for: item.clip),
                "exportStatus": item.clip.exportStatus,
                "status": item.status,
                "reason": item.reason,
                "nextAction": item.nextAction,
                "nextCommand": item.nextCommand,
                "sequenceStartTime": item.evidence["sequenceStartTime"] ?? 0,
                "sequenceEndTime": item.evidence["sequenceEndTime"] ?? 0,
                "recipeDuration": item.evidence["recipeDuration"] ?? 0,
                "exportExists": evidenceBool(item.evidence, "exportExists"),
                "previewCommand": commandWithSelection(item.clip, evidenceString(item.evidence, "previewCommand")),
                "contactSheetCommand": commandWithSelection(item.clip, evidenceString(item.evidence, "contactSheetCommand")),
                "requiredIncompleteStepIds": missing,
                "exportPath": item.evidence["exportPath"] ?? "",
                "transcriptContext": item.evidence["transcriptContext"] ?? [:],
                "textBurnPolicy": item.evidence["textBurnPolicy"] ?? [:],
                "publicationReadiness": item.readiness
            ]
        }

        func listenThroughGuidePayload(_ item: ShortNavigatorCandidate?) -> [String: Any] {
            guard let item else {
                return [
                    "available": false,
                    "status": "none",
                    "truth": "No exported short currently needs listen-through review."
                ]
            }

            let preview = commandWithSelection(item.clip, evidenceString(item.evidence, "previewCommand"))
            let markListened = commandWithSelection(
                item.clip,
                "script/agentctl.sh shorts-listen-through \"audio/timing listened through; note any awkward cut, sync issue, or keep/refine reason\""
            )
            let refine = "script/agentctl.sh shorts-review \(item.clip.id.uuidString) refine \"listen-through found an issue; describe trim/crop/audio fix\""
            let keep = "script/agentctl.sh shorts-review \(item.clip.id.uuidString) keep \"listen-through passed; still capture platform copy before queueing\""
            let reject = "script/agentctl.sh shorts-review \(item.clip.id.uuidString) reject \"listen-through rejected; preserve as learning data\""

            return [
                "available": true,
                "model": "quipsly-short-listen-through-guide",
                "version": "2026-06-19.short-listen-through-guide.v1",
                "title": item.clip.title,
                "shortId": item.clip.id.uuidString,
                "sequenceStartTime": item.evidence["sequenceStartTime"] ?? 0,
                "sequenceEndTime": item.evidence["sequenceEndTime"] ?? 0,
                "recipeDuration": item.evidence["recipeDuration"] ?? 0,
                "exportPath": item.evidence["exportPath"] ?? "",
                "transcriptContext": item.evidence["transcriptContext"] ?? [:],
                "playPreviewCommand": preview,
                "markListenedCommand": markListened,
                "refineCommand": refine,
                "keepCommand": keep,
                "rejectCommand": reject,
                "checklist": [
                    "Does the first second make sense, or does it need a lead-in?",
                    "Is there an awkward jump, clipped word, silence, or audio glitch?",
                    "Does the ending land cleanly instead of feeling chopped?",
                    "Does the crop/framing distract from the idea after watching with sound?",
                    "What single note would make the next pass faster?"
                ],
                "operatorGuidance": "Cue and listen first. Only run markListenedCommand after an actual listen-through. Use refine/keep/reject only as an explicit editorial decision.",
                "truth": "This guide makes review easier; it does not approve publication or mutate media by itself."
            ]
        }

        return [
            "model": "quipsly-short-review-navigator",
            "version": "2026-06-19.short-review-navigator.v1",
            "status": next?.status ?? "no_candidates",
            "queueCount": queue.count,
            "selectedShortId": selectedShortClipId?.uuidString ?? "",
            "nextCandidate": candidatePayload(next),
            "nextMechanicalCandidate": candidatePayload(nextMechanical),
            "nextAuditionCandidate": candidatePayload(nextAudition),
            "listenThroughGuide": listenThroughGuidePayload(nextAudition),
            "selectedCandidate": candidatePayload(candidates.first(where: { $0.selected })),
            "counts": [
                "needsExport": count { $0.status == "needs_export" },
                "needsRefinement": count { $0.status == "needs_refinement" },
                "needsVisualReview": count { $0.status == "needs_visual_review" },
                "needsListenThrough": count { $0.status == "needs_listen_through" },
                "needsTextReview": count { $0.status == "needs_text_review" },
                "needsReviewDecision": count { $0.status == "needs_review_decision" },
                "readyForSocialQueue": count { $0.status == "ready_for_social_queue" },
                "rejectedLearningData": count { $0.status == "rejected_learning_data" }
            ],
            "nextAction": next?.nextAction ?? "No review action available.",
            "nextReason": next?.reason ?? "No queued short candidates are available.",
            "nextCommand": next?.nextCommand ?? "",
            "nextMechanicalAction": nextMechanical?.nextAction ?? "",
            "nextMechanicalReason": nextMechanical?.reason ?? "",
            "nextMechanicalCommand": nextMechanical?.nextCommand ?? "",
            "nextAuditionAction": nextAudition == nil ? "" : "Cue this short for listen-through review without marking it complete.",
            "nextAuditionReason": nextAudition?.reason ?? "",
            "nextAuditionCommand": nextAuditionCommand,
            "listenReviewPacket": [
                "model": "quipsly-short-listen-review-packet-pointer",
                "version": "2026-06-19.short-listen-review-packet-pointer.v1",
                "status": FileManager.default.fileExists(atPath: reviewPacketHtmlPath) ? "generated" : "not_generated",
                "sessionName": reviewPacketSessionName,
                "outputDirectory": reviewPacketDirectory,
                "basename": reviewPacketBasename,
                "htmlPath": reviewPacketHtmlPath,
                "manifestPath": reviewPacketManifestPath,
                "generateCommand": "script/agentctl.sh shorts-listen-review-packet \(shellQuoted(reviewPacketDirectory)) \(shellQuoted(reviewPacketBasename))",
                "openCommand": "script/agentctl.sh shorts-listen-review-open",
                "truth": "This packet is a local review aid. It does not mutate source media, edit decisions, review state, or publication approval."
            ],
            "operatorGuidance": "Use this when the left shorts rail feels noisy. It chooses the next evidence-building step, not the best artistic short.",
            "truth": "Navigator state is transparent routing, not a quality score. It never approves publishing, mutates source media, or burns text into pixels by itself."
        ]
    }

