    private func selectedSocialMasterQueuePostingSessionPayload() -> [String: Any] {
        guard let candidate = selectedSocialMasterQueueCandidate() else {
            return [
                "model": "quipsly-selected-social-posting-session",
                "version": "2026-06-18.selected-social-posting-session.v1",
                "status": "no-candidate-selected",
                "readyForOperator": false,
                "summary": "Load and select a social candidate before starting a posting session."
            ]
        }

        let rows = socialMasterQueuePlatformCompletionRows()
        let nextPlatform = nextIncompleteSocialPostingPlatform() ?? ""
        let selectedPlatform = socialMasterReceiptCapturePlatform.trimmingCharacters(in: .whitespacesAndNewlines)
        let currentPlatform = rows.contains { row in
            (row["platform"] as? String ?? "") == selectedPlatform
                && (row["proofCaptured"] as? Bool) != true
        } ? selectedPlatform : nextPlatform
        let incompleteCount = rows.filter { ($0["proofCaptured"] as? Bool) != true }.count
        let receiptId = socialMasterQueueSelectedReceiptId(platform: currentPlatform.isEmpty ? selectedPlatform : currentPlatform)
        let clipPath = (candidate["clipPath"] ?? "").trimmingCharacters(in: .whitespacesAndNewlines)
        let platformCopyPath = (candidate["platformCopyPath"] ?? "").trimmingCharacters(in: .whitespacesAndNewlines)
        let captionPath = (candidate["captionSrtPath"] ?? "").trimmingCharacters(in: .whitespacesAndNewlines)
        let thumbnailPath = (candidate["thumbnailPath"] ?? "").trimmingCharacters(in: .whitespacesAndNewlines)
        let allComplete = !rows.isEmpty && incompleteCount == 0
        let queueRows = rows.map { row -> [String: Any] in
            let platform = row["platform"] as? String ?? ""
            let proofCaptured = row["proofCaptured"] as? Bool ?? false
            let receiptRowFound = row["receiptRowFound"] as? Bool ?? false
            let isCurrent = !currentPlatform.isEmpty && platform == currentPlatform
            return [
                "platform": platform,
                "isCurrent": isCurrent,
                "proofCaptured": proofCaptured,
                "receiptRowFound": receiptRowFound,
                "status": proofCaptured ? "proof-captured" : (receiptRowFound ? "needs-platform-proof" : "needs-receipt-row"),
                "nextSafeAction": proofCaptured
                    ? "No posting action needed unless you need to inspect the captured receipt."
                    : (receiptRowFound ? "Post or schedule manually, then capture a real public/scheduled URL or provider receipt." : "Create receipt rows before posting session capture."),
                "selectCommand": "script/agentctl.sh social-master-select-receipt-platform \(shellQuote(platform)) published"
            ]
        }

        return [
            "model": "quipsly-selected-social-posting-session",
            "version": "2026-06-18.selected-social-posting-session.v1",
            "status": allComplete ? "all-platform-proof-captured" : "ready-for-manual-platform-posting",
            "readyForOperator": !allComplete,
            "candidateRank": candidate["rank"] ?? "",
            "title": candidate["title"] ?? "",
            "selectedPlatform": currentPlatform,
            "nextIncompletePlatform": nextPlatform,
            "incompletePlatformCount": incompleteCount,
            "platformQueue": queueRows,
            "postingRunPacketPath": effectiveSocialPostingRunPacketPath(),
            "postingRunPacketExists": !effectiveSocialPostingRunPacketPath().isEmpty && FileManager.default.fileExists(atPath: effectiveSocialPostingRunPacketPath()),
            "receiptId": receiptId,
            "clipPath": clipPath,
            "clipExists": !clipPath.isEmpty && FileManager.default.fileExists(atPath: clipPath),
            "platformCopyPath": platformCopyPath,
            "platformCopyExists": !platformCopyPath.isEmpty && FileManager.default.fileExists(atPath: platformCopyPath),
            "captionSrtPath": captionPath,
            "captionSrtExists": !captionPath.isEmpty && FileManager.default.fileExists(atPath: captionPath),
            "thumbnailPath": thumbnailPath,
            "thumbnailExists": !thumbnailPath.isEmpty && FileManager.default.fileExists(atPath: thumbnailPath),
            "selectNextCommand": "script/agentctl.sh social-master-select-next-posting-platform",
            "receiptCommand": socialMasterQueueReceiptCommandForSelectedCandidate(includeFilledValues: false, platform: currentPlatform.isEmpty ? selectedPlatform : currentPlatform),
            "operatorSteps": [
                "Open and watch clipPath.",
                "Open platformCopyPath and captionSrtPath if needed.",
                "Post or schedule manually on selectedPlatform.",
                "Capture the real public/scheduled URL or provider receipt back into Quipsly.",
                "Repeat until incompletePlatformCount is 0."
            ],
            "proofRule": "This session guides manual platform work only. Nothing is complete until receipt tracking has a real platform URL or provider receipt."
        ] as [String: Any]
    }

