    private func selectedSocialMasterQueuePostingPacketPayload() -> [String: Any] {
        guard let candidate = selectedSocialMasterQueueCandidate() else {
            return [
                "model": "quipsly-selected-social-posting-packet",
                "version": "2026-06-17.selected-social-posting-packet.v1",
                "status": "no-candidate-selected",
                "readyToPost": false,
                "summary": "Load and select a social candidate before building a posting packet."
            ]
        }

        let clipPath = (candidate["clipPath"] ?? "").trimmingCharacters(in: .whitespacesAndNewlines)
        let thumbnailPath = (candidate["thumbnailPath"] ?? "").trimmingCharacters(in: .whitespacesAndNewlines)
        let captionPath = (candidate["captionSrtPath"] ?? "").trimmingCharacters(in: .whitespacesAndNewlines)
        let copyPath = (candidate["platformCopyPath"] ?? "").trimmingCharacters(in: .whitespacesAndNewlines)
        let artifactReadiness = selectedSocialMasterQueueArtifactReadinessPayload()
        let receiptChecklist = selectedSocialMasterQueueReceiptChecklistPayload()
        let readyToReview = artifactReadiness["readyToReview"] as? Bool ?? false
        let readyReceiptCount = receiptChecklist["readyPlatformCount"] as? Int ?? 0
        let platformCopy: [String: Any]

        if copyPath.isEmpty {
            platformCopy = [
                "path": "",
                "status": "missing",
                "text": ""
            ]
        } else {
            do {
                platformCopy = [
                    "path": copyPath,
                    "status": "loaded",
                    "text": try String(contentsOfFile: copyPath, encoding: .utf8)
                ]
            } catch {
                platformCopy = [
                    "path": copyPath,
                    "status": "unreadable",
                    "error": error.localizedDescription,
                    "text": ""
                ]
            }
        }

        return [
            "model": "quipsly-selected-social-posting-packet",
            "version": "2026-06-17.selected-social-posting-packet.v1",
            "status": readyToReview ? "ready-for-human-posting-review" : "needs-artifacts",
            "readyToPost": readyToReview,
            "selectedCandidateRank": candidate["rank"] ?? "",
            "title": candidate["title"] ?? "",
            "hook": candidate["hook"] ?? "",
            "durationSeconds": candidate["duration"] ?? "",
            "sourcePack": candidate["sourcePack"] ?? "",
            "candidate": candidate,
            "platforms": socialMasterQueueSelectedPlatforms(),
            "artifacts": [
                "clipPath": clipPath,
                "clipExists": !clipPath.isEmpty && FileManager.default.fileExists(atPath: clipPath),
                "thumbnailPath": thumbnailPath,
                "thumbnailExists": !thumbnailPath.isEmpty && FileManager.default.fileExists(atPath: thumbnailPath),
                "captionSrtPath": captionPath,
                "captionSrtExists": !captionPath.isEmpty && FileManager.default.fileExists(atPath: captionPath),
                "platformCopyPath": copyPath,
                "platformCopyExists": !copyPath.isEmpty && FileManager.default.fileExists(atPath: copyPath)
            ] as [String: Any],
            "platformCopy": platformCopy,
            "artifactReadiness": artifactReadiness,
            "receiptChecklist": receiptChecklist,
            "readyReceiptPlatformCount": readyReceiptCount,
            "commands": [
                "inspect": "script/agentctl.sh selected-social-posting-packet",
                "openClip": "script/agentctl.sh social-master-open-selected-clip",
                "copyPlatformCopy": "script/agentctl.sh social-master-copy-selected-platform-copy",
                "receiptChecklist": "script/agentctl.sh selected-social-receipts",
                "copyAllReceiptCommands": "script/agentctl.sh social-master-copy-receipt-commands",
                "captureReceipt": "script/agentctl.sh social-master-queue-receipt <rank> \"YouTube Shorts\" published <public-url> <provider-id> \"manual receipt\""
            ],
            "safeChecklist": [
                "Watch the derivative 9:16 clip once before posting.",
                "Read the loaded platform copy and adjust it for the target platform if needed.",
                "Attach captions/SRT when the platform supports it.",
                "Post or schedule manually/API-side.",
                "Capture the real public URL, scheduled URL, or provider receipt back into Quipsly."
            ],
            "proofRule": "A platform is not complete until a real public/scheduled URL or provider receipt is captured.",
            "sourcePolicy": "Posting packets reference derivative shorts, copy, captions, thumbnails, and receipts only. They do not mutate source media or edit decisions.",
            "nonGoals": [
                "This packet does not upload, schedule, or publish.",
                "This packet does not claim receipt proof without a platform URL/provider receipt.",
                "This packet does not touch source media."
            ]
        ]
