    private func selectedSocialMasterQueueReceiptChecklistPayload() -> [String: Any] {
        guard let candidate = selectedSocialMasterQueueCandidate() else {
            return [
                "status": "no-candidate-selected",
                "readyPlatformCount": 0,
                "blockedPlatformCount": 0,
                "items": [],
                "summary": "Load and select a social candidate before receipt capture."
            ]
        }

        let platforms = socialMasterQueueSelectedPlatforms()
        let items: [[String: Any]] = platforms.map { platform in
            let receiptId = socialMasterQueueSelectedReceiptId(platform: platform)
            let ready = !receiptId.isEmpty
            return [
                "platform": platform,
                "receiptId": receiptId,
                "readyForCapture": ready,
                "candidateRank": candidate["rank"] ?? "",
                "title": candidate["title"] ?? "",
                "clipPath": candidate["clipPath"] ?? "",
                "platformCopyPath": candidate["platformCopyPath"] ?? "",
                "captionSrtPath": candidate["captionSrtPath"] ?? "",
                "captureCommand": ready
                    ? "script/agentctl.sh social-master-queue-receipt \(candidate["rank"] ?? "") \"\(platform)\" published <public-url> <provider-id> \"manual receipt\""
                    : "No receipt id is attached for \(platform). Generate/promote a publish receipt before claiming Quipsly captured this post.",
                "proofRule": "Only mark this platform uploaded, scheduled, or published after a real public/scheduled URL or provider receipt exists."
            ] as [String: Any]
        }
        let readyCount = items.filter { ($0["readyForCapture"] as? Bool) == true }.count
        return [
            "model": "quipsly-selected-social-receipt-checklist",
            "version": "2026-06-17.selected-social-receipt-checklist.v1",
            "status": readyCount == 0 ? "needs-receipt-ids" : "ready-for-receipt-capture",
            "selectedCandidateRank": candidate["rank"] ?? "",
            "selectedTitle": candidate["title"] ?? "",
            "readyPlatformCount": readyCount,
            "blockedPlatformCount": max(0, items.count - readyCount),
            "items": items,
            "nextAction": readyCount == 0
                ? "Promote/generate platform receipt rows for this selected candidate before claiming Quipsly captured publication proof."
                : "Post or schedule manually/API-side, then run the listed capture command for each platform URL/provider receipt.",
            "nonGoals": [
                "This checklist does not upload, schedule, or publish.",
                "Do not mark a platform complete without a real URL or provider receipt.",
                "Do not mutate source media or edit decisions from receipt capture."
            ]
        ]
    }

    private func selectedSocialMasterQueueArtifactReadinessPayload() -> [String: Any] {
        guard let candidate = selectedSocialMasterQueueCandidate() else {
            return [
                "status": "no-candidate-selected",
                "readyToReview": false,
                "items": []
            ]
        }

        let specs: [(key: String, label: String, required: Bool)] = [
            ("clipPath", "derivative short", true),
            ("thumbnailPath", "thumbnail", false),
            ("captionSrtPath", "captions", false),
            ("platformCopyPath", "platform copy", true)
        ]
        let items = specs.map { spec -> [String: Any] in
            let path = (candidate[spec.key] ?? "").trimmingCharacters(in: .whitespacesAndNewlines)
            let exists = !path.isEmpty && FileManager.default.fileExists(atPath: path)
            return [
                "key": spec.key,
                "label": spec.label,
                "path": path,
                "required": spec.required,
                "exists": exists,
                "status": exists ? "ready" : (spec.required ? "missing-required" : "missing-optional")
            ]
        }
        let missingRequired = items.contains { item in
            (item["required"] as? Bool ?? false) && !(item["exists"] as? Bool ?? false)
        }
        return [
            "status": missingRequired ? "needs-files" : "ready-to-review",
            "readyToReview": !missingRequired,
            "items": items
        ]
    }

