    private func captureSocialReceiptFromAgent(values: [String: String]) {
        guard let sequence = projectStore.activeSequence else {
            lastMediaAction = "Social receipt capture blocked: no active sequence"
            updateAgentState()
            return
        }
        let publicURL = (values["public_url"] ?? values["url"] ?? values["publicURL"] ?? "")
            .trimmingCharacters(in: .whitespacesAndNewlines)
        guard !publicURL.isEmpty else {
            lastMediaAction = "Social receipt capture blocked: missing public_url"
            updateAgentState()
            return
        }

        let status = (values["status"] ?? "published").trimmingCharacters(in: .whitespacesAndNewlines)
        let providerId = (values["provider_receipt_id"] ?? values["provider_id"] ?? "")
            .trimmingCharacters(in: .whitespacesAndNewlines)
        let platform = (values["platform"] ?? "").trimmingCharacters(in: .whitespacesAndNewlines).lowercased()
        let title = (values["title"] ?? "").trimmingCharacters(in: .whitespacesAndNewlines).lowercased()
        let artifactPath = (values["artifact_path"] ?? values["artifactPath"] ?? "")
            .trimmingCharacters(in: .whitespacesAndNewlines)
        let deliveryLaneId = (values["delivery_lane_id"] ?? values["lane_id"] ?? "")
            .trimmingCharacters(in: .whitespacesAndNewlines)

        let explicitId = (values["id"] ?? values["receipt_id"] ?? "").trimmingCharacters(in: .whitespacesAndNewlines)
        let receipt: PublishReceiptRecord?
        if let receiptId = UUID(uuidString: explicitId) {
            receipt = sequence.publishReceipts.first { $0.id == receiptId }
        } else {
            let candidates = socialShortPublishRecords(from: sequence.publishReceipts).filter { record in
                if !platform.isEmpty && record.platform.lowercased() != platform { return false }
                if !title.isEmpty && record.title.trimmingCharacters(in: .whitespacesAndNewlines).lowercased() != title { return false }
                if !artifactPath.isEmpty && record.artifactPath != artifactPath { return false }
                if !deliveryLaneId.isEmpty && !publishLaneMatches(record.deliveryLaneId, targetLaneId: deliveryLaneId) { return false }
                return true
            }
            guard candidates.count == 1 else {
                lastMediaAction = candidates.isEmpty
                    ? "Social receipt capture blocked: no matching social receipt"
                    : "Social receipt capture blocked: matching receipt is ambiguous; provide receipt_id"
                updateAgentState()
                return
            }
            receipt = candidates.first
        }

        guard let receipt else {
            lastMediaAction = "Social receipt capture blocked: receipt not found"
            updateAgentState()
            return
        }

        var updateValues: [String: String] = [
            "id": receipt.id.uuidString,
            "status": status.isEmpty ? "published" : status,
            "upload_job_status": uploadJobStatusForManualReceipt(status.isEmpty ? "published" : status),
            "public_url": publicURL,
            "receipt_json": stableJSONString([
                "model": "quipsly-manual-social-receipt",
                "version": "2026-06-17.manual-social-receipt.v1",
                "platform": receipt.platform,
                "deliveryLaneId": receipt.deliveryLaneId,
                "title": receipt.title,
                "artifactPath": receipt.artifactPath,
                "publicURL": publicURL,
                "status": status.isEmpty ? "published" : status,
                "capturedAt": ISO8601DateFormatter().string(from: Date()),
                "captureMethod": "quipsly-agent-command"
            ]),
            "notes": values["notes"] ?? "Manual social receipt captured by agent command."
        ]
        if !providerId.isEmpty {
            updateValues["provider_receipt_id"] = providerId
        }
        updatePublishReceiptFromAgent(values: updateValues)
    }

    private func generateSocialShortsPacketForAgent(directoryPath: String?, basename: String?) {
        guard let sequence = projectStore.activeSequence else {
            socialShortsPacketStatus = "blocked"
            socialShortsPacketOutputPath = ""
            socialShortsPacketErrorMessage = "Load an episode session before generating a social shorts packet."
            socialShortsPacketGeneratedAt = Date()
            lastMediaAction = "Social shorts packet blocked: no loaded session"
            updateAgentState()
            return
        }

        guard !sequence.shortClipQueue.isEmpty else {
            socialShortsPacketStatus = "blocked"
            socialShortsPacketOutputPath = ""
            socialShortsPacketErrorMessage = "Queue at least one short before generating a social shorts packet."
            socialShortsPacketGeneratedAt = Date()
            lastMediaAction = "Social shorts packet blocked: no queued shorts"
            updateAgentState()
            return
        }

        socialShortsPacketStatus = "generating"
        socialShortsPacketErrorMessage = ""
        socialShortsPacketGeneratedAt = Date()

        do {
            let rootDirectory: URL
            if let directoryPath, !directoryPath.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty {
                rootDirectory = URL(fileURLWithPath: directoryPath, isDirectory: true)
            } else {
                rootDirectory = defaultPublishPacketDirectory()
                    .appendingPathComponent("SocialShortPackets", isDirectory: true)
            }
            let safeBase = sanitizedExportBasename(basename?.isEmpty == false ? basename! : "\(normalizedActiveSessionName())-social-shorts")
            let packetDirectory = rootDirectory.appendingPathComponent("\(safeBase)-social-shorts-packet", isDirectory: true)
            try FileManager.default.createDirectory(at: packetDirectory, withIntermediateDirectories: true)

            let manifestURL = packetDirectory.appendingPathComponent("\(safeBase)-social-shorts-manifest.json")
            try writeJSONObject(
                socialShortsPacketManifest(sequence: sequence, packetDirectory: packetDirectory.path),
                to: manifestURL
            )

            socialShortsPacketStatus = "generated"
            socialShortsPacketOutputPath = manifestURL.path
            socialShortsPacketErrorMessage = ""
            lastMediaAction = "Generated social shorts packet: \(manifestURL.lastPathComponent)"
        } catch {
            socialShortsPacketStatus = "failed"
            socialShortsPacketErrorMessage = error.localizedDescription
            lastMediaAction = "Social shorts packet failed: \(error.localizedDescription)"
        }
        updateAgentState()
    }

    private func socialShortsPacketManifest(sequence: MediaSequence, packetDirectory: String) -> [String: Any] {
        let formatter = ISO8601DateFormatter()
        let clips = sequence.shortClipQueue.enumerated().map { index, clip -> [String: Any] in
            let sequenceStart = sequenceStartTime(for: clip, in: sequence)
            let artifactPath = lastExportedShortPath(for: clip) ?? ""
            let artifactReady = !artifactPath.isEmpty && FileManager.default.fileExists(atPath: artifactPath)
            let title = clip.title.trimmingCharacters(in: .whitespacesAndNewlines)
            let caption = clip.captionDraft.trimmingCharacters(in: .whitespacesAndNewlines)
            let overlay = clip.primaryOverlayText.trimmingCharacters(in: .whitespacesAndNewlines)
            let hook = clip.hookText.trimmingCharacters(in: .whitespacesAndNewlines)
            let presets = clip.destinationPresets.isEmpty
                ? clip.destinations.map { ShortDestinationPreset(platform: $0, title: title.isEmpty ? "Untitled short" : title) }
                : clip.destinationPresets

            return [
                "index": index + 1,
                "id": clip.id.uuidString,
                "title": title.isEmpty ? "Untitled short" : title,
                "timeBase": "sequence-seconds",
                "sequenceStartTime": sequenceStart,
                "sequenceEndTime": sequenceStart + clip.duration,
                "duration": clip.duration,
                "format": clip.format.rawValue,
                "artifactPath": artifactPath,
                "artifactStatus": artifactReady ? "ready" : "needs-export",
                "reviewStatus": clip.reviewStatus,
                "exportStatus": clip.exportStatus,
                "hookText": hook,
                "captionDraft": caption,
                "primaryOverlayText": overlay,
                "notes": clip.notes,
                "publishNotes": clip.publishNotes,
                "sourceLaneId": clip.sourceLaneId?.uuidString ?? "",
                "sourceTagId": clip.sourceTagId?.uuidString ?? "",
                "createdAt": formatter.string(from: clip.createdAt),
                "updatedAt": formatter.string(from: clip.updatedAt),
                "platforms": presets.map { preset in
                    let platformTitle = preset.title.trimmingCharacters(in: .whitespacesAndNewlines)
                    let platformCaption = preset.caption.trimmingCharacters(in: .whitespacesAndNewlines)
                    return [
                        "platform": preset.platform,
                        "title": platformTitle.isEmpty ? (title.isEmpty ? "Untitled short" : title) : platformTitle,
                        "caption": platformCaption.isEmpty ? caption : platformCaption,
                        "hashtags": preset.hashtags,
                        "status": preset.status,
                        "uploadStatus": "manual-review-required",
                        "destinationGuidance": publishDestinationGuidance(
                            platform: preset.platform,
                            deliveryLaneId: "social-short-clips",
                            format: "9:16"
                        )
                    ] as [String: Any]
                }
            ]
        }

        return [
            "model": "quipsly-social-shorts-packet",
            "version": "2026-06-17.social-shorts-packet.v1",
            "sessionName": normalizedActiveSessionName(),
            "sequenceTitle": sequence.title,
            "sequenceDuration": sequence.duration,
            "generatedAt": formatter.string(from: Date()),
            "packetDirectory": packetDirectory,
            "clipCount": sequence.shortClipQueue.count,
            "readyArtifactCount": clips.filter { ($0["artifactStatus"] as? String) == "ready" }.count,
            "destinationPlatforms": ["YouTube Shorts", "Instagram", "Facebook", "LinkedIn"],
            "directPublishingReady": false,
            "manualPublishingReady": true,
            "sourcePolicy": "Cuts are output metadata over sequence time. This packet references exported derivative files and does not mutate whole source media.",
            "nextActions": [
                "Export any clips with artifactStatus=needs-export.",
                "Review title, caption, overlay, and hashtags per platform.",
                "Upload manually or hand this packet to a future platform connector.",
                "Capture platform receipts back into the publish ledger after posting or scheduling."
            ],
            "clips": clips
        ]
    }

    private func generateSocialPublicationQueueForAgent(directoryPath: String?, basename: String?) {
        guard var sequence = projectStore.activeSequence else {
            socialPublicationQueueStatus = "blocked"
            socialPublicationQueueOutputPath = ""
            socialPublicationQueueErrorMessage = "Load an episode session before generating a social publication queue."
            socialPublicationQueueGeneratedAt = Date()
            lastMediaAction = "Social publication queue blocked: no loaded session"
            updateAgentState()
            return
        }

        if sequence.publishReceipts.isEmpty {
            generatePublishLedgerFromCurrentDelivery()
            sequence = projectStore.activeSequence ?? sequence
        }

        let shortRecords = socialPublicationQueueSourceRecords(from: sequence)
        guard !shortRecords.isEmpty else {
            socialPublicationQueueStatus = "blocked"
            socialPublicationQueueOutputPath = ""
            socialPublicationQueueErrorMessage = "No exported social short artifacts were found in the publish ledger. Export shorts and refresh the publish ledger first."
            socialPublicationQueueGeneratedAt = Date()
            lastMediaAction = "Social publication queue blocked: no exported short artifacts"
            updateAgentState()
            return
        }

        socialPublicationQueueStatus = "generating"
        socialPublicationQueueOutputPath = ""
        socialPublicationQueueErrorMessage = ""
        socialPublicationQueueGeneratedAt = Date()

        do {
            let rootDirectory: URL
            if let directoryPath, !directoryPath.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty {
                rootDirectory = URL(fileURLWithPath: directoryPath, isDirectory: true)
            } else {
                rootDirectory = defaultPublishPacketDirectory()
                    .appendingPathComponent("SocialPublicationQueues", isDirectory: true)
            }
            let safeBase = sanitizedExportBasename(basename?.isEmpty == false ? basename! : "\(normalizedActiveSessionName())-social-publication")
            let queueDirectory = rootDirectory.appendingPathComponent("\(safeBase)-social-publication-queue", isDirectory: true)
            let clipsDirectory = queueDirectory.appendingPathComponent("clips", isDirectory: true)
            let captionsDirectory = queueDirectory.appendingPathComponent("captions", isDirectory: true)
            let copyDirectory = queueDirectory.appendingPathComponent("platform-copy", isDirectory: true)
            try FileManager.default.createDirectory(at: clipsDirectory, withIntermediateDirectories: true)
            try FileManager.default.createDirectory(at: captionsDirectory, withIntermediateDirectories: true)
            try FileManager.default.createDirectory(at: copyDirectory, withIntermediateDirectories: true)

            let queueItems = try shortRecords.enumerated().map { index, record in
                try socialPublicationQueueItem(
                    record: record,
                    sequence: sequence,
                    index: index + 1,
                    clipsDirectory: clipsDirectory,
                    captionsDirectory: captionsDirectory,
                    copyDirectory: copyDirectory
                )
            }
            let manifestURL = queueDirectory.appendingPathComponent("\(safeBase)-social-publication-queue.json")
            let csvURL = queueDirectory.appendingPathComponent("\(safeBase)-social-publication-queue.csv")
            let readmeURL = queueDirectory.appendingPathComponent("README.md")
            let manifest = socialPublicationQueueManifest(
                sequence: sequence,
                queueDirectory: queueDirectory.path,
                items: queueItems
            )
            try writeJSONObject(manifest, to: manifestURL)
            try socialPublicationQueueCSV(items: queueItems).write(to: csvURL, atomically: true, encoding: .utf8)
            try socialPublicationQueueReadme(items: queueItems, manifestURL: manifestURL, csvURL: csvURL).write(to: readmeURL, atomically: true, encoding: .utf8)

            socialPublicationQueueStatus = "generated"
            socialPublicationQueueOutputPath = queueDirectory.path
            socialPublicationQueueErrorMessage = ""
            socialPublicationQueueGeneratedAt = Date()
            lastMediaAction = "Generated social publication queue: \(queueDirectory.lastPathComponent)"
        } catch {
            socialPublicationQueueStatus = "failed"
            socialPublicationQueueOutputPath = ""
            socialPublicationQueueErrorMessage = error.localizedDescription
            socialPublicationQueueGeneratedAt = Date()
            lastMediaAction = "Social publication queue failed: \(error.localizedDescription)"
        }
        updateAgentState()
    }

    private func generateReviewedSocialQueueForAgent(directoryPath: String?, basename: String?) {
        guard let sequence = projectStore.activeSequence else {
            socialPublicationQueueStatus = "blocked"
            socialPublicationQueueOutputPath = ""
            socialPublicationQueueErrorMessage = "Load an episode session before generating a reviewed social queue."
            socialPublicationQueueGeneratedAt = Date()
            lastMediaAction = "Reviewed social queue blocked: no loaded session"
            updateAgentState()
            return
        }

        let keptShorts = sequence.shortClipQueue
            .filter { $0.reviewStatus.lowercased() == "keep" }
            .sorted { lhs, rhs in
                let left = shortClipSegments(for: lhs, in: sequence).map(\.start).min() ?? lhs.startTime
                let right = shortClipSegments(for: rhs, in: sequence).map(\.start).min() ?? rhs.startTime
                if left == right {
                    return lhs.title < rhs.title
                }
                return left < right
            }

        guard !keptShorts.isEmpty else {
            socialPublicationQueueStatus = "blocked"
            socialPublicationQueueOutputPath = ""
            socialPublicationQueueErrorMessage = "No shorts are marked Keep. Review the queue first, then generate a publication queue."
            socialPublicationQueueGeneratedAt = Date()
            lastMediaAction = "Reviewed social queue blocked: no kept shorts"
            updateAgentState()
            return
        }

        let missingExports = keptShorts.filter { clip in
            guard let path = lastExportedShortPath(for: clip), FileManager.default.fileExists(atPath: path) else {
                return true
            }
            return false
        }

        guard missingExports.isEmpty else {
            let names = missingExports.map(\.title).prefix(3).joined(separator: ", ")
            socialPublicationQueueStatus = "blocked"
            socialPublicationQueueOutputPath = ""
            socialPublicationQueueErrorMessage = "Kept short(s) need a 9:16 export before queue generation: \(names). Export selected or queued shorts first."
            socialPublicationQueueGeneratedAt = Date()
            lastMediaAction = "Reviewed social queue blocked: kept shorts need export"
            updateAgentState()
            return
        }

        socialPublicationQueueStatus = "generating"
        socialPublicationQueueOutputPath = ""
        socialPublicationQueueErrorMessage = ""
        socialPublicationQueueGeneratedAt = Date()

        do {
            let rootDirectory: URL
            if let directoryPath, !directoryPath.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty {
                rootDirectory = URL(fileURLWithPath: directoryPath, isDirectory: true)
            } else {
                rootDirectory = defaultPublishPacketDirectory()
                    .appendingPathComponent("ReviewedSocialQueues", isDirectory: true)
            }
            let safeBase = sanitizedExportBasename(basename?.isEmpty == false ? basename! : "\(normalizedActiveSessionName())-reviewed-keeps")
            let queueDirectory = rootDirectory.appendingPathComponent("\(safeBase)-reviewed-social-queue", isDirectory: true)
            let clipsDirectory = queueDirectory.appendingPathComponent("clips", isDirectory: true)
            let captionsDirectory = queueDirectory.appendingPathComponent("captions", isDirectory: true)
            let copyDirectory = queueDirectory.appendingPathComponent("platform-copy", isDirectory: true)
            try FileManager.default.createDirectory(at: clipsDirectory, withIntermediateDirectories: true)
            try FileManager.default.createDirectory(at: captionsDirectory, withIntermediateDirectories: true)
            try FileManager.default.createDirectory(at: copyDirectory, withIntermediateDirectories: true)

            let queueItems = try keptShorts.enumerated().map { index, clip in
                try reviewedSocialPublicationQueueItem(
                    clip: clip,
                    sequence: sequence,
                    index: index + 1,
                    clipsDirectory: clipsDirectory,
                    captionsDirectory: captionsDirectory,
                    copyDirectory: copyDirectory
                )
            }

            let manifestURL = queueDirectory.appendingPathComponent("\(safeBase)-reviewed-social-queue.json")
            let csvURL = queueDirectory.appendingPathComponent("\(safeBase)-reviewed-social-queue.csv")
            let readmeURL = queueDirectory.appendingPathComponent("README.md")
            let manifest = reviewedSocialPublicationQueueManifest(
                sequence: sequence,
                queueDirectory: queueDirectory.path,
                items: queueItems
            )
            try writeJSONObject(manifest, to: manifestURL)
            try socialPublicationQueueCSV(items: queueItems).write(to: csvURL, atomically: true, encoding: .utf8)
            try reviewedSocialPublicationQueueReadme(items: queueItems, manifestURL: manifestURL, csvURL: csvURL).write(to: readmeURL, atomically: true, encoding: .utf8)

            socialPublicationQueueStatus = "generated"
            socialPublicationQueueOutputPath = queueDirectory.path
            socialPublicationQueueErrorMessage = ""
            socialPublicationQueueGeneratedAt = Date()
            lastMediaAction = "Generated reviewed social queue: \(queueDirectory.lastPathComponent)"
        } catch {
            socialPublicationQueueStatus = "failed"
            socialPublicationQueueOutputPath = ""
            socialPublicationQueueErrorMessage = error.localizedDescription
            socialPublicationQueueGeneratedAt = Date()
            lastMediaAction = "Reviewed social queue failed: \(error.localizedDescription)"
        }
        updateAgentState()
    }

    private func reviewedSocialPublicationQueueItem(
        clip: ShortClipCandidate,
        sequence: MediaSequence,
        index: Int,
        clipsDirectory: URL,
        captionsDirectory: URL,
        copyDirectory: URL
    ) throws -> [String: Any] {
        let title = clip.title.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty ? "Untitled short" : clip.title
        let slug = sanitizedExportBasename(title).lowercased()
        let artifactPath = lastExportedShortPath(for: clip) ?? ""
        let sourceURL = URL(fileURLWithPath: artifactPath)
        let copiedClipURL = clipsDirectory.appendingPathComponent(String(format: "%02d-%@-9x16.mp4", index, slug))
        if FileManager.default.fileExists(atPath: copiedClipURL.path) {
            try FileManager.default.removeItem(at: copiedClipURL)
        }
        try FileManager.default.copyItem(at: sourceURL, to: copiedClipURL)

        let exportRanges = shortClipExportRanges(for: clip, in: sequence)
        let duration = max(1, exportRanges.reduce(0) { $0 + $1.duration })
        let segments = shortClipSegments(for: clip, in: sequence)
        let sequenceStart = segments.map(\.start).min() ?? clip.startTime
        let sequenceEnd = segments.map(\.end).max() ?? (sequenceStart + clip.duration)
        let hook = clip.hookText.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty
            ? title
            : clip.hookText.trimmingCharacters(in: .whitespacesAndNewlines)
        let roughTranscript = clip.captionDraft
            .replacingOccurrences(of: "Rough transcript:", with: "")
            .trimmingCharacters(in: .whitespacesAndNewlines)
        let platformCopy = socialPublicationPlatformCopy(title: title, hook: hook, sequence: sequence)
        let captionURL = captionsDirectory.appendingPathComponent(String(format: "%02d-%@.srt", index, slug))
        let captionText = roughTranscript.isEmpty ? hook : roughTranscript
        try socialPublicationSRT(caption: captionText, duration: duration).write(to: captionURL, atomically: true, encoding: .utf8)

        let copyURL = copyDirectory.appendingPathComponent(String(format: "%02d-%@-copy.md", index, slug))
        try socialPublicationCopyMarkdown(title: title, hook: hook, roughTranscript: roughTranscript, platformCopy: platformCopy)
            .write(to: copyURL, atomically: true, encoding: .utf8)

        return [
            "rank": index,
            "queueIndex": index,
            "reviewStatus": "keep",
            "title": title,
            "hook": hook,
            "roughTranscript": roughTranscript,
            "duration": duration,
            "sourceSequenceStartSeconds": sequenceStart,
            "sourceSequenceEndSeconds": sequenceEnd,
            "sourceShortClipId": clip.id.uuidString,
            "sourcePublishReceiptId": "",
            "sourceArtifactPath": artifactPath,
            "clipPath": copiedClipURL.path,
            "clipBytes": fileSize(atPath: copiedClipURL.path),
            "captionSrtPath": captionURL.path,
            "platformCopyPath": copyURL.path,
            "platformCopy": platformCopy,
            "hashtags": socialPublicationHashtags(for: title),
            "manualReviewChecklist": [
                "Watch this kept short end to end.",
                "Confirm the vertical crop and captions are safe for YouTube Shorts, Instagram, Facebook, and LinkedIn.",
                "Confirm the title, hook, and description fit the target platform.",
                "Upload manually until direct platform integrations are wired.",
                "Record public URLs or receipts back into Quipsly after posting or scheduling."
            ]
        ]
    }

    private func reviewedSocialPublicationQueueManifest(sequence: MediaSequence, queueDirectory: String, items: [[String: Any]]) -> [String: Any] {
        let formatter = ISO8601DateFormatter()
        return [
            "model": "quipsly-reviewed-social-publication-queue",
            "version": "2026-06-18.reviewed-social-publication-queue.v1",
            "generatedAt": formatter.string(from: Date()),
            "sessionName": normalizedActiveSessionName(),
            "episode": sequence.title,
            "queueFolder": queueDirectory,
            "publishingTruth": "Manual-upload-ready queue generated only from shorts explicitly marked Keep.",
            "reviewGate": "draft, refine, and reject shorts were intentionally excluded.",
            "sourcePolicy": "Uses copied rendered 9:16 derivative shorts only. Original source media and long sequence lanes are untouched.",
            "platforms": ["YouTube Shorts", "Instagram", "Facebook", "LinkedIn"],
            "manualUploadStatus": "ready-for-human-review-and-upload",
            "clipCount": items.count,
            "clips": items.sorted { ($0["rank"] as? Int ?? 999) < ($1["rank"] as? Int ?? 999) }
        ]
    }

    private func reviewedSocialPublicationQueueReadme(items: [[String: Any]], manifestURL: URL, csvURL: URL) -> String {
        let list = items.sorted { ($0["rank"] as? Int ?? 999) < ($1["rank"] as? Int ?? 999) }.map { item -> String in
            let index = item["queueIndex"] as? Int ?? 0
            let title = item["title"] as? String ?? "Untitled short"
            let duration = item["duration"] as? Double ?? 0
            let clip = URL(fileURLWithPath: item["clipPath"] as? String ?? "").lastPathComponent
            return "\(index). \(title) (\(String(format: "%.1f", duration))s)\n   - Review: keep\n   - File: `\(clip)`"
        }.joined(separator: "\n")

        return """
        # Reviewed Social Publication Queue

        Generated from QuipslyStudio using only shorts explicitly marked **Keep**. Draft, refine, and reject shorts were not copied.

        ## What is ready
        - \(items.count) vertical short(s) copied into `clips/`.
        - Platform copy drafts are in `platform-copy/`.
        - Caption sidecars are in `captions/`.
        - Machine-readable queue: `\(manifestURL.lastPathComponent)`.
        - Spreadsheet-friendly queue: `\(csvURL.lastPathComponent)`.

        ## Recommended posting order
        \(list)

        ## Human review rule
        These are publication-ready candidates, not auto-published posts. Watch each one once before upload, confirm safe zones/captions, then record the public URL back into Quipsly.
        """
    }

    private func socialPublicationQueueSourceRecords(from sequence: MediaSequence) -> [PublishReceiptRecord] {
        var seenPaths: Set<String> = []
        var records: [PublishReceiptRecord] = []
        for record in sequence.publishReceipts {
            let path = record.artifactPath.trimmingCharacters(in: .whitespacesAndNewlines)
            guard !path.isEmpty,
                  !seenPaths.contains(path),
                  FileManager.default.fileExists(atPath: path),
                  record.format == "9:16",
                  record.artifactType.lowercased().contains("short") else {
                continue
            }
            seenPaths.insert(path)
            records.append(record)
        }
        return records.sorted { lhs, rhs in
            let left = socialPublicationMetadataDouble(lhs.metadataJson, key: "sequenceStartTime") ?? Double.greatestFiniteMagnitude
            let right = socialPublicationMetadataDouble(rhs.metadataJson, key: "sequenceStartTime") ?? Double.greatestFiniteMagnitude
            if left == right {
                return lhs.title < rhs.title
            }
            return left < right
        }
    }

    private func socialPublicationQueueItem(
        record: PublishReceiptRecord,
        sequence: MediaSequence,
        index: Int,
        clipsDirectory: URL,
        captionsDirectory: URL,
        copyDirectory: URL
    ) throws -> [String: Any] {
        let metadata = socialPublicationMetadata(record.metadataJson)
        let title = record.title.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty ? "Untitled short" : record.title
        let slug = sanitizedExportBasename(title).lowercased()
        let sourceURL = URL(fileURLWithPath: record.artifactPath)
        let copiedClipURL = clipsDirectory.appendingPathComponent(String(format: "%02d-%@-9x16.mp4", index, slug))
        if FileManager.default.fileExists(atPath: copiedClipURL.path) {
            try FileManager.default.removeItem(at: copiedClipURL)
        }
        try FileManager.default.copyItem(at: sourceURL, to: copiedClipURL)

        let duration = socialPublicationMetadataDouble(record.metadataJson, key: "duration") ?? shortMediaDurationFallback(record: record)
        let hook = (metadata["hookText"] as? String)?.trimmingCharacters(in: .whitespacesAndNewlines)
            ?? title
        let roughTranscript = ((metadata["captionDraft"] as? String) ?? record.description)
            .replacingOccurrences(of: "Rough transcript:", with: "")
            .trimmingCharacters(in: .whitespacesAndNewlines)
        let platformCopy = socialPublicationPlatformCopy(title: title, hook: hook, sequence: sequence)
        let captionURL = captionsDirectory.appendingPathComponent(String(format: "%02d-%@.srt", index, slug))
        let captionText = roughTranscript.isEmpty ? hook : roughTranscript
        try socialPublicationSRT(caption: captionText, duration: max(duration, 1)).write(to: captionURL, atomically: true, encoding: .utf8)

        let copyURL = copyDirectory.appendingPathComponent(String(format: "%02d-%@-copy.md", index, slug))
        try socialPublicationCopyMarkdown(title: title, hook: hook, roughTranscript: roughTranscript, platformCopy: platformCopy)
            .write(to: copyURL, atomically: true, encoding: .utf8)

        let hashtags = socialPublicationHashtags(for: title)
        let rank = socialPublicationRank(for: title, fallback: index)
        return [
            "rank": rank,
            "queueIndex": index,
            "reviewStatus": socialPublicationReviewStatus(rank: rank),
            "title": title,
            "hook": hook,
            "roughTranscript": roughTranscript,
            "duration": duration,
            "sourceSequenceStartSeconds": metadata["sequenceStartTime"] ?? NSNull(),
            "sourceSequenceEndSeconds": metadata["sequenceEndTime"] ?? NSNull(),
            "sourceShortClipId": metadata["shortClipId"] as? String ?? "",
            "sourcePublishReceiptId": record.id.uuidString,
            "sourceArtifactPath": record.artifactPath,
            "clipPath": copiedClipURL.path,
            "captionSrtPath": captionURL.path,
            "platformCopyPath": copyURL.path,
            "platformCopy": platformCopy,
            "hashtags": hashtags,
            "manualReviewChecklist": [
                "Watch the exported short end to end.",
                "Confirm burned-in text/captions do not cover faces or platform UI safe zones.",
                "Confirm title/caption tone before posting.",
                "Upload manually until direct platform integrations are wired.",
                "Record published URL/receipt back into Quipsly after posting."
            ]
        ]
    }

    private func socialPublicationQueueManifest(sequence: MediaSequence, queueDirectory: String, items: [[String: Any]]) -> [String: Any] {
        let formatter = ISO8601DateFormatter()
        return [
            "model": "quipsly-social-publication-queue",
            "version": "2026-06-17.social-publication-queue.v1",
            "generatedAt": formatter.string(from: Date()),
            "sessionName": normalizedActiveSessionName(),
            "episode": sequence.title,
            "queueFolder": queueDirectory,
            "publishingTruth": "Manual-upload-ready queue. Nothing here has been uploaded or scheduled by this app action.",
            "sourcePolicy": "Uses copied rendered 9:16 derivative shorts only. Original source media is untouched.",
            "platforms": ["YouTube Shorts", "Instagram", "Facebook", "LinkedIn"],
            "manualUploadStatus": "ready-for-human-review-and-upload",
            "clipCount": items.count,
            "topPicks": items.filter { ($0["reviewStatus"] as? String) == "top-pick" }.map { $0["title"] as? String ?? "" },
            "clips": items.sorted { ($0["rank"] as? Int ?? 999) < ($1["rank"] as? Int ?? 999) }
        ]
    }

    private func socialPublicationQueueCSV(items: [[String: Any]]) -> String {
        let headers = ["rank", "queue_index", "status", "title", "duration_seconds", "clip_path", "caption_srt_path", "youtube_shorts_caption", "instagram_caption", "facebook_caption", "linkedin_caption"]
        let rows = items.sorted { ($0["rank"] as? Int ?? 999) < ($1["rank"] as? Int ?? 999) }.map { item -> [String] in
            let platformCopy = item["platformCopy"] as? [String: String] ?? [:]
            let rank = item["rank"] as? Int ?? 0
            let queueIndex = item["queueIndex"] as? Int ?? 0
            let reviewStatus = item["reviewStatus"] as? String ?? ""
            let title = item["title"] as? String ?? ""
            let duration = item["duration"] as? Double ?? 0
            let clipPath = item["clipPath"] as? String ?? ""
            let captionPath = item["captionSrtPath"] as? String ?? ""
            return [
                "\(rank)",
                "\(queueIndex)",
                reviewStatus,
                title,
                String(format: "%.3f", duration),
                clipPath,
                captionPath,
                platformCopy["YouTube Shorts"] ?? "",
                platformCopy["Instagram"] ?? "",
                platformCopy["Facebook"] ?? "",
                platformCopy["LinkedIn"] ?? ""
            ]
        }
        return ([headers] + rows)
            .map { $0.map(csvEscape).joined(separator: ",") }
            .joined(separator: "\n") + "\n"
    }

    private func socialPublicationQueueReadme(items: [[String: Any]], manifestURL: URL, csvURL: URL) -> String {
        let sorted = items.sorted { ($0["rank"] as? Int ?? 999) < ($1["rank"] as? Int ?? 999) }
        let list = sorted.map { item -> String in
            let rank = item["rank"] as? Int ?? 0
            let title = item["title"] as? String ?? "Untitled short"
            let duration = item["duration"] as? Double ?? 0
            let status = item["reviewStatus"] as? String ?? ""
            let hook = item["hook"] as? String ?? ""
            let clip = URL(fileURLWithPath: item["clipPath"] as? String ?? "").lastPathComponent
            return "\(rank). \(title) (\(String(format: "%.1f", duration))s) - \(status)\n   - Hook: \(hook)\n   - File: `\(clip)`"
        }.joined(separator: "\n")
        return """
        # Social Publication Queue

        Generated from QuipslyStudio using rendered 9:16 derivative shorts only. Original source media was not touched.

        ## What is ready
        - \(items.count) vertical shorts copied into `clips/`.
        - Platform copy drafts are in `platform-copy/`.
        - Caption sidecars are in `captions/`.
        - Machine-readable queue: `\(manifestURL.lastPathComponent)`.
        - Spreadsheet-friendly queue: `\(csvURL.lastPathComponent)`.

        ## Recommended posting order
        \(list)

        ## Human review rule
        These are publication-ready candidates, not auto-published posts. Watch each one once before upload, confirm safe zones/captions, then record the public URL back into Quipsly.
        """
    }

    private func socialPublicationMetadata(_ text: String) -> [String: Any] {
        let trimmed = text.trimmingCharacters(in: .whitespacesAndNewlines)
        guard !trimmed.isEmpty,
              let data = trimmed.data(using: .utf8),
              let object = try? JSONSerialization.jsonObject(with: data),
              let dictionary = object as? [String: Any] else {
            return [:]
        }
        return dictionary
    }

    private func socialPublicationMetadataDouble(_ text: String, key: String) -> Double? {
        let metadata = socialPublicationMetadata(text)
        if let value = metadata[key] as? Double {
            return value
        }
        if let value = metadata[key] as? NSNumber {
            return value.doubleValue
        }
        if let value = metadata[key] as? String {
            return Double(value)
        }
        return nil
    }

    private func socialPublicationPlatformCopy(title: String, hook: String, sequence: MediaSequence) -> [String: String] {
        let episodeLabel = sequence.title.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty
            ? "High Ground Odyssey"
            : "High Ground Odyssey \(sequence.title)"
        let tags = socialPublicationHashtags(for: title).joined(separator: " ")
        return [
            "YouTube Shorts": "\(hook)\n\nFrom \(episodeLabel).\n\n\(tags) #Cuts",
            "Instagram": "\(hook)\n\nA moment from \(episodeLabel).\n\n\(tags) #Reels",
            "Facebook": "\(hook)\n\nFrom \(episodeLabel). What does this bring up for you?\n\n\(tags)",
            "LinkedIn": "\(hook)\n\nA short reflection from \(episodeLabel). Useful for anyone thinking about mentorship, purpose, identity, and the work of becoming.\n\n\(tags)"
        ]
    }

    private func socialPublicationCopyMarkdown(title: String, hook: String, roughTranscript: String, platformCopy: [String: String]) -> String {
        let sections = ["YouTube Shorts", "Instagram", "Facebook", "LinkedIn"].map { platform in
            "## \(platform)\n\(platformCopy[platform] ?? "")"
        }.joined(separator: "\n\n")
        return """
        # \(title)

        Hook: \(hook)

        Rough transcript: \(roughTranscript.isEmpty ? "Needs transcript review." : roughTranscript)

        \(sections)
        """
    }

    private func socialPublicationSRT(caption: String, duration: Double) -> String {
        "1\n00:00:00,000 --> \(srtTimestamp(duration))\n\(caption)\n"
    }

    private func srtTimestamp(_ seconds: Double) -> String {
        let milliseconds = Int((seconds * 1000).rounded())
        let hours = milliseconds / 3_600_000
        let minutes = (milliseconds % 3_600_000) / 60_000
        let secs = (milliseconds % 60_000) / 1000
        let ms = milliseconds % 1000
        return String(format: "%02d:%02d:%02d,%03d", hours, minutes, secs, ms)
    }

    private func socialPublicationHashtags(for title: String) -> [String] {
        let common = ["#HighGroundOdyssey", "#TheWednesdayRule", "#Podcast", "#Storytelling"]
        let specific: [String]
        switch title {
        case "Learning Why, Not Just What":
            specific = ["#Mentorship", "#Learning", "#Leadership"]
        case "Identity Changes Behavior":
            specific = ["#Identity", "#Habits", "#BehaviorChange"]
        case "Write Things Worth Reading":
            specific = ["#Writing", "#Legacy", "#CreativeLife"]
        case "Don't Downplay Yourself":
            specific = ["#Confidence", "#Encouragement", "#Leadership"]
        case "Farm Work Teaches Stewardship":
            specific = ["#Mentorship", "#Leadership", "#WorkEthic"]
        case "Mutual Mentorship":
            specific = ["#Mentorship", "#Brotherhood", "#Leadership"]
        case "Parkinson's Awareness Goal":
            specific = ["#ParkinsonsAwareness", "#PurposeDriven", "#Podcast"]
        case "Record From Anywhere":
            specific = ["#Podcasting", "#CreativeWorkflow", "#RemoteWork"]
        default:
            specific = ["#CreativeProcess"]
        }
        var seen: Set<String> = []
        return (common + specific).filter { seen.insert($0).inserted }
    }

    private func socialPublicationRank(for title: String, fallback: Int) -> Int {
        switch title {
        case "Learning Why, Not Just What": return 1
        case "Identity Changes Behavior": return 2
        case "Write Things Worth Reading": return 3
        case "Don't Downplay Yourself": return 4
        case "Farm Work Teaches Stewardship": return 5
        case "Mutual Mentorship": return 6
        case "Parkinson's Awareness Goal": return 7
        case "Record From Anywhere": return 8
        default: return fallback
        }
    }

    private func socialPublicationReviewStatus(rank: Int) -> String {
        if rank <= 4 {
            return "top-pick"
        }
        if rank <= 8 {
            return "good-candidate"
        }
        return "test-only-review-last"
    }

    private func shortMediaDurationFallback(record: PublishReceiptRecord) -> Double {
        socialPublicationMetadataDouble(record.metadataJson, key: "duration") ?? 0
    }

    private func csvEscape(_ value: String) -> String {
        let escaped = value.replacingOccurrences(of: "\"", with: "\"\"")
        return "\"\(escaped)\""
    }

    private func generatePodcastPacketForAgent(directoryPath: String?, basename: String?) {
        guard let sequence = projectStore.activeSequence else {
            podcastPacketStatus = "blocked"
            podcastPacketOutputPath = ""
            podcastPacketErrorMessage = "Load an episode session before generating a podcast packet."
            podcastPacketGeneratedAt = Date()
            lastMediaAction = "Podcast packet blocked: no loaded session"
            updateAgentState()
            return
        }

        podcastPacketStatus = "generating"
        podcastPacketErrorMessage = ""
        podcastPacketGeneratedAt = Date()

        do {
            let rootDirectory: URL
            if let directoryPath, !directoryPath.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty {
                rootDirectory = URL(fileURLWithPath: directoryPath, isDirectory: true)
            } else {
                rootDirectory = defaultPublishPacketDirectory()
                    .appendingPathComponent("PodcastPackets", isDirectory: true)
            }
            let safeBase = sanitizedExportBasename(basename?.isEmpty == false ? basename! : "\(normalizedActiveSessionName())-podcast")
            let packetDirectory = rootDirectory.appendingPathComponent("\(safeBase)-podcast-packet", isDirectory: true)
            try FileManager.default.createDirectory(at: packetDirectory, withIntermediateDirectories: true)

            let manifestURL = packetDirectory.appendingPathComponent("\(safeBase)-podcast-manifest.json")
            try writeJSONObject(
                podcastPacketManifest(sequence: sequence, packetDirectory: packetDirectory.path),
                to: manifestURL
            )

            podcastPacketStatus = "generated"
            podcastPacketOutputPath = manifestURL.path
            podcastPacketErrorMessage = ""
            lastMediaAction = "Generated podcast packet: \(manifestURL.lastPathComponent)"
        } catch {
            podcastPacketStatus = "failed"
            podcastPacketOutputPath = ""
            podcastPacketErrorMessage = error.localizedDescription
            lastMediaAction = "Podcast packet failed: \(error.localizedDescription)"
        }
        updateAgentState()
    }

    private func podcastPacketManifest(sequence: MediaSequence, packetDirectory: String) -> [String: Any] {
        let formatter = ISO8601DateFormatter()
        let audioPath = podcastAudioArtifactPath()
        let audioReady = !audioPath.isEmpty && FileManager.default.fileExists(atPath: audioPath)
        let defaultTitle = sequence.title.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty
            ? normalizedActiveSessionName()
            : sequence.title.trimmingCharacters(in: .whitespacesAndNewlines)

        let platforms = ["Spotify", "Apple Podcasts"].map { platform -> [String: Any] in
            let receipt = sequence.publishReceipts.first { record in
                record.platform == platform && record.deliveryLaneId == "podcast-audio-master"
            }
            let receiptId = receipt?.id.uuidString ?? ""
            return [
                "platform": platform,
                "deliveryLaneId": "podcast-audio-master",
                "title": defaultTitle,
                "description": defaultPublishDescription(platform: platform, sequence: sequence),
                "tags": defaultPublishTags(platform: platform, sequence: sequence),
                "artifactPath": audioPath,
                "artifactStatus": audioReady ? "ready" : "needs-audio-export",
                "uploadStatus": "manual-host-or-rss-handoff-required",
                "publishReceiptId": receiptId,
                "publishStatus": receipt?.publishStatus ?? "missing-publish-ledger-record",
                "publicURL": receipt?.publicURL ?? "",
                "providerReceiptId": receipt?.providerReceiptId ?? "",
                "receiptCaptured": receipt.map { publishRecordReceiptCaptured($0) } ?? false,
                "receiptCaptureCommand": receiptId.isEmpty
                    ? "Generate the publish ledger before receipt capture."
                    : "script/agentctl.sh podcast-receipt-capture \"\(platform)\" published <public-url> <provider-id> \"manual podcast receipt\"",
                "destinationGuidance": publishDestinationGuidance(
                    platform: platform,
                    deliveryLaneId: "podcast-audio-master",
                    format: "audio"
                )
            ] as [String: Any]
        }

        return [
            "model": "quipsly-podcast-packet",
            "version": "2026-06-17.podcast-packet.v1",
            "sessionName": normalizedActiveSessionName(),
            "sequenceTitle": sequence.title,
            "sequenceDuration": sequence.duration,
            "generatedAt": formatter.string(from: Date()),
            "packetDirectory": packetDirectory,
            "showTitle": "High Ground Odyssey",
            "episodeTitle": defaultTitle,
            "audioArtifactPath": audioPath,
            "audioArtifactStatus": audioReady ? "ready" : "needs-audio-export",
            "audioArtifactKind": audioPath.isEmpty ? "" : URL(fileURLWithPath: audioPath).pathExtension.lowercased(),
            "manualPublishingReady": audioReady,
            "directPublishingReady": false,
            "rssFeedRequired": true,
            "receiptTargets": podcastReceiptTargetsPayload(records: sequence.publishReceipts),
            "destinationPlatforms": ["Spotify", "Apple Podcasts"],
            "sourcePolicy": "Podcast packet references the exported audio artifact and episode metadata. It does not mutate source media or mark any platform as published.",
            "nextActions": audioReady
                ? [
                    "Review the audio master and episode metadata.",
                    "Upload through the podcast host or RSS workflow for Spotify and Apple Podcasts.",
                    "Capture the public episode URL and provider receipt/id back into the publish ledger."
                ]
                : [
                    "Run audio master export before publishing.",
                    "Regenerate this podcast packet after the audio artifact exists.",
                    "Do not mark Spotify or Apple Podcasts as ready until the audio artifact is present."
                ],
            "platforms": platforms
        ]
    }

    private func podcastAudioArtifactPath() -> String {
        let exportPath = exportOutputPaths
            .filter { FileManager.default.fileExists(atPath: $0) }
            .first { path in
                let lower = path.lowercased()
                return lower.hasSuffix(".m4a")
                    || lower.hasSuffix(".mp3")
                    || lower.hasSuffix(".wav")
                    || lower.hasSuffix(".aac")
                    || lower.hasSuffix(".flac")
            }
        if let exportPath {
            return exportPath
        }

        let records = projectStore.activeSequence?.publishReceipts ?? []
        if let readyReceiptPath = records.first(where: { record in
            record.deliveryLaneId == "podcast-audio-master"
                && FileManager.default.fileExists(atPath: record.artifactPath)
        })?.artifactPath {
            return readyReceiptPath
        }

        return records.first(where: { $0.deliveryLaneId == "podcast-audio-master" })?.artifactPath ?? ""
    }

    private func podcastReadyPacketIsOperatorReady(path explicitPath: String? = nil) -> Bool {
        if let explicitPath {
            return podcastReadyPacketManifestIsOperatorReady(explicitPath.trimmingCharacters(in: .whitespacesAndNewlines))
        }
        let statePath = podcastReadyPacketOutputPath.trimmingCharacters(in: .whitespacesAndNewlines)
        if podcastReadyPacketStatus == "generated",
           podcastReadyPacketManifestIsOperatorReady(statePath) {
            return true
        }
        let durablePath = durablePodcastReadyPacketManifestPath()
        return podcastReadyPacketManifestIsOperatorReady(durablePath)
    }

    private func effectivePodcastReadyPacketManifestPath() -> String {
        let statePath = podcastReadyPacketOutputPath.trimmingCharacters(in: .whitespacesAndNewlines)
        if podcastReadyPacketStatus == "generated",
           podcastReadyPacketManifestIsOperatorReady(statePath) {
            return statePath
        }
        let durablePath = durablePodcastReadyPacketManifestPath()
        if podcastReadyPacketManifestIsOperatorReady(durablePath) {
            return durablePath
        }
        return statePath
    }

    private func durablePodcastReadyPacketManifestPath() -> String {
        let audioPath = podcastAudioArtifactPath().trimmingCharacters(in: .whitespacesAndNewlines)
        guard !audioPath.isEmpty else { return "" }
        let audioURL = URL(fileURLWithPath: audioPath)
        let audioBase = audioURL.deletingPathExtension().lastPathComponent
        let releaseBase: String
        if audioBase.hasSuffix("-podcast-audio") {
            releaseBase = String(audioBase.dropLast("-podcast-audio".count))
        } else {
            releaseBase = audioBase
        }
        let readyBase = "\(releaseBase)-podcast-ready"
        return audioURL
            .deletingLastPathComponent()
            .appendingPathComponent(readyBase, isDirectory: true)
            .appendingPathComponent("\(readyBase).json")
            .path
    }

    private func podcastReadyPacketManifestIsOperatorReady(_ path: String) -> Bool {
        guard !path.isEmpty,
              FileManager.default.fileExists(atPath: path),
              let data = FileManager.default.contents(atPath: path),
              let object = try? JSONSerialization.jsonObject(with: data) as? [String: Any] else {
            return false
        }
        let manualReady = object["manualPublishingReady"] as? Bool ?? false
        let audioPath = (object["audioPath"] as? String ?? "").trimmingCharacters(in: .whitespacesAndNewlines)
        guard manualReady, !audioPath.isEmpty, FileManager.default.fileExists(atPath: audioPath) else {
            return false
        }
        let platforms = object["platforms"] as? [[String: Any]] ?? []
        return platforms.contains { ($0["platform"] as? String) == "Spotify" }
            && platforms.contains { ($0["platform"] as? String) == "Apple Podcasts" }
    }

    private func revealPublishArtifact(_ record: PublishReceiptRecord) {
        let path = record.artifactPath.trimmingCharacters(in: .whitespacesAndNewlines)
        guard !path.isEmpty else {
            lastMediaAction = "Reveal blocked: \(record.platform) has no artifact path"
            updateAgentState()
            return
        }
        #if os(macOS)
        let url = URL(fileURLWithPath: path)
        if FileManager.default.fileExists(atPath: path) {
            NSWorkspace.shared.activateFileViewerSelecting([url])
            lastMediaAction = "Revealed \(record.platform) artifact"
        } else {
            lastMediaAction = "Reveal blocked: artifact missing for \(record.platform)"
        }
        #else
        lastMediaAction = "Reveal is only available on macOS"
        #endif
        updateAgentState()
    }

    private func generatePublishPacketForAgent(directoryPath: String?, basename: String?) {
        guard let sequence = projectStore.activeSequence else {
            publishPacketStatus = "blocked"
            publishPacketOutputPath = ""
            publishPacketErrorMessage = "Load an episode session before generating a publish packet."
            publishPacketGeneratedAt = Date()
            lastMediaAction = "Ship packet blocked: no loaded session"
            updateAgentState()
            return
        }

        guard !sequence.publishReceipts.isEmpty else {
            publishPacketStatus = "blocked"
            publishPacketOutputPath = ""
            publishPacketErrorMessage = "Generate the publish ledger before writing a publish packet."
            publishPacketGeneratedAt = Date()
            lastMediaAction = "Ship packet blocked: ledger has no records"
            updateAgentState()
            return
        }

        publishPacketStatus = "generating"
        publishPacketErrorMessage = ""
        publishPacketGeneratedAt = Date()

        do {
            let rootDirectory: URL
            if let directoryPath, !directoryPath.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty {
                rootDirectory = URL(fileURLWithPath: directoryPath, isDirectory: true)
            } else {
                rootDirectory = defaultPublishPacketDirectory()
            }
            let safeBase = sanitizedExportBasename(basename?.isEmpty == false ? basename! : normalizedActiveSessionName())
            let packetDirectory = rootDirectory.appendingPathComponent("\(safeBase)-publish-packet", isDirectory: true)
            try FileManager.default.createDirectory(at: packetDirectory, withIntermediateDirectories: true)

            let ledgerURL = packetDirectory.appendingPathComponent("\(safeBase)-publish-ledger.json")
            try writeJSONObject(publishLedgerPayload(for: sequence), to: ledgerURL)

            let checklistURL = packetDirectory.appendingPathComponent("\(safeBase)-publish-release-checklist.json")
            try writeJSONObject(publishReleaseChecklistPayload(for: sequence), to: checklistURL)

            let destinationsURL = packetDirectory.appendingPathComponent("\(safeBase)-publish-destinations.json")
            try writeJSONObject(publishDestinationCatalogPayload(), to: destinationsURL)

            let manifestURL = packetDirectory.appendingPathComponent("\(safeBase)-publish-manifest.json")
            try writeJSONObject(
                publishPacketManifest(
                    sequence: sequence,
                    packetDirectory: packetDirectory.path,
                    destinationCatalogFilename: destinationsURL.lastPathComponent
                ),
                to: manifestURL
            )

            for (index, record) in sequence.publishReceipts.enumerated() {
                let recordBase = sanitizedExportBasename(String(format: "%02d-%@-%@", index + 1, record.platform, record.deliveryLaneId))
                let metadataURL = packetDirectory.appendingPathComponent("\(recordBase)-metadata.json")
                let uploadJobURL = packetDirectory.appendingPathComponent("\(recordBase)-upload-job.json")
                let checklistURL = packetDirectory.appendingPathComponent("\(recordBase)-checklist.md")
                try writeJSONStringOrWrappedText(record.metadataJson, fallbackKey: "metadata", to: metadataURL)
                try writeJSONStringOrWrappedText(record.uploadJobJson, fallbackKey: "uploadJob", to: uploadJobURL)
                try publishReceiptChecklistMarkdown(record).write(to: checklistURL, atomically: true, encoding: .utf8)
            }

            publishPacketStatus = "generated"
            publishPacketOutputPath = packetDirectory.path
            publishPacketErrorMessage = ""
            lastMediaAction = "Generated publish packet: \(packetDirectory.lastPathComponent)"
        } catch {
            publishPacketStatus = "failed"
            publishPacketErrorMessage = error.localizedDescription
            lastMediaAction = "Ship packet failed: \(error.localizedDescription)"
        }
        updateAgentState()
    }

    private func generateVerticalSlicePacketForAgent(directoryPath: String?, basename: String?) {
        guard let sequence = projectStore.activeSequence else {
