        }

        verticalSlicePacketStatus = "generating"
        verticalSlicePacketErrorMessage = ""
        verticalSlicePacketGeneratedAt = Date()

        do {
            let rootDirectory: URL
            if let directoryPath, !directoryPath.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty {
                rootDirectory = URL(fileURLWithPath: directoryPath, isDirectory: true)
            } else {
                rootDirectory = defaultPublishPacketDirectory()
