            let verticalSlicePayload = episodeSpinePayload(for: sequence, readinessSummary: readinessSummary)
            let nestWritingPacketState = nestWritingPacketStatePayload()
            let nestWritingSnapshot = nestWritingPacketPayload()

            let studioPayload: [String: Any] = [
                "deliveryReadiness": deliveryReadinessPayload(summary: readinessSummary),
                "shortClipQueue": shortClipQueuePayload(for: sequence),
                "editorProofSnapshot": editorProofSnapshotPayload(
                    for: sequence,
                    readinessSummary: readinessSummary,
                    selectedLaneName: selectedLaneName,
                    selectedTagType: selectedTag.type,
                    programTitle: programState.title,
                    programDetail: programState.detail
                ),
                "sharedPlayheadContract": sharedPlayheadContractPayload(for: sequence)
            ]

            let towerPayload: [String: Any] = [
                "publicationMissionControl": publicationMissionControlPayload(for: sequence),
                "publicationReadyHandoff": publicationReadyHandoffPayload(for: sequence),
                "publishLedger": publishLedgerPayload(for: sequence),
                "publishReleaseChecklist": publishReleaseChecklistPayload(for: sequence),
                "publishPacket": publishPacketPayload(),
                "missingPublicationReceipts": missingPublicationReceiptsPayload(for: sequence)
            ]

            let payload: [String: Any] = [
                "model": "quipsly-nest-studio-tower-vertical-slice-packet",
                "version": "2026-06-20.vertical-slice-packet.v1",
                "generatedAt": formatter.string(from: Date()),
                "sessionName": normalizedActiveSessionName(),
                "projectTitle": projectStore.project.title,
                "sequenceTitle": sequence.title,
                "sequenceDuration": sequence.duration,
                "verticalSliceStatus": verticalSlicePayload["status"] ?? "",
                "verticalSliceNextAction": verticalSlicePayload["nextAction"] ?? "",
                "truth": "One portable snapshot of the current Nest -> Studio -> Tower loop. This is a handoff artifact, not the source of truth.",
                "creativePartnerPolicy": "Codex and Quipslys may create publishable drafts, packets, and production-support materials as full creative partners. Provenance, review state, source context, reversible decisions, and receipts make the work inspectable.",
                "sourcePolicy": "Source media stays whole and proxy-first. Seeded context remains review-labeled. Publication is only true after platform receipts.",
                "verticalSlice": verticalSlicePayload,
                "nest": nestPayload(),
                "nestWritingPacket": nestWritingPacketState,
                "nestWritingSnapshot": nestWritingSnapshot,
                "studio": studioPayload,
                "tower": towerPayload,
                "agentCommands": [
                    "observe": "script/agentctl.sh vertical-slice",
                    "generatePacket": "script/agentctl.sh vertical-slice-packet-generate \"\(rootDirectory.path)\" \"\(safeBase)\"",
                    "openNestWritingLayer": "script/agentctl.sh nest-ensure-writing-document",
                    "generateNestWritingPacket": "script/agentctl.sh nest-writing-packet-generate \"\(rootDirectory.path)\" \"\(safeBase)\"",
                    "prepareRelease": "script/agentctl.sh full-release-prepare /absolute/output/folder \(safeBase) 8",
                    "captureEpisodeReceipt": "script/agentctl.sh episode-receipt-capture YouTube published <public-url> <provider-id> \"manual episode receipt\""
                ],
                "handoffRules": [
                    "This packet may guide agents and humans, but it must not overwrite manuscript canon, timeline decisions, exports, or platform publication state.",
                    "Agent-authored material is allowed to be serious work, not only placeholder work, when labeled with authorship, provenance, and review state.",
                    "Research and factual claims need source context or explicit uncertainty.",
                    "Platform publication is not complete until a public/scheduled URL or provider receipt is captured."
                ]
            ]

            try writeJSONObject(payload, to: outputURL)
            verticalSlicePacketStatus = "generated"
            verticalSlicePacketOutputPath = outputURL.path
            verticalSlicePacketErrorMessage = ""
            lastMediaAction = "Generated vertical slice packet: \(outputURL.lastPathComponent)"
        } catch {
            verticalSlicePacketStatus = "failed"
            verticalSlicePacketErrorMessage = error.localizedDescription
            lastMediaAction = "Vertical slice packet failed: \(error.localizedDescription)"
        }
        updateAgentState()
    }

