    private func publishPacketManifest(
        sequence: MediaSequence,
        packetDirectory: String,
        destinationCatalogFilename: String
    ) -> [String: Any] {
        let formatter = ISO8601DateFormatter()
        let destinationCatalog = publishDestinationCatalogPayload()
        return [
            "model": "quipsly-publish-packet",
            "version": "2026-06-16.publish-packet.v1",
            "sessionName": normalizedActiveSessionName(),
            "sequenceTitle": sequence.title,
            "sequenceDuration": sequence.duration,
            "generatedAt": formatter.string(from: Date()),
            "packetDirectory": packetDirectory,
            "sourcePolicy": "publish packet contains release metadata and artifact references; it does not mutate source media",
            "directPublishingReady": false,
            "destinationCatalog": [
                "filename": destinationCatalogFilename,
                "model": destinationCatalog["model"] ?? "quipslystudio-publish-destinations",
                "version": destinationCatalog["version"] ?? "unknown",
                "rule": "Use destination catalog guidance before manual upload, API upload, receipt capture, or schedule decisions."
            ],
            "recordCount": sequence.publishReceipts.count,
            "releaseChecklist": publishReleaseChecklistSummary(records: sequence.publishReceipts),
            "episodeReceiptTargets": episodeReceiptTargetsPayload(records: sequence.publishReceipts),
            "episodeReceiptCaptureCommand": "script/agentctl.sh episode-receipt-capture YouTube published <public-url> <provider-id> \"manual episode receipt\"",
            "bundledDryRunWorkerReadyCount": sequence.publishReceipts.filter {
                bundledPublishDryRunWorker(for: $0.platform).executable
            }.count,
            "dryRunWorkerPolicy": "Bundled workers validate release packets and ledger safety only. They do not upload, schedule, publish, or create provider receipts.",
            "records": sequence.publishReceipts.enumerated().map { index, record in
                let bundledWorker = bundledPublishDryRunWorker(for: record.platform)
                return [
                    "index": index + 1,
                    "platform": record.platform,
                    "deliveryLaneId": record.deliveryLaneId,
                    "format": record.format,
                    "artifactPath": record.artifactPath,
                    "artifactStatus": record.artifactStatus,
                    "publishStatus": record.publishStatus,
                    "metadataStatus": record.metadataStatus,
                    "uploadJobKind": record.uploadJobKind,
                    "uploadJobStatus": record.uploadJobStatus,
                    "destinationGuidance": publishDestinationGuidance(for: record),
                    "bundledDryRunWorkerFilename": bundledWorker.filename,
                    "bundledDryRunWorkerPath": bundledWorker.path,
                    "bundledDryRunWorkerExists": bundledWorker.exists,
                    "bundledDryRunWorkerExecutableReady": bundledWorker.executable,
                    "bundledDryRunCommand": bundledWorker.command(platform: record.platform, laneId: record.deliveryLaneId),
                    "publicURL": record.publicURL,
                    "providerReceiptId": record.providerReceiptId
                ] as [String: Any]
            }
        ]
    }

    private func publishDestinationCatalogPayload() -> [String: Any] {
        let fileURL = URL(fileURLWithPath: #filePath)
        let sourceRoot = fileURL
            .deletingLastPathComponent()
            .deletingLastPathComponent()
            .deletingLastPathComponent()
        let cwdRoot = URL(fileURLWithPath: FileManager.default.currentDirectoryPath)
        let candidates = [
            sourceRoot.appendingPathComponent("docs").appendingPathComponent("quipslystudio-publish-destinations.json"),
            cwdRoot.appendingPathComponent("docs").appendingPathComponent("quipslystudio-publish-destinations.json"),
            Bundle.main.resourceURL?.appendingPathComponent("quipslystudio-publish-destinations.json")
        ].compactMap { $0 }

        for url in candidates {
            guard
                let data = try? Data(contentsOf: url),
                let object = try? JSONSerialization.jsonObject(with: data),
                let payload = object as? [String: Any]
            else {
                continue
            }
            return payload
        }

        return [
            "model": "quipslystudio-publish-destinations",
            "version": "missing",
            "status": "catalog-missing",
            "checkedPaths": candidates.map(\.path),
            "truth": "Publishing destinations consume exported artifacts and metadata packets. Source media remains untouched."
        ]
    }

    private func publishDestinationGuidance(for record: PublishReceiptRecord) -> [String: Any] {
        publishDestinationGuidance(
            platform: record.platform,
            deliveryLaneId: record.deliveryLaneId,
            format: record.format
        )
    }

    private func publishDestinationGuidance(
        platform: String,
        deliveryLaneId: String,
        format: String
    ) -> [String: Any] {
        let catalog = publishDestinationCatalogPayload()
        let destinations = catalog["destinations"] as? [[String: Any]] ?? []
        let destinationId = publishDestinationId(
            platform: platform,
            deliveryLaneId: deliveryLaneId,
            format: format
        )
        let destination = destinations.first { destination in
            (destination["id"] as? String) == destinationId
        } ?? destinations.first { destination in
            normalizedPlatformName(destination["platform"] as? String ?? "") == normalizedPlatformName(platform)
        }

        guard let destination else {
            return [
                "status": "destination-guidance-missing",
                "destinationId": destinationId,
                "platform": platform,
                "nextAction": "Use the publish destination catalog before upload or receipt capture."
            ]
        }

        return [
            "destinationId": destination["id"] ?? destinationId,
            "label": destination["label"] ?? platform,
            "preferredFormat": destination["preferredFormat"] ?? "",
            "requires": destination["requires"] ?? [],
            "niceToHave": destination["niceToHave"] ?? [],
            "humanChecklist": destination["humanChecklist"] ?? [],
            "agentGuidance": destination["agentGuidance"] ?? "",
            "catalogVersion": catalog["version"] ?? ""
        ]
    }

    private func publishDestinationId(for record: PublishReceiptRecord) -> String {
        publishDestinationId(
            platform: record.platform,
            deliveryLaneId: record.deliveryLaneId,
            format: record.format
        )
    }

    private func publishDestinationId(
        platform rawPlatform: String,
        deliveryLaneId: String,
        format rawFormat: String
    ) -> String {
        let platform = normalizedPlatformName(rawPlatform)
        let lane = deliveryLaneId.lowercased()
        let format = rawFormat.lowercased()

        if platform.contains("instagram") {
            return "instagram_reel"
        }
        if platform.contains("facebook") {
            return "facebook_reel"
        }
        if platform.contains("linkedin") {
            return "linkedin_video"
        }
        if platform.contains("youtube shorts") || (platform.contains("youtube") && (lane.contains("short") || format.contains("9:16"))) {
            return "youtube_short"
        }
        if platform.contains("youtube") {
            return "youtube_episode"
        }
        if platform.contains("patreon") {
            return "patreon_episode"
        }
        if platform.contains("spotify") {
            return "spotify_podcast"
        }
        if platform.contains("apple") {
            return "apple_podcasts"
        }
        if format.contains("9:16") {
            return "youtube_short"
        }
        return platform.replacingOccurrences(of: " ", with: "_")
    }

    private func normalizedPlatformName(_ value: String) -> String {
        value
            .lowercased()
            .trimmingCharacters(in: .whitespacesAndNewlines)
            .replacingOccurrences(of: "-", with: " ")
            .replacingOccurrences(of: "_", with: " ")
    }

    private func writeJSONObject(_ object: [String: Any], to url: URL) throws {
        let data = try JSONSerialization.data(withJSONObject: object, options: [.prettyPrinted, .sortedKeys])
        try data.write(to: url, options: .atomic)
    }

    private func writeJSONStringOrWrappedText(_ text: String, fallbackKey: String, to url: URL) throws {
        let trimmed = text.trimmingCharacters(in: .whitespacesAndNewlines)
        if !trimmed.isEmpty,
           let data = trimmed.data(using: .utf8),
           JSONSerialization.isValidJSONObject((try? JSONSerialization.jsonObject(with: data)) as Any) {
            try data.write(to: url, options: .atomic)
        } else {
            try writeJSONObject([fallbackKey: text], to: url)
        }
    }

    private func publishReceiptChecklistMarkdown(_ record: PublishReceiptRecord) -> String {
        let bundledWorker = bundledPublishDryRunWorker(for: record.platform)
        let dryRunCommand = bundledWorker.command(platform: record.platform, laneId: record.deliveryLaneId)
        let destinationGuidance = publishDestinationGuidance(for: record)
        let destinationRequires = markdownBulletList(destinationGuidance["requires"])
        let destinationChecklist = markdownNumberedList(destinationGuidance["humanChecklist"])
        return """
        # \(record.platform) release checklist

        - Delivery lane: \(record.deliveryLaneId)
        - Format: \(record.format)
        - Artifact type: \(record.artifactType)
        - Artifact status: \(record.artifactStatus)
        - Artifact path: \(record.artifactPath.isEmpty ? "Not exported yet" : record.artifactPath)
        - Ship status: \(record.publishStatus)
        - Upload job: \(record.uploadJobKind.isEmpty ? "manual-platform-upload" : record.uploadJobKind)
        - Upload job status: \(record.uploadJobStatus)
        - Bundled dry-run worker: \(bundledWorker.filename.isEmpty ? "None" : bundledWorker.filename)
        - Bundled dry-run worker path: \(bundledWorker.path.isEmpty ? "Not available" : bundledWorker.path)
        - Bundled dry-run worker executable: \(bundledWorker.executable ? "yes" : "no")

        ## Destination guidance

        - Destination: \(destinationGuidance["label"] as? String ?? record.platform)
        - Destination id: \(destinationGuidance["destinationId"] as? String ?? publishDestinationId(for: record))
        - Preferred format: \(destinationGuidance["preferredFormat"] as? String ?? record.format)
        - Agent guidance: \(destinationGuidance["agentGuidance"] as? String ?? "Use the publish destination catalog before upload.")

        Required fields:

        \(destinationRequires.isEmpty ? "- See publish destination catalog." : destinationRequires)

        Platform checklist:

        \(destinationChecklist.isEmpty ? "1. Review destination catalog guidance." : destinationChecklist)

        ## Dry-run proof

        \(dryRunCommand.isEmpty ? "No bundled dry-run command is available for this platform record." : "Run this before real upload work:\n\n```bash\n\(dryRunCommand)\n```")

        Dry-run proof validates the artifact, copy, metadata, and receipt contract.
        It must not upload, schedule, publish, create a provider receipt, or create
        a public URL.

        ## Platform copy

        Title:
        \(record.title)

        Description:
        \(record.description)

        ## Receipt

        - Public URL: \(record.publicURL.isEmpty ? "Not saved yet" : record.publicURL)
        - Provider receipt/id: \(record.providerReceiptId.isEmpty ? "Not saved yet" : record.providerReceiptId)
        - Notes: \(record.notes.isEmpty ? "None" : record.notes)

        ## Operator steps

        1. Review the exported artifact path above.
        2. Run the dry-run proof if a bundled worker is available.
        3. Copy the title and description into \(record.platform).
        4. Upload or schedule the artifact manually until direct API integration is wired.
        5. Save the public URL, provider receipt/id, and notes back into Quipsly.
        6. Keep this checklist with the release folder for handoff/debugging.
        """
    }

    private func markdownBulletList(_ rawItems: Any?) -> String {
        let items = rawItems as? [String] ?? []
        return items.map { "- \($0)" }.joined(separator: "\n")
    }

    private func markdownNumberedList(_ rawItems: Any?) -> String {
        let items = rawItems as? [String] ?? []
        return items.enumerated().map { index, item in
            "\(index + 1). \(item)"
        }.joined(separator: "\n")
    }

