    private func currentPublicationReleaseFolderPath() -> String {
        let fileManager = FileManager.default
        let candidates = [
            fullReleaseOutputPath,
            publishUploadBundleOutputPath,
            publishPacketOutputPath,
            publicationCockpitOutputPath,
            publicationReceiptLogOutputPath,
            socialMasterQueueOutputPath,
            podcastReadyPacketOutputPath,
            podcastPacketOutputPath
        ]
        .map { $0.trimmingCharacters(in: .whitespacesAndNewlines) }
        .filter { !$0.isEmpty }

        for path in candidates {
            var isDirectory: ObjCBool = false
            if fileManager.fileExists(atPath: path, isDirectory: &isDirectory) {
                if isDirectory.boolValue {
                    return path
                }
                return URL(fileURLWithPath: path).deletingLastPathComponent().path
            }
        }

        return ""
    }

