    private func copySocialMasterQueueCandidateSummary() {
        guard let candidate = selectedSocialMasterQueueCandidate() else {
            lastMediaAction = "Copy social candidate blocked: no candidate selected"
            updateAgentState()
            return
        }
        let summary = """
        Social candidate #\(candidate["rank"] ?? "?"): \(candidate["title"] ?? "Untitled short")
        Hook: \(candidate["hook"] ?? "")
        Duration: \(candidate["duration"] ?? "?")s
        Platforms: \(candidate["platforms"] ?? "")
        Clip: \(candidate["clipPath"] ?? "")
        Thumbnail: \(candidate["thumbnailPath"] ?? "")
        Captions: \(candidate["captionSrtPath"] ?? "")
        Platform copy: \(candidate["platformCopyPath"] ?? "")
        Human check: \(candidate["humanCheck"] ?? "Watch once before posting.")
        """
        #if os(macOS)
        NSPasteboard.general.clearContents()
        NSPasteboard.general.setString(summary, forType: .string)
        lastMediaAction = "Copied social candidate handoff"
        #else
        lastMediaAction = summary
        #endif
        updateAgentState()
    }

