            lastMediaAction = "Copied social platform copy text"
            #else
            lastMediaAction = text
            #endif
        } catch {
            lastMediaAction = "Copy social platform copy failed: \(error.localizedDescription)"
        }
        updateAgentState()
    }

    private func copySelectedSocialPostingPacketJSON() {
        let packet = selectedSocialMasterQueuePostingPacketPayload()
        guard JSONSerialization.isValidJSONObject(packet) else {
            lastMediaAction = "Copy social posting packet blocked: packet could not be serialized"
            updateAgentState()
            return
        }

        do {
            let data = try JSONSerialization.data(withJSONObject: packet, options: [.prettyPrinted, .sortedKeys])
            let text = String(data: data, encoding: .utf8) ?? "{}"
            #if os(macOS)
            NSPasteboard.general.clearContents()
            NSPasteboard.general.setString(text, forType: .string)
            lastMediaAction = "Copied selected social posting packet JSON"
            #else
            lastMediaAction = text
            #endif
        } catch {
            lastMediaAction = "Copy social posting packet failed: \(error.localizedDescription)"
        }
        updateAgentState()
    }

    private func socialMasterQueueSelectedPlatformCopyPreview(maxCharacters: Int) -> String {
        let path = socialMasterQueueSelectedPath("platformCopyPath")
        guard !path.isEmpty else {
            return "No platform-copy file is attached yet."
        }

        do {
            let text = try String(contentsOfFile: path, encoding: .utf8)
                .trimmingCharacters(in: .whitespacesAndNewlines)
            guard !text.isEmpty else {
                return "Platform-copy file is empty."
            }
            if text.count <= maxCharacters {
                return text
            }
            return "\(String(text.prefix(maxCharacters)))..."
        } catch {
            return "Could not read platform-copy file: \(error.localizedDescription)"
        }
    }

    private func handleSocialMasterQueueArtifactCommand(action: String?, key: String?) {
        let normalizedAction = (action ?? "").trimmingCharacters(in: .whitespacesAndNewlines).lowercased()
        let normalizedKey = (key ?? "").trimmingCharacters(in: .whitespacesAndNewlines)
        let artifactKey = normalizedKey.isEmpty ? "clipPath" : normalizedKey
        let label = socialMasterQueueArtifactLabel(for: artifactKey)

        switch normalizedAction {
        case "open":
            openSocialMasterQueueCandidateArtifact(key: artifactKey, label: label)
        case "reveal":
            revealSocialMasterQueueCandidateArtifact(key: artifactKey, label: label)
        case "copy_handoff":
            copySocialMasterQueueCandidateSummary()
        case "copy_platform_copy":
            copySocialMasterQueueCandidatePlatformCopy()
        default:
            lastMediaAction = "Social candidate artifact action blocked: \(normalizedAction.isEmpty ? "missing action" : normalizedAction)"
            updateAgentState()
        }
    }

    private func socialMasterQueueArtifactLabel(for key: String) -> String {
        switch key {
        case "clipPath":
            return "clip"
        case "thumbnailPath":
            return "thumbnail"
        case "captionSrtPath":
            return "captions"
        case "platformCopyPath":
            return "platform copy"
        default:
            return key
        }
    }

    private func socialMasterQueueSelectedPlatforms() -> [String] {
        guard let candidate = selectedSocialMasterQueueCandidate() else {
            return ["YouTube Shorts", "Instagram", "Facebook", "LinkedIn"]
        }
        let raw = (candidate["platforms"] ?? "").trimmingCharacters(in: .whitespacesAndNewlines)
        let values = raw
            .split(separator: ",")
            .map { String($0).trimmingCharacters(in: .whitespacesAndNewlines) }
            .filter { !$0.isEmpty }
        return values.isEmpty ? ["YouTube Shorts", "Instagram", "Facebook", "LinkedIn"] : values
    }

    private func socialMasterQueueSelectedReceiptId(platform: String? = nil) -> String {
        guard let candidate = selectedSocialMasterQueueCandidate() else { return "" }
        let selectedPlatform = (platform ?? socialMasterReceiptCapturePlatform).trimmingCharacters(in: .whitespacesAndNewlines)
        guard let key = socialMasterQueueReceiptCandidateKey(for: selectedPlatform) else {
            return ""
        }
        return candidate[key] ?? ""
    }

    private func socialMasterQueueReceiptCandidateKey(for platform: String) -> String? {
        switch platform.trimmingCharacters(in: .whitespacesAndNewlines).lowercased() {
        case "youtube shorts", "youtube", "shorts":
            return "youtubeShortsReceiptId"
        case "instagram", "instagram reels", "reels":
            return "instagramReceiptId"
        case "facebook", "facebook reels":
            return "facebookReceiptId"
        case "linkedin", "linked in":
            return "linkedinReceiptId"
        default:
            return nil
        }
    }

    private func socialMasterQueueSelectedReceiptRecord(platform: String) -> PublishReceiptRecord? {
        let receiptId = socialMasterQueueSelectedReceiptId(platform: platform)
            .trimmingCharacters(in: .whitespacesAndNewlines)
        guard !receiptId.isEmpty,
              let sequence = projectStore.activeSequence else {
            return nil
        }
        return sequence.publishReceipts.first { record in
            record.id.uuidString.caseInsensitiveCompare(receiptId) == .orderedSame
        }
    }

    private func socialMasterQueuePlatformCompletionRows() -> [[String: Any]] {
        guard let candidate = selectedSocialMasterQueueCandidate() else {
            return []
        }

        return socialMasterQueueSelectedPlatforms().map { platform -> [String: Any] in
            let receiptId = socialMasterQueueSelectedReceiptId(platform: platform)
            let record = socialMasterQueueSelectedReceiptRecord(platform: platform)
            let proofCaptured = record.map(publishRecordReceiptCaptured) ?? false
            let publishStatus = record?.publishStatus ?? ""
            let publicURL = record?.publicURL ?? ""
            let providerReceiptId = record?.providerReceiptId ?? ""
            let status: String
            let nextAction: String

            if receiptId.isEmpty {
                status = "needs receipt row"
                nextAction = "Create receipt rows before posting."
            } else if record == nil {
                status = "receipt row missing from ledger"
                nextAction = "Promote receipt rows again or reload the selected queue."
            } else if proofCaptured {
                switch publishStatus {
                case "published":
                    status = "published proof captured"
                case "scheduled":
                    status = "scheduled proof captured"
                case "uploaded":
                    status = "uploaded proof captured"
                default:
                    status = "proof captured"
                }
                nextAction = "No action needed unless the platform URL changes."
            } else if publishStatus == "needs-export" {
                status = "needs export before posting"
                nextAction = "Regenerate or locate the derivative short before posting."
            } else {
                status = "ready to post or schedule"
                nextAction = "Post/schedule manually, then capture the public/scheduled URL or provider receipt."
            }

            return [
                "platform": platform,
                "candidateRank": candidate["rank"] ?? "",
                "title": candidate["title"] ?? "",
                "receiptId": receiptId,
                "receiptRowFound": record != nil,
                "status": status,
                "nextAction": nextAction,
                "publishStatus": publishStatus,
                "uploadJobStatus": record?.uploadJobStatus ?? "",
                "publicURL": publicURL,
                "providerReceiptId": providerReceiptId,
                "proofCaptured": proofCaptured,
                "readyForCapture": !receiptId.isEmpty,
                "captureCommand": receiptId.isEmpty
                    ? "script/agentctl.sh social-master-queue-promote-receipts"
                    : "script/agentctl.sh social-master-queue-receipt \(candidate["rank"] ?? "") \"\(platform)\" published <public-or-scheduled-url> <provider-id> \"manual receipt\""
            ]
        }
    }

    private func selectedSocialMasterQueuePlatformCompletionPayload() -> [String: Any] {
        guard let candidate = selectedSocialMasterQueueCandidate() else {
            return [
                "model": "quipsly-selected-social-platform-completion",
                "version": "2026-06-18.social-platform-completion.v1",
                "status": "no-candidate-selected",
                "completedPlatformCount": 0,
                "platformCount": 0,
                "platforms": []
            ]
        }

        let rows = socialMasterQueuePlatformCompletionRows()
        let completedCount = rows.filter { ($0["proofCaptured"] as? Bool) == true }.count
        let platformCount = rows.count

        return [
            "model": "quipsly-selected-social-platform-completion",
            "version": "2026-06-18.social-platform-completion.v1",
            "status": platformCount > 0 && completedCount == platformCount ? "all-platform-proof-captured" : "needs-platform-proof",
            "completedPlatformCount": completedCount,
            "platformCount": platformCount,
            "selectedCandidateRank": candidate["rank"] ?? "",
            "title": candidate["title"] ?? "",
            "platforms": rows,
            "proofRule": "Each platform is complete only after its receipt row has a real public/scheduled URL or provider receipt id.",
            "copyReceiptCommandsCommand": "script/agentctl.sh social-master-copy-receipt-commands"
        ]
    }

    private func selectSocialMasterReceiptPlatform(platform: String?, status: String?) {
        guard selectedSocialMasterQueueCandidate() != nil else {
            lastMediaAction = "Select social receipt platform blocked: no selected candidate"
            updateAgentState()
            return
        }

        let requestedPlatform = (platform ?? "").trimmingCharacters(in: .whitespacesAndNewlines)
        let availablePlatforms = socialMasterQueueSelectedPlatforms()
        let matchedPlatform = availablePlatforms.first {
            $0.caseInsensitiveCompare(requestedPlatform) == .orderedSame
        } ?? availablePlatforms.first { candidate in
            candidate.lowercased().contains(requestedPlatform.lowercased())
                || requestedPlatform.lowercased().contains(candidate.lowercased())
        }

        guard let matchedPlatform else {
            lastMediaAction = "Select social receipt platform blocked: \(requestedPlatform.isEmpty ? "missing platform" : requestedPlatform) is not in this candidate"
            updateAgentState()
            return
        }

        let requestedStatus = (status ?? "").trimmingCharacters(in: .whitespacesAndNewlines)
        socialMasterReceiptCapturePlatform = matchedPlatform
        if !requestedStatus.isEmpty {
            socialMasterReceiptCaptureStatus = requestedStatus
        } else if socialMasterReceiptCaptureStatus.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty {
            socialMasterReceiptCaptureStatus = "published"
        }
        lastMediaAction = "Selected \(matchedPlatform) for social receipt capture"
        updateAgentState()
    }

    private func nextIncompleteSocialPostingPlatform() -> String? {
        socialMasterQueuePlatformCompletionRows().first { row in
            (row["proofCaptured"] as? Bool) != true
        }?["platform"] as? String
    }

    private func selectNextIncompleteSocialPostingPlatform() {
        guard let platform = nextIncompleteSocialPostingPlatform() else {
            lastMediaAction = "Posting session complete: no incomplete social platform remains for the selected candidate"
            updateAgentState()
            return
        }
        selectSocialMasterReceiptPlatform(platform: platform, status: socialMasterReceiptCaptureStatus.isEmpty ? "published" : socialMasterReceiptCaptureStatus)
        lastMediaAction = "Posting session selected next platform: \(platform)"
        updateAgentState()
    }

    private func promoteSelectedSocialMasterQueueCandidateToReceipts() {
        guard var sequence = projectStore.activeSequence else {
            lastMediaAction = "Social receipt promotion blocked: no loaded episode session"
            updateAgentState()
            return
        }
        guard let candidate = selectedSocialMasterQueueCandidate() else {
            lastMediaAction = "Social receipt promotion blocked: no selected candidate"
            updateAgentState()
            return
        }

        let rank = (candidate["rank"] ?? selectedSocialMasterQueueRank).trimmingCharacters(in: .whitespacesAndNewlines)
        let sourceShortClipId = (candidate["sourceShortClipId"] ?? candidate["shortClipId"] ?? "").trimmingCharacters(in: .whitespacesAndNewlines)
        let deliveryLaneId = sourceShortClipId.isEmpty
            ? "social-master-queue/\(rank.isEmpty ? "selected" : rank)"
            : "social-short-clips/\(sourceShortClipId)"
        let artifactPath = (candidate["clipPath"] ?? "").trimmingCharacters(in: .whitespacesAndNewlines)
        let artifactReady = !artifactPath.isEmpty && FileManager.default.fileExists(atPath: artifactPath)
        let artifactStatus = artifactReady ? "exported" : "missing"
        let publishStatus = artifactReady ? "ready-to-upload" : "needs-export"
        let title = (candidate["title"] ?? "Untitled social short").trimmingCharacters(in: .whitespacesAndNewlines)
        let hook = (candidate["hook"] ?? "").trimmingCharacters(in: .whitespacesAndNewlines)
        let description = hook.isEmpty ? "Short-form video release draft from \(sequence.title)." : hook
        let captionPath = (candidate["captionSrtPath"] ?? "").trimmingCharacters(in: .whitespacesAndNewlines)
        let platformCopyPath = (candidate["platformCopyPath"] ?? "").trimmingCharacters(in: .whitespacesAndNewlines)
        let thumbnailPath = (candidate["thumbnailPath"] ?? "").trimmingCharacters(in: .whitespacesAndNewlines)
        let now = Date()
        let terminalStatuses = Set(["uploaded", "scheduled", "published"])
        var promotedByPlatform: [String: String] = [:]
        var nextReceipts = sequence.publishReceipts

        for platform in socialMasterQueueSelectedPlatforms() {
            let key = publishReceiptKey(platform, deliveryLaneId, artifactPath)
            let existingIndex = nextReceipts.firstIndex {
                publishReceiptKey($0.platform, $0.deliveryLaneId, $0.artifactPath) == key
            }

            let metadataJson = stableJSONString([
                "model": "quipsly-social-master-receipt-promotion",
                "version": "2026-06-18.social-master-receipt-promotion.v1",
                "platform": platform,
                "deliveryLaneId": deliveryLaneId,
                "candidateRank": rank,
                "sourceShortClipId": sourceShortClipId,
                "sourcePack": candidate["sourcePack"] ?? "",
                "sourceManifest": candidate["sourceManifest"] ?? "",
                "title": title,
                "description": description,
                "durationSeconds": candidate["duration"] ?? "",
                "clipPath": artifactPath,
                "thumbnailPath": thumbnailPath,
                "captionSrtPath": captionPath,
                "platformCopyPath": platformCopyPath,
                "artifactStatus": artifactStatus,
                "format": "9:16",
                "humanReviewRequired": true,
                "sourcePolicy": "receipt row references derivative social artifact only; source media and edit decisions stay untouched"
            ])
            let uploadJobJson = stableJSONString([
                "kind": defaultUploadJobKind(platform: platform),
                "platform": platform,
                "deliveryLaneId": deliveryLaneId,
                "candidateRank": rank,
                "artifactPath": artifactPath,
                "artifactStatus": artifactStatus,
                "format": "9:16",
                "status": artifactReady ? "integration-needed" : "needs-export",
                "manualUploadReady": artifactReady,
                "directUploadReady": false,
                "receiptWritesTo": "publishReceipts.providerReceiptId publicURL receiptJson publishedAt",
                "proofRule": "Do not mark uploaded, scheduled, or published until a real public/scheduled URL or provider receipt is captured."
            ])

            if let existingIndex {
                if !terminalStatuses.contains(nextReceipts[existingIndex].publishStatus) {
                    nextReceipts[existingIndex].artifactType = "Short MP4 clip"
                    nextReceipts[existingIndex].format = "9:16"
                    nextReceipts[existingIndex].artifactPath = artifactPath
                    nextReceipts[existingIndex].artifactStatus = artifactStatus
                    nextReceipts[existingIndex].publishStatus = publishStatus
                    nextReceipts[existingIndex].title = title
                    nextReceipts[existingIndex].description = description
                    nextReceipts[existingIndex].metadataJson = metadataJson
                    nextReceipts[existingIndex].metadataStatus = "draft"
                    nextReceipts[existingIndex].uploadJobKind = defaultUploadJobKind(platform: platform)
                    nextReceipts[existingIndex].uploadJobStatus = artifactReady ? "integration-needed" : "needs-export"
                    nextReceipts[existingIndex].uploadJobJson = uploadJobJson
                    nextReceipts[existingIndex].notes = "Receipt row promoted from selected social posting candidate. Capture a real URL/provider receipt after manual upload or scheduling."
                    nextReceipts[existingIndex].updatedAt = now
                }
                promotedByPlatform[platform] = nextReceipts[existingIndex].id.uuidString
            } else {
                let record = PublishReceiptRecord(
                    platform: platform,
                    deliveryLaneId: deliveryLaneId,
                    artifactType: "Short MP4 clip",
                    format: "9:16",
                    artifactPath: artifactPath,
                    artifactStatus: artifactStatus,
                    publishStatus: publishStatus,
                    title: title,
                    description: description,
                    metadataJson: metadataJson,
                    metadataStatus: "draft",
                    uploadJobKind: defaultUploadJobKind(platform: platform),
                    uploadJobStatus: artifactReady ? "integration-needed" : "needs-export",
                    uploadJobJson: uploadJobJson,
                    notes: "Receipt row promoted from selected social posting candidate. Capture a real URL/provider receipt after manual upload or scheduling.",
                    createdAt: now,
                    updatedAt: now
                )
                nextReceipts.append(record)
                promotedByPlatform[platform] = record.id.uuidString
            }
        }

        sequence.publishReceipts = nextReceipts.sorted {
            if $0.deliveryLaneId == $1.deliveryLaneId {
                return $0.platform < $1.platform
            }
            return $0.deliveryLaneId < $1.deliveryLaneId
        }

        if let candidateIndex = socialMasterQueueCandidatePreview.firstIndex(where: { candidate in
            let candidateRank = (candidate["rank"] ?? "").trimmingCharacters(in: .whitespacesAndNewlines)
            return !rank.isEmpty && candidateRank == rank
        }) ?? (rank.isEmpty ? socialMasterQueueCandidatePreview.indices.first : nil) {
            var updatedCandidate = socialMasterQueueCandidatePreview[candidateIndex]
            for (platform, receiptId) in promotedByPlatform {
                if let key = socialMasterQueueReceiptCandidateKey(for: platform) {
                    updatedCandidate[key] = receiptId
                }
            }
            updatedCandidate["platformReceiptCount"] = "\(promotedByPlatform.count)"
            updatedCandidate["receiptPromotionStatus"] = artifactReady ? "ready-for-receipt-capture-after-posting" : "needs-export-before-posting"
            socialMasterQueueCandidatePreview[candidateIndex] = updatedCandidate
            if selectedSocialMasterQueueRank.isEmpty {
                selectedSocialMasterQueueRank = updatedCandidate["rank"] ?? rank
            }
        }

        projectStore.updateSequence(sequence, undoManager: nil, actionName: "Promote Social Receipt Rows")
        scheduleAutosave(reason: "promoted social receipt rows")
        lastMediaAction = "Promoted selected social candidate to \(promotedByPlatform.count) receipt row(s)"
        updateAgentState()
    }

