    private func captureSocialMasterQueueReceiptsFromBatchText() {
        captureSocialMasterQueueReceiptsFromBatchRows(socialMasterReceiptBatchText)
    }

    private func captureSocialMasterQueueReceiptsFromBatchRows(_ rowsText: String?) {
        guard selectedSocialMasterQueueCandidate() != nil else {
            lastMediaAction = "Social receipt batch blocked: no selected candidate"
            updateAgentState()
            return
        }

        let lines = (rowsText ?? "").components(separatedBy: .newlines)
        var applied = 0
        var skipped = 0
        var skippedReasons: [String] = []

        for rawLine in lines {
            let line = rawLine.trimmingCharacters(in: .whitespacesAndNewlines)
            guard !line.isEmpty, !line.hasPrefix("#") else { continue }

            let lower = line.lowercased()
            if lower.hasPrefix("platform,") || lower.hasPrefix("platform\t") || lower.hasPrefix("platform|") {
                continue
            }

            let separator: Character
            if line.contains("\t") {
                separator = "\t"
            } else if line.contains("|") {
                separator = "|"
            } else {
                separator = ","
            }

            let parts = line.split(separator: separator, omittingEmptySubsequences: false)
                .map { String($0).trimmingCharacters(in: .whitespacesAndNewlines) }
            guard parts.count >= 3 else {
                skipped += 1
                skippedReasons.append("malformed row")
                continue
            }

            let platform = parts[0]
            let status = parts[1].isEmpty ? "published" : parts[1]
            let publicURL = parts[2]
            guard publicURL.lowercased().hasPrefix("https://") || publicURL.lowercased().hasPrefix("http://") else {
                skipped += 1
                skippedReasons.append("\(platform): missing real URL")
                continue
            }

            let providerId = parts.count > 3 ? parts[3] : ""
            let notes = parts.count > 4
                ? parts.dropFirst(4).joined(separator: " ")
                : "Manual batch receipt captured from the social master queue."
            let receiptId = socialMasterQueueSelectedReceiptId(platform: platform)
            guard !receiptId.isEmpty else {
                skipped += 1
                skippedReasons.append("\(platform): create receipt row first")
                continue
            }

            captureSocialMasterQueueReceiptFromAgent(values: [
                "rank": selectedSocialMasterQueueRank,
                "platform": platform,
                "status": status,
                "public_url": publicURL,
                "provider_receipt_id": providerId,
                "notes": notes
            ])
            applied += 1
        }

        if applied > 0 {
            socialMasterReceiptBatchText = ""
        }
        let suffix = skippedReasons.prefix(3).joined(separator: "; ")
        lastMediaAction = "Applied \(applied) social receipt batch row(s); skipped \(skipped)\(suffix.isEmpty ? "" : " - \(suffix)")"
        updateAgentState()
    }

    private func captureSocialMasterQueueReceiptFromAgent(values: [String: String]) {
        if let rank = values["rank"], !rank.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty {
            selectedSocialMasterQueueRank = rank.trimmingCharacters(in: .whitespacesAndNewlines)
        }
        guard let candidate = selectedSocialMasterQueueCandidate() else {
            lastMediaAction = "Social master receipt capture blocked: no candidate selected"
            updateAgentState()
            return
        }
        let platform = (values["platform"] ?? socialMasterReceiptCapturePlatform)
            .trimmingCharacters(in: .whitespacesAndNewlines)
        let receiptId = socialMasterQueueSelectedReceiptId(platform: platform)
        guard !receiptId.isEmpty else {
            lastMediaAction = "Social master receipt capture blocked: selected candidate has no \(platform.isEmpty ? "platform" : platform) receipt id"
            updateAgentState()
            return
        }
        let publicURL = (values["public_url"] ?? values["url"] ?? values["publicURL"] ?? socialMasterReceiptCaptureURL)
            .trimmingCharacters(in: .whitespacesAndNewlines)
        guard !publicURL.isEmpty else {
            lastMediaAction = "Social master receipt capture blocked: paste a public or scheduled URL first"
            updateAgentState()
            return
        }
        let status = (values["status"] ?? socialMasterReceiptCaptureStatus)
            .trimmingCharacters(in: .whitespacesAndNewlines)
        let providerId = (values["provider_receipt_id"] ?? values["provider_id"] ?? socialMasterReceiptCaptureProviderId)
            .trimmingCharacters(in: .whitespacesAndNewlines)
        var updateValues: [String: String] = [
            "id": receiptId,
            "status": status.isEmpty ? "published" : status,
            "upload_job_status": uploadJobStatusForManualReceipt(status.isEmpty ? "published" : status),
            "public_url": publicURL,
            "receipt_json": stableJSONString([
                "model": "quipsly-social-master-queue-receipt",
                "version": "2026-06-17.social-master-receipt.v1",
                "candidateRank": candidate["rank"] ?? "",
                "sourcePack": candidate["sourcePack"] ?? "",
                "sourceManifest": candidate["sourceManifest"] ?? "",
                "platform": platform,
                "title": candidate["title"] ?? "",
                "clipPath": candidate["clipPath"] ?? "",
                "platformCopyPath": candidate["platformCopyPath"] ?? "",
                "captionSrtPath": candidate["captionSrtPath"] ?? "",
                "publicURL": publicURL,
                "status": status.isEmpty ? "published" : status,
                "capturedAt": ISO8601DateFormatter().string(from: Date()),
                "captureMethod": "quipsly-studio-social-master-queue"
            ]),
            "notes": values["notes"] ?? "Manual receipt captured from the social master queue."
        ]
        if !providerId.isEmpty {
            updateValues["provider_receipt_id"] = providerId
        }
        updatePublishReceiptFromAgent(values: updateValues)
        socialMasterReceiptCaptureURL = ""
        socialMasterReceiptCaptureProviderId = ""
    }

    private func socialMasterQueueReceiptCommandForSelectedCandidate(
        includeFilledValues: Bool,
        platform: String? = nil,
        status: String? = nil
    ) -> String {
        let rank = selectedSocialMasterQueueRank.trimmingCharacters(in: .whitespacesAndNewlines)
        let resolvedPlatform = (platform ?? socialMasterReceiptCapturePlatform)
            .trimmingCharacters(in: .whitespacesAndNewlines)
        let resolvedStatus = (status ?? socialMasterReceiptCaptureStatus)
            .trimmingCharacters(in: .whitespacesAndNewlines)
        let publicURL = socialMasterReceiptCaptureURL.trimmingCharacters(in: .whitespacesAndNewlines)
        let providerId = socialMasterReceiptCaptureProviderId.trimmingCharacters(in: .whitespacesAndNewlines)
        let rankArg = rank.isEmpty ? "<rank>" : shellQuote(rank)
        let platformArg = shellQuote(resolvedPlatform.isEmpty ? "YouTube Shorts" : resolvedPlatform)
        let statusArg = shellQuote(resolvedStatus.isEmpty ? "published" : resolvedStatus)
        let publicURLArg = includeFilledValues && !publicURL.isEmpty
            ? shellQuote(publicURL)
            : "<public-or-scheduled-url>"
        let providerIdArg = includeFilledValues && !providerId.isEmpty
            ? shellQuote(providerId)
            : "<provider-id>"
        return "script/agentctl.sh social-master-queue-receipt \(rankArg) \(platformArg) \(statusArg) \(publicURLArg) \(providerIdArg) \(shellQuote("manual receipt"))"
    }

    private func copySocialMasterQueueReceiptCommand() {
        let receiptId = socialMasterQueueSelectedReceiptId()
        guard !receiptId.isEmpty else {
            lastMediaAction = "Copy social receipt command blocked: selected candidate has no receipt id"
            updateAgentState()
            return
        }
        let hasPublicURL = !socialMasterReceiptCaptureURL.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty
        let command = socialMasterQueueReceiptCommandForSelectedCandidate(includeFilledValues: hasPublicURL)
        #if os(macOS)
        NSPasteboard.general.clearContents()
        NSPasteboard.general.setString(command, forType: .string)
        lastMediaAction = hasPublicURL
            ? "Copied filled social receipt command"
            : "Copied social receipt template command"
        #else
        lastMediaAction = command
        #endif
        updateAgentState()
    }

