    private func generateSocialMasterQueuePostingRunPacket() {
        guard let candidate = selectedSocialMasterQueueCandidate() else {
            lastMediaAction = "Social posting run packet blocked: no selected candidate"
            updateAgentState()
            return
        }

        let session = selectedSocialMasterQueuePostingSessionPayload()
        let title = (candidate["title"] ?? "selected social candidate")
            .trimmingCharacters(in: .whitespacesAndNewlines)
        let rank = (candidate["rank"] ?? selectedSocialMasterQueueRank)
            .trimmingCharacters(in: .whitespacesAndNewlines)
        let safeTitle = sanitizedExportBasename(title.isEmpty ? "social-short" : title).lowercased()
        let safeRank = sanitizedExportBasename(rank.isEmpty ? "selected" : rank).lowercased()
        let outputRoot = defaultPublishPacketDirectory()
            .appendingPathComponent("SocialPostingRuns", isDirectory: true)
        let outputDirectory = outputRoot
            .appendingPathComponent("\(safeRank)-\(safeTitle)-posting-run", isDirectory: true)
        let platformQueue = session["platformQueue"] as? [[String: Any]] ?? []
        let clipPath = (session["clipPath"] as? String ?? candidate["clipPath"] ?? "")
            .trimmingCharacters(in: .whitespacesAndNewlines)
        let copyPath = (session["platformCopyPath"] as? String ?? candidate["platformCopyPath"] ?? "")
            .trimmingCharacters(in: .whitespacesAndNewlines)
        let captionPath = (session["captionSrtPath"] as? String ?? candidate["captionSrtPath"] ?? "")
            .trimmingCharacters(in: .whitespacesAndNewlines)
        let thumbnailPath = (session["thumbnailPath"] as? String ?? candidate["thumbnailPath"] ?? "")
            .trimmingCharacters(in: .whitespacesAndNewlines)

        do {
            try FileManager.default.createDirectory(at: outputDirectory, withIntermediateDirectories: true)
            let packetRows: [[String: Any]] = try platformQueue.map { row in
                let platform = row["platform"] as? String ?? ""
                let receiptCommand = socialMasterQueueReceiptCommandForSelectedCandidate(
                    includeFilledValues: false,
                    platform: platform
                )
                let batchRow = "\(platform.isEmpty ? "<platform>" : platform),published,<real-platform-url>,<provider-id>,manual receipt for \(title.isEmpty ? "selected short" : title)"
                let packetFilename = "\(sanitizedExportBasename(platform.isEmpty ? "platform" : platform).lowercased())-posting-packet.md"
                let packetURL = outputDirectory.appendingPathComponent(packetFilename)
                let text = [
                    "# \(platform.isEmpty ? "Platform" : platform) posting packet",
                    "",
                    "Candidate: \(rank.isEmpty ? "selected" : "#\(rank)") \(title.isEmpty ? "Untitled short" : title)",
                    "Platform status: \(row["status"] as? String ?? "needs-platform-proof")",
                    "Current platform: \((row["isCurrent"] as? Bool ?? false) ? "yes" : "no")",
                    "",
                    "## Artifacts",
                    "- Clip: \(clipPath.isEmpty ? "<missing clip path>" : clipPath)",
                    "- Platform copy: \(copyPath.isEmpty ? "<missing platform copy path>" : copyPath)",
                    "- Captions: \(captionPath.isEmpty ? "<missing caption path>" : captionPath)",
                    "- Thumbnail: \(thumbnailPath.isEmpty ? "<missing thumbnail path>" : thumbnailPath)",
                    "",
                    "## Steps",
                    "1. Watch the clip.",
                    "2. Open/review the platform copy.",
                    "3. Upload or schedule manually on \(platform.isEmpty ? "this platform" : platform).",
                    "4. Paste the real public/scheduled URL or provider receipt back into Quipsly.",
                    "",
                    "## Receipt command",
                    receiptCommand,
                    "",
                    "## Batch row template",
                    batchRow,
                    "",
                    "Proof rule: this packet is not proof. Completion requires a real platform URL or provider receipt."
                ].joined(separator: "\n")
                try text.write(to: packetURL, atomically: true, encoding: .utf8)
                return [
                    "platform": platform,
                    "packetPath": packetURL.path,
                    "status": row["status"] as? String ?? "",
                    "proofCaptured": row["proofCaptured"] as? Bool ?? false,
                    "receiptRowFound": row["receiptRowFound"] as? Bool ?? false,
                    "receiptCommand": receiptCommand,
                    "batchRowTemplate": batchRow
                ]
            }

            let startHereURL = outputDirectory.appendingPathComponent("START-HERE.md")
            let manifestURL = outputDirectory.appendingPathComponent("posting-run-manifest.json")
            let startHere = [
                "# Quipsly social posting run",
                "",
                "Candidate: \(rank.isEmpty ? "selected" : "#\(rank)") \(title.isEmpty ? "Untitled short" : title)",
                "",
                "This folder is an operator packet for manual posting/scheduling. It does not prove publication.",
                "",
                "## Source artifacts",
                "- Clip: \(clipPath.isEmpty ? "<missing clip path>" : clipPath)",
                "- Platform copy: \(copyPath.isEmpty ? "<missing platform copy path>" : copyPath)",
                "- Captions: \(captionPath.isEmpty ? "<missing caption path>" : captionPath)",
                "- Thumbnail: \(thumbnailPath.isEmpty ? "<missing thumbnail path>" : thumbnailPath)",
                "",
                "## Platform packets",
                packetRows.map { row in
                    let platform = (row["platform"] as? String ?? "").isEmpty ? "Platform" : (row["platform"] as? String ?? "Platform")
                    return "- \(platform): \(row["packetPath"] as? String ?? "")"
                }.joined(separator: "\n"),
                "",
                "Proof rule: capture a real public/scheduled URL or provider receipt in Quipsly after posting."
            ].joined(separator: "\n")
            try startHere.write(to: startHereURL, atomically: true, encoding: .utf8)

            let manifest: [String: Any] = [
                "model": "quipsly-social-posting-run-packet",
                "version": "2026-06-18.social-posting-run-packet.v1",
                "generatedAt": ISO8601DateFormatter().string(from: Date()),
                "candidateRank": rank,
                "title": title,
                "outputDirectory": outputDirectory.path,
                "startHerePath": startHereURL.path,
                "clipPath": clipPath,
                "platformCopyPath": copyPath,
                "captionSrtPath": captionPath,
                "thumbnailPath": thumbnailPath,
                "platformPackets": packetRows,
                "proofRule": "This packet is not proof. Completion requires a real public/scheduled URL or provider receipt."
            ]
            let data = try JSONSerialization.data(withJSONObject: manifest, options: [.prettyPrinted, .sortedKeys])
            try data.write(to: manifestURL, options: [.atomic])

            socialMasterPostingRunPacketPath = outputDirectory.path
            #if os(macOS)
            NSPasteboard.general.clearContents()
            NSPasteboard.general.setString(startHereURL.path, forType: .string)
            #endif
            lastMediaAction = "Generated social posting run packet: \(outputDirectory.path)"
        } catch {
            lastMediaAction = "Social posting run packet failed: \(error.localizedDescription)"
        }
        updateAgentState()
    }

