    private func generateDeliveryPacketForAgent(directoryPath: String?, basename: String?) {
        guard projectStore.activeSequence != nil else {
            deliveryPacketStatus = "blocked"
            deliveryPacketOutputPath = ""
            deliveryPacketErrorMessage = "Load an episode session before generating a delivery packet."
            deliveryPacketGeneratedAt = Date()
            lastMediaAction = "Delivery packet blocked: no loaded session"
            updateAgentState()
            return
        }

        let directory = (directoryPath ?? "").trimmingCharacters(in: .whitespacesAndNewlines)
        guard !directory.isEmpty else {
            deliveryPacketStatus = "blocked"
            deliveryPacketOutputPath = ""
            deliveryPacketErrorMessage = "Choose an output folder for the delivery packet JSON."
            deliveryPacketGeneratedAt = Date()
            lastMediaAction = "Delivery packet blocked: missing output folder"
            updateAgentState()
            return
        }

        deliveryPacketStatus = "generating"
        deliveryPacketOutputPath = ""
        deliveryPacketErrorMessage = ""
        deliveryPacketGeneratedAt = Date()

        do {
            let safeBase = sanitizedExportBasename(basename ?? "quipsly-delivery")
            let outputDirectory = URL(fileURLWithPath: directory, isDirectory: true)
            try FileManager.default.createDirectory(at: outputDirectory, withIntermediateDirectories: true)
            let outputURL = outputDirectory.appendingPathComponent("\(safeBase)-delivery-packet.json")
            var packet = deliveryPacketPayload(summary: mediaReadinessSummary())
            packet["status"] = "generated"
            packet["outputPath"] = outputURL.path
            packet["generatedAt"] = ISO8601DateFormatter().string(from: Date())
            let data = try JSONSerialization.data(withJSONObject: packet, options: [.prettyPrinted, .sortedKeys])
            try data.write(to: outputURL, options: [.atomic])

            deliveryPacketStatus = "generated"
            deliveryPacketOutputPath = outputURL.path
            deliveryPacketErrorMessage = ""
            deliveryPacketGeneratedAt = Date()
            lastMediaAction = "Generated delivery packet: \(outputURL.lastPathComponent)"
        } catch {
            deliveryPacketStatus = "failed"
            deliveryPacketOutputPath = ""
            deliveryPacketErrorMessage = error.localizedDescription
            deliveryPacketGeneratedAt = Date()
            lastMediaAction = "Delivery packet failed: \(error.localizedDescription)"
        }

        updateAgentState()
    }

    private func generateDeliveryPacketForHuman() {
        let baseDirectory = FileManager.default.homeDirectoryForCurrentUser
            .appendingPathComponent("Movies", isDirectory: true)
            .appendingPathComponent("QuipslyStudio", isDirectory: true)
            .appendingPathComponent("DeliveryPackets", isDirectory: true)
        generateDeliveryPacketForAgent(
            directoryPath: baseDirectory.path,
            basename: normalizedActiveSessionName().isEmpty ? "quipsly-delivery" : normalizedActiveSessionName()
        )
    }

