    private func mediaReadinessSummary() -> MediaReadinessSummary {
        guard let sequence = projectStore.activeSequence else {
            return MediaReadinessSummary(
                hasSequence: false,
                readyCount: 0,
                heldCount: 0,
                missingCount: 0,
                blockingCount: 0,
                videoProxyReadyCount: 0,
                videoBlockedCount: 0,
                audioReadyCount: 0,
                audioBlockedCount: 0,
                showDecisionCount: 0,
                skipDecisionCount: 0,
                rawVaultCount: 0,
                storageAccessNeededCount: 0,
                proxyBlockedCount: 0,
                ignoredCount: 0,
                detail: "Load an episode or import media to see source readiness."
            )
        }

        var ready = 0
        var held = 0
        var missing = 0
        var videoProxyReady = 0
        var videoBlocked = 0
        var audioReady = 0
        var audioBlocked = 0
        var showDecisions = 0
        var skipDecisions = 0
        var rawVaulted = 0
        var storageAccessNeeded = 0
        var proxyBlocked = 0
        var ignored = 0

        for lane in sequence.lanes {
            if lane.metadata?.ignoreForProduction == true {
                ignored += 1
                continue
            }

            let readiness = sourceReadiness(for: lane)
            if readiness.needsStorageAccess {
                storageAccessNeeded += 1
            }
            if readiness.isReady {
                ready += 1
            } else if readiness.label == "Missing source" {
                missing += 1
            } else {
                held += 1
            }

            if isSupportOnlyLane(lane) {
                if readiness.isReady {
                    audioReady += 1
                } else {
                    audioBlocked += 1
                }
            } else if readiness.label == "Proxy ready" {
                videoProxyReady += 1
            } else {
                videoBlocked += 1
            }

            if lane.metadata?.vaultRawPath?.isEmpty == false {
                rawVaulted += 1
            }

            if readiness.label.lowercased().contains("proxy blocked") {
                proxyBlocked += 1
            }

            showDecisions += lane.tags.filter { $0.type == .active }.count
            skipDecisions += lane.tags.filter { $0.type == .cut }.count
        }

        let blocking = held + missing
        let detail: String
        if sequence.lanes.isEmpty {
            detail = "No lanes yet. Import media or load a Premiere rescue packet."
        } else if rawVaulted > 0 {
            detail = "\(rawVaulted) lane(s) still point at raw vault media. Keep originals external and edit from proxies."
        } else if proxyBlocked > 0 {
            detail = "\(proxyBlocked) proxy job(s) are blocked. Grant external storage access or relink readable originals, then retry pending proxies."
        } else if storageAccessNeeded > 0 && blocking == 0 && videoBlocked == 0 {
            let heldSuffix = ignored > 0 ? " \(ignored) lane(s) are held for recovery and excluded from export." : ""
            detail = "All \(videoProxyReady) video lane(s) and \(audioReady) audio/context lane(s) are proxy-backed for preview and proxy export. Grant storage access only for relink, waveform-from-originals, or raw-source operations.\(heldSuffix)"
        } else if blocking == 0 && videoBlocked == 0 {
            let heldSuffix = ignored > 0 ? " \(ignored) lane(s) are held for recovery and excluded from export." : ""
            detail = "All \(videoProxyReady) video lane(s) and \(audioReady) audio/context lane(s) are proxy-backed for preview, and originals remain whole.\(heldSuffix)"
        } else if missing > 0 {
            if videoProxyReady > 0 || audioReady > 0 {
                detail = "\(videoProxyReady) video proxy lane(s) and \(audioReady) audio/context proxy lane(s) are usable now. \(missing) unresolved Premiere placeholder lane(s) still need whole-source recovery before final export."
            } else {
                detail = "\(missing) lane(s) are unresolved Premiere placeholders. Keep the whole lane visible, relink the original source if found, or attach a full-length proxy."
            }
        } else if videoBlocked > 0 {
            if videoProxyReady > 0 || audioReady > 0 {
                detail = "\(videoProxyReady) video proxy lane(s) and \(audioReady) audio/context proxy lane(s) are usable now. \(videoBlocked) video lane(s) still need generated proxies before final export."
            } else {
                detail = "\(videoBlocked) video lane(s) need generated proxies before editor playback. Do not fall back to raw originals."
            }
        } else if audioBlocked > 0 {
            detail = "\(audioBlocked) audio/context lane(s) need local audio proxies before production editing, waveform work, or sync review."
        } else {
            detail = "\(blocking) lane(s) are held. Local preview proxies are required before production editing."
        }

        return MediaReadinessSummary(
            hasSequence: true,
            readyCount: ready,
            heldCount: held,
            missingCount: missing,
            blockingCount: blocking,
            videoProxyReadyCount: videoProxyReady,
            videoBlockedCount: videoBlocked,
            audioReadyCount: audioReady,
            audioBlockedCount: audioBlocked,
            showDecisionCount: showDecisions,
            skipDecisionCount: skipDecisions,
            rawVaultCount: rawVaulted,
            storageAccessNeededCount: storageAccessNeeded,
            proxyBlockedCount: proxyBlocked,
            ignoredCount: ignored,
            detail: detail
        )
    }

    private func selectedDecision() -> (lane: VideoLane, tag: VideoTag)? {
        guard let laneId = selectedLaneId,
              let tagId = selectedTagId,
              let sequence = projectStore.activeSequence,
              let lane = sequence.lanes.first(where: { $0.id == laneId }),
              let tag = lane.tags.first(where: { $0.id == tagId }) else {
            return nil
        }

        return (lane, tag)
    }

    private func addSelectedDecisionToShortQueue(title requestedTitle: String?) {
        guard var sequence = projectStore.activeSequence else {
            lastMediaAction = "Short queue blocked: no active sequence"
            updateAgentState()
            return
        }

        guard let selected = selectedDecision() else {
            lastMediaAction = "Short queue blocked: select a SHOW decision first"
            updateAgentState()
            return
        }

        guard selected.tag.type == .active else {
            lastMediaAction = "Short queue blocked: selected decision is not a SHOW region"
            updateAgentState()
            return
        }

        let title = requestedTitle?.trimmingCharacters(in: .whitespacesAndNewlines)
        let clipTitle = (title?.isEmpty == false ? title! : defaultShortClipTitle(for: selected.lane, tag: selected.tag))
        let candidate = ShortClipCandidate(
            title: clipTitle,
            startTime: selected.tag.startTime,
            duration: selected.tag.duration,
            sourceLaneId: selected.lane.id,
            sourceTagId: selected.tag.id,
            notes: "Queued from selected SHOW decision over whole source lanes."
        )

        sequence.shortClipQueue.append(candidate)
        selectedShortClipId = candidate.id
        selectedLaneId = selected.lane.id
        selectedTagId = selected.tag.id
        playbackEngine.playbackFormat = .vertical9x16
        playbackEngine.scrub(to: sequenceStartTime(for: candidate, in: sequence))
        projectStore.updateSequence(sequence, undoManager: nil, actionName: "Queue Short Recipe")
        lastMediaAction = "Queued short recipe: \(clipTitle)"
        requestTimelineFocus(reason: "Focused selected short recipe on the Episode Trail Map")
        scheduleAutosave(reason: "queued short recipe")
        updateAgentState()
    }

    private func addSequenceRangeToShortQueue(title requestedTitle: String?, start rawStart: Double?, end rawEnd: Double?) {
        guard var sequence = projectStore.activeSequence else {
            lastMediaAction = "Short range queue blocked: no active sequence"
            updateAgentState()
            return
        }

        let minimumDuration = 0.15
        let maxSequenceEnd = max(minimumDuration, sequence.duration)
        let requestedStart = rawStart ?? playbackEngine.playhead
        let requestedEnd = rawEnd ?? min(maxSequenceEnd, requestedStart + 30)
        let start = min(max(0, requestedStart), max(0, maxSequenceEnd - minimumDuration))
        let end = max(start + minimumDuration, min(maxSequenceEnd, requestedEnd))

        guard end > start else {
            lastMediaAction = "Short range queue blocked: invalid range"
            updateAgentState()
            return
        }

        let title = requestedTitle?.trimmingCharacters(in: .whitespacesAndNewlines)
        let clipTitle = title?.isEmpty == false
            ? title!
            : String(format: "Short from episode @ %.1fs", start)
        let candidate = ShortClipCandidate(
            title: clipTitle,
            startTime: start,
            duration: end - start,
            sourceLaneId: nil,
            sourceTagId: nil,
            notes: "Queued from explicit episode sequence range. Sequence time is the source of truth for this short recipe."
        )

        sequence.shortClipQueue.append(candidate)
        selectedShortClipId = candidate.id
        selectedLaneId = nil
        selectedTagId = nil
        playbackEngine.playbackFormat = .vertical9x16
        playbackEngine.scrub(to: start)
        projectStore.updateSequence(sequence, undoManager: nil, actionName: "Queue Sequence Short Recipe")
        lastMediaAction = String(format: "Queued sequence short recipe %.2fs -> %.2fs: %@", start, end, clipTitle)
        requestTimelineFocus(reason: "Focused selected short recipe on the Episode Trail Map")
        scheduleAutosave(reason: "queued sequence short recipe")
        updateAgentState()
    }

    private func removeShortClipCandidate(id rawId: String) {
        guard var sequence = projectStore.activeSequence else {
            lastMediaAction = "Short queue remove blocked: no active sequence"
            updateAgentState()
            return
        }

        guard let clipId = UUID(uuidString: rawId) else {
            lastMediaAction = "Short queue remove blocked: invalid id \(rawId)"
            updateAgentState()
            return
        }

        let before = sequence.shortClipQueue.count
        sequence.shortClipQueue.removeAll { $0.id == clipId }
        guard sequence.shortClipQueue.count != before else {
            lastMediaAction = "Short queue remove blocked: clip not found"
            updateAgentState()
            return
        }
        if selectedShortClipId == clipId {
            selectedShortClipId = nil
        }

        projectStore.updateSequence(sequence, undoManager: nil, actionName: "Remove Short Recipe")
        lastMediaAction = "Removed short recipe candidate"
        scheduleAutosave(reason: "removed short recipe")
        updateAgentState()
    }

    private func selectShortClipCandidate(_ clip: ShortClipCandidate) {
        selectedShortClipId = clip.id
        playbackEngine.playbackFormat = .vertical9x16

        if let laneId = clip.sourceLaneId {
            selectedLaneId = laneId
        }
        if let tagId = clip.sourceTagId {
            selectedTagId = tagId
        }

        if let sequence = projectStore.activeSequence {
            playbackEngine.scrub(to: sequenceStartTime(for: clip, in: sequence))
        }
        rebuildPlayer()
        lastMediaAction = "Opened short recipe: \(clip.title)"
        requestTimelineFocus(reason: "Focused Episode Trail Map for short recipe")
        updateAgentState()
    }

    private func selectShortClipCandidateForAgent(id rawId: String?, title rawTitle: String?, index rawIndex: String?) {
        guard let sequence = projectStore.activeSequence else {
            lastMediaAction = "Short select blocked: no active sequence"
            updateAgentState()
            return
        }

        let trimmedId = rawId?.trimmingCharacters(in: .whitespacesAndNewlines) ?? ""
        let trimmedTitle = rawTitle?.trimmingCharacters(in: .whitespacesAndNewlines) ?? ""
        let trimmedIndex = rawIndex?.trimmingCharacters(in: .whitespacesAndNewlines) ?? ""

        let selected: ShortClipCandidate?
        if let uuid = UUID(uuidString: trimmedId) {
            selected = sequence.shortClipQueue.first { $0.id == uuid }
        } else if !trimmedTitle.isEmpty {
            let normalizedTitle = trimmedTitle.lowercased()
            selected = sequence.shortClipQueue.first { $0.title.lowercased() == normalizedTitle }
                ?? sequence.shortClipQueue.first { $0.title.lowercased().contains(normalizedTitle) }
        } else if let parsedIndex = Int(trimmedIndex) {
            let zeroBasedIndex = parsedIndex > 0 ? parsedIndex - 1 : parsedIndex
            selected = sequence.shortClipQueue.indices.contains(zeroBasedIndex)
                ? sequence.shortClipQueue[zeroBasedIndex]
                : nil
        } else {
            selected = nil
        }

        guard let selected else {
            lastMediaAction = "Short select failed: no candidate matched id/title/index"
            updateAgentState()
            return
        }

        selectShortClipCandidate(selected)
    }

    private func selectNextShortReviewCandidate(status rawStatus: String?) {
        guard let sequence = projectStore.activeSequence else {
            lastMediaAction = "Short review next blocked: no active sequence"
            updateAgentState()
            return
        }

        guard let next = nextShortReviewCandidate(in: sequence, preferredStatus: rawStatus) else {
            lastMediaAction = "Short review next blocked: no queued shorts"
            updateAgentState()
            return
        }

        leftWorkbenchMode = .shorts
        isInspectorVisible = true
        selectShortClipCandidate(next)
        lastMediaAction = "Reviewing next short candidate: \(next.title)"
        updateAgentState()
    }

    private func nextShortReviewCandidate(in sequence: MediaSequence, preferredStatus rawStatus: String? = nil) -> ShortClipCandidate? {
        let queue = sequence.shortClipQueue
        guard !queue.isEmpty else { return nil }

        let preferredStatus = normalizedShortReviewStatus(rawStatus ?? "")
        let selectedIndex = selectedShortClipId.flatMap { selectedId in
            queue.firstIndex { $0.id == selectedId }
        } ?? -1
        let startIndex = selectedIndex >= 0 ? (selectedIndex + 1) % queue.count : 0
        let rotated = queue.indices.map { offset in
            queue[(startIndex + offset) % queue.count]
        }

        if !preferredStatus.isEmpty && preferredStatus != "draft" {
            if let exact = rotated.first(where: { normalizedShortReviewStatus($0.reviewStatus) == preferredStatus }) {
                return exact
            }
        }

        let unresolved = rotated.enumerated()
            .filter { _, clip in isShortStillReviewable(clip) }
            .min { left, right in
                let leftRank = shortReviewRank(for: left.element.reviewStatus)
                let rightRank = shortReviewRank(for: right.element.reviewStatus)
                if leftRank != rightRank { return leftRank < rightRank }
                return left.offset < right.offset
            }

        return unresolved?.element ?? rotated.first
    }

    private func shortReviewNextCandidatePayload(for sequence: MediaSequence?) -> [String: Any] {
        guard let sequence,
              let candidate = nextShortReviewCandidate(in: sequence, preferredStatus: nil) else {
            return [
                "available": false,
                "reason": sequence == nil ? "no_active_sequence" : "no_queued_shorts",
                "command": "script/agentctl.sh shorts-review-next",
                "endpoint": "GET /shorts_review_next"
            ]
        }

        let segments = shortClipSegments(for: candidate, in: sequence)
        let exportRanges = shortClipExportRanges(for: candidate, in: sequence)
        let recipeDuration = exportRanges.reduce(0) { $0 + $1.duration }
        let sequenceStart = segments.map(\.start).min() ?? sequenceStartTime(for: candidate, in: sequence)
        let sequenceEnd = segments.map(\.end).max() ?? (sequenceStart + recipeDuration)

        return [
            "available": true,
            "id": candidate.id.uuidString,
            "title": candidate.title,
            "reviewStatus": candidate.reviewStatus,
            "exportStatus": candidate.exportStatus,
            "sequenceStartTime": sequenceStart,
            "sequenceEndTime": sequenceEnd,
            "recipeDuration": recipeDuration,
            "segmentCount": segments.count,
            "transcriptContext": shortTranscriptContextPayload(for: candidate, in: sequence),
            "reviewEvidence": shortReviewEvidencePayload(for: candidate, in: sequence),
            "selectCommand": "script/agentctl.sh shorts-review-next",
            "selectEndpoint": "GET /shorts_review_next",
            "truth": "Selecting the next short only changes editor focus/playhead. It does not approve, publish, or mutate source media."
        ]
    }

    private func normalizedShortReviewStatus(_ status: String) -> String {
        let trimmed = status.trimmingCharacters(in: .whitespacesAndNewlines)
            .lowercased()
            .replacingOccurrences(of: "_", with: "-")
        return trimmed.isEmpty ? "draft" : trimmed
    }

    private func isShortStillReviewable(_ clip: ShortClipCandidate) -> Bool {
        let status = normalizedShortReviewStatus(clip.reviewStatus)
        return status != "keep" && status != "reject"
    }

    private func shortReviewRank(for status: String) -> Int {
        switch normalizedShortReviewStatus(status) {
        case "draft", "queued", "needs-review", "needs-human-review", "ready-for-human-review":
            return 0
        case "refine", "needs-refinement", "needs-captions", "needs-export":
            return 1
        case "exported":
            return 2
        case "keep":
            return 90
        case "reject":
            return 99
        default:
            return 3
        }
    }

    private func selectedNestDocumentValue() -> NestDocument? {
        if let selectedNestDocumentId,
           let document = projectStore.project.nestDocuments.first(where: { $0.id == selectedNestDocumentId }) {
            return document
        }
        return projectStore.project.nestDocuments.sorted { $0.updatedAt > $1.updatedAt }.first
    }

    private func selectedNestBlockValue(in document: NestDocument?) -> NestBlock? {
        guard let document else { return nil }
        if let selectedNestBlockId,
           let block = document.blocks.first(where: { $0.id == selectedNestBlockId }) {
            return block
        }
        return document.blocks.sorted { $0.sortIndex < $1.sortIndex }.first
    }

    private func nestOutlineEntries() -> [NestOutlineEntry] {
        let outlineBlocks = projectStore.project.nestDocuments
            .flatMap { document in
                document.blocks.map { block in (document, block) }
            }
            .sorted { left, right in
                if left.0.updatedAt == right.0.updatedAt {
                    return left.1.sortIndex < right.1.sortIndex
                }
                return left.0.updatedAt < right.0.updatedAt
            }
            .filter { _, block in
                let role = block.role.trimmingCharacters(in: .whitespacesAndNewlines).lowercased()
                let tags = Set(block.tags.map { $0.trimmingCharacters(in: .whitespacesAndNewlines).lowercased() })
                return role == "chapter-marker"
                    || role == "episode-marker"
                    || tags.contains("chapter")
                    || tags.contains("episode")
            }

        var currentChapterSlug = ""
        var currentChapterTitle = ""
        return outlineBlocks.map { document, block in
            let role = block.role.trimmingCharacters(in: .whitespacesAndNewlines).lowercased()
            let tags = Set(block.tags.map { $0.trimmingCharacters(in: .whitespacesAndNewlines).lowercased() })
            let isChapter = role == "chapter-marker" || tags.contains("chapter")
            let kind = isChapter ? "chapter" : "episode"
            let title = normalizedNestOutlineTitle(for: block)
            let derivedSlug = nestSlug(from: title, fallback: kind)
            let chapterSlug = isChapter
                ? (block.chapterSlug.isEmpty ? derivedSlug : block.chapterSlug)
                : currentChapterSlug
            let episodeSlug = isChapter
                ? ""
                : (block.episodeSlug.isEmpty ? derivedSlug : block.episodeSlug)
            if isChapter {
                currentChapterSlug = chapterSlug
                currentChapterTitle = title
            }
            return NestOutlineEntry(
                id: block.id,
                documentId: document.id,
                documentTitle: document.title,
                kind: kind,
                title: title,
                chapterSlug: chapterSlug,
                chapterTitle: isChapter ? title : currentChapterTitle,
                episodeSlug: episodeSlug,
                role: block.role,
                authorship: block.authorship,
                reviewStatus: block.reviewStatus,
                tags: block.tags
            )
        }
    }

    private func normalizedNestTags(_ raw: String) -> [String] {
        raw
            .components(separatedBy: CharacterSet(charactersIn: ",;\n"))
            .map { $0.trimmingCharacters(in: .whitespacesAndNewlines) }
            .filter { !$0.isEmpty }
    }

    private func nestAuthorshipLabel(_ authorship: String) -> String {
        switch authorship.trimmingCharacters(in: .whitespacesAndNewlines).lowercased() {
        case "human-authored":
            return "Human"
        case "agent-authored":
            return "Agent"
        case "mixed-authorship":
            return "Mixed"
        case "source-context", "seeded-source":
            return "Source"
        default:
            return "Trace"
        }
    }

    private func nestAuthorshipColor(_ authorship: String) -> Color {
        switch authorship.trimmingCharacters(in: .whitespacesAndNewlines).lowercased() {
        case "human-authored":
            return QuipslyStudioTheme.moss
        case "agent-authored":
            return QuipslyStudioTheme.creek
        case "mixed-authorship":
            return QuipslyStudioTheme.lichen
        case "source-context", "seeded-source":
            return QuipslyStudioTheme.honey
        default:
            return QuipslyStudioTheme.sage
        }
    }

    private func normalizedNestOutlineTitle(for block: NestBlock) -> String {
        let normalizedText = block.text
            .replacingOccurrences(of: "\\n", with: "\n")
            .trimmingCharacters(in: .whitespacesAndNewlines)
        let firstTitleLine = normalizedText
            .split(separator: "\n", omittingEmptySubsequences: true)
            .first
            .map(String.init) ?? normalizedText
        let title = firstTitleLine.trimmingCharacters(in: .whitespacesAndNewlines)
        return title.isEmpty ? block.role : String(title.prefix(96))
    }

    private func nestSlug(from text: String, fallback: String) -> String {
        let lowered = text
            .lowercased()
            .replacingOccurrences(of: #"[^a-z0-9]+"#, with: "-", options: .regularExpression)
            .trimmingCharacters(in: CharacterSet(charactersIn: "-"))
        let cleaned = lowered.isEmpty ? fallback : lowered
        return String(cleaned.prefix(72)).trimmingCharacters(in: CharacterSet(charactersIn: "-"))
    }

    private func appendNestDraftBlock() {
        appendNestBlockFromAgent(
            title: nestDraftTitle,
            text: nestDraftBody,
            tags: nestDraftTags,
            role: "writing",
            episodeSlug: "",
            authorship: nestDraftAuthorship,
            provenanceNote: "Created from the native Nest write/paste workbench.",
            reviewStatus: nestDraftAuthorship == "agent-authored" ? "agent-first-pass" : "authored-draft"
        )
        nestDraftTitle = ""
        nestDraftBody = ""
    }

    private func appendNestStructureMarker(kind: String) {
        let normalizedKind = kind.trimmingCharacters(in: .whitespacesAndNewlines).lowercased()
        let isChapter = normalizedKind == "chapter"
        let title = nestDraftTitle.trimmingCharacters(in: .whitespacesAndNewlines)
        let body = nestDraftBody.trimmingCharacters(in: .whitespacesAndNewlines)
        let markerText = title.isEmpty ? body : title
        guard !markerText.isEmpty else {
            lastMediaAction = "Structure marker blocked: add a title or body first"
            updateAgentState()
            return
        }

        let slug = nestSlug(from: markerText, fallback: isChapter ? "chapter" : "episode")
        let extraTags = normalizedNestTags(nestDraftTags).filter { tag in
            let lower = tag.lowercased()
            return lower != "chapter" && lower != "episode" && lower != "writing"
        }
        let baseTags = isChapter
            ? ["chapter", "structure", "book"]
            : ["episode", "structure", "show", slug]
        let tags = (baseTags + extraTags).joined(separator: ",")
        let storedText = body.isEmpty || body == markerText
            ? markerText
            : "\(markerText)\n\n\(body)"

        appendNestBlockFromAgent(
            title: markerText,
            text: storedText,
            tags: tags,
            role: isChapter ? "chapter-marker" : "episode-marker",
            episodeSlug: isChapter ? "" : slug,
            authorship: nestDraftAuthorship,
            provenanceNote: "Created as a \(isChapter ? "Chapter" : "Episode") structure marker from the native Nest write/paste panel.",
            reviewStatus: nestDraftAuthorship == "agent-authored" ? "agent-first-pass" : "authored-draft"
        )
        if isChapter {
            updateSelectedNestBlockStructure(
                role: "chapter-marker",
                tags: tags,
                chapterSlug: slug,
                note: "Assigned chapter slug during direct Chapter marker creation.",
                blockId: selectedNestBlockId?.uuidString
            )
        }
        nestDraftTitle = ""
        nestDraftBody = ""
        lastMediaAction = "Created Nest \(isChapter ? "Chapter" : "Episode") marker: \(markerText)"
        updateAgentState()
    }

    private func appendNestBlockFromAgent(
        title: String?,
        text: String?,
        tags: String?,
        role: String?,
        episodeSlug: String?,
        authorship: String? = nil,
        provenanceNote: String? = nil,
        reviewStatus: String? = nil
    ) {
        let body = (text ?? "").trimmingCharacters(in: .whitespacesAndNewlines)
        guard !body.isEmpty else {
            lastMediaAction = "Nest block blocked: no text supplied"
            updateAgentState()
            return
        }

        var project = projectStore.project
        let now = Date()
        let writingTitle = (title ?? "").trimmingCharacters(in: .whitespacesAndNewlines)
        let normalizedAuthorship = (authorship ?? "agent-authored").trimmingCharacters(in: .whitespacesAndNewlines).isEmpty
            ? "agent-authored"
            : (authorship ?? "agent-authored").trimmingCharacters(in: .whitespacesAndNewlines)
        let blockReviewStatus = (reviewStatus ?? (normalizedAuthorship == "agent-authored" ? "agent-first-pass" : "authored-draft"))
        let documentIndex: Int
        if let selectedNestDocumentId,
           let existingIndex = project.nestDocuments.firstIndex(where: { $0.id == selectedNestDocumentId }),
           project.nestDocuments[existingIndex].source != "seeded-episodes-1-3-local-context" {
            documentIndex = existingIndex
        } else if let existingIndex = project.nestDocuments.firstIndex(where: { $0.source == "human-authored" && $0.kind == "writing" }) {
            documentIndex = existingIndex
        } else {
            project.nestDocuments.append(NestDocument(
                title: writingTitle.isEmpty ? "High Ground Odyssey Writing Draft" : writingTitle,
                kind: "writing",
                status: "draft",
                source: "human-authored",
                tags: normalizedNestTags(tags ?? "book,writing"),
                notes: "Living authored layer. Seeded context is separate and reviewable."
            ))
            documentIndex = project.nestDocuments.count - 1
        }

        let sortIndex = (project.nestDocuments[documentIndex].blocks.map(\.sortIndex).max() ?? -1) + 1
        let block = NestBlock(
            role: (role ?? "writing"),
            text: body,
            tags: normalizedNestTags(tags ?? nestDraftTags),
            authorship: normalizedAuthorship,
            provenanceNote: (provenanceNote ?? "Added through QuipslyStudio agent/write capture. Review before canon promotion."),
            episodeSlug: (episodeSlug ?? "").trimmingCharacters(in: .whitespacesAndNewlines),
            reviewStatus: blockReviewStatus,
            sortIndex: sortIndex,
            createdAt: now,
            updatedAt: now
        )
        project.nestDocuments[documentIndex].blocks.append(block)
        project.nestDocuments[documentIndex].updatedAt = now
        if !writingTitle.isEmpty && project.nestDocuments[documentIndex].title == "High Ground Odyssey Writing Draft" {
            project.nestDocuments[documentIndex].title = writingTitle
        }

        selectedNestDocumentId = project.nestDocuments[documentIndex].id
        selectedNestBlockId = block.id
        projectStore.updateProject(project, undoManager: nil, actionName: "Add Nest Block")
        lastMediaAction = "Added Nest writing block: \(project.nestDocuments[documentIndex].title)"
        scheduleAutosave(reason: "added nest block")
        updateAgentState()
    }

