    private func replaceNestBlockText(blockId: String?, text: String?, note: String?, reviewStatus: String?) {
        let body = (text ?? "").trimmingCharacters(in: .whitespacesAndNewlines)
        guard !body.isEmpty else {
            lastMediaAction = "Nest revision blocked: no text supplied"
            updateAgentState()
            return
        }

        guard let targetBlockId = UUID(uuidString: (blockId ?? selectedNestBlockId?.uuidString ?? "")) else {
            lastMediaAction = "Nest revision blocked: missing block id"
            updateAgentState()
            return
        }

        var project = projectStore.project
        guard let documentIndex = project.nestDocuments.firstIndex(where: { document in
            document.blocks.contains { $0.id == targetBlockId }
        }), let blockIndex = project.nestDocuments[documentIndex].blocks.firstIndex(where: { $0.id == targetBlockId }) else {
            lastMediaAction = "Nest revision blocked: block not found"
            updateAgentState()
            return
        }

        let oldText = project.nestDocuments[documentIndex].blocks[blockIndex].text
        guard oldText != body else {
            lastMediaAction = "Nest revision skipped: text unchanged"
            updateAgentState()
            return
        }

        let now = Date()
        let existingNote = project.nestDocuments[documentIndex].blocks[blockIndex].provenanceNote
            .trimmingCharacters(in: .whitespacesAndNewlines)
        let revisionNote = (note ?? "Revised through QuipslyStudio.").trimmingCharacters(in: .whitespacesAndNewlines)
        let suffix = revisionNote.isEmpty ? "Revised through QuipslyStudio." : revisionNote
        project.nestDocuments[documentIndex].blocks[blockIndex].text = body
        project.nestDocuments[documentIndex].blocks[blockIndex].provenanceNote = existingNote.isEmpty
            ? suffix
            : "\(existingNote) \(suffix)"
        if let reviewStatus, !reviewStatus.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty {
            project.nestDocuments[documentIndex].blocks[blockIndex].reviewStatus = reviewStatus.trimmingCharacters(in: .whitespacesAndNewlines)
        } else if project.nestDocuments[documentIndex].blocks[blockIndex].reviewStatus == "canon-approved" {
            project.nestDocuments[documentIndex].blocks[blockIndex].reviewStatus = "authored-draft"
            project.nestDocuments[documentIndex].blocks[blockIndex].provenanceNote += " Canon approval reset because the block text changed."
        }
        project.nestDocuments[documentIndex].blocks[blockIndex].updatedAt = now
        project.nestDocuments[documentIndex].updatedAt = now

        selectedNestDocumentId = project.nestDocuments[documentIndex].id
        selectedNestBlockId = targetBlockId
        projectStore.updateProject(project, undoManager: nil, actionName: "Revise Nest Block")
        lastMediaAction = "Revised Nest block: \(project.nestDocuments[documentIndex].blocks[blockIndex].role)"
        scheduleAutosave(reason: "revised nest block")
        updateAgentState()
    }

    private func seedHighGroundOdysseyNestContext() {
        let previousSelectedDocumentId = selectedNestDocumentId
        let previousSelectedBlockId = selectedNestBlockId
        var project = projectStore.project
        let now = Date()
        let blocks = highGroundOdysseySeedBlocks(now: now)
        let document = NestDocument(
            title: "High Ground Odyssey Episodes 1-3 + Book Seed Context",
            kind: "episode-context",
            status: "seeded-needs-human-review",
            source: "seeded-episodes-1-3-local-context",
            tags: ["high-ground-odyssey", "episodes-1-3", "book-source", "seeded", "needs-human-review"],
            blocks: blocks,
            notes: "Working Nest context seeded from local transcript/import artifacts and Homer chapter source files. Use as scaffolding; Charlie/Homer reviewed writing remains the canon layer.",
            createdAt: now,
            updatedAt: now
        )

        if let index = project.nestDocuments.firstIndex(where: { $0.source == "seeded-episodes-1-3-local-context" }) {
            project.nestDocuments[index] = document
        } else {
            project.nestDocuments.append(document)
        }

        if let previousSelectedDocumentId,
           let previousSelectedBlockId,
           project.nestDocuments.contains(where: { candidate in
               candidate.id == previousSelectedDocumentId
                   && candidate.blocks.contains(where: { $0.id == previousSelectedBlockId })
           }) {
            selectedNestDocumentId = previousSelectedDocumentId
            selectedNestBlockId = previousSelectedBlockId
        } else {
            selectedNestDocumentId = document.id
            selectedNestBlockId = document.blocks.first?.id
        }
        projectStore.updateProject(project, undoManager: nil, actionName: "Seed Nest Context")
        leftWorkbenchMode = .nest
        lastMediaAction = "Seeded Nest context for Episodes 1-3"
        scheduleAutosave(reason: "seeded nest context")
        updateAgentState()
    }

    private func highGroundOdysseySeedBlocks(now: Date) -> [NestBlock] {
        let repoRoot = "/Users/wall-e/Dev/high-ground-studio"
        let seeds: [(episode: String, title: String, path: String, source: String, url: String)] = [
            ("episode-1", "Episode 1 - The Wednesday Rule", "\(repoRoot)/artifacts/transcripts/youtube-captions/episode-1.youtube-auto.vtt", "youtube-caption-local", "https://youtu.be/96LN__TA-T8"),
            ("episode-2", "Episode 2 - Local ASR context", "\(repoRoot)/artifacts/transcripts/local-asr/episode-2-codex-overlap-review-v3.whisper-cpp.srt", "local-asr", "https://youtu.be/7Rn4rV2cLy4"),
            ("episode-3", "Episode 3 - YouTube caption context", "\(repoRoot)/artifacts/transcripts/youtube-captions/episode-3.youtube-auto.vtt", "youtube-caption-local", "https://youtu.be/rf3L1xki_Nk")
        ]

        var blocks: [NestBlock] = [
            NestBlock(
                role: "seed-note",
                text: "Seeded context is scaffolding for the Nest -> Studio -> Tower proof loop. It may come from local transcripts, Premiere imports, published pages, or YouTube captions. Treat it as searchable context until Charlie/Homer author or review it.",
                tags: ["seeded", "source-context", "not-canon"],
                authorship: "source-context",
                provenanceNote: "System seed note explaining source/canon boundaries.",
                reviewStatus: "needs-human-review",
                sortIndex: 0,
                createdAt: now,
                updatedAt: now
            )
        ]

        for (index, seed) in seeds.enumerated() {
            let excerpt = seedExcerpt(from: seed.path)
            blocks.append(NestBlock(
                role: "episode-context",
                text: "\(seed.title)\n\nSource type: \(seed.source)\nPublished reference: \(seed.url)\n\n\(excerpt)",
                tags: ["seeded", "episode", seed.episode, "needs-human-review"],
                authorship: "source-context",
                provenanceNote: "Seeded from local transcript/caption context; not canon manuscript text.",
                episodeSlug: seed.episode,
                sourcePath: seed.path,
                sourceURL: seed.url,
                reviewStatus: "seeded-needs-human-review",
                sortIndex: index + 1,
                createdAt: now,
                updatedAt: now
            ))
        }

        let importPaths = [
            ("episode-1", "\(repoRoot)/content/quipsly/premiere-imports/episode-1.json"),
            ("episode-2", "\(repoRoot)/content/quipsly/premiere-imports/episode-2.json"),
            ("episode-3", "\(repoRoot)/content/quipsly/premiere-imports/episode-3.json")
        ]
        for (offset, item) in importPaths.enumerated() {
            let excerpt = seedExcerpt(from: item.1, maxCharacters: 1200)
            blocks.append(NestBlock(
                role: "production-source",
                text: "\(item.0) production import metadata\n\n\(excerpt)",
                tags: ["seeded", "premiere-import", item.0, "studio-link"],
                authorship: "source-context",
                provenanceNote: "Seeded from local production import metadata for traceability.",
                episodeSlug: item.0,
                sourcePath: item.1,
                reviewStatus: "source-reference",
                sortIndex: 10 + offset,
                createdAt: now,
                updatedAt: now
            ))
        }

        blocks.append(contentsOf: highGroundOdysseyBookSeedBlocks(now: now, startSortIndex: 20))

        return blocks
    }

    private func highGroundOdysseyBookSeedBlocks(now: Date, startSortIndex: Int) -> [NestBlock] {
        let rootPath = "/Users/wall-e/Dev/high-ground-studio/apps/web/content/_inbox/HighGroundOdysseyBook"
        let rootURL = URL(fileURLWithPath: rootPath, isDirectory: true)
        guard let enumerator = FileManager.default.enumerator(
            at: rootURL,
            includingPropertiesForKeys: nil,
            options: [.skipsHiddenFiles]
        ) else {
            return [
                NestBlock(
                    role: "book-source-index",
                    text: "High Ground Odyssey book source folder was not available at seed time.\n\nExpected path: \(rootPath)",
                    tags: ["seeded", "book-source", "missing-source", "needs-human-review"],
                    authorship: "source-context",
                    provenanceNote: "Generated missing-source marker during Nest seed.",
                    reviewStatus: "missing-source",
                    sortIndex: startSortIndex,
                    createdAt: now,
                    updatedAt: now
                )
            ]
        }

        var markdownFiles: [URL] = []
        for case let fileURL as URL in enumerator {
            if fileURL.pathExtension.lowercased() == "md" {
                markdownFiles.append(fileURL)
            }
        }
        markdownFiles.sort { highGroundOdysseyRelativePath(for: $0, rootPath: rootPath) < highGroundOdysseyRelativePath(for: $1, rootPath: rootPath) }

        guard !markdownFiles.isEmpty else {
            return [
                NestBlock(
                    role: "book-source-index",
                    text: "High Ground Odyssey book source folder was present, but no Markdown chapter files were found.\n\nFolder: \(rootPath)",
                    tags: ["seeded", "book-source", "empty-source", "needs-human-review"],
                    authorship: "source-context",
                    provenanceNote: "Generated empty-source marker during Nest seed.",
                    reviewStatus: "missing-source",
                    sortIndex: startSortIndex,
                    createdAt: now,
                    updatedAt: now
                )
            ]
        }

        let indexText = markdownFiles
            .map { "- \(highGroundOdysseyRelativePath(for: $0, rootPath: rootPath))" }
            .joined(separator: "\n")

        var blocks: [NestBlock] = [
            NestBlock(
                role: "book-source-index",
                text: "Homer book source index\n\nThese are local chapter files from the HighGroundOdysseyBook inbox. They are imported as review-labeled context excerpts, not canon manuscript text.\n\n\(indexText)",
                tags: ["seeded", "book-source", "homer-source", "source-index", "needs-human-review"],
                authorship: "source-context",
                provenanceNote: "Generated from the local Homer book source folder index.",
                reviewStatus: "source-reference",
                sortIndex: startSortIndex,
                createdAt: now,
                updatedAt: now
            )
        ]

        for (offset, fileURL) in markdownFiles.enumerated() {
            let relativePath = highGroundOdysseyRelativePath(for: fileURL, rootPath: rootPath)
            let title = highGroundOdysseyBookSeedTitle(for: fileURL, rootPath: rootPath)
            let sectionTag = highGroundOdysseyBookSectionTag(for: relativePath)
            let excerpt = seedExcerpt(from: fileURL.path, maxCharacters: 1800)
            let sourceNote = "Local source path: \(fileURL.path)\nReview rule: source context only; do not treat this as the current canon manuscript until Charlie/Homer review it."
            blocks.append(NestBlock(
                role: "book-source",
                text: "\(title)\n\n\(sourceNote)\n\n\(excerpt)",
                tags: ["seeded", "book-source", "homer-source", sectionTag, "needs-human-review"],
                authorship: "source-context",
                provenanceNote: "Seeded excerpt from local Homer book source Markdown; review before canon promotion.",
                sourcePath: fileURL.path,
                reviewStatus: "seeded-needs-human-review",
                sortIndex: startSortIndex + offset + 1,
                createdAt: now,
                updatedAt: now
            ))
        }

        return blocks
    }

    private func highGroundOdysseyRelativePath(for fileURL: URL, rootPath: String) -> String {
        let prefix = rootPath.hasSuffix("/") ? rootPath : rootPath + "/"
        if fileURL.path.hasPrefix(prefix) {
            return String(fileURL.path.dropFirst(prefix.count))
        }
        return fileURL.lastPathComponent
    }

    private func highGroundOdysseyBookSeedTitle(for fileURL: URL, rootPath: String) -> String {
        let relativePath = highGroundOdysseyRelativePath(for: fileURL, rootPath: rootPath)
        let parts = relativePath.split(separator: "/").map(String.init)
        let section = parts.dropLast().last ?? ""
        let fileName = fileURL.deletingPathExtension().lastPathComponent
        if section.isEmpty || section == fileName {
            return fileName
        }
        return "\(section) - \(fileName)"
    }

    private func highGroundOdysseyBookSectionTag(for relativePath: String) -> String {
        let lower = relativePath.lowercased()
        let candidates = [
            "preface",
            "introduction",
            "forward",
            "outtro",
            "chapter zero",
            "chapter one",
            "chapter two",
            "chapter three",
            "chapter four.five",
            "chapter four",
            "chapter five",
            "chapter six",
            "chapter seven",
            "chapter eight",
            "chapter nine",
            "chapter ten",
            "chapter eleven",
            "chapter twelve"
        ]
        let match = candidates.first { lower.contains($0) } ?? "book-section"
        return match
            .replacingOccurrences(of: ".", with: "-")
            .replacingOccurrences(of: " ", with: "-")
    }

    private func firstMeaningfulLine(from text: String) -> String {
        let line = text
            .components(separatedBy: .newlines)
            .map { $0.trimmingCharacters(in: .whitespacesAndNewlines) }
            .first { !$0.isEmpty } ?? "Untitled writing block"
        if line.count <= 96 {
            return line
        }
        return String(line.prefix(93)) + "..."
    }

    private func seedExcerpt(from path: String, maxCharacters: Int = 2200) -> String {
        let url = URL(fileURLWithPath: path)
        guard let raw = try? String(contentsOf: url, encoding: .utf8) else {
            return "No local text was available at seed time. Use the published HighGroundOdyssey.com episode page or YouTube reference as fallback context."
        }
        let cleaned = raw
            .components(separatedBy: .newlines)
            .map { line in
                line
                    .replacingOccurrences(of: "<[^>]+>", with: "", options: .regularExpression)
                    .trimmingCharacters(in: .whitespacesAndNewlines)
            }
            .filter { line in
                guard !line.isEmpty else { return false }
                if line == "WEBVTT" { return false }
                if line.contains("-->") { return false }
                if line.range(of: #"^\d+$"#, options: .regularExpression) != nil { return false }
                return true
            }
            .joined(separator: " ")
            .replacingOccurrences(of: #"\s+"#, with: " ", options: .regularExpression)
            .trimmingCharacters(in: .whitespacesAndNewlines)
        if cleaned.isEmpty {
            return "Local source exists but did not contain extractable prose/caption text. Keep the source path as context and use published page fallback if needed."
        }
        if cleaned.count <= maxCharacters {
            return cleaned
        }
        return String(cleaned.prefix(maxCharacters)) + "..."
    }

    private func updateSelectedNestBlockStructure(
        role: String? = nil,
        tags: String? = nil,
        episodeSlug: String? = nil,
        chapterSlug: String? = nil,
        note: String,
        blockId explicitBlockId: String? = nil
    ) {
        var project = projectStore.project
        let explicitId = explicitBlockId
            .flatMap { UUID(uuidString: $0.trimmingCharacters(in: .whitespacesAndNewlines)) }
        guard let targetBlockId = explicitId ?? selectedNestBlockId,
              let documentIndex = project.nestDocuments.firstIndex(where: { document in
                  document.blocks.contains { $0.id == targetBlockId }
              }),
              let blockIndex = project.nestDocuments[documentIndex].blocks.firstIndex(where: { $0.id == targetBlockId }) else {
            lastMediaAction = "No selected Nest block to structure."
            updateAgentState()
            return
        }

        if let role {
            let normalizedRole = role.trimmingCharacters(in: .whitespacesAndNewlines)
            if !normalizedRole.isEmpty {
                project.nestDocuments[documentIndex].blocks[blockIndex].role = normalizedRole
            }
        }
        if let tags {
            let incoming = normalizedNestTags(tags)
            if !incoming.isEmpty {
                let existing = project.nestDocuments[documentIndex].blocks[blockIndex].tags
                project.nestDocuments[documentIndex].blocks[blockIndex].tags = Array(Set(existing + incoming)).sorted()
            }
        }
        if let episodeSlug {
            let normalizedEpisode = episodeSlug.trimmingCharacters(in: .whitespacesAndNewlines)
            if !normalizedEpisode.isEmpty {
                project.nestDocuments[documentIndex].blocks[blockIndex].episodeSlug = normalizedEpisode
            }
        }
        if let chapterSlug {
            let normalizedChapter = chapterSlug.trimmingCharacters(in: .whitespacesAndNewlines)
            if !normalizedChapter.isEmpty {
                project.nestDocuments[documentIndex].blocks[blockIndex].chapterSlug = normalizedChapter
            }
        }

        let normalizedNote = note.trimmingCharacters(in: .whitespacesAndNewlines)
        if !normalizedNote.isEmpty {
            let existing = project.nestDocuments[documentIndex].blocks[blockIndex].provenanceNote
                .trimmingCharacters(in: .whitespacesAndNewlines)
            project.nestDocuments[documentIndex].blocks[blockIndex].provenanceNote = existing.isEmpty
                ? normalizedNote
                : "\(existing) \(normalizedNote)"
        }
        project.nestDocuments[documentIndex].blocks[blockIndex].updatedAt = Date()
        project.nestDocuments[documentIndex].updatedAt = Date()
        projectStore.updateProject(project, undoManager: nil, actionName: "Structure Nest Block")
        selectedNestDocumentId = project.nestDocuments[documentIndex].id
        selectedNestBlockId = targetBlockId
        lastMediaAction = "Structured Nest block."
        scheduleAutosave(reason: "structured nest block")
        updateAgentState()
    }

    private func selectNestBlockById(_ blockId: String?) {
        guard let targetBlockId = blockId
            .flatMap({ UUID(uuidString: $0.trimmingCharacters(in: .whitespacesAndNewlines)) }),
              let document = projectStore.project.nestDocuments.first(where: { document in
                  document.blocks.contains { $0.id == targetBlockId }
              }) else {
            lastMediaAction = "Nest block select blocked: unknown block id."
            updateAgentState()
            return
        }

        selectedNestDocumentId = document.id
        selectedNestBlockId = targetBlockId
        lastMediaAction = "Selected Nest block by ID."
        updateAgentState()
    }

    private func updateSelectedNestBlockReviewStatus(_ status: String, note: String, blockId explicitBlockId: String? = nil) {
        let normalizedStatus = status.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty
            ? "needs-human-review"
            : status.trimmingCharacters(in: .whitespacesAndNewlines)
        let normalizedNote = note.trimmingCharacters(in: .whitespacesAndNewlines)
        var project = projectStore.project
        let explicitId = explicitBlockId
            .flatMap { UUID(uuidString: $0.trimmingCharacters(in: .whitespacesAndNewlines)) }
        guard let targetBlockId = explicitId ?? selectedNestBlockId,
              let documentIndex = project.nestDocuments.firstIndex(where: { document in
                  document.blocks.contains { $0.id == targetBlockId }
              }),
              let blockIndex = project.nestDocuments[documentIndex].blocks.firstIndex(where: { $0.id == targetBlockId }) else {
            lastMediaAction = "No selected Nest block to mark."
            updateAgentState()
            return
        }

        project.nestDocuments[documentIndex].blocks[blockIndex].reviewStatus = normalizedStatus
        if !normalizedNote.isEmpty {
            let existing = project.nestDocuments[documentIndex].blocks[blockIndex].provenanceNote
                .trimmingCharacters(in: .whitespacesAndNewlines)
            project.nestDocuments[documentIndex].blocks[blockIndex].provenanceNote = existing.isEmpty
                ? normalizedNote
                : "\(existing) \(normalizedNote)"
        }
        project.nestDocuments[documentIndex].blocks[blockIndex].updatedAt = Date()
        project.nestDocuments[documentIndex].updatedAt = Date()
        projectStore.updateProject(project, undoManager: nil, actionName: "Mark Nest Block")
        selectedNestDocumentId = project.nestDocuments[documentIndex].id
        selectedNestBlockId = targetBlockId
        lastMediaAction = "Marked Nest block \(normalizedStatus)."
        scheduleAutosave(reason: "marked nest block")
        updateAgentState()
    }

    private func nestWritingNextActionRows() -> [[String: String]] {
        let documents = projectStore.project.nestDocuments
        let writingDocuments = documents.filter { $0.source == "human-authored" && $0.kind == "writing" }
        let seededContextAvailable = documents.contains { $0.source == "seeded-episodes-1-3-local-context" }
        let authoredBlocks = writingDocuments
            .flatMap(\.blocks)
            .filter { nestWritingIsAuthoredCandidate($0) }
            .sorted { lhs, rhs in
                let lhsPriority = nestWritingReviewPriority(lhs)
                let rhsPriority = nestWritingReviewPriority(rhs)
                if lhsPriority == rhsPriority {
                    return lhs.sortIndex < rhs.sortIndex
                }
                return lhsPriority < rhsPriority
            }
        let reviewBlocks = authoredBlocks.filter { block in
            let status = block.reviewStatus.trimmingCharacters(in: .whitespacesAndNewlines).lowercased()
            return status.isEmpty || status.contains("needs") || status.contains("draft") || status == "agent-first-pass"
        }
        let agentFirstPassBlocks = authoredBlocks.filter { $0.reviewStatus == "agent-first-pass" }
        let outline = nestOutlineEntries()
        let chapterCount = outline.filter { $0.kind == "chapter" }.count
        let episodeCount = outline.filter { $0.kind == "episode" }.count

        var rows: [[String: String]] = []
        if writingDocuments.isEmpty {
            rows.append([
                "kind": "start-writing",
                "tone": "write",
                "label": "Start the authored manuscript layer",
                "detail": "Create the durable writing document before seeded context gets mistaken for manuscript truth.",
                "button": "Start",
                "command": "script/agentctl.sh nest-ensure-writing-document"
            ])
        }
        if !seededContextAvailable {
            rows.append([
                "kind": "seed-context",
                "tone": "source",
                "label": "Bring in Episodes 1-3 context",
                "detail": "Seed review-labeled source context so writing, editing, and publishing stay connected without promoting it to canon.",
                "button": "Seed",
                "command": "script/agentctl.sh nest-seed-context"
            ])
        }
        if let firstReview = reviewBlocks.first {
            rows.append([
                "kind": "select-review-block",
                "tone": "review",
                "label": "Review the next draft block",
                "detail": "\(reviewBlocks.count) authored block(s) still need review. Select the next one instead of hunting through the document.",
                "button": "Select",
                "blockId": firstReview.id.uuidString,
                "command": "script/agentctl.sh nest-select-block \(firstReview.id.uuidString)"
            ])
        }
        if chapterCount == 0 {
            rows.append([
                "kind": "create-structure",
                "tone": "structure",
                "label": "Add the first Chapter marker",
                "detail": "Chapter and Episode markers make the outline a projection of the living document, not a second truth.",
                "button": "Prep",
                "draftTitle": "Chapter 0 - The Ground Beneath the Story",
                "draftTags": "chapter,structure,book",
                "command": "Use the Chapter button in the native Nest write/paste panel."
            ])
        }
        if episodeCount == 0 {
            rows.append([
                "kind": "create-structure",
                "tone": "structure",
                "label": "Add the first Episode marker",
                "detail": "Episode markers tie manuscript work to Studio and Tower without copying episode state into a separate system.",
                "button": "Prep",
                "draftTitle": "Episode 1 - The Wednesday Rule",
                "draftTags": "episode,structure,show,episode-1",
                "command": "Use the Episode button in the native Nest write/paste panel."
            ])
        }
        if authoredBlocks.isEmpty {
            rows.append([
                "kind": "draft-next",
                "tone": "write",
                "label": "Draft the first original passage",
                "detail": "Codex may create a serious first pass or Charlie can write fresh. Either way, authorship and review state stay visible.",
                "button": "Prep",
                "draftTitle": "Episode 1 - Charlie first pass",
                "draftTags": "book,writing,episode-1,agent-first-pass",
                "command": "script/agentctl.sh nest-append-block \"Episode 1 - Charlie first pass\" \"<draft text>\" \"book,writing,episode-1\" writing episode-1 agent-authored \"agent first pass\" agent-first-pass"
            ])
        } else if agentFirstPassBlocks.count > 0 {
            rows.append([
                "kind": "select-review-block",
                "tone": "review",
                "label": "Human-check agent first-pass writing",
                "detail": "\(agentFirstPassBlocks.count) agent-authored first-pass block(s) are waiting to be shaped into Charlie/Homer voice.",
                "button": "Select",
                "blockId": agentFirstPassBlocks.first?.id.uuidString ?? "",
                "command": "script/agentctl.sh nest-select-block \(agentFirstPassBlocks.first?.id.uuidString ?? "<block-id>")"
            ])
        } else {
            rows.append([
                "kind": "draft-next",
                "tone": "write",
                "label": "Write the next manuscript beat",
                "detail": "Keep adding authored blocks here; seeded context stays nearby as source material, not canon.",
                "button": "Prep",
                "draftTitle": "Next High Ground Odyssey beat",
                "draftTags": "book,writing,draft",
                "command": "Use Add writing block or script/agentctl.sh nest-append-block."
            ])
        }

        return Array(rows.prefix(5))
    }

    private func nestWritingIsAuthoredCandidate(_ block: NestBlock) -> Bool {
        let authorship = block.authorship.trimmingCharacters(in: .whitespacesAndNewlines).lowercased()
        return authorship == "human-authored" || authorship == "agent-authored" || authorship == "mixed-authorship"
    }

    private func nestWritingReviewPriority(_ block: NestBlock) -> Int {
        let role = block.role.trimmingCharacters(in: .whitespacesAndNewlines).lowercased()
        if role == "writing" {
            return 0
        }
        if role.contains("episode") || role.contains("chapter") {
            return 1
        }
        return 2
    }

    private func performNestWritingNextAction(_ row: [String: String]) {
        switch row["kind"] {
        case "start-writing":
            ensureNestWritingDocument()
        case "seed-context":
            seedHighGroundOdysseyNestContext()
        case "select-review-block":
            selectNestBlockById(row["blockId"])
        case "create-structure", "draft-next":
            ensureNestWritingDocument()
            nestDraftTitle = row["draftTitle"] ?? nestDraftTitle
            nestDraftTags = row["draftTags"] ?? nestDraftTags
            if row["kind"] == "draft-next" {
                nestDraftAuthorship = "agent-authored"
            }
            lastMediaAction = "Prepared Nest writing panel: \(row["label"] ?? "next action")"
            updateAgentState()
        default:
            lastMediaAction = "Nest next action has no native handler yet."
            updateAgentState()
        }
    }

    private func performNestWritingNextActionForAgent(index rawIndex: String?, kind rawKind: String?) {
        let rows = nestWritingNextActionRows()
        guard !rows.isEmpty else {
            lastMediaAction = "Nest writing queue is empty."
            updateAgentState()
            return
        }

        let trimmedKind = (rawKind ?? "").trimmingCharacters(in: .whitespacesAndNewlines)
        let rawIndexValue = (rawIndex ?? "0").trimmingCharacters(in: .whitespacesAndNewlines).lowercased()
        let selectedRow: [String: String]?
        if !trimmedKind.isEmpty {
            selectedRow = rows.first { row in
                (row["kind"] ?? "").caseInsensitiveCompare(trimmedKind) == .orderedSame
                    || (row["label"] ?? "").localizedCaseInsensitiveContains(trimmedKind)
            }
        } else if rawIndexValue == "first" || rawIndexValue.isEmpty {
            selectedRow = rows.first
        } else if let parsed = Int(rawIndexValue) {
            let zeroBasedIndex = parsed > 0 ? parsed - 1 : parsed
            selectedRow = rows.indices.contains(zeroBasedIndex) ? rows[zeroBasedIndex] : nil
        } else {
            selectedRow = rows.first
        }

        guard let selectedRow else {
            lastMediaAction = "Nest writing queue action blocked: no row matched index \(rawIndex ?? "") kind \(rawKind ?? "")."
            updateAgentState()
            return
        }

        performNestWritingNextAction(selectedRow)
    }

    private func nestWritingReadinessPayload() -> [String: Any] {
        let documents = projectStore.project.nestDocuments
        let writingDocuments = documents.filter { $0.source == "human-authored" && $0.kind == "writing" }
        let authoredBlocks = writingDocuments.flatMap(\.blocks).filter { block in
            let authorship = block.authorship.trimmingCharacters(in: .whitespacesAndNewlines).lowercased()
            return authorship == "human-authored" || authorship == "agent-authored" || authorship == "mixed-authorship"
        }
        let sourceContextBlockCount = documents.flatMap(\.blocks).filter { block in
            let authorship = block.authorship.trimmingCharacters(in: .whitespacesAndNewlines).lowercased()
            return authorship == "source-context" || authorship == "seeded-source"
        }.count
        let needsReviewCount = authoredBlocks.filter { block in
            let status = block.reviewStatus.trimmingCharacters(in: .whitespacesAndNewlines).lowercased()
            return status.isEmpty || status.contains("needs") || status.contains("draft") || status == "agent-first-pass"
        }.count
        let canonCount = authoredBlocks.filter { $0.reviewStatus == "canon-approved" }.count
        let agentAuthoredCount = authoredBlocks.filter { $0.authorship == "agent-authored" }.count
        let humanAuthoredCount = authoredBlocks.filter { $0.authorship == "human-authored" }.count
        let mixedAuthorshipCount = authoredBlocks.filter { $0.authorship == "mixed-authorship" }.count
        let reviewStatusCounts = Dictionary(
            grouping: authoredBlocks,
            by: { block in
                let status = block.reviewStatus.trimmingCharacters(in: .whitespacesAndNewlines)
                return status.isEmpty ? "needs-human-review" : status
            }
        ).mapValues(\.count)
        let nextReviewBlock = authoredBlocks
            .filter { block in
                let status = block.reviewStatus.trimmingCharacters(in: .whitespacesAndNewlines).lowercased()
                return status.isEmpty || status.contains("needs") || status.contains("draft") || status == "agent-first-pass"
            }
            .sorted { lhs, rhs in
                let lhsPriority = nestWritingReviewPriority(lhs)
                let rhsPriority = nestWritingReviewPriority(rhs)
                if lhsPriority == rhsPriority {
                    return lhs.updatedAt < rhs.updatedAt
                }
                return lhsPriority < rhsPriority
            }
            .first
        let nextReviewBlockPayload: [String: Any]
        if let block = nextReviewBlock {
            nextReviewBlockPayload = [
                "id": block.id.uuidString,
                "title": firstMeaningfulLine(from: block.text),
                "role": block.role,
                "authorship": block.authorship,
                "reviewStatus": block.reviewStatus,
                "episodeSlug": block.episodeSlug,
                "chapterSlug": block.chapterSlug,
                "selectCommand": "script/agentctl.sh nest-select-block \(block.id.uuidString)",
                "markReviewedCommand": "script/agentctl.sh nest-mark-block human-reviewed \"Reviewed for the next manuscript pass.\" \(block.id.uuidString)",
                "markCanonCommand": "script/agentctl.sh nest-mark-block canon-approved \"Approved as canon manuscript text.\" \(block.id.uuidString)"
            ]
        } else {
            nextReviewBlockPayload = [:]
        }

        let status: String
        let nextAction: String
        if writingDocuments.isEmpty {
            status = "needs-writing-document"
            nextAction = "Create the authored writing layer before treating seeded context as manuscript material."
        } else if authoredBlocks.isEmpty {
            status = "ready-for-first-draft"
            nextAction = "Add a first human, agent, or mixed writing block. Keep source context separate until reviewed."
        } else if needsReviewCount > 0 {
            status = "drafting-needs-review"
            nextAction = "Continue drafting, then mark reviewed/canon only after a human or explicit review pass approves it."
        } else {
            status = "writing-loop-active"
            nextAction = "Use the authored layer for new manuscript work while Nest keeps source context available beside it."
        }

        return [
            "model": "quipsly-nest-writing-readiness-v1",
            "status": status,
            "writingDocumentCount": writingDocuments.count,
            "authoredBlockCount": authoredBlocks.count,
            "authoredNeedsReviewCount": needsReviewCount,
            "canonApprovedBlockCount": canonCount,
            "agentAuthoredBlockCount": agentAuthoredCount,
            "humanAuthoredBlockCount": humanAuthoredCount,
            "mixedAuthorshipBlockCount": mixedAuthorshipCount,
            "reviewStatusCounts": reviewStatusCounts,
            "sourceContextBlockCount": sourceContextBlockCount,
            "sourcePolicy": "Authored writing documents are the manuscript candidate layer. Seeded/imported/source context remains review-labeled support material until deliberately rewritten or approved.",
            "creativePartnerPolicy": "Agent-authored blocks may be real publishable drafts when provenance and review state stay visible.",
            "seriousAgentWorkAllowed": true,
            "placeholderPolicy": "Agent-authored does not mean placeholder. Use placeholder only for intentionally disposable fixture material.",
            "canonBoundary": "Writing readiness can guide drafting and review, but it does not canonize text or publish anything by itself.",
            "authorshipVocabulary": [
                "human-authored": "Written directly by a human.",
                "agent-authored": "Created by Codex or another Quipsly as serious first-pass or support material unless explicitly marked as disposable fixture content.",
                "mixed-authorship": "Substantively shaped by both human and agent collaborators.",
                "source-context": "Imported or seeded context used as research/support material, not manuscript canon.",
                "seeded-source": "Automatically seeded source material that must remain review-labeled until deliberately rewritten or approved."
            ] as [String: Any],
            "reviewVocabulary": [
                "agent-first-pass": "Serious agent-created draft awaiting human/agent review.",
                "authored-draft": "Draft writing not yet approved as canon.",
                "needs-human-review": "Requires human review before canon or publication.",
                "human-reviewed": "Reviewed by a human but not necessarily canon-approved.",
                "canon-approved": "Approved as manuscript/project canon.",
                "publication-ready": "Ready to travel into Tower packaging, still requiring destination receipts after publishing."
            ] as [String: Any],
            "nextAction": nextAction,
            "nextReviewBlock": nextReviewBlockPayload,
            "nextDraftSuggestion": [
                "title": "Episode 1 - Next High Ground Odyssey beat",
                "tags": ["book", "writing", "episode-1", "agent-first-pass"],
                "authorship": "agent-authored",
                "reviewStatus": "agent-first-pass",
                "truth": "Use this when the workflow needs real content. It should be treated as serious first-pass material until reviewed, not as fake filler.",
                "appendCommand": "script/agentctl.sh nest-append-block \"Episode 1 - Next High Ground Odyssey beat\" \"<draft text>\" \"book,writing,episode-1\" writing episode-1 agent-authored \"serious first pass created to move the Nest Studio Tower loop\" agent-first-pass",
                "shortcutCommand": "script/agentctl.sh nest-serious-draft \"Episode 1 - Next High Ground Odyssey beat\" \"<draft text>\" episode-1 \"book,writing,episode-1,agent-first-pass\" \"serious first pass created to move the Nest Studio Tower loop\"",
                "fileCommand": "script/agentctl.sh nest-serious-draft-file \"Episode 1 - The Wednesday Rule\" /Users/wall-e/Dev/high-ground-studio/docs/quipsly/content-drafts/hgo-episode-1-the-wednesday-rule-agent-first-pass.md episode-1 \"book,writing,episode-1,agent-first-pass\" \"agent first-pass draft created to dogfood the Nest Studio Tower loop\""
                ,"towerPublicationPacketPath": "/Users/wall-e/Dev/high-ground-studio/docs/quipsly/publication-packets/hgo-episode-1-the-wednesday-rule-writing-publication-packet.md"
            ] as [String: Any],
            "nextActionQueue": nestWritingNextActionRows().map { row in row as [String: Any] },
            "commands": [
                "ensureWritingDocument": "script/agentctl.sh nest-ensure-writing-document",
                "appendSeriousAgentDraft": "script/agentctl.sh nest-serious-draft \"Title\" \"Draft text\" episode-1 \"book,writing,episode-1,agent-first-pass\" \"why this draft exists\"",
                "appendSeriousAgentDraftFromFile": "script/agentctl.sh nest-serious-draft-file \"Episode 1 - The Wednesday Rule\" /Users/wall-e/Dev/high-ground-studio/docs/quipsly/content-drafts/hgo-episode-1-the-wednesday-rule-agent-first-pass.md episode-1 \"book,writing,episode-1,agent-first-pass\" \"agent first-pass draft created to dogfood the Nest Studio Tower loop\"",
                "reviewEpisode1WritingPublicationPacket": "open /Users/wall-e/Dev/high-ground-studio/docs/quipsly/publication-packets/hgo-episode-1-the-wednesday-rule-writing-publication-packet.md",
                "reviewEpisode1WritingPublicationPacketCli": "script/agentctl.sh publication-writing-packet",
                "appendWritingBlock": "script/agentctl.sh nest-append-block \"Title\" \"Text\" \"book,writing\" writing \"\" agent-authored \"why this draft exists\" agent-first-pass",
                "reviewSelectedBlock": "script/agentctl.sh nest-mark-block human-reviewed \"review note\" <block-id>",
                "approveSelectedBlock": "script/agentctl.sh nest-mark-block canon-approved \"approval note\" <block-id>"
            ] as [String: Any]
        ]
    }

    private func nestPayload() -> [String: Any] {
        let documents = projectStore.project.nestDocuments.sorted { $0.updatedAt > $1.updatedAt }
        let selectedDocument = selectedNestDocumentValue() ?? documents.first
        let selectedBlock = selectedNestBlockValue(in: selectedDocument)
        let blockCount = projectStore.project.nestDocuments.reduce(0) { $0 + $1.blocks.count }
        let seededContextAvailable = projectStore.project.nestDocuments.contains { $0.source == "seeded-episodes-1-3-local-context" }
        let writingDocumentAvailable = projectStore.project.nestDocuments.contains { $0.source == "human-authored" && $0.kind == "writing" }
        let allBlockSummaries = projectStore.project.nestDocuments
            .flatMap { document in
                document.blocks.map { block in
                    [
                        "id": block.id.uuidString,
                        "documentId": document.id.uuidString,
                        "documentTitle": document.title,
                        "documentKind": document.kind,
                        "role": block.role,
                        "authorship": block.authorship,
                        "reviewStatus": block.reviewStatus,
                        "episodeSlug": block.episodeSlug,
                        "chapterSlug": block.chapterSlug,
                        "tags": block.tags,
                        "textPreview": String(block.text.prefix(180))
                    ] as [String: Any]
                }
            }
        let outlineEntries = nestOutlineEntries()
        let outlinePayloadEntries: [[String: Any]] = outlineEntries.map { entry in
            return [
                "kind": entry.kind,
                "id": entry.id.uuidString,
                "documentId": entry.documentId.uuidString,
                "documentTitle": entry.documentTitle,
                "title": entry.title,
                "chapterSlug": entry.chapterSlug,
                "chapterTitle": entry.chapterTitle,
                "episodeSlug": entry.episodeSlug,
                "role": entry.role,
                "authorship": entry.authorship,
                "reviewStatus": entry.reviewStatus,
                "titleSource": "first-line-normalized",
                "tags": entry.tags,
                "selectCommand": "script/agentctl.sh nest-select-block \(entry.id.uuidString)"
            ] as [String: Any]
        }
        let reviewStatusCounts = Dictionary(
            grouping: projectStore.project.nestDocuments.flatMap(\.blocks),
            by: { block in
                block.reviewStatus.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty ? "needs-human-review" : block.reviewStatus
            }
        ).mapValues(\.count)
        let authorshipCounts = Dictionary(
            grouping: projectStore.project.nestDocuments.flatMap(\.blocks),
            by: { block in
                block.authorship.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty ? "unknown-authorship" : block.authorship
            }
        ).mapValues(\.count)
        let formatter = ISO8601DateFormatter()
        let documentSummaries = documents.map { document in
            [
                "id": document.id.uuidString,
                "title": document.title,
                "kind": document.kind,
                "status": document.status,
                "source": document.source,
                "tags": document.tags,
                "blockCount": document.blocks.count,
                "updatedAt": formatter.string(from: document.updatedAt)
            ] as [String: Any]
        }
        let selectedDocumentPayload: [String: Any]
        if let selectedDocument {
            let blockSummaries = selectedDocument.blocks
                .sorted { $0.sortIndex < $1.sortIndex }
                .map { block in
                    [
                        "id": block.id.uuidString,
                        "role": block.role,
                        "authorship": block.authorship,
                        "reviewStatus": block.reviewStatus,
                        "episodeSlug": block.episodeSlug,
                        "chapterSlug": block.chapterSlug,
                        "tags": block.tags,
                        "textPreview": String(block.text.prefix(160))
                    ] as [String: Any]
                }
            selectedDocumentPayload = [
                "id": selectedDocument.id.uuidString,
                "title": selectedDocument.title,
                "kind": selectedDocument.kind,
                "status": selectedDocument.status,
                "source": selectedDocument.source,
                "tags": selectedDocument.tags,
                "notes": selectedDocument.notes,
                "blockCount": selectedDocument.blocks.count,
                "blocks": blockSummaries,
                "updatedAt": formatter.string(from: selectedDocument.updatedAt)
            ]
        } else {
            selectedDocumentPayload = [:]
        }
        let selectedBlockPayload: [String: Any]
        if let selectedBlock {
            selectedBlockPayload = [
                "id": selectedBlock.id.uuidString,
                "role": selectedBlock.role,
                "text": selectedBlock.text,
                "tags": selectedBlock.tags,
                "authorship": selectedBlock.authorship,
                "provenanceNote": selectedBlock.provenanceNote,
                "episodeSlug": selectedBlock.episodeSlug,
                "chapterSlug": selectedBlock.chapterSlug,
                "sourcePath": selectedBlock.sourcePath,
                "sourceURL": selectedBlock.sourceURL,
                "reviewStatus": selectedBlock.reviewStatus,
                "sortIndex": selectedBlock.sortIndex,
                "updatedAt": formatter.string(from: selectedBlock.updatedAt)
            ]
        } else {
            selectedBlockPayload = [:]
        }

        return [
            "model": "quipsly-nest-context-v1",
            "truth": "Seeded context is review-labeled scaffolding. Human-authored Nest writing is the canon candidate layer. Do not silently promote transcript/import text to manuscript truth.",
            "creativePartnerTruth": "Codex and Quipslys can create serious first-pass writing and content packets. The Nest must expose authorship, provenance, review state, and canon boundaries instead of bottlenecking on human-supplied text.",
            "documentCount": projectStore.project.nestDocuments.count,
            "blockCount": blockCount,
            "seededContextAvailable": seededContextAvailable,
            "writingDocumentAvailable": writingDocumentAvailable,
            "authorshipCounts": authorshipCounts,
            "reviewStatusCounts": reviewStatusCounts,
            "writingReadiness": nestWritingReadinessPayload(),
            "selectedDocumentId": selectedDocument?.id.uuidString ?? "",
            "selectedBlockId": selectedBlock?.id.uuidString ?? "",
            "selectedDocument": selectedDocumentPayload,
            "selectedBlock": selectedBlockPayload,
            "blocks": allBlockSummaries,
            "outline": [
                "model": "quipsly-nest-derived-outline-v1",
                "truth": "Derived from Chapter/Episode block metadata. Do not maintain a separate outline truth.",
                "entryCount": outlineEntries.count,
                "chapterCount": outlineEntries.filter { $0.kind == "chapter" }.count,
                "episodeCount": outlineEntries.filter { $0.kind == "episode" }.count,
                "entries": outlinePayloadEntries
            ] as [String: Any],
            "documents": documentSummaries,
            "fallbackSourcePolicy": "Use local transcript/import artifacts first. If missing, use the published HighGroundOdyssey.com episode page or YouTube reference as fallback context and keep needs-human-review status.",
            "agentCommands": [
                "GET /left_workbench?mode=nest",
                "GET /nest_seed_context",
                "GET /nest_ensure_writing_document",
                "GET /nest_append_block?title=<title>&text=<text>&tags=<comma-tags>&role=writing&episode=<episode-slug>&authorship=agent-authored&provenance=<why>",
                "GET /nest_select_block?block_id=<block-id>",
                "GET /nest_update_block?block_id=<block-id>&role=chapter-marker|episode-marker|writing&tags=<comma-tags>&episode=<episode-slug>&chapter=<chapter-slug>&note=<why>",
                "GET /nest_mark_block?status=human-reviewed&note=<why>",
                "GET /nest_mark_block?status=canon-approved&note=<why>"
            ]
        ]
    }

    private func nestWritingPacketPayload() -> [String: Any] {
        let formatter = ISO8601DateFormatter()
        let project = projectStore.project
        let documents = project.nestDocuments.sorted { $0.updatedAt > $1.updatedAt }
        let writingDocuments = documents.filter { document in
            document.kind == "writing" && document.source == "human-authored"
        }
        let authoredBlocks = writingDocuments
            .flatMap { document in
                document.blocks.map { block in (document: document, block: block) }
            }
            .filter { item in nestWritingIsAuthoredCandidate(item.block) }
            .sorted { lhs, rhs in
                let lhsPriority = nestWritingReviewPriority(lhs.block)
                let rhsPriority = nestWritingReviewPriority(rhs.block)
                if lhsPriority == rhsPriority {
                    return lhs.block.sortIndex < rhs.block.sortIndex
                }
                return lhsPriority < rhsPriority
            }
        let reviewBlocks = authoredBlocks.filter { item in
            let status = item.block.reviewStatus.trimmingCharacters(in: .whitespacesAndNewlines).lowercased()
            return status != "human-reviewed"
                && status != "canon-approved"
                && status != "publication-ready"
        }
        let sourceContextBlocks = documents
            .flatMap { document in
                document.blocks.map { block in (document: document, block: block) }
            }
            .filter { item in
                item.block.authorship.trimmingCharacters(in: .whitespacesAndNewlines).lowercased() == "source-context"
            }
            .sorted { lhs, rhs in
                if lhs.document.updatedAt == rhs.document.updatedAt {
                    return lhs.block.sortIndex < rhs.block.sortIndex
                }
                return lhs.document.updatedAt > rhs.document.updatedAt
            }
        let selectedDocument = selectedNestDocumentValue() ?? documents.first
        let selectedBlock = selectedNestBlockValue(in: selectedDocument)

        let authoredPayload = authoredBlocks.map { item in
            [
                "id": item.block.id.uuidString,
                "documentId": item.document.id.uuidString,
                "documentTitle": item.document.title,
                "role": item.block.role,
                "text": item.block.text,
                "tags": item.block.tags,
                "authorship": item.block.authorship,
                "provenanceNote": item.block.provenanceNote,
                "episodeSlug": item.block.episodeSlug,
                "chapterSlug": item.block.chapterSlug,
                "reviewStatus": item.block.reviewStatus,
                "sortIndex": item.block.sortIndex,
                "updatedAt": formatter.string(from: item.block.updatedAt),
                "selectCommand": "script/agentctl.sh nest-select-block \(item.block.id.uuidString)"
            ] as [String: Any]
        }
        let reviewPayload = reviewBlocks.prefix(12).map { item in
            [
                "id": item.block.id.uuidString,
                "title": firstMeaningfulLine(from: item.block.text),
                "role": item.block.role,
                "authorship": item.block.authorship,
                "reviewStatus": item.block.reviewStatus,
                "episodeSlug": item.block.episodeSlug,
                "chapterSlug": item.block.chapterSlug,
                "textPreview": String(item.block.text.prefix(360)),
                "selectCommand": "script/agentctl.sh nest-select-block \(item.block.id.uuidString)",
                "markHumanReviewedCommand": "script/agentctl.sh nest-mark-block human-reviewed \"Reviewed and accepted for next writing pass.\" \(item.block.id.uuidString)",
                "markCanonCommand": "script/agentctl.sh nest-mark-block canon-approved \"Approved as canon manuscript text.\" \(item.block.id.uuidString)"
            ] as [String: Any]
        }
        let sourceContextPayload = sourceContextBlocks.prefix(20).map { item in
            [
                "id": item.block.id.uuidString,
                "documentTitle": item.document.title,
                "role": item.block.role,
                "episodeSlug": item.block.episodeSlug,
                "chapterSlug": item.block.chapterSlug,
                "reviewStatus": item.block.reviewStatus,
                "sourcePath": item.block.sourcePath,
                "sourceURL": item.block.sourceURL,
                "tags": item.block.tags,
                "textPreview": String(item.block.text.prefix(420))
            ] as [String: Any]
        }
        let selectedBlockPayload: [String: Any]
        if let selectedBlock {
            selectedBlockPayload = [
                "id": selectedBlock.id.uuidString,
                "role": selectedBlock.role,
                "authorship": selectedBlock.authorship,
                "reviewStatus": selectedBlock.reviewStatus,
                "episodeSlug": selectedBlock.episodeSlug,
                "chapterSlug": selectedBlock.chapterSlug,
                "tags": selectedBlock.tags,
                "textPreview": String(selectedBlock.text.prefix(500)),
                "selectCommand": "script/agentctl.sh nest-select-block \(selectedBlock.id.uuidString)"
            ]
        } else {
            selectedBlockPayload = [:]
        }

        return [
            "model": "quipsly-nest-writing-packet",
            "version": "2026-06-20.nest-writing-packet.v1",
            "generatedAt": formatter.string(from: Date()),
            "sessionName": normalizedActiveSessionName(),
            "projectTitle": project.title,
            "truth": "This packet carries authored writing work and source-context summaries. It is a handoff artifact, not manuscript canon.",
            "creativePartnerPolicy": "Codex and Quipslys may create serious first-pass writing and content packets. Authorship, provenance, review state, source context, and canon/publication boundaries make the work inspectable.",
            "sourcePolicy": "Seeded source-context blocks can inform writing but must not be silently promoted to manuscript truth.",
            "authorshipPolicy": [
                "agent-authored": "May be serious publishable first-pass work, not placeholder by default.",
                "mixed-authorship": "Use when a human and agent have both materially shaped the text.",
                "source-context": "Use for imported/seeded context that supports writing but should not masquerade as canon."
            ] as [String: Any],
            "writingReadiness": nestWritingReadinessPayload(),
            "selectedBlock": selectedBlockPayload,
            "authoredBlockCount": authoredPayload.count,
            "reviewQueueCount": reviewBlocks.count,
            "sourceContextSummaryCount": sourceContextPayload.count,
            "sourceContextStatus": sourceContextPayload.isEmpty ? "not-loaded-in-current-session" : "available",
            "sourceContextRecovery": sourceContextPayload.isEmpty ? [
                "truth": "No source-context blocks were present in the current running Nest state. This does not invalidate authored writing; it only means the packet lacks nearby research/source scaffolding.",
                "safeCommand": "script/agentctl.sh nest-seed-context",
                "followUp": "Regenerate the Nest writing packet after seeding context if source material should travel with this handoff.",
                "fallbackReferences": [
                    "Episode 1 YouTube": "https://youtu.be/96LN__TA-T8",
                    "Episode 2 YouTube": "https://youtu.be/7Rn4rV2cLy4",
                    "Episode 3 YouTube": "https://youtu.be/rf3L1xki_Nk",
                    "HGO published site": "https://highgroundodyssey.com"
                ]
            ] as [String: Any] : [
                "truth": "Source-context summaries are present. Use them as scaffolding and review context, not manuscript canon.",
                "safeCommand": "",
                "followUp": "Review source context before promoting authored drafts toward canon."
            ] as [String: Any],
            "authoredBlocks": authoredPayload,
            "reviewQueue": reviewPayload,
            "sourceContextSummaries": sourceContextPayload,
            "outline": nestPayload()["outline"] ?? [:],
            "agentCommands": [
                "inspect": "script/agentctl.sh nest-writing-packet",
                "generatePacket": "script/agentctl.sh nest-writing-packet-generate /absolute/output/folder optional-basename",
                "nextAction": "script/agentctl.sh nest-writing-next-action 1",
                "appendSeriousAgentDraft": "script/agentctl.sh nest-serious-draft \"Title\" \"Draft text\" episode-1 \"book,writing,episode-1,agent-first-pass\" \"why this draft exists\"",
                "appendSeriousAgentDraftFromFile": "script/agentctl.sh nest-serious-draft-file \"Episode 1 - The Wednesday Rule\" /Users/wall-e/Dev/high-ground-studio/docs/quipsly/content-drafts/hgo-episode-1-the-wednesday-rule-agent-first-pass.md episode-1 \"book,writing,episode-1,agent-first-pass\" \"agent first-pass draft created to dogfood the Nest Studio Tower loop\"",
                "reviewEpisode1WritingPublicationPacket": "open /Users/wall-e/Dev/high-ground-studio/docs/quipsly/publication-packets/hgo-episode-1-the-wednesday-rule-writing-publication-packet.md",
                "reviewEpisode1WritingPublicationPacketCli": "script/agentctl.sh publication-writing-packet",
                "appendWriting": "script/agentctl.sh nest-append-block \"Title\" \"Text\" \"book,episode-context\" writing episode-1 agent-authored \"why this was created\" agent-first-pass",
                "selectBlock": "script/agentctl.sh nest-select-block <block-id>",
                "markReviewed": "script/agentctl.sh nest-mark-block human-reviewed \"review note\" <block-id>",
                "markCanon": "script/agentctl.sh nest-mark-block canon-approved \"canon approval note\" <block-id>"
            ] as [String: Any],
            "handoffRules": [
                "Agent-authored work can be serious work, not placeholder by default.",
                "Do not canonize or publish from this packet alone.",
                "Use reviewStatus and provenanceNote before deciding what needs human review.",
                "Use source-context blocks as context, not hidden manuscript truth."
            ]
        ]
    }

    private func selectedShortClipValue() -> ShortClipCandidate? {
        guard let selectedShortClipId,
              let sequence = projectStore.activeSequence else {
            return nil
        }
        return sequence.shortClipQueue.first { $0.id == selectedShortClipId }
    }

    private func updateSelectedShortClip(_ mutate: (inout ShortClipCandidate) -> Void) {
        guard let selectedShortClipId,
              var sequence = projectStore.activeSequence,
              let index = sequence.shortClipQueue.firstIndex(where: { $0.id == selectedShortClipId }) else {
            lastMediaAction = "Short update blocked: no selected short recipe"
            updateAgentState()
            return
        }

        mutate(&sequence.shortClipQueue[index])
        sequence.shortClipQueue[index].updatedAt = Date()
        if sequence.shortClipQueue[index].destinationPresets.isEmpty {
            let title = sequence.shortClipQueue[index].title
            sequence.shortClipQueue[index].destinationPresets = sequence.shortClipQueue[index].destinations.map {
                ShortDestinationPreset(platform: $0, title: title)
            }
        }

        projectStore.updateSequence(sequence, undoManager: nil, actionName: "Update Short Packet")
        lastMediaAction = "Updated short recipe: \(sequence.shortClipQueue[index].title)"
        scheduleAutosave(reason: "updated short recipe")
        updateAgentState()
    }

    private func updateSelectedShortClipField(field rawField: String?, value: String?) {
        let field = (rawField ?? "").lowercased().trimmingCharacters(in: .whitespacesAndNewlines)
        let newValue = value ?? ""
        updateSelectedShortClip { clip in
            switch field {
            case "title":
                clip.title = newValue
            case "hook", "hooktext", "hook_text":
                clip.hookText = newValue
            case "caption", "captiondraft", "caption_draft":
                clip.captionDraft = newValue
            case "overlay", "primaryoverlay", "primary_overlay", "primaryoverlaytext", "primary_overlay_text":
                clip.primaryOverlayText = newValue
            case "notes":
                clip.notes = newValue
            case "publishnotes", "publish_notes", "publishnote", "publish_note":
                clip.publishNotes = appendLine(newValue, to: clip.publishNotes)
            case "replacepublishnotes", "replace_publish_notes":
                clip.publishNotes = newValue
            case "review", "reviewstatus", "review_status":
                clip.reviewStatus = newValue
            case "export", "exportstatus", "export_status":
                clip.exportStatus = newValue
            case "status":
                clip.status = newValue
            default:
                clip.notes = clip.notes.isEmpty
                    ? "Ignored unknown short field: \(field)"
                    : "\(clip.notes)\nIgnored unknown short field: \(field)"
            }
        }
    }

    private func applySelectedShortReviewDecision(status rawStatus: String?, notes rawNotes: String?) {
        applyShortReviewDecision(id: selectedShortClipId?.uuidString, status: rawStatus, notes: rawNotes)
    }

    private func applyShortReviewDecision(id rawId: String?, status rawStatus: String?, notes rawNotes: String?) {
        guard let rawId,
              let shortId = UUID(uuidString: rawId),
              let sequence = projectStore.activeSequence,
              sequence.shortClipQueue.contains(where: { $0.id == shortId }) else {
            lastMediaAction = "Short review blocked: target short not found in loaded session"
            updateAgentState()
            return
        }
        selectedShortClipId = shortId
        let normalized = (rawStatus ?? "draft")
            .lowercased()
            .trimmingCharacters(in: .whitespacesAndNewlines)
            .replacingOccurrences(of: "_", with: "-")
            .replacingOccurrences(of: " ", with: "-")

        let status: String
        let defaultNote: String
        switch normalized {
        case "keep", "approve", "approved", "publish", "queue":
            status = "keep"
            defaultNote = "Review decision: keep for social publication queue."
        case "refine", "revise", "needs-work", "needs-edit", "needs-review":
            status = "refine"
            defaultNote = "Review decision: refine before publication."
        case "reject", "rejected", "skip", "no":
            status = "reject"
            defaultNote = "Review decision: reject for publication, preserve as learning/context."
        default:
            status = "draft"
            defaultNote = "Review decision reset to draft."
        }

        let note = (rawNotes ?? defaultNote).trimmingCharacters(in: .whitespacesAndNewlines)
        updateSelectedShortClip { clip in
            clip.reviewStatus = status
            if !note.isEmpty && !clip.notes.contains(note) {
                clip.notes = clip.notes.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty
                    ? note
                    : "\(clip.notes)\n\(note)"
            }
        }
        lastMediaAction = "Marked short \(status.uppercased()) for review workflow"
        updateAgentState()
    }

    private func previewSelectedShortClip(play: Bool) {
        guard let clip = selectedShortClipValue(),
              let sequence = projectStore.activeSequence else {
            lastMediaAction = "Short preview blocked: no selected short recipe"
            updateAgentState()
            return
        }

        let start = sequenceStartTime(for: clip, in: sequence)
        let renderDuration = max(0.15, shortClipExportRanges(for: clip, in: sequence).reduce(0) { $0 + $1.duration })
        let end = start + renderDuration
        playbackEngine.playbackMode = .playEdit
        playbackEngine.playbackFormat = .vertical9x16
        playbackEngine.updateValidRanges(for: sequence)
        rebuildPlayer()
        playbackEngine.scrub(to: start)
        if play {
            shortPreviewClipId = clip.id
            shortPreviewStopAt = end
            playbackEngine.play()
        } else {
            shortPreviewClipId = nil
            shortPreviewStopAt = nil
            playbackEngine.pause()
        }
        lastMediaAction = play
            ? String(format: "Previewing short recipe from %.2fs to %.2fs: %@", start, end, clip.title)
            : String(format: "Cued short recipe at %.2fs: %@", start, clip.title)
        updateAgentState()
    }

    private func enforceSelectedShortPreviewStop(at playhead: Double) {
        guard let stopAt = shortPreviewStopAt,
              playbackEngine.isPlaying,
              playhead >= stopAt else {
            return
        }

        let stoppedClipId = shortPreviewClipId
        shortPreviewClipId = nil
        shortPreviewStopAt = nil
        playbackEngine.pause()
        playbackEngine.scrub(to: stopAt)
        if let stoppedClipId,
           let sequence = projectStore.activeSequence,
           let clip = sequence.shortClipQueue.first(where: { $0.id == stoppedClipId }) {
            lastMediaAction = String(format: "Short preview stopped at out point %.2fs: %@", stopAt, clip.title)
        } else {
            lastMediaAction = String(format: "Short preview stopped at out point %.2fs", stopAt)
        }
        updateAgentState()
    }

    private func setSelectedShortBoundaryFromPlayhead(_ boundary: String) {
        adjustSelectedShortBoundary(boundary, targetSequenceTime: playbackEngine.playhead, delta: nil)
    }

    private func nudgeSelectedShortBoundary(_ boundary: String, by delta: Double) {
        adjustSelectedShortBoundary(boundary, targetSequenceTime: nil, delta: delta)
    }

    private func adjustSelectedShortBoundary(_ boundary: String, targetSequenceTime: Double?, delta: Double?) {
        guard let selectedShortClipId,
              var sequence = projectStore.activeSequence,
              let index = sequence.shortClipQueue.firstIndex(where: { $0.id == selectedShortClipId }) else {
            lastMediaAction = "Short range update blocked: no selected short recipe"
            updateAgentState()
            return
        }

        let minimumDuration = 0.15
        var clip = sequence.shortClipQueue[index]
        let sourceOffset = sourceOffset(for: clip, in: sequence)
        var start = sequenceStartTime(for: clip, in: sequence)
        var end = start + max(minimumDuration, clip.duration)
        let normalizedBoundary = boundary.lowercased().trimmingCharacters(in: .whitespacesAndNewlines)
        let maxSequenceEnd = max(minimumDuration, sequence.duration)

        switch normalizedBoundary {
        case "start", "in":
            let requested = targetSequenceTime ?? (start + (delta ?? 0))
            start = min(max(0, requested), max(0, end - minimumDuration))
        case "end", "out":
            let requested = targetSequenceTime ?? (end + (delta ?? 0))
            end = max(start + minimumDuration, min(maxSequenceEnd, requested))
        default:
            lastMediaAction = "Short range update blocked: unknown boundary \(boundary)"
            updateAgentState()
            return
        }

        if end > maxSequenceEnd {
            end = maxSequenceEnd
            start = min(start, max(0, end - minimumDuration))
        }

        clip.startTime = max(0, start - sourceOffset)
        clip.duration = max(minimumDuration, end - start)
        if clip.segments.isEmpty {
            clip.segments = [ShortClipSegment(
                title: "Segment 1",
                startTime: clip.startTime,
                duration: clip.duration,
                sourceLaneId: clip.sourceLaneId,
                sourceTagId: clip.sourceTagId
            )]
        } else {
            clip.segments[0].startTime = clip.startTime
            clip.segments[0].duration = clip.duration
            clip.segments[0].updatedAt = Date()
        }
        clip.exportStatus = clip.exportStatus == "exported" ? "not-exported" : clip.exportStatus
        clip.updatedAt = Date()
        sequence.shortClipQueue[index] = clip
        projectStore.updateSequence(sequence, undoManager: nil, actionName: "Adjust Short Range")
        scheduleAutosave(reason: "adjusted short range")
        playbackEngine.playbackFormat = .vertical9x16
        playbackEngine.scrub(to: start)
        lastMediaAction = String(format: "Adjusted short %@ to %.2fs -> %.2fs", normalizedBoundary, start, end)
        requestTimelineFocus(reason: "Focused adjusted short recipe on the Episode Trail Map")
        updateAgentState()
    }

    private func appendSelectedDecisionToSelectedShort() {
        guard let selectedShortClipId,
              let selected = selectedDecision(),
              selected.tag.type == .active,
              var sequence = projectStore.activeSequence,
              let index = sequence.shortClipQueue.firstIndex(where: { $0.id == selectedShortClipId }) else {
            lastMediaAction = "Short segment add blocked: select a short recipe and a SHOW decision"
            updateAgentState()
            return
        }

        let segment = ShortClipSegment(
            title: "Segment \(sequence.shortClipQueue[index].segments.count + 1)",
            startTime: max(0, selected.tag.startTime),
            duration: selected.tag.duration,
            sourceLaneId: selected.lane.id,
            sourceTagId: selected.tag.id,
            notes: "Added from selected SHOW decision over the whole synced episode spine."
        )
        sequence.shortClipQueue[index].segments.append(segment)
        sequence.shortClipQueue[index].exportStatus = sequence.shortClipQueue[index].exportStatus == "exported" ? "not-exported" : sequence.shortClipQueue[index].exportStatus
        sequence.shortClipQueue[index].updatedAt = Date()
        projectStore.updateSequence(sequence, undoManager: nil, actionName: "Add Short Segment")
        selectedLaneId = selected.lane.id
        selectedTagId = selected.tag.id
        playbackEngine.playbackFormat = .vertical9x16
        playbackEngine.scrub(to: selected.tag.startTime)
        lastMediaAction = "Added SHOW decision to short recipe: \(sequence.shortClipQueue[index].title)"
        requestTimelineFocus(reason: "Focused multi-segment short recipe on the Episode Trail Map")
        scheduleAutosave(reason: "added short segment")
        updateAgentState()
    }

    private func exportSelectedShortClipForAgent(directoryPath: String?, basename: String?) {
        guard var sequence = projectStore.activeSequence else {
            lastMediaAction = "Short export blocked: no active sequence"
            blockExportStatus(kind: "selected-short-9x16", reason: "No active sequence loaded.")
            updateAgentState()
            return
        }

        guard let selectedShortClipId,
              let index = sequence.shortClipQueue.firstIndex(where: { $0.id == selectedShortClipId }) else {
            lastMediaAction = "Short export blocked: no selected short recipe"
            blockExportStatus(kind: "selected-short-9x16", reason: "Select a short recipe before exporting.")
            updateAgentState()
            return
        }

        let readiness = mediaReadinessSummary()
        guard readiness.isProductionReady else {
            lastMediaAction = "Short export blocked: \(readiness.detail)"
            blockExportStatus(kind: "selected-short-9x16", reason: readiness.detail)
            updateAgentState()
            return
        }

        let clip = sequence.shortClipQueue[index]
        let exportRanges = shortClipExportRanges(for: clip, in: sequence)
        let exportDuration = exportRanges.reduce(0) { $0 + $1.duration }
        guard exportDuration.isFinite, exportDuration > 0 else {
            lastMediaAction = "Short export blocked: selected short has no duration"
            blockExportStatus(kind: "selected-short-9x16", reason: "Selected short recipe has no positive duration.")
            updateAgentState()
            return
        }

        let outputDirectory: URL
        if let directoryPath, !directoryPath.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty {
            outputDirectory = URL(fileURLWithPath: directoryPath, isDirectory: true)
        } else {
            outputDirectory = defaultLocalExportDirectory()
                .appendingPathComponent("shorts", isDirectory: true)
        }

        let requestedBasename = basename?.trimmingCharacters(in: .whitespacesAndNewlines)
        let cleanBasename = sanitizedExportBasename(
            requestedBasename?.isEmpty == false
            ? requestedBasename!
            : "\(normalizedActiveSessionName())-\(clip.title)"
        )
        let outputURL = outputDirectory.appendingPathComponent("\(cleanBasename)-9x16-short.mp4")

        sequence.shortClipQueue[index].exportStatus = "exporting"
        sequence.shortClipQueue[index].publishNotes = appendLine(
            "Export started: \(outputURL.path)",
            to: sequence.shortClipQueue[index].publishNotes
        )
        sequence.shortClipQueue[index].updatedAt = Date()
        projectStore.updateSequence(sequence, undoManager: nil, actionName: "Export Short Clip")
        scheduleAutosave(reason: "started short export")

        beginExportStatus(kind: "selected-short-9x16", outputURLs: [outputURL], proofSeconds: exportDuration)
        playbackEngine.playbackFormat = .vertical9x16
        lastMediaAction = "Short export started: \(clip.title)"
        updateAgentState()

        Task {
            do {
                try await ExportEngine.shared.export(
                    sequence: sequence,
                    to: outputURL,
                    format: .vertical9x16,
                    allowExternalOriginalMedia: false,
                    allowedOriginalMediaRootPath: nil,
                    sequenceRanges: exportRanges,
                    allowPixelTextOverlays: false,
                    primaryOverlayText: burnedInPrimaryOverlayText(for: clip),
                    captionText: burnedInCaptionText(for: clip)
                )

                await MainActor.run {
                    markShortClipExportResult(
                        id: selectedShortClipId,
                        status: "exported",
                        note: shortExportSuccessNote(outputURL: outputURL, clip: clip)
                    )
                    completeExportStatus(outputURLs: [outputURL])
                    lastMediaAction = "Short export completed: \(outputURL.path)"
                    updateAgentState()
                }
            } catch {
                await MainActor.run {
                    markShortClipExportResult(
                        id: selectedShortClipId,
                        status: "export-failed",
                        note: "Export failed: \(error.localizedDescription)"
                    )
                    failExportStatus(error: error)
                    lastMediaAction = "Short export failed: \(error.localizedDescription)"
                    errorMessage = lastMediaAction
                    showErrorAlert = true
                    updateAgentState()
                }
            }
        }
    }

    private func burnedInCaptionText(for clip: ShortClipCandidate) -> String? {
        guard shortPixelTextBurnInIsEnabled else {
            return nil
        }

        let caption = clip.captionDraft.trimmingCharacters(in: .whitespacesAndNewlines)
        guard !caption.isEmpty else {
            return nil
        }

        let lowered = caption.lowercased()
        let draftMarkers = [
            "rough transcript:",
            "rough transcript",
            "draft transcript:",
            "draft caption:",
            "caption draft:"
        ]
        if draftMarkers.contains(where: { lowered.hasPrefix($0) }) {
            return nil
        }

        guard captionBurnInDirective(for: clip) == "approved" else {
            return nil
        }

        return caption
    }

    private func captionBurnInDirective(for clip: ShortClipCandidate) -> String {
        let lines = clip.publishNotes
            .lowercased()
            .components(separatedBy: .newlines)

        var directive = "metadata"
        for line in lines {
            if line.contains("caption-face-safe-lower-rail-burn-in-ok")
                || line.contains("caption lower rail burn in ok")
                || line.contains("caption lower-rail approved")
                || line.contains("caption no-face-zone lower rail approved") {
                directive = "approved"
            }
            if directive != "approved"
                && (line.contains("caption-face-safe-burn-in-ok")
                    || line.contains("caption face safe burn in ok")
                    || line.contains("caption face-safe approved")
                    || line.contains("caption no-face-zone approved")
                    || line.contains("caption-burn-in-ok")
                    || line.contains("caption burn in ok")
                    || line.contains("caption safe-zone approved")
                    || line.contains("caption safe zone approved")) {
                directive = "needs_face_safe_review"
            }
            if line.contains("caption-burn-in-hold")
                || line.contains("caption held")
                || line.contains("caption metadata only")
                || line.contains("caption sidecar only") {
                directive = "held"
            }
        }
        return directive
    }

    private func primaryOverlayBurnInDirective(for clip: ShortClipCandidate) -> String {
        let lines = clip.publishNotes
            .lowercased()
            .components(separatedBy: .newlines)

        var directive = "metadata"
        for line in lines {
            if line.contains("face-safe-top-canopy-burn-in-ok")
                || line.contains("top canopy burn in ok")
                || line.contains("overlay top-canopy approved")
                || line.contains("overlay top canopy approved")
                || line.contains("text overlay top-canopy approved") {
                directive = "approved"
            }
            if directive != "approved"
                && (line.contains("face-safe-burn-in-ok")
                    || line.contains("face safe burn in ok")
                    || line.contains("overlay face-safe approved")
                    || line.contains("overlay no-face-zone approved")
                    || line.contains("text overlay face-safe approved")
                    || line.contains("burn-in-ok")
                    || line.contains("burn in ok")
                    || line.contains("overlay approved")
                    || line.contains("text overlay approved")
                    || line.contains("safe-zone approved")
                    || line.contains("safe zone approved")) {
                directive = "needs_face_safe_review"
            }
            if line.contains("burn-in-hold")
                || line.contains("overlay held")
                || line.contains("metadata only")
                || line.contains("keep as metadata") {
                directive = "held"
            }
        }
        return directive
    }

    private func burnedInPrimaryOverlayText(for clip: ShortClipCandidate) -> String? {
        guard shortPixelTextBurnInIsEnabled else {
            return nil
        }

        let overlay = clip.primaryOverlayText.trimmingCharacters(in: .whitespacesAndNewlines)
        guard !overlay.isEmpty else {
            return nil
        }
        guard primaryOverlayBurnInDirective(for: clip) == "approved" else {
            return nil
        }
        return overlay
    }

    private var shortPixelTextBurnInIsEnabled: Bool {
        // MVP safety rule: text belongs in editable metadata, sidecars, and
        // platform copy until we have a real face-safe placement editor or face
        // detection proof. This prevents hooks/captions from landing on faces
        // in 9:16 exports while keeping the writing data attached to the short.
        false
    }

    private func approveSelectedShortOverlayBurnIn() {
        applySelectedShortOverlayBurnInDecision(decision: "approve", note: nil)
    }

    private func holdSelectedShortOverlayAsMetadata() {
        applySelectedShortOverlayBurnInDecision(decision: "hold", note: nil)
    }

    private func applySelectedShortOverlayBurnInDecision(decision: String?, note: String?) {
        let normalized = (decision ?? "hold")
            .trimmingCharacters(in: .whitespacesAndNewlines)
            .lowercased()

        let isPositionedApproval = [
            "approve-top-canopy",
            "approve_top_canopy",
            "top-canopy-approved",
            "top_canopy_approved",
            "face-safe-top-canopy",
            "face_safe_top_canopy"
        ].contains(normalized)
        let isApprovalRequest = ["approve", "approved", "ok", "burn-in-ok", "safe-zone-approved", "request-review", "request_review"].contains(normalized)
        let auditLine: String
        if isPositionedApproval {
            auditLine = "face-safe-top-canopy-burn-in-ok: Primary overlay approved only for the top canopy rail after visual face-safe review."
        } else if isApprovalRequest {
            auditLine = "face-safe-burn-in-review-needed: Burn-in was requested, but text remains metadata until a positioned safe rail is explicitly approved."
        } else {
            auditLine = "burn-in-hold: Primary overlay held as metadata/platform copy; do not burn into pixels."
        }
        let optionalNote = (note ?? "").trimmingCharacters(in: .whitespacesAndNewlines)

        updateSelectedShortClip { clip in
            clip.publishNotes = appendLine(auditLine, to: clip.publishNotes)
            if !optionalNote.isEmpty {
                clip.publishNotes = appendLine("burn-in-review-note: \(optionalNote)", to: clip.publishNotes)
            }
        }
        lastMediaAction = isPositionedApproval
            ? "Approved selected short overlay for top canopy burn-in"
            : (isApprovalRequest ? "Requested face-safe burn-in review; overlay remains metadata" : "Held selected short overlay as metadata")
        updateAgentState()
    }

    private func markSelectedShortListenThrough(note: String?) {
        let optionalNote = (note ?? "").trimmingCharacters(in: .whitespacesAndNewlines)
        updateSelectedShortClip { clip in
            clip.publishNotes = appendLine(
                "listen-through: Audio, timing, and awkward-cut sanity reviewed.",
                to: clip.publishNotes
            )
            if !optionalNote.isEmpty {
                clip.publishNotes = appendLine("listen-through-note: \(optionalNote)", to: clip.publishNotes)
            }
        }
        lastMediaAction = "Marked selected short listen-through reviewed"
        updateAgentState()
    }

    private func markSelectedShortVisualReview(sheetPath: String?, sourcePath: String?, note: String?) {
        let sheet = (sheetPath ?? "").trimmingCharacters(in: .whitespacesAndNewlines)
        let source = (sourcePath ?? "").trimmingCharacters(in: .whitespacesAndNewlines)
        let optionalNote = (note ?? "").trimmingCharacters(in: .whitespacesAndNewlines)

        updateSelectedShortClip { clip in
            let proofLine = sheet.isEmpty
                ? "visual review: Contact sheet or derivative preview generated for framing/crop/sync sanity."
                : "visual review contact sheet: \(sheet)"
            clip.publishNotes = appendLine(proofLine, to: clip.publishNotes)
            if !source.isEmpty {
                clip.publishNotes = appendLine("visual review source derivative: \(source)", to: clip.publishNotes)
            }
            if !optionalNote.isEmpty {
                clip.publishNotes = appendLine("visual review note: \(optionalNote)", to: clip.publishNotes)
            }
        }
        lastMediaAction = "Recorded visual review evidence for selected short"
        updateAgentState()
    }

    private func applySelectedShortTextReviewDecision(decision: String?, note: String?) {
        let normalized = (decision ?? "approve")
            .trimmingCharacters(in: .whitespacesAndNewlines)
            .lowercased()
        let optionalNote = (note ?? "").trimmingCharacters(in: .whitespacesAndNewlines)
        let needsRewrite = ["rewrite", "needs-rewrite", "needs_rewrite", "refine", "revise", "hold"].contains(normalized)
        let auditLine = needsRewrite
            ? "caption-copy-needs-rewrite: Caption/on-video/platform copy needs another pass before publishing."
            : "caption-copy-ok: Caption/on-video/platform copy reviewed; current burn-in policy is intentional."

        updateSelectedShortClip { clip in
            clip.publishNotes = appendLine(auditLine, to: clip.publishNotes)
            if !optionalNote.isEmpty {
                clip.publishNotes = appendLine("caption-copy-review-note: \(optionalNote)", to: clip.publishNotes)
            }
        }
        lastMediaAction = needsRewrite
            ? "Marked selected short text as needing rewrite"
            : "Marked selected short text reviewed"
        updateAgentState()
    }

    private func captionBurnInPolicyPayload(for clip: ShortClipCandidate) -> [String: Any] {
        let overlay = clip.primaryOverlayText.trimmingCharacters(in: .whitespacesAndNewlines)
        let caption = clip.captionDraft.trimmingCharacters(in: .whitespacesAndNewlines)
        let burnedOverlay = burnedInPrimaryOverlayText(for: clip)?.trimmingCharacters(in: .whitespacesAndNewlines) ?? ""
        let burnedCaption = burnedInCaptionText(for: clip)?.trimmingCharacters(in: .whitespacesAndNewlines) ?? ""

        let status: String
        let detail: String
        if !shortPixelTextBurnInIsEnabled {
            status = "pixel_text_disabled"
            detail = "Overlay and caption drafts are preserved as metadata, sidecars, and platform copy. Pixel burn-in is disabled until Quipsly has explicit face-safe placement tooling."
        } else if caption.isEmpty {
            status = "no_caption_draft"
            detail = "No caption draft is present. Overlay copy still stays metadata unless a positioned safe rail is explicitly approved."
        } else if burnedCaption.isEmpty {
            status = "caption_draft_suppressed"
            detail = "Caption draft is preserved as review metadata/sidecar/platform copy and is not burned into the video without explicit face-safe caption burn-in approval."
        } else {
            status = "caption_burned_in"
            detail = "Caption text has explicit lower-rail caption burn-in approval and will be burned into that positioned rail."
        }

        return [
            "model": "quipsly-short-text-burn-policy",
            "version": "2026-06-19.short-text-burn-policy.v1",
            "status": status,
            "detail": detail,
            "primaryOverlayText": overlay,
            "primaryOverlayDirective": primaryOverlayBurnInDirective(for: clip),
            "burnedInPrimaryOverlayText": burnedOverlay,
            "primaryOverlayBurnedIn": !burnedOverlay.isEmpty,
            "captionDirective": captionBurnInDirective(for: clip),
            "captionDraftPresent": !caption.isEmpty,
            "captionDraftPreview": caption,
            "burnedInCaptionText": burnedCaption,
            "captionBurnedIn": !burnedCaption.isEmpty,
            "pixelTextBurnInEnabled": shortPixelTextBurnInIsEnabled,
            "policy": "Hook, overlay, and caption drafts stay as metadata by default. Current MVP exports do not burn text into pixels; platform captions, SRT sidecars, and editable copy carry the text until explicit face-safe placement tooling exists.",
            "safeRailRule": "No pixel text is exported over the video frame right now. Future burn-in must use a positioned, inspectable safe region rather than generic approval words."
        ]
    }

    private func shortPublicationReadinessPayload(
        for clip: ShortClipCandidate,
        exportExists: Bool,
        exportPath: String,
        reviewStatus review: String,
        textBurnPolicy: [String: Any]
    ) -> [String: Any] {
        let hook = clip.hookText.trimmingCharacters(in: .whitespacesAndNewlines)
        let overlay = clip.primaryOverlayText.trimmingCharacters(in: .whitespacesAndNewlines)
        let notes = clip.publishNotes.lowercased()
        let overlayBurnedIn = (textBurnPolicy["primaryOverlayBurnedIn"] as? Bool) ?? false
        let overlaySuppressed = !overlay.isEmpty && !overlayBurnedIn
        let captionDraftPresent = (textBurnPolicy["captionDraftPresent"] as? Bool) ?? false
        let captionBurnedIn = (textBurnPolicy["captionBurnedIn"] as? Bool) ?? false
        let captionSuppressed = captionDraftPresent && !captionBurnedIn
        let noteLines = notes
            .components(separatedBy: .newlines)
            .map { $0.trimmingCharacters(in: .whitespacesAndNewlines) }
        let hasListenProof = noteLines.contains { line in
            line.hasPrefix("listen-through:")
                || line.hasPrefix("listen-through-ok:")
                || line.hasPrefix("listened-through:")
                || line.hasPrefix("audio-reviewed:")
                || line.hasPrefix("audio-review-ok:")
        }
        let hasTextReviewProof = notes.contains("caption-copy-ok")
            || notes.contains("text-review-ok")
            || notes.contains("copy-reviewed")
            || notes.contains("platform-copy-approved")
            || notes.contains("metadata-copy-approved")
        let textNeedsReview = (overlaySuppressed || captionSuppressed) && !hasTextReviewProof
        let hasVisualProof = review == "keep"
            || review == "refine"
            || review == "reject"
            || notes.contains("contact sheet")
            || notes.contains("visual review")
            || notes.contains("watched")

        var steps: [[String: Any]] = []
        func addStep(
            _ id: String,
            label: String,
            status: String,
            complete: Bool,
            required: Bool = true,
            detail: String,
            command: String = ""
        ) {
            steps.append([
                "id": id,
                "label": label,
                "status": status,
                "complete": complete,
                "required": required,
                "detail": detail,
                "command": command
            ])
        }

        addStep(
            "export-derivative",
            label: "Export 9:16 derivative",
            status: exportExists ? "complete" : "needs_export",
            complete: exportExists,
            detail: exportExists ? "Derivative exists at \(exportPath)." : "Export the selected short before review."
        )
        addStep(
            "visual-review",
            label: "Visual framing/contact-sheet review",
            status: hasVisualProof ? "complete_or_decided" : "needs_visual_review",
            complete: hasVisualProof,
            detail: hasVisualProof ? "A review decision or visual note exists." : "Create a contact sheet or watch the export before marking keep/refine/reject.",
            command: exportExists ? "script/agentctl.sh shorts-contact-sheet \(shellQuoted(exportPath))" : ""
        )
        addStep(
            "listen-through",
            label: "Listen-through / audio sanity",
            status: hasListenProof ? "complete" : "needs_listen_through",
            complete: hasListenProof,
            detail: hasListenProof ? "Publish notes include listen-through/audio review proof." : "Do not call this publish-ready until a human or agent listens for audio, timing, and awkward cuts.",
            command: "script/agentctl.sh shorts-listen-through \"optional notes\""
        )
        let textStatus: String
        let textCompleteDetail: String
        if !textNeedsReview && hasTextReviewProof {
            textStatus = "reviewed_metadata_or_sidecar"
            textCompleteDetail = "Text/caption copy has explicit review proof; suppressed text remains metadata, sidecar, or platform copy unless separately approved for burn-in."
        } else if !textNeedsReview {
            textStatus = "copy_safe_for_current_export"
            textCompleteDetail = "Current text burn policy is safe for this export."
        } else {
            textStatus = "needs_text_review"
            textCompleteDetail = "Recipe text exists but needs explicit copy review before this short can be treated as publish-ready."
        }
        addStep(
            "caption-copy",
            label: "Caption and on-video text review",
            status: textStatus,
            complete: !textNeedsReview,
            detail: textCompleteDetail,
            command: "script/agentctl.sh shorts-text-review approve|rewrite \"optional notes\""
        )
        addStep(
            "hook-platform-copy",
            label: "Hook and platform copy",
            status: (!hook.isEmpty || !overlay.isEmpty) ? "copy_seeded" : "needs_hook_or_copy",
            complete: !hook.isEmpty || !overlay.isEmpty,
            detail: (!hook.isEmpty || !overlay.isEmpty) ? "Hook or overlay copy exists for a first review pass." : "Add a hook, caption, or platform copy before social queue packaging."
        )
        addStep(
            "publication-receipts",
            label: "Platform publication receipts",
            status: "not_published",
            complete: false,
            required: false,
            detail: "Receipts are captured only after manual or integrated posting to YouTube Shorts, Instagram, Facebook, LinkedIn, etc."
        )

        let requiredIncomplete = steps.filter { step in
            ((step["required"] as? Bool) ?? true) && !((step["complete"] as? Bool) ?? false)
        }
        let status: String
        let nextAction: String
        if review == "reject" {
            status = "rejected"
            nextAction = "No publishing action. Preserve as learning data."
        } else if review == "refine" {
            status = "needs_refinement"
            nextAction = "Refine the short recipe, framing, text, or audio, then re-export."
        } else if !exportExists {
            status = "needs_export"
            nextAction = "Export the derivative first."
        } else if review != "keep" {
            status = "needs_human_review_decision"
            nextAction = "Watch/listen, then mark keep, refine, or reject."
        } else if !requiredIncomplete.isEmpty {
            status = "reviewed_but_not_publish_ready"
            nextAction = requiredIncomplete.first?["detail"] as? String ?? "Complete remaining review steps."
        } else {
            status = "ready_for_social_queue"
            nextAction = "Move into reviewed social queue and prepare platform copy/receipt tracking."
        }

        return [
            "model": "quipsly-short-publication-readiness",
            "version": "2026-06-19.short-publication-readiness.v1",
            "status": status,
            "nextAction": nextAction,
            "reviewStatus": review,
            "exportExists": exportExists,
            "readyForSocialQueue": status == "ready_for_social_queue",
            "requiredIncompleteCount": requiredIncomplete.count,
            "requiredIncompleteStepIds": requiredIncomplete.compactMap { $0["id"] as? String },
            "steps": steps,
            "truth": "This is a transparent readiness ladder, not a moral score. It separates artifact existence from publication readiness so humans stay in control."
        ]
    }

    private func exportQueuedShortClipsForAgent(directoryPath: String?, basename: String?) {
        guard var sequence = projectStore.activeSequence else {
            lastMediaAction = "Batch short export blocked: no active sequence"
            blockExportStatus(kind: "queued-shorts-9x16", reason: "No active sequence loaded.")
            updateAgentState()
            return
        }

        let queuedClips = sequence.shortClipQueue
        guard !queuedClips.isEmpty else {
            lastMediaAction = "Batch short export blocked: no queued short recipes"
            blockExportStatus(kind: "queued-shorts-9x16", reason: "Queue at least one short recipe before batch export.")
            updateAgentState()
            return
        }

        let readiness = mediaReadinessSummary()
        guard readiness.isProductionReady else {
            lastMediaAction = "Batch short export blocked: \(readiness.detail)"
            blockExportStatus(kind: "queued-shorts-9x16", reason: readiness.detail)
            updateAgentState()
            return
        }

        let outputDirectory: URL
        if let directoryPath, !directoryPath.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty {
            outputDirectory = URL(fileURLWithPath: directoryPath, isDirectory: true)
        } else {
            outputDirectory = defaultLocalExportDirectory()
                .appendingPathComponent("shorts", isDirectory: true)
        }

        let requestedBasename = basename?.trimmingCharacters(in: .whitespacesAndNewlines)
        let cleanBasename = sanitizedExportBasename(
            requestedBasename?.isEmpty == false
            ? requestedBasename!
            : "\(normalizedActiveSessionName())-shorts"
        )

        struct QueuedShortExportJob {
            let clip: ShortClipCandidate
            let outputURL: URL
            let sequenceRanges: [(start: Double, duration: Double)]
            let proofDuration: Double
        }

        let jobs: [QueuedShortExportJob] = queuedClips.enumerated().compactMap { index, clip in
            let exportRanges = shortClipExportRanges(for: clip, in: sequence)
            let proofDuration = exportRanges.reduce(0) { $0 + $1.duration }
            guard proofDuration.isFinite, proofDuration > 0 else {
                return nil
            }
            let titleSlug = sanitizedExportBasename(clip.title.isEmpty ? "short" : clip.title)
            let filePrefix = String(format: "%@-%02d-%@", cleanBasename, index + 1, titleSlug)
            return QueuedShortExportJob(
                clip: clip,
                outputURL: outputDirectory.appendingPathComponent("\(filePrefix)-9x16-short.mp4"),
                sequenceRanges: exportRanges,
                proofDuration: proofDuration
            )
        }

        guard jobs.count == queuedClips.count else {
            let invalidCount = queuedClips.count - jobs.count
            lastMediaAction = "Batch short export blocked: \(invalidCount) short recipes have invalid duration"
            blockExportStatus(kind: "queued-shorts-9x16", reason: "Every queued short recipe needs a positive duration before batch export.")
            updateAgentState()
            return
        }

        let outputURLs = jobs.map(\.outputURL)
        let outputById = Dictionary(uniqueKeysWithValues: jobs.map { ($0.clip.id, $0.outputURL.path) })
        for index in sequence.shortClipQueue.indices {
            let clipId = sequence.shortClipQueue[index].id
            sequence.shortClipQueue[index].exportStatus = "queued-for-export"
            sequence.shortClipQueue[index].publishNotes = appendLine(
                "Batch export queued: \(outputById[clipId] ?? outputDirectory.path)",
                to: sequence.shortClipQueue[index].publishNotes
            )
            sequence.shortClipQueue[index].updatedAt = Date()
        }
        projectStore.updateSequence(sequence, undoManager: nil, actionName: "Queue Batch Short Export")
        scheduleAutosave(reason: "queued batch short export")

        let proofSeconds = jobs.reduce(0) { $0 + max(0, $1.proofDuration) }
        beginExportStatus(kind: "queued-shorts-9x16", outputURLs: outputURLs, proofSeconds: proofSeconds)
        playbackEngine.playbackFormat = .vertical9x16
        lastMediaAction = "Batch short export started: \(jobs.count) queued packet(s)"
        updateAgentState()

        Task {
            var completedURLs: [URL] = []
            do {
                for job in jobs {
                    await MainActor.run {
                        markShortClipExportResult(
                            id: job.clip.id,
                            status: "exporting",
                            note: "Batch export started: \(job.outputURL.path)"
                        )
                    }

                    try await ExportEngine.shared.export(
                        sequence: sequence,
                        to: job.outputURL,
                        format: .vertical9x16,
                        allowExternalOriginalMedia: false,
                        allowedOriginalMediaRootPath: nil,
                        sequenceRanges: job.sequenceRanges,
                        primaryOverlayText: burnedInPrimaryOverlayText(for: job.clip),
                        captionText: burnedInCaptionText(for: job.clip)
                    )

                    completedURLs.append(job.outputURL)
                    await MainActor.run {
                        markShortClipExportResult(
                            id: job.clip.id,
                            status: "exported",
                            note: shortExportSuccessNote(outputURL: job.outputURL, clip: job.clip)
                        )
                    }
                }

                await MainActor.run {
                    completeExportStatus(outputURLs: completedURLs)
                    lastMediaAction = "Batch short export completed: \(completedURLs.count) file(s)"
                    updateAgentState()
                }
            } catch {
                await MainActor.run {
                    if let failedJob = jobs.first(where: { !completedURLs.contains($0.outputURL) }) {
                        markShortClipExportResult(
                            id: failedJob.clip.id,
                            status: "export-failed",
                            note: "Batch export failed: \(error.localizedDescription)"
                        )
                    }
                    failExportStatus(error: error)
                    lastMediaAction = "Batch short export failed after \(completedURLs.count) file(s): \(error.localizedDescription)"
                    errorMessage = lastMediaAction
                    showErrorAlert = true
                    updateAgentState()
                }
            }
        }
    }

    private func selectedShortSequenceRange(_ clip: ShortClipCandidate) -> (start: Double, end: Double, duration: Double)? {
        guard let sequence = projectStore.activeSequence else { return nil }
        let segments = shortClipSegments(for: clip, in: sequence)
        guard !segments.isEmpty else { return nil }
        let start = segments.map(\.start).min() ?? sequenceStartTime(for: clip, in: sequence)
        let end = segments.map(\.end).max() ?? (start + max(0, clip.duration))
        let duration = shortClipExportRanges(for: clip, in: sequence).reduce(0) { $0 + $1.duration }
        return (start, end, duration)
    }

    private func sequenceStartTime(for clip: ShortClipCandidate, in sequence: MediaSequence) -> Double {
        if let first = clip.segments.sorted(by: { $0.startTime < $1.startTime }).first {
            return max(0, first.startTime + sourceOffset(for: first, in: sequence))
        }
        return max(0, clip.startTime + sourceOffset(for: clip, in: sequence))
    }

    private func sourceOffset(for clip: ShortClipCandidate, in sequence: MediaSequence) -> Double {
        sourceOffset(for: clip.sourceLaneId, in: sequence)
    }

    private func sourceOffset(for segment: ShortClipSegment, in sequence: MediaSequence) -> Double {
        sourceOffset(for: segment.sourceLaneId, in: sequence)
    }

    private func sourceOffset(for sourceLaneId: UUID?, in sequence: MediaSequence) -> Double {
        guard let sourceLaneId,
              let lane = sequence.lanes.first(where: { $0.id == sourceLaneId }),
              let sourceVideo = lane.sourceVideo else {
            return 0
        }
        return sourceVideo.offset
    }

    private func shortClipSegments(
        for clip: ShortClipCandidate,
        in sequence: MediaSequence
    ) -> [(segment: ShortClipSegment, start: Double, end: Double, duration: Double)] {
        let materializedSegments = clip.segments.isEmpty
            ? [ShortClipSegment(
                title: "Segment 1",
                startTime: clip.startTime,
                duration: clip.duration,
                sourceLaneId: clip.sourceLaneId,
                sourceTagId: clip.sourceTagId
            )]
            : clip.segments

        return materializedSegments
            .filter { $0.startTime.isFinite && $0.duration.isFinite && $0.duration > 0 }
            .map { segment in
                let start = max(0, segment.startTime + sourceOffset(for: segment, in: sequence))
                let duration = max(0, segment.duration)
                return (segment: segment, start: start, end: start + duration, duration: duration)
            }
            .sorted { $0.start < $1.start }
    }

    private func shortClipExportRanges(
        for clip: ShortClipCandidate,
        in sequence: MediaSequence
    ) -> [(start: Double, duration: Double)] {
        let playEditRanges = PlaybackEngine.computeValidRanges(for: sequence)
        let recipeSegments = shortClipSegments(for: clip, in: sequence)

        if playEditRanges.isEmpty {
            return recipeSegments.map { (start: $0.start, duration: $0.duration) }
        }

        return recipeSegments.flatMap { segment -> [(start: Double, duration: Double)] in
            playEditRanges.compactMap { activeRange in
                let overlapStart = max(segment.start, activeRange.lowerBound)
                let overlapEnd = min(segment.end, activeRange.upperBound)
                guard overlapEnd > overlapStart else { return nil }
                return (start: overlapStart, duration: overlapEnd - overlapStart)
            }
        }
    }

    private func markShortClipExportResult(id: UUID, status: String, note: String) {
        guard var sequence = projectStore.activeSequence,
              let index = sequence.shortClipQueue.firstIndex(where: { $0.id == id }) else {
            return
        }

        sequence.shortClipQueue[index].exportStatus = status
        sequence.shortClipQueue[index].publishNotes = appendLine(note, to: sequence.shortClipQueue[index].publishNotes)
        sequence.shortClipQueue[index].updatedAt = Date()
        projectStore.updateSequence(sequence, undoManager: nil, actionName: "Update Short Export Status")
        scheduleAutosave(reason: "updated short export status")
    }

    private func appendLine(_ line: String, to existing: String) -> String {
        let trimmed = existing.trimmingCharacters(in: .whitespacesAndNewlines)
        return trimmed.isEmpty ? line : "\(trimmed)\n\(line)"
    }

    private func lastExportedShortPath(for clip: ShortClipCandidate) -> String? {
        clip.publishNotes
            .components(separatedBy: .newlines)
            .reversed()
            .compactMap { line -> String? in
                let marker = "Exported 9:16 short: "
                guard let range = line.range(of: marker) else { return nil }
                let path = String(line[range.upperBound...]).trimmingCharacters(in: .whitespacesAndNewlines)
                return path.isEmpty ? nil : path
            }
            .first
    }

    private func shortReviewEvidencePayload(for clip: ShortClipCandidate, in sequence: MediaSequence) -> [String: Any] {
        let exportPath = lastExportedShortPath(for: clip) ?? ""
        let exportExists = !exportPath.isEmpty && FileManager.default.fileExists(atPath: exportPath)
        let expectedExportTarget = shortReviewExpectedExportTarget(for: clip, exportPath: exportPath)
        let segments = shortClipSegments(for: clip, in: sequence)
        let exportRanges = shortClipExportRanges(for: clip, in: sequence)
        let recipeDuration = exportRanges.reduce(0) { $0 + $1.duration }
        let sequenceStart = segments.map(\.start).min() ?? sequenceStartTime(for: clip, in: sequence)
        let sequenceEnd = segments.map(\.end).max() ?? (sequenceStart + recipeDuration)
        let review = normalizedShortReviewStatus(clip.reviewStatus)
        let burnPolicy = captionBurnInPolicyPayload(for: clip)
        let publicationReadiness = shortPublicationReadinessPayload(
            for: clip,
            exportExists: exportExists,
            exportPath: exportPath,
            reviewStatus: review,
            textBurnPolicy: burnPolicy
        )
        let nextSafeAction: String

        if !exportExists {
            nextSafeAction = "Export the 9:16 derivative, then create a contact sheet or preview before keep/refine/reject."
        } else if review == "keep" {
            nextSafeAction = "Already approved. It can flow into a reviewed social queue after receipt tracking."
        } else if review == "reject" {
            nextSafeAction = "Rejected. Preserve as learning data; no publishing action needed."
        } else if review == "refine" {
            nextSafeAction = "Refine range, framing, hook, overlay, or caption before re-export."
        } else {
            nextSafeAction = "Review the exported derivative and mark keep, refine, or reject."
        }

        return [
            "model": "quipsly-short-review-evidence",
            "version": "2026-06-19.short-review-evidence.v1",
            "status": exportExists ? "exported_derivative_ready" : "needs_export",
            "title": clip.title,
            "reviewStatus": clip.reviewStatus,
            "exportStatus": clip.exportStatus,
            "exportPath": exportPath,
            "exportExists": exportExists,
            "expectedExportPath": expectedExportTarget.path,
            "suggestedExportDirectory": expectedExportTarget.directory,
            "suggestedExportBasename": expectedExportTarget.basename,
            "exportCommand": "script/agentctl.sh shorts-select id \(clip.id.uuidString) >/dev/null && script/agentctl.sh shorts-export-selected \(shellQuoted(expectedExportTarget.directory)) \(shellQuoted(expectedExportTarget.basename))",
            "contactSheetCommand": exportExists ? "script/agentctl.sh shorts-contact-sheet \(shellQuoted(exportPath))" : "",
            "postExportContactSheetCommand": "script/agentctl.sh shorts-contact-sheet \(shellQuoted(expectedExportTarget.path))",
            "previewCommand": "script/agentctl.sh shorts-preview-selected play",
            "selectCommand": "script/agentctl.sh shorts-select id \(clip.id.uuidString)",
            "reviewCommand": "script/agentctl.sh shorts-review \(clip.id.uuidString) keep|refine|reject \"notes\"",
            "nextSafeAction": nextSafeAction,
            "sequenceStartTime": sequenceStart,
            "sequenceEndTime": sequenceEnd,
            "recipeDuration": recipeDuration,
            "segmentCount": segments.count,
            "transcriptContext": shortTranscriptContextPayload(for: clip, in: sequence),
            "textBurnPolicy": burnPolicy,
            "publicationReadiness": publicationReadiness,
            "sourcePolicy": "Evidence reads the exported derivative short and timeline metadata only. It does not touch raw originals, proxies, or source media.",
            "truth": "Review evidence helps decide keep/refine/reject; it is not itself a publishing approval."
        ]
    }

    private func shortReviewExpectedExportTarget(
        for clip: ShortClipCandidate,
        exportPath: String
    ) -> (directory: String, basename: String, path: String) {
        let suffix = "-9x16-short"
        let fallbackDirectory = defaultLocalExportDirectory()
            .appendingPathComponent("short-review", isDirectory: true)
        let fallbackBasename = sanitizedExportBasename("\(normalizedActiveSessionName())-\(clip.title)")

        let directory: String
        let basename: String

        if exportPath.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty {
            directory = fallbackDirectory.path
            basename = fallbackBasename
        } else {
            let url = URL(fileURLWithPath: exportPath)
            directory = url.deletingLastPathComponent().path
            let filenameBase = url.deletingPathExtension().lastPathComponent
            if filenameBase.hasSuffix(suffix) {
                basename = String(filenameBase.dropLast(suffix.count))
            } else {
                basename = sanitizedExportBasename(filenameBase.isEmpty ? fallbackBasename : filenameBase)
            }
        }

        let expectedPath = URL(fileURLWithPath: directory, isDirectory: true)
            .appendingPathComponent("\(basename)\(suffix).mp4")
            .path
        return (directory, basename, expectedPath)
    }

    private func shellQuoted(_ value: String) -> String {
        "'\(value.replacingOccurrences(of: "'", with: "'\\''"))'"
    }

    private func revealShortExport(path: String) {
        #if os(macOS)
        NSWorkspace.shared.activateFileViewerSelecting([URL(fileURLWithPath: path)])
        #endif
        lastMediaAction = "Revealed short export: \(path)"
        updateAgentState()
    }

    private func shortExportSuccessNote(outputURL: URL, clip: ShortClipCandidate) -> String {
        let rawOverlay = clip.primaryOverlayText.trimmingCharacters(in: .whitespacesAndNewlines)
        let overlay = burnedInPrimaryOverlayText(for: clip)?.trimmingCharacters(in: .whitespacesAndNewlines) ?? ""
        let caption = burnedInCaptionText(for: clip)?.trimmingCharacters(in: .whitespacesAndNewlines) ?? ""
        let draftCaption = clip.captionDraft.trimmingCharacters(in: .whitespacesAndNewlines)
        var lines = ["Exported 9:16 short: \(outputURL.path)"]
        var burnIns: [String] = []
        if !overlay.isEmpty {
            burnIns.append("overlay")
        }
        if !caption.isEmpty {
            burnIns.append("caption")
        }
        if !burnIns.isEmpty {
            lines.append("Text burn-in: \(burnIns.joined(separator: ", "))")
        } else if !rawOverlay.isEmpty || !draftCaption.isEmpty {
            lines.append("Text burn-in: none; Quipsly MVP keeps short text as metadata, SRT/platform copy, and review notes.")
        }
        if !rawOverlay.isEmpty && overlay.isEmpty {
            lines.append("Overlay text preserved as metadata/platform copy; not burned in without explicit positioned top-canopy approval.")
        }
        if !draftCaption.isEmpty && caption.isEmpty {
            lines.append("Caption draft preserved as metadata; not burned in without explicit positioned lower-rail approval.")
        }
        if (!rawOverlay.isEmpty && overlay.isEmpty) || (!draftCaption.isEmpty && caption.isEmpty) {
            lines.append("Text burn policy proof: metadata-only-export-v1; no generic face-safe approval was used for pixel burn-in.")
        }
        return lines.joined(separator: "\n")
    }

