    private func applyLeftWorkbenchMode(_ rawMode: String?) {
        let mode = (rawMode ?? "shorts").lowercased().trimmingCharacters(in: .whitespacesAndNewlines)
        switch mode {
        case "closed", "close", "hide":
            isInspectorVisible = false
            lastMediaAction = "Closed left workbench"
        case "inspector", "inspect", "framing":
            leftWorkbenchMode = .inspector
            isInspectorVisible = true
            lastMediaAction = "Opened Frame workbench"
        case "shorts", "short", "short-clips", "clips":
            leftWorkbenchMode = .shorts
            isInspectorVisible = true
            lastMediaAction = "Opened Shorts workbench"
        case "transcript", "transcripts", "caption", "captions", "words":
            leftWorkbenchMode = .transcript
            isInspectorVisible = true
            lastMediaAction = "Opened Script workbench"
        case "publish", "publishing", "publication", "release", "cockpit", "mission":
            leftWorkbenchMode = .publish
            isInspectorVisible = true
            lastMediaAction = "Opened Ship workbench"
        case "nest", "writing", "capture", "context", "manuscript":
            leftWorkbenchMode = .nest
            isInspectorVisible = true
            lastMediaAction = "Opened Nest workbench"
        case "agent", "codex", "driver", "receipts", "proofs":
            leftWorkbenchMode = .agent
            isInspectorVisible = true
            lastMediaAction = "Opened Agent receipt workbench"
        default:
            leftWorkbenchMode = .shorts
            isInspectorVisible = true
            lastMediaAction = "Opened Shorts workbench"
        }
        updateAgentState()
    }

