    private func selectedShortProofPayload(for sequence: MediaSequence?) -> [String: Any] {
        guard let sequence else {
            return [
                "status": "no_sequence",
                "selected": false,
                "supportsMultipleSegments": true,
                "timelineRailVisible": false,
                "segmentCount": 0,
                "exportRangeCount": 0,
                "recipeDuration": 0,
                "contract": "Cuts are output recipes over sequence time. They can be one continuous segment or multiple ordered segments, and they never chop source media."
            ]
        }

        guard let selectedShortClipId,
              let clip = sequence.shortClipQueue.first(where: { $0.id == selectedShortClipId }) else {
            return [
                "status": sequence.shortClipQueue.isEmpty ? "no_short_candidates" : "no_short_selected",
                "selected": false,
                "supportsMultipleSegments": true,
                "timelineRailVisible": false,
                "shortClipQueueCount": sequence.shortClipQueue.count,
                "segmentCount": 0,
                "exportRangeCount": 0,
                "recipeDuration": 0,
                "nextSafeActions": [
                    "GET /shorts_queue_add_selected?title=<optional-title>",
                    "GET /shorts_queue_add_range?start=<sequence-seconds>&end=<sequence-seconds>&title=<optional-title>",
                    "GET /shorts_queue_select?id=<short-clip-id>|title=<text>|index=<one-based-index>"
                ],
                "contract": "Cuts are output recipes over sequence time. Select or create one to show its pull-out rail on the timeline."
            ]
        }

        let segments = shortClipSegments(for: clip, in: sequence)
        let exportRanges = shortClipExportRanges(for: clip, in: sequence)
        let sequenceStart = segments.map(\.start).min() ?? sequenceStartTime(for: clip, in: sequence)
        let sequenceEnd = segments.map(\.end).max() ?? sequenceStart + clip.duration
        let recipeDuration = exportRanges.reduce(0) { $0 + $1.duration }
        let playheadInsideRecipe = segments.contains { item in
            playbackEngine.playhead >= item.start && playbackEngine.playhead <= item.end
        }
        let burnPolicy = captionBurnInPolicyPayload(for: clip)
        let exportPath = lastExportedShortPath(for: clip) ?? ""
        let exportExists = !exportPath.isEmpty && FileManager.default.fileExists(atPath: exportPath)
        let expectedExportTarget = shortReviewExpectedExportTarget(for: clip, exportPath: exportPath)
        let publicationReadiness = shortPublicationReadinessPayload(
            for: clip,
            exportExists: exportExists,
            exportPath: exportPath,
            reviewStatus: normalizedShortReviewStatus(clip.reviewStatus),
            textBurnPolicy: burnPolicy
        )

        return [
            "status": "selected",
            "selected": true,
            "id": clip.id.uuidString,
            "title": clip.title,
            "format": clip.format.rawValue,
            "supportsMultipleSegments": true,
            "timelineRailVisible": true,
            "timelineRailModel": "selected short pull-out rail over the long sequence timeline",
            "recipeModel": "ordered-sequence-segments",
            "timeBase": "sequence-seconds",
            "segmentCount": segments.count,
            "isMultiSegment": segments.count > 1,
            "exportRangeCount": exportRanges.count,
            "sequenceStartTime": sequenceStart,
            "sequenceEndTime": sequenceEnd,
            "sourceSpanDuration": max(0, sequenceEnd - sequenceStart),
            "recipeDuration": recipeDuration,
            "playheadInsideSelectedShort": playheadInsideRecipe,
            "reviewStatus": clip.reviewStatus,
            "exportStatus": clip.exportStatus,
            "lastExportedPath": exportPath,
            "lastExportExists": exportExists,
            "expectedExportPath": expectedExportTarget.path,
            "expectedExportDirectory": expectedExportTarget.directory,
            "expectedExportBasename": expectedExportTarget.basename,
            "exportCommand": "script/agentctl.sh shorts-export-selected \(shellQuoted(expectedExportTarget.directory)) \(shellQuoted(expectedExportTarget.basename))",
            "contactSheetCommand": exportExists ? "script/agentctl.sh shorts-contact-sheet \(shellQuoted(exportPath))" : "",
            "postExportContactSheetCommand": "script/agentctl.sh shorts-contact-sheet \(shellQuoted(expectedExportTarget.path))",
            "textBurnPolicy": burnPolicy,
            "publicationReadiness": publicationReadiness,
            "destinations": clip.destinations,
            "segments": segments.enumerated().map { index, item in
                [
                    "index": index,
                    "id": item.segment.id.uuidString,
                    "title": item.segment.title.isEmpty ? "Segment \(index + 1)" : item.segment.title,
                    "sequenceStartTime": item.start,
                    "sequenceEndTime": item.end,
                    "duration": item.duration,
                    "sourceLaneId": item.segment.sourceLaneId?.uuidString ?? "",
                    "sourceTagId": item.segment.sourceTagId?.uuidString ?? ""
                ] as [String: Any]
            },
            "exportRanges": exportRanges.enumerated().map { index, range in
                [
                    "index": index,
                    "sequenceStartTime": range.start,
                    "sequenceEndTime": range.start + range.duration,
                    "duration": range.duration
                ] as [String: Any]
            },
            "nextSafeActions": [
                "GET /shorts_preview_selected?play=true|false",
                "GET /shorts_quality_action?action=fill-hook|draft-copy|copy-polish-prompt|needs-refine",
                "GET /shorts_range_selected?boundary=start|end&time=<sequence-seconds>|delta=<seconds>",
                "GET /shorts_queue_append_selected_segment",
                "GET /shorts_overlay_burn_in?decision=request_review|approve_top_canopy|hold&note=<optional-review-note>",
                "GET /shorts_export_selected?directory=<absolute-output-folder>&basename=<name>"
            ],
            "contract": "A selected short is a recipe over whole source lanes and SHOW/SKIP metadata. Multiple segments are allowed; exports render derivatives without touching source media."
        ]
    }

    private func transcriptPayload(for sequence: MediaSequence?) -> [String: Any] {
        guard let sequence else {
            return [
                "model": "transcript-spine",
                "version": "2026-06-16.transcript-spine.v1",
                "count": 0,
                "jobCount": 0,
                "latestJob": [:],
                "jobs": [],
                "segments": [],
                "timingReadiness": transcriptTimingReadinessPayload(for: []),
                "truth": "Script segments are timed episode metadata. Captions and text assets should derive from them, not from detached text boxes."
            ]
        }

        return [
            "model": "transcript-spine",
            "version": "2026-06-16.transcript-spine.v1",
            "count": sequence.transcriptSegments.count,
            "jobCount": sequence.transcriptJobs.count,
            "latestJob": transcriptJobPayload(sequence.transcriptJobs.sorted { $0.startedAt > $1.startedAt }.first),
            "jobs": sequence.transcriptJobs.sorted { $0.startedAt > $1.startedAt }.prefix(10).map { job in
                transcriptJobPayload(job)
            },
            "timingReadiness": transcriptTimingReadinessPayload(for: sequence.transcriptSegments),
            "truth": "Script segments are timed episode metadata. Captions and text assets should derive from them, not from detached text boxes.",
            "segments": sequence.transcriptSegments.sorted { $0.startTime < $1.startTime }.map { segment in
                transcriptSegmentPayload(segment)
            }
        ]
    }

    private func transcriptTimingReadinessPayload(for segments: [TranscriptSegment]) -> [String: Any] {
        let words = segments.flatMap { transcriptWordTimings(for: $0) }
        let demoCount = words.filter { $0.source.localizedCaseInsensitiveContains("demo") }.count
        let estimatedCount = words.filter { $0.source.localizedCaseInsensitiveContains("estimated") }.count
        let wordLevelCount = max(0, words.count - demoCount - estimatedCount)
        let status: String
        let label: String
        let detail: String

        if segments.isEmpty {
            status = "no_transcript"
            label = "No transcript"
            detail = "Import, generate, or seed a transcript before using script-aware editing."
        } else if words.isEmpty {
            status = "line_timing_only"
            label = "Line timing only"
            detail = "Segments exist, but there are no word timings yet. Useful for navigation; not ready for word-highlight captions."
        } else if demoCount == words.count {
            status = "demo_timing"
            label = "Demo timing"
            detail = "This proves the workflow. Replace with real word-level timing before publication captions or edit-by-word claims."
        } else if estimatedCount > 0 || demoCount > 0 {
            status = "mixed_timing"
            label = "Mixed timing"
            detail = "\(wordLevelCount) word-level, \(estimatedCount) estimated, \(demoCount) demo. Good for review; verify before publishing captions."
        } else {
            status = "word_level_timing"
            label = "Word-level timing"
            detail = "\(wordLevelCount) timed words are available for script-aware editing, captions, quotes, and shorts."
        }

        return [
            "model": "transcript-timing-readiness",
            "version": "2026-06-19.transcript-timing-readiness.v1",
            "status": status,
            "label": label,
            "detail": detail,
            "segmentCount": segments.count,
            "wordCount": words.count,
            "wordLevelCount": wordLevelCount,
            "estimatedCount": estimatedCount,
            "demoCount": demoCount,
            "publicationCaptionReady": status == "word_level_timing",
            "judgementPolicy": "transparency_only_no_quality_gate",
            "truth": "Transcript timing readiness is an honesty label. It does not block editing, score the user, or make source media changes."
        ]
    }

    private func transcriptJobPayload(_ job: TranscriptJobRecord?) -> [String: Any] {
        guard let job else { return [:] }
        let formatter = ISO8601DateFormatter()
        return [
            "id": job.id.uuidString,
            "sourceLaneId": job.sourceLaneId?.uuidString ?? "",
            "sourceLaneName": job.sourceLaneName,
            "sourcePath": job.sourcePath,
            "provider": job.provider,
            "commandPath": job.commandPath ?? "",
            "status": job.status,
            "startedAt": formatter.string(from: job.startedAt),
            "completedAt": job.completedAt.map { formatter.string(from: $0) } ?? "",
            "error": job.error,
            "segmentCount": job.segmentCount
        ]
    }

    private func transcriptSegmentPayload(_ segment: TranscriptSegment?) -> [String: Any] {
        guard let segment else { return [:] }
        let speakerContext = transcriptSpeakerContext(for: segment, at: (segment.startTime + segment.endTime) / 2.0)
        var payload: [String: Any] = [
            "id": segment.id.uuidString,
            "sourceAssetId": segment.sourceAssetId?.uuidString ?? "",
            "speaker": segment.speaker,
            "speakerDisplay": speakerContext.displayName,
            "speakerSource": speakerContext.source,
            "speakerNeedsReview": transcriptSpeakerNeedsReview(source: speakerContext.source),
            "speakerDetail": speakerContext.detail,
            "speakerLaneNames": speakerContext.laneNames,
            "startTime": segment.startTime,
            "endTime": segment.endTime,
            "duration": max(0, segment.endTime - segment.startTime),
            "text": segment.text,
            "wordCount": transcriptWordTimings(for: segment).count,
            "wordTimingSource": transcriptWordTimings(for: segment).first?.source ?? "",
            "words": segment.words.prefix(60).map { wordTimingPayload($0) },
            "reviewStatus": segment.reviewStatus,
            "createdAt": ISO8601DateFormatter().string(from: segment.createdAt),
            "updatedAt": ISO8601DateFormatter().string(from: segment.updatedAt)
        ]
        if let confidence = segment.confidence {
            payload["confidence"] = confidence
        }
        return payload
    }

    private func currentTranscriptWordPayload(segment: TranscriptSegment?, time: Double) -> [String: Any] {
        guard let segment else { return [:] }
        let words = transcriptWordTimings(for: segment)
        guard !words.isEmpty else {
            return [
                "segmentId": segment.id.uuidString,
                "speaker": segment.speaker,
                "word": "",
                "wordIndex": -1,
                "wordCount": 0,
                "time": time,
                "timingModel": "empty_segment"
            ]
        }
        let index = activeTranscriptWordIndex(words: words, segment: segment, at: time) ?? 0
        let word = words.indices.contains(index) ? words[index] : words[0]
        let isDemo = word.source.localizedCaseInsensitiveContains("demo")
        let isEstimated = word.source.localizedCaseInsensitiveContains("estimated")
        let speakerContext = transcriptSpeakerContext(for: segment, at: time)
        return [
            "segmentId": segment.id.uuidString,
            "speaker": segment.speaker,
            "speakerDisplay": speakerContext.displayName,
            "speakerSource": speakerContext.source,
            "speakerNeedsReview": transcriptSpeakerNeedsReview(source: speakerContext.source),
            "speakerDetail": speakerContext.detail,
            "speakerLaneNames": speakerContext.laneNames,
            "word": word.word,
            "wordIndex": index,
            "wordCount": words.count,
            "wordStart": word.startTime,
            "wordEnd": word.endTime,
            "wordSource": word.source,
            "segmentStart": segment.startTime,
            "segmentEnd": segment.endTime,
            "time": time,
            "timingModel": isDemo ? "demo_word_timing" : (isEstimated ? "estimated_from_segment_duration" : "word_level_timing"),
            "truth": isDemo
                ? "This word is demo scaffold timing for proving the workflow."
                : (isEstimated
                    ? "This word is estimated from segment timing. Replace with word-level timestamps when the transcriber returns them."
                    : "This word is backed by imported word-level timing.")
        ]
    }

    private func transcriptWordTimingHelpText(label: String) -> String {
        switch label {
        case "WORD":
            return "Word highlight is using imported word-level timing."
        case "DEMO WORD":
            return "Demo word timing proves the workflow; replace it with real transcript timing before publication."
        default:
            return "Word highlight is estimated from the segment until word-level transcription lands."
        }
    }

    private func transcriptWordChipBackground(isActive: Bool, isSelected: Bool) -> Color {
        if isSelected {
            return QuipslyStudioTheme.creek.opacity(0.34)
        }
        if isActive {
            return QuipslyStudioTheme.honey.opacity(0.95)
        }
        return QuipslyStudioTheme.panelLift.opacity(0.22)
    }

    private func wordTimingPayload(_ word: TranscriptWordTiming) -> [String: Any] {
        var payload: [String: Any] = [
            "id": word.id.uuidString,
            "word": word.word,
            "startTime": word.startTime,
            "endTime": word.endTime,
            "duration": max(0, word.endTime - word.startTime),
            "source": word.source
        ]
        if let confidence = word.confidence {
            payload["confidence"] = confidence
        }
        return payload
    }

    private func selectedTranscriptWordPayload(in sequence: MediaSequence?) -> [String: Any] {
        guard let selected = selectedTranscriptWordValue(in: sequence) else { return [:] }
        var payload = wordTimingPayload(selected.word)
        let words = transcriptWordTimings(for: selected.segment)
        let isDemo = selected.word.source.localizedCaseInsensitiveContains("demo")
        let isEstimated = selected.word.source.localizedCaseInsensitiveContains("estimated")
        let speakerContext = transcriptSpeakerContext(for: selected.segment, at: selected.word.startTime)
        payload["segmentId"] = selected.segment.id.uuidString
        payload["speaker"] = selected.segment.speaker
        payload["speakerDisplay"] = speakerContext.displayName
        payload["speakerSource"] = speakerContext.source
        payload["speakerNeedsReview"] = transcriptSpeakerNeedsReview(source: speakerContext.source)
        payload["speakerDetail"] = speakerContext.detail
        payload["speakerLaneNames"] = speakerContext.laneNames
        payload["segmentSpeaker"] = selected.segment.speaker
        payload["wordIndex"] = selected.index
        payload["wordCount"] = words.count
        payload["wordStart"] = selected.word.startTime
        payload["wordEnd"] = selected.word.endTime
        payload["wordSource"] = selected.word.source
        payload["segmentStart"] = selected.segment.startTime
        payload["segmentEnd"] = selected.segment.endTime
        payload["time"] = selected.word.startTime
        payload["timingModel"] = isDemo ? "demo_word_timing" : (isEstimated ? "estimated_from_segment_duration" : "word_level_timing")
        payload["truth"] = isDemo
            ? "This selected word is demo scaffold timing for proving the workflow."
            : (isEstimated
                ? "This selected word is estimated from segment timing. Replace with word-level timestamps when the transcriber returns them."
                : "This selected word is backed by imported word-level timing.")
        return payload
    }

    private func scriptFollowPayload(
        for sequence: MediaSequence?,
        currentSegment: TranscriptSegment?,
        selectedSegment: TranscriptSegment?
    ) -> [String: Any] {
        guard let sequence else {
            return [
                "model": "script-follow",
                "version": "2026-06-19.script-follow.v1",
                "status": "no_sequence",
                "segmentCount": 0,
                "current": [:],
                "selected": [:],
                "surroundingSegments": [],
                "shortcuts": [
                    "openScript": "Option+S",
                    "previousWord": "Option+Comma",
                    "nextWord": "Option+Period"
                ],
                "truth": "Script Follow is read-only awareness over timed transcript metadata."
            ]
        }

        let ordered = sequence.transcriptSegments.sorted { $0.startTime < $1.startTime }
        let currentIndex = currentSegment.flatMap { current in
            ordered.firstIndex { $0.id == current.id }
        }
        let surroundingIndices: [Int] = {
            guard let currentIndex else {
                return selectedSegment
                    .flatMap { selected in ordered.firstIndex { $0.id == selected.id } }
                    .map { [max(0, $0 - 1), $0, min(ordered.count - 1, $0 + 1)] }
                    ?? []
            }
            return [max(0, currentIndex - 1), currentIndex, min(ordered.count - 1, currentIndex + 1)]
        }()
        let uniqueSurroundingIndices = Array(Set(surroundingIndices)).sorted()

        return [
            "model": "script-follow",
            "version": "2026-06-19.script-follow.v1",
            "status": ordered.isEmpty ? "no_transcript" : (currentSegment == nil ? "between_segments" : "following"),
            "playhead": playbackEngine.playhead,
            "leftWorkbenchMode": leftWorkbenchMode.rawValue,
            "segmentCount": ordered.count,
            "current": [
                "segment": transcriptSegmentPayload(currentSegment),
                "word": currentTranscriptWordPayload(segment: currentSegment, time: playbackEngine.playhead)
            ],
            "selected": [
                "segment": transcriptSegmentPayload(selectedSegment),
                "word": selectedTranscriptWordPayload(in: sequence)
            ],
            "surroundingSegments": uniqueSurroundingIndices.map { index in
                transcriptSegmentBriefPayload(ordered[index], role: index == currentIndex ? "current" : "context")
            },
            "shortcuts": [
                "openScript": "Option+S",
                "previousWord": "Option+Comma",
                "nextWord": "Option+Period",
                "mapOverlaps": "Option+R",
                "previousOverlap": "Option+[",
                "nextOverlap": "Option+]",
                "resolveOverlap": "Option+1/2/4/5/6"
            ],
            "truth": "Script Follow is read-only awareness over timed transcript metadata. It follows the same shared sequence playhead as Program Output, Source Grove, and Episode Spine."
        ]
    }

    private func scriptCursorPayload(for sequence: MediaSequence?, currentSegment: TranscriptSegment?) -> [String: Any] {
        guard let sequence else {
            return [
                "model": "script-cursor",
                "version": "2026-06-19.script-cursor.v1",
                "status": "no_sequence",
                "speaker": "",
                "word": [:],
                "wordWindow": [],
                "truth": "Script cursor is read-only timeline awareness. Load a sequence before using it."
            ]
        }

        guard let segment = currentSegment ?? currentTranscriptSegment(in: sequence) else {
            return [
                "model": "script-cursor",
                "version": "2026-06-19.script-cursor.v1",
                "status": sequence.transcriptSegments.isEmpty ? "no_transcript" : "between_segments",
                "segmentCount": sequence.transcriptSegments.count,
                "playhead": playbackEngine.playhead,
                "speaker": "",
                "word": [:],
                "wordWindow": [],
                "nextAction": sequence.transcriptSegments.isEmpty
                    ? "Generate, import, or seed the Script Spine."
                    : "Scrub to a transcript segment or use GET /transcript_select?mode=at_playhead.",
                "truth": "Script cursor does not infer words outside transcript coverage."
            ]
        }

        let words = transcriptWordTimings(for: segment)
        let activeIndex = activeTranscriptWordIndex(words: words, segment: segment, at: playbackEngine.playhead)
        let currentWord = activeIndex.flatMap { words.indices.contains($0) ? words[$0] : nil }
        let windowStart = max(0, (activeIndex ?? 0) - 6)
        let windowEnd = min(words.count, (activeIndex ?? 0) + 7)
        let window = words.enumerated()
            .filter { index, _ in index >= windowStart && index < windowEnd }
            .map { index, word -> [String: Any] in
                var payload = wordTimingPayload(word)
                payload["index"] = index
                payload["active"] = index == activeIndex
                return payload
            }

        var activeWordPayload: [String: Any] = currentWord.map(wordTimingPayload) ?? [:]
        let speakerContext = transcriptSpeakerContext(for: segment, at: playbackEngine.playhead)
        if let activeIndex {
            activeWordPayload["index"] = activeIndex
            activeWordPayload["speaker"] = speakerContext.displayName
            activeWordPayload["transcriptSpeaker"] = segment.speaker
            activeWordPayload["speakerSource"] = speakerContext.source
            activeWordPayload["speakerNeedsReview"] = transcriptSpeakerNeedsReview(source: speakerContext.source)
            activeWordPayload["speakerDetail"] = speakerContext.detail
            activeWordPayload["time"] = currentWord?.startTime ?? playbackEngine.playhead
        }

        return [
            "model": "script-cursor",
            "version": "2026-06-19.script-cursor.v1",
            "status": currentWord == nil ? "segment_ready_word_estimate_unavailable" : "word_ready",
            "playhead": playbackEngine.playhead,
            "segmentId": segment.id.uuidString,
            "segmentStart": segment.startTime,
            "segmentEnd": segment.endTime,
            "speaker": speakerContext.displayName,
            "transcriptSpeaker": segment.speaker,
            "speakerSource": speakerContext.source,
            "speakerNeedsReview": transcriptSpeakerNeedsReview(source: speakerContext.source),
            "speakerDetail": speakerContext.detail,
            "speakerLaneNames": speakerContext.laneNames,
            "text": segment.text,
            "word": activeWordPayload,
            "wordWindow": window,
            "selectedWord": selectedTranscriptWordPayload(in: sequence),
            "semanticCommands": [
                "GET /transcript_word?mode=current",
                "GET /transcript_word?mode=next",
                "GET /transcript_word?mode=previous",
                "GET /scrub?time=<word-start>"
            ],
            "truth": "Script cursor follows the shared sequence playhead and exposes nearby timed words for caption-aware editing, quotes, shorts, and agent decisions."
        ]
    }

    private func transcriptSegmentBriefPayload(_ segment: TranscriptSegment, role: String) -> [String: Any] {
        [
            "id": segment.id.uuidString,
            "role": role,
            "speaker": segment.speaker,
            "startTime": segment.startTime,
            "endTime": segment.endTime,
            "duration": max(0, segment.endTime - segment.startTime),
            "text": segment.text
        ]
    }

    private func transcriptWordTokens(_ text: String) -> [String] {
        text
            .split(whereSeparator: { $0.isWhitespace || $0.isNewline })
            .map { String($0) }
    }

    private func transcriptWordTimings(for segment: TranscriptSegment) -> [TranscriptWordTiming] {
        if !segment.words.isEmpty {
            return segment.words.sorted { $0.startTime < $1.startTime }
        }
        let tokens = transcriptWordTokens(segment.text)
        guard !tokens.isEmpty else { return [] }
        let duration = max(0.01, segment.endTime - segment.startTime)
        let step = duration / Double(tokens.count)
        return tokens.enumerated().map { index, word in
            let start = segment.startTime + (Double(index) * step)
            return TranscriptWordTiming(
                word: word,
                startTime: start,
                endTime: min(segment.endTime, start + step),
                confidence: nil,
                source: "segment-estimated"
            )
        }
    }

    private func activeTranscriptWordIndex(words: [TranscriptWordTiming], segment: TranscriptSegment, at time: Double) -> Int? {
        guard !words.isEmpty else { return nil }
        if let exact = words.firstIndex(where: { time >= $0.startTime && time < max($0.endTime, $0.startTime + 0.001) }) {
            return exact
        }
        let start = segment.startTime
        let end = max(segment.endTime, start + 0.01)
        let progress = min(max((time - start) / (end - start), 0), 0.999_999)
        return min(max(Int(progress * Double(words.count)), 0), words.count - 1)
    }

    private func transcriptSpeakerContext(
        for segment: TranscriptSegment,
        at sequenceTime: Double? = nil
    ) -> (displayName: String, source: String, detail: String, laneNames: [String]) {
        let transcriptSpeaker = segment.speaker.trimmingCharacters(in: .whitespacesAndNewlines)
        if !transcriptSpeakerIsGeneric(transcriptSpeaker) {
            return (
                displayName: transcriptSpeaker,
                source: "transcript",
                detail: "Speaker came from the transcript sidecar/import.",
                laneNames: []
            )
        }

        guard let sequence = projectStore.activeSequence else {
            return (
                displayName: "Unknown speaker",
                source: "unknown",
                detail: "The transcript did not include a speaker and no active sequence is loaded for source-lane inference.",
                laneNames: []
            )
        }

        let sampleTime = sequenceTime ?? ((segment.startTime + segment.endTime) / 2.0)
        let activeLanes = activeProgramLanes(in: sequence, at: sampleTime)
        let laneNames = activeLanes.map(\.name)
        let friendlyNames = orderedUnique(activeLanes.map { transcriptFriendlySpeakerName(for: $0) })
            .filter { !$0.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty }

        guard !friendlyNames.isEmpty else {
            return (
                displayName: "Unknown speaker",
                source: activeLanes.isEmpty ? "generic_transcript" : "unresolved_program_source",
                detail: activeLanes.isEmpty
                    ? "The transcript did not include a speaker, and no active SHOW source could be inferred at this time."
                    : "The transcript did not include a speaker, and the active SHOW source is not labeled as Charlie, Homer, Both, or Reference. Assign a lane role before using this as speaker truth.",
                laneNames: laneNames
            )
        }

        let display = friendlyNames.joined(separator: " + ")
        return (
            displayName: display,
            source: friendlyNames.count > 1 ? "program_multi_source_inferred" : "program_source_inferred",
            detail: String(
                format: "Transcript speaker was generic; inferred from active SHOW source at %.2fs.",
                sampleTime
            ),
            laneNames: laneNames
        )
    }

    private func transcriptSpeakerIsGeneric(_ speaker: String) -> Bool {
        let normalized = speaker
            .trimmingCharacters(in: .whitespacesAndNewlines)
            .lowercased()
        return normalized.isEmpty
            || normalized == "speaker"
            || normalized == "unknown"
            || normalized == "unknown speaker"
            || normalized == "person"
            || normalized == "voice"
    }

    private func transcriptFriendlySpeakerName(for lane: VideoLane) -> String {
        let role = (lane.metadata?.role ?? "").lowercased()
        let label = (lane.metadata?.sourceLabel ?? "").lowercased()
        let name = lane.name.lowercased()

        if role.contains("charlie") || label.contains("charlie") || name.contains("charlie") {
            return "Charlie"
        }
        if role.contains("homer") || label.contains("homer") || name.contains("homer") {
            return "Homer"
        }
        if role.contains("both") || label.contains("both") || name.contains("both") {
            return "Both"
        }
        if role.contains("reference") || role.contains("clip") || name.contains("reference") || name.contains("clip") {
            return "Reference clip"
        }

        let rawLabel = lane.metadata?.sourceLabel?.trimmingCharacters(in: .whitespacesAndNewlines)
        let fallback = rawLabel?.isEmpty == false ? rawLabel! : lane.name
        return transcriptSpeakerFallbackLabelIsUseful(fallback) ? fallback : ""
    }

    private func transcriptSpeakerFallbackLabelIsUseful(_ label: String) -> Bool {
        let normalized = label
            .trimmingCharacters(in: .whitespacesAndNewlines)
            .lowercased()
        guard !normalized.isEmpty else { return false }
        let unresolvedMarkers = [
            "unresolved",
            "temp_video",
            "video clip",
            ".mp4",
            ".mov",
            ".m4v",
            ".wav",
            ".m4a",
            ".mp3"
        ]
        return !unresolvedMarkers.contains { normalized.contains($0) }
    }

    private func transcriptSpeakerNeedsReview(source: String) -> Bool {
        let normalized = source.lowercased()
        return normalized == "unknown"
            || normalized == "generic_transcript"
            || normalized == "unresolved_program_source"
    }

    private func orderedUnique(_ values: [String]) -> [String] {
        var seen = Set<String>()
        var result: [String] = []
        for value in values {
            let key = value.lowercased()
            guard !seen.contains(key) else { continue }
            seen.insert(key)
            result.append(value)
        }
        return result
    }

    private func programLayoutPayload(for sequence: MediaSequence?) -> [String: Any] {
        guard let sequence else {
            return [
                "model": "program-layout-rules",
                "version": "2026-06-16.program-layout.v1",
                "layoutMode": "none",
                "activeVisualLaneCount": 0,
                "activeVisualLanes": [],
                "format": playbackEngine.playbackFormat.rawValue,
                "truth": "Program layout is render metadata over whole source lanes; it never crops or duplicates source media."
            ]
        }

        let activeLanes = sequence.lanes
            .filter { lane in
                !isSupportOnlyLane(lane)
                    && sourceReadiness(for: lane).isReady
                    && decisionAtPlayhead(for: lane)?.type == .active
            }
            .sorted { lhs, rhs in
                programLayoutSortKey(lhs) < programLayoutSortKey(rhs)
            }
        let mode: String
        if activeLanes.count <= 1 {
            mode = "single_fill"
        } else if playbackEngine.playbackFormat == .vertical9x16 {
            mode = "stacked_vertical"
        } else {
            mode = "side_by_side"
        }

        return [
            "model": "program-layout-rules",
            "version": "2026-06-16.program-layout.v1",
            "layoutMode": mode,
            "activeVisualLaneCount": activeLanes.count,
            "format": playbackEngine.playbackFormat.rawValue,
            "activeVisualLanes": activeLanes.enumerated().map { index, lane in
                [
                    "index": index,
                    "id": lane.id.uuidString,
                    "name": lane.name,
                    "role": lane.metadata?.role ?? "",
                    "defaultSlot": defaultProgramSlotName(index: index, total: activeLanes.count),
                    "crop": programCropPayload(for: lane, format: playbackEngine.playbackFormat)
                ] as [String: Any]
            },
            "singleSpeakerDefault": "aspect_fill_center_crop",
            "bothSpeaker16x9Default": "side_by_side_equal_crop",
            "bothSpeaker9x16Default": "stacked_equal_crop",
            "truth": "Program layout is render metadata over whole source lanes; it never crops or duplicates source media."
        ]
    }

    private func programDecisionAmbiguityPayload(for sequence: MediaSequence?) -> [String: Any] {
        guard let sequence else {
            return [
                "status": "no_sequence",
                "activeVisualLaneCount": 0,
                "needsReview": false,
                "truth": "Decision ambiguity is evaluated over SHOW/SKIP metadata at the shared playhead."
            ]
        }

        let activeLanes = playableProgramLanes(in: sequence)
            .filter { decisionAtPlayhead(for: $0)?.type == .active }
            .sorted { lhs, rhs in
                programLayoutSortKey(lhs) < programLayoutSortKey(rhs)
            }
        let speakerLanes = activeLanes.filter { lane in
            let role = (lane.metadata?.role ?? "").lowercased()
            let name = lane.name.lowercased()
            return role.contains("camera")
                || role.contains("charlie")
                || role.contains("homer")
                || name.contains("camera")
                || name.contains("charlie")
                || name.contains("homer")
        }
        let sourceClipLanes = activeLanes.filter { lane in
            let role = (lane.metadata?.role ?? "").lowercased()
            let name = lane.name.lowercased()
            return role.contains("source")
                || role.contains("clip")
                || role.contains("reference")
                || name.contains("source clip")
                || name.contains("reference")
        }
        let multipleSpeakers = speakerLanes.count > 1
        let moreThanExpectedOverlay = activeLanes.count > 2
        let needsReview = multipleSpeakers || moreThanExpectedOverlay
        let status: String
        if activeLanes.isEmpty {
            status = "source_or_gap"
        } else if needsReview {
            status = "needs_program_decision_review"
        } else {
            status = "clear_at_playhead"
        }

        return [
            "status": status,
            "needsReview": needsReview,
            "playhead": playbackEngine.playhead,
            "activeVisualLaneCount": activeLanes.count,
            "activeSpeakerLaneCount": speakerLanes.count,
            "activeSourceClipLaneCount": sourceClipLanes.count,
            "activeVisualLanes": activeLanes.map { lane in
                [
                    "id": lane.id.uuidString,
                    "name": lane.name,
                    "role": lane.metadata?.role ?? "",
                    "trackIds": lane.metadata?.trackIds ?? []
                ] as [String: Any]
            },
            "plainEnglish": needsReview
                ? "Multiple visual lanes are SHOW at this playhead. This may be intentional, but inherited Premiere sessions should be reviewed before treating it as final program truth."
                : "The current playhead has a clear program decision shape.",
            "truth": "This is a non-destructive review signal. It does not change media, proxies, decisions, exports, or publication state."
        ]
    }

    private func refreshProgramDecisionAmbiguityReport(sampleLimit: Int?) {
        guard let sequence = projectStore.activeSequence else {
            latestProgramDecisionAmbiguityReport = [
                "status": "no_sequence",
                "reviewPointCount": 0,
                "truth": "Load a sequence before building a program ambiguity report."
            ]
            selectedProgramDecisionAmbiguityExampleIndex = nil
            lastMediaAction = "Program ambiguity report blocked: no active sequence"
            updateAgentState()
            return
        }

        let report = programDecisionAmbiguityReportPayload(for: sequence, sampleLimit: sampleLimit)
        latestProgramDecisionAmbiguityReport = report
        selectedProgramDecisionAmbiguityExampleIndex = nil
        let reviewCount = report["reviewPointCount"] as? Int ?? 0
        let sampledCount = report["sampledIntervalCount"] as? Int ?? 0
        lastMediaAction = "Program ambiguity report: \(reviewCount) review point(s) from \(sampledCount) sampled interval(s)"
        updateAgentState()
    }

    private func ambiguityReportExamples() -> [[String: Any]] {
        latestProgramDecisionAmbiguityReport["examples"] as? [[String: Any]] ?? []
    }

    private func selectedProgramDecisionAmbiguityExamplePayload() -> [String: Any] {
        let examples = ambiguityReportExamples()
        guard let index = selectedProgramDecisionAmbiguityExampleIndex,
              examples.indices.contains(index)
        else {
            return [:]
        }

        var payload = examples[index]
        payload["index"] = index
        payload["humanIndex"] = index + 1
        payload["exampleCount"] = examples.count
        payload["truth"] = "Selected ambiguity example is a navigation target only. It does not mutate media, decisions, exports, or publication state."
        return payload
    }

    private func programAmbiguityOperatorPayload(for sequence: MediaSequence?) -> [String: Any] {
        guard sequence != nil else {
            return [
                "model": "program-ambiguity-operator",
                "version": "2026-06-19.program-ambiguity-operator.v1",
                "status": "no_sequence",
                "reportLoaded": false,
                "reviewPointCount": 0,
                "selected": [:],
                "choices": [],
                "manualReviewReceipt": latestProgramDecisionAmbiguityManualReviewReceipt,
                "nextSafeActions": ["Load a native session before mapping overlap review points."],
                "truth": "This operator is a guide for explicit SHOW/SKIP decisions. It never edits media by itself."
            ]
        }

        let examples = ambiguityReportExamples()
        let selected = selectedProgramDecisionAmbiguityExamplePayload()
        let reviewCount = latestProgramDecisionAmbiguityReport["reviewPointCount"] as? Int
        let reportStatus = latestProgramDecisionAmbiguityReport["status"] as? String ?? ""
        let reportLoaded = latestProgramDecisionAmbiguityReport.isEmpty == false
        let hasSelection = selected.isEmpty == false
        let choices = hasSelection ? programAmbiguityChoicePayloads(for: selected) : []
        let recommendation = hasSelection
            ? programAmbiguityRecommendationPayload(for: selected, choices: choices)
            : [:]
        let nextActions: [String]
        let status: String

        if !reportLoaded {
            status = "needs_map"
            nextActions = [
                "GET /program_ambiguity_report?sample_limit=500",
                "Shortcut: Option+R"
            ]
        } else if (reviewCount ?? 0) == 0 {
            status = "clear"
            nextActions = ["No sampled overlap review points are currently loaded."]
        } else if !hasSelection {
            status = "needs_review_selection"
            nextActions = [
                "GET /program_ambiguity_review?mode=first",
                "GET /program_ambiguity_review?mode=nearest",
                "Shortcuts: Option+[ / Option+]"
            ]
        } else {
            status = "ready_to_resolve"
            nextActions = choices.flatMap { choice in
                [
                    choice["advanceEndpoint"] as? String,
                    choice["clipPreservingAdvanceEndpoint"] as? String
                ].compactMap { $0 }
            } + [
                "GET /program_ambiguity_resolve?choice=skip&advance=next",
                "GET /program_ambiguity_manual_review?choice=<choice>&note=<why>&actor=<name>&actor_type=human|agent&apply=0|1"
            ]
        }

        return [
            "model": "program-ambiguity-operator",
            "version": "2026-06-19.program-ambiguity-operator.v1",
            "status": status,
            "reportLoaded": reportLoaded,
            "reportStatus": reportStatus,
            "reviewPointCount": reviewCount ?? 0,
            "exampleCount": examples.count,
            "selected": selected,
            "choices": choices,
            "recommendation": recommendation,
            "batchReceipt": latestProgramDecisionAmbiguityBatchReceipt,
            "manualReviewReceipt": latestProgramDecisionAmbiguityManualReviewReceipt,
            "nextSafeActions": nextActions,
            "shortcuts": [
                "mapOverlaps": "Option+R",
                "previousReview": "Option+[",
                "nextReview": "Option+]",
                "resolveFirstAndNext": "Option+1",
                "resolveSecondAndNext": "Option+2",
                "quietGapAndNext": "Option+4",
                "resolveFirstWithClipAndNext": "Option+5",
                "resolveSecondWithClipAndNext": "Option+6"
            ],
            "truth": "This operator guide exposes explicit metadata choices over whole synced lanes. It does not auto-judge the edit, chop source media, touch proxies, export, or publish."
        ]
    }

    private func programAmbiguityChoicePayloads(for example: [String: Any]) -> [[String: Any]] {
        let lanes = example["activeVisualLanes"] as? [[String: Any]] ?? []
        return lanes.enumerated().map { index, lane in
            let name = lane["name"] as? String ?? "source \(index + 1)"
            let role = lane["role"] as? String ?? ""
            let baseChoice = index == 0 ? "first" : (index == 1 ? "second" : (index == 2 ? "third" : ""))
            let clipChoice = index == 0 ? "first_clip" : (index == 1 ? "second_clip" : "")
            var payload: [String: Any] = [
                "index": index,
                "humanIndex": index + 1,
                "name": name,
                "role": role,
                "isSpeakerCandidate": programAmbiguityPayloadLooksLikeSpeaker(lane),
                "isClipOrReferenceCandidate": programAmbiguityPayloadLooksLikeClip(lane)
            ]
            if !baseChoice.isEmpty {
                payload["choice"] = baseChoice
                payload["endpoint"] = "GET /program_ambiguity_resolve?choice=\(baseChoice)"
                payload["advanceEndpoint"] = "GET /program_ambiguity_resolve?choice=\(baseChoice)&advance=next"
            }
            if !clipChoice.isEmpty {
                payload["clipPreservingChoice"] = clipChoice
                payload["clipPreservingAdvanceEndpoint"] = "GET /program_ambiguity_resolve?choice=\(clipChoice)&advance=next"
            }
            return payload
        }
    }

    private func programAmbiguityRecommendationPayload(
        for example: [String: Any],
        choices: [[String: Any]]
    ) -> [String: Any] {
        guard !choices.isEmpty else {
            return [
                "status": "no_choices",
                "label": "No recommendation",
                "reason": "There are no visual lane choices for this review point.",
                "confidence": 0.0,
                "truth": "Recommendation is read-only guidance. It does not mutate edit decisions."
            ]
        }

        let sourceClipChoices = choices.filter { $0["isClipOrReferenceCandidate"] as? Bool == true }
        let speakerChoices = choices.filter { $0["isSpeakerCandidate"] as? Bool == true }
        let namedSpeakerChoices = speakerChoices.filter { !programAmbiguityChoiceLooksUnresolved($0) }
        let activeSourceClipCount = example["activeSourceClipLaneCount"] as? Int ?? sourceClipChoices.count
        let activeSpeakerCount = example["activeSpeakerLaneCount"] as? Int ?? speakerChoices.count

        if activeSourceClipCount > 0,
           let speaker = namedSpeakerChoices.first ?? speakerChoices.first,
           let clipChoice = speaker["clipPreservingChoice"] as? String {
            let label = "Suggest \(speaker["name"] as? String ?? "speaker") + source clip"
            return [
                "status": "recommended",
                "choice": clipChoice,
                "label": label,
                "endpoint": speaker["clipPreservingAdvanceEndpoint"] as? String ?? "GET /program_ambiguity_resolve?choice=\(clipChoice)&advance=next",
                "confidence": namedSpeakerChoices.count == 1 ? 0.78 : 0.64,
                "reason": "A source/title/reference clip is active, so the safest edit preserves clip lanes while choosing the clearest speaker/camera lane instead of treating every overlapping lane as a split-screen.",
                "features": [
                    "activeSpeakerLaneCount": activeSpeakerCount,
                    "activeSourceClipLaneCount": activeSourceClipCount,
                    "namedSpeakerCandidateCount": namedSpeakerChoices.count,
                    "sourceClipCandidateCount": sourceClipChoices.count
                ],
                "safeguards": [
                    "Metadata-only SHOW/SKIP decision",
                    "Whole source media stays untouched",
                    "Requires explicit Apply action"
                ],
                "truth": "This is an edit suggestion, not an automatic judgment. It exists to make Codex and human review explainable."
            ]
        }

        if activeSourceClipCount == 0,
           activeSpeakerCount > 1,
           namedSpeakerChoices.count == 1,
           let choice = namedSpeakerChoices.first?["choice"] as? String {
            let speaker = namedSpeakerChoices[0]
            return [
                "status": "recommended",
                "choice": choice,
                "label": "Suggest \(speaker["name"] as? String ?? "named camera")",
                "endpoint": speaker["advanceEndpoint"] as? String ?? "GET /program_ambiguity_resolve?choice=\(choice)&advance=next",
                "confidence": 0.66,
                "reason": "Only one speaker/camera lane is clearly named while another active visual lane looks unresolved or imported. Prefer the named lane unless the source monitor proves otherwise.",
                "features": [
                    "activeSpeakerLaneCount": activeSpeakerCount,
                    "activeSourceClipLaneCount": activeSourceClipCount,
                    "namedSpeakerCandidateCount": namedSpeakerChoices.count
                ],
                "safeguards": [
                    "Metadata-only SHOW/SKIP decision",
                    "Can be corrected by human review",
                    "Requires explicit Apply action"
                ],
                "truth": "This is a weak recommendation. It should be treated as a review accelerant, not an editor verdict."
            ]
        }

        return [
            "status": "manual_review",
            "label": "Manual review suggested",
            "confidence": 0.35,
            "reason": "The active lanes do not have enough clear role evidence for a safe automatic recommendation. Use the source monitors and Script Spine before choosing.",
            "features": [
                "activeSpeakerLaneCount": activeSpeakerCount,
                "activeSourceClipLaneCount": activeSourceClipCount,
                "choiceCount": choices.count
            ],
            "safeguards": [
                "No auto-apply",
                "Use source monitors",
                "Keep whole source lanes intact"
            ],
            "truth": "Manual review is a productive state. It prevents Codex from pretending uncertainty is confidence."
        ]
    }

    private func programAmbiguityChoiceLooksUnresolved(_ payload: [String: Any]) -> Bool {
        let role = (payload["role"] as? String ?? "").lowercased()
        let name = (payload["name"] as? String ?? "").lowercased()
        return role.contains("unresolved")
            || name.contains("unresolved")
            || name.contains("temp_")
            || name.contains("video clip")
    }

    private func programAmbiguityPayloadLooksLikeSpeaker(_ payload: [String: Any]) -> Bool {
        let role = (payload["role"] as? String ?? "").lowercased()
        let name = (payload["name"] as? String ?? "").lowercased()
        return role.contains("camera")
            || role.contains("charlie")
            || role.contains("homer")
            || name.contains("camera")
            || name.contains("charlie")
            || name.contains("homer")
    }

    private func programAmbiguityPayloadLooksLikeClip(_ payload: [String: Any]) -> Bool {
        let role = (payload["role"] as? String ?? "").lowercased()
        let name = (payload["name"] as? String ?? "").lowercased()
        return role.contains("source")
            || role.contains("clip")
            || role.contains("reference")
            || name.contains("source")
            || name.contains("clip")
            || name.contains("reference")
            || name.contains("title")
    }

    private func navigateProgramDecisionAmbiguityExample(mode: String?, sampleLimit: Int?) {
        guard projectStore.activeSequence != nil else {
            lastMediaAction = "Program ambiguity navigation blocked: no active sequence"
            selectedProgramDecisionAmbiguityExampleIndex = nil
            updateAgentState()
            return
        }

        if ambiguityReportExamples().isEmpty {
            refreshProgramDecisionAmbiguityReport(sampleLimit: sampleLimit)
        }

        let examples = ambiguityReportExamples()
        guard !examples.isEmpty else {
            lastMediaAction = "Program ambiguity navigation found no sampled review examples"
            selectedProgramDecisionAmbiguityExampleIndex = nil
            updateAgentState()
            return
        }

        let currentIndex = selectedProgramDecisionAmbiguityExampleIndex
            .flatMap { examples.indices.contains($0) ? $0 : nil }
        let normalizedMode = (mode ?? "next").lowercased()
        let targetIndex: Int
        switch normalizedMode {
        case "first":
            targetIndex = examples.startIndex
        case "last":
            targetIndex = examples.index(before: examples.endIndex)
        case "previous", "prev", "back":
            targetIndex = max(examples.startIndex, (currentIndex ?? examples.startIndex) - 1)
        case "nearest":
            targetIndex = examples.indices.min { lhs, rhs in
                let lhsTime = examples[lhs]["sampleTime"] as? Double ?? .greatestFiniteMagnitude
                let rhsTime = examples[rhs]["sampleTime"] as? Double ?? .greatestFiniteMagnitude
                return abs(lhsTime - playbackEngine.playhead) < abs(rhsTime - playbackEngine.playhead)
            } ?? examples.startIndex
        default:
            targetIndex = min(examples.index(before: examples.endIndex), (currentIndex ?? -1) + 1)
        }

        selectedProgramDecisionAmbiguityExampleIndex = targetIndex
        let example = examples[targetIndex]
        let sampleTime = example["sampleTime"] as? Double
            ?? example["startTime"] as? Double
            ?? playbackEngine.playhead
        playbackEngine.scrub(to: max(0, sampleTime))
        let lanes = (example["activeVisualLanes"] as? [[String: Any]])?
            .compactMap { $0["name"] as? String }
            .prefix(3)
            .joined(separator: " + ") ?? "multiple lanes"
        lastMediaAction = "Review overlap \(targetIndex + 1)/\(examples.count) at \(String(format: "%.2fs", sampleTime)): \(lanes)"
        updateAgentState()
    }

    private func resolveSelectedProgramAmbiguity(choice: String?, advanceAfterResolve: Bool = false) {
        guard let sequence = projectStore.activeSequence else {
            lastMediaAction = "Program ambiguity resolution blocked: no active sequence"
            updateAgentState()
            return
        }

        let example = selectedProgramDecisionAmbiguityExamplePayload()
        guard !example.isEmpty,
              let startTime = example["startTime"] as? Double,
              let endTime = example["endTime"] as? Double,
              endTime - startTime >= 0.05
        else {
            lastMediaAction = "Program ambiguity resolution blocked: choose a review point first"
            updateAgentState()
            return
        }

        let lanes = example["activeVisualLanes"] as? [[String: Any]] ?? []
        let normalizedChoice = (choice ?? "first")
            .lowercased()
            .trimmingCharacters(in: .whitespacesAndNewlines)
        let compactChoice = normalizedChoice
            .replacingOccurrences(of: " ", with: "")
            .replacingOccurrences(of: "_", with: "")
            .replacingOccurrences(of: "-", with: "")
            .replacingOccurrences(of: "+", with: "")
        let preserveClipLanes = compactChoice.contains("clip")
            || compactChoice.contains("source")
            || compactChoice.contains("reference")
        let showLaneIds: Set<UUID>
        let choiceLabel: String

        if ["skip", "quiet", "cut", "gap"].contains(normalizedChoice) || compactChoice == "skipover" {
            showLaneIds = []
            choiceLabel = "Quiet gap"
        } else {
            let requestedIndex: Int?
            switch compactChoice {
            case "first", "one", "1", "firstclip", "oneclip", "1clip", "firstsource", "onesource", "1source":
                requestedIndex = 0
            case "second", "two", "2", "secondclip", "twoclip", "2clip", "secondsource", "twosource", "2source":
                requestedIndex = 1
            case "third", "three", "3", "thirdclip", "threeclip", "3clip", "thirdsource", "threesource", "3source":
                requestedIndex = 2
            default:
                requestedIndex = nil
            }

            let lanePayload: [String: Any]?
            if let requestedIndex, lanes.indices.contains(requestedIndex) {
                lanePayload = lanes[requestedIndex]
            } else if let directLane = sequence.lanes.first(where: { laneMatches($0, laneId: normalizedChoice) }) {
                lanePayload = ["id": directLane.id.uuidString, "name": directLane.name]
            } else {
                lanePayload = lanes.first
            }

            guard let lanePayload,
                  let laneIdString = lanePayload["id"] as? String,
                  let laneId = UUID(uuidString: laneIdString),
                  sequence.lanes.contains(where: { $0.id == laneId })
            else {
                lastMediaAction = "Program ambiguity resolution blocked: source choice not found"
                updateAgentState()
                return
            }

            var selectedShowLaneIds: Set<UUID> = [laneId]
            if preserveClipLanes {
                for payload in lanes {
                    guard let candidateIdString = payload["id"] as? String,
                          let candidateId = UUID(uuidString: candidateIdString),
                          let candidateLane = sequence.lanes.first(where: { $0.id == candidateId }),
                          isSourceClipProgramLane(candidateLane)
                    else { continue }
                    selectedShowLaneIds.insert(candidateId)
                }
            }

            showLaneIds = selectedShowLaneIds
            let baseLabel = lanePayload["name"] as? String ?? "source"
            choiceLabel = preserveClipLanes ? "\(baseLabel) + clip/source lanes" : baseLabel
        }

        let decisionMap = visualDecisionMap(
            in: sequence,
            showLaneIds: showLaneIds,
            cutOtherVisuals: true
        )
        applyDecisionWindowMap(
            decisionMap,
            sequenceStart: startTime,
            sequenceDuration: endTime - startTime,
            actionName: "Resolve Program Ambiguity",
            autosaveReason: "resolved program ambiguity",
            mediaActionLabel: "Resolved overlap as \(choiceLabel)"
        )
        if advanceAfterResolve {
            refreshProgramDecisionAmbiguityReport(sampleLimit: 500)
            navigateProgramDecisionAmbiguityExample(mode: "first", sampleLimit: 500)
            lastMediaAction = String(
                format: "Resolved overlap %.2fs-%.2fs as %@, remapped, and advanced to the next review point.",
                startTime,
                endTime,
                choiceLabel
            )
            updateAgentState()
        } else {
            latestProgramDecisionAmbiguityReport["stale"] = true
            latestProgramDecisionAmbiguityReport["staleReason"] = "A selected overlap interval was resolved; remap overlaps to refresh counts."
            selectedProgramDecisionAmbiguityExampleIndex = nil
            lastMediaAction = String(
                format: "Resolved overlap %.2fs-%.2fs as %@. Remap overlaps to refresh the review count.",
                startTime,
                endTime,
                choiceLabel
            )
            updateAgentState()
        }
    }

    private func runProgramAmbiguityBatchOperator(
        mode rawMode: String?,
        maxCount rawMaxCount: Int?,
        minConfidence rawMinConfidence: Double?
    ) {
        guard projectStore.activeSequence != nil else {
            latestProgramDecisionAmbiguityBatchReceipt = [
                "status": "blocked",
                "mode": rawMode ?? "preview",
                "reason": "No active sequence is loaded.",
                "truth": "Batch operator did not mutate media or edit metadata."
            ]
            lastMediaAction = "Program ambiguity batch blocked: no active sequence"
            updateAgentState()
            return
        }

        let mode = (rawMode ?? "preview").lowercased().trimmingCharacters(in: .whitespacesAndNewlines)
        let shouldApply = ["apply", "run", "commit", "edit"].contains(mode)
        let maxCount = min(max(rawMaxCount ?? (shouldApply ? 3 : 8), 1), shouldApply ? 8 : 40)
        let minConfidence = min(max(rawMinConfidence ?? 0.75, 0.0), 1.0)
        var inspected: [[String: Any]] = []
        var stoppedReason = ""

        refreshProgramDecisionAmbiguityReport(sampleLimit: 500)

        if shouldApply {
            navigateProgramDecisionAmbiguityExample(mode: "first", sampleLimit: 500)
            var applied = 0

            while applied < maxCount {
                let selected = selectedProgramDecisionAmbiguityExamplePayload()
                guard !selected.isEmpty else {
                    stoppedReason = "No selected review point remained after remapping."
                    break
                }

                let choices = programAmbiguityChoicePayloads(for: selected)
                let recommendation = programAmbiguityRecommendationPayload(for: selected, choices: choices)
                let confidence = recommendation["confidence"] as? Double ?? 0
                guard recommendation["status"] as? String == "recommended",
                      confidence >= minConfidence,
                      let choice = recommendation["choice"] as? String
                else {
                    stoppedReason = recommendation["reason"] as? String ?? "Next recommendation was below threshold."
                    inspected.append(programAmbiguityBatchRow(
                        example: selected,
                        recommendation: recommendation,
                        applied: false,
                        skippedReason: "below_threshold_or_manual_review"
                    ))
                    break
                }

                inspected.append(programAmbiguityBatchRow(
                    example: selected,
                    recommendation: recommendation,
                    applied: true,
                    skippedReason: ""
                ))
                resolveSelectedProgramAmbiguity(choice: choice, advanceAfterResolve: true)
                applied += 1
            }

            if stoppedReason.isEmpty {
                stoppedReason = applied >= maxCount ? "Reached max_count guard." : "No more eligible recommendations."
            }

            latestProgramDecisionAmbiguityBatchReceipt = [
                "status": "applied",
                "mode": "apply",
                "maxCount": maxCount,
                "minConfidence": minConfidence,
                "appliedCount": inspected.filter { $0["applied"] as? Bool == true }.count,
                "inspectedCount": inspected.count,
                "stoppedReason": stoppedReason,
                "rows": inspected,
                "remainingReviewPointCount": latestProgramDecisionAmbiguityReport["reviewPointCount"] as? Int ?? 0,
                "truth": "Batch operator applied only explicit metadata SHOW/SKIP recommendations above threshold. Source media and proxies were not chopped or moved."
            ]
            lastMediaAction = "Program ambiguity batch applied \(inspected.filter { $0["applied"] as? Bool == true }.count) high-confidence recommendation(s)"
            updateAgentState()
            return
        }

        let examples = ambiguityReportExamples()
        for example in examples {
            guard inspected.count < maxCount else {
                stoppedReason = "Reached max_count guard."
                break
            }
            let choices = programAmbiguityChoicePayloads(for: example)
            let recommendation = programAmbiguityRecommendationPayload(for: example, choices: choices)
            let confidence = recommendation["confidence"] as? Double ?? 0
            let isEligible = recommendation["status"] as? String == "recommended" && confidence >= minConfidence
            inspected.append(programAmbiguityBatchRow(
                example: example,
                recommendation: recommendation,
                applied: false,
                skippedReason: isEligible ? "" : "below_threshold_or_manual_review"
            ))
        }

        if stoppedReason.isEmpty {
            stoppedReason = examples.isEmpty ? "No review examples were available." : "Preview only; no edit metadata changed."
        }

        latestProgramDecisionAmbiguityBatchReceipt = [
            "status": "preview",
            "mode": "preview",
            "maxCount": maxCount,
            "minConfidence": minConfidence,
            "eligibleCount": inspected.filter { row in
                guard let recommendation = row["recommendation"] as? [String: Any] else { return false }
                return recommendation["status"] as? String == "recommended"
                    && (recommendation["confidence"] as? Double ?? 0) >= minConfidence
            }.count,
            "inspectedCount": inspected.count,
            "stoppedReason": stoppedReason,
            "rows": inspected,
            "remainingReviewPointCount": latestProgramDecisionAmbiguityReport["reviewPointCount"] as? Int ?? 0,
            "applyEndpoint": "GET /program_ambiguity_batch?mode=apply&max_count=\(maxCount)&min_confidence=\(String(format: "%.2f", minConfidence))",
            "truth": "Preview mode does not mutate edit metadata. Review rows before applying a bounded batch."
        ]
        lastMediaAction = "Program ambiguity batch preview inspected \(inspected.count) recommendation(s)"
        updateAgentState()
    }

    private func recordProgramAmbiguityManualReview(values: [String: String]) {
        guard var sequence = projectStore.activeSequence else {
            latestProgramDecisionAmbiguityManualReviewReceipt = [
                "status": "blocked",
                "reason": "No active sequence is loaded.",
                "truth": "Manual review did not mutate media, edit metadata, or notes."
            ]
            lastMediaAction = "Program ambiguity manual review blocked: no active sequence"
            updateAgentState()
            return
        }

        let note = (values["note"] ?? "")
            .trimmingCharacters(in: .whitespacesAndNewlines)
        guard !note.isEmpty else {
            latestProgramDecisionAmbiguityManualReviewReceipt = [
                "status": "blocked",
                "reason": "A manual review note is required.",
                "truth": "Low-confidence edit decisions need an explicit reason before they become training data."
            ]
            lastMediaAction = "Program ambiguity manual review blocked: note was empty"
            updateAgentState()
            return
        }

        let selected = selectedProgramDecisionAmbiguityExamplePayload()
        guard !selected.isEmpty,
              let startTime = selected["startTime"] as? Double,
              let endTime = selected["endTime"] as? Double
        else {
            latestProgramDecisionAmbiguityManualReviewReceipt = [
                "status": "blocked",
                "reason": "Choose a program ambiguity review point first.",
                "truth": "Manual review receipts attach to a selected overlap interval."
            ]
            lastMediaAction = "Program ambiguity manual review blocked: no selected review point"
            updateAgentState()
            return
        }

        let choices = programAmbiguityChoicePayloads(for: selected)
        let recommendation = programAmbiguityRecommendationPayload(for: selected, choices: choices)
        let recommendedChoice = recommendation["choice"] as? String ?? "manual_review"
        let chosenChoice = (values["choice"] ?? recommendedChoice)
            .lowercased()
            .trimmingCharacters(in: .whitespacesAndNewlines)
        let shouldApply = ["1", "true", "yes", "apply", "next"].contains((values["apply"] ?? "").lowercased())
        let applyableChoice = !["", "manual", "manual_review", "review", "hold", "none"].contains(chosenChoice)
        let actor = values["actor"] ?? "Codex"
        let actorType = values["actor_type"] ?? values["actorType"] ?? "agent"
        let sampleTime = selected["sampleTime"] as? Double ?? max(0, startTime + ((endTime - startTime) / 2))
        let beforePayload: [String: Any] = [
            "selected": selected,
            "choices": choices,
            "recommendation": recommendation,
            "requestedChoice": chosenChoice,
            "requestedApply": shouldApply,
            "truth": "This payload captures the low-confidence review state before any optional metadata edit."
        ]

        var applied = false
        var applyStatus = "recorded_only"
        if shouldApply && applyableChoice {
            resolveSelectedProgramAmbiguity(choice: chosenChoice, advanceAfterResolve: true)
            sequence = projectStore.activeSequence ?? sequence
            applied = true
            applyStatus = "applied"
        } else if shouldApply && !applyableChoice {
            applyStatus = "not_applied_invalid_choice"
        }

        let afterPayload: [String: Any] = [
            "applied": applied,
            "applyStatus": applyStatus,
            "chosenChoice": chosenChoice,
            "remainingReviewPointCount": latestProgramDecisionAmbiguityReport["reviewPointCount"] as? Int ?? 0,
            "truth": applied
                ? "Manual review applied one explicit SHOW/SKIP metadata decision over whole synced lanes."
                : "Manual review captured reasoning only. It did not mutate edit metadata."
        ]
        let record = EditCorrectionNoteRecord(
            actor: actor,
            actorType: actorType,
            category: values["category"] ?? "program-ambiguity-manual-review",
            note: note,
            sequenceTime: sampleTime,
            sourceTime: nil,
            laneId: nil,
            laneName: selected["activeVisualLaneNames"] as? String ?? "",
            tagId: nil,
            tagType: "program-ambiguity",
            beforeJson: compactJSONString(beforePayload),
            afterJson: compactJSONString(afterPayload),
            reviewStatus: applied ? "applied" : "reviewed"
        )

        sequence.editCorrectionNotes.append(record)
        projectStore.updateSequence(sequence, undoManager: nil, actionName: "Record Program Ambiguity Manual Review")
        latestProgramDecisionAmbiguityManualReviewReceipt = [
            "status": applyStatus,
            "noteId": record.id.uuidString,
            "actor": actor,
            "actorType": actorType,
            "choice": chosenChoice,
            "applied": applied,
            "startTime": startTime,
            "endTime": endTime,
            "sampleTime": sampleTime,
            "recommendation": recommendation,
            "note": note,
            "before": beforePayload,
            "after": afterPayload,
            "truth": "This receipt is durable training/context data for a low-confidence edit decision. It preserves source media, proxies, and whole-lane architecture."
        ]
        lastMediaAction = String(
            format: "Manual review %@ for overlap %.2fs-%.2fs: %@",
            applied ? "applied \(chosenChoice)" : "recorded",
            startTime,
            endTime,
            note
        )
        scheduleAutosave(reason: "recorded program ambiguity manual review")
        updateAgentState()
    }

    private func programAmbiguityBatchRow(
        example: [String: Any],
        recommendation: [String: Any],
        applied: Bool,
        skippedReason: String
    ) -> [String: Any] {
        [
            "index": example["index"] as? Int ?? -1,
            "humanIndex": example["humanIndex"] as? Int ?? -1,
            "startTime": example["startTime"] as? Double ?? 0,
            "endTime": example["endTime"] as? Double ?? 0,
            "sampleTime": example["sampleTime"] as? Double ?? 0,
            "activeVisualLaneCount": example["activeVisualLaneCount"] as? Int ?? 0,
            "activeSpeakerLaneCount": example["activeSpeakerLaneCount"] as? Int ?? 0,
            "activeSourceClipLaneCount": example["activeSourceClipLaneCount"] as? Int ?? 0,
            "recommendation": recommendation,
            "applied": applied,
            "skippedReason": skippedReason
        ]
    }

    private func programDecisionAmbiguityReportPayload(for sequence: MediaSequence, sampleLimit: Int?) -> [String: Any] {
        let limit = min(max(sampleLimit ?? 500, 40), 1_500)
        let playableLanes = playableProgramLanes(in: sequence)
        guard !playableLanes.isEmpty else {
            return [
                "status": "no_playable_visual_lanes",
                "reviewPointCount": 0,
                "sampledIntervalCount": 0,
                "sampleLimit": limit,
                "truth": "No playable visual lanes are available for ambiguity analysis."
            ]
        }

        var boundaries = Set<Double>()
        boundaries.insert(0)
        boundaries.insert(max(0, sequence.duration))
        for lane in playableLanes {
            let offset = lane.sourceVideo?.offset ?? 0
            for tag in lane.tags where tag.type == .active || tag.type == .cut {
                let start = max(0, tag.startTime + offset)
                let end = min(max(0, sequence.duration), max(start, tag.startTime + tag.duration + offset))
                if start.isFinite { boundaries.insert(start) }
                if end.isFinite { boundaries.insert(end) }
            }
        }

        let sorted = boundaries.sorted()
        let intervals = zip(sorted, sorted.dropFirst())
            .map { (start: $0.0, end: $0.1) }
            .filter { $0.end - $0.start > 0.05 }
        let stride = max(1, Int(ceil(Double(intervals.count) / Double(limit))))
        var sampledIntervalCount = 0
        var reviewPointCount = 0
        var maxActiveVisualLaneCount = 0
        var maxActiveSpeakerLaneCount = 0
        var examples: [[String: Any]] = []

        for (index, interval) in intervals.enumerated() where index % stride == 0 {
            sampledIntervalCount += 1
            let time = (interval.start + interval.end) / 2
            let activeLanes = activeProgramLanes(in: sequence, at: time)
            let speakerLanes = activeLanes.filter(isSpeakerProgramLane)
            let sourceClipLanes = activeLanes.filter(isSourceClipProgramLane)
            maxActiveVisualLaneCount = max(maxActiveVisualLaneCount, activeLanes.count)
            maxActiveSpeakerLaneCount = max(maxActiveSpeakerLaneCount, speakerLanes.count)
            let needsReview = speakerLanes.count > 1 || activeLanes.count > 2
            guard needsReview else { continue }
            reviewPointCount += 1
            if examples.count < 24 {
                examples.append([
                    "startTime": interval.start,
                    "endTime": interval.end,
                    "sampleTime": time,
                    "duration": interval.end - interval.start,
                    "activeVisualLaneCount": activeLanes.count,
                    "activeSpeakerLaneCount": speakerLanes.count,
                    "activeSourceClipLaneCount": sourceClipLanes.count,
                    "activeVisualLanes": activeLanes.map { lane in
                        [
                            "id": lane.id.uuidString,
                            "name": lane.name,
                            "role": lane.metadata?.role ?? "",
                            "trackIds": lane.metadata?.trackIds ?? []
                        ] as [String: Any]
                    }
                ])
            }
        }

        return [
            "status": reviewPointCount > 0 ? "needs_program_decision_review" : "clear_in_sample",
            "reviewPointCount": reviewPointCount,
            "sampledIntervalCount": sampledIntervalCount,
            "sourceIntervalCount": intervals.count,
            "sampleLimit": limit,
            "maxActiveVisualLaneCount": maxActiveVisualLaneCount,
            "maxActiveSpeakerLaneCount": maxActiveSpeakerLaneCount,
            "examples": examples,
            "plainEnglish": reviewPointCount > 0
                ? "Some sampled intervals have multiple speaker/visual lanes marked SHOW. Review these before treating inherited Premiere decisions as final Quipsly program truth."
                : "No sampled intervals showed obvious program-decision ambiguity.",
            "truth": "This report samples SHOW/SKIP metadata over whole lanes. It is a review map, not a grade, and it does not mutate media, decisions, exports, or publication state."
        ]
    }

    private func activeProgramLanes(in sequence: MediaSequence, at sequenceTime: Double) -> [VideoLane] {
        playableProgramLanes(in: sequence)
            .filter { decision(for: $0, at: sequenceTime)?.type == .active }
            .sorted { lhs, rhs in
                programLayoutSortKey(lhs) < programLayoutSortKey(rhs)
            }
    }

    private func decision(for lane: VideoLane, at sequenceTime: Double) -> VideoTag? {
        let offset = lane.sourceVideo?.offset ?? 0
        let localTime = sequenceTime - offset
        return lane.tags
            .filter { tag in
                guard tag.type == .active || tag.type == .cut else { return false }
                return localTime >= tag.startTime && localTime < tag.startTime + tag.duration
            }
            .sorted {
                if $0.startTime == $1.startTime {
                    return $0.duration < $1.duration
                }
                return $0.startTime > $1.startTime
            }
            .first
    }

    private func isSpeakerProgramLane(_ lane: VideoLane) -> Bool {
        let role = (lane.metadata?.role ?? "").lowercased()
        let name = lane.name.lowercased()
        return role.contains("camera")
            || role.contains("charlie")
            || role.contains("homer")
            || name.contains("camera")
            || name.contains("charlie")
            || name.contains("homer")
    }

    private func isSourceClipProgramLane(_ lane: VideoLane) -> Bool {
        let role = (lane.metadata?.role ?? "").lowercased()
        let name = lane.name.lowercased()
        return role.contains("source")
            || role.contains("clip")
            || role.contains("reference")
            || name.contains("source clip")
            || name.contains("reference")
    }

    private func programCropPayload(for lane: VideoLane, format: ExportFormat) -> [String: Any] {
        let baseline: ProgramCropAdjustment
        let keyframes: [ProgramCropKeyframe]
        switch format {
        case .horizontal16x9:
            baseline = lane.metadata?.programCrop16x9 ?? ProgramCropAdjustment()
            keyframes = lane.metadata?.programCropKeyframes16x9 ?? []
        case .vertical9x16:
            baseline = lane.metadata?.programCrop9x16 ?? ProgramCropAdjustment()
            keyframes = lane.metadata?.programCropKeyframes9x16 ?? []
        }
        let atPlayhead = ProgramCropAdjustment.interpolated(
            baseline: baseline,
            keyframes: keyframes,
            at: playbackEngine.playhead
        )
        return [
            "format": format.rawValue,
            "editMode": programCropEditMode.rawValue,
            "editModeLabel": programCropEditMode.title,
            "gestureTarget": programCropGestureTargetDescription(),
            "playhead": playbackEngine.playhead,
            "panX": baseline.panX,
            "panY": baseline.panY,
            "zoom": baseline.zoom,
            "baseline": programCropValuePayload(baseline),
            "atPlayhead": programCropValuePayload(atPlayhead),
            "truth": "Base framing fixes the whole lane for this output format. Keyframes override it over time. Both are render metadata over protected source media.",
            "keyframeCount": keyframes.count,
            "keyframes": keyframes.prefix(12).map { keyframe in
                [
                    "id": keyframe.id.uuidString,
                    "time": keyframe.time,
                    "panX": keyframe.panX,
                    "panY": keyframe.panY,
                    "zoom": keyframe.zoom,
                    "interpolation": keyframe.interpolation.rawValue
                ]
            }
        ]
    }

    private func programCropValuePayload(_ crop: ProgramCropAdjustment) -> [String: Any] {
        [
            "panX": crop.panX,
            "panY": crop.panY,
            "zoom": crop.zoom
        ]
    }

    private func programCropKeyframes(for lane: VideoLane, format: ExportFormat) -> [ProgramCropKeyframe] {
        switch format {
        case .horizontal16x9:
            return lane.metadata?.programCropKeyframes16x9 ?? []
        case .vertical9x16:
            return lane.metadata?.programCropKeyframes9x16 ?? []
        }
    }

    private func programLayoutSortKey(_ lane: VideoLane) -> String {
        let role = (lane.metadata?.role ?? "").lowercased()
        let name = lane.name.lowercased()
        if role.contains("charlie") || name.contains("charlie") {
            return "00-charlie-\(lane.name)"
        }
        if role.contains("homer") || name.contains("homer") {
            return "01-homer-\(lane.name)"
        }
        if role.contains("clip") || name.contains("clip") || name.contains("reference") {
            return "02-clip-\(lane.name)"
        }
        return "99-\(lane.name)"
    }

    private func defaultProgramSlotName(index: Int, total: Int) -> String {
        guard total > 1 else { return "full_frame" }
        if playbackEngine.playbackFormat == .vertical9x16 {
            return index == 0 ? "top_stack" : (index == 1 ? "bottom_stack" : "stack_\(index + 1)")
        }
        return index == 0 ? "left_split" : (index == 1 ? "right_split" : "split_\(index + 1)")
    }

    private func selectedTranscriptSegmentValue(in sequence: MediaSequence? = nil) -> TranscriptSegment? {
        guard let selectedTranscriptSegmentId else { return nil }
        let activeSequence = sequence ?? projectStore.activeSequence
        return activeSequence?.transcriptSegments.first { $0.id == selectedTranscriptSegmentId }
    }

    private func currentTranscriptSegment(in sequence: MediaSequence) -> TranscriptSegment? {
        let time = playbackEngine.playhead
        return sequence.transcriptSegments
            .sorted { $0.startTime < $1.startTime }
            .first { segment in
                time >= segment.startTime && time < max(segment.endTime, segment.startTime + 0.01)
            }
    }

    private func seedDemoTranscriptForActiveSequence() {
        guard var sequence = projectStore.activeSequence else {
            lastMediaAction = "Script seed blocked: no active sequence"
            updateAgentState()
            return
        }

        let segments = demoTranscriptSegments(for: sequence)
        guard !segments.isEmpty else {
            lastMediaAction = "Script seed blocked: no valid sequence ranges"
            updateAgentState()
            return
        }

        sequence.transcriptSegments = segments
        selectedTranscriptSegmentId = segments.first?.id
        selectedTranscriptWordSegmentId = segments.first?.id
        selectedTranscriptWordIndex = segments.first.map { _ in 0 }
        if let first = segments.first {
            playbackEngine.scrub(to: first.startTime)
        }
        leftWorkbenchMode = .transcript
        isInspectorVisible = true
        projectStore.updateSequence(sequence, undoManager: nil, actionName: "Seed Script Spine")
        lastMediaAction = "Seeded transcript spine with \(segments.count) timed demo segment(s)"
        scheduleAutosave(reason: "seeded transcript spine")
        updateAgentState()
    }

