    private func importTranscriptForActiveSequence(path: String?, format: String?) {
        guard var sequence = projectStore.activeSequence else {
            lastMediaAction = "Script import blocked: no active sequence"
            updateAgentState()
            return
        }

        guard let path,
              !path.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty else {
            lastMediaAction = "Script import blocked: missing transcript path"
            updateAgentState()
            return
        }

        let url = URL(fileURLWithPath: path)
        do {
            let text = try String(contentsOf: url, encoding: .utf8)
            let imported = try TranscriptParser.parse(
                text: text,
                filename: url.lastPathComponent,
                format: format ?? "auto"
            )
            sequence.transcriptSegments = imported
            selectedTranscriptSegmentId = imported.first?.id
            selectedTranscriptWordSegmentId = imported.first?.id
            selectedTranscriptWordIndex = imported.first.map { _ in 0 }
            if let first = imported.first {
                playbackEngine.scrub(to: first.startTime)
            }
            leftWorkbenchMode = .transcript
            isInspectorVisible = true
            projectStore.updateSequence(sequence, undoManager: nil, actionName: "Import Script Spine")
            lastMediaAction = "Imported transcript spine: \(imported.count) segment(s) from \(url.lastPathComponent)"
            scheduleAutosave(reason: "imported transcript spine")
        } catch {
            lastMediaAction = "Script import failed: \(error.localizedDescription)"
        }
        updateAgentState()
    }

    private func generateTranscriptForActiveSequence(laneId rawLaneId: String?, commandPath rawCommandPath: String?) {
        guard var sequence = projectStore.activeSequence else {
            lastMediaAction = "Script generation blocked: no active sequence"
            updateAgentState()
            return
        }

        let requestedLaneId = rawLaneId?.trimmingCharacters(in: .whitespacesAndNewlines)
        let laneIndex: Int?
        if let requestedLaneId, !requestedLaneId.isEmpty {
            laneIndex = sequence.lanes.firstIndex { laneMatches($0, laneId: requestedLaneId) }
        } else if let selectedLaneId {
            laneIndex = sequence.lanes.firstIndex { $0.id == selectedLaneId }
        } else {
            laneIndex = sequence.lanes.firstIndex { $0.sourceVideo != nil && ($0.metadata?.mediaKind.lowercased() == "audio" || $0.name.lowercased().contains("audio")) }
                ?? sequence.lanes.firstIndex { $0.sourceVideo != nil }
        }

        guard let laneIndex, sequence.lanes.indices.contains(laneIndex) else {
            lastMediaAction = "Script generation blocked: select a source lane or pass lane_id"
            updateAgentState()
            return
        }

        let lane = sequence.lanes[laneIndex]
        guard let sourceVideo = lane.sourceVideo else {
            lastMediaAction = "Script generation blocked: selected lane has no source media"
            updateAgentState()
            return
        }
        let sourceAssetId = sourceVideo.id

        guard let mediaURL = transcriptReadableMediaURL(for: lane) else {
            lastMediaAction = "Script generation blocked: selected lane needs a readable proxy or local media path"
            updateAgentState()
            return
        }

        let commandPath = rawCommandPath?.trimmingCharacters(in: .whitespacesAndNewlines)
        let jobId = UUID()
        let job = TranscriptJobRecord(
            id: jobId,
            sourceLaneId: lane.id,
            sourceLaneName: lane.name,
            sourcePath: mediaURL.path,
            provider: (commandPath?.isEmpty == false) ? "local-command" : "sidecar-or-configured-command",
            commandPath: commandPath?.isEmpty == false ? commandPath : nil,
            status: "running",
            startedAt: Date()
        )
        sequence.transcriptJobs.append(job)
        selectedLaneId = lane.id
        selectedTagId = nil
        leftWorkbenchMode = .transcript
        isInspectorVisible = true
        projectStore.updateSequence(sequence, undoManager: nil, actionName: "Start Script Generation")
        lastMediaAction = "Script generation started for \(lane.name)"
        scheduleAutosave(reason: "started transcript generation")
        updateAgentState()

        Task.detached(priority: .utility) {
            do {
                let generated = try Self.generateTranscriptSegments(
                    from: mediaURL,
                    commandPath: commandPath
                )
                let generatedSegments = generated.segments.map { segment -> TranscriptSegment in
                    var updated = segment
                    updated.sourceAssetId = sourceAssetId
                    return updated
                }
                let generatedProvider = generated.provider
                let generatedCommandPath = generated.commandPath
                let generatedCount = generatedSegments.count

                await MainActor.run {
                    guard var currentSequence = projectStore.activeSequence else { return }
                    if let index = currentSequence.transcriptJobs.firstIndex(where: { $0.id == jobId }) {
                        currentSequence.transcriptJobs[index].status = "completed"
                        currentSequence.transcriptJobs[index].provider = generatedProvider
                        currentSequence.transcriptJobs[index].commandPath = generatedCommandPath
                        currentSequence.transcriptJobs[index].completedAt = Date()
                        currentSequence.transcriptJobs[index].error = ""
                        currentSequence.transcriptJobs[index].segmentCount = generatedCount
                    }
                    currentSequence.transcriptSegments = generatedSegments
                    selectedTranscriptSegmentId = generatedSegments.first?.id
                    selectedTranscriptWordSegmentId = generatedSegments.first?.id
                    selectedTranscriptWordIndex = generatedSegments.first.map { _ in 0 }
                    if let first = generatedSegments.first {
                        playbackEngine.scrub(to: first.startTime)
                    }
                    projectStore.updateSequence(currentSequence, undoManager: nil, actionName: "Generate Script Spine")
                    lastMediaAction = "Generated transcript spine: \(generatedCount) segment(s) from \(generatedProvider)"
                    scheduleAutosave(reason: "generated transcript spine")
                    updateAgentState()
                }
            } catch {
                await MainActor.run {
                    guard var currentSequence = projectStore.activeSequence else { return }
                    if let index = currentSequence.transcriptJobs.firstIndex(where: { $0.id == jobId }) {
                        currentSequence.transcriptJobs[index].status = "failed"
                        currentSequence.transcriptJobs[index].completedAt = Date()
                        currentSequence.transcriptJobs[index].error = error.localizedDescription
                        currentSequence.transcriptJobs[index].segmentCount = 0
                    }
                    projectStore.updateSequence(currentSequence, undoManager: nil, actionName: "Fail Script Generation")
                    lastMediaAction = "Script generation failed: \(error.localizedDescription)"
                    scheduleAutosave(reason: "recorded transcript generation failure")
                    updateAgentState()
                }
            }
        }
    }

    private func defaultLocalTranscriptProviderPath() -> String? {
        let sourceFile = URL(fileURLWithPath: #filePath)
        let root = sourceFile
            .deletingLastPathComponent()
            .deletingLastPathComponent()
            .deletingLastPathComponent()
        let candidate = root.appendingPathComponent("script/local_transcript_provider.py")
        return FileManager.default.isExecutableFile(atPath: candidate.path) ? candidate.path : nil
    }

    private func transcriptReadableMediaURL(for lane: VideoLane) -> URL? {
        guard let sourceVideo = lane.sourceVideo else { return nil }
        let candidates = [sourceVideo.proxyURL, Optional(sourceVideo.mediaURL)].compactMap { $0 }
        return candidates.first { FileManager.default.fileExists(atPath: $0.path) }
    }

    nonisolated private static func generateTranscriptSegments(from mediaURL: URL, commandPath rawCommandPath: String?) throws -> (segments: [TranscriptSegment], provider: String, commandPath: String?) {
        if let sidecar = transcriptSidecarURL(for: mediaURL) {
            let text = try String(contentsOf: sidecar, encoding: .utf8)
            let segments = try TranscriptParser.parse(text: text, filename: sidecar.lastPathComponent, format: "auto")
            return (segments, "sidecar-\(sidecar.pathExtension.lowercased())", nil)
        }

        let commandPath = rawCommandPath?.trimmingCharacters(in: .whitespacesAndNewlines) ?? ""
        guard !commandPath.isEmpty else {
            throw NSError(
                domain: "QuipslyTranscript",
                code: 1,
                userInfo: [
                    NSLocalizedDescriptionKey: "No .srt/.vtt sidecar was found next to the selected media and no local transcriber command path was provided."
                ]
            )
        }

        let commandURL = URL(fileURLWithPath: commandPath)
        guard FileManager.default.isExecutableFile(atPath: commandURL.path) else {
            throw NSError(
                domain: "QuipslyTranscript",
                code: 2,
                userInfo: [
                    NSLocalizedDescriptionKey: "Transcriber command is not executable: \(commandURL.path)"
                ]
            )
        }

        let output = try runTranscriptCommand(commandURL: commandURL, mediaURL: mediaURL)
        let segments = try TranscriptParser.parse(text: output, filename: commandURL.lastPathComponent, format: "auto")
        return (segments, "local-command", commandURL.path)
    }

    nonisolated private static func transcriptSidecarURL(for mediaURL: URL) -> URL? {
        let base = mediaURL.deletingPathExtension()
        for ext in ["srt", "vtt"] {
            let candidate = base.appendingPathExtension(ext)
            if FileManager.default.fileExists(atPath: candidate.path) {
                return candidate
            }
        }
        return nil
    }

    nonisolated private static func runTranscriptCommand(commandURL: URL, mediaURL: URL) throws -> String {
        let process = Process()
        process.executableURL = commandURL
        process.arguments = [mediaURL.path]

        let stdout = Pipe()
        let stderr = Pipe()
        process.standardOutput = stdout
        process.standardError = stderr

        try process.run()
        process.waitUntilExit()

        let stdoutText = String(data: stdout.fileHandleForReading.readDataToEndOfFile(), encoding: .utf8) ?? ""
        let stderrText = String(data: stderr.fileHandleForReading.readDataToEndOfFile(), encoding: .utf8) ?? ""

        guard process.terminationStatus == 0 else {
            throw NSError(
                domain: "QuipslyTranscript",
                code: Int(process.terminationStatus),
                userInfo: [
                    NSLocalizedDescriptionKey: stderrText.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty
                        ? "Transcriber command failed with exit code \(process.terminationStatus)."
                        : stderrText.trimmingCharacters(in: .whitespacesAndNewlines)
                ]
            )
        }

        guard !stdoutText.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty else {
            throw NSError(
                domain: "QuipslyTranscript",
                code: 3,
                userInfo: [
                    NSLocalizedDescriptionKey: "Transcriber command produced no SRT/VTT text on stdout."
                ]
            )
        }

        return stdoutText
    }

    private func normalizedTranscriptSearchText(_ text: String) -> String {
        text
            .lowercased()
            .components(separatedBy: CharacterSet.alphanumerics.inverted)
            .filter { !$0.isEmpty }
            .joined(separator: " ")
    }

    private func transcriptSearchWordIndex(query: String, in segment: TranscriptSegment) -> Int? {
        let queryTokens = normalizedTranscriptSearchText(query)
            .split(separator: " ")
            .map(String.init)
        guard !queryTokens.isEmpty else { return nil }

        let words = transcriptWordTimings(for: segment)
        for (index, word) in words.enumerated() {
            let normalizedWord = normalizedTranscriptSearchText(word.word)
            guard !normalizedWord.isEmpty else { continue }
            if queryTokens.contains(normalizedWord) {
                return index
            }
        }
        return nil
    }

    private func searchTranscriptForAgent(query rawQuery: String?, mode rawMode: String?) {
        guard let sequence = projectStore.activeSequence else {
            latestTranscriptSearchReceipt = [
                "status": "blocked",
                "query": rawQuery ?? "",
                "reason": "No active sequence is loaded."
            ]
            lastMediaAction = "Script search blocked: no active sequence"
            updateAgentState()
            return
        }

        let query = (rawQuery ?? "").trimmingCharacters(in: .whitespacesAndNewlines)
        let normalizedQuery = normalizedTranscriptSearchText(query)
        guard !normalizedQuery.isEmpty else {
            latestTranscriptSearchReceipt = [
                "status": "blocked",
                "query": query,
                "reason": "Search query is empty."
            ]
            lastMediaAction = "Script search blocked: empty query"
            updateAgentState()
            return
        }

        let ordered = sequence.transcriptSegments.sorted { $0.startTime < $1.startTime }
        guard !ordered.isEmpty else {
            latestTranscriptSearchReceipt = [
                "status": "blocked",
                "query": query,
                "reason": "No transcript segments exist on the active sequence."
            ]
            lastMediaAction = "Script search blocked: no transcript segments"
            updateAgentState()
            return
        }

        let matches = ordered.enumerated().filter { _, segment in
            let haystack = normalizedTranscriptSearchText("\(segment.speaker) \(segment.text)")
            return haystack.contains(normalizedQuery)
        }

        guard !matches.isEmpty else {
            latestTranscriptSearchReceipt = [
                "status": "no_match",
                "query": query,
                "mode": rawMode ?? "next",
                "matchCount": 0,
                "truth": "Transcript search found no matching timed segment. No media or edit decisions changed."
            ]
            lastMediaAction = "Script search found no match for \(query)"
            updateAgentState()
            return
        }

        let selectedIndex = selectedTranscriptSegmentId.flatMap { selectedId in
            ordered.firstIndex { $0.id == selectedId }
        } ?? ordered.firstIndex(where: { segment in
            playbackEngine.playhead >= segment.startTime && playbackEngine.playhead < segment.endTime
        }) ?? 0

        let mode = (rawMode ?? "next").lowercased().trimmingCharacters(in: .whitespacesAndNewlines)
        let targetPair: (offset: Int, element: TranscriptSegment)
        switch mode {
        case "first":
            targetPair = matches[0]
        case "previous", "prev":
            targetPair = matches.reversed().first { $0.offset < selectedIndex } ?? matches.last!
        case "current", "at_playhead", "now":
            targetPair = matches.first { match in
                playbackEngine.playhead >= match.element.startTime && playbackEngine.playhead < match.element.endTime
            } ?? matches.first { $0.element.startTime >= playbackEngine.playhead } ?? matches[0]
        default:
            targetPair = matches.first { $0.offset > selectedIndex } ?? matches[0]
        }

        let segment = targetPair.element
        let wordIndex = transcriptSearchWordIndex(query: query, in: segment)
        if let wordIndex {
            selectTranscriptWord(segment: segment, wordIndex: wordIndex)
        } else {
            selectTranscriptSegment(segment)
        }

        latestTranscriptSearchReceipt = [
            "status": "found",
            "query": query,
            "mode": mode,
            "matchCount": matches.count,
            "matchIndex": targetPair.offset,
            "segmentId": segment.id.uuidString,
            "speaker": segment.speaker,
            "startTime": segment.startTime,
            "endTime": segment.endTime,
            "wordIndex": wordIndex ?? -1,
            "text": segment.text,
            "truth": "Transcript search selects a timed segment or word on the shared playhead. It does not mutate media, SHOW/SKIP decisions, shorts, exports, or publication state."
        ]
        lastMediaAction = String(format: "Script search found %@ at %.2fs (%@)", query, segment.startTime, segment.speaker)
        updateAgentState()
    }

    private func selectTranscriptSegment(_ segment: TranscriptSegment) {
        selectedTranscriptSegmentId = segment.id
        selectedTranscriptWordSegmentId = segment.id
        selectedTranscriptWordIndex = 0
        leftWorkbenchMode = .transcript
        isInspectorVisible = true
        playbackEngine.scrub(to: max(0, segment.startTime))
        lastMediaAction = String(format: "Selected transcript segment %.2fs: %@", segment.startTime, segment.speaker)
        updateAgentState()
    }

    private func selectTranscriptSegmentForAgent(mode rawMode: String?, id rawId: String?) {
        guard let sequence = projectStore.activeSequence else {
            lastMediaAction = "Script select blocked: no active sequence"
            updateAgentState()
            return
        }

        let ordered = sequence.transcriptSegments.sorted { $0.startTime < $1.startTime }
        guard !ordered.isEmpty else {
            lastMediaAction = "Script select blocked: no transcript segments"
            updateAgentState()
            return
        }

        if let rawId,
           let id = UUID(uuidString: rawId),
           let segment = ordered.first(where: { $0.id == id }) {
            selectTranscriptSegment(segment)
            return
        }

        let mode = (rawMode ?? "at_playhead").lowercased().trimmingCharacters(in: .whitespacesAndNewlines)
        let currentIndex = selectedTranscriptSegmentId.flatMap { selectedId in
            ordered.firstIndex { $0.id == selectedId }
        } ?? ordered.firstIndex(where: { segment in
            playbackEngine.playhead >= segment.startTime && playbackEngine.playhead < segment.endTime
        }) ?? 0

        let target: TranscriptSegment
        switch mode {
        case "first":
            target = ordered[0]
        case "next":
            target = ordered[min(ordered.count - 1, currentIndex + 1)]
        case "previous", "prev":
            target = ordered[max(0, currentIndex - 1)]
        case "at_playhead", "current", "now":
            target = currentTranscriptSegment(in: sequence)
                ?? ordered.first(where: { $0.startTime >= playbackEngine.playhead })
                ?? ordered.last!
        default:
            target = ordered[0]
        }

        selectTranscriptSegment(target)
    }

    private func selectTranscriptWord(segment: TranscriptSegment, wordIndex rawIndex: Int) {
        let words = transcriptWordTimings(for: segment)
        guard !words.isEmpty else {
            selectedTranscriptSegmentId = segment.id
            selectedTranscriptWordSegmentId = nil
            selectedTranscriptWordIndex = nil
            leftWorkbenchMode = .transcript
            isInspectorVisible = true
            playbackEngine.scrub(to: max(0, segment.startTime))
            lastMediaAction = "Script word select fell back to segment start: no words available"
            updateAgentState()
            return
        }

        let index = min(max(rawIndex, 0), words.count - 1)
        let word = words[index]
        selectedTranscriptSegmentId = segment.id
        selectedTranscriptWordSegmentId = segment.id
        selectedTranscriptWordIndex = index
        leftWorkbenchMode = .transcript
        isInspectorVisible = true
        playbackEngine.scrub(to: max(0, word.startTime))
        lastMediaAction = String(
            format: "Selected transcript word %@ at %.2fs (%@)",
            word.word,
            word.startTime,
            segment.speaker
        )
        updateAgentState()
    }

    private func selectTranscriptWordForAgent(mode rawMode: String?, segmentId rawSegmentId: String?, index rawIndex: String?) {
        guard let sequence = projectStore.activeSequence else {
            lastMediaAction = "Script word select blocked: no active sequence"
            updateAgentState()
            return
        }

        let ordered = sequence.transcriptSegments.sorted { $0.startTime < $1.startTime }
        guard !ordered.isEmpty else {
            lastMediaAction = "Script word select blocked: no transcript segments"
            updateAgentState()
            return
        }

        let requestedSegmentId = rawSegmentId.flatMap(UUID.init(uuidString:))
        let segment: TranscriptSegment
        if let requestedSegmentId,
           let requested = ordered.first(where: { $0.id == requestedSegmentId }) {
            segment = requested
        } else if let selectedTranscriptWordSegmentId,
                  let selected = ordered.first(where: { $0.id == selectedTranscriptWordSegmentId }) {
            segment = selected
        } else if let selectedTranscriptSegmentId,
                  let selected = ordered.first(where: { $0.id == selectedTranscriptSegmentId }) {
            segment = selected
        } else {
            segment = currentTranscriptSegment(in: sequence)
                ?? ordered.first(where: { $0.startTime >= playbackEngine.playhead })
                ?? ordered[0]
        }

        let words = transcriptWordTimings(for: segment)
        guard !words.isEmpty else {
            selectTranscriptSegment(segment)
            return
        }

        if let rawIndex,
           let explicitIndex = Int(rawIndex) {
            selectTranscriptWord(segment: segment, wordIndex: explicitIndex)
            return
        }

        let mode = (rawMode ?? "current").lowercased().trimmingCharacters(in: .whitespacesAndNewlines)
        let currentIndex: Int = {
            if selectedTranscriptWordSegmentId == segment.id,
               let selectedTranscriptWordIndex {
                return min(max(selectedTranscriptWordIndex, 0), words.count - 1)
            }
            return activeTranscriptWordIndex(words: words, segment: segment, at: playbackEngine.playhead) ?? 0
        }()

        let targetIndex: Int
        switch mode {
        case "first":
            targetIndex = 0
        case "last":
            targetIndex = words.count - 1
        case "next":
            targetIndex = min(words.count - 1, currentIndex + 1)
        case "previous", "prev":
            targetIndex = max(0, currentIndex - 1)
        case "at_playhead", "current", "now":
            targetIndex = activeTranscriptWordIndex(words: words, segment: segment, at: playbackEngine.playhead) ?? currentIndex
        default:
            targetIndex = currentIndex
        }

        selectTranscriptWord(segment: segment, wordIndex: targetIndex)
    }

    private func selectedTranscriptWordValue(in sequence: MediaSequence? = nil) -> (segment: TranscriptSegment, index: Int, word: TranscriptWordTiming)? {
        guard let selectedTranscriptWordSegmentId,
              let selectedTranscriptWordIndex else {
            return nil
        }
        let activeSequence = sequence ?? projectStore.activeSequence
        guard let segment = activeSequence?.transcriptSegments.first(where: { $0.id == selectedTranscriptWordSegmentId }) else {
            return nil
        }
        let words = transcriptWordTimings(for: segment)
        guard words.indices.contains(selectedTranscriptWordIndex) else {
            return nil
        }
        return (segment, selectedTranscriptWordIndex, words[selectedTranscriptWordIndex])
    }

    private func applySelectedTranscriptToShort(field rawField: String?) {
        guard let segment = selectedTranscriptSegmentValue() else {
            lastMediaAction = "Script apply blocked: no selected transcript segment"
            updateAgentState()
            return
        }

        guard selectedShortClipValue() != nil else {
            lastMediaAction = "Script apply blocked: select a short recipe first"
            updateAgentState()
            return
        }

        let field = (rawField ?? "caption").lowercased().trimmingCharacters(in: .whitespacesAndNewlines)
        updateSelectedShortClip { clip in
            switch field {
            case "overlay", "primary_overlay", "primaryoverlay":
                clip.primaryOverlayText = segment.text
            case "hook", "hook_text", "hooktext":
                clip.hookText = segment.text
            case "caption", "caption_draft", "captiondraft":
                clip.captionDraft = segment.text
            default:
                clip.captionDraft = segment.text
            }
            clip.notes = appendLine(
                String(format: "Script %@ applied from %.2fs-%.2fs (%@)", field.isEmpty ? "caption" : field, segment.startTime, segment.endTime, segment.speaker),
                to: clip.notes
            )
        }
        lastMediaAction = "Applied transcript segment to selected short \(field.isEmpty ? "caption" : field)"
        updateAgentState()
    }

    private func createShortFromTranscriptForAgent(
        mode rawMode: String?,
        title requestedTitle: String?,
        paddingBefore rawPaddingBefore: Double?,
        paddingAfter rawPaddingAfter: Double?,
        actor rawActor: String?,
        actorType rawActorType: String?
    ) {
        guard var sequence = projectStore.activeSequence else {
            latestTranscriptToShortReceipt = [
                "status": "blocked",
                "reason": "no_active_sequence",
                "createdAt": ISO8601DateFormatter().string(from: Date())
            ]
            lastMediaAction = "Transcript short blocked: no active sequence"
            updateAgentState()
            return
        }

        let mode = (rawMode ?? "current").lowercased().trimmingCharacters(in: .whitespacesAndNewlines)
        let ordered = sequence.transcriptSegments.sorted { $0.startTime < $1.startTime }
        let selectedSegment = selectedTranscriptSegmentValue(in: sequence)
        let currentSegment = currentTranscriptSegment(in: sequence)
        let segment: TranscriptSegment?
        switch mode {
        case "selected":
            segment = selectedSegment ?? currentSegment ?? ordered.first
        case "first":
            segment = ordered.first
        case "last":
            segment = ordered.last
        case "next":
            if let selectedSegment,
               let index = ordered.firstIndex(where: { $0.id == selectedSegment.id }),
               ordered.indices.contains(index + 1) {
                segment = ordered[index + 1]
            } else {
                segment = ordered.first(where: { $0.startTime > playbackEngine.playhead }) ?? ordered.first
            }
        case "previous", "prev":
            if let selectedSegment,
               let index = ordered.firstIndex(where: { $0.id == selectedSegment.id }),
               ordered.indices.contains(index - 1) {
                segment = ordered[index - 1]
            } else {
                segment = ordered.last(where: { $0.endTime < playbackEngine.playhead }) ?? ordered.first
            }
        case "current", "at_playhead", "now":
            segment = currentSegment ?? selectedSegment ?? ordered.first(where: { $0.startTime >= playbackEngine.playhead }) ?? ordered.first
        default:
            segment = currentSegment ?? selectedSegment ?? ordered.first
        }

        guard let segment else {
            latestTranscriptToShortReceipt = [
                "status": "blocked",
                "reason": "no_transcript_segments",
                "mode": mode,
                "createdAt": ISO8601DateFormatter().string(from: Date())
            ]
            lastMediaAction = "Transcript short blocked: no transcript segment"
            updateAgentState()
            return
        }

        let paddingBefore = max(0, rawPaddingBefore ?? 1.0)
        let paddingAfter = max(0, rawPaddingAfter ?? 2.0)
        let minimumDuration = 0.15
        let sequenceDuration = max(sequence.duration, segment.endTime + paddingAfter, minimumDuration)
        let start = min(max(0, segment.startTime - paddingBefore), max(0, sequenceDuration - minimumDuration))
        let end = max(start + minimumDuration, min(sequenceDuration, segment.endTime + paddingAfter))
        let duration = max(minimumDuration, end - start)
        let trimmedTitle = requestedTitle?.trimmingCharacters(in: .whitespacesAndNewlines) ?? ""
        let defaultTitle = transcriptShortTitle(for: segment)
        let title = trimmedTitle.isEmpty ? defaultTitle : trimmedTitle
        let actor = (rawActor?.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty == false ? rawActor! : "unknown")
        let actorType = (rawActorType?.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty == false ? rawActorType! : "agent")
        let notes = [
            "Queued from transcript segment \(segment.id.uuidString).",
            String(format: "Speaker: %@. Transcript %.2fs-%.2fs. Recipe %.2fs-%.2fs.", segment.speaker, segment.startTime, segment.endTime, start, end),
            "Actor: \(actor) (\(actorType)).",
            "Transcript text: \(segment.text)"
        ].joined(separator: "\n")
        let segmentRecipe = ShortClipSegment(
            title: "Transcript line - \(segment.speaker)",
            startTime: start,
            duration: duration,
            notes: "Source transcript segment \(segment.id.uuidString)"
        )
        let candidate = ShortClipCandidate(
            title: title,
            startTime: start,
            duration: duration,
            segments: [segmentRecipe],
            status: "queued",
            reviewStatus: "needs-human-review",
            exportStatus: "not-exported",
            hookText: transcriptHookText(for: segment),
            captionDraft: segment.text,
            primaryOverlayText: transcriptOverlayText(for: segment),
            publishNotes: "Created from Script Spine. Verify transcript timing and edit framing before publication.",
            sourceLaneId: nil,
            sourceTagId: nil,
            notes: notes
        )

        let beforeLedger: [String: Any] = [
            "shortClipQueueCount": sequence.shortClipQueue.count,
            "selectedShortClipId": selectedShortClipId?.uuidString ?? "",
            "transcriptSegmentId": segment.id.uuidString,
            "playhead": playbackEngine.playhead
        ]
        sequence.shortClipQueue.append(candidate)
        selectedShortClipId = candidate.id
        selectedTranscriptSegmentId = segment.id
        selectedTranscriptWordSegmentId = segment.id
        selectedTranscriptWordIndex = activeTranscriptWordIndex(
            words: transcriptWordTimings(for: segment),
            segment: segment,
            at: playbackEngine.playhead
        ) ?? 0
        selectedLaneId = nil
        selectedTagId = nil
        playbackEngine.playbackFormat = .vertical9x16
        playbackEngine.scrub(to: start)
        leftWorkbenchMode = .shorts
        isInspectorVisible = true
        latestTranscriptToShortReceipt = [
            "status": "created",
            "id": candidate.id.uuidString,
            "title": candidate.title,
            "mode": mode,
            "speaker": segment.speaker,
            "transcriptSegmentId": segment.id.uuidString,
            "transcriptStart": segment.startTime,
            "transcriptEnd": segment.endTime,
            "sequenceStart": start,
            "sequenceEnd": start + duration,
            "duration": duration,
            "actor": actor,
            "actorType": actorType,
            "createdAt": ISO8601DateFormatter().string(from: Date()),
            "truth": "Transcript-created shorts are output recipes over sequence time. They do not cut source media."
        ]
        appendEditActionLedgerEntry(
            to: &sequence,
            actionId: "transcript-create-short",
            actionLabel: "Create short from transcript",
            category: "script-to-short",
            endpoint: "GET /transcript_create_short",
            lane: nil,
            tag: nil,
            before: beforeLedger,
            after: latestTranscriptToShortReceipt,
            note: notes,
            actor: actor,
            actorType: actorType
        )
        projectStore.updateSequence(sequence, undoManager: nil, actionName: "Queue Transcript Short")
        lastMediaAction = String(format: "Queued transcript short %.2fs -> %.2fs: %@", start, start + duration, title)
        requestTimelineFocus(reason: "Focused transcript-created short recipe on the Episode Trail Map")
        scheduleAutosave(reason: "queued transcript short recipe")
        updateAgentState()
    }

    private func transcriptShortTitle(for segment: TranscriptSegment) -> String {
        let tokens = transcriptWordTokens(segment.text).prefix(6)
        let phrase = tokens.joined(separator: " ")
        let suffix = phrase.isEmpty ? "spoken moment" : phrase
        return String(format: "%@ - %@", segment.speaker, suffix)
    }

    private func transcriptHookText(for segment: TranscriptSegment) -> String {
        let text = segment.text.trimmingCharacters(in: .whitespacesAndNewlines)
        guard text.count > 96 else { return text }
        let index = text.index(text.startIndex, offsetBy: 96)
        return String(text[..<index]).trimmingCharacters(in: .whitespacesAndNewlines) + "..."
    }

    private func transcriptOverlayText(for segment: TranscriptSegment) -> String {
        let tokens = transcriptWordTokens(segment.text).prefix(8)
        let overlay = tokens.joined(separator: " ")
        return overlay.isEmpty ? segment.speaker : overlay
    }

    private func demoTranscriptSegments(for sequence: MediaSequence) -> [TranscriptSegment] {
        let ranges = PlaybackEngine.computeValidRanges(for: sequence)
        let fallbackEnd = min(max(sequence.duration, 0), 8)
        let usableRanges = ranges.isEmpty && fallbackEnd > 0
            ? [0...fallbackEnd]
            : ranges
        let sampleLines = [
            ("Charlie", "This is the transcript spine: one timed line that can become captions, quotes, shorts, and search."),
            ("Homer", "The editor keeps the source lanes whole while the transcript and decisions describe what to publish."),
            ("Charlie", "When transcription is automated, these segments become reviewable suggestions instead of magic text."),
            ("Homer", "A selected transcript line can feed a short caption without copying text into disconnected boxes."),
            ("Charlie", "Scrubbing the timeline should always keep the words, monitors, and edit decisions in the same truth."),
            ("Homer", "This is demo text for proving the workflow before we ask ASR to generate real episode words.")
        ]

        return usableRanges
            .prefix(sampleLines.count)
            .enumerated()
            .compactMap { index, range -> TranscriptSegment? in
                let start = max(0, range.lowerBound)
                let boundedEnd = min(max(range.upperBound, start + 0.5), start + 8.0)
                guard boundedEnd > start else { return nil }
                let sample = sampleLines[index % sampleLines.count]
                return TranscriptSegment(
                    speaker: sample.0,
                    startTime: start,
                    endTime: boundedEnd,
                    text: sample.1,
                    words: demoTranscriptWordTimings(
                        text: sample.1,
                        startTime: start,
                        endTime: boundedEnd
                    ),
                    confidence: 0.72,
                    reviewStatus: "demo"
                )
            }
    }

    private func demoTranscriptWordTimings(text: String, startTime: Double, endTime: Double) -> [TranscriptWordTiming] {
        let tokens = transcriptWordTokens(text)
        guard !tokens.isEmpty else { return [] }
        let duration = max(0.01, endTime - startTime)
        let step = duration / Double(tokens.count)
        return tokens.enumerated().map { index, word in
            let start = startTime + (Double(index) * step)
            return TranscriptWordTiming(
                word: word,
                startTime: start,
                endTime: min(endTime, start + step),
                confidence: 0.72,
                source: "demo-word-timing"
            )
        }
    }

    private func selectedLane() -> VideoLane? {
        guard let laneId = selectedLaneId,
              selectedTagId == nil,
              let sequence = projectStore.activeSequence else {
            return nil
        }

        return sequence.lanes.first(where: { $0.id == laneId })
    }

    private func selectedProgramCropLane() -> VideoLane? {
        guard let laneId = selectedLaneId,
              let sequence = projectStore.activeSequence else {
            return nil
        }

        return sequence.lanes.first(where: { $0.id == laneId })
    }

    private func selectedProgramCropAdjustment() -> ProgramCropAdjustment {
        guard let lane = selectedProgramCropLane() else {
            return ProgramCropAdjustment()
        }

        switch playbackEngine.playbackFormat {
        case .horizontal16x9:
            return lane.metadata?.programCrop16x9 ?? ProgramCropAdjustment()
        case .vertical9x16:
            return lane.metadata?.programCrop9x16 ?? ProgramCropAdjustment()
        }
    }

    private func selectedProgramCropAtPlayheadAdjustment() -> ProgramCropAdjustment {
        guard let lane = selectedProgramCropLane() else {
            return ProgramCropAdjustment()
        }

        let baseline: ProgramCropAdjustment
        let keyframes: [ProgramCropKeyframe]
        switch playbackEngine.playbackFormat {
        case .horizontal16x9:
            baseline = lane.metadata?.programCrop16x9 ?? ProgramCropAdjustment()
            keyframes = lane.metadata?.programCropKeyframes16x9 ?? []
        case .vertical9x16:
            baseline = lane.metadata?.programCrop9x16 ?? ProgramCropAdjustment()
            keyframes = lane.metadata?.programCropKeyframes9x16 ?? []
        }

        return ProgramCropAdjustment.interpolated(
            baseline: baseline,
            keyframes: keyframes,
            at: playbackEngine.playhead
        )
    }

    private func selectedProgramCropKeyframeCount() -> Int {
        guard let lane = selectedProgramCropLane() else { return 0 }
        return programCropKeyframes(for: lane, format: playbackEngine.playbackFormat).count
    }

    private func clearSelection() {
        selectedLaneId = nil
        selectedTagId = nil
        lastMediaAction = "Cleared selection"
        updateAgentState()
    }

    private func selectSourceLane(_ laneId: UUID) {
        guard let sequence = projectStore.activeSequence,
              let lane = sequence.lanes.first(where: { $0.id == laneId }) else {
            return
        }

        selectedLaneId = lane.id
        selectedTagId = nil
        playbackEngine.seek(to: max(0, lane.sourceVideo?.offset ?? playbackEngine.playhead))
        lastMediaAction = "Selected source monitor: \(lane.name)"
        updateAgentState()
    }

    private func beginRelinkLane(_ laneId: UUID) {
        selectSourceLane(laneId)
        relinkingLaneId = laneId
        isShowingRelinkImporter = true
        if let lane = projectStore.activeSequence?.lanes.first(where: { $0.id == laneId }) {
            lastMediaAction = "Choose a readable whole source for \(lane.name)"
        }
        updateAgentState()
    }

    private func beginAttachProxy(_ laneId: UUID) {
        selectSourceLane(laneId)
        proxyAttachingLaneId = laneId
        isShowingAttachProxyImporter = true
        if let lane = projectStore.activeSequence?.lanes.first(where: { $0.id == laneId }) {
            lastMediaAction = "Choose a local full-length proxy for \(lane.name); original source will stay unchanged"
        }
        updateAgentState()
    }

    private func showSourceLaneWindow(_ laneId: UUID) {
        applySourceWallDecision(laneId: laneId, type: .active, sequenceDuration: 10)
    }

    private func cutSourceLaneWindow(_ laneId: UUID) {
        applySourceWallDecision(laneId: laneId, type: .cut, sequenceDuration: 10)
    }

    private func applySourceWallDecision(laneId: UUID, type: TagType, sequenceDuration requestedDuration: Double) {
        guard let sequence = projectStore.activeSequence,
              sequence.lanes.contains(where: { $0.id == laneId }) else {
            lastMediaAction = "Source-wall decision failed: lane not found"
            updateAgentState()
            return
        }

        let sequenceStart = min(max(0, playbackEngine.playhead), max(0, sequence.duration))
        let decisionMap: [UUID: TagType]
        if type == .active {
            decisionMap = visualDecisionMap(
                in: sequence,
                showLaneIds: [laneId],
                cutOtherVisuals: true
            )
        } else {
            decisionMap = [laneId: .cut]
        }

        applyDecisionWindowMap(
            decisionMap,
            sequenceStart: sequenceStart,
            sequenceDuration: requestedDuration,
            actionName: type == .active ? "Show Source Window" : "Cut Source Window",
            autosaveReason: type == .active ? "source-wall show decision" : "source-wall cut decision",
            mediaActionLabel: type == .active ? "Added SHOW source-wall decision" : "Added CUT source-wall decision"
        )
    }

    private func applyDecisionWindowMap(
        _ decisionsByLaneId: [UUID: TagType],
        sequenceStart requestedSequenceStart: Double,
        sequenceDuration requestedDuration: Double,
        actionName: String,
        autosaveReason: String,
        mediaActionLabel: String
    ) {
        guard var sequence = projectStore.activeSequence else { return }
        let sequenceStart = min(max(0, requestedSequenceStart), max(0, sequence.duration))
        let sequenceEnd = min(max(sequenceStart, sequenceStart + max(0.1, requestedDuration)), max(0, sequence.duration))
        guard sequenceEnd - sequenceStart >= 0.05 else {
            lastMediaAction = "Source-wall decision failed: no room at the current playhead"
            updateAgentState()
            return
        }

        var preferredSelectedDecision: (laneId: UUID, tagId: UUID, type: TagType)? = nil
        var fallbackSelectedDecision: (laneId: UUID, tagId: UUID, type: TagType)? = nil

        func replaceDecisionWindow(laneIndex: Int, with decisionType: TagType) {
            guard sequence.lanes.indices.contains(laneIndex) else { return }
            let lane = sequence.lanes[laneIndex]
            let offset = lane.sourceVideo?.offset ?? 0
            let laneDuration = max(0, lane.sourceVideo?.duration ?? lane.duration)
            guard laneDuration > 0 else { return }

            var replacementTags: [VideoTag] = []
            for tag in lane.tags {
                guard tag.type == .active || tag.type == .cut else {
                    replacementTags.append(tag)
                    continue
                }

                let tagSequenceStart = tag.startTime + offset
                let tagSequenceEnd = tagSequenceStart + tag.duration

                if tagSequenceEnd <= sequenceStart || tagSequenceStart >= sequenceEnd {
                    replacementTags.append(tag)
                    continue
                }

                if tagSequenceStart < sequenceStart {
                    var left = tag
                    left.duration = max(0, sequenceStart - tagSequenceStart)
                    if left.duration >= 0.05 {
                        replacementTags.append(left)
                    }
                }

                if tagSequenceEnd > sequenceEnd {
                    var right = tag
                    right.startTime = max(0, sequenceEnd - offset)
                    right.duration = max(0, tagSequenceEnd - sequenceEnd)
                    if right.duration >= 0.05 {
                        replacementTags.append(right)
                    }
                }
            }

            let localStart = max(0, sequenceStart - offset)
            let localEnd = min(laneDuration, sequenceEnd - offset)
            let localDuration = localEnd - localStart
            guard localDuration >= 0.05 else {
                sequence.lanes[laneIndex].tags = replacementTags.sorted { $0.startTime < $1.startTime }
                return
            }

            let newTag = VideoTag(type: decisionType, startTime: localStart, duration: localDuration)
            replacementTags.append(newTag)
            sequence.lanes[laneIndex].tags = replacementTags.sorted { $0.startTime < $1.startTime }

            let selected = (sequence.lanes[laneIndex].id, newTag.id, decisionType)
            if decisionType == .active {
                if preferredSelectedDecision == nil {
                    preferredSelectedDecision = selected
                }
            } else if fallbackSelectedDecision == nil {
                fallbackSelectedDecision = selected
            }
        }

        for laneIndex in sequence.lanes.indices {
            let lane = sequence.lanes[laneIndex]
            guard let decisionType = decisionsByLaneId[lane.id] else { continue }
            replaceDecisionWindow(laneIndex: laneIndex, with: decisionType)
        }

        projectStore.updateSequence(sequence, undoManager: nil, actionName: actionName)
        if let selectedDecision = preferredSelectedDecision ?? fallbackSelectedDecision {
            selectedLaneId = selectedDecision.laneId
            selectedTagId = selectedDecision.tagId
        }
        playbackEngine.updateValidRanges(for: sequence)
        playbackEngine.seek(to: sequenceStart)
        rebuildPlayer()
        lastMediaAction = String(
            format: "%@ · %.1fs at %.2fs",
            mediaActionLabel,
            sequenceEnd - sequenceStart,
            sequenceStart
        )
        scheduleAutosave(reason: autosaveReason)
        updateAgentState()
    }

    private func seekToSelectedDecision(_ selected: (lane: VideoLane, tag: VideoTag)) {
        let sequenceTime = max(0, (selected.lane.sourceVideo?.offset ?? 0) + selected.tag.startTime)
        playbackEngine.seek(to: sequenceTime)
        lastMediaAction = String(format: "Jumped to selected decision at %.2fs", sequenceTime)
        updateAgentState()
    }

    private func setSelectedLaneRole(_ role: String) {
        guard let laneId = selectedLaneId else {
            return
        }

        assignLaneRole(laneId: laneId.uuidString, role: role)
    }

    private func assignLaneRole(laneId: String, role: String) {
        guard var sequence = projectStore.activeSequence,
              let laneIndex = sequence.lanes.firstIndex(where: { laneMatches($0, laneId: laneId) }) else {
            return
        }

        var metadata = sequence.lanes[laneIndex].metadata ?? VideoLaneMetadata(
            mediaKind: role.contains("audio") ? "audio" : "video",
            role: role,
            sourcePath: sequence.lanes[laneIndex].sourceVideo?.mediaURL.path,
            originalPath: sequence.lanes[laneIndex].sourceVideo?.mediaURL.path,
            declaredExists: sequence.lanes[laneIndex].metadata?.declaredExists,
            sourceLabel: sequence.lanes[laneIndex].sourceVideo?.mediaURL.lastPathComponent
        )

        metadata.role = role
        if role.contains("audio") {
            metadata.mediaKind = "audio"
        } else {
            metadata.mediaKind = "video"
        }

        sequence.lanes[laneIndex].metadata = metadata
        sequence.lanes[laneIndex].name = laneName(for: role, metadata: metadata, fallback: sequence.lanes[laneIndex].name)
        projectStore.updateSequence(sequence, undoManager: nil, actionName: "Assign Lane Role")
        playbackEngine.updateValidRanges(for: sequence)
        scheduleAutosave(reason: "assigned lane role")
        updateAgentState()
    }

    private func setLaneProductionIgnored(laneId: String, ignored: Bool) {
        guard var sequence = projectStore.activeSequence,
              let laneIndex = sequence.lanes.firstIndex(where: { laneMatches($0, laneId: laneId) }) else {
            return
        }

        var metadata = sequence.lanes[laneIndex].metadata ?? VideoLaneMetadata(
            mediaKind: isSupportOnlyLane(sequence.lanes[laneIndex]) ? "audio" : "video",
            role: sequence.lanes[laneIndex].metadata?.role ?? "unknown",
            sourcePath: sequence.lanes[laneIndex].sourceVideo?.mediaURL.path,
            originalPath: sequence.lanes[laneIndex].sourceVideo?.mediaURL.path,
            declaredExists: sequence.lanes[laneIndex].metadata?.declaredExists,
            sourceLabel: sequence.lanes[laneIndex].sourceVideo?.mediaURL.lastPathComponent
        )
        metadata.ignoreForProduction = ignored ? true : nil
        sequence.lanes[laneIndex].metadata = metadata

        projectStore.updateSequence(sequence, undoManager: nil, actionName: ignored ? "Hold Lane For Recovery" : "Unhold Lane For Production")
        playbackEngine.updateSourcePlayers(for: sequence)
        playbackEngine.updateValidRanges(for: sequence)
        lastMediaAction = ignored
            ? "Held \(sequence.lanes[laneIndex].name) for recovery; excluded from Play Edit and export"
            : "Unheld \(sequence.lanes[laneIndex].name); included in production readiness again"
        scheduleAutosave(reason: ignored ? "held lane for recovery" : "unheld lane for production")
        updateAgentState()
    }

    private func laneName(for role: String, metadata: VideoLaneMetadata, fallback: String) -> String {
        let label = metadata.sourceLabel?.isEmpty == false ? metadata.sourceLabel! : fallback
        let tracks = metadata.trackIds.isEmpty ? "" : "\(metadata.trackIds.joined(separator: ",")) "

        switch role {
        case "charlie_camera":
            return "Charlie Camera - \(label)"
        case "homer_camera":
            return "Homer Camera - \(label)"
        case "source_clip":
            return "Source Clip \(tracks)- \(label)".replacingOccurrences(of: "  ", with: " ")
        case "reference_clip":
            return "Reference Clip - \(label)"
        case "audio":
            return "Audio \(tracks)- \(label)".replacingOccurrences(of: "  ", with: " ")
        default:
            return label
        }
    }

    private func deleteSelectedTag() {
        guard let laneId = selectedLaneId,
              let tagId = selectedTagId,
              var sequence = projectStore.activeSequence,
              let laneIndex = sequence.lanes.firstIndex(where: { $0.id == laneId }) else {
            return
        }

        sequence.lanes[laneIndex].tags.removeAll(where: { $0.id == tagId })
        selectedLaneId = nil
        selectedTagId = nil
        projectStore.updateSequence(sequence, undoManager: nil, actionName: "Delete Decision")
        playbackEngine.updateValidRanges(for: sequence)
        rebuildPlayer()
        lastMediaAction = "Deleted selected decision"
        scheduleAutosave(reason: "deleted decision")
        updateAgentState()
    }

    private func selectTag(laneId: String, tagId: String) {
        guard let sequence = projectStore.activeSequence,
              let lane = sequence.lanes.first(where: { laneMatches($0, laneId: laneId) }),
              let tag = lane.tags.first(where: { tagMatches($0, tagId: tagId) }) else {
            lastMediaAction = "Select decision failed: tag not found"
            updateAgentState()
            return
        }

        selectedLaneId = lane.id
        selectedTagId = tag.id
        let sequenceTime = (lane.sourceVideo?.offset ?? 0) + tag.startTime
        playbackEngine.seek(to: max(0, sequenceTime))
        lastMediaAction = "Selected \(tag.type.rawValue.uppercased()) decision on \(lane.name)"
        updateAgentState()
    }

    private func selectDecision(mode: String, laneId: String?, scope: String? = nil) {
        guard let sequence = projectStore.activeSequence else {
            lastMediaAction = "Select decision failed: no active sequence"
            updateAgentState()
            return
        }

        let requestedMode = mode.lowercased().replacingOccurrences(of: "-", with: "_")
        let requestedScope = scope?.lowercased().replacingOccurrences(of: "-", with: "_") ?? ""
        let normalizedScope: String
        let normalizedMode: String

        if requestedMode.hasSuffix("_video") || requestedMode.hasSuffix("_visual") || requestedMode.hasSuffix("_source") {
            normalizedScope = "video"
            normalizedMode = requestedMode
                .replacingOccurrences(of: "_video", with: "")
                .replacingOccurrences(of: "_visual", with: "")
                .replacingOccurrences(of: "_source", with: "")
        } else if requestedMode.hasSuffix("_support") || requestedMode.hasSuffix("_audio") {
            normalizedScope = "support"
            normalizedMode = requestedMode
                .replacingOccurrences(of: "_support", with: "")
                .replacingOccurrences(of: "_audio", with: "")
        } else if ["video", "visual", "source"].contains(requestedScope) {
            normalizedScope = "video"
            normalizedMode = requestedMode
        } else if ["support", "audio", "context"].contains(requestedScope) {
            normalizedScope = "support"
            normalizedMode = requestedMode
        } else {
            normalizedScope = "all"
            normalizedMode = requestedMode
        }

        let lanes = sequence.lanes.filter { lane in
            if let laneId, !laneId.isEmpty, !laneMatches(lane, laneId: laneId) {
                return false
            }

            switch normalizedScope {
            case "video":
                return !isSupportOnlyLane(lane)
            case "support":
                return isSupportOnlyLane(lane)
            default:
                return true
            }
        }

        var candidates: [(lane: VideoLane, tag: VideoTag, sequenceTime: Double)] = []
        for lane in lanes {
            let offset = lane.sourceVideo?.offset ?? 0
            for tag in lane.tags where tag.type == .active || tag.type == .cut {
                candidates.append((lane, tag, offset + tag.startTime))
            }
        }

        guard !candidates.isEmpty else {
            let scopeLabel = normalizedScope == "all" ? "" : " \(normalizedScope)"
            lastMediaAction = "Select decision failed: no\(scopeLabel) SHOW/SKIP decisions found"
            updateAgentState()
            return
        }

        let playhead = playbackEngine.playhead
        let selected: (lane: VideoLane, tag: VideoTag, sequenceTime: Double)?

        if normalizedScope == "video",
           ["next", "previous", "prev", "first", "first_active"].contains(normalizedMode) {
            let boundaryMarkers = decisionBoundaryMarkers(scope: "video", laneId: laneId)
            let marker: DecisionMarker?
            switch normalizedMode {
            case "next":
                marker = boundaryMarkers
                    .first(where: { $0.sequenceTime > playhead + 0.05 })
                    ?? boundaryMarkers.first
            case "previous", "prev":
                marker = boundaryMarkers
                    .last(where: { $0.sequenceTime < playhead - 0.05 })
                    ?? boundaryMarkers.last
            default:
                marker = boundaryMarkers.first
            }

            if let marker,
               let lane = sequence.lanes.first(where: { $0.id == marker.laneId }),
               let tag = lane.tags.first(where: { $0.id == marker.tagId }) {
                selected = (lane, tag, marker.sequenceTime)
            } else {
                selected = nil
            }
        } else {
            switch normalizedMode {
            case "next":
                selected = candidates
                    .filter { $0.sequenceTime > playhead + 0.001 }
                    .min { $0.sequenceTime < $1.sequenceTime }
                    ?? candidates.min { $0.sequenceTime < $1.sequenceTime }
            case "previous", "prev":
                selected = candidates
                    .filter { $0.sequenceTime < playhead - 0.001 }
                    .max { $0.sequenceTime < $1.sequenceTime }
                    ?? candidates.max { $0.sequenceTime < $1.sequenceTime }
            case "first", "first_active":
                selected = candidates.min { $0.sequenceTime < $1.sequenceTime }
            case "at_playhead", "current":
            let atPlayhead = lanes.compactMap { lane -> (lane: VideoLane, tag: VideoTag, sequenceTime: Double)? in
                guard let tag = decisionAtPlayhead(for: lane) else { return nil }
                return (lane, tag, (lane.sourceVideo?.offset ?? 0) + tag.startTime)
            }
                selected = normalizedScope == "video"
                    ? (atPlayhead.first(where: { $0.tag.type == .active }) ?? atPlayhead.first
                        ?? candidates.min { abs($0.sequenceTime - playhead) < abs($1.sequenceTime - playhead) })
                    : (atPlayhead.first
                ?? candidates.min { abs($0.sequenceTime - playhead) < abs($1.sequenceTime - playhead) }
                    )
            default:
                selected = candidates.min { $0.sequenceTime < $1.sequenceTime }
            }
        }

        guard let selected else {
            lastMediaAction = "Select decision failed: no matching decision"
            updateAgentState()
            return
        }

        selectedLaneId = selected.lane.id
        selectedTagId = selected.tag.id
        playbackEngine.seek(to: max(0, selected.sequenceTime))
        lastMediaAction = String(
            format: "Selected %@ %@ decision via %@ at %.2fs on %@",
            selected.tag.type.rawValue.uppercased(),
            normalizedScope,
            normalizedMode,
            selected.sequenceTime,
            selected.lane.name
        )
        updateAgentState()
    }

    private func nudgeSelectedTag(by delta: Double) {
        guard let laneId = selectedLaneId,
              let tagId = selectedTagId,
              var sequence = projectStore.activeSequence,
              let laneIndex = sequence.lanes.firstIndex(where: { $0.id == laneId }),
              let tagIndex = sequence.lanes[laneIndex].tags.firstIndex(where: { $0.id == tagId }) else {
            return
        }

        let lane = sequence.lanes[laneIndex]
        let laneDuration = lane.sourceVideo?.duration ?? sequence.duration
        var tag = sequence.lanes[laneIndex].tags[tagIndex]
        tag.startTime = min(max(0, tag.startTime + delta), max(0, laneDuration - tag.duration))
        sequence.lanes[laneIndex].tags[tagIndex] = tag

        projectStore.updateSequence(sequence, undoManager: nil, actionName: "Nudge Decision")
        playbackEngine.updateValidRanges(for: sequence)
        playbackEngine.seek(to: (lane.sourceVideo?.offset ?? 0) + tag.startTime)
        rebuildPlayer()
        lastMediaAction = String(format: "Nudged selected decision to %.2fs", tag.startTime)
        scheduleAutosave(reason: "nudged decision")
        updateAgentState()
    }

    private func trimSelectedTag(startDelta: Double, durationDelta: Double) {
        guard let laneId = selectedLaneId,
              let tagId = selectedTagId,
              var sequence = projectStore.activeSequence,
              let laneIndex = sequence.lanes.firstIndex(where: { $0.id == laneId }),
              let tagIndex = sequence.lanes[laneIndex].tags.firstIndex(where: { $0.id == tagId }) else {
            lastMediaAction = "Trim decision failed: no selected decision"
            updateAgentState()
            return
        }

        let lane = sequence.lanes[laneIndex]
        let laneDuration = lane.sourceVideo?.duration ?? sequence.duration
        var tag = sequence.lanes[laneIndex].tags[tagIndex]
        let minimumDuration = 0.1
        let proposedStart = tag.startTime + startDelta
        let proposedDuration = tag.duration + durationDelta
        let boundedStart = min(max(0, proposedStart), max(0, laneDuration - minimumDuration))
        let boundedDuration = min(
            max(minimumDuration, proposedDuration),
            max(minimumDuration, laneDuration - boundedStart)
        )

        tag.startTime = boundedStart
        tag.duration = boundedDuration
        sequence.lanes[laneIndex].tags[tagIndex] = tag

        projectStore.updateSequence(sequence, undoManager: nil, actionName: "Trim Decision")
        playbackEngine.updateValidRanges(for: sequence)
        playbackEngine.seek(to: (lane.sourceVideo?.offset ?? 0) + tag.startTime)
        rebuildPlayer()
        lastMediaAction = String(format: "Trimmed selected decision to %.2fs for %.2fs", tag.startTime, tag.duration)
        scheduleAutosave(reason: "trimmed decision")
        updateAgentState()
    }

    private func handleAgentCommandDispatch(fallbackToLegacy: Bool) {
        let queuedRequests = agentServer.drainCommandRequests()
        if !queuedRequests.isEmpty {
            lastDrainedAgentCommandSerial = agentServer.commandSerial
            for request in queuedRequests {
                handleAgentCommand(request)
            }
            agentServer.commandToExecute = ""
            updateAgentState()
            return
        }

        guard fallbackToLegacy else { return }
        handleLegacyAgentCommand()
    }

    private func handleAgentCommand(_ request: AgentCommandRequest) {
        switch request.name {
        case "load_demo":
            loadDemoEdit()
        case "import_file":
            if let path = request.values["path"] {
                loadVideoIntoProject(url: URL(fileURLWithPath: path), allowProtectedOriginalProbe: false)
            }
        case "load_premiere_packet":
            if let path = request.values["path"] {
                loadPremierePacket(url: URL(fileURLWithPath: path))
            }
        case "playback":
            applyAgentPlayback(
                mode: request.values["mode"],
                action: request.values["action"]
            )
        case "lane_role":
            if let laneId = request.values["lane_id"],
               let role = request.values["role"] {
                assignLaneRole(laneId: laneId, role: role)
            }
        case "lane_production_ignore":
            if let laneId = request.values["lane_id"] {
                let ignore = ["1", "true", "yes", "ignore", "held", "hold"].contains((request.values["ignore"] ?? "1").lowercased())
                setLaneProductionIgnored(laneId: laneId, ignored: ignore)
            }
        case "save_session":
            saveNativeSession(named: request.values["name"] ?? "autosave")
        case "load_session":
            loadNativeSession(named: request.values["name"] ?? "autosave")
        case "vault_lane":
            if let laneId = request.values["lane_id"] {
                vaultLaneMedia(laneId: laneId)
            }
        case "relink_lane":
            if let laneId = request.values["lane_id"],
               let path = request.values["path"] {
                let queueProxy = ["1", "true", "yes"].contains((request.values["queue_proxy"] ?? "").lowercased())
                relinkLaneMedia(laneId: laneId, sourceURL: URL(fileURLWithPath: path), queueProxy: queueProxy)
            }
        case "attach_proxy":
            if let laneId = request.values["lane_id"],
               let path = request.values["path"] {
                attachProxyToLane(laneId: laneId, proxyURL: URL(fileURLWithPath: path))
            }
        case "match_folder":
            relinkExpectedMediaFromExternalFolder(rootPathOverride: request.values["path"])
        case "export_proxy_package":
            exportProxyPackageForAgent(
                directoryPath: request.values["directory"],
                basename: request.values["basename"],
                proofSeconds: Double(request.values["proof_seconds"] ?? "")
            )
        case "audio_master_export":
            exportAudioMasterForAgent(
                directoryPath: request.values["directory"],
                basename: request.values["basename"],
                proofSeconds: Double(request.values["proof_seconds"] ?? "")
            )
        case "delivery_packet_generate":
            generateDeliveryPacketForAgent(
                directoryPath: request.values["directory"],
                basename: request.values["basename"]
            )
        case "nest_seed_context":
            seedHighGroundOdysseyNestContext()
        case "nest_ensure_writing_document":
            ensureNestWritingDocument()
        case "nest_writing_packet_generate":
            generateNestWritingPacketForAgent(
                directoryPath: request.values["directory"],
                basename: request.values["basename"]
            )
        case "nest_writing_next_action":
            performNestWritingNextActionForAgent(
                index: request.values["index"],
                kind: request.values["kind"]
            )
        case "nest_append_block":
            appendNestBlockFromAgent(
                title: request.values["title"],
                text: request.values["text"],
                tags: request.values["tags"],
                role: request.values["role"],
                episodeSlug: request.values["episode"],
                authorship: request.values["authorship"],
                provenanceNote: request.values["provenance"],
                reviewStatus: request.values["review_status"]
            )
        case "nest_mark_block":
            updateSelectedNestBlockReviewStatus(
                request.values["status"] ?? "needs-human-review",
                note: request.values["note"] ?? "Marked by agent through Nest review-state route.",
                blockId: request.values["block_id"]
            )
        case "nest_update_block":
            updateSelectedNestBlockStructure(
                role: request.values["role"],
                tags: request.values["tags"],
                episodeSlug: request.values["episode"],
                chapterSlug: request.values["chapter"],
                note: request.values["note"] ?? "Structured by agent through Nest structure route.",
                blockId: request.values["block_id"]
            )
        case "nest_replace_block_text":
            replaceNestBlockText(
                blockId: request.values["block_id"],
                text: request.values["text"],
                note: request.values["note"],
                reviewStatus: request.values["review_status"]
            )
        case "nest_select_block":
            selectNestBlockById(request.values["block_id"])
        case "release_prepare":
            prepareReleaseForAgent(
                directoryPath: request.values["directory"],
                basename: request.values["basename"],
                proofSeconds: Double(request.values["proof_seconds"] ?? "")
            )
        case "full_release_prepare":
            prepareFullReleaseForAgent(
                directoryPath: request.values["directory"],
                basename: request.values["basename"],
                proofSeconds: Double(request.values["proof_seconds"] ?? "")
            )
        case "publish_ledger_generate":
            generatePublishLedgerFromCurrentDelivery()
        case "publish_packet_generate":
            generatePublishPacketForAgent(
                directoryPath: request.values["directory"],
                basename: request.values["basename"]
            )
        case "vertical_slice_packet_generate":
            generateVerticalSlicePacketForAgent(
                directoryPath: request.values["directory"],
                basename: request.values["basename"]
            )
        case "publish_upload_packet_bundle_generate":
            generatePublishUploadPacketBundleForAgent(
                directoryPath: request.values["directory"],
                basename: request.values["basename"]
            )
        case "publication_cockpit_generate":
            generatePublicationCockpitForAgent(
                directoryPath: request.values["directory"],
                basename: request.values["basename"]
            )
        case "production_command_center":
            let mode = (request.values["mode"] ?? "fast").lowercased()
            let shouldOpen = ["1", "true", "yes", "open"].contains((request.values["open"] ?? "").lowercased())
            generateProductionCommandCenter(reuseExisting: mode != "live", openAfter: shouldOpen)
        case "production_command_center_open":
