    private func handleLegacyAgentCommand() {
        if agentServer.commandToExecute == "import_file", let path = agentServer.importFilePath {
            let url = URL(fileURLWithPath: path)
            loadVideoIntoProject(url: url, allowProtectedOriginalProbe: true)
        } else if agentServer.commandToExecute == "edit", let laneId = agentServer.editLaneId, let action = agentServer.editAction {
            applyAgentEdit(laneId: laneId, action: action, value1: agentServer.editValue1, value2: agentServer.editValue2)
        } else if agentServer.commandToExecute == "decision", let decision = agentServer.requestedDecision {
            applyAgentDecision(decision, start: agentServer.editValue1, duration: agentServer.editValue2)
        } else if agentServer.commandToExecute == "playback" {
            applyAgentPlayback(mode: agentServer.requestedPlaybackMode, action: agentServer.requestedPlaybackAction)
        } else if agentServer.commandToExecute == "lane_role", let laneId = agentServer.requestedLaneRoleId, let role = agentServer.requestedLaneRole {
            assignLaneRole(laneId: laneId, role: role)
        } else if agentServer.commandToExecute == "save_session", let name = agentServer.requestedSessionName {
            saveNativeSession(named: name)
        } else if agentServer.commandToExecute == "load_session", let name = agentServer.requestedSessionName {
            loadNativeSession(named: name)
        } else if agentServer.commandToExecute == "vault_lane", let laneId = agentServer.requestedVaultLaneId {
            vaultLaneMedia(laneId: laneId)
        } else if agentServer.commandToExecute == "relink_lane",
                  let laneId = agentServer.requestedRelinkLaneId,
                  let path = agentServer.requestedRelinkFilePath {
            relinkLaneMedia(laneId: laneId, sourceURL: URL(fileURLWithPath: path))
        } else if agentServer.commandToExecute == "load_demo" {
            loadDemoEdit()
        } else if agentServer.commandToExecute == "load_premiere_packet", let path = agentServer.premierePacketPath {
            loadPremierePacket(url: URL(fileURLWithPath: path))
        } else if agentServer.commandToExecute == "get_state" {
            updateAgentState()
        }

        agentServer.commandToExecute = ""
        updateAgentState()
    }

    private func sourceSyncProofPayload(for sequence: MediaSequence?) -> [String: Any] {
        let toleranceSeconds = 0.75
        let playhead = playbackEngine.playhead
        func jsonNumberOrNull(_ value: Double?) -> Any {
            value.map { $0 as Any } ?? NSNull()
        }

        guard let sequence else {
            return [
                "status": "no_sequence",
                "sourceSyncPassing": false,
                "sourceSyncToleranceSeconds": toleranceSeconds,
                "playhead": playhead,
                "boundedPlayhead": playhead,
                "sequenceDuration": playbackEngine.sequenceDuration,
                "sourceMonitorVideoCount": 0,
                "playableSourceMonitorCount": 0,
                "sourcePlayerCount": playbackEngine.sourcePlayers.count,
                "maxSourcePlayerDeltaSeconds": NSNull(),
                "samples": [],
                "contract": "One sequence playhead drives Program Output, source monitors, timeline, and agent state."
            ]
        }

        let sourceMonitorLanes = sequence.lanes.filter { !isSupportOnlyLane($0) }
        let samples: [[String: Any]] = sourceMonitorLanes.map { lane in
            let actual = playbackEngine.sourcePlayerTime(laneId: lane.id)
            let expected = playbackEngine.expectedSourcePlayerTime(laneId: lane.id, sequenceTime: playhead)
            let delta = (actual != nil && expected != nil) ? abs(actual! - expected!) : nil
            let passing = delta.map { $0 <= toleranceSeconds } ?? false
            return [
                "laneId": lane.id.uuidString,
                "laneName": lane.name,
                "sourceOffset": lane.sourceVideo?.offset ?? 0,
                "sourceDuration": lane.sourceVideo?.duration ?? lane.duration,
                "sourceMonitorPlayerReady": playbackEngine.sourcePlayers[lane.id] != nil,
                "expectedSourcePlayerTimeSeconds": jsonNumberOrNull(expected),
                "actualSourcePlayerTimeSeconds": jsonNumberOrNull(actual),
                "sourcePlayerDeltaSeconds": jsonNumberOrNull(delta),
                "sourceSyncPassing": passing
            ]
        }

        let playableSamples = samples.filter { $0["sourceMonitorPlayerReady"] as? Bool == true }
        let deltas = playableSamples.compactMap { $0["sourcePlayerDeltaSeconds"] as? Double }
        let maxDelta = deltas.max()
        let passing = !playableSamples.isEmpty
            && playableSamples.count == deltas.count
            && (maxDelta ?? .infinity) <= toleranceSeconds

        return [
            "status": passing ? "synced" : "needs_sync_attention",
            "sourceSyncPassing": passing,
            "sourceSyncToleranceSeconds": toleranceSeconds,
            "playhead": playhead,
            "boundedPlayhead": playhead,
            "sequenceDuration": sequence.duration,
            "sourceMonitorVideoCount": sourceMonitorLanes.count,
            "playableSourceMonitorCount": playableSamples.count,
            "sourcePlayerCount": playbackEngine.sourcePlayers.count,
            "maxSourcePlayerDeltaSeconds": jsonNumberOrNull(maxDelta),
            "samples": samples,
            "contract": "One sequence playhead drives Program Output, source monitors, timeline, and agent state over whole proxy-backed source lanes."
        ]
    }

    private func sharedPlayheadContractPayload(for sequence: MediaSequence?) -> [String: Any] {
        let proof = sourceSyncProofPayload(for: sequence)
        let sequenceDuration = sequence?.duration ?? 0.0
        let sourceMonitorVideoCount = proof["sourceMonitorVideoCount"] ?? 0
        let playableSourceMonitorCount = proof["playableSourceMonitorCount"] ?? 0
        let maxSourcePlayerDeltaSeconds = proof["maxSourcePlayerDeltaSeconds"] ?? NSNull()
        let sourceSyncPassing = proof["sourceSyncPassing"] ?? false
        let status = proof["status"] ?? (sequence == nil ? "no_sequence" : "unknown")

        return [
            "status": status,
            "passing": sourceSyncPassing,
            "playhead": playbackEngine.playhead,
            "sequenceDuration": sequenceDuration,
            "sourceMonitorVideoCount": sourceMonitorVideoCount,
            "playableSourceMonitorCount": playableSourceMonitorCount,
            "maxSourcePlayerDeltaSeconds": maxSourcePlayerDeltaSeconds,
            "timelinePixelsPerSecond": timelinePixelsPerSecond,
            "timelineFitToWindow": isTimelineFitToWindow,
            "programMonitorHitbox": programMonitorHitboxPayload(),
            "timelineHitbox": timelineHitboxPayload(),
            "programScrollModel": "two_finger_scroll_over_program_output_scrubs_shared_spine",
            "timelineGestureModel": "drag_red_thread_scrubs_shared_spine_pinch_timeline_zooms_precision",
            "humanProof": [
                "Drag the red timeline thread and confirm Program Output plus Source Grove move together.",
                "Two-finger scroll over Program Output and confirm the same playhead moves.",
                "Pinch the Episode Spine and confirm timelinePixelsPerSecond changes without changing playhead truth."
            ],
            "agentProof": [
                "GET /scrub?time=<seconds>",
                "GET /program_scroll?delta=<seconds>",
                "GET /timeline_zoom?mode=precision|frame|fit|set&scale=<pixels-per-second>",
                "GET /state and inspect sharedPlayheadContract plus sourceSyncProof.samples"
            ],
            "contract": "One sequence playhead drives Program Output, Source Grove, Episode Spine, keyboard shortcuts, program scrolling, and Codex semantic commands."
        ]
    }

    private func programMonitorHitboxPayload() -> [String: Any] {
        guard programMonitorWindowFrame.isNull == false,
              programMonitorWindowFrame.width > 0,
              programMonitorWindowFrame.height > 0
        else {
            return [
                "status": "unpublished",
                "coordinateSpace": "window-local-appkit-bottom-left",
                "available": false,
                "reason": "Program Output view has not published a usable hitbox yet. Focus monitors or wait for the view to lay out, then re-read /state."
            ]
        }

        let centerX = programMonitorWindowFrame.midX
        let centerY = programMonitorWindowFrame.midY
        return [
            "status": "ready",
            "coordinateSpace": "window-local-appkit-bottom-left",
            "available": true,
            "x": programMonitorWindowFrame.minX,
            "y": programMonitorWindowFrame.minY,
            "width": programMonitorWindowFrame.width,
            "height": programMonitorWindowFrame.height,
            "centerX": centerX,
            "centerY": centerY,
            "agentPhysicalProof": [
                "Use System Events to get the app window top-left position and size.",
                "Convert centerY from AppKit bottom-left window coordinates to global screen coordinates with globalY = windowTopY + windowHeight - centerY.",
                "Send a CGEvent scroll at the converted center point, then re-read /state and confirm playhead changed and sharedPlayheadContract.passing stayed true."
            ],
            "semanticFallback": "GET /program_scroll?delta=<seconds>"
        ]
    }

    private func timelineHitboxPayload() -> [String: Any] {
        guard timelineWindowFrame.isNull == false,
              timelineWindowFrame.width > 0,
              timelineWindowFrame.height > 0
        else {
            return [
                "status": "unpublished",
                "coordinateSpace": "window-local-appkit-bottom-left",
                "available": false,
                "reason": "Episode Spine timeline has not published a usable hitbox yet. Scroll/focus the timeline into view, then re-read /state."
            ]
        }

        let sidebarWidth = 220.0
        let rulerTopInset = 12.0
        let safeStartX = min(max(timelineWindowFrame.minX + sidebarWidth + 120, timelineWindowFrame.minX + 24), timelineWindowFrame.maxX - 180)
        let safeEndX = min(max(safeStartX + 260, safeStartX + 60), timelineWindowFrame.maxX - 60)
        let rulerY = min(max(timelineWindowFrame.maxY - rulerTopInset, timelineWindowFrame.minY + 18), timelineWindowFrame.maxY - 8)
        let centerX = timelineWindowFrame.midX
        let centerY = timelineWindowFrame.midY

        return [
            "status": "ready",
            "coordinateSpace": "window-local-appkit-bottom-left",
            "available": true,
            "x": timelineWindowFrame.minX,
            "y": timelineWindowFrame.minY,
            "width": timelineWindowFrame.width,
            "height": timelineWindowFrame.height,
            "centerX": centerX,
            "centerY": centerY,
            "trackSidebarWidth": sidebarWidth,
            "recommendedRulerDragStartX": safeStartX,
            "recommendedRulerDragEndX": safeEndX,
            "recommendedRulerDragY": rulerY,
            "recommendedScrubSurface": "quipsly.timeline.rulerScrubSurface",
            "agentPhysicalProof": [
                "Use System Events to get the app window top-left position and size.",
                "Use recommendedRulerDragStartX/recommendedRulerDragEndX/recommendedRulerDragY to drag across the Episode Spine ruler scrub surface.",
                "Convert AppKit bottom-left window coordinates to global screen coordinates with globalY = windowTopY + windowHeight - localY.",
                "After the drag, re-read /state and confirm playhead changed and sharedPlayheadContract.passing stayed true."
            ],
            "semanticFallback": "GET /scrub?time=<seconds> and GET /timeline_zoom?mode=<fit|precision|frame|set>"
        ]
    }

    private func updateAgentState() {
        guard let sequence = projectStore.activeSequence else {
            agentServer.writeStatus([
                "projectTitle": projectStore.project.title,
                "sequenceTitle": "",
                "sequenceDuration": 0,
                "mediaBinCount": projectStore.project.mediaBin.count,
                "laneCount": 0,
                "lanes": [],
                "monitorWallModel": "program_output_plus_whole_source_lanes",
                "monitorWallLayout": "program_star_with_horizontal_source_wall",
                "sourceMonitorLayout": "horizontal_whole_lane_cards",
                "monitorFocusBehavior": "focus_monitors_scrolls_to_program_and_source_wall",
                "agentAccessibilityModel": "semantic_commands_with_state_echo",
                "agentInterfaceModel": "observe_state_choose_semantic_action_execute_reobserve",
                "agentCommandSerial": agentServer.commandSerial,
                "agentLastProcessedCommandSerial": lastDrainedAgentCommandSerial,
                "agentOperatingProtocol": agentOperatingProtocolPayload(),
                "agentTrainingDataContract": agentTrainingDataContractPayload(),
                "editorControlPlane": editorControlPlanePayload(sequenceLoaded: false, readinessSummary: nil),
