    private func editTargetRecommendationPayload(for sequence: MediaSequence?, summary: MediaReadinessSummary?) -> [String: Any] {
        let truth = workingSetTruthPayload(for: sequence, summary: summary)
        let status = truth["status"] as? String ?? "unknown"
        let currentSession = sequence == nil ? "" : normalizedActiveSessionName()
        let title = sequence?.title ?? ""
        let charlieReady = truth["charlieReadyCount"] as? Int ?? 0
        let homerReady = truth["homerReadyCount"] as? Int ?? 0
        let mysteryCount = truth["mysteryLaneCount"] as? Int ?? 0
        let hasShortQueue = (sequence?.shortClipQueue.isEmpty == false)

        let recommendedPath: String
        let primaryAction: String
        let rationale: String
        let safeCommands: [String]
        let avoid: [String]

        if sequence == nil {
            recommendedPath = "load-known-two-camera-proof-lane"
            primaryAction = "Load Episode 1 before making edit claims."
            rationale = "No native editor session is loaded, so neither humans nor Codex have an authoritative episode spine to edit."
            safeCommands = [
                "script/agentctl.sh load-session episode-1-premiere-rescue",
                "script/agentctl.sh codex-observe"
            ]
            avoid = [
                "Do not claim editor readiness from an empty state.",
                "Do not create synthetic success media."
            ]
        } else if status == "usable-charlie-homer-working-set" || status == "usable-generic-two-camera-working-set" {
            recommendedPath = "continue-current-episode-edit"
            primaryAction = "Keep cutting this episode and review/export shorts from the same spine."
            rationale = "The current session has enough proxy-backed camera truth for real edit decisions. Missing parked sources should stay recovery-only unless the picture visibly needs them."
            safeCommands = [
                "script/agentctl.sh codex-observe",
                "script/agentctl.sh focus-timeline",
                "script/agentctl.sh shorts-review-next"
            ]
            avoid = [
                "Do not relitigate parked recovery lanes while the visible edit has enough usable camera truth.",
                "Do not convert whole sources into chopped timeline clips."
            ]
        } else if status == "single-camera-working-set" {
            recommendedPath = hasShortQueue ? "review-shorts-here-or-switch-for-two-camera" : "attach-second-camera-or-switch-proof-lane"
            primaryAction = hasShortQueue
                ? "Use this session for transcript/short review, or switch to Episode 1 for true two-camera editing."
                : "Attach/proxy the missing long host camera, or switch to Episode 1 for true two-camera proof work."
            rationale = "This session has \(charlieReady) Charlie-ready and \(homerReady) Homer-ready primary camera lane(s), with \(mysteryCount) mystery/recovery lane(s). That is honest single-camera work, not a two-camera edit target."
            safeCommands = [
                "script/agentctl.sh shorts-review-next",
                "script/agentctl.sh left-workbench shorts",
                "script/agentctl.sh load-session episode-1-premiere-rescue"
            ]
            avoid = [
                "Do not spend long on short missing placeholders if the usable camera path is sufficient for review work.",
                "Do not call this session two-camera edit-ready until the real second long host camera is proxy-ready."
            ]
        } else if status == "no-usable-video-working-set" {
            recommendedPath = "recover-media-before-editing"
            primaryAction = "Import, relink, or proxy a primary camera source before editing."
            rationale = "No usable visual working set is available. Editing here would train both humans and Codex to tolerate broken media truth."
            safeCommands = [
                "script/agentctl.sh recovery-report",
                "script/agentctl.sh match-folder /absolute/folder/with/episode-media",
                "script/agentctl.sh load-session episode-1-premiere-rescue"
            ]
            avoid = [
                "Do not make publication or edit-quality claims from missing media.",
                "Do not chase every orphan before restoring at least one primary source."
            ]
        } else {
            recommendedPath = "observe-before-acting"
            primaryAction = "Re-observe state, then choose between editing, short review, or media recovery."
            rationale = "The current working-set status is \(status). Codex should gather one fresh state packet before acting."
            safeCommands = [
                "script/agentctl.sh codex-observe",
                "script/agentctl.sh recovery-report"
            ]
            avoid = [
                "Do not infer readiness from pixels alone."
            ]
        }

        return [
            "model": "quipsly-editor-target-recommendation",
            "version": "2026-06-19.edit-target-recommendation.v1",
            "currentSessionName": currentSession,
            "sequenceTitle": title,
            "workingSetStatus": status,
            "recommendedPath": recommendedPath,
            "primaryAction": primaryAction,
            "rationale": rationale,
            "safeCommands": safeCommands,
            "avoid": avoid,
            "knownTwoCameraProofSession": "episode-1-premiere-rescue",
            "truthContract": "This recommendation routes attention. It never mutates media, decisions, sessions, or publication state."
        ]
    }

    private func workingSetTruthPayload(for sequence: MediaSequence?, summary: MediaReadinessSummary?) -> [String: Any] {
        guard let sequence else {
            return [
                "model": "quipsly-editor-working-set-truth",
                "version": "2026-06-19.working-set-truth.v1",
                "status": "no-sequence",
                "sufficientForEditingNow": false,
                "summary": "Load an episode before deciding which camera lanes matter.",
                "policy": "Do not chase missing media until an episode session proves the usable source set is insufficient."
            ]
        }

        let videoLanes = sequence.lanes.filter { lane in
            !isSupportOnlyLane(lane) && lane.sourceVideo != nil
        }
        let readyVideoLanes = videoLanes.filter { lane in
            sourceReadiness(for: lane).isReady && lane.metadata?.ignoreForProduction != true
        }
        let primaryCameraLanes = videoLanes.filter { workingSetLaneIsPrimaryCamera($0, in: sequence) }
        let shortOrPlaceholderCameraLanes = videoLanes.filter { lane in
            workingSetLaneLooksLikeCamera(lane) && !workingSetLaneIsPrimaryCamera(lane, in: sequence)
        }
        let readyPrimaryCameraLanes = primaryCameraLanes.filter { lane in
            sourceReadiness(for: lane).isReady && lane.metadata?.ignoreForProduction != true
        }
        let missingPrimaryCameraLanes = primaryCameraLanes.filter { lane in
            lane.metadata?.ignoreForProduction != true && !sourceReadiness(for: lane).isReady
        }
        let charlieLanes = readyPrimaryCameraLanes.filter { workingSetLaneMatches($0, tokens: ["charlie"]) }
        let homerLanes = readyPrimaryCameraLanes.filter { workingSetLaneMatches($0, tokens: ["homer"]) }
        let mysteryLanes = videoLanes.filter { workingSetLaneLooksMystery($0) }
        let heldMysteryLanes = mysteryLanes.filter { $0.metadata?.ignoreForProduction == true }
        let unresolvedActiveMysteryLanes = mysteryLanes.filter { $0.metadata?.ignoreForProduction != true && !sourceReadiness(for: $0).isReady }
        let sufficientNamedPair = !charlieLanes.isEmpty && !homerLanes.isEmpty
        let sufficientGenericPair = readyPrimaryCameraLanes.count >= 2
        let sufficientForEditingNow = sufficientNamedPair || sufficientGenericPair

        let status: String
        let summaryText: String
        let nextAction: String
        if sufficientNamedPair {
            status = "usable-charlie-homer-working-set"
            summaryText = "Charlie and Homer proxy lanes are usable. Other unresolved placeholders are optional recovery, not a reason to stall the edit."
            nextAction = "Keep editing from the usable named camera pair. Only investigate mystery lanes if the picture visibly needs a missing source."
        } else if sufficientGenericPair {
            status = "usable-generic-two-camera-working-set"
            summaryText = "\(readyPrimaryCameraLanes.count) primary camera proxy lane(s) are usable. The named Charlie/Homer mapping still deserves review, but editing can continue."
            nextAction = "Cut with the usable proxy lanes and tag roles when the source monitor proves who is who."
        } else if readyPrimaryCameraLanes.count == 1 {
            status = "single-camera-working-set"
            if missingPrimaryCameraLanes.isEmpty {
                summaryText = "One long primary camera proxy lane is usable. Reference clips may be ready too; short placeholder camera fragments are parked as recovery notes, not full host cameras."
                nextAction = "Use the ready camera for transcript/short review. Attach or proxy a second long host camera lane before calling the episode two-camera edit-ready."
            } else {
                summaryText = "One primary camera proxy lane is usable and \(missingPrimaryCameraLanes.count) plausible primary camera lane(s) still need media."
                nextAction = "Use the ready camera for transcript/short review; relink or proxy the missing primary host camera before calling the episode edit-ready."
            }
        } else {
            status = "no-usable-video-working-set"
            summaryText = summary?.videoRoughCutDetail ?? "No usable proxy video lane is available yet."
            nextAction = "Import, relink, or proxy the primary source media before editing."
        }

        return [
            "model": "quipsly-editor-working-set-truth",
            "version": "2026-06-19.working-set-truth.v1",
            "status": status,
            "sufficientForEditingNow": sufficientForEditingNow,
            "summary": summaryText,
            "nextAction": nextAction,
            "policy": "If Charlie and Homer are usable, do not spend time solving unrelated placeholder mysteries. Preserve them visibly for later recovery.",
            "usableProxyLaneCount": readyVideoLanes.count,
            "primaryCameraProxyReadyCount": readyPrimaryCameraLanes.count,
            "charlieReadyCount": charlieLanes.count,
            "homerReadyCount": homerLanes.count,
            "mysteryLaneCount": mysteryLanes.count,
            "heldMysteryLaneCount": heldMysteryLanes.count,
            "unresolvedActiveMysteryLaneCount": unresolvedActiveMysteryLanes.count,
            "shortOrPlaceholderCameraLaneCount": shortOrPlaceholderCameraLanes.count,
            "missingPrimaryCameraLaneCount": missingPrimaryCameraLanes.count,
            "primaryCameraMinimumDurationSeconds": workingSetPrimaryCameraMinimumDuration(for: sequence),
            "primaryCameraLanes": primaryCameraLanes.map { workingSetLanePayload($0) },
            "shortOrPlaceholderCameraLanes": shortOrPlaceholderCameraLanes.map { workingSetLanePayload($0) },
            "usableLanes": readyVideoLanes.map { workingSetLanePayload($0) },
            "mysteryLanes": mysteryLanes.map { workingSetLanePayload($0) },
            "editorInstruction": "Proceed with real edit and short review once the usable working set is enough. Treat placeholder recovery as a separate task, not the main path."
        ]
    }

    private func workingSetLanePayload(_ lane: VideoLane) -> [String: Any] {
        let readiness = sourceReadiness(for: lane)
        return [
            "id": lane.id.uuidString,
            "name": lane.name,
            "role": lane.metadata?.role ?? "",
            "sourceLabel": lane.metadata?.sourceLabel ?? "",
            "readiness": readiness.label,
            "readinessDetail": readiness.detail,
            "ready": readiness.isReady,
            "ignoredForProduction": lane.metadata?.ignoreForProduction == true,
            "proxyPath": lane.sourceVideo?.proxyURL?.path ?? "",
            "originalPath": lane.metadata?.originalPath ?? lane.sourceVideo?.mediaURL.path ?? ""
        ]
    }

    private func workingSetLaneMatches(_ lane: VideoLane, tokens: [String]) -> Bool {
        let haystack = workingSetLaneSearchText(lane)
        return tokens.contains { haystack.contains($0.lowercased()) }
    }

    private func workingSetLaneLooksMystery(_ lane: VideoLane) -> Bool {
        let haystack = workingSetLaneSearchText(lane)
        return haystack.contains("unresolved")
            || haystack.contains("__quipsly_missing_media__")
            || haystack.contains("missing media")
            || haystack.contains("placeholder")
    }

    private func workingSetLaneIsPrimaryCamera(_ lane: VideoLane, in sequence: MediaSequence) -> Bool {
        guard workingSetLaneLooksLikeCamera(lane) else { return false }
        let duration = lane.sourceVideo?.duration ?? lane.duration
        let minimumDuration = workingSetPrimaryCameraMinimumDuration(for: sequence)
        return duration >= minimumDuration
    }

    private func workingSetLaneLooksLikeCamera(_ lane: VideoLane) -> Bool {
        let haystack = workingSetLaneSearchText(lane)
        if haystack.contains("source_clip") || haystack.contains("reference_clip") || haystack.contains("title sequence") {
            return false
        }
        return haystack.contains("camera")
            || haystack.contains("charlie")
            || haystack.contains("homer")
    }

    private func workingSetPrimaryCameraMinimumDuration(for sequence: MediaSequence) -> Double {
        guard sequence.duration > 0 else { return 30 }
        return max(30, min(600, sequence.duration * 0.05))
    }

    private func workingSetLaneSearchText(_ lane: VideoLane) -> String {
        [
            lane.name,
            lane.metadata?.role ?? "",
            lane.metadata?.sourceLabel ?? "",
            lane.metadata?.originalPath ?? "",
            lane.sourceVideo?.mediaURL.path ?? "",
            lane.sourceVideo?.proxyURL?.path ?? ""
        ]
            .joined(separator: " ")
            .lowercased()
    }

    private func editCorrectionNotesPayload(for sequence: MediaSequence) -> [[String: Any]] {
        sequence.editCorrectionNotes
            .sorted { $0.createdAt > $1.createdAt }
            .prefix(16)
            .map { editCorrectionNotePayload($0) }
    }

