    private func saveNativeSession(named name: String) {
        let sessionName = normalizedSessionName(name)
        guard validateSessionSaveTarget(sessionName, isAutosave: false) else { return }

        Task {
            do {
                let url = try await projectStore.saveNativeSession(named: sessionName)
                await MainActor.run {
                    activeSessionName = sessionName
                    lastSessionPath = url.path
                    lastSavedAt = Date()
                    autosaveStatus = "Saved"
                    lastMediaAction = "Saved native session \(sessionName)"
                    errorMessage = nil
                    showErrorAlert = false
                    refreshRecentSessions()
                    updateAgentState()
                }
            } catch {
                await MainActor.run {
                    lastMediaAction = "Save session failed: \(error.localizedDescription)"
                    errorMessage = lastMediaAction
                    showErrorAlert = true
                    updateAgentState()
                }
            }
        }
    }

    private func loadNativeSession(named name: String) {
        let sessionName = normalizedSessionName(name)
        autosaveTask?.cancel()
        autosaveTask = nil
        resetExportStatusForSessionSwitch()
        autosaveStatus = "Loading"
        lastMediaAction = "Loading native session \(sessionName)"
        updateAgentState()

        Task {
            do {
                let loaded = try await projectStore.readNativeSession(named: sessionName)
                await MainActor.run {
                    projectStore.applyNativeSession(loaded.session)
                    selectedLaneId = nil
                    selectedTagId = nil
                    proxyFailureByLaneId.removeAll()
                    audioProxyValidationByPath.removeAll()
                    audioProxyValidationInFlight.removeAll()
                    videoProxyValidationInFlight.removeAll()
                    activeSessionName = sessionName
                    lastSessionPath = loaded.url.path
                    lastSavedAt = nil
                    autosaveStatus = "Loaded"
                    lastMediaAction = "Loaded native session \(sessionName)"
                    errorMessage = nil
                    showErrorAlert = false
                    refreshRecentSessions()
                    if let sequence = projectStore.activeSequence {
                        playbackEngine.updateSourcePlayers(for: sequence)
                        playbackEngine.updateValidRanges(for: sequence)
                    }
                    if !mediaReadinessSummary().isProductionReady {
                        isShowingProductionDetails = true
                    }
                    rebuildPlayer()
                    updateAgentState()
                }
            } catch {
                await MainActor.run {
                    lastMediaAction = "Load session failed: \(error.localizedDescription)"
                    errorMessage = lastMediaAction
                    showErrorAlert = true
                    updateAgentState()
                }
            }
        }
    }

    private func vaultLaneMedia(laneId: String) {
        guard let sequence = projectStore.activeSequence,
              let lane = sequence.lanes.first(where: { laneMatches($0, laneId: laneId) }),
              let source = lane.sourceVideo else {
            lastMediaAction = "Vault lane failed: lane or source not found"
            updateAgentState()
            return
        }

        let originalURL = source.mediaURL
        let originalPath = lane.metadata?.originalPath ?? originalURL.path

        Task {
            do {
                let isAudio = isAudioPath(originalURL.path)
                let fingerprint = LocalMediaVault.shared.assetFingerprint(for: originalURL)
                let proxyDestination = try LocalMediaVault.shared.proxyURL(for: originalURL)
                if isExternalOriginalPath(originalURL.path),
                   !externalMediaAccess.hasExplicitFolderGrant,
                   !FileManager.default.fileExists(atPath: proxyDestination.path) {
                    await MainActor.run {
                        proxyFailureByLaneId[lane.id] = "Grant external storage access before creating the local proxy for \(originalURL.lastPathComponent)."
                        lastMediaAction = "Proxy blocked for \(lane.name): external storage access is not active"
                        updateAgentState()
                    }
                    return
                }
                let proxyURL = try await ProxyEngine.shared.generateProxy(for: originalURL)

                await MainActor.run {
                    guard var updatedSequence = projectStore.activeSequence,
                          let laneIndex = updatedSequence.lanes.firstIndex(where: { $0.id == lane.id }),
                          var updatedSource = updatedSequence.lanes[laneIndex].sourceVideo else {
                        return
                    }

                    updatedSource.mediaURL = originalURL
                    updatedSource.proxyURL = proxyURL
                    updatedSequence.lanes[laneIndex].sourceVideo = updatedSource

                    var metadata = updatedSequence.lanes[laneIndex].metadata ?? VideoLaneMetadata(
                        mediaKind: isAudio ? "audio" : "video",
                        role: isAudio ? "audio" : "camera"
                    )
                    metadata.originalPath = originalPath
                    metadata.sourcePath = originalURL.path
                    metadata.vaultRawPath = nil
                    metadata.vaultProxyPath = proxyURL.path
                    metadata.assetFingerprint = fingerprint
                    metadata.declaredExists = true
                    if metadata.sourceLabel == nil {
                        metadata.sourceLabel = originalURL.lastPathComponent
                    }
                    updatedSequence.lanes[laneIndex].metadata = metadata
                    proxyFailureByLaneId[lane.id] = nil

                    projectStore.updateSequence(updatedSequence, undoManager: nil, actionName: "Vault Lane Media")
                    playbackEngine.updateSourcePlayers(for: updatedSequence)
                    playbackEngine.updateValidRanges(for: updatedSequence)
                    lastMediaAction = isAudio
                        ? "Cached audio proxy for \(updatedSequence.lanes[laneIndex].name) without copying raw audio"
                        : "Cached proxy for \(updatedSequence.lanes[laneIndex].name) without copying raw video"
                    rebuildPlayer()
                    scheduleAutosave(reason: isAudio ? "cached audio proxy" : "cached proxy")
                    updateAgentState()
                }
            } catch {
                await MainActor.run {
                    proxyFailureByLaneId[lane.id] = error.localizedDescription
                    lastMediaAction = "Vault lane failed: \(error.localizedDescription)"
                    errorMessage = lastMediaAction
                    showErrorAlert = true
                    updateAgentState()
                }
            }
        }
    }

    private func relinkLaneMedia(laneId: String, sourceURL: URL, queueProxy: Bool = true) {
        guard let sequence = projectStore.activeSequence,
              let lane = sequence.lanes.first(where: { laneMatches($0, laneId: laneId) }) else {
            lastMediaAction = "Relink failed: lane not found"
            updateAgentState()
            return
        }

        let canProbeSource = shouldProbeOriginalPath(sourceURL.path)
        let sourceExists = canProbeSource
            ? (externalMediaAccess.fileExistsWithoutPrompt(at: sourceURL) ?? false)
            : isExternalOriginalPath(sourceURL.path)
        guard sourceExists else {
            lastMediaAction = "Relink failed: source not found at \(sourceURL.path)"
            autosaveStatus = "Relink failed"
            updateAgentState()
            return
        }

        let isAudio = isAudioPath(sourceURL.path)
        let plannedProxyURL = try? LocalMediaVault.shared.proxyURL(for: sourceURL)
        lastMediaAction = isAudio
            ? "Relinking audio lane \(lane.name) to full source and preparing audio proxy"
            : "Relinking video lane \(lane.name) to full source and preparing proxy"
        autosaveStatus = "Relinking media"

        guard var updatedSequence = projectStore.activeSequence,
              let laneIndex = updatedSequence.lanes.firstIndex(where: { $0.id == lane.id }) else {
            lastMediaAction = "Relink failed: lane disappeared before update"
            autosaveStatus = "Relink failed"
            updateAgentState()
            return
        }

        let previousSource = updatedSequence.lanes[laneIndex].sourceVideo
        let relinkedSource = SourceVideo(
            id: previousSource?.id ?? UUID(),
            mediaURL: sourceURL,
            proxyURL: plannedProxyURL,
            duration: previousSource?.duration ?? 60,
            offset: previousSource?.offset ?? 0,
            is360: previousSource?.is360 == true || sourceURL.pathExtension.lowercased() == "insv"
        )
        updatedSequence.lanes[laneIndex].sourceVideo = relinkedSource

        var metadata = updatedSequence.lanes[laneIndex].metadata ?? VideoLaneMetadata(
            mediaKind: isAudio ? "audio" : "video",
            role: isAudio ? "audio" : "camera"
        )
        if metadata.originalPath == nil || metadata.originalPath?.isEmpty == true {
            metadata.originalPath = sourceURL.path
        }
        metadata.sourcePath = sourceURL.path
        metadata.vaultRawPath = nil
        metadata.vaultProxyPath = plannedProxyURL?.path
        metadata.assetFingerprint = nil
        metadata.declaredExists = true
        metadata.sourceLabel = sourceURL.lastPathComponent
        metadata.mediaKind = isAudio ? "audio" : "video"
        if metadata.role == "unknown" {
            metadata.role = isAudio ? "audio" : "camera"
        }
        updatedSequence.lanes[laneIndex].metadata = metadata
        proxyFailureByLaneId[lane.id] = nil

        selectedLaneId = updatedSequence.lanes[laneIndex].id
        selectedTagId = nil
        projectStore.updateSequence(updatedSequence, undoManager: nil, actionName: "Relink Lane Media")
        playbackEngine.updateSourcePlayers(for: updatedSequence)
        playbackEngine.updateValidRanges(for: updatedSequence)
        lastMediaAction = isAudio
            ? "Relinked \(updatedSequence.lanes[laneIndex].name) to full external audio; audio proxy queued"
            : "Relinked \(updatedSequence.lanes[laneIndex].name) to full external source; proxy queued"
        rebuildPlayer()
        scheduleAutosave(reason: "relinked media")
        updateAgentState()

        guard queueProxy else { return }
        if let plannedProxyURL, externalMediaAccess.fileExistsWithoutPrompt(at: plannedProxyURL) == true {
            proxyFailureByLaneId[lane.id] = nil
            lastMediaAction = isAudio
                ? "Audio proxy already ready for \(updatedSequence.lanes[laneIndex].name)"
                : "Proxy already ready for \(updatedSequence.lanes[laneIndex].name)"
            updateAgentState()
            return
        }

        if isExternalOriginalPath(sourceURL.path) && !externalMediaAccess.hasExplicitFolderGrant {
            proxyFailureByLaneId[lane.id] = "Grant external storage access before creating the local proxy for \(sourceURL.lastPathComponent)."
            lastMediaAction = isAudio
                ? "Audio proxy blocked for \(updatedSequence.lanes[laneIndex].name): external storage access is not active"
                : "Proxy blocked for \(updatedSequence.lanes[laneIndex].name): external storage access is not active"
            updateAgentState()
            return
        }

        let relinkedLaneId = lane.id
        let relinkedLaneName = lane.name
        Task(priority: .utility) { [sourceURL, relinkedLaneId, relinkedLaneName] in
            do {
                await MainActor.run {
                    lastMediaAction = isAudioPath(sourceURL.path)
                        ? "Audio proxy job preparing for \(relinkedLaneName)"
                        : "Proxy job preparing for \(relinkedLaneName)"
                    updateAgentState()
                }
                let fingerprint = LocalMediaVault.shared.assetFingerprint(for: sourceURL)
                let proxyDestination = try LocalMediaVault.shared.proxyURL(for: sourceURL)
                let existingProxyURL = FileManager.default.fileExists(atPath: proxyDestination.path) ? proxyDestination : nil
                let generatedProxyURL: URL
                if let existingProxyURL {
                    generatedProxyURL = existingProxyURL
                } else {
                    await MainActor.run {
                        lastMediaAction = isAudioPath(sourceURL.path)
                            ? "Generating audio proxy for \(relinkedLaneName)"
                            : "Generating proxy for \(relinkedLaneName)"
                        updateAgentState()
                    }
                    generatedProxyURL = try await ProxyEngine.shared.generateProxy(for: sourceURL)
                }
                await MainActor.run {
                    guard var updatedSequence = projectStore.activeSequence,
                          let laneIndex = updatedSequence.lanes.firstIndex(where: { $0.id == relinkedLaneId }),
                          var updatedSource = updatedSequence.lanes[laneIndex].sourceVideo else {
                        return
                    }

                    guard updatedSource.mediaURL.path == sourceURL.path else {
                        return
                    }

                    updatedSource.proxyURL = generatedProxyURL
                    updatedSequence.lanes[laneIndex].sourceVideo = updatedSource

                    var metadata = updatedSequence.lanes[laneIndex].metadata ?? VideoLaneMetadata(
                        mediaKind: isAudioPath(sourceURL.path) ? "audio" : "video",
                        role: isAudioPath(sourceURL.path) ? "audio" : "camera"
                    )
                    metadata.assetFingerprint = fingerprint
                    metadata.vaultProxyPath = generatedProxyURL.path
                    updatedSequence.lanes[laneIndex].metadata = metadata
                    proxyFailureByLaneId[relinkedLaneId] = nil

                    projectStore.updateSequence(updatedSequence, undoManager: nil, actionName: "Proxy Ready")
                    playbackEngine.updateSourcePlayers(for: updatedSequence)
                    playbackEngine.updateValidRanges(for: updatedSequence)
                    lastMediaAction = isAudioPath(sourceURL.path)
                        ? "Audio proxy-safe for \(updatedSequence.lanes[laneIndex].name)"
                        : "Proxy ready for \(updatedSequence.lanes[laneIndex].name)"
                    rebuildPlayer()
                    scheduleAutosave(reason: "proxy-safe")
                    updateAgentState()
                }
            } catch {
                await MainActor.run {
                    proxyFailureByLaneId[relinkedLaneId] = error.localizedDescription
                    lastMediaAction = "Relink failed: \(error.localizedDescription)"
                    errorMessage = lastMediaAction
                    showErrorAlert = true
                    updateAgentState()
                }
            }
        }
    }

    private func attachProxyToLane(laneId: String, proxyURL: URL) {
        guard let sequence = projectStore.activeSequence,
              let lane = sequence.lanes.first(where: { laneMatches($0, laneId: laneId) }),
              let source = lane.sourceVideo else {
            lastMediaAction = "Attach proxy failed: lane or source not found"
            updateAgentState()
            return
        }

        guard FileManager.default.fileExists(atPath: proxyURL.path) else {
            lastMediaAction = "Attach proxy failed: proxy not found at \(proxyURL.path)"
            proxyFailureByLaneId[lane.id] = "Proxy file not found at \(proxyURL.path)"
            updateAgentState()
            return
        }

        let originalURL = source.mediaURL
        let expectedProxyURL: URL
        do {
            expectedProxyURL = try LocalMediaVault.shared.proxyURL(for: originalURL)
            let proxyFolder = expectedProxyURL.deletingLastPathComponent()
            if !FileManager.default.fileExists(atPath: proxyFolder.path) {
                try FileManager.default.createDirectory(at: proxyFolder, withIntermediateDirectories: true)
            }

            if proxyURL.standardizedFileURL.path != expectedProxyURL.standardizedFileURL.path {
                try? FileManager.default.removeItem(at: expectedProxyURL)
                try FileManager.default.copyItem(at: proxyURL, to: expectedProxyURL)
            }
        } catch {
            lastMediaAction = "Attach proxy failed: \(error.localizedDescription)"
            proxyFailureByLaneId[lane.id] = error.localizedDescription
            updateAgentState()
            return
        }

        guard var updatedSequence = projectStore.activeSequence,
              let laneIndex = updatedSequence.lanes.firstIndex(where: { $0.id == lane.id }),
              var updatedSource = updatedSequence.lanes[laneIndex].sourceVideo else {
            lastMediaAction = "Attach proxy failed: lane disappeared before update"
            updateAgentState()
            return
        }

        updatedSource.proxyURL = expectedProxyURL
        updatedSequence.lanes[laneIndex].sourceVideo = updatedSource

        var metadata = updatedSequence.lanes[laneIndex].metadata ?? VideoLaneMetadata(
            mediaKind: isAudioPath(originalURL.path) ? "audio" : "video",
            role: isAudioPath(originalURL.path) ? "audio" : "camera"
        )
        metadata.sourcePath = originalURL.path
        metadata.vaultProxyPath = expectedProxyURL.path
        metadata.assetFingerprint = LocalMediaVault.shared.assetFingerprint(for: originalURL)
        metadata.declaredExists = true
        if metadata.sourceLabel == nil {
            metadata.sourceLabel = originalURL.lastPathComponent
        }
        updatedSequence.lanes[laneIndex].metadata = metadata
        proxyFailureByLaneId[lane.id] = nil
        audioProxyValidationByPath.removeValue(forKey: expectedProxyURL.path)
        audioProxyValidationInFlight.remove(expectedProxyURL.path)
        videoProxyValidationInFlight.remove(expectedProxyURL.path)
        selectedLaneId = lane.id
        selectedTagId = nil

        projectStore.updateSequence(updatedSequence, undoManager: nil, actionName: "Attach Proxy")
        playbackEngine.updateSourcePlayers(for: updatedSequence)
        playbackEngine.updateValidRanges(for: updatedSequence)
        rebuildPlayer()
        lastMediaAction = isAudioPath(originalURL.path)
            ? "Attached local audio proxy to \(updatedSequence.lanes[laneIndex].name); original source remains whole"
            : "Attached local video proxy to \(updatedSequence.lanes[laneIndex].name); original source remains whole"
        if !isAudioPath(originalURL.path) {
            validateAttachedVideoProxy(
                laneId: lane.id,
                proxyPath: expectedProxyURL.path,
                expectedDuration: updatedSource.duration,
                laneName: updatedSequence.lanes[laneIndex].name
            )
        }
        scheduleAutosave(reason: "attached proxy")
        updateAgentState()
    }

    private func validateAttachedVideoProxy(laneId: UUID, proxyPath: String, expectedDuration: Double, laneName: String) {
        guard expectedDuration.isFinite, expectedDuration > 10 else { return }
        guard !videoProxyValidationInFlight.contains(proxyPath) else { return }

        videoProxyValidationInFlight.insert(proxyPath)
        Task.detached(priority: .utility) {
            let issue: String
            do {
                let asset = AVURLAsset(url: URL(fileURLWithPath: proxyPath))
                let videoTracks = try await asset.loadTracks(withMediaType: .video)
                if videoTracks.isEmpty {
                    issue = "Attached proxy has no video track. Attach a full-length video proxy for \(laneName)."
                } else {
                    let duration = try await asset.load(.duration)
                    let proxyDuration = CMTimeGetSeconds(duration)
                    if !proxyDuration.isFinite || proxyDuration <= 0 {
                        issue = "Attached proxy duration could not be verified. Attach a readable full-length video proxy for \(laneName)."
                    } else {
                        let tolerance = max(2.0, expectedDuration * 0.01)
                        if proxyDuration + tolerance < expectedDuration {
                            issue = String(
                                format: "Attached proxy is too short for this whole lane: proxy %.1fs vs source %.1fs. Attach or generate a full-length proxy; do not satisfy a whole lane with a clipped file.",
                                proxyDuration,
                                expectedDuration
                            )
                        } else {
                            issue = ""
                        }
                    }
                }
            } catch {
                issue = "Attached proxy could not be verified: \(error.localizedDescription). Attach a readable full-length video proxy for \(laneName)."
            }

            await MainActor.run {
                videoProxyValidationInFlight.remove(proxyPath)
                if issue.isEmpty {
                    proxyFailureByLaneId.removeValue(forKey: laneId)
                    lastMediaAction = "Verified full-length video proxy for \(laneName)"
                } else {
                    proxyFailureByLaneId[laneId] = issue
                    lastMediaAction = "Proxy verification blocked \(laneName): \(issue)"
                    isShowingProductionDetails = true
                }
                updateAgentState()
            }
        }
    }

    private func relinkExpectedMediaFromExternalFolder(rootPathOverride: String? = nil) {
        guard let sequence = projectStore.activeSequence else {
            lastMediaAction = "Match folder failed: no active sequence"
            updateAgentState()
            return
        }

        let rootPath = rootPathOverride?.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty == false
            ? rootPathOverride!.trimmingCharacters(in: .whitespacesAndNewlines)
            : externalMediaAccess.rootPath
        guard !rootPath.isEmpty else {
            #if os(macOS)
            isShowingExternalMediaAccessImporter = true
            #endif
            lastMediaAction = "Choose the external media folder before matching lanes"
            updateAgentState()
            return
        }

        if rootPathOverride == nil {
            _ = externalMediaAccess.restoreAccess()
        }

        let rootURL = URL(fileURLWithPath: rootPath, isDirectory: true)
        isRelinkingExternalFolder = true
        autosaveStatus = "Scanning external folder"
        lastMediaAction = "Matching expected media in \(rootURL.lastPathComponent)"
        updateAgentState()

        let lanes = sequence.lanes
        Task.detached(priority: .utility) {
            let report = EpisodeMediaFolderMatcher.match(rootURL: rootURL, lanes: lanes, maxDepth: 3)

            await MainActor.run {
                isRelinkingExternalFolder = false

                guard !report.matches.isEmpty else {
                    autosaveStatus = "Match found no files"
                    lastMediaAction = "No expected lane files found in \(rootURL.lastPathComponent). Scanned \(report.scannedFileCount) file(s)."
                    updateAgentState()
                    return
                }

                lastMediaAction = "Matched \(report.matches.count) lane(s) from \(rootURL.lastPathComponent); relinking whole sources and queueing proxies"
                autosaveStatus = "Relinking matched lanes"
                updateAgentState()

                for match in report.matches {
                    relinkLaneMedia(laneId: match.laneId.uuidString, sourceURL: match.url, queueProxy: true)
                }

                if !report.unmatchedLaneNames.isEmpty {
                    let preview = report.unmatchedLaneNames.prefix(3).joined(separator: ", ")
                    lastMediaAction = "Relinked \(report.matches.count) lane(s); still missing \(report.unmatchedLaneNames.count): \(preview)"
                }
                updateAgentState()
            }
        }
    }

    private func mediaDuration(for url: URL, fallback: Double) async -> Double {
        let options: [String: Any]? = url.pathExtension.lowercased() == "insv" ? ["AVURLAssetOutOfBandMIMETypeKey": "video/mp4"] : nil
        let asset = AVURLAsset(url: url, options: options)
        do {
            let duration = try await asset.load(.duration).seconds
            if duration.isFinite && duration > 0 {
                return duration
            }
        } catch {
            print("Duration probe failed for relinked media: \(error)")
        }
        return fallback
    }

    private func handlePlaybackModeRequest(_ mode: PlaybackMode) {
        if playbackEngine.playbackMode == mode {
            playbackEngine.togglePlayback()
            updateAgentState()
            return
        }

        playbackEngine.playbackMode = mode
        if let sequence = projectStore.activeSequence {
            playbackEngine.updateValidRanges(for: sequence)
        }
        rebuildPlayer(resumeAfterRebuild: true)
        updateAgentState()
    }

    private func selectLaneForAgent(laneId: String) {
        guard let sequence = projectStore.activeSequence,
              let lane = sequence.lanes.first(where: { laneMatches($0, laneId: laneId) }) else {
            lastMediaAction = "Select lane failed: lane not found"
            updateAgentState()
            return
        }

        selectSourceLane(lane.id)
    }

    private func applyAgentFormat(_ value: String?) {
        switch exportFormat(from: value) ?? .horizontal16x9 {
        case .vertical9x16:
            playbackEngine.playbackFormat = .vertical9x16
            lastMediaAction = "Agent switched output format to 9:16"
        case .horizontal16x9:
            playbackEngine.playbackFormat = .horizontal16x9
            lastMediaAction = "Agent switched output format to 16:9"
        }

