        updateAgentState()
    }

    private func applyAgentProgramCropMode(_ mode: String?) {
        let normalized = (mode ?? "")
            .lowercased()
            .trimmingCharacters(in: .whitespacesAndNewlines)
            .replacingOccurrences(of: "_", with: "-")
            .replacingOccurrences(of: " ", with: "-")

        switch normalized {
        case "keyframe", "keyframes", "animate", "animate-moment", "moment", "timed":
            programCropEditMode = .keyframe
            lastMediaAction = "Agent switched position + zoom mode to Keyframe: Program Output drag/pinch writes timed crop at the shared playhead."
        case "baseline", "base", "whole-lane", "whole-camera", "camera", "default", "":
            programCropEditMode = .baseline
            lastMediaAction = "Agent switched position + zoom mode to Base frame: Program Output drag/pinch fixes the whole selected lane."
        default:
            lastMediaAction = "Program crop mode blocked: unknown mode \(mode ?? "")"
        }

        updateAgentState()
    }

    private func applyProgramCropAdjustment(
        laneId rawLaneId: String?,
        format rawFormat: String?,
        panX: Double?,
        panY: Double?,
        zoom: Double?,
        panXDelta: Double?,
        panYDelta: Double?,
        zoomDelta: Double?
    ) {
        guard var sequence = projectStore.activeSequence else {
            lastMediaAction = "Program crop blocked: no active sequence"
            updateAgentState()
            return
        }

        let requestedLaneId = rawLaneId?.trimmingCharacters(in: .whitespacesAndNewlines)
        let laneIndex: Int?
        if let requestedLaneId, !requestedLaneId.isEmpty {
            laneIndex = sequence.lanes.firstIndex { laneMatches($0, laneId: requestedLaneId) }
        } else if let selectedLaneId {
            laneIndex = sequence.lanes.firstIndex { $0.id == selectedLaneId }
        } else {
            laneIndex = nil
        }

        guard let laneIndex, sequence.lanes.indices.contains(laneIndex) else {
            lastMediaAction = "Program crop blocked: select a lane or pass lane_id"
            updateAgentState()
            return
        }

        let format = exportFormat(from: rawFormat) ?? playbackEngine.playbackFormat
        var metadata = sequence.lanes[laneIndex].metadata ?? VideoLaneMetadata()
        let existing: ProgramCropAdjustment
        switch format {
        case .horizontal16x9:
            existing = metadata.programCrop16x9 ?? ProgramCropAdjustment()
        case .vertical9x16:
            existing = metadata.programCrop9x16 ?? ProgramCropAdjustment()
        }

        let next = ProgramCropAdjustment(
            panX: panX ?? (existing.panX + (panXDelta ?? 0)),
            panY: panY ?? (existing.panY + (panYDelta ?? 0)),
            zoom: zoom ?? (existing.zoom + (zoomDelta ?? 0))
        )
        let beforePayload = cropLedgerPayload(
            lane: sequence.lanes[laneIndex],
            format: format,
            baseline: existing,
            keyframes: programCropKeyframes(for: sequence.lanes[laneIndex], format: format)
        )

        switch format {
        case .horizontal16x9:
            metadata.programCrop16x9 = next
        case .vertical9x16:
            metadata.programCrop9x16 = next
        }
        sequence.lanes[laneIndex].metadata = metadata
        let afterKeyframes = programCropKeyframes(for: sequence.lanes[laneIndex], format: format)
        let afterPayload = cropLedgerPayload(
            lane: sequence.lanes[laneIndex],
            format: format,
            baseline: next,
            keyframes: afterKeyframes
        )
        let endpoint = "GET /program_crop?lane_id=\(sequence.lanes[laneIndex].id.uuidString)&format=\(format.rawValue)&pan_x=\(next.panX)&pan_y=\(next.panY)&zoom=\(next.zoom)"
        appendEditActionLedgerEntry(
            to: &sequence,
            actionId: "program-crop-base-frame",
            actionLabel: "Set base frame",
            category: "framing",
            endpoint: endpoint,
            lane: sequence.lanes[laneIndex],
            before: beforePayload,
            after: afterPayload,
            note: "Whole-lane base-frame metadata changed; source and proxy media stayed untouched."
        )

        projectStore.updateSequence(sequence, undoManager: nil, actionName: "Adjust Program Crop")
        selectedLaneId = sequence.lanes[laneIndex].id
        playbackEngine.updateValidRanges(for: sequence)
        rebuildPlayer()
        lastMediaAction = String(
            format: "Adjusted %@ crop for %@: panX %.2f, panY %.2f, zoom %.2f",
            format.rawValue,
            sequence.lanes[laneIndex].name,
            next.panX,
            next.panY,
            next.zoom
        )
        scheduleAutosave(reason: "adjusted program crop")
        updateAgentState()
    }

    private func applyProgramCropPreset(
        laneId rawLaneId: String?,
        format rawFormat: String?,
        preset rawPreset: String?,
        mode rawMode: String?,
        time rawTime: Double?
    ) {
        guard var sequence = projectStore.activeSequence else {
            lastMediaAction = "Program crop preset blocked: no active sequence"
            updateAgentState()
            return
        }

        let requestedLaneId = rawLaneId?.trimmingCharacters(in: .whitespacesAndNewlines)
        let laneIndex: Int?
        if let requestedLaneId, !requestedLaneId.isEmpty {
            laneIndex = sequence.lanes.firstIndex { laneMatches($0, laneId: requestedLaneId) }
        } else if let selectedLaneId {
            laneIndex = sequence.lanes.firstIndex { $0.id == selectedLaneId }
        } else {
            laneIndex = nil
        }

        guard let laneIndex, sequence.lanes.indices.contains(laneIndex) else {
            lastMediaAction = "Program crop preset blocked: select a lane or pass lane_id"
            updateAgentState()
            return
        }

        let format = exportFormat(from: rawFormat) ?? playbackEngine.playbackFormat
        let mode = (rawMode ?? "baseline")
            .lowercased()
            .trimmingCharacters(in: .whitespacesAndNewlines)
        let preset = (rawPreset ?? "")
            .lowercased()
            .trimmingCharacters(in: .whitespacesAndNewlines)
            .replacingOccurrences(of: "_", with: "-")
            .replacingOccurrences(of: " ", with: "-")

        var metadata = sequence.lanes[laneIndex].metadata ?? VideoLaneMetadata()
        let baseline: ProgramCropAdjustment
        var keyframes: [ProgramCropKeyframe]
        switch format {
        case .horizontal16x9:
            baseline = metadata.programCrop16x9 ?? ProgramCropAdjustment()
            keyframes = metadata.programCropKeyframes16x9 ?? []
        case .vertical9x16:
            baseline = metadata.programCrop9x16 ?? ProgramCropAdjustment()
            keyframes = metadata.programCropKeyframes9x16 ?? []
        }

        let keyframeTime = max(0, rawTime ?? playbackEngine.playhead)
        let currentCrop = mode == "keyframe"
            ? ProgramCropAdjustment.interpolated(baseline: baseline, keyframes: keyframes, at: keyframeTime)
            : baseline
        let beforePayload = cropLedgerPayload(
            lane: sequence.lanes[laneIndex],
            format: format,
            baseline: baseline,
            keyframes: keyframes
        )
        let next: ProgramCropAdjustment
        switch preset {
        case "centered", "center", "safe-center":
            next = ProgramCropAdjustment(panX: 0, panY: 0, zoom: max(1.08, currentCrop.zoom))
        case "solo-safe", "solo", "talking-head", "speaker-safe":
            next = ProgramCropAdjustment(panX: 0, panY: -0.04, zoom: max(1.10, currentCrop.zoom))
        case "hide-desk", "desk", "less-desk", "crop-desk":
            next = ProgramCropAdjustment(panX: currentCrop.panX, panY: -0.20, zoom: max(1.22, currentCrop.zoom))
        case "tighter", "tight", "punch-in", "punchin", "zoom-in", "zoomin":
            next = currentCrop.adjusted(zoomDelta: 0.18)
        case "vertical-solo", "shorts-solo", "reels-solo", "mobile-solo":
            next = ProgramCropAdjustment(panX: 0, panY: -0.06, zoom: max(1.35, currentCrop.zoom))
        case "vertical-punch", "shorts-punch", "big-punch":
            next = currentCrop.adjusted(zoomDelta: 0.30)
        case "looser", "loose", "wide", "zoom-out", "zoomout":
            next = currentCrop.adjusted(zoomDelta: -0.18)
        case "headroom", "head-room", "less-headroom", "up":
            next = ProgramCropAdjustment(panX: currentCrop.panX, panY: -0.18, zoom: max(1.18, currentCrop.zoom))
        case "upper-third", "top-third", "head-top-third", "speaker-upper-third":
            if format == .vertical9x16 {
                next = ProgramCropAdjustment(panX: currentCrop.panX == 0 ? 0.04 : currentCrop.panX, panY: -0.18, zoom: max(1.42, currentCrop.zoom))
            } else {
                next = ProgramCropAdjustment(panX: currentCrop.panX == 0 ? 0.03 : currentCrop.panX, panY: -0.24, zoom: max(1.26, currentCrop.zoom))
            }
        case "left", "nudge-left", "speaker-left", "weight-left":
            next = ProgramCropAdjustment(panX: -0.22, panY: currentCrop.panY, zoom: max(1.18, currentCrop.zoom))
        case "right", "nudge-right", "speaker-right", "weight-right":
            next = ProgramCropAdjustment(panX: 0.22, panY: currentCrop.panY, zoom: max(1.18, currentCrop.zoom))
        case "stack-top", "top-speaker", "top":
            next = ProgramCropAdjustment(panX: 0, panY: -0.14, zoom: max(1.18, currentCrop.zoom))
        case "stack-bottom", "bottom-speaker", "bottom":
            next = ProgramCropAdjustment(panX: 0, panY: 0.14, zoom: max(1.18, currentCrop.zoom))
        default:
            lastMediaAction = "Program crop preset blocked: unknown preset \(rawPreset ?? "")"
            updateAgentState()
            return
        }

        if mode == "keyframe" {
            let keyframe = ProgramCropKeyframe(
                time: keyframeTime,
                panX: next.panX,
                panY: next.panY,
                zoom: next.zoom,
                interpolation: interpolation
            )
            keyframes.removeAll { abs($0.time - keyframeTime) < 0.1 }
            keyframes.append(keyframe)
            keyframes.sort { $0.time < $1.time }
            switch format {
            case .horizontal16x9:
                metadata.programCropKeyframes16x9 = keyframes
            case .vertical9x16:
                metadata.programCropKeyframes9x16 = keyframes
            }
        } else {
            switch format {
            case .horizontal16x9:
                metadata.programCrop16x9 = next
            case .vertical9x16:
                metadata.programCrop9x16 = next
            }
        }

        sequence.lanes[laneIndex].metadata = metadata
        let afterBaseline: ProgramCropAdjustment
        let afterKeyframes: [ProgramCropKeyframe]
        switch format {
        case .horizontal16x9:
            afterBaseline = metadata.programCrop16x9 ?? ProgramCropAdjustment()
            afterKeyframes = metadata.programCropKeyframes16x9 ?? []
        case .vertical9x16:
            afterBaseline = metadata.programCrop9x16 ?? ProgramCropAdjustment()
            afterKeyframes = metadata.programCropKeyframes9x16 ?? []
        }
        let afterPayload = cropLedgerPayload(
            lane: sequence.lanes[laneIndex],
            format: format,
            baseline: afterBaseline,
            keyframes: afterKeyframes
        )
        let endpoint = "GET /program_crop_preset?lane_id=\(sequence.lanes[laneIndex].id.uuidString)&format=\(format.rawValue)&preset=\(preset)&mode=\(mode)&time=\(keyframeTime)"
        appendEditActionLedgerEntry(
            to: &sequence,
            actionId: mode == "keyframe" ? "program-crop-preset-keyframe" : "program-crop-preset-base-frame",
            actionLabel: mode == "keyframe" ? "Apply framing preset as keyframe" : "Apply framing preset as base frame",
            category: "framing",
            endpoint: endpoint,
            lane: sequence.lanes[laneIndex],
            before: beforePayload,
            after: afterPayload,
            note: "Applied \(preset) framing preset as \(mode) metadata; source and proxy media stayed untouched."
        )
        projectStore.updateSequence(sequence, undoManager: nil, actionName: "Apply Program Crop Preset")
        selectedLaneId = sequence.lanes[laneIndex].id
        playbackEngine.updateValidRanges(for: sequence)
        rebuildPlayer()
        lastMediaAction = String(
            format: "Applied %@ %@ crop preset to %@ in %@: panX %.2f, panY %.2f, zoom %.2f",
            mode,
            preset,
            sequence.lanes[laneIndex].name,
            format.rawValue,
            next.panX,
            next.panY,
            next.zoom
        )
        scheduleAutosave(reason: "applied program crop preset")
        updateAgentState()
    }

    private func applyProgramCropKeyframe(
        laneId rawLaneId: String?,
