        appendEditActionLedgerEntry(
            to: &sequence,
            actionId: "program-crop-keyframe",
            actionLabel: "Add framing keyframe",
            category: "framing",
            endpoint: endpoint,
            lane: sequence.lanes[laneIndex],
            before: beforePayload,
            after: afterPayload,
            note: "Timed framing keyframe changed on top of the whole-lane base frame."
        )

        projectStore.updateSequence(sequence, undoManager: nil, actionName: "Add Program Crop Keyframe")
        selectedLaneId = sequence.lanes[laneIndex].id
        playbackEngine.updateValidRanges(for: sequence)
        rebuildPlayer()
