    private func clearProgramCropKeyframes(laneId rawLaneId: String?, format rawFormat: String?) {
        guard var sequence = projectStore.activeSequence else {
            lastMediaAction = "Program crop keyframe clear blocked: no active sequence"
            updateAgentState()
            return
        }

        let requestedLaneId = rawLaneId?.trimmingCharacters(in: .whitespacesAndNewlines)
        let laneIndex: Int?
        if let requestedLaneId, !requestedLaneId.isEmpty {
            laneIndex = sequence.lanes.firstIndex { laneMatches($0, laneId: requestedLaneId) }
        } else if let selectedLaneId {
            laneIndex = sequence.lanes.firstIndex { $0.id == selectedLaneId }
        } else {
            laneIndex = nil
        }

        guard let laneIndex, sequence.lanes.indices.contains(laneIndex) else {
            lastMediaAction = "Program crop keyframe clear blocked: select a lane or pass lane_id"
            updateAgentState()
            return
        }

        let format = exportFormat(from: rawFormat) ?? playbackEngine.playbackFormat
        var metadata = sequence.lanes[laneIndex].metadata ?? VideoLaneMetadata()
        let beforeBaseline: ProgramCropAdjustment
        let beforeKeyframes: [ProgramCropKeyframe]
        switch format {
        case .horizontal16x9:
            beforeBaseline = metadata.programCrop16x9 ?? ProgramCropAdjustment()
            beforeKeyframes = metadata.programCropKeyframes16x9 ?? []
        case .vertical9x16:
            beforeBaseline = metadata.programCrop9x16 ?? ProgramCropAdjustment()
            beforeKeyframes = metadata.programCropKeyframes9x16 ?? []
        }
        let beforePayload = cropLedgerPayload(
            lane: sequence.lanes[laneIndex],
            format: format,
            baseline: beforeBaseline,
            keyframes: beforeKeyframes
        )
        let removed: Int
        switch format {
        case .horizontal16x9:
            removed = metadata.programCropKeyframes16x9?.count ?? 0
            metadata.programCropKeyframes16x9 = []
        case .vertical9x16:
            removed = metadata.programCropKeyframes9x16?.count ?? 0
            metadata.programCropKeyframes9x16 = []
        }
        sequence.lanes[laneIndex].metadata = metadata
        let afterPayload = cropLedgerPayload(
            lane: sequence.lanes[laneIndex],
            format: format,
            baseline: beforeBaseline,
            keyframes: []
        )
        let endpoint = "GET /program_crop_clear_keyframes?lane_id=\(sequence.lanes[laneIndex].id.uuidString)&format=\(format.rawValue)"
        appendEditActionLedgerEntry(
            to: &sequence,
            actionId: "program-crop-clear-keyframes",
            actionLabel: "Clear framing keyframes",
            category: "framing",
            endpoint: endpoint,
            lane: sequence.lanes[laneIndex],
            before: beforePayload,
            after: afterPayload,
            note: "Cleared \(removed) timed framing keyframe(s). Base framing stayed intact."
        )

        projectStore.updateSequence(sequence, undoManager: nil, actionName: "Clear Program Crop Keyframes")
        selectedLaneId = sequence.lanes[laneIndex].id
        rebuildPlayer()
        lastMediaAction = "Cleared \(removed) \(format.rawValue) crop keyframe(s) for \(sequence.lanes[laneIndex].name)"
        scheduleAutosave(reason: "cleared program crop keyframes")
        updateAgentState()
    }

    private func setEditPassContext(values: [String: String]) {
        guard var sequence = projectStore.activeSequence else {
            lastMediaAction = "Edit pass blocked: no active sequence"
            updateAgentState()
            return
        }

        let oldContext = sequence.editPassContext
        let passNumber = Int(values["pass_number"] ?? values["pass"] ?? "") ?? oldContext.passNumber
        let context = EditPassContext(
            label: values["label"] ?? values["name"] ?? oldContext.label,
            actor: values["actor"] ?? oldContext.actor,
            actorType: values["actor_type"] ?? values["actorType"] ?? oldContext.actorType,
            passNumber: passNumber,
            goal: values["goal"] ?? oldContext.goal,
            status: values["status"] ?? oldContext.status,
            startedAt: Date(),
            updatedAt: Date()
        )
        sequence.editPassContext = context
        appendEditActionLedgerEntry(
            to: &sequence,
            actionId: "edit-pass-context",
            actionLabel: "Set editing pass context",
            category: "edit-pass",
            endpoint: "GET /edit_pass",
            lane: nil,
            before: editPassContextPayload(oldContext),
            after: editPassContextPayload(context),
            note: values["note"] ?? "Marked editing pass context for dogfood learning loop.",
            actor: context.actor,
            actorType: context.actorType
        )
        projectStore.updateSequence(sequence, undoManager: nil, actionName: "Set Edit Pass Context")
        lastMediaAction = "Marked \(context.label) (pass \(context.passNumber), \(context.actor))"
        scheduleAutosave(reason: "marked edit pass context")
        updateAgentState()
    }

