    private func exportVideo() {
        #if os(macOS)
        guard let sequence = projectStore.activeSequence else { return }
        let readiness = mediaReadinessSummary()
        if !readiness.isProductionReady {
            isShowingProductionDetails = true
            errorMessage = "Export needs a proxy-ready production session first. \(readiness.detail)"
            showErrorAlert = true
            lastMediaAction = "Export blocked: \(readiness.detail)"
            blockExportStatus(kind: "manual-ui", reason: readiness.detail)
            updateAgentState()
            return
        }

        let panel = NSSavePanel()
        panel.allowedContentTypes = [.mpeg4Movie]
        panel.nameFieldStringValue = "QuipslyExport.mp4"

        if panel.runModal() == .OK, let outputURL = panel.url {
            let wideURL = outputURL.deletingPathExtension().appendingPathExtension("16x9.mp4")
            let verticalURL = outputURL.deletingPathExtension().appendingPathExtension("9x16.mp4")
            beginExportStatus(kind: "manual-ui", outputURLs: [wideURL, verticalURL], proofSeconds: nil)
            updateAgentState()

            Task {
                do {
                    // Export 16x9 Base
                    try await ExportEngine.shared.export(
                        sequence: sequence,
                        to: wideURL,
                        format: .horizontal16x9,
                        allowExternalOriginalMedia: false,
                        allowedOriginalMediaRootPath: nil
                    )

                    // Export 9x16 Reframed
                    try await ExportEngine.shared.export(
                        sequence: sequence,
                        to: verticalURL,
                        format: .vertical9x16,
                        allowExternalOriginalMedia: false,
                        allowedOriginalMediaRootPath: nil
                    )

                    await MainActor.run {
                        completeExportStatus(outputURLs: [wideURL, verticalURL])
                        self.errorMessage = "Export completed successfully to \(outputURL.deletingLastPathComponent().path)"
                        self.showErrorAlert = true
                        self.lastMediaAction = "Export completed: \(wideURL.lastPathComponent), \(verticalURL.lastPathComponent)"
                        self.updateAgentState()
                    }
                } catch {
                    await MainActor.run {
                        failExportStatus(error: error)
                        self.errorMessage = "Export failed: \(error.localizedDescription)"
                        self.showErrorAlert = true
                        self.lastMediaAction = "Export failed: \(error.localizedDescription)"
                        self.updateAgentState()
                    }
                }
            }
        }
        #else
        print("Export not supported")
        #endif
    }

    private func exportProxyPackageForAgent(directoryPath: String?, basename: String?, proofSeconds: Double?) {
        guard let sequence = projectStore.activeSequence else {
            lastMediaAction = "Export proof blocked: no active sequence"
            blockExportStatus(kind: "agent-proxy-package", reason: "No active sequence loaded.")
            updateAgentState()
            return
        }

        let readiness = mediaReadinessSummary()
        guard readiness.isProductionReady else {
            lastMediaAction = "Export proof blocked: \(readiness.detail)"
            isShowingProductionDetails = true
            blockExportStatus(kind: "agent-proxy-package", reason: readiness.detail)
            updateAgentState()
            return
        }

        let cleanBasename = sanitizedExportBasename(basename?.isEmpty == false ? basename! : normalizedActiveSessionName())
        let outputDirectory: URL
        if let directoryPath, !directoryPath.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty {
            outputDirectory = URL(fileURLWithPath: directoryPath, isDirectory: true)
        } else {
            outputDirectory = defaultLocalExportDirectory()
        }
        let proofLimit = (proofSeconds?.isFinite == true && (proofSeconds ?? 0) > 0) ? proofSeconds : nil
        let wideURL = outputDirectory.appendingPathComponent("\(cleanBasename)-16x9.mp4")
        let verticalURL = outputDirectory.appendingPathComponent("\(cleanBasename)-9x16.mp4")
        beginExportStatus(kind: "agent-proxy-package", outputURLs: [wideURL, verticalURL], proofSeconds: proofLimit)

        lastMediaAction = proofLimit.map {
            String(format: "Export proof started: %.1fs proxy package", $0)
        } ?? "Export proof started: full proxy package"
        updateAgentState()

        Task {
            do {
                try await ExportEngine.shared.export(
                    sequence: sequence,
                    to: wideURL,
                    format: .horizontal16x9,
                    allowExternalOriginalMedia: false,
                    allowedOriginalMediaRootPath: nil,
                    durationLimitSeconds: proofLimit
                )
                try await ExportEngine.shared.export(
                    sequence: sequence,
                    to: verticalURL,
                    format: .vertical9x16,
                    allowExternalOriginalMedia: false,
                    allowedOriginalMediaRootPath: nil,
                    durationLimitSeconds: proofLimit
                )

                await MainActor.run {
                    completeExportStatus(outputURLs: [wideURL, verticalURL])
                    lastMediaAction = "Export proof completed: \(wideURL.path) and \(verticalURL.path)"
                    updateAgentState()
                }
            } catch {
                await MainActor.run {
                    failExportStatus(error: error)
                    lastMediaAction = "Export proof failed: \(error.localizedDescription)"
                    errorMessage = lastMediaAction
                    showErrorAlert = true
                    updateAgentState()
                }
            }
        }
    }

    private func exportAudioMasterForAgent(directoryPath: String?, basename: String?, proofSeconds: Double?) {
        guard let sequence = projectStore.activeSequence else {
            lastMediaAction = "Audio master export blocked: no active sequence"
            blockExportStatus(kind: "agent-audio-master", reason: "No active sequence loaded.")
            updateAgentState()
            return
        }

        let readiness = mediaReadinessSummary()
        guard readiness.hasSequence,
              readiness.audioReadyCount > 0,
              readiness.audioBlockedCount == 0 else {
            let reason = readiness.hasSequence
                ? "Podcast audio needs ready audio proxies first. \(readiness.detail)"
                : "Load an episode session before exporting podcast audio."
            lastMediaAction = "Audio master export blocked: \(reason)"
            isShowingProductionDetails = true
            blockExportStatus(kind: "agent-audio-master", reason: reason)
            updateAgentState()
            return
        }

        let cleanBasename = sanitizedExportBasename(basename?.isEmpty == false ? basename! : normalizedActiveSessionName())
        let outputDirectory: URL
        if let directoryPath, !directoryPath.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty {
            outputDirectory = URL(fileURLWithPath: directoryPath, isDirectory: true)
        } else {
            outputDirectory = defaultLocalExportDirectory()
        }
        let proofLimit = (proofSeconds?.isFinite == true && (proofSeconds ?? 0) > 0) ? proofSeconds : nil
        let audioURL = outputDirectory.appendingPathComponent("\(cleanBasename)-podcast-audio.m4a")
        beginExportStatus(kind: "agent-audio-master", outputURLs: [audioURL], proofSeconds: proofLimit)

        lastMediaAction = proofLimit.map {
            String(format: "Podcast audio proof started: %.1fs M4A", $0)
        } ?? "Podcast audio master export started"
        updateAgentState()

        Task {
            do {
                try await ExportEngine.shared.exportAudioMaster(
                    sequence: sequence,
                    to: audioURL,
                    allowExternalOriginalMedia: false,
                    allowedOriginalMediaRootPath: nil,
                    durationLimitSeconds: proofLimit
                )

                await MainActor.run {
                    completeExportStatus(outputURLs: [audioURL])
                    lastMediaAction = "Podcast audio export completed: \(audioURL.path)"
                    updateAgentState()
                }
            } catch {
                await MainActor.run {
                    failExportStatus(error: error)
                    lastMediaAction = "Podcast audio export failed: \(error.localizedDescription)"
                    errorMessage = lastMediaAction
                    showErrorAlert = true
                    updateAgentState()
                }
            }
        }
    }

