        fullReleaseStep = "exporting release artifacts"
        fullReleaseOutputPath = outputDirectory.path
        fullReleaseBasename = basename
        fullReleaseErrorMessage = ""
        fullReleaseStartedAt = Date()
        fullReleaseCompletedAt = nil
    }

    private func completeFullReleaseStatus(outputDirectory: URL, basename: String) {
        fullReleaseStatus = "completed"
        fullReleaseStep = "operator handoff ready"
        fullReleaseOutputPath = outputDirectory.path
        fullReleaseBasename = basename
        fullReleaseErrorMessage = ""
        fullReleaseCompletedAt = Date()
    }

    private func blockFullReleaseStatus(reason: String) {
        fullReleaseStatus = "blocked"
        fullReleaseStep = "blocked"
        fullReleaseErrorMessage = reason
        fullReleaseCompletedAt = Date()
    }

    private func failFullReleaseStatus(reason: String) {
        fullReleaseStatus = "failed"
        fullReleaseStep = "failed"
        fullReleaseErrorMessage = reason
        fullReleaseCompletedAt = Date()
    }

    private func writeFullReleaseReceipt(
        outputDirectory: URL,
        basename: String,
        phase: String,
        status: String,
        message: String = "",
        extra: [String: Any] = [:]
    ) {
        let receiptURL = outputDirectory.appendingPathComponent("\(basename)-release-finalization-receipt.json")
        let formatter = ISO8601DateFormatter()
        var payload: [String: Any] = [
            "model": "quipsly-full-release-finalization-receipt",
            "version": "2026-06-17.full-release-finalization-receipt.v1",
            "writtenAt": formatter.string(from: Date()),
            "phase": phase,
            "status": status,
            "message": message,
            "sessionName": normalizedActiveSessionName(),
            "basename": basename,
            "outputDirectory": outputDirectory.path,
            "exportState": exportStatePayload(),
            "fullRelease": fullReleasePayload(),
            "sourcePolicy": "receipt records release progress and artifact truth; it does not mutate source media or platform state"
        ]
        if !extra.isEmpty {
            payload["extra"] = extra
        }
        do {
            try FileManager.default.createDirectory(at: outputDirectory, withIntermediateDirectories: true)
            try writeJSONObject(payload, to: receiptURL)
        } catch {
            lastMediaAction = "Release receipt write failed: \(error.localizedDescription)"
        }
    }

    private func prepareFullReleaseForHuman() {
        let baseDirectory = defaultLocalExportDirectory()
            .appendingPathComponent("full-release", isDirectory: true)
        prepareFullReleaseForAgent(
            directoryPath: baseDirectory.path,
            basename: normalizedActiveSessionName().isEmpty ? "quipsly-release" : normalizedActiveSessionName(),
            proofSeconds: nil
        )
    }

    private func prepareFullReleaseForAgent(directoryPath: String?, basename: String?, proofSeconds: Double?) {
        prepareReleaseForAgent(
            directoryPath: directoryPath,
            basename: basename,
            proofSeconds: proofSeconds,
            generatePublishHandoff: true
        )
    }

    private func prepareReleaseForAgent(directoryPath: String?, basename: String?, proofSeconds: Double?, generatePublishHandoff: Bool = false) {
        guard let sequence = projectStore.activeSequence else {
            lastMediaAction = "Release prep blocked: no active sequence"
            if generatePublishHandoff {
                blockFullReleaseStatus(reason: "No active sequence loaded.")
            }
            blockExportStatus(kind: "release-prep", reason: "No active sequence loaded.")
            updateAgentState()
            return
        }

        let readiness = mediaReadinessSummary()
        guard readiness.isProductionReady else {
            lastMediaAction = "Release prep blocked: \(readiness.detail)"
            if generatePublishHandoff {
                blockFullReleaseStatus(reason: readiness.detail)
            }
            blockExportStatus(kind: "release-prep", reason: readiness.detail)
            updateAgentState()
            return
        }
        guard readiness.audioReadyCount > 0, readiness.audioBlockedCount == 0 else {
            let reason = "Release prep needs ready audio proxies before podcast audio can be prepared. \(readiness.detail)"
            lastMediaAction = "Release prep blocked: \(reason)"
            if generatePublishHandoff {
                blockFullReleaseStatus(reason: reason)
            }
            blockExportStatus(kind: "release-prep", reason: reason)
            updateAgentState()
            return
        }

        let cleanBasename = sanitizedExportBasename(basename?.isEmpty == false ? basename! : normalizedActiveSessionName())
        let outputDirectory: URL
        if let directoryPath, !directoryPath.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty {
            outputDirectory = URL(fileURLWithPath: directoryPath, isDirectory: true)
        } else {
            outputDirectory = defaultLocalExportDirectory()
                .appendingPathComponent("release-prep", isDirectory: true)
        }
        let proofLimit = (proofSeconds?.isFinite == true && (proofSeconds ?? 0) > 0) ? proofSeconds : nil
        let wideURL = outputDirectory.appendingPathComponent("\(cleanBasename)-16x9.mp4")
        let verticalURL = outputDirectory.appendingPathComponent("\(cleanBasename)-9x16.mp4")
        let audioURL = outputDirectory.appendingPathComponent("\(cleanBasename)-podcast-audio.m4a")
        let shortJobs: [(clip: ShortClipCandidate, url: URL, sequenceRanges: [(start: Double, duration: Double)], proofDuration: Double)] = sequence.shortClipQueue.enumerated().compactMap { index, clip in
            let exportRanges = shortClipExportRanges(for: clip, in: sequence)
            let proofDuration = exportRanges.reduce(0) { $0 + $1.duration }
            guard proofDuration.isFinite, proofDuration > 0 else {
                return nil
            }
            let titleSlug = sanitizedExportBasename(clip.title.isEmpty ? "short" : clip.title)
            let filePrefix = String(format: "%@-%02d-%@", cleanBasename, index + 1, titleSlug)
            return (
                clip: clip,
                url: outputDirectory.appendingPathComponent("\(filePrefix)-9x16-short.mp4"),
                sequenceRanges: exportRanges,
                proofDuration: proofDuration
            )
        }
        guard shortJobs.count == sequence.shortClipQueue.count else {
            let invalidCount = sequence.shortClipQueue.count - shortJobs.count
            let reason = "Release prep has \(invalidCount) queued short recipes with invalid duration. Fix or remove them before full prep."
            lastMediaAction = "Release prep blocked: \(reason)"
            if generatePublishHandoff {
                blockFullReleaseStatus(reason: reason)
            }
            blockExportStatus(kind: "release-prep", reason: reason)
            updateAgentState()
            return
        }
        let plannedOutputs = [wideURL, verticalURL] + shortJobs.map { $0.url } + [audioURL]

        beginExportStatus(kind: "release-prep", outputURLs: plannedOutputs, proofSeconds: proofLimit)
        if generatePublishHandoff {
            beginFullReleaseStatus(outputDirectory: outputDirectory, basename: cleanBasename)
            writeFullReleaseReceipt(
                outputDirectory: outputDirectory,
                basename: cleanBasename,
                phase: "started",
                status: "running",
                message: "Full release prep started."
            )
        }
        deliveryPacketStatus = "idle"
        deliveryPacketOutputPath = ""
        deliveryPacketErrorMessage = ""
        publishPacketStatus = "idle"
        publishPacketOutputPath = ""
        publishPacketErrorMessage = ""
        publishUploadBundleStatus = "idle"
        publishUploadBundleOutputPath = ""
        publishUploadBundleErrorMessage = ""
        publicationCockpitStatus = "idle"
        publicationCockpitOutputPath = ""
        publicationReceiptLogOutputPath = ""
        publicationCockpitErrorMessage = ""
        publicationCockpitGeneratedAt = nil
        socialShortsPacketStatus = "idle"
        socialShortsPacketOutputPath = ""
        socialShortsPacketErrorMessage = ""
        socialPublicationQueueStatus = "idle"
        socialPublicationQueueOutputPath = ""
        socialPublicationQueueErrorMessage = ""
        socialMasterQueueStatus = "idle"
        socialMasterQueueOutputPath = ""
        socialMasterQueueErrorMessage = ""
        socialMasterQueueGeneratedAt = nil
        socialMasterQueueClipCount = 0
        socialMasterQueueTopTitles = []
        socialMasterQueueSourcePackSummary = []
        socialMasterQueueCandidatePreview = []
        selectedSocialMasterQueueRank = ""
        socialMasterReceiptCapturePlatform = "YouTube Shorts"
        socialMasterReceiptCaptureURL = ""
        socialMasterReceiptCaptureProviderId = ""
        socialMasterReceiptCaptureStatus = "published"
        podcastPacketStatus = "idle"
        podcastPacketOutputPath = ""
        podcastPacketErrorMessage = ""
        podcastReadyPacketStatus = "idle"
        podcastReadyPacketOutputPath = ""
        podcastReadyPacketErrorMessage = ""
        podcastReadyPacketGeneratedAt = nil
        lastMediaAction = proofLimit.map {
            String(format: "Release prep started: %.1fs proof outputs", $0)
        } ?? "Release prep started: episode, queued shorts, audio, and delivery packet"
        updateAgentState()

        Task {
            do {
                try FileManager.default.createDirectory(at: outputDirectory, withIntermediateDirectories: true)
                try await ExportEngine.shared.export(
                    sequence: sequence,
                    to: wideURL,
                    format: .horizontal16x9,
                    allowExternalOriginalMedia: false,
                    allowedOriginalMediaRootPath: nil,
                    durationLimitSeconds: proofLimit
                )
                try await ExportEngine.shared.export(
                    sequence: sequence,
                    to: verticalURL,
                    format: .vertical9x16,
                    allowExternalOriginalMedia: false,
                    allowedOriginalMediaRootPath: nil,
                    durationLimitSeconds: proofLimit
                )
                for job in shortJobs {
                    await MainActor.run {
                        markShortClipExportResult(
                            id: job.clip.id,
                            status: "exporting",
                            note: "Release prep short export started: \(job.url.path)"
                        )
                    }
                    try await ExportEngine.shared.export(
                        sequence: sequence,
                        to: job.url,
                        format: .vertical9x16,
                        allowExternalOriginalMedia: false,
                        allowedOriginalMediaRootPath: nil,
                        sequenceRanges: proofLimit.map { limit in
                            var remaining = max(0, limit)
                            return job.sequenceRanges.compactMap { range -> (start: Double, duration: Double)? in
                                guard remaining > 0 else { return nil }
                                let duration = min(range.duration, remaining)
                                remaining -= duration
                                return duration > 0 ? (start: range.start, duration: duration) : nil
                            }
                        } ?? job.sequenceRanges,
                        primaryOverlayText: burnedInPrimaryOverlayText(for: job.clip),
                        captionText: burnedInCaptionText(for: job.clip)
                    )
                    await MainActor.run {
                        markShortClipExportResult(
                            id: job.clip.id,
                            status: "exported",
                            note: shortExportSuccessNote(outputURL: job.url, clip: job.clip)
                        )
                    }
                }
                try await ExportEngine.shared.exportAudioMaster(
                    sequence: sequence,
                    to: audioURL,
                    allowExternalOriginalMedia: false,
                    allowedOriginalMediaRootPath: nil,
                    durationLimitSeconds: proofLimit
                )

                await MainActor.run {
                    completeExportStatus(outputURLs: plannedOutputs)
                    lastMediaAction = "Release prep exports completed in \(outputDirectory.path)"
                    if generatePublishHandoff {
                        writeFullReleaseReceipt(
                            outputDirectory: outputDirectory,
                            basename: cleanBasename,
                            phase: "exports-completed",
                            status: "running",
                            message: "Release media artifacts exported; handoff packet generation is starting."
                        )
                    }
                    if generatePublishHandoff {
                        fullReleaseStep = "generating delivery packet"
                    }
                    generateDeliveryPacketForAgent(directoryPath: outputDirectory.path, basename: cleanBasename)
                    if generatePublishHandoff {
                        if deliveryPacketStatus != "generated" {
                            failFullReleaseStatus(reason: deliveryPacketErrorMessage.isEmpty ? "Delivery packet generation did not complete." : deliveryPacketErrorMessage)
                            writeFullReleaseReceipt(
                                outputDirectory: outputDirectory,
                                basename: cleanBasename,
                                phase: "delivery-packet",
                                status: "failed",
                                message: fullReleaseErrorMessage
                            )
                            updateAgentState()
                            return
                        }
                        writeFullReleaseReceipt(
                            outputDirectory: outputDirectory,
                            basename: cleanBasename,
                            phase: "delivery-packet",
                            status: "running",
                            message: "Delivery packet generated."
                        )
                        fullReleaseStep = "generating publish ledger"
                        generatePublishLedgerFromCurrentDelivery()
                        writeFullReleaseReceipt(
                            outputDirectory: outputDirectory,
                            basename: cleanBasename,
                            phase: "publish-ledger",
                            status: "running",
                            message: "Ship ledger generated from current delivery packet."
                        )
                        fullReleaseStep = "generating publish packet"
                        generatePublishPacketForAgent(directoryPath: outputDirectory.path, basename: cleanBasename)
                        if publishPacketStatus != "generated" {
                            failFullReleaseStatus(reason: publishPacketErrorMessage.isEmpty ? "Ship packet generation did not complete." : publishPacketErrorMessage)
                            writeFullReleaseReceipt(
                                outputDirectory: outputDirectory,
                                basename: cleanBasename,
                                phase: "publish-packet",
                                status: "failed",
                                message: fullReleaseErrorMessage
                            )
                            updateAgentState()
                            return
                        }
                        writeFullReleaseReceipt(
                            outputDirectory: outputDirectory,
                            basename: cleanBasename,
                            phase: "publish-packet",
                            status: "running",
                            message: "Ship packet generated."
                        )
                        fullReleaseStep = "generating upload packet bundle"
                        generatePublishUploadPacketBundleForAgent(directoryPath: outputDirectory.path, basename: cleanBasename)
                        if publishUploadBundleStatus != "generated" {
                            failFullReleaseStatus(reason: publishUploadBundleErrorMessage.isEmpty ? "Upload packet bundle generation did not complete." : publishUploadBundleErrorMessage)
                            writeFullReleaseReceipt(
                                outputDirectory: outputDirectory,
                                basename: cleanBasename,
                                phase: "upload-packet-bundle",
                                status: "failed",
                                message: fullReleaseErrorMessage
                            )
                            updateAgentState()
                            return
                        }
                        writeFullReleaseReceipt(
                            outputDirectory: outputDirectory,
                            basename: cleanBasename,
                            phase: "upload-packet-bundle",
                            status: "running",
                            message: "Upload packet bundle generated."
                        )
                        if !shortJobs.isEmpty {
                            fullReleaseStep = "generating social shorts packet"
                            generateSocialShortsPacketForAgent(directoryPath: outputDirectory.path, basename: cleanBasename)
                            if socialShortsPacketStatus != "generated" {
                                failFullReleaseStatus(reason: socialShortsPacketErrorMessage.isEmpty ? "Social shorts packet generation did not complete." : socialShortsPacketErrorMessage)
                                writeFullReleaseReceipt(
                                    outputDirectory: outputDirectory,
                                    basename: cleanBasename,
                                    phase: "social-shorts-packet",
                                    status: "failed",
                                    message: fullReleaseErrorMessage
                                )
                                updateAgentState()
                                return
                            }
                            writeFullReleaseReceipt(
                                outputDirectory: outputDirectory,
                                basename: cleanBasename,
                                phase: "social-shorts-packet",
                                status: "running",
                                message: "Social shorts packet generated."
                            )
                            fullReleaseStep = "generating social publication queue"
                            generateSocialPublicationQueueForAgent(directoryPath: outputDirectory.path, basename: cleanBasename)
                            if socialPublicationQueueStatus != "generated" {
                                failFullReleaseStatus(reason: socialPublicationQueueErrorMessage.isEmpty ? "Social publication queue generation did not complete." : socialPublicationQueueErrorMessage)
                                writeFullReleaseReceipt(
                                    outputDirectory: outputDirectory,
                                    basename: cleanBasename,
                                    phase: "social-publication-queue",
                                    status: "failed",
                                    message: fullReleaseErrorMessage
                                )
                                updateAgentState()
                                return
                            }
                            writeFullReleaseReceipt(
                                outputDirectory: outputDirectory,
                                basename: cleanBasename,
                                phase: "social-publication-queue",
                                status: "running",
                                message: "Social publication queue generated."
                            )
                            fullReleaseStep = "generating social ready packet"
                            let socialQueueManifestURL = URL(fileURLWithPath: socialPublicationQueueOutputPath, isDirectory: true)
                                .appendingPathComponent("\(cleanBasename)-social-publication-queue.json")
                            let socialReadyOutputFolder = outputDirectory
                                .appendingPathComponent("\(cleanBasename)-social-ready", isDirectory: true)
                            let socialReadyGenerated = generateSocialReadyPacketForFullRelease(
                                queueManifestURL: socialQueueManifestURL,
                                outputFolder: socialReadyOutputFolder,
                                basename: "\(cleanBasename)-social-ready",
                                topCount: max(12, shortJobs.count)
                            )
                            if !socialReadyGenerated {
                                failFullReleaseStatus(reason: socialMasterQueueErrorMessage.isEmpty ? "Social ready packet generation did not complete." : socialMasterQueueErrorMessage)
                                writeFullReleaseReceipt(
                                    outputDirectory: outputDirectory,
                                    basename: cleanBasename,
                                    phase: "social-ready-packet",
                                    status: "failed",
                                    message: fullReleaseErrorMessage
                                )
                                updateAgentState()
                                return
                            }
                            writeFullReleaseReceipt(
                                outputDirectory: outputDirectory,
                                basename: cleanBasename,
                                phase: "social-ready-packet",
                                status: "running",
                                message: "Social ready packet generated."
                            )
                        }
                        fullReleaseStep = "generating podcast packet"
                        generatePodcastPacketForAgent(directoryPath: outputDirectory.path, basename: cleanBasename)
                        if podcastPacketStatus != "generated" {
                            failFullReleaseStatus(reason: podcastPacketErrorMessage.isEmpty ? "Podcast packet generation did not complete." : podcastPacketErrorMessage)
                            writeFullReleaseReceipt(
                                outputDirectory: outputDirectory,
                                basename: cleanBasename,
                                phase: "podcast-packet",
                                status: "failed",
                                message: fullReleaseErrorMessage
                            )
                            updateAgentState()
                            return
                        }
                        writeFullReleaseReceipt(
                            outputDirectory: outputDirectory,
                            basename: cleanBasename,
                            phase: "podcast-packet",
                            status: "running",
                            message: "Podcast packet generated."
                        )
                        fullReleaseStep = "generating podcast ready packet"
                        let podcastManifestURL = URL(fileURLWithPath: outputDirectory.path, isDirectory: true)
                            .appendingPathComponent("\(cleanBasename)-podcast-packet", isDirectory: true)
                            .appendingPathComponent("\(cleanBasename)-podcast-manifest.json")
                        let podcastReadyOutputFolder = outputDirectory
                            .appendingPathComponent("\(cleanBasename)-podcast-ready", isDirectory: true)
                        let podcastReadyGenerated = generatePodcastReadyPacketForFullRelease(
                            manifestURL: podcastManifestURL,
                            outputFolder: podcastReadyOutputFolder,
                            basename: "\(cleanBasename)-podcast-ready"
                        )
                        if !podcastReadyGenerated {
                            failFullReleaseStatus(reason: podcastReadyPacketErrorMessage.isEmpty ? "Podcast ready packet generation did not complete." : podcastReadyPacketErrorMessage)
                            writeFullReleaseReceipt(
                                outputDirectory: outputDirectory,
                                basename: cleanBasename,
                                phase: "podcast-ready-packet",
                                status: "failed",
                                message: fullReleaseErrorMessage
                            )
                            updateAgentState()
                            return
                        }
                        writeFullReleaseReceipt(
                            outputDirectory: outputDirectory,
                            basename: cleanBasename,
                            phase: "podcast-ready-packet",
                            status: "running",
                            message: "Podcast ready packet generated."
                        )
                        fullReleaseStep = "generating publication cockpit"
                        generatePublicationCockpitForAgent(directoryPath: outputDirectory.path, basename: cleanBasename)
                        if publicationCockpitStatus != "generated" {
                            failFullReleaseStatus(reason: publicationCockpitErrorMessage.isEmpty ? "Publication cockpit generation did not complete." : publicationCockpitErrorMessage)
                            writeFullReleaseReceipt(
                                outputDirectory: outputDirectory,
                                basename: cleanBasename,
                                phase: "publication-cockpit",
                                status: "failed",
                                message: fullReleaseErrorMessage
                            )
                            updateAgentState()
                            return
                        }
                        writeFullReleaseReceipt(
                            outputDirectory: outputDirectory,
                            basename: cleanBasename,
                            phase: "publication-cockpit",
                            status: "running",
                            message: "Publication cockpit generated."
                        )
                        completeFullReleaseStatus(outputDirectory: outputDirectory, basename: cleanBasename)
                        lastMediaAction = "Full release prep completed in \(outputDirectory.path)"
                        writeFullReleaseReceipt(
                            outputDirectory: outputDirectory,
                            basename: cleanBasename,
                            phase: "completed",
                            status: "completed",
                            message: "Full release prep completed."
                        )
                    }
                    updateAgentState()
                }
            } catch {
                await MainActor.run {
                    failExportStatus(error: error)
                    deliveryPacketStatus = "failed"
                    deliveryPacketErrorMessage = "Release prep failed before packet generation: \(error.localizedDescription)"
                    if generatePublishHandoff {
                        failFullReleaseStatus(reason: error.localizedDescription)
                        writeFullReleaseReceipt(
                            outputDirectory: outputDirectory,
                            basename: cleanBasename,
                            phase: "failed",
                            status: "failed",
                            message: error.localizedDescription
                        )
                    }
                    lastMediaAction = "Release prep failed: \(error.localizedDescription)"
                    errorMessage = lastMediaAction
                    showErrorAlert = true
                    updateAgentState()
                }
            }
        }
    }

    private func sanitizedExportBasename(_ value: String) -> String {
        let allowed = CharacterSet.alphanumerics.union(CharacterSet(charactersIn: "-_"))
        let safeString = value.unicodeScalars.map { allowed.contains($0) ? String($0) : "-" }.joined()
        let collapsed = safeString
            .replacingOccurrences(of: "-+", with: "-", options: .regularExpression)
            .trimmingCharacters(in: CharacterSet(charactersIn: "-_"))
        return collapsed.isEmpty ? "quipsly-export-proof" : collapsed
    }

    private func defaultLocalExportDirectory() -> URL {
        if let configured = ProcessInfo.processInfo.environment["QUIPSLY_MEDIA_VAULT"], !configured.isEmpty {
            return URL(fileURLWithPath: configured, isDirectory: true)
                .appendingPathComponent("exports", isDirectory: true)
        }

        let appSupport = FileManager.default.urls(for: .applicationSupportDirectory, in: .userDomainMask).first!
        return appSupport
            .appendingPathComponent("Quipsly", isDirectory: true)
            .appendingPathComponent("MediaVault", isDirectory: true)
            .appendingPathComponent("exports", isDirectory: true)
    }

    private func syncAudio() {
        guard let sequence = projectStore.activeSequence else { return }

        isSyncing = true
        Task {
            do {
                let syncedSequence = try await AudioSyncer.shared.syncSequence(sequence)

                await MainActor.run {
                    var project = projectStore.project
                    if let index = project.sequences.firstIndex(where: { $0.id == sequence.id }) {
                        project.sequences[index] = syncedSequence
                        projectStore.updateProject(project, undoManager: nil, actionName: "Sync Audio")
                    }
                    rebuildPlayer()
                    scheduleAutosave(reason: "synced audio")
                    isSyncing = false
                }
            } catch {
                await MainActor.run {
                    self.errorMessage = "Failed to sync audio: \(error.localizedDescription)"
                    self.showErrorAlert = true
                    self.isSyncing = false
                }
            }
        }
    }

    private func addKeyframe(at time: Double? = nil, yaw: Double? = nil, pitch: Double? = nil, roll: Double? = nil, fov: Double? = nil, interpolation: InterpolationMode? = nil) {
        guard var sequence = projectStore.activeSequence else { return }

        let newKeyframe = FramingKeyframe(
            id: UUID(),
            time: time ?? playbackEngine.playhead,
            yaw: yaw ?? self.yaw,
            pitch: pitch ?? self.pitch,
            roll: roll ?? self.roll,
            fov: fov ?? self.fov,
            interpolation: interpolation ?? self.interpolation
        )

        if playbackEngine.playbackFormat == .vertical9x16 {
            sequence.verticalOrientationTrack.keyframes.removeAll(where: { abs($0.time - newKeyframe.time) < 0.1 })
            sequence.verticalOrientationTrack.keyframes.append(newKeyframe)
            sequence.verticalOrientationTrack.keyframes.sort { $0.time < $1.time }
        } else {
            sequence.orientationTrack.keyframes.removeAll(where: { abs($0.time - newKeyframe.time) < 0.1 })
            sequence.orientationTrack.keyframes.append(newKeyframe)
            sequence.orientationTrack.keyframes.sort { $0.time < $1.time }
        }

        projectStore.updateSequence(sequence, undoManager: nil, actionName: "Add frame key")

        rebuildPlayer()
        scheduleAutosave(reason: "added keyframe")
    }

    private func updateKeyframe() {
        guard var sequence = projectStore.activeSequence else { return }
        // For simplicity, just add/update keyframe at current playhead when dragging slider
        let time = playbackEngine.playhead

        if playbackEngine.playbackFormat == .vertical9x16 {
            if let index = sequence.verticalOrientationTrack.keyframes.firstIndex(where: { abs($0.time - time) < 0.5 }) {
                sequence.verticalOrientationTrack.keyframes[index].yaw = self.yaw
                sequence.verticalOrientationTrack.keyframes[index].pitch = self.pitch
                sequence.verticalOrientationTrack.keyframes[index].roll = self.roll
                sequence.verticalOrientationTrack.keyframes[index].fov = self.fov
                sequence.verticalOrientationTrack.keyframes[index].interpolation = self.interpolation

                projectStore.updateSequence(sequence, undoManager: nil, actionName: "Update Keyframe")
                rebuildPlayer()
                scheduleAutosave(reason: "updated keyframe")
            } else {
                addKeyframe()
            }
        } else {
            if let index = sequence.orientationTrack.keyframes.firstIndex(where: { abs($0.time - time) < 0.5 }) {
                sequence.orientationTrack.keyframes[index].yaw = self.yaw
                sequence.orientationTrack.keyframes[index].pitch = self.pitch
                sequence.orientationTrack.keyframes[index].roll = self.roll
                sequence.orientationTrack.keyframes[index].fov = self.fov
                sequence.orientationTrack.keyframes[index].interpolation = self.interpolation

                projectStore.updateSequence(sequence, undoManager: nil, actionName: "Update Keyframe")
                rebuildPlayer()
                scheduleAutosave(reason: "updated keyframe")
            } else {
                addKeyframe()
            }
        }
    }

    private func normalizedActiveSessionName() -> String {
        normalizedSessionName(activeSessionName)
    }

    private func normalizedSessionName(_ value: String) -> String {
        let trimmed = value.trimmingCharacters(in: .whitespacesAndNewlines)
        return trimmed.isEmpty ? "autosave" : trimmed
    }

    private var timeOnlyFormatter: DateFormatter {
        let formatter = DateFormatter()
        formatter.timeStyle = .medium
        formatter.dateStyle = .none
        return formatter
    }

    private func scheduleAutosave(reason: String) {
        autosaveTask?.cancel()
        autosaveStatus = "Saving soon: \(reason)"
        updateAgentState()

        let sessionName = normalizedActiveSessionName()
        autosaveTask = Task {
            try? await Task.sleep(nanoseconds: 900_000_000)
            guard !Task.isCancelled else { return }
            guard await MainActor.run(body: {
                validateSessionSaveTarget(sessionName, isAutosave: true)
            }) else {
                return
            }

            do {
                let url = try await projectStore.saveNativeSession(named: sessionName)
                await MainActor.run {
                    activeSessionName = sessionName
                    lastSessionPath = url.path
                    lastSavedAt = Date()
                    autosaveStatus = "Autosaved: \(reason)"
                    lastMediaAction = autosaveStatus
                    errorMessage = nil
                    showErrorAlert = false
                    refreshRecentSessions()
                    updateAgentState()
                }
            } catch {
                await MainActor.run {
                    autosaveStatus = "Autosave failed"
                    lastMediaAction = "Autosave failed: \(error.localizedDescription)"
                    updateAgentState()
                }
            }
        }
    }

    private func validateSessionSaveTarget(_ sessionName: String, isAutosave: Bool) -> Bool {
        guard let targetEpisode = episodeNumber(in: sessionName) else {
            return true
        }

        guard let projectEpisode = currentProjectEpisodeNumber(), projectEpisode == targetEpisode else {
            let projectLabel = projectStore.activeSequence?.title ?? projectStore.project.title
            let message = "\(isAutosave ? "Autosave" : "Save") blocked: \(sessionName) does not match current project \(projectLabel)."
            autosaveStatus = isAutosave ? "Autosave blocked" : "Save blocked"
            lastMediaAction = message
            if !isAutosave {
                errorMessage = message
                showErrorAlert = true
            }
            updateAgentState()
            return false
        }

        return true
    }

    private func currentProjectEpisodeNumber() -> Int? {
        episodeNumber(in: projectStore.activeSequence?.title ?? "") ??
        episodeNumber(in: projectStore.project.title)
    }

    private func episodeNumber(in value: String) -> Int? {
        let pattern = #"episode\s*-?\s*(\d+)"#
        guard let expression = try? NSRegularExpression(pattern: pattern, options: [.caseInsensitive]) else {
            return nil
        }
        let range = NSRange(value.startIndex..<value.endIndex, in: value)
        guard let match = expression.firstMatch(in: value, range: range),
              match.numberOfRanges > 1,
              let captureRange = Range(match.range(at: 1), in: value) else {
            return nil
        }
        return Int(value[captureRange])
    }

    private func refreshRecentSessions() {
        Task {
            do {
                let sessions = try await LocalMediaVault.shared.listSessions()
                await MainActor.run {
                    recentSessions = sessions
                }
            } catch {
                await MainActor.run {
                    lastMediaAction = "Could not list sessions: \(error.localizedDescription)"
                    updateAgentState()
                }
            }
        }
    }

    private func restoreActiveSessionIfPossible() {
        guard !didAttemptInitialSessionRestore else {
            refreshRecentSessions()
            return
        }
        didAttemptInitialSessionRestore = true

        Task {
            do {
                let sessions = try await LocalMediaVault.shared.listSessions()
                let sessionName = normalizedActiveSessionName()
                let hasActiveSession = sessions.contains { $0["name"] == sessionName }

                await MainActor.run {
                    recentSessions = sessions
                    if hasActiveSession && projectStore.activeSequence == nil {
                        loadNativeSession(named: sessionName)
                    }
                }
            } catch {
                await MainActor.run {
                    lastMediaAction = "Could not restore active session: \(error.localizedDescription)"
                    updateAgentState()
                }
            }
        }
    }

    private func vaultReachableLanes() {
        guard let sequence = projectStore.activeSequence else { return }
        var skippedStorageAccessCount = 0
        let laneIds = sequence.lanes.compactMap { lane -> String? in
            guard let source = lane.sourceVideo else { return nil }
            let readiness = sourceReadiness(for: lane)
            if readiness.label == "Proxy ready" || readiness.label == "Audio ready" {
                return nil
            }
            guard shouldProbeOriginalPath(source.mediaURL.path) else {
                skippedStorageAccessCount += 1
                return nil
            }
            if externalMediaAccess.fileExistsWithoutPrompt(at: source.mediaURL) == true {
                return lane.id.uuidString
            }
            return nil
        }

        guard !laneIds.isEmpty else {
            if skippedStorageAccessCount > 0 {
                lastMediaAction = "Grant external storage access before vaulting \(skippedStorageAccessCount) original lane(s). Proxy editing is still safe."
            } else {
                lastMediaAction = "No reachable lanes to vault yet"
            }
            updateAgentState()
            return
        }

        lastMediaAction = "Vaulting \(laneIds.count) reachable lane(s)"
        updateAgentState()
        for laneId in laneIds {
            vaultLaneMedia(laneId: laneId)
        }
    }

    private func retryPendingProxyGeneration() {
        guard let sequence = projectStore.activeSequence else {
            lastMediaAction = "Retry proxies failed: no active sequence"
            updateAgentState()
            return
        }

        let lanesNeedingProxy = sequence.lanes.filter { lane in
            guard let source = lane.sourceVideo,
                  let proxyURL = source.proxyURL else {
                return false
            }
            return !(externalMediaAccess.fileExistsWithoutPrompt(at: proxyURL) ?? false)
        }

        guard !lanesNeedingProxy.isEmpty else {
            lastMediaAction = "All declared proxies are already available"
            updateAgentState()
            return
        }

        let externalBlocked = lanesNeedingProxy.filter { lane in
            guard let source = lane.sourceVideo else { return false }
            return isExternalOriginalPath(source.mediaURL.path) && !externalMediaAccess.hasExplicitFolderGrant
        }

        if !externalBlocked.isEmpty {
            for lane in externalBlocked {
                if let source = lane.sourceVideo {
                    proxyFailureByLaneId[lane.id] = "Grant external storage access before creating the local proxy for \(source.mediaURL.lastPathComponent)."
                }
            }
            lastMediaAction = "Proxy retry needs external storage access for \(externalBlocked.count) lane(s). Grant the Episode folder, then retry."
            isShowingProductionDetails = true
            updateAgentState()
            return
        }

        lastMediaAction = "Retrying \(lanesNeedingProxy.count) pending proxy job(s)"
        updateAgentState()
        for lane in lanesNeedingProxy {
            if let source = lane.sourceVideo {
                relinkLaneMedia(laneId: lane.id.uuidString, sourceURL: source.mediaURL, queueProxy: true)
            }
        }
    }

    private func rebuildPlayer(resumeAfterRebuild: Bool? = nil) {
        guard let sequence = projectStore.activeSequence else { return }

        Task { @MainActor in
            do {
                playbackEngine.updateSourcePlayers(for: sequence)
                let playerItem = try await AVCompositionBuilder().buildPlayerItem(
                    for: sequence,
                    mode: playbackEngine.playbackMode,
                    format: playbackEngine.playbackFormat,
                    allowExternalOriginalMedia: false,
                    allowedOriginalMediaRootPath: nil
                )
                let shouldResume = resumeAfterRebuild ?? playbackEngine.isPlaying
                let oldTime = playbackEngine.playhead

                playbackEngine.player = AVPlayer(playerItem: playerItem)
                playbackEngine.seek(to: oldTime)
                if shouldResume {
                    playbackEngine.play()
                } else {
                    playbackEngine.pause()
                }
                updateAgentState()
            } catch {
                self.errorMessage = "Failed to build composition: \(error.localizedDescription)"
                self.showErrorAlert = true
                print("Failed to build item: \(error)")
            }
        }
    }
}

private struct NestOutlineEntry: Identifiable {
    let id: UUID
    let documentId: UUID
    let documentTitle: String
    let kind: String
    let title: String
    let chapterSlug: String
    let chapterTitle: String
    let episodeSlug: String
    let role: String
    let authorship: String
    let reviewStatus: String
    let tags: [String]
}

private struct EpisodeMediaFolderMatchReport {
    var matches: [EpisodeMediaFolderMatch]
    var unmatchedLaneNames: [String]
    var scannedFileCount: Int
}

private struct EpisodeMediaFolderMatch {
    var laneId: UUID
    var laneName: String
    var url: URL
}

private enum EpisodeMediaFolderMatcher {
    private static let supportedExtensions: Set<String> = [
        "mp4", "mov", "m4v", "insv",
        "wav", "aif", "aiff", "mp3", "m4a", "aac", "flac"
    ]

    static func match(rootURL: URL, lanes: [VideoLane], maxDepth: Int = 6, maxFiles: Int = 25_000) -> EpisodeMediaFolderMatchReport {
        let expectations = lanes
            .map { lane in
                (lane: lane, names: expectedFilenames(for: lane))
            }
            .filter { !$0.names.isEmpty }

        var nameToLane: [String: VideoLane] = [:]
        for expectation in expectations {
            for name in expectation.names {
                nameToLane[normalized(name)] = expectation.lane
            }
        }

        var matchesByLaneId: [UUID: EpisodeMediaFolderMatch] = [:]
        var scannedFileCount = 0

        let rootComponents = rootURL.standardizedFileURL.pathComponents
        let candidates = FileManager.default.enumerator(
            at: rootURL,
            includingPropertiesForKeys: [.isRegularFileKey],
            options: [.skipsHiddenFiles, .skipsPackageDescendants]
        )

        while let url = candidates?.nextObject() as? URL {
            let standardizedURL = url.standardizedFileURL
            let depth = max(0, standardizedURL.pathComponents.count - rootComponents.count)
            if depth > maxDepth {
                candidates?.skipDescendants()
                continue
            }

            let fileExtension = standardizedURL.pathExtension.lowercased()
            guard supportedExtensions.contains(fileExtension) else { continue }
            scannedFileCount += 1
            if scannedFileCount > maxFiles { break }

            guard (try? standardizedURL.resourceValues(forKeys: [.isRegularFileKey]).isRegularFile) != false else {
                continue
            }

            let key = normalized(standardizedURL.lastPathComponent)
            guard let lane = nameToLane[key], matchesByLaneId[lane.id] == nil else { continue }

            matchesByLaneId[lane.id] = EpisodeMediaFolderMatch(
                laneId: lane.id,
                laneName: lane.name,
                url: standardizedURL
            )

            if matchesByLaneId.count == expectations.count {
                break
            }
        }

        let unmatchedLaneNames = expectations
            .map(\.lane)
            .filter { matchesByLaneId[$0.id] == nil }
            .map(\.name)

        let matches = expectations
            .compactMap { matchesByLaneId[$0.lane.id] }

        return EpisodeMediaFolderMatchReport(
            matches: matches,
            unmatchedLaneNames: unmatchedLaneNames,
            scannedFileCount: scannedFileCount
        )
    }

    private static func expectedFilenames(for lane: VideoLane) -> Set<String> {
        var names = Set<String>()

        func insertFilename(_ value: String?) {
            guard let value else { return }
            let trimmed = value.trimmingCharacters(in: .whitespacesAndNewlines)
            guard !trimmed.isEmpty else { return }
            names.insert(URL(fileURLWithPath: trimmed).lastPathComponent)
        }

        insertFilename(lane.sourceVideo?.mediaURL.lastPathComponent)
        insertFilename(lane.metadata?.sourceLabel)
        insertFilename(lane.metadata?.sourcePath)
        insertFilename(lane.metadata?.originalPath)

        if let suffix = lane.name.components(separatedBy: " - ").last, suffix != lane.name {
            insertFilename(suffix)
        }

        return names.filter { !$0.isEmpty }
    }

    private static func normalized(_ value: String) -> String {
        value
            .trimmingCharacters(in: .whitespacesAndNewlines)
            .lowercased()
    }
}

#if os(macOS)
struct PlayerView: NSViewRepresentable {
    var player: AVPlayer?
    var onScroll: ((Double) -> Void)? = nil
    var onHoverChange: ((Bool) -> Void)? = nil
    var onWindowFrameChange: ((CGRect) -> Void)? = nil

    func makeNSView(context: Context) -> ScrollScrubPlayerView {
        let view = ScrollScrubPlayerView()
        view.player = player
        view.onScroll = onScroll
        view.onHoverChange = onHoverChange
        view.onWindowFrameChange = onWindowFrameChange
        view.controlsStyle = .none // or inline, depending on needs
        view.publishWindowFrame()
        return view
    }

    func updateNSView(_ nsView: ScrollScrubPlayerView, context: Context) {
        nsView.player = player
        nsView.onScroll = onScroll
        nsView.onHoverChange = onHoverChange
        nsView.onWindowFrameChange = onWindowFrameChange
        nsView.publishWindowFrame()
    }
}

final class ScrollScrubPlayerView: AVPlayerView {
    var onScroll: ((Double) -> Void)?
    var onHoverChange: ((Bool) -> Void)?
    var onWindowFrameChange: ((CGRect) -> Void)?
    private var pointerTrackingArea: NSTrackingArea?

    override func viewDidMoveToWindow() {
        super.viewDidMoveToWindow()
        publishWindowFrame()
    }

    override func setFrameSize(_ newSize: NSSize) {
        super.setFrameSize(newSize)
        publishWindowFrame()
    }

    override func setFrameOrigin(_ newOrigin: NSPoint) {
        super.setFrameOrigin(newOrigin)
        publishWindowFrame()
    }

    override func updateTrackingAreas() {
        super.updateTrackingAreas()

        if let pointerTrackingArea {
            removeTrackingArea(pointerTrackingArea)
        }

        let options: NSTrackingArea.Options = [
            .mouseEnteredAndExited,
            .mouseMoved,
            .activeInKeyWindow,
            .inVisibleRect
        ]
        let trackingArea = NSTrackingArea(rect: bounds, options: options, owner: self, userInfo: nil)
        addTrackingArea(trackingArea)
        pointerTrackingArea = trackingArea
        publishWindowFrame()
    }

    override func mouseEntered(with event: NSEvent) {
        super.mouseEntered(with: event)
        onHoverChange?(true)
    }

    override func mouseMoved(with event: NSEvent) {
        super.mouseMoved(with: event)
        onHoverChange?(true)
        publishWindowFrame()
    }

    override func mouseExited(with event: NSEvent) {
        super.mouseExited(with: event)
        onHoverChange?(false)
    }

    override func scrollWheel(with event: NSEvent) {
        guard let onScroll else {
            super.scrollWheel(with: event)
            return
        }

        let flags = event.modifierFlags.intersection([.command, .control, .option])
        guard flags.isEmpty else {
            super.scrollWheel(with: event)
            return
        }

        let dominantDelta = abs(event.scrollingDeltaX) > abs(event.scrollingDeltaY)
            ? event.scrollingDeltaX
            : -event.scrollingDeltaY
        let sensitivity = event.hasPreciseScrollingDeltas ? 0.055 : 0.35
        let seconds = max(-12, min(12, dominantDelta * sensitivity))
        guard abs(seconds) > 0.001 else {
            super.scrollWheel(with: event)
            return
        }

        onHoverChange?(true)
        publishWindowFrame()
        onScroll(seconds)
    }

    func publishWindowFrame() {
        guard let window else { return }
        let rectInWindow = convert(bounds, to: nil)
        guard rectInWindow.isNull == false, rectInWindow.width > 0, rectInWindow.height > 0 else { return }
        // `NSEvent.locationInWindow` uses the same bottom-left window coordinate
        // space as this converted rect, so the local monitor can hit-test
        // physical wheel events without relying only on hover state.
        if window.isVisible {
            onWindowFrameChange?(rectInWindow)
        }
    }
}
#else
struct PlayerView: UIViewControllerRepresentable {
    var player: AVPlayer?
    var onScroll: ((Double) -> Void)? = nil

    func makeUIViewController(context: Context) -> AVPlayerViewController {
        let controller = AVPlayerViewController()
        controller.player = player
        controller.showsPlaybackControls = false
        return controller
    }

    func updateUIViewController(_ uiViewController: AVPlayerViewController, context: Context) {
        uiViewController.player = player
    }
}
#endif
